#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADS1115 I2C address (ADDR pin tied to GND) */
#define ADS1115_ADDR 0x48

/* ADS1115 registers */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

/* Config register bits */
#define ADS1115_CFG_OS_BEGIN 0x8000  /* Begin single conversion */
#define ADS1115_CFG_MUX_AIN0 0x4000  /* AIN0 single-ended */
#define ADS1115_CFG_PGA_4_096V 0x0200 /* ±4.096V gain */
#define ADS1115_CFG_MODE_SINGLE 0x0100 /* Single-shot mode */
#define ADS1115_CFG_DR_128SPS 0x0080  /* 128 samples per second */
#define ADS1115_CFG_CQUE_NONE 0x0003  /* Disable comparator */

/* MLX91219 parameters */
#define MLX91219_SENSITIVITY 0.040  /* 40mV/A */
#define MLX91219_ZERO_CURRENT_OFFSET 0.5  /* Mid-supply */

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a 16-bit value to an ADS1115 register (big-endian on the wire) */
static int ads1115_write_reg(uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    return i2cWriteI2CBlockData(i2c_handle, reg, buf, 3);
}

/* Read a 16-bit value from an ADS1115 register (big-endian on the wire) */
static int ads1115_read_reg(uint8_t reg, uint16_t *value) {
    char buf[2];
    int bytes = i2cReadI2CBlockData(i2c_handle, reg, buf, 2);
    if (bytes != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* Trigger a single-shot conversion and read the result */
static int ads1115_read_conversion(int16_t *raw_value) {
    uint16_t config = ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_AIN0 |
                      ADS1115_CFG_PGA_4_096V | ADS1115_CFG_MODE_SINGLE |
                      ADS1115_CFG_DR_128SPS | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(ADS1115_REG_CONFIG, config) != 0) {
        return -1;
    }

    /* Wait for conversion to complete (~8ms at 128 SPS) */
    gpioDelay(10000);

    uint16_t conv;
    if (ads1115_read_reg(ADS1115_REG_CONVERSION, &conv) != 0) {
        return -1;
    }

    /* Convert to signed 16-bit value */
    *raw_value = (int16_t)conv;
    return 0;
}

/* Convert raw ADC value to current in amperes */
static float raw_to_current(int16_t raw) {
    return (float)raw * MLX91219_SENSITIVITY - MLX91219_ZERO_CURRENT_OFFSET;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (handle=%d)\n",
                I2C_BUS, ADS1115_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler\n");
    }

    printf("MLX91219 current sensor via ADS1115 (I2C bus %d, addr 0x%02X)\n",
           I2C_BUS, ADS1115_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    while (!terminate) {
        int16_t raw;
        if (ads1115_read_conversion(&raw) != 0) {
            fprintf(stderr, "Error: Failed to read ADS1115 conversion\n");
            gpioDelay(500000);
            continue;
        }

        float current = raw_to_current(raw);
        printf("Current: %.4f A\n", current);

        gpioDelay(500000); /* 500ms */
    }

    /* Clean up */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

