#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define GPIO_CHIP "gpiochip4"
#define FAN_GPIO 18
#define SENSOR_SENSITIVITY 0.1f  /* 100 mV/A default */
#define DEFAULT_THRESHOLD 5.0f
#define LOG_FILE "current_log.txt"
#define ADC_MAX 1023
#define ADC_VREF 3.3f

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *fan_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    fan_line = gpiod_chip_get_line(chip, FAN_GPIO);
    if (!fan_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", FAN_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(fan_line, "fan_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", FAN_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        fan_line = NULL;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)(0x80 | (channel << 4)), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_current(int adc_value) {
    if (adc_value < 0 || adc_value > ADC_MAX) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0f;
    }
    return (float)adc_value * ADC_VREF / ADC_MAX * SENSOR_SENSITIVITY;
}

static void control_fan(float current) {
    int state = (current > DEFAULT_THRESHOLD) ? 1 : 0;
    if (gpiod_line_set_value(fan_line, state) < 0) {
        fprintf(stderr, "Error setting fan GPIO value: %s\n", strerror(errno));
    }
}

static void log_data(float current) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, Current: %.2f A\n", timestamp, current);
    fclose(fp);
}

static void cleanup(void) {
    if (fan_line) {
        gpiod_line_set_value(fan_line, 0);
        gpiod_line_release(fan_line);
        fan_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    float threshold = DEFAULT_THRESHOLD;
    int log_errors = 0;

    while ((opt = getopt(argc, argv, "s:t:e")) != -1) {
        switch (opt) {
            case 's':
                SENSOR_SENSITIVITY = atof(optarg);
                break;
            case 't':
                threshold = atof(optarg);
                break;
            case 'e':
                log_errors = 1;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensor_sensitivity] [-t threshold] [-e]\n", argv[0]);
                return 1;
        }
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        close(spi_fd);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            if (log_errors) {
                fprintf(stderr, "Error reading ADC value, skipping cycle.\n");
            }
            sleep(1);
            continue;
        }

        float current = adc_to_current(adc_value);
        if (current < 0) {
            if (log_errors) {
                fprintf(stderr, "Error converting ADC value to current, skipping cycle.\n");
            }
            sleep(1);
            continue;
        }

        control_fan(current);
        log_data(current);

        printf("Current: %.2f A, Fan: %s\n", current, (current > DEFAULT_THRESHOLD) ? "ON" : "OFF");

        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

