    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection to ADS1115\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t raw_value;

        // Read raw ADC value from CO sensor
        if (read_co_sensor(i2c_handle, &raw_value) != 0) {
            fprintf(stderr, "Error reading CO sensor, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
