#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define FLAME_SENSOR_GPIO 4
#define SPI_CHANNEL 0       // SPI0 CE0 (GPIO8)
#define SPI_SPEED 1000000   // 1 MHz
#define ADC_CHANNEL 0       // MCP3008 channel 0
#define LOG_FILE "flame_data.csv"
#define SAMPLE_INTERVAL_US 1000000 // 1 second

// Global variables
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flame_sensor(int gpio_pin);
int read_mcp3008(int spi_channel, int adc_channel);
float calculate_temperature(int adc_value);
int log_data(float temperature, int flame_detected);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to read the flame sensor value (0 = no flame, 1 = flame detected)
int read_flame_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to read the ADC value from MCP3008
int read_mcp3008(int spi_channel, int adc_channel) {
    if (adc_channel < 0 || adc_channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", adc_channel);
        return -1;
    }

    // MCP3008 SPI command format (3 bytes):
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel selection (0x00-0x07)
    // Byte 2: Don't care (0x00)
    unsigned char spi_tx_buf[3] = {0x01, (0x80 | (adc_channel << 4)), 0x00};
    unsigned char spi_rx_buf[3] = {0};

    int result = spiXfer(spi_channel, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate the temperature from the ADC value
float calculate_temperature(int adc_value) {
    // Linear approximation: 10-bit ADC -> 10.0-40.0°C
    // For KY-026 flame sensor, the output is high when flame is detected
    // (0 = no flame, 1 = flame detected)
    // Invert the logic to get the actual temperature
    if (adc_value == 0) {
        return 40.0f; // No flame detected
    } else {
        return 10.0f; // Flame detected
    }
}

// Function to log the data to a CSV file
int log_data(float temperature, int flame_detected) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, flame_detected);
    fclose(fp);
    return 0;
}

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Set flame sensor GPIO as input
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);

    // Open SPI channel (mode 0, active low CS)
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to clean up resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio and SPI
    if (initialize() != 0) {
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read flame sensor value
        int flame_detected = read_flame_sensor(FLAME_SENSOR_GPIO);
        if (flame_detected < 0) {
            fprintf(stderr, "Warning: Failed to read flame sensor\n");
        }

        // Read ADC value from MCP3008
        int adc_value = read_mcp3008(SPI_CHANNEL, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Warning: Failed to read ADC value\n");
        } else {
            // Calculate temperature from ADC value
            float temperature = calculate_temperature(adc_value);

            // Log the data
            if (log_data(temperature, flame_detected) != 0) {
                fprintf(stderr, "Warning: Failed to log data\n");
            }
        }

        // Wait for 1 second
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Clean up resources
    cleanup();
    printf("Flame sensor monitoring stopped.\n");

    return 0;
}

