#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49
#define MIC1_REG 0x00
#define MIC2_REG 0x00
#define SAMPLE_INTERVAL_US 100000
#define SENSITIVITY -38.0
#define REFERENCE_PRESSURE 20e-6
#define ERROR_VALUE -999.0

static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_microphone_data(int handle, int16_t *data) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, MIC1_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device (handle %d): %d\n", handle, result);
        return -1;
    }
    *data = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static double calculate_sound_pressure(int16_t raw_data) {
    double pressure = (double)raw_data * REFERENCE_PRESSURE / 32768.0;
    double db = 20.0 * log10(pressure / REFERENCE_PRESSURE);
    return db;
}

static void log_data(double pressure1, double pressure2) {
    FILE *fp = fopen("audio_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening audio_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            pressure1, pressure2);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, MIC1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for MIC1: %d\n", i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, MIC2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for MIC2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Acoustic leak detection system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int16_t raw_data1 = 0, raw_data2 = 0;
        double pressure1 = ERROR_VALUE, pressure2 = ERROR_VALUE;

        if (read_microphone_data(i2c_handle1, &raw_data1) == 0) {
            pressure1 = calculate_sound_pressure(raw_data1);
        }

        if (read_microphone_data(i2c_handle2, &raw_data2) == 0) {
            pressure2 = calculate_sound_pressure(raw_data2);
        }

        log_data(pressure1, pressure2);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

