#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0 (GPIO8)
#define SPI_SPEED 1000000   // 1 MHz
#define LED_GPIO 27         // GPIO27 for LED
#define THRESHOLD 0.7       // RMS threshold for event detection
#define SAMPLE_RATE 1000    // Samples per second
#define WINDOW_SIZE 100     // Samples per channel in a window
#define LED_ON_TIME_MS 500  // LED on time in milliseconds
#define SAMPLE_INTERVAL_US (1000000 / SAMPLE_RATE) // 1 ms in microseconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double calculate_rms(int *samples, int num_samples);
void trigger_led(int gpio, int duration_ms);
void log_data(double mic1_rms, double mic2_rms);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to read data from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format:
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | Channel selection (0x00-0x07) << 4
    // Byte 2: Don't care (0x00)
    unsigned char spi_tx_buf[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char spi_rx_buf[3] = {0};

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate RMS value from samples
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * (double)samples[i];
    }
    return sqrt(sum_of_squares / num_samples);
}

// Function to trigger the LED for a specified duration
void trigger_led(int gpio, int duration_ms) {
    gpioWrite(gpio, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay for specified duration in microseconds
    gpioWrite(gpio, 0); // Turn LED off
}

// Function to log data to a CSV file
void log_data(double mic1_rms, double mic2_rms) {
    FILE *fp = fopen("audio_events.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open audio_events.csv for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.4f,%.4f\n", timestamp, mic1_rms, mic2_rms);
    fclose(fp);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
