        for (int i = 0; i < WINDOW_SIZE; i++) {
            mic1_adc_value = read_mcp3008(0); // Read from channel 0
            mic2_adc_value = read_mcp3008(1); // Read from channel 1

            if (mic1_adc_value < 0 || mic2_adc_value < 0) {
                fprintf(stderr, "Error: Failed to read ADC values\n");
                gpioDelay(SAMPLE_INTERVAL_US);
                continue;
            }

            mic1_samples[i] = mic1_adc_value;
            mic2_samples[i] = mic2_adc_value;

            gpioDelay(SAMPLE_INTERVAL_US);
        }

        // Calculate RMS values
        mic1_rms = calculate_rms(mic1_samples, WINDOW_SIZE);
        mic2_rms = calculate_rms(mic2_samples, WINDOW_SIZE);

        // Check for threshold and trigger LED
        if (mic1_rms > THRESHOLD || mic2_rms > THRESHOLD) {
            trigger_led(LED_GPIO, LED_ON_TIME_MS);
        }

        // Log data to CSV file
        log_data(mic1_rms, mic2_rms);

        gpioDelay(SAMPLE_INTERVAL_US); // Delay for 1 ms
    }

    // Cleanup
    gpioWrite(LED_GPIO, 0); // Turn off LED
