#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG_MUX_A0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define OVERCURRENT_THRESHOLD 50.0f
#define SAMPLE_RATE_HZ 10
#define BUFFER_SIZE 100
#define LED_GPIO 17

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_pigpio(void);
int initialize_i2c(void);
int read_ads1115(int16_t *raw_value);
float convert_to_current(int16_t raw_value);
void add_to_buffer(CircularBuffer *buffer, float value);
float calculate_average(CircularBuffer *buffer);
void control_led(float average_current);
void signal_handler(int signal);
void cleanup(void);

// Initialize the circular buffer
void initialize_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Initialize pigpio library
int initialize_pigpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw value from ADS1115
int read_ads1115(int16_t *raw_value) {
    char config[3];
    char reg_config[1] = {ADS1115_REG_CONFIG};
    char reg_conversion[1] = {ADS1115_REG_CONVERSION};

    // Write config register to start conversion
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_A0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE) >> 8;
    config[2] = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_A0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write config to ADS1115\n");
        return -1;
    }

    // Wait for conversion to complete (128 SPS -> ~8ms)
    gpioDelay(10000);

    // Read conversion register
    if (i2cWriteDevice(i2c_handle, reg_conversion, 1) != 0) {
        fprintf(stderr, "Failed to set conversion register pointer\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, reg_conversion, 2) != 2) {
        fprintf(stderr, "Failed to read conversion register\n");
        return -1;
    }

    *raw_value = (int16_t)((reg_conversion[0] << 8) | reg_conversion[1]);
    return 0;
}

// Convert raw ADC value to current (assuming 5V supply)
float convert_to_current(int16_t raw_value) {
    // MLX91204: 0.5V to 4.5V for 0-100A, PGA = 4.096V
    // Assuming 5V supply, 1 bit = 0.000125V
    // 125uV per A
    return (float)raw_value * 0.000125f;
}

// Add value to circular buffer
void add_to_buffer(CircularBuffer *buffer, float value) {
    buffer->buffer[buffer->head] = value;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Calculate average of all values in circular buffer
float calculate_average(CircularBuffer *buffer) {
    if (buffer->count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->buffer[i];
    }
    return sum / buffer->count;
}

// Control LED based on average current
void control_led(float average_current) {
    if (average_current > OVERCURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Cleanup resources
void cleanup(void) {
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main(void) {
    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    // Initialize circular buffer
    CircularBuffer current_buffer;
    initialize_buffer(&current_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Starting current monitoring...\n");

    // Main loop
    while (program_running) {
        int16_t raw_value;
        if (read_ads1115(&raw_value) == 0) {
            float current = convert_to_current(raw_value);
            add_to_buffer(&current_buffer, current);
            float average_current = calculate_average(&current_buffer);
            control_led(average_current);
            printf("Current: %.2f A, Average: %.2f A\n", current, average_current);
        } else {
            fprintf(stderr, "Failed to read current from sensor\n");
        }
        gpioDelay(1000000 / SAMPLE_RATE_HZ); // Delay for 100ms (10Hz)
    }

    // Cleanup
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

