#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TCS34725_ADDR        0x29
#define TCS34725_ENABLE      0x00
#define TCS34725_ATIME       0x01
#define TCS34725_CONTROL     0x0F
#define TCS34725_ID          0x12
#define TCS34725_CDATA       0x14
#define TCS34725_RDATA       0x16
#define TCS34725_GDATA       0x18
#define TCS34725_BDATA       0x1A

#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02
#define TCS34725_ENABLE_PONAEN 0x03

#define I2C_BUS             1
#define LOG_FILE            "color_log.csv"
#define SAMPLE_INTERVAL_US  1000000  /* 1 second */
#define MAX_CONSEC_ERRORS   3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int tcs34725_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n",
                reg, value, rc);
    }
    return rc;
}

static int tcs34725_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int tcs34725_init(int handle)
{
    uint8_t id = 0;

    if (tcs34725_read_reg(handle, TCS34725_ID, &id) < 0) {
        return -1;
    }
    if ((id & 0xF0) != 0x40) {
        fprintf(stderr, "TCS34725 ID mismatch: got 0x%02X, expected 0x44\n", id);
        return -1;
    }

    if (tcs34725_write_reg(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) {
        return -1;
    }
    gpioDelay(3000);  /* 3 ms power-on settle */

    if (tcs34725_write_reg(handle, TCS34725_ATIME, 0xFF) < 0) {
        return -1;
    }
    if (tcs34725_write_reg(handle, TCS34725_CONTROL, 0x01) < 0) {
        return -1;
    }
    if (tcs34725_write_reg(handle, TCS34725_ENABLE, TCS34725_ENABLE_PONAEN) < 0) {
        return -1;
    }

    return 0;
}

static int tcs34725_read_color(int handle, uint16_t *clear, uint16_t *red,
                              uint16_t *green, uint16_t *blue)
{
    uint8_t c, r, g, b;

    if (tcs34725_read_reg(handle, TCS34725_CDATA, &c) < 0) return -1;
    if (tcs34725_read_reg(handle, TCS34725_RDATA, &r) < 0) return -1;
    if (tcs34725_read_reg(handle, TCS34725_GDATA, &g) < 0) return -1;
    if (tcs34725_read_reg(handle, TCS34725_BDATA, &b) < 0) return -1;

    *clear = (uint16_t)((c << 8) | r);
    *red   = (uint16_t)((r << 8) | g);
    *green = (uint16_t)((g << 8) | b);
    *blue  = (uint16_t)((b << 8) | c);
    return 0;
}

static int log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green,
                    uint16_t blue)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
