#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define CURRENT_THRESHOLD 10.0f
#define MOTOR_SHUTDOWN_PIN 17
#define SAMPLE_INTERVAL_SEC 1
#define MAX_SPI_RETRIES 3

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_shutdown_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_spi(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_mcp3008(int spi_fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_SPI_RETRIES, strerror(errno));
        if (attempt < MAX_SPI_RETRIES - 1) {
            usleep(10000);
        }
    }

    return -1;
}

static float adc_to_current(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        return -1.0f;
    }
    float voltage = (float)adc_value * 3.3f / 1024.0f;
    return (voltage - 0.05f) / 0.1f;
}

static void log_current(float current) {
