    if (motor_shutdown_line) {
        if (gpiod_line_set_value(motor_shutdown_line, 1) < 0) {
            fprintf(stderr, "Error re-enabling motor: %s\n", strerror(errno));
        }
    }
}

static void cleanup(void) {
    if (motor_shutdown_line) {
        gpiod_line_set_value(motor_shutdown_line, 1);
        gpiod_line_release(motor_shutdown_line);
        motor_shutdown_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        return 1;
    }

    motor_shutdown_line = gpiod_chip_get_line(chip, MOTOR_SHUTDOWN_PIN);
    if (!motor_shutdown_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", MOTOR_SHUTDOWN_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(motor_shutdown_line, "motor_shutdown", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", MOTOR_SHUTDOWN_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    int spi_fd = init_spi();
    if (spi_fd < 0) {
        cleanup();
        return 1;
    }

    log_file = fopen("current_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(spi_fd);
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Current_in_Amperes\n");
        fflush(log_file);
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value after %d retries.\n", MAX_SPI_RETRIES);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float current = adc_to_current(adc_value);
        if (current < 0.0f) {
            fprintf(stderr, "Invalid current reading: %.3f A\n", current);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        log_current(current);

        if (current > CURRENT_THRESHOLD) {
            printf("Overcurrent detected! Current: %.3f A\n", current);
            motor_shutdown();
            sleep(1);
            motor_reenable();
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

