#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_MUX_AIN1_GND 0x5000
#define ADS1115_CONFIG_PGA_2_048V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_CONFIG_DEFAULT 0xC083

#define LED_GPIO 17
#define PRESSURE_THRESHOLD 105.0f
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

// Global variables
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(void);
int init_ads1115(void);
int read_ads1115(int16_t *raw_pressure, int16_t *raw_temperature);
float convert_pressure(int16_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
void control_led(float pressure);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

// Initialize I2C communication
int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize ADS1115 ADC
int init_ads1115(void) {
    // Write config register to start single-shot conversion
    uint16_t config = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND | ADS1115_CONFIG_PGA_2_048V |
                      ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;
    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    int result = i2cWriteDevice(i2c_handle, config_buf, 3);
    if (result < 0) {
        fprintf(stderr, "Error writing to ADS1115 config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read raw ADC values from ADS1115
int read_ads1115(int16_t *raw_pressure, int16_t *raw_temperature) {
    char reg = ADS1115_REG_CONVERSION;
    char data[2];

    // Write register pointer
    int result = i2cWriteDevice(i2c_handle, &reg, 1);
    if (result < 0) {
        fprintf(stderr, "Error setting ADS1115 register pointer: %d\n", result);
        return -1;
    }

    // Read 2 bytes of conversion data
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from ADS1115: %d\n", result);
        return -1;
    }

    // Combine bytes (big-endian)
    *raw_pressure = (int16_t)((data[0] << 8) | data[1]);

    // AIN1 is the NTC temperature sensor
    *raw_temperature = *raw_pressure;

    return 0;
}

// Convert raw ADC value to pressure (kPa)
float convert_pressure(int16_t raw_pressure) {
    // Linear transfer function: 0V = 0 kPa, 5V = 400 kPa
    float voltage = (float)raw_pressure * 0.000125f;
    return voltage * 400.0f;
}

// Convert raw ADC value to temperature (°C)
float convert_temperature(int16_t raw_temperature) {
    // Simplified linear NTC approximation: 1V = 0°C, 2V = 100°C
    float voltage = (float)raw_temperature * 0.000125f;
    return (voltage - 1.0f) * 100.0f;
}

// Control LED based on pressure threshold
void control_led(float pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize ADS1115
    if (init_ads1115() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("MLX90834 Pressure Sensor Interface\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t raw_pressure = 0, raw_temperature = 0;
        bool read_success = false;

        // Retry loop for I2C read
        for (int i = 0; i < MAX_RETRIES; i++) {
            if (read_ads1115(&raw_pressure, &raw_temperature) == 0) {
                read_success = true;
                break;
            }
            fprintf(stderr, "I2C read failed, retrying (%d/%d)...\n", i + 1, MAX_RETRIES);
            gpioDelay(10000); // 10ms delay before retry
        }

        if (!read_success) {
            fprintf(stderr, "Failed to read sensor after %d retries. Skipping sample.\n", MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        // Convert raw values to physical units
        float pressure = convert_pressure(raw_pressure);
        float temperature = convert_temperature(raw_temperature);

        // Display data
        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        // Control LED
        control_led(pressure);

        // Wait for next sample
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

