#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* Configuration */
#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */
#define MCP3008_CHANNEL  0          /* MLX91209 on MCP3008 CH0 */
#define ADC_MAX          1023       /* 10-bit ADC */
#define VREF             3.3        /* Reference voltage */
#define SENSITIVITY      0.0066     /* 66 mV/A (MLX91209 typical) */
#define CURRENT_THRESHOLD 10.0       /* Amps */
#define SHUTDOWN_PIN     27         /* GPIO27 for motor shutdown */
#define SAMPLE_PERIOD_US 100000     /* 100 ms */
#define LOG_FILE         "current_log.txt"

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int  read_mcp3008(int channel);
static float adc_to_voltage(int adc_value);
static float voltage_to_current(float voltage);
static void log_current(float current);
static void log_error(const char *message);
static void signal_handler(int signal);
static void cleanup(void);

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on error.
 */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_error("Invalid MCP3008 channel requested");
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   Byte 2: 0x00  (clock out remaining bits)
     * Response:
     *   rx[0] = ignored
     *   rx[1] = bits 9..2 in upper nibble, bits 1..0 in lower nibble
     *   rx[2] = bits 7..0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result != 3) {
        log_error("SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* Convert ADC value to voltage (0-3.3V, 1024 steps) */
static float adc_to_voltage(int adc_value) {
    return ((float)adc_value / (float)ADC_MAX) * VREF;
}

/* Convert voltage to current (Vcc/2 at zero current, sensitivity) */
static float voltage_to_current(float voltage) {
    return (voltage - (VREF / 2.0f)) / SENSITIVITY;
}

/* Append a timestamped current reading to the log file */
static void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        log_error("Failed to get local time");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Current: %.2f A\n", timestamp, current) < 0) {
        log_error("Failed to write to log file");
    }
    fflush(log_file);
}

/* Append a timestamped error message to the log file */
static void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stderr, "%s, ERROR: %s (errno: %d - %s)\n",
            timestamp, message, errno, strerror(errno));

    if (log_file != NULL) {
        fprintf(log_file, "%s, ERROR: %s (errno: %d - %s)\n",
                timestamp, message, errno, strerror(errno));
        fflush(log_file);
    }
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Reset motor shutdown pin to LOW */
    gpioWrite(SHUTDOWN_PIN, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d, speed %d)\n",
                SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure shutdown pin as output and ensure it starts LOW */
    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) != 0) {
        log_error("Failed to set shutdown pin mode");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(SHUTDOWN_PIN, 0);

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_error("Failed to register SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("Failed to register SIGTERM handler");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            log_error("Failed to read ADC value");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float current = voltage_to_current(voltage);

        log_current(current);

        /* Safety monitor: if current exceeds threshold, shutdown motor */
        if (current > CURRENT_THRESHOLD) {
            printf("Current threshold exceeded! Current: %.2f A\n", current);
            log_error("Current threshold exceeded!");
            gpioWrite(SHUTDOWN_PIN, 1);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

