#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0 (GPIO8)
#define SPI_SPEED 1000000   // 1 MHz
#define MCP3208_CHANNEL 0   // MCP3208 channel for humidity (single-ended)
#define MCP3208_CHANNEL_T 1 // MCP3208 channel for thermistor (single-ended)
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"
#define EMAIL_SENDER "sender@example.com"
#define EMAIL_SMTP_SERVER "smtp.example.com"
#define EMAIL_SMTP_PORT 587
#define EMAIL_SMTP_USERNAME "username"
#define EMAIL_SMTP_PASSWORD ""

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3208(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
void log_data(float humidity, float temperature);
void send_email_alert(float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read data from MCP3208 ADC via SPI
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3208 channel: %d\n", channel);
        return -1;
    }

    // MCP3208 SPI command format (3 bytes):
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel (0x00-0x07) << 4
    // Byte 2: Don't care (0x00)
    unsigned char spi_tx_buf[3] = {0x01, (unsigned char)((0x80 | channel) << 4), 0x00};
    unsigned char spi_rx_buf[3] = {0};

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 12-bit ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate relative humidity from ADC value
float calculate_humidity(int adc_value) {
    // HIH-4602-A transfer function: Vout = 0.824 + 0.0315 * RH
    // Assuming 5.0V supply
    float voltage = (float)adc_value * 5.0 / 1023.0;
    float humidity = (voltage - 0.824) / 0.0315;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

// Function to calculate temperature from ADC value
float calculate_temperature(int adc_value) {
    // Thermistor transfer function: Vout = Beta * (10k/R0) * (1 - e^(-Beta/T))
    // Assuming Beta = 3950K, R0 = 10kΩ, T = 25°C
    float voltage = (float)adc_value * 5.0 / 1023.0;
    float resistance = 10000.0 * (5.0 - voltage) / voltage;
    if (resistance <= 0.0) return -999.0; // Invalid resistance
    float temperature = 1.0 / (log(resistance / 10000.0) / 3950.0 + 1.0 / 298.15);
    return temperature;
}

// Function to log data to file
void log_data(float humidity, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fclose(fp);
}

// Function to send email alert
void send_email_alert(float humidity) {
    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Humidity Alert\\n\\nHumidity exceeds threshold: %.2f%%\" | ssmtp %s",
             humidity, EMAIL_RECIPIENT);
    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error: Could not execute ssmtp command\n");
    } else if (result != 0) {
        fprintf(stderr, "Error: ssmtp command returned non-zero exit code: %d\n", result);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read humidity ADC value
        int adc_humidity = read_mcp3208(MCP3208_CHANNEL);
        if (adc_humidity < 0) {
            fprintf(stderr, "Error: Failed to read humidity ADC value\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Read temperature ADC value
        int adc_temperature = read_mcp3208(MCP3208_CHANNEL_T);
        if (adc_temperature < 0) {
            fprintf(stderr, "Error: Failed to read temperature ADC value\n");
            gpioDelay(1000000);
            continue;
        }

        // Calculate humidity and temperature
        float humidity = calculate_humidity(adc_humidity);
        float temperature = calculate_temperature(adc_temperature);

        // Log data
        log_data(humidity, temperature);

        // Send email alert if humidity exceeds threshold
        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity);
        }

        // Wait 1 second
        gpioDelay(1000000);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

