#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0 (GPIO8)
#define SPI_SPEED 1000000   // 1 MHz
#define SPI_FLAGS 0         // SPI Mode 0
#define CS_PIN 8            // GPIO8 for CS control
#define ADC_CHANNELS 3      // ADXL335 X/Y/Z channels
#define ADC_RESOLUTION 1024 // 10-bit ADC
#define VREF 3.3            // Reference voltage
#define SENSITIVITY 0.0300  // ADXL335 sensitivity in mV/g
#define IMPACT_THRESHOLD 2.0 // Impact threshold in g
#define SAMPLE_RATE 100     // Hz
#define LOG_FILE "impact_log.txt"

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double adc_to_g(int adc_value);
void log_data(int adc_x, int adc_y, int adc_z, double impact_magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format:
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel (0x00-0x07) << 4
    // Byte 2: Don't care (0x00)
    unsigned char tx_buffer[3] = {0x01, (unsigned char)((0x80 | channel) << 4), 0x00};
    unsigned char rx_buffer[3] = {0};

    // Assert CS
    gpioWrite(CS_PIN, 0);

    // Perform SPI transfer
    int result = spiXfer(spi_handle, (char *)tx_buffer, (char *)rx_buffer, 3);

    // Deassert CS
    gpioWrite(CS_PIN, 1);

    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to acceleration in g
double adc_to_g(int adc_value) {
    if (adc_value < 0 || adc_value > ADC_RESOLUTION) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1.0;
    }

    // Convert ADC value to voltage
    double voltage = (adc_value / (double)ADC_RESOLUTION) * VREF;

    // Convert voltage to acceleration in g
    double acceleration = (voltage - 1.65) / SENSITIVITY;

    return acceleration;
}

// Function to log data to file
void log_data(int adc_x, int adc_y, int adc_z, double impact_magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.3f\n", timestamp, adc_x, adc_y, adc_z, impact_magnitude);
    fflush(log_file); // Ensure data is written to file immediately

    if (impact_magnitude > IMPACT_THRESHOLD) {
        fprintf(log_file, "%s,IMPACT DETECTED\n", timestamp);
        fflush(log_file);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output and ensure it's high (inactive)
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_values[ADC_CHANNELS];
        double impact_magnitudes[ADC_CHANNELS];
        int error_flag = 0;

        // Read ADC values from all channels
        for (int i = 0; i < ADC_CHANNELS; i++) {
            adc_values[i] = read_mcp3008(i);
            if (adc_values[i] < 0) {
                fprintf(stderr, "Error: Failed to read ADC channel %d\n", i);
                error_flag = 1;
                break;
            }
        }

        // Convert ADC values to acceleration in g
        if (!error_flag) {
            for (int i = 0; i < ADC_CHANNELS; i++) {
                impact_magnitudes[i] = adc_to_g(adc_values[i]);
                if (impact_magnitudes[i] < 0) {
                    fprintf(stderr, "Error: Failed to convert ADC value %d to g\n", adc_values[i]);
                    error_flag = 1;
                    break;
                }
            }
        }

        // Log data if no errors
        if (!error_flag) {
            log_data(adc_values[0], adc_values[1], adc_values[2], impact_magnitudes[0]);
        }

        // Delay for 100 Hz sampling rate
        gpioDelay(1000000 / SAMPLE_RATE);
    }

    // Cleanup
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

