/*
 * Si1172-A30-GMR Optical Heart Rate Sensor Reader for Raspberry Pi Zero W
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   Si1172 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   Si1172 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   Si1172 VDD -> 3.3 V
 *   Si1172 GND -> GND
 *
 * Build: gcc -Wall -o si1172_hr si1172_hr.c -lpigpio -lrt
 * Run:   sudo ./si1172_hr
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1172 I2C address (7-bit) ---- */
#define SI1172_ADDR 0x49

/* ---- Si1172 register addresses ---- */
#define SI1172_REG_PART_ID      0x00
#define SI1172_REG_HW_KEY       0x07
#define SI1172_REG_MEAS_RATE0   0x08
#define SI1172_REG_MEAS_RATE1   0x09
#define SI1172_REG_FIFO_WR      0x0A
#define SI1172_REG_FIFO_RD      0x0B
#define SI1172_REG_FIFO_DATA    0x0C
#define SI1172_REG_COMMAND      0xC0
#define SI1172_REG_RESPONSE     0xC1
#define SI1172_REG_IRQ_ENABLE   0xC2
#define SI1172_REG_IRQ_MODE1   0xC3
#define SI1172_REG_IRQ_MODE2   0xC4
#define SI1172_REG_HW_KEY_VAL   0x17

/* ---- Command codes ---- */
#define SI1172_CMD_RESET        0x01
#define SI1172_CMD_PS_FORCE     0x05
#define SI1172_CMD_ALS_FORCE    0x06
#define SI1172_CMD_PSALS_FORCE  0x07

/* ---- Error codes ---- */
#define SI1172_ERROR_OK         0
#define SI1172_ERROR_I2C        1
#define SI1172_ERROR_SENSOR     2

/* ---- Globals for signal handler ---- */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ---- Function prototypes ---- */
static int  si1172_write_reg(uint8_t reg, uint8_t value);
static int  si1172_read_reg(uint8_t reg, uint8_t *value);
static int  si1172_read_block(uint8_t reg, uint8_t *buf, uint32_t len);
static int  si1172_init(void);
static int  si1172_read_data(uint16_t *ir, uint16_t *red);
static int  log_data(uint16_t ir, uint16_t red, int hr, int spo2, int error_code);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------------------------------------------ */
/* Write a single byte to a Si1172 register.                            */
/* ------------------------------------------------------------------ */
static int si1172_write_reg(uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    int rc = i2cWriteDevice(i2c_handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return SI1172_ERROR_I2C;
    }
    return SI1172_ERROR_OK;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a Si1172 register.                           */
/* ------------------------------------------------------------------ */
static int si1172_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cWriteByte(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(reg=0x%02X) failed: %d\n", reg, rc);
        return SI1172_ERROR_I2C;
    }
    rc = i2cReadByte(i2c_handle);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByte(reg=0x%02X) failed: %d\n", reg, rc);
        return SI1172_ERROR_I2C;
    }
    *value = (uint8_t)rc;
    return SI1172_ERROR_OK;
}

/* ------------------------------------------------------------------ */
/* Read a block of bytes from a Si1172 register.                        */
/* ------------------------------------------------------------------ */
static int si1172_read_block(uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cWriteByte(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(reg=0x%02X) failed: %d\n", reg, rc);
        return SI1172_ERROR_I2C;
    }
    rc = i2cReadDevice(i2c_handle, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X, len=%u) failed: %d\n",
                reg, len, rc);
        return SI1172_ERROR_I2C;
    }
    return SI1172_ERROR_OK;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1172 sensor.                                       */
/* ------------------------------------------------------------------ */
static int si1172_init(void)
{
    uint8_t part_id = 0;

    /* Verify sensor presence by reading PART_ID */
    if (si1172_read_reg(SI1172_REG_PART_ID, &part_id) != SI1172_ERROR_OK) {
        fprintf(stderr, "[ERROR] Cannot read PART_ID — sensor absent or bus error.\n");
        return SI1172_ERROR_SENSOR;
    }
    printf("[INFO] Si1172 PART_ID = 0x%02X\n", part_id);

    /* Reset the sensor */
    if (si1172_write_reg(SI1172_REG_COMMAND, SI1172_CMD_RESET) != SI1172_ERROR_OK) {
        fprintf(stderr, "[ERROR] Failed to reset Si1172.\n");
        return SI1172_ERROR_SENSOR;
    }
    gpioDelay(10000); /* 10 ms reset delay */

    /* Write HW_KEY to enable command-based register access */
    if (si1172_write_reg(SI1172_REG_HW_KEY, SI1172_REG_HW_KEY_VAL) != SI1172_ERROR_OK) {
        fprintf(stderr, "[ERROR] Failed to write HW_KEY.\n");
        return SI1172_ERROR_SENSOR;
    }

    /* Configure measurement rate: 1 measurement per second */
    if (si1172_write_reg(SI1172_REG_MEAS_RATE0, 0x01) != SI1172_ERROR_OK) {
        fprintf(stderr, "[ERROR] Failed to set MEAS_RATE0.\n");
        return SI1172_ERROR_SENSOR;
    }
    if (si1172_write_reg(SI1172_REG_MEAS_RATE1, 0x00) != SI1172_ERROR_OK) {
        fprintf(stderr, "[ERROR] Failed to set MEAS_RATE1.\n");
        return SI1172_ERROR_SENSOR;
    }

    /* Enable PSALS interrupt */
    if (si1172_write_reg(SI1172_REG_IRQ_ENABLE, 0x01) != SI1172_ERROR_OK) {
        fprintf(stderr, "[ERROR] Failed to enable IRQ_ENABLE.\n");
        return SI1172_ERROR_SENSOR;
    }

    /* Set IRQ_MODE1: PSALS interrupt on every measurement */
    if (si1172_write_reg(SI1172_REG_IRQ_MODE1, 0x01) != SI1172_ERROR_OK) {
        fprintf(stderr, "[ERROR] Failed to set IRQ_MODE1.\n");
        return SI1172_ERROR_SENSOR;
    }

    /* Set IRQ_MODE2: PSALS interrupt on every measurement */
    if (si1172_write_reg(SI1172_REG_IRQ_MODE2, 0x01) != SI1172_ERROR_OK) {
        fprintf(stderr, "[ERROR] Failed to set IRQ_MODE2.\n");
        return SI1172_ERROR_SENSOR;
    }

    printf("[INFO] Si1172 initialized successfully.\n");
    return SI1172_ERROR_OK;
}

/* ------------------------------------------------------------------ */
/* Read raw IR and RED ADC values from the FIFO.                        */
/* ------------------------------------------------------------------ */
static int si1172_read_data(uint16_t *ir, uint16_t *red)
{
    uint8_t data[6];

    /* Trigger a measurement by writing PSALS_FORCE command */
    if (si1172_write_reg(SI1172_REG_COMMAND, SI1172_CMD_PSALS_FORCE) != SI1172_ERROR_OK) {
        fprintf(stderr, "[ERROR] Failed to trigger measurement.\n");
        return SI1172_ERROR_I2C;
    }

    /* Wait for measurement to complete (FIFO_RD register is updated) */
    gpioDelay(10000); /* 10 ms */

    /* Read 6 bytes of FIFO data: 2 IR samples, 2 RED samples, 2 padding */
    if (si1172_read_block(SI1172_REG_FIFO_DATA, data, 6) != SI1172_ERROR_OK) {
        fprintf(stderr, "[ERROR] Failed to read FIFO data.\n");
        return SI1172_ERROR_I2C;
    }

    /* Combine the two 16-bit samples (little-endian) */
    *ir  = (uint16_t)((data[1] << 8) | data[0]);
    *red = (uint16_t)((data[3] << 8) | data[2]);

    return SI1172_ERROR_OK;
}

/* ------------------------------------------------------------------ */
/* Log data to the CSV file.                                          */
/* ------------------------------------------------------------------ */
static int log_data(uint16_t ir, uint16_t red, int hr, int spo2, int error_code)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%u,%u,%d,%d,%d\n",
            timestamp, ir, red, hr, spo2, error_code);
    fflush(log_file);

    return SI1172_ERROR_OK;
}

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C).                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources.                                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t ir = 0, red = 0;
    int hr = 0, spo2 = 0;
    int error_code = SI1172_ERROR_OK;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1172 address */
    i2c_handle = i2cOpen(1, SI1172_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                SI1172_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the Si1172 sensor */
    if (si1172_init() != SI1172_ERROR_OK) {
        fprintf(stderr, "[FATAL] Si1172 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    log_file = fopen("biometric_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open biometric_log.csv for writing.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write the CSV header if the file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,ir_raw,red_raw,hr_bpm,spo2_percent,error_code\n");
        fflush(log_file);
    }

    /* Register the signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] Failed to register SIGINT handler.\n");
    }

    printf("[INFO] Logging data to biometric_log.csv. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        error_code = SI1172_ERROR_OK;

        /* Read raw data */
        if (si1172_read_data(&ir, &red) != SI1172_ERROR_OK) {
            error_code = SI1172_ERROR_I2C;
        }

        /* Convert raw data to HR and SpO2 (placeholder: replace with actual algorithm) */
        hr = (int)(ir * 0.1);
        spo2 = (int)(red * 0.1);

        /* Log the data */
        if (log_data(ir, red, hr, spo2, error_code) != SI1172_ERROR_OK) {
            fprintf(stderr, "[ERROR] Failed to log data.\n");
        }

        /* Sleep for 1 second */
        gpioDelay(1000000); /* 1 second */
    }

    printf("\n[INFO] Shutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

