#define NUM_CHANNELS 2
#define ADC_RESOLUTION 1024 // 10-bit ADC
#define SAMPLE_RATE 1000    // 1 kHz sampling rate
#define BUFFER_SIZE (SAMPLE_RATE / 10) // 100 samples per second

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int process_audio(int channel1, int channel2);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read data from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format:
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | Channel selection (0x00-0x07) << 4
    // Byte 2: Don't care (0x00)
    unsigned char spi_tx_buf[3] = {0x01, (0x80 | (channel << 4)), 0x00};
    unsigned char spi_rx_buf[3] = {0};

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract the 10-bit ADC value from the response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to process the audio data
int process_audio(int channel1, int channel2) {
    // Simple noise cancellation: subtract the two channels
    int audio_data = channel1 - channel2;
    return audio_data;
}

int main(int argc, char *argv[]) {
    // Parse the gain value from the command line
    int gain = 1;
    if (argc > 1) {
        gain = atoi(argv[1]);
        if (gain <= 0) {
            fprintf(stderr, "Error: Gain value must be a positive integer.\n");
            return 1;
        }
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0 CE0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read audio data from both channels
        int channel1_data = read_mcp3008(0);
        int channel2_data = read_mcp3008(1);

        // Check for SPI errors
        if (channel1_data < 0 || channel2_data < 0) {
            fprintf(stderr, "Error: Failed to read audio data from MCP3008\n");
            break;
        }

        // Process the audio data
        int audio_data = process_audio(channel1_data, channel2_data);

        // Apply gain control
        audio_data *= gain;

        // Print the audio data to the terminal
        printf("%d,%d,%d\n", channel1_data, channel2_data, audio_data);
        fflush(stdout);

        // Delay for a short period
        gpioDelay(10000); // 10 ms
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

