#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define BUZZER_PIN 18
#define ADC_CHANNEL 0
#define FLAME_THRESHOLD 1.0f
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_MS 500
#define LOG_FILE "flame_log.txt"
#define AMBIENT_TEMP_FILE "ambient_temp.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *buzzer_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ambient_temperature(float *temp) {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening ambient temperature file: %s\n", strerror(errno));
        return -1;
    }
    if (fscanf(fp, "%f", temp) != 1) {
        fprintf(stderr, "Error reading ambient temperature from file\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int read_mcp3008(int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float calculate_compensated_voltage(int adc_value, float ambient_temp) {
    float voltage = (float)adc_value * 3.3f / 1023.0f;
    return voltage + (ambient_temp - 25.0f) * 0.001f;
}

static void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%d,%.3f,%.3f,%.2f,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file);
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", BUZZER_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "flame_buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", BUZZER_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    float ambient_temp = 25.0f;
    if (read_ambient_temperature(&ambient_temp) < 0) {
        fprintf(stderr, "Using default ambient temperature: %.2f\n", ambient_temp);
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && adc_value < 0) {
            if (read_mcp3008(ADC_CHANNEL, &adc_value) == 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                usleep(10000);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries. Skipping iteration.\n", MAX_RETRIES);
            log_data(-1, -1.0f, -1.0f, ambient_temp, 0);
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        if (adc_value > 1023) {
            fprintf(stderr, "ADC value out of range: %d. Skipping iteration.\n", adc_value);
            log_data(adc_value, -1.0f, -1.0f, ambient_temp, 0);
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        float voltage = (float)adc_value * 3.3f / 1023.0f;
        float compensated_voltage = calculate_compensated_voltage(adc_value, ambient_temp);
        int flame_detected = (compensated_voltage > FLAME_THRESHOLD) ? 1 : 0;

        log_data(adc_value, voltage, compensated_voltage, ambient_temp, flame_detected);

        if (flame_detected) {
            gpiod_line_set_value(buzzer_line, 1);
            printf("Flame detected! Buzzer ON\n");
        } else {
            gpiod_line_set_value(buzzer_line, 0);
            printf("No flame detected. Buzzer OFF\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

