#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define LED_GPIO       17
#define WATER_LEVEL_THRESHOLD_HIGH 75
#define WATER_LEVEL_THRESHOLD_LOW   70
#define SAMPLE_INTERVAL_SEC 5
#define SPI_READ_DELAY_US 100000   /* 100 ms between SPI reads */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_json_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended channel from the MCP3008.                       */
/* Returns 0-1023 on success, -1 on SPI transfer error.                */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                         (start bit)
     *   tx[1] = 0x80 | (channel << 4)        (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                         (padding for clocking data out)
     * Result: ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)(0x80 | (channel << 4)), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value to percentage of 0-1023 range.                    */
/* ------------------------------------------------------------------ */
static float adc_to_percentage(int adc_value)
{
    return (float)adc_value / 1023.0f * 100.0f;
}

/* ------------------------------------------------------------------ */
/* Append a JSON object to the log file.                               */
/* ------------------------------------------------------------------ */
static void log_water_level(float water_level)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_json_file, "{\"timestamp\":\"%s.%03ld\",\"water_level\":%.2f}\n",
            timestamp, ts.tv_nsec / 1000000, water_level);
    fflush(g_json_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_json_file != NULL) {
        fflush(g_json_file);
        fclose(g_json_file);
        g_json_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO as output */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, speed %d, flags %d)\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open JSON file for appending (append mode) */
    g_json_file = fopen("water_levels.json", "a");
    if (g_json_file == NULL) {
        fprintf(stderr, "Error: cannot open water_levels.json for appending\n");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write opening JSON array if file is empty */
    fseek(g_json_file, 0, SEEK_END);
    long file_size = ftell(g_json_file);
    if (file_size == 0) {
        fprintf(g_json_file, "[\n");
        fflush(g_json_file);
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    int led_state = 0;

    while (g_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Warning: ADC read failed, skipping sample\n");
            gpioDelay(SPI_READ_DELAY_US);
            continue;
        }

        float water_level = adc_to_percentage(adc_value);

        printf("Water level: %.2f%% (ADC: %d)\n", water_level, adc_value);

        log_water_level(water_level);

        /* Hysteresis control */
        if (water_level > WATER_LEVEL_THRESHOLD_HIGH && led_state == 0) {
            gpioWrite(LED_GPIO, 1);
            led_state = 1;
            printf("LED ON (water level %.2f%% > %.1f%%)\n",
                   water_level, WATER_LEVEL_THRESHOLD_HIGH);
        } else if (water_level < WATER_LEVEL_THRESHOLD_LOW && led_state == 1) {
            gpioWrite(LED_GPIO, 0);
            led_state = 0;
            printf("LED OFF (water level %.2f%% < %.1f%%)\n",
                   water_level, WATER_LEVEL_THRESHOLD_LOW);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

