        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to flow rate in LPM
float convert_to_lpm(int adc_value) {
    // AWM7300V: 0-3.3V output, 1000 LPM = 3.3V / 1000 = 0.033V/LPM
    // Assuming 10-bit ADC resolution (0-1023)
    // Flow rate = (adc_value * 3.3V) / 1023
    float voltage = (adc_value * 3.3f) / 1023.0f;
    float flow_rate = voltage / 0.033f;
    return flow_rate;
}

// Log data to CSV file
int log_data(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file\n");
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    // Write CSV header if file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        if (fprintf(log_file, "Timestamp,FlowRate (LPM)\n") < 0) {
            fprintf(stderr, "Error: Failed to write CSV header\n");
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(log_file);
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float flow_rate = convert_to_lpm(adc_value);

        if (log_data(flow_rate) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

