#define MAX_RAW 700
#define MOISTURE_THRESHOLD 30
#define LOGGING_INTERVAL 60
#define EMAIL_RECIPIENT "recipient@example.com"
#define MSMTP_CONFIG_FILE "/etc/msmtprc"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config, don't care */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float calculate_moisture_percentage(int raw_value) {
    if (raw_value < MIN_RAW) raw_value = MIN_RAW;
    if (raw_value > MAX_RAW) raw_value = MAX_RAW;
    return 100.0f - ((float)(raw_value - MIN_RAW) / (float)(MAX_RAW - MIN_RAW)) * 100.0f;
}

static int log_data(float moisture_percentage) {
    FILE *fp = fopen("plant_data.txt", "a");
    if (!fp) {
        perror("Error opening plant_data.txt");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage) < 0) {
