    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Plant Moisture Alert\\n\\nPlant moisture level: %.2f%%\" | msmtp %s",
             moisture_percentage, EMAIL_RECIPIENT);

    FILE *fp = popen(command, "r");
    if (!fp) {
        perror("Error executing msmtp");
        return -1;
    }

    int status = pclose(fp);
    if (status == -1) {
        perror("pclose failed");
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "msmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int spi_channel = SPI_CHANNEL;
    int adc_channel = ADC_CHANNEL;
    int min_raw = MIN_RAW;
    int max_raw = MAX_RAW;
    int moisture_threshold = MOISTURE_THRESHOLD;
    int logging_interval = LOGGING_INTERVAL;
    char *recipient_email = EMAIL_RECIPIENT;
    char *msmtp_config_file = MSMTP_CONFIG_FILE;

    if (argc > 1) spi_channel = atoi(argv[1]);
    if (argc > 2) adc_channel = atoi(argv[2]);
    if (argc > 3) min_raw = atoi(argv[3]);
    if (argc > 4) max_raw = atoi(argv[4]);
    if (argc > 5) moisture_threshold = atoi(argv[5]);
    if (argc > 6) logging_interval = atoi(argv[6]);
    if (argc > 7) recipient_email = argv[7];
    if (argc > 8) msmtp_config_file = argv[8];

    if (spi_channel < 0 || spi_channel > 7) {
        fprintf(stderr, "Invalid SPI channel %d\n", spi_channel);
        return 1;
    }
    if (adc_channel < 0 || adc_channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", adc_channel);
        return 1;
    }
    if (min_raw < 0 || min_raw > 1023) {
        fprintf(stderr, "Invalid min_raw %d\n", min_raw);
        return 1;
    }
    if (max_raw < 0 || max_raw > 1023) {
        fprintf(stderr, "Invalid max_raw %d\n", max_raw);
        return 1;
    }
    if (moisture_threshold < 0 || moisture_threshold > 100) {
        fprintf(stderr, "Invalid moisture_threshold %d\n", moisture_threshold);
        return 1;
    }
    if (logging_interval <= 0) {
        fprintf(stderr, "Invalid logging_interval %d\n", logging_interval);
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(spi_channel, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d): %d\n",
                spi_channel, SPI_SPEED, spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Plant moisture monitoring started. Logging every %d seconds.\n", logging_interval);
    printf("SPI channel: %d, ADC channel: %d, Min raw: %d, Max raw: %d, Moisture threshold: %d%%\n",
           spi_channel, adc_channel, min_raw, max_raw, moisture_threshold);
    printf("Email recipient: %s, msmtp config: %s\n", recipient_email, msmtp_config_file);

    while (running) {
        int raw_value = read_mcp3008(adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in %d seconds...\n", logging_interval);
            sleep(logging_interval);
            continue;
        }

        float moisture_percentage = calculate_moisture_percentage(raw_value);

        if (log_data(moisture_percentage) != 0) {
            fprintf(stderr, "Error logging data, retrying in %d seconds...\n", logging_interval);
        }

        if (moisture_percentage < moisture_threshold) {
            if (send_email_alert(moisture_percentage) != 0) {
                fprintf(stderr, "Error sending email alert, retrying in %d seconds...\n", logging_interval);
            }
        }

        sleep(logging_interval);
    }

    printf("\nShutting down gracefully...\n");

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return 0;
}

