#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0       // SPI0 CE0 (GPIO8)
#define SPI_SPEED 1000000   // 1 MHz
#define ADC_CHANNEL 0       // MCP3008 channel connected to the sensor
#define VREF 3.3            // Reference voltage
#define MIN_PRESSURE 0.1    // Minimum pressure in kPa
#define MAX_PRESSURE 1.5    // Maximum pressure in kPa
#define MIN_VOLTAGE 0.5     // Minimum voltage in V
#define MAX_VOLTAGE 4.5     // Maximum voltage in V
#define ADC_MAX 1023        // 10-bit ADC maximum
#define SAMPLE_INTERVAL 1   // Sample interval in seconds

// Global variables
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float voltage_to_pressure(float voltage);
void log_data(float pressure);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read data from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format:
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel (0x00-0x07) << 4
    // Byte 2: Don't care (0x00)
    unsigned char spi_tx_buf[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char spi_rx_buf[3] = {0};

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from the response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert voltage to pressure in kPa
float voltage_to_pressure(float voltage) {
    if (voltage < MIN_VOLTAGE || voltage > MAX_VOLTAGE) {
        fprintf(stderr, "Error: Voltage out of range: %.3fV\n", voltage);
        return -1.0;
    }

    float pressure = MIN_PRESSURE + (voltage - MIN_VOLTAGE) * (MAX_PRESSURE - MIN_PRESSURE) / (MAX_VOLTAGE - MIN_VOLTAGE);
    return pressure;
}

// Function to log data to the console
void log_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("%s, Pressure: %.2f kPa\n", timestamp, pressure);
    fflush(stdout);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Pressure sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Convert ADC value to voltage
        float voltage = (float)adc_value / ADC_MAX * VREF;

        // Convert voltage to pressure
        float pressure = voltage_to_pressure(voltage);

        // Log the data
        log_data(pressure);

        // Wait for the next sample interval
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("Pressure sensor monitoring stopped.\n");
    return 0;
}

