#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 300
#define MOISTURE_THRESHOLD_HIGH 600
#define SAMPLE_INTERVAL_SEC 5
#define BUFFER_SIZE 20

#define VH400_ADC_CHANNEL 0

typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write GPIO %d\n", PUMP_GPIO);
    }
}

static void log_data(int moisture_level, int pump_state) {
    time(&log_buffer[buffer_index].timestamp);
    log_buffer[buffer_index].moisture_level = moisture_level;
    log_buffer[buffer_index].pump_state = pump_state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void print_log_buffer(void) {
    printf("\n--- Log Buffer (%d entries) ---\n", buffer_count);
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        struct tm *tm_info = localtime(&log_buffer[idx].timestamp);
        char time_str[64];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("[%s] Moisture: %d, Pump: %s\n",
               time_str, log_buffer[idx].moisture_level,
               log_buffer[idx].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log Buffer ---\n\n");
}

static void timer_callback(void *user_data) {
    (void)user_data;

    int moisture_level = read_mcp3008(VH400_ADC_CHANNEL);
    if (moisture_level < 0) {
        fprintf(stderr, "Warning: Failed to read moisture level, skipping sample\n");
        return;
    }

    int pump_state = (moisture_level < MOISTURE_THRESHOLD_LOW) ? 1 : 0;
    control_pump(pump_state);

    log_data(moisture_level, pump_state);
    print_log_buffer();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", PUMP_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_pump(0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_SEC, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set timer function\n");
        control_pump(0);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitoring System started. Press Ctrl+C to exit.\n");

    while (running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

