#define REG_SPO2_CONFIG 0x08
#define REG_LED1_PA 0x09
#define REG_LED2_PA 0x0A
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x15
#define RESET_CMD 0x40
#define SPO2_MODE 0x03
#define SPO2_CONFIG_100HZ 0x27
#define LED_PA_4096 0x24

#define HEART_RATE_MIN 60
#define HEART_RATE_MAX 120
#define SPO2_THRESHOLD 95
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_reg16(uint8_t reg, uint16_t *value) {
    int rc = i2cReadWordData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint16_t)rc;
    return 0;
}

static int init_max30102(void) {
    uint8_t part_id;
    if (read_reg(REG_PART_ID, &part_id) < 0) {
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X). Sensor not present?\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    if (write_reg(REG_MODE_CONFIG, RESET_CMD) < 0) {
        return -1;
    }
    gpioDelay(10000);

    if (write_reg(REG_INTR_ENABLE_1, 0x00) < 0) {
        return -1;
    }
    if (write_reg(REG_FIFO_WR_PTR, 0x00) < 0) {
        return -1;
    }
    if (write_reg(REG_OVF_COUNTER, 0x00) < 0) {
        return -1;
    }
    if (write_reg(REG_FIFO_RD_PTR, 0x00) < 0) {
        return -1;
    }
    if (write_reg(REG_FIFO_CONFIG, 0x4F) < 0) {
        return -1;
    }
    if (write_reg(REG_MODE_CONFIG, SPO2_MODE) < 0) {
        return -1;
    }
    if (write_reg(REG_SPO2_CONFIG, SPO2_CONFIG_100HZ) < 0) {
        return -1;
    }
    if (write_reg(REG_LED1_PA, LED_PA_4096) < 0) {
        return -1;
    }
    if (write_reg(REG_LED2_PA, LED_PA_4096) < 0) {
        return -1;
    }

    return 0;
}

static int read_fifo_data(uint32_t *red, uint32_t *ir) {
    uint8_t data[6];
    int rc = i2cReadI2CBlockData(i2c_handle, REG_FIFO_DATA, (char *)data, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading FIFO data: %d\n", rc);
        return -1;
    }
    *red = ((uint32_t)data[0] << 16) | ((uint32_t)data[1] << 8) | data[2];
    *ir = ((uint32_t)data[3] << 16) | ((uint32_t)data[4] << 8) | data[5];
    return 0;
}

static int calculate_spo2(uint32_t red, uint32_t ir, int *spo2) {
    if (red == 0 || ir == 0) {
        return -1;
    }

    float ratio_red = (float)red / (float)ir;
    float ratio_ir = (float)ir / (float)red;

    float spo2_red = 100.0f - (20.0f * ratio_red);
    float spo2_ir = 100.0f - (20.0f * ratio_ir);

    if (spo2_red < 0.0f) spo2_red = 0.0f;
    if (spo2_red > 100.0f) spo2_red = 100.0f;
    if (spo2_ir < 0.0f) spo2_ir = 0.0f;
    if (spo2_ir > 100.0f) spo2_ir = 100.0f;

    float avg_spo2 = (spo2_red + spo2_ir) / 2.0f;
    *spo2 = (int)avg_spo2;
    return 0;
}

static int detect_heart_rate(uint32_t *ir_data, int num_samples, int *heart_rate) {
    if (num_samples < 2) {
        return -1;
    }

    int peaks = 0;
    for (int i = 1; i < num_samples - 1; i++) {
        if (ir_data[i] > ir_data[i - 1] && ir_data[i] > ir_data[i + 1]) {
            peaks++;
        }
    }

    if (peaks < 5) {
        return -1;
    }

    float time_diff_sum = 0.0f;
    for (int i = 1; i < num_samples - 1; i++) {
        if (ir_data[i] > ir_data[i - 1] && ir_data[i] > ir_data[i + 1]) {
            time_diff_sum += (float)(ir_data[i + 1] - ir_data[i - 1]) / 1000000.0f;
        }
    }

    float time_diff_avg = time_diff_sum / (float)peaks;
    if (time_diff_avg <= 0.0f) {
        return -1;
    }

    *heart_rate = (int)(60.0f / time_diff_avg);
    return 0;
}

static void log_data(int spo2, int heart_rate) {
    FILE *fp = fopen("health_log.txt", "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, SpO2: %d%%, Heart Rate: %d BPM\n", timestamp, spo2, heart_rate);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, MAX30102_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_max30102() < 0) {
        fprintf(stderr, "MAX30102 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint32_t ir_data[100];
    int ir_index = 0;
    int ir_count = 0;

    while (!terminate) {
        uint32_t red, ir;
        if (read_fifo_data(&red, &ir) < 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        ir_data[ir_index] = ir;
        ir_index = (ir_index + 1) % 100;
        if (ir_count < 100) {
            ir_count++;
        }

        int spo2;
        if (calculate_spo2(red, ir, &spo2) < 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int heart_rate;
        if (detect_heart_rate(ir_data, ir_count, &heart_rate) < 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (spo2 < SPO2_THRESHOLD || heart_rate > HEART_RATE_MAX) {
            log_data(spo2, heart_rate);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

