#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CONFIG 0x01

#define GPIO_CHIP      "gpiochip4"
#define RELAY_LINE     17
#define DOOR_REED_LINE 27

#define LOG_FILE       "/var/log/door_events.log"
#define SAMPLE_COUNT   10
#define SAMPLE_DELAY_MS 50
#define POLL_DELAY_MS   200
#define RELAY_ON_MS    3000
#define THRESHOLD_PCT   80

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *reed_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char ts_str[32];
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", ts_str, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (i2c_write_reg16(i2c_fd, ADS1115_REG_CONFIG, 0xC383) < 0) {
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }
    relay_line = gpiod_chip_get_line(chip, RELAY_LINE);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line %d: %s\n", RELAY_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(relay_line, "door_lock", 0) < 0) {
        fprintf(stderr, "Failed to request relay line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        relay_line = NULL;
        return -1;
    }
    reed_line = gpiod_chip_get_line(chip, DOOR_REED_LINE);
    if (!reed_line) {
        fprintf(stderr, "Failed to get reed line %d: %s\n", DOOR_REED_LINE, strerror(errno));
        gpiod_line_release(relay_line);
        relay_line = NULL;
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_input_flags(reed_line, "door_reed", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request reed line as input: %s\n", strerror(errno));
        gpiod_line_release(relay_line);
        relay_line = NULL;
        gpiod_line_release(reed_line);
        reed_line = NULL;
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    return 0;
}

static int read_ads1115(int16_t *raw) {
    uint16_t config;
    if (i2c_read_reg16(i2c_fd, ADS1115_REG_CONFIG, &config) < 0) {
        return -1;
    }
    config |= 0x8000;
    if (i2c_write_reg16(i2c_fd, ADS1115_REG_CONFIG, config) < 0) {
        return -1;
    }
    usleep(10000);
    uint16_t conv;
    if (i2c_read_reg16(i2c_fd, ADS1115_REG_CONV, &conv) < 0) {
        return -1;
    }
    *raw = (int16_t)conv;
    return 0;
}

static int calibrate_threshold(void) {
    int sum = 0;
    for (int i = 0; i < SAMPLE_COUNT; i++) {
        int16_t raw;
        if (read_ads1115(&raw) < 0) {
            log_event("Sensor read failed during calibration");
            return -1;
        }
        sum += raw;
        usleep(SAMPLE_DELAY_MS * 1000);
    }
    int avg = sum / SAMPLE_COUNT;
    int threshold = (avg * THRESHOLD_PCT) / 100;
    printf("Calibration: threshold = %d\n", threshold);
    return threshold;
}

static void release_door(void) {
    printf("Releasing door lock...\n");
    if (gpiod_line_set_value(relay_line, 1) < 0) {
        fprintf(stderr, "Failed to energize relay: %s\n", strerror(errno));
        log_event("Failed to energize relay");
        return;
    }
    usleep(RELAY_ON_MS * 1000);
    if (gpiod_line_set_value(relay_line, 0) < 0) {
        fprintf(stderr, "Failed to de-energize relay: %s\n", strerror(errno));
        log_event("Failed to de-energize relay");
    } else {
        log_event("Door lock released");
    }
}

static void check_door_open(void) {
    int val = gpiod_line_get_value(reed_line);
    if (val < 0) {
        fprintf(stderr, "Failed to read reed sensor: %s\n", strerror(errno));
        log_event("Failed to read reed sensor");
        return;
    }
    if (val == 0) {
        printf("Door opened!\n");
        log_event("Door opened");
    } else {
        printf("Door closed.\n");
        log_event("Door not opened");
    }
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (reed_line) {
        gpiod_line_release(reed_line);
        reed_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() < 0) {
        return 1;
    }
    if (init_gpio() < 0) {
        close(i2c_fd);
        return 1;
    }

    int threshold = calibrate_threshold();
    if (threshold < 0) {
        cleanup();
        return 1;
    }

    printf("Door lock system started. Threshold = %d\n", threshold);
    log_event("Door lock system started");

    while (running) {
        int16_t raw;
        if (read_ads1115(&raw) < 0) {
            log_event("Sensor read failed");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }
        if (raw < threshold) {
            release_door();
        }
        check_door_open();
        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    log_event("Door lock system shutting down");
    cleanup();
    return 0;
}

