#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CONFIG 0x01

#define GPIO_SHUTDOWN  27
#define BUFFER_SIZE    10
#define THRESHOLD_GAUSS 500.0f

#define SS49E_ZERO_FIELD_V 2.5f
#define SS49E_SENSITIVITY_MV_PER_GAUSS 1.4f
#define SS49E_VCC 3.3f

#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static CircularBuffer field_buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float buffer_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / cb->count;
}

static int read_ads1115(int handle, int16_t *raw) {
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = 0xC3;  /* MUX=AIN0 single-ended, PGA=4.096V, single-shot, 128 SPS */
    config[2] = 0x83;  /* Mode=continuous, DR=128 SPS, COMP_MODE=disabled */

    if (i2cWriteDevice(handle, config, 3) != 0) {
        syslog(LOG_ERR, "I2C write failed");
        return -1;
    }

    gpioDelay(10000);  /* 10 ms conversion time */

    char reg = ADS1115_REG_CONV;
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        syslog(LOG_ERR, "I2C write reg select failed");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        syslog(LOG_ERR, "I2C read failed");
        return -1;
    }

    *raw = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

static float raw_to_gauss(int16_t raw) {
    float voltage = (raw * SS49E_VCC) / 32767.0f;
    return (voltage - SS49E_ZERO_FIELD_V) / SS49E_SENSITIVITY_MV_PER_GAUSS;
}

static void control_motor(bool shutdown) {
    if (gpioWrite(GPIO_SHUTDOWN, shutdown ? 1 : 0) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO%d", GPIO_SHUTDOWN);
    }
}

int main(void) {
    openlog("hall_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d addr 0x%02X: %d", I2C_BUS, ADS1115_ADDR, i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", GPIO_SHUTDOWN);
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    control_motor(false);

    buffer_init(&field_buffer);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Hall monitor started");

    while (running) {
        int16_t raw;
        if (read_ads1115(i2c_handle, &raw) != 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float gauss = raw_to_gauss(raw);

