    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error setting SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting SIGTERM handler");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Watering system started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = read_mcp3008(ADC_CHANNEL);
        if (moisture_level < 0) {
            fprintf(stderr, "Error reading moisture level. Skipping cycle.\n");
        } else {
            printf("Moisture Level: %d\n", moisture_level);

            if (moisture_level < MOISTURE_THRESHOLD) {
                printf("Watering cycle started...\n");
                control_pump(1);

                for (int i = 0; i < PUMP_DURATION_SEC && running; i++) {
                    sleep(1);
                }

                control_pump(0);
                printf("Watering cycle complete.\n");

                log_event(moisture_level);
            }
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Watering system stopped.\n");

    return EXIT_SUCCESS;
}

