#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define RELAY_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30.0
#define MOISTURE_THRESHOLD_HIGH 35.0
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "soil_moisture"
#define MQTT_CLIENT_ID "soil_moisture_monitor"
#define MQTT_COMMAND_TOPIC "pump_control"
#define SAMPLE_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static MQTTClient client;
static MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
static MQTTClient_message pubmsg = MQTTClient_message_initializer;
static MQTTClient_deliveryToken token;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel %d", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        syslog(LOG_ERR, "SPI transfer failed (returned %d)", ret);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
        return -1.0;
    }
    float voltage = (float)adc_value * 3.3 / 1023.0;
    float resistance = 10000.0 * (3.3 - voltage) / voltage;
    if (resistance <= 0.0) {
        syslog(LOG_ERR, "Sensor absent or wiring fault");
        return -1.0;
    }
    float moisture = 100.0 - (resistance / 10000.0) * 100.0;
    if (moisture < 0.0) moisture = 0.0;
    if (moisture > 100.0) moisture = 100.0;
    return moisture;
}

static void control_pump(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write relay GPIO %d", RELAY_GPIO);
    }
}

static void on_connect(void *context, MQTTClient_connectionStatus *status) {
    (void)context;
    if (status->connected) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        int rc = MQTTClient_subscribe(client, MQTT_COMMAND_TOPIC, 0);
        if (rc != MQTTCLIENT_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to command topic: %s", MQTTClient_strerror(rc));
        }
    } else {
        syslog(LOG_ERR, "Disconnected from MQTT broker: %s", status->cause);
    }
}

static void on_message(void *context, char *topicName, int topicLen, MQTTClient_message *message) {
    (void)context;
    (void)topicLen;
    char *payload = (char *)message->payload;
    if (message->payloadlen > 0) {
        syslog(LOG_INFO, "Received command: %s", payload);
        if (strcmp(payload, "pump_on") == 0) {
            control_pump(1);
            MQTTClient_publishMessage(client, MQTT_COMMAND_TOPIC, "pump_on", 6, NULL, 0, 0, NULL);
        } else if (strcmp(payload, "pump_off") == 0) {
            control_pump(0);
            MQTTClient_publishMessage(client, MQTT_COMMAND_TOPIC, "pump_off", 7, NULL, 0, 0, NULL);
        }
    }
    MQTTClient_freeMessage(&message);
    MQTTClient_free(topicName);
}

static void on_delivery(void *context, MQTTClient_deliveryToken token) {
    (void)context;
    (void)token;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %s", pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set relay GPIO %d as output", RELAY_GPIO);
        return -1;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialize relay GPIO %d to LOW", RELAY_GPIO);
        return -1;
    }
    return 0;
}

static int init_mqtt(void) {
    int rc = MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to create MQTT client: %s", MQTTClient_strerror(rc));
        return -1;
    }
    conn_opts.keepAliveInterval = 60;
    conn_opts.cleansession = 1;
    conn_opts.onConnect = on_connect;
    conn_opts.onMessage = on_message;
    conn_opts.onDelivery = on_delivery;
    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        client = NULL;
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (client != NULL) {
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        client = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
