    syslog(LOG_INFO, "Starting soil moisture monitoring");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (init_spi() != 0) {
