        if (moisture < 0.0) {
            syslog(LOG_ERR, "Failed to calculate moisture");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        syslog(LOG_INFO, "Moisture: %.2f%% (ADC: %d)", moisture, adc_value);

        if (moisture < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
            control_pump(1);
            pump_state = 1;
            syslog(LOG_INFO, "Pump turned ON");
        } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
