            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (noise_level > NOISE_THRESHOLD) {
            int motor1_speed = (noise_level * PWM_RANGE) / NOISE_THRESHOLD;
            int motor2_speed = (noise_level * PWM_RANGE) / NOISE_THRESHOLD;

