    printf("[%s] Moisture: %.2f%%\n", timestamp, moisture);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

