    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && adc_value < 0) {
            adc_value = read_mcp3008(0);
            if (adc_value < 0) {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "Read failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);
                    time_sleep(0.1);
                }
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read moisture after %d retries. Skipping cycle.\n", MAX_RETRIES);
        } else {
            float moisture = adc_to_moisture(adc_value);
            if (moisture >= 0.0f) {
                control_pump(moisture);
                log_data(moisture);
            } else {
                fprintf(stderr, "Invalid moisture reading: %.2f\n", moisture);
            }
        }

        time_sleep(LOG_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    gpioWrite(PUMP_GPIO, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

