#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_DEVICE "/dev/spidev0.0"
#define CONFIG_FILE "theremin_config.txt"
#define PWM_PERIOD_NS 1000000000L
#define PWM_RANGE 1000
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 1000
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define MIN_FREQUENCY 220.0
#define MAX_FREQUENCY 880.0
#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023
#define TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trig_line = NULL;
static struct gpiod_line *echo_line = NULL;
static struct gpiod_line *pwm_line = NULL;
static int spi_fd = -1;
static int pwm_fd = -1;
static int config_loaded = 0;
static float frequency_min = MIN_FREQUENCY;
static float frequency_max = MAX_FREQUENCY;
static int pwm_range = PWM_RANGE;
static int pwm_duty_min = PWM_DUTY_MIN;
static int pwm_duty_max = PWM_DUTY_MAX;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }
    unsigned int speed = 1000000;
    unsigned char mode = SPI_MODE_0;
    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    return 0;
}

static int pwm_init(void) {
    pwm_fd = open("/sys/class/pwm/pwmchip0/export", O_WRONLY);
    if (pwm_fd < 0) {
        perror("Failed to export PWM");
        return -1;
    }
    char buf[4];
    snprintf(buf, sizeof(buf), "%d", 0);
    if (write(pwm_fd, buf, strlen(buf)) < 0) {
        perror("Failed to set PWM channel");
        close(pwm_fd);
        pwm_fd = -1;
        return -1;
    }
    usleep(100000);
    snprintf(buf, sizeof(buf), "/sys/class/pwm/pwmchip0/pwm0/period");
    pwm_period_ns = (long)read_file(buf);
    if (pwm_period_ns <= 0) {
        fprintf(stderr, "Failed to read PWM period\n");
        close(pwm_fd);
        pwm_fd = -1;
        return -1;
    }
    snprintf(buf, sizeof(buf), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    if (write(pwm_fd, buf, strlen(buf)) < 0) {
        perror("Failed to set PWM duty cycle path");
        close(pwm_fd);
        pwm_fd = -1;
        return -1;
    }
    snprintf(buf, sizeof(buf), "/sys/class/pwm/pwmchip0/pwm0/enable");
    pwm_line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!pwm_line) {
        perror("Failed to get PWM line");
        close(pwm_fd);
        pwm_fd = -1;
        return -1;
    }
    if (gpiod_line_request_output(pwm_line, "theremin", 0) < 0) {
        perror("Failed to request PWM line as output");
        close(pwm_fd);
        pwm_fd = -1;
        return -1;
    }
    return 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_frequency(int distance) {
    if (distance < 0) return 0.0;
    float freq = frequency_min + (distance / 100.0) * (frequency_max - frequency_min);
    if (freq < MIN_FREQUENCY) freq = MIN_FREQUENCY;
    if (freq > MAX_FREQUENCY) freq = MAX_FREQUENCY;
    return freq;
}

static int set_pwm_duty(int duty) {
    if (duty < PWM_DUTY_MIN) duty = PWM_DUTY_MIN;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;
    long on_ns = (long)duty * pwm_period_ns / pwm_range;
    long off_ns = pwm_period_ns - on_ns;
    char buf[64];
    snprintf(buf, sizeof(buf), "%ld", on_ns);
    if (write(pwm_fd, buf, strlen(buf)) < 0) {
        perror("Failed to set PWM duty cycle");
        return -1;
    }
    snprintf(buf, sizeof(buf), "%ld", off_ns);
    if (write(pwm_fd, buf, strlen(buf)) < 0) {
        perror("Failed to set PWM duty cycle");
        return -1;
    }
    return 0;
}

static int read_distance(void) {
    struct timespec start, end;
    long elapsed_us;
    int timeout = 0;

    if (gpiod_line_set_value(trig_line, 0) < 0) {
        perror("Failed to set trigger low");
        return -1;
    }
    usleep(2);
    if (gpiod_line_set_value(trig_line, 1) < 0) {
        perror("Failed to set trigger high");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig_line, 0) < 0) {
        perror("Failed to set trigger low");
        return -1;
    }

    while (gpiod_line_get_value(echo_line) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
            perror("clock_gettime start failed");
            return -1;
        }
        timeout++;
        if (timeout > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            return -1;
        }
        usleep(1);
    }
    timeout = 0;
    while (gpiod_line_get_value(echo_line) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
            perror("clock_gettime end failed");
            return -1;
        }
        timeout++;
        if (timeout > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1;
        }
        usleep(1);
    }
    elapsed_us = (end.tv_sec - start.tv_sec) * 1000000L + (end.tv_nsec - start.tv_nsec) / 1000L;
    float distance = (float)elapsed_us * 0.0343 / 2.0;
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1;
    }
    return (int)distance;
}

static int save_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (!fp) {
        perror("Failed to open config file");
        return -1;
    }
    fprintf(fp, "frequency_min=%.2f\n", frequency_min);
    fprintf(fp, "frequency_max=%.2f\n", frequency_max);
    fprintf(fp, "pwm_range=%d\n", pwm_range);
    fprintf(fp, "pwm_duty_min=%d\n", pwm_duty_min);
    fprintf(fp, "pwm_duty_max=%d\n", pwm_duty_max);
    fclose(fp);
    return 0;
}

static int load_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        perror("Failed to open config file");
        return -1;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");
        if (!key || !value) continue;
        if (strcmp(key, "frequency_min") == 0) {
            frequency_min = atof(value);
        } else if (strcmp(key, "frequency_max") == 0) {
            frequency_max = atof(value);
        } else if (strcmp(key, "pwm_range") == 0) {
            pwm_range = atoi(value);
        } else if (strcmp(key, "pwm_duty_min") == 0) {
            pwm_duty_min = atoi(value);
        } else if (strcmp(key, "pwm_duty_max") == 0) {
            pwm_duty_max = atoi(value);
        }
    }
    fclose(fp);
    config_loaded = 1;
    return 0;
}

static long read_file(const char *path) {
    FILE *fp = fopen(path, "r");
    if (!fp) return -1;
    long val;
    if (fscanf(fp, "%ld", &val) != 1) val = -1;
    fclose(fp);
    return val;
}

static void cleanup(void) {
    if (pwm_line) {
        gpiod_line_set_value(pwm_line, 0);
        gpiod_line_release(pwm_line);
        pwm_line = NULL;
    }
    if (trig_line) {
        gpiod_line_release(trig_line);
        trig_line = NULL;
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
        echo_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (pwm_fd >= 0) {
        close(pwm_fd);
        pwm_fd = -1;
    }
    if (config_loaded) save_config();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig_line || !echo_line) {
        perror("Failed to get GPIO lines");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(trig_line, "theremin", 0) < 0 ||
        gpiod_line_request_input(echo_line, "theremin") < 0) {
        perror("Failed to request GPIO lines");
        cleanup();
        return 1;
    }

    if (spi_init() < 0) {
        cleanup();
        return 1;
    }
    if (pwm_init() < 0) {
        cleanup();
        return 1;
    }

    if (load_config() < 0) {
        fprintf(stderr, "Failed to load config, using defaults\n");
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Sensor read error, using last valid state\n");
        } else {
            float freq = calculate_frequency(distance);
            int duty = (int)(((float)freq - frequency_min) / (frequency_max - frequency_min)) * pwm_range;
            if (set_pwm_duty(duty) < 0) {
                fprintf(stderr, "PWM set error\n");
            }
        }
        usleep(100000);
    }

    cleanup();
    printf("Theremin stopped.\n");
    return 0;
}

