#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_FLAGS 0       // Mode 0, active-low CS
#define MQ135_CHANNEL 0
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 1000
#define SAMPLE_INTERVAL_S 5

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int calculate_aqi(int adc_value);
void control_fan(int aqi);
void log_data(int aqi);
void signal_handler(int signal);
int initialize_spi();
void cleanup();

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message for MCP3008
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode + channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate AQI from ADC value
int calculate_aqi(int adc_value) {
    // Linear mapping: 0-500 AQI for 0-1023 ADC
    return (int)(((float)adc_value / 1023.0) * 500.0);
}

// Function to control the ventilation fan
void control_fan(int aqi) {
    if (aqi > AQI_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
    }
}

// Function to log data to a file
void log_data(int aqi) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, AQI: %d\n", timestamp, aqi);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialization failed (handle %d)\n", spi_handle);
        return -1;
    }
    return 0;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Air quality monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = -1;
        int retries = 0;

        // Retry loop for SPI read
        while (retries < MAX_RETRIES && adc_value < 0) {
            adc_value = read_mcp3008(MQ135_CHANNEL);
            if (adc_value < 0) {
                fprintf(stderr, "Error: SPI read failed, retrying (%d/%d)...\n", retries + 1, MAX_RETRIES);
                retries++;
                if (retries < MAX_RETRIES) {
                    gpioDelay(RETRY_DELAY_MS * 1000); // Wait before retrying
                }
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC after %d retries. Re-initializing SPI...\n", MAX_RETRIES);
            spiClose(spi_handle);
            spi_handle = -1;
            if (initialize_spi() != 0) {
                fprintf(stderr, "Error: SPI re-initialization failed. Exiting.\n");
                break;
            }
            continue; // Skip this sample and retry next cycle
        }

        // Calculate AQI
        int aqi = calculate_aqi(adc_value);

        // Control fan
        control_fan(aqi);

        // Log data
        log_data(aqi);

        // Wait for 5 seconds
        gpioDelay(SAMPLE_INTERVAL_S * 1000000);
    }

    // Cleanup
    cleanup();

    return 0;
}

