#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define MCP3008_CHANNEL 0
#define LOG_FILE "alcohol_log.txt"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int mcp3008_read(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((channel << 4) | 0x80), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_ppm(int adc_value) {
    return (adc_value * 0.5f) - 10.0f;
}

static void log_data(float ppm, const char *status) {
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(log_fp, "%s, PPM: %.2f, Status: %s\n", timestamp, ppm, status);
    fflush(log_fp);
}

static void cleanup(void) {
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, 8);
    if (!cs_line) {
        fprintf(stderr, "Error getting GPIO line 8: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008_cs", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line 8 as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Alcohol sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && running) {
            if (gpiod_line_set_value(cs_line, 0) < 0) {
                fprintf(stderr, "Error asserting CS: %s\n", strerror(errno));
                retries++;
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            }

            adc_value = mcp3008_read(MCP3008_CHANNEL);

            if (gpiod_line_set_value(cs_line, 1) < 0) {
                fprintf(stderr, "Error deasserting CS: %s\n", strerror(errno));
                retries++;
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            }

            if (adc_value < 0) {
                retries++;
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            }

            if (adc_value == 0 || adc_value == 1023) {
                fprintf(stderr, "Warning: ADC reading at extreme (%d) - sensor absent or wiring fault\n", adc_value);
            }

            break;
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries. Skipping sample.\n", MAX_RETRIES);
            log_data(-1.0f, "Sensor read error");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float ppm = adc_to_ppm(adc_value);
        const char *status;

        if (ppm > 50.0f) {
            status = "Alcohol detected! Limit exceeded.";
        } else if (ppm < 20.0f) {
            status = "Sobriety confirmed.";
        } else {
            status = "Alcohol level within acceptable range.";
        }

        log_data(ppm, status);
        printf("PPM: %.2f, Status: %s\n", ppm, status);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

