    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set pump GPIO as output and ensure it is off initially
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int moisture_level = read_mcp3008(0); // Read moisture level from channel 0

        if (moisture_level >= 0) {
            // Check if moisture level is below threshold
            if (moisture_level < MOISTURE_THRESHOLD) {
                control_pump(1); // Activate pump
                log_data(moisture_level, 1); // Log pump activation
            } else {
                control_pump(0); // Deactivate pump
                log_data(moisture_level, 0); // Log pump deactivation
            }
        } else {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            log_data(-1, -1); // Log error
        }

        // Wait for the specified interval
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup (should not reach here normally due to signal handler)
    control_pump(0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

