#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>

// Motor 1 GPIOs
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2 GPIOs
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Potentiometer ADC Channels
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// Motor Speed Limits
#define MIN_SPEED 50
#define MAX_SPEED 255

// Global variables for cleanup
static int spi_handle = -1;
static volatile int running = 1;

// Function prototypes
int read_potentiometer(int channel);
int map_potentiometer_to_speed(int pot_value);
void set_motor_speed(int motor_enable, int motor_direction, int speed);
void move_motors(int motor1_speed, int motor2_speed);
void motion_profile(int motor1_speed, int motor2_speed);
void cleanup();
void signal_handler(int signal);

// Function to read the value from the MCP3008 ADC
int read_potentiometer(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format: Start bit (1), Single-ended mode (1), Channel select (3 bits), Don't care (1 bit)
    unsigned char tx_buffer[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx_buffer[3] = {0};

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract the 10-bit ADC value from the response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to map the potentiometer value to a motor speed factor
int map_potentiometer_to_speed(int pot_value) {
    if (pot_value < 0) pot_value = 0;
    if (pot_value > 1023) pot_value = 1023;

    // Logarithmic mapping: 0-1023 -> 50-255
    float log_value = log10f((float)pot_value + 1.0f);
    float speed_factor = MIN_SPEED + (log_value - log10f(1024.0f)) * (MAX_SPEED - MIN_SPEED);

    if (speed_factor < MIN_SPEED) speed_factor = MIN_SPEED;
    if (speed_factor > MAX_SPEED) speed_factor = MAX_SPEED;

    return (int)speed_factor;
}

// Function to set the motor speed and direction
void set_motor_speed(int motor_enable, int motor_direction, int speed) {
    if (speed < 0) speed = 0;
    if (speed > 255) speed = 255;

    gpioPWM(motor_enable, speed);
    gpioWrite(motor_direction, speed > 0);
}

// Function to move the motors simultaneously
void move_motors(int motor1_speed, int motor2_speed) {
    set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, motor1_speed);
    set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, motor2_speed);
}

// Function to perform the motion profile
void motion_profile(int motor1_speed, int motor2_speed) {
    move_motors(motor1_speed, motor2_speed);
    time_sleep(2.0); // Hold for 2 seconds
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");

    // Stop motors
    set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, 0);
    set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, 0);

    // Disable PWM
    gpioPWM(MOTOR1_ENABLE, 0);
    gpioPWM(MOTOR2_ENABLE, 0);

    // Close SPI
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Set PWM range for motor speed control
    gpioSetPWMrange(MOTOR1_ENABLE, 255);
    gpioSetPWMrange(MOTOR2_ENABLE, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read potentiometer values
        int pot1_value = read_potentiometer(POT1_CHANNEL);
        int pot2_value = read_potentiometer(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error: Failed to read potentiometers, retrying...\n");
            time_sleep(0.1);
            continue;
        }

        // Map potentiometer values to motor speed factors
        int motor1_speed = map_potentiometer_to_speed(pot1_value);
        int motor2_speed = map_potentiometer_to_speed(pot2_value);

        // Perform motion profile
        motion_profile(motor1_speed, motor2_speed);

        // Pause for 5 seconds
        time_sleep(5.0);

        // Reverse directions
        set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, 0);
        set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, 0);
        time_sleep(0.5);

        // Move motors simultaneously
        move_motors(motor1_speed, motor2_speed);
        time_sleep(2.0);

        // Pause for 5 seconds
        time_sleep(5.0);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

