#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0       // SPI channel (CE0)
#define SPI_SPEED 1000000   // SPI speed (1 MHz)
#define MCP3008_CS 8        // MCP3008 CS pin (GPIO8)
#define LED_PIN 17          // LED pin (GPIO17)
#define NOISE_THRESHOLD 10  // Noise threshold in percent (10% above average)
#define DEBOUNCE_MS 10      // LED debounce time in milliseconds
#define SAMPLE_INTERVAL_US 100000 // 100 ms between samples
#define CALIBRATION_TIME_S 5 // Calibration time in seconds

// Global variables
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int calibrate_noise_level(void);
int check_noise_level(int noise_level);
void control_led(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Function to read data from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format:
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel (0x00-0x07) << 4
    // Byte 2: Don't care (0x00)
    unsigned char spi_tx_buf[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char spi_rx_buf[3] = {0};

    // Perform SPI transfer
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calibrate the noise level
int calibrate_noise_level(void) {
    int sum = 0;
    int samples = 0;
    int noise_level;

    printf("Calibrating noise level... Please keep the microphone near the sensor.\n");

    // Wait for calibration time
    for (int i = 0; i < CALIBRATION_TIME_S * 10 && !terminate; i++) {
        gpioDelay(100000); // 100 ms
    }

    if (terminate) {
        fprintf(stderr, "Calibration interrupted by signal.\n");
        return -1;
    }

    // Read 10 samples to calculate average
    for (int i = 0; i < 10 && !terminate; i++) {
        noise_level = read_mcp3008(0);
        if (noise_level < 0) {
            fprintf(stderr, "Error reading noise level during calibration.\n");
            return -1;
        }
        sum += noise_level;
        samples++;
        gpioDelay(10000); // 10 ms delay between samples
    }

    if (terminate) {
        fprintf(stderr, "Calibration interrupted by signal.\n");
        return -1;
    }

    if (samples == 0) {
        fprintf(stderr, "Error: No samples collected during calibration.\n");
        return -1;
    }

    // Calculate average noise level
    int average_noise_level = sum / samples;
    printf("Calibration complete. Average noise level: %d\n", average_noise_level);

    return average_noise_level;
}

// Function to check the noise level
int check_noise_level(int noise_level) {
    if (noise_level < 0) {
        return 0; // Error reading noise level
    }

    // Calculate noise threshold (10% above average)
    int threshold = average_noise_level + (average_noise_level * NOISE_THRESHOLD / 100);

    // Check if noise level exceeds threshold
    if (noise_level > threshold) {
        return 1; // Noise detected
    } else {
        return 0; // Noise not detected
    }
}

