void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set SPI channel mode
    if (gpioSetMode(MCP3008_CS, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set CS pin mode\n");
        gpioTerminate();
        return 1;
    }

    // Set LED pin mode
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set LED pin mode\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Calibrate the noise level
    int average_noise_level = calibrate_noise_level();
    if (average_noise_level < 0) {
        fprintf(stderr, "Error: Failed to calibrate noise level.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Noise level calibration complete. Average noise level: %d\n", average_noise_level);

    // Main loop
    while (!terminate) {
        // Read noise level from MCP3008
        int noise_level = read_mcp3008(0);
        if (noise_level < 0) {
            fprintf(stderr, "Error reading noise level.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        // Check if noise level exceeds threshold
        int noise_detected = check_noise_level(noise_level);

        // Control LED based on noise detection
        if (noise_detected) {
            control_led(1); // Turn LED on
            gpioDelay(DEBOUNCE_MS * 1000); // Debounce for 10 ms
            control_led(0); // Turn LED off
        }

        gpioDelay(SAMPLE_INTERVAL_US); // Delay for 100 ms
    }

    // Cleanup
    printf("\nCleaning up...\n");
    control_led(0); // Turn off LED
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return 0;
}

