#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define VOLTAGE_MIN 0.5
#define VOLTAGE_MAX 4.5
#define AIRFLOW_MIN 0.0
#define AIRFLOW_MAX 200.0
#define LOG_FILE "airflow_log.txt"
#define SAMPLE_INTERVAL_US 100000 // 100 ms

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float voltage_to_airflow(float voltage);
int log_data(float airflow);
void signal_handler(int signal);

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format: Start bit (1), Single-ended mode (1), Channel select (3 bits), Don't care (1 bit)
    unsigned char tx_buffer[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx_buffer[3] = {0};

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert voltage to airflow (SLPM)
float voltage_to_airflow(float voltage) {
    if (voltage < VOLTAGE_MIN || voltage > VOLTAGE_MAX) {
        fprintf(stderr, "Error: Voltage out of range: %.2fV\n", voltage);
        return -1.0;
    }

    float airflow = (voltage - VOLTAGE_MIN) / (VOLTAGE_MAX - VOLTAGE_MIN) * AIRFLOW_MAX;
    return airflow;
}

// Function to log data to file
int log_data(float airflow) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    if (airflow < 0) {
        fprintf(log_file, "%s, ERROR: ADC read failed\n", timestamp);
    } else {
        fprintf(log_file, "%s, %.2f SLPM\n", timestamp, airflow);
    }

    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            // Error reading ADC, log and continue
            log_data(-1.0);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        // Convert ADC value to voltage
        float voltage = (adc_value / 1023.0) * 3.3;

        // Convert voltage to airflow
        float airflow = voltage_to_airflow(voltage);

        // Log data
        if (log_data(airflow) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        // Delay for 100 ms
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

