#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <math.h>
#include <signal.h>
#include <stdbool.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_FLAGS 0       // Mode 0, active low CS
#define MCP3008_CS 8      // GPIO8 for CS
#define ADC_RESOLUTION 1024.0
#define ADC_REF_VOLTAGE 3.3
#define SENSITIVITY 0.0300 // 300 mV/g
#define ZERO_G_OFFSET 1.5 // 1.5V
#define SAMPLE_RATE 10    // Hz
#define NUM_SAMPLES 100

// Kalman filter parameters
#define Q 0.01
#define R 0.01
#define P 0.1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Structure to hold Kalman filter state
typedef struct {
    float x;
    float P;
} kalman_state_t;

// Function prototypes
int read_mcp3008(int channel);
accelerometer_data_t read_adxl335();
kalman_state_t kalman_filter(kalman_state_t state, float measurement);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format: Start bit (1), Single-ended mode (1), Channel select (3 bits), Don't care (1 bit)
    unsigned char tx_buffer[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx_buffer[3] = {0};

    // Perform SPI transaction
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transaction failed with code: %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to read accelerometer data from ADXL335
accelerometer_data_t read_adxl335() {
    accelerometer_data_t data = {0.0, 0.0, 0.0};
    int adc_x, adc_y, adc_z;

    adc_x = read_mcp3008(0); // Read X-axis data
    adc_y = read_mcp3008(1); // Read Y-axis data
    adc_z = read_mcp3008(2); // Read Z-axis data

    if (adc_x < 0 || adc_y < 0 || adc_z < 0) {
        fprintf(stderr, "Error: Failed to read ADC values\n");
        return data; // Return zeros on error
    }

    // Convert ADC values to voltage
    float voltage_x = (adc_x / ADC_RESOLUTION) * ADC_REF_VOLTAGE;
    float voltage_y = (adc_y / ADC_RESOLUTION) * ADC_REF_VOLTAGE;
    float voltage_z = (adc_z / ADC_RESOLUTION) * ADC_REF_VOLTAGE;

    // Convert voltage to acceleration (g)
    data.x = (voltage_x - ZERO_G_OFFSET) / SENSITIVITY;
    data.y = (voltage_y - ZERO_G_OFFSET) / SENSITIVITY;
    data.z = (voltage_z - ZERO_G_OFFSET) / SENSITIVITY;

    return data;
}

// Kalman filter function
kalman_state_t kalman_filter(kalman_state_t state, float measurement) {
    kalman_state_t filtered_state = state;
    float prediction = filtered_state.x;
    float error = measurement - prediction;

    filtered_state.x = prediction + (Q * error);
    filtered_state.P = filtered_state.P + (R * (1 - (Q / P)));

    return filtered_state;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set CS pin as output and ensure it is high (inactive)
    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioWrite(MCP3008_CS, 1);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize Kalman filter states
    kalman_state_t kalman_x = {0.0, 0.0};
    kalman_state_t kalman_y = {0.0, 0.0};
    kalman_state_t kalman_z = {0.0, 0.0};

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        accelerometer_data_t accelerometer_data = read_adxl335();

        // Apply Kalman filter to each axis
        kalman_x = kalman_filter(kalman_x, accelerometer_data.x);
        kalman_y = kalman_filter(kalman_y, accelerometer_data.y);
        kalman_z = kalman_filter(kalman_z, accelerometer_data.z);

        // Print filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", kalman_x.x, kalman_y.x, kalman_z.x);

        // Delay for the specified sample rate
        gpioDelay(1000000 / SAMPLE_RATE); // 1000000 microseconds = 1 second
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

