#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define VCC 3.3
#define V_QUIESCENT 1.65
#define SENSITIVITY 0.025
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 100
#define MIN_FIELD_MT -100.0
#define MAX_FIELD_MT 100.0

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_sensor(struct gpiod_line *line, int pin) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return val;
}

static double calculate_field(int sensor_value) {
    double voltage = (double)sensor_value * VCC / 2;
    double field = (voltage - V_QUIESCENT) / SENSITIVITY;
    return field;
}

static int log_data(const char *data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%s\n", data) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int pins[3] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "drv5055va-hall") < 0) {
            fprintf(stderr, "Error requesting GPIO %d as input: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Reading DRV5055VA Hall-Effect sensors on GPIO%d, GPIO%d, GPIO%d...\n",
           SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN);
    printf("Logging to %s every %d ms. Press Ctrl+C to exit.\n", LOG_FILE, SAMPLE_INTERVAL_MS);

    while (program_running) {
        int sensor1_val = read_sensor(lines[0], SENSOR1_PIN);
        int sensor2_val = read_sensor(lines[1], SENSOR2_PIN);
        int sensor3_val = read_sensor(lines[2], SENSOR3_PIN);

        if (sensor1_val < 0 || sensor2_val < 0 || sensor3_val < 0) {
            fprintf(stderr, "Error reading sensor values, skipping log entry.\n");
        } else {
            double field1 = calculate_field(sensor1_val);
            double field2 = calculate_field(sensor2_val);
            double field3 = calculate_field(sensor3_val);

            if (field1 < MIN_FIELD_MT || field1 > MAX_FIELD_MT ||
                field2 < MIN_FIELD_MT || field2 > MAX_FIELD_MT ||
                field3 < MIN_FIELD_MT || field3 > MAX_FIELD_MT) {
                fprintf(stderr, "Warning: Field value out of range: %.2f mT, %.2f mT, %.2f mT\n",
                        field1, field2, field3);
            }

            char data[128];
            snprintf(data, sizeof(data), "%.2f,%.2f,%.2f", field1, field2, field3);
            if (log_data(data) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

