#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define GPIO_LED 17
#define MAX_RECONNECT_DELAY 60

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

static void led_control_callback(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;

    if (message->payloadlen <= 0) {
        log_error("Empty MQTT message received");
        return;
    }

    char *payload = malloc(message->payloadlen + 1);
    if (!payload) {
        log_error("Failed to allocate memory for MQTT payload");
        return;
    }
    memcpy(payload, message->payload, message->payloadlen);
    payload[message->payloadlen] = '\0';

    cJSON *root = cJSON_Parse(payload);
    if (!root) {
        log_error("Failed to parse JSON payload");
        free(payload);
        return;
    }

    cJSON *led_state = cJSON_GetObjectItemCaseSensitive(root, "led_state");
    if (!led_state || !cJSON_IsBool(led_state)) {
        log_error("Missing or invalid led_state key in JSON payload");
        cJSON_Delete(root);
        free(payload);
        return;
    }

    int state = led_state->valueint;
    if (state != 0 && state != 1) {
        log_error("Invalid led_state value (must be 0 or 1)");
        cJSON_Delete(root);
        free(payload);
        return;
    }

    if (gpioWrite(GPIO_LED, state) != 0) {
        log_error("Failed to write to GPIO17");
    }

    cJSON_Delete(root);
    free(payload);
}

static void mqtt_connect_callback(struct mosquitto *m, void *userdata, int result) {
    (void)m;
    (void)userdata;

    if (result == MOSQ_ERR_SUCCESS) {
        if (mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            log_error("Failed to subscribe to MQTT topic");
        } else {
            printf("Connected to MQTT broker and subscribed to %s\n", MQTT_TOPIC);
        }
    } else {
        log_error("Failed to connect to MQTT broker");
    }
}

static void mqtt_disconnect_callback(struct mosquitto *m, void *userdata, int result) {
    (void)m;
    (void)userdata;

    if (result == MOSQ_ERR_SUCCESS) {
        printf("Disconnected from MQTT broker\n");
    } else {
        log_error("Failed to disconnect from MQTT broker");
    }
}

static void mqtt_reconnect_callback(struct mosquitto *m, void *userdata, int result) {
    (void)m;
    (void)userdata;
    (void)result;

    int delay = 1;
    while (delay <= MAX_RECONNECT_DELAY && running) {
        if (mosquitto_reconnect(m) != MOSQ_ERR_SUCCESS) {
            log_error("Failed to reconnect to MQTT broker");
        } else {
            printf("Reconnected to MQTT broker after %d seconds\n", delay);
            return;
        }
        delay *= 2;
        sleep(delay);
    }

    if (!running) {
        log_error("Exiting due to signal");
    } else {
        log_error("Failed to reconnect to MQTT broker after max delay");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GPIO_LED);
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(GPIO_LED, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO%d to LOW\n", GPIO_LED);
        gpioTerminate();
        return 1;
    }

    mosquitto_lib_init();

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Failed to create mosquitto instance\n");
        gpioTerminate();
        mosquitto_lib_cleanup();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_reconnect_callback_set(mosq, mqtt_reconnect_callback);
    mosquitto_message_callback_set(mosq, led_control_callback);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to start mosquitto loop: %s\n", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    printf("LED control system started. Press Ctrl+C to exit.\n");

    while (running) {
        sleep(1);
    }

    printf("\nShutting down...\n");

    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
    return 0;
}

