    ret = gpiod_line_request_input(sound_line, CONSUMER);
    if (ret < 0) {
        perror("Failed to request sound sensor line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request alarm LED line as output, initial value LOW */
    ret = gpiod_line_request_output(alarm_line, CONSUMER, 0);
    if (ret < 0) {
        perror("Failed to request alarm LED line as output");
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Sound alarm system started. Press Ctrl+C to exit.\n");

