            ret = gpiod_line_set_value(alarm_line, 1);
            if (ret < 0) {
                perror("Failed to set alarm LED ON");
                break;
            }

            /* Blink LED for 1 second */
            for (int i = 0; i < 10 && program_running; i++) {
                usleep(100000); /* 100 ms */
            }

            ret = gpiod_line_set_value(alarm_line, 0);
            if (ret < 0) {
                perror("Failed to set alarm LED OFF");
                break;
            }
        }

        usleep(100000); /* 100 ms delay */
    }

    /* Clean up GPIO resources */
    if (sound_line) {
        gpiod_line_release(sound_line);
    }
    if (alarm_line) {
        gpiod_line_release(alarm_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

