#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define VREF 3.3
#define LM35_MV_PER_C 10.0
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"
#define READ_INTERVAL_SEC 5

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static CircularBuffer temperature_buffer;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int initialize_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    return 0;
}

static int read_mcp3008(int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = 0x01;
    tx_buf[1] = (0x08 | channel) << 4;
    tx_buf[2] = 0x00;

    int ret = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed: returned %d\n", ret);
        return -1;
    }

    *adc_value = ((rx_buf[1] & 0x03) << 8) | (rx_buf[2] & 0xFF);
    return 0;
}

static float convert_to_celsius(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF * 1000.0 / LM35_MV_PER_C;
}

static int log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "wb+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (fseek(fp, 0, SEEK_END) != 0) {
        fprintf(stderr, "Error seeking in log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    long file_size = ftell(fp);
    if (file_size < 0) {
        fprintf(stderr, "Error getting file size: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (file_size < BUFFER_SIZE * sizeof(float)) {
        size_t remaining = BUFFER_SIZE * sizeof(float) - file_size;
        memset(fp, 0, remaining);
    }

    if (fseek(fp, 0, SEEK_SET) != 0) {
        fprintf(stderr, "Error rewinding log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    size_t written = fwrite(temperature_buffer.buffer, sizeof(float), BUFFER_SIZE, fp);
    if (written != BUFFER_SIZE) {
        fprintf(stderr, "Error writing to log file: wrote %zu of %d entries\n", written, BUFFER_SIZE);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void print_temperature(float temperature) {
    printf("Temperature: %.2f °C\n", temperature);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_circular_buffer(&temperature_buffer) != 0) {
        fprintf(stderr, "Failed to initialize circular buffer\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = 0;
        if (read_mcp3008(ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Failed to read ADC value, skipping this reading\n");
        } else {
            float temperature = convert_to_celsius(adc_value);
            temperature_buffer.buffer[temperature_buffer.head] = temperature;
            temperature_buffer.head = (temperature_buffer.head + 1) % BUFFER_SIZE;
            if (temperature_buffer.count < BUFFER_SIZE) {
                temperature_buffer.count++;
            }

            print_temperature(temperature);

            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Failed to log temperature\n");
            }
        }

        time_sleep(READ_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");

    if (spiClose(spi_handle) != 0) {
        fprintf(stderr, "Error closing SPI: %s\n", strerror(errno));
    }

    gpioTerminate();

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

