#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Configuration
#define SPI_CHANNEL 0       // CE0
#define SPI_SPEED 500000    // 500 kHz
#define SPI_FLAGS 0         // Mode 0, active-low CE
#define MCP3008_CHANNEL 0   // ADC channel 0
#define DAC_I2C_ADDR 0x62   // MCP4725 I2C address
#define DAC_VREF 3.3        // DAC reference voltage
#define DAC_MAX_CODE 4095   // 12-bit DAC resolution
#define TEMP_MIN 0.0       // Minimum temperature in Celsius
#define TEMP_MAX 50.0      // Maximum temperature in Celsius
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 500000 // 0.5 seconds

// Global variables
int spi_handle = -1;
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_temperature(int adc_value);
int temperature_to_dac_code(float temperature);
int write_dac_code(int code);
int log_data(int adc_value, float temperature, float dac_voltage);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format (3 bytes):
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel (0x00 to 0x07) << 4
    // Byte 2: Don't care (0x00)
    unsigned char spi_tx_buf[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char spi_rx_buf[3] = {0};

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Convert ADC value to temperature in Celsius
float adc_to_temperature(int adc_value) {
    // TMP36: 10 mV/°C, 0 V = 0°C, 3.3 V = 50°C
    // Linear mapping: 0V -> 0°C, 3.3V -> 50°C
    return ((float)adc_value / 1023.0) * (TEMP_MAX - TEMP_MIN) + TEMP_MIN;
}

// Convert temperature to DAC code (0-4095)
int temperature_to_dac_code(float temperature) {
    if (temperature < TEMP_MIN) temperature = TEMP_MIN;
    if (temperature > TEMP_MAX) temperature = TEMP_MAX;
    return (int)((temperature - TEMP_MIN) / (TEMP_MAX - TEMP_MIN) * DAC_MAX_CODE);
}

// Write DAC code to MCP4725 via I2C
int write_dac_code(int code) {
    if (code < 0 || code > DAC_MAX_CODE) {
        fprintf(stderr, "Error: Invalid DAC code: %d\n", code);
        return -1;
    }

    // MCP4725 command format (2 bytes):
    // Byte 0: Control byte (0x40 for write)
    // Byte 1: 12-bit code (MSB first)
    unsigned char dac_tx_buf[2] = {0x40, (unsigned char)(code >> 4)};

    int result = i2cWriteDevice(i2c_handle, dac_tx_buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error: I2C write failed (returned %d)\n", result);
        return -1;
    }

    return 0;
}

// Log data to file and stdout
int log_data(int adc_value, float temperature, float dac_voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s'\n", LOG_FILE);
        return -1;
    }

    fprintf(log_file, "%s, ADC: %d, Temperature: %.2f C, DAC: %.2f V\n",
            timestamp, adc_value, temperature, dac_voltage);
    fclose(log_file);
    log_file = NULL;

    printf("%s, ADC: %d, Temperature: %.2f C, DAC: %.2f V\n",
           timestamp, adc_value, temperature, dac_voltage);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open I2C channel
    i2c_handle = i2cOpen(1, DAC_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle %d)\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float temperature = adc_to_temperature(adc_value);
        int dac_code = temperature_to_dac_code(temperature);

        if (write_dac_code(dac_code) != 0) {
            fprintf(stderr, "Error: Failed to write DAC code, retrying...\n");
        }

        if (log_data(adc_value, temperature, (float)dac_code / DAC_MAX_CODE * DAC_VREF) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    printf("Temperature monitoring stopped.\n");
    return 0;
