#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

// BCM GPIO pins for the four relays (active-high relay modules)
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Global variables for cleanup
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[4] = {NULL, NULL, NULL, NULL};
static volatile int keep_running = 1;

// Function prototypes
int init_gpio(void);
void cleanup_gpio(void);
void activate_relay(int pin);
void deactivate_relay(int pin);
void handle_signal(int sig);

// Initialize GPIO lines using libgpiod
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    // Request each line as output, initially LOW (relays off)
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", pins[i]);
            cleanup_gpio();
            return -1;
        }

        struct gpiod_line_request_config config = {
            .consumer = "light_sequencer",
            .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
            .flags = 0
        };

        if (gpiod_line_request(lines[i], &config, 0) < 0) {
            perror("Failed to request GPIO line as output");
