#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0       // CE0 (GPIO8)
#define SPI_SPEED 1000000   // 1 MHz
#define SPI_FLAGS 0         // Mode 0, active-low CE
#define LED_GPIO 16
#define SOUND_THRESHOLD 500 // 10-bit ADC value
#define DEBOUNCE_DELAY_US 10000 // 10 ms
#define LED_ON_DURATION_US 500000 // 500 ms
#define LOG_FILE "sound_events.log"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_led(int state);
void log_event(void);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format (3 bytes):
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel (0x00-0x07) << 4
    // Byte 2: Don't care (0x00)
    unsigned char spi_tx_buf[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char spi_rx_buf[3] = {0};

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Function to log the event to a file
void log_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error: Failed to format timestamp\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s: Sound detected!\n", timestamp) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Failed to close log file\n");
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    control_led(0); // Ensure LED is off initially

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0); // Read from MCP3008 channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(DEBOUNCE_DELAY_US);
            continue;
        }

        if (adc_value > SOUND_THRESHOLD) {
            printf("Sound detected! ADC value: %d\n", adc_value);
            control_led(1); // Turn on LED
            log_event();
            gpioDelay(LED_ON_DURATION_US); // Keep LED on for 500 ms
            control_led(0); // Turn off LED
        }

        gpioDelay(DEBOUNCE_DELAY_US); // Debounce delay
    }

    // Cleanup
    control_led(0); // Turn off LED
    spiClose(spi_handle); // Close SPI channel
    gpioTerminate(); // Terminate pigpio library

    printf("Sound sensor monitoring stopped.\n");
    return 0;
}

