#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// GPIO pin definitions for L298N motor driver
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

// SPI configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Rain sensor ADC channel (MCP3008 single-ended channel 0)
#define RAIN_SENSOR_CHANNEL 0

// Rain threshold (0-10)
#define RAIN_THRESHOLD 5

// Motor PWM range and duty cycle
#define MOTOR_PWM_RANGE 255
#define MOTOR_PWM_DUTY 150

// Window open/close duration in seconds
#define WINDOW_DURATION 3

// Global variables for cleanup
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rain_sensor(int channel);
int convert_to_rain_level(int adc_value);
void control_motor(int direction, int speed);
void close_window(void);
void open_window(void);
void log_rain_data(int rain_level);
void signal_handler(int signal);
int initialize(void);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Initialize pigpio, SPI, and GPIO pins
int initialize(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);

    // Set PWM range and duty cycle
    gpioSetPWMrange(MOTOR_ENA, MOTOR_PWM_RANGE);
    gpioPWM(MOTOR_ENA, MOTOR_PWM_DUTY);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read rain sensor value from MCP3008 (single-ended channel 0)
int read_rain_sensor(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3];
    unsigned char rx[3];

    // MCP3008 single-ended read: start bit, config byte, don't care
    tx[0] = 0x01;
    tx[1] = (0x08 | channel) << 4;
    tx[2] = 0x00;

    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value: bits 9-2 from rx[1], bits 1-0 from rx[2]
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

// Convert ADC value (0-1023) to rain level (0-10)
int convert_to_rain_level(int adc_value) {
    // Sensor outputs higher voltage when dry (0 ADC)
    // Map 1023 to 0, 0 to 10
    return 10 - (adc_value * 10 / 1023);
}

// Control motor: direction (1=forward, 0=reverse), speed (0-255)
void control_motor(int direction, int speed) {
    if (speed < 0 || speed > MOTOR_PWM_RANGE) {
        fprintf(stderr, "Error: Invalid motor speed %d\n", speed);
        return;
    }

    if (direction == 1) {
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
    } else {
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
    }

    gpioPWM(MOTOR_ENA, speed);
}

// Close window: forward motor for 3 seconds
void close_window(void) {
    printf("Closing window...\n");
    control_motor(1, MOTOR_PWM_DUTY);
    sleep(WINDOW_DURATION);
    control_motor(0, 0);
    printf("Window closed.\n");
}

// Open window: reverse motor for 3 seconds
void open_window(void) {
    printf("Opening window...\n");
    control_motor(0, MOTOR_PWM_DUTY);
    sleep(WINDOW_DURATION);
    control_motor(0, 0);
    printf("Window opened.\n");
}

// Log rain data to file
void log_rain_data(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up...\n");

    // Stop motor
    control_motor(0, 0);

    // Close SPI
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete.\n");
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open rain_log.txt for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_rain_sensor(RAIN_SENSOR_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read rain sensor\n");
            sleep(1);
            continue;
        }

        int rain_level = convert_to_rain_level(adc_value);
        log_rain_data(rain_level);

        printf("Rain Level: %d\n", rain_level);

        if (rain_level >= RAIN_THRESHOLD) {
            close_window();
        } else {
            open_window();
        }

        sleep(1);
    }

    // Cleanup
    cleanup();
    return EXIT_SUCCESS;
}

