#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define MIC_GPIO 26
#define LED_GPIO 16
#define ADC_RESOLUTION 1023.0
#define THRESHOLD_VOLTAGE 0.7
#define LED_ON_TIME_MS 500
#define DEBOUNCE_MS 50
#define SAMPLE_DELAY_US 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read the analog level from the MAX9814 via bit-banged ADC sampling.
 * Returns 0-1023 on success, -1 on error.
 */
static int read_adc(void) {
    int adc_value = 0;
    int i;

    /*
     * MAX9814 AGC: sample for 100 us, then read the 10-bit result.
     * We sample at 1 kHz, so the ADC clock is ~100 us.
     */
    for (i = 0; i < 100; i++) {
        gpioWrite(MIC_GPIO, 1);
        gpioDelay(1);
        adc_value += gpioRead(MIC_GPIO);
        gpioWrite(MIC_GPIO, 0);
        gpioDelay(1);
    }

    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

static void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

static void log_detection(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Clap detected!\n", timestamp);
    fflush(stdout);
}

int main(void) {
    int adc_value;
    int led_state = 0;
    int debounce_count = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(MIC_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set MIC_GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off initially */
    control_led(0);

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Clap detection started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, retrying...\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        /* Convert ADC value to voltage */
        float voltage = (float)adc_value / ADC_RESOLUTION * 3.3;

        /* Check if clap is detected */
        if (voltage > THRESHOLD_VOLTAGE) {
            debounce_count++;
            if (debounce_count >= (DEBOUNCE_MS * 1000) / SAMPLE_DELAY_US) {
                debounce_count = 0;
                led_state = !led_state;
                control_led(led_state);
                log_detection();
            }
        } else {
            debounce_count = 0;
            led_state = 0;
            control_led(led_state);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    /* Clean shutdown */
    control_led(0);
    gpioTerminate();
    printf("\nClap detection stopped.\n");
    return EXIT_SUCCESS;
}

