                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, field);
    } else {
        fprintf(fp, "Timestamp error, Field: %.2f mT\n", field);
    }

    fclose(fp);
}

