#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

/*
 * Raspberry Pi Zero W — MLX91211 current sensor via MCP3008 ADC
 *
 * Hardware:
 *   - MCP3008 on SPI0 (CE0=GPIO8, MOSI=GPIO10, MISO=GPIO9, SCLK=GPIO11)
 *   - MCP3008 VDD/VREF -> Pi 5V rail, AGND/DGND -> Pi GND
 *   - MLX91211 analog output -> MCP3008 CH0 (single-ended)
 *   - MLX91211 VDD -> Pi 5V, GND -> Pi GND
 *
 * MLX91211 ratiometric output:
 *   2.5V  -> 0 A
 *   5.0V  -> 50 A
 *
 * Build: gcc -Wall -Wextra -O2 -o current_logger current_logger.c -lpigpio -lrt
 * Run:   sudo ./current_logger
 */

#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended CH0 */
#define LOG_FILE       "current_log.txt"
#define SAMPLE_PERIOD_US 100000   /* 100 ms */

/* MLX91211 linear calibration */
#define VDD_SUPPLY      5.0f
#define VOUT_ZERO       2.5f
#define VOUT_FULL       5.0f
#define CURRENT_FULL    50.0f

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended sample from the MCP3008                       */
/* Returns 0-1023 on success, -1 on SPI transfer error                */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = 0x80 | (channel << 4)      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2]
     */
    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert raw ADC code to voltage (0-5V)                            */
/* ------------------------------------------------------------------ */
static float adc_to_voltage(int adc_value)
{
    return ((float)adc_value / 1023.0f) * VDD_SUPPLY;
}

/* ------------------------------------------------------------------ */
/* Convert voltage to current (A) using linear interpolation          */
/* ------------------------------------------------------------------ */
static float voltage_to_current(float voltage)
{
    if (voltage < VOUT_ZERO) {
        fprintf(stderr, "Warning: voltage %.3f V below zero — skipping sample\n", voltage);
        return 0.0f;
    }
    if (voltage > VOUT_FULL) {
        fprintf(stderr, "Warning: voltage %.3f V above full scale — skipping sample\n", voltage);
        return 0.0f;
    }

    float current = (voltage - VOUT_ZERO) * (CURRENT_FULL / (VOUT_FULL - VOUT_ZERO));
    return current;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped current reading to the log file                */
/* ------------------------------------------------------------------ */
static int log_current(float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file\n");
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    printf("MLX91211 current logger started. Logging to '%s'. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            /* SPI error — skip this sample and wait before retrying */
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float current = voltage_to_current(voltage);

        if (log_current(current) != 0) {
            fprintf(stderr, "Warning: failed to log current reading\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

