#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_MS 2
#define POLL_INTERVAL_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int debounce_read(struct gpiod_line *line) {
    int sum = 0;
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO line\n");
            return -1;
        }
        sum += val;
        usleep(DEBOUNCE_DELAY_MS * 1000);
    }
    return (sum >= (DEBOUNCE_SAMPLES / 2)) ? 0 : 1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip 0");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        perror("Failed to get GPIO line 4");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        perror("Failed to get GPIO line 17");
        goto cleanup;
    }

    if (gpiod_line_request_input(line1, "b5w-db01-sensor1") < 0) {
        perror("Failed to request GPIO line 4 as input");
        goto cleanup;
    }

    if (gpiod_line_request_input(line2, "b5w-db01-sensor2") < 0) {
        perror("Failed to request GPIO line 17 as input");
        goto cleanup;
    }

    printf("Monitoring B5W-DB01 sensors on GPIO%d and GPIO%d...\n", SENSOR1_PIN, SENSOR2_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = debounce_read(line1);
        int s2 = debounce_read(line2);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error reading sensor values\n");
            break;
        }

        printf("Sensor 1: %d, Sensor 2: %d\n", s1, s2);

        if (s1 == 0 && s2 == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

