#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <errno.h>
#include <sys/wait.h>
#include <pigpio.h>

#define PIR_GPIO          17
#define DEBOUNCE_MS       200
#define POLL_INTERVAL_US  50000   /* 50 ms */
#define CAPTURE_WIDTH      1280
#define CAPTURE_HEIGHT     720
#define CAPTURE_QUALITY    85
#define CAPTURE_TIMEOUT   10      /* seconds */
#define CAPTURE_DIR       "/home/pi/security_cam"
#define LOG_FILE          "/var/log/security_cam.log"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int priority, const char *message)
{
    openlog(LOG_FILE, LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", message);
    closelog();
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static int ensure_capture_dir(void)
{
    if (access(CAPTURE_DIR, F_OK) == 0)
        return 0;

    if (mkdir(CAPTURE_DIR, 0755) != 0) {
        syslog(LOG_ERR, "mkdir(%s): %s", CAPTURE_DIR, strerror(errno));
        return -1;
    }

    syslog(LOG_INFO, "Created capture directory: %s", CAPTURE_DIR);
    return 0;
}

static int capture_image(void)
{
    char filename[256];
    char command[512];

    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        syslog(LOG_ERR, "localtime_r failed: %s", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H%M%S",
                 &timeinfo) == 0) {
        syslog(LOG_ERR, "strftime failed");
        return -1;
    }

    snprintf(filename, sizeof(filename), "%s/%s.jpg",
             CAPTURE_DIR, timestamp);

    snprintf(command, sizeof(command),
             "libcamera-still -o '%s' --width %d --height %d --quality %d "
             "--timeout %d",
             filename, CAPTURE_WIDTH, CAPTURE_HEIGHT, CAPTURE_QUALITY,
             CAPTURE_TIMEOUT);

    syslog(LOG_INFO, "Capturing image: %s", filename);

    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork() failed: %s", strerror(errno));
        return -1;
    }

    if (pid == 0) {
        /* Child: redirect stdout/stderr to syslog */
        openlog("libcamera-still", LOG_PID | LOG_CONS, LOG_USER);
        dup2(LOG_FILE_DESC, STDOUT_FILENO);
        dup2(LOG_FILE_DESC, STDERR_FILENO);
        closelog();

        /* Execute libcamera-still */
        execlp("libcamera-still", "libcamera-still",
               "-o", filename,
               "--width", "1280",
               "--height", "720",
               "--quality", "85",
               "--timeout", "10",
               (char *)NULL);

        /* If execvp returns, it failed */
        syslog(LOG_ERR, "execlp(libcamera-still) failed: %s",
               strerror(errno));
        _exit(127);
    }

    /* Parent: wait for child to finish */
    int status = 0;
    pid_t w;
    do {
        w = waitpid(pid, &status, 0);
    } while (w < 0 && errno == EINTR);

    if (w < 0) {
        syslog(LOG_ERR, "waitpid() failed: %s", strerror(errno));
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        syslog(LOG_INFO, "Image captured successfully: %s", filename);
        return 0;
    }

    syslog(LOG_ERR, "libcamera-still failed (exit status %d)",
           WIFEXITED(status) ? WEXITSTATUS(status) : -1);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return EXIT_FAILURE;
    }

    /* Configure PIR GPIO as input with pull-down */
    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_INPUT) failed", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure capture directory exists */
    if (ensure_capture_dir() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Security camera started (PIR=BCM%d, dir=%s)",
           PIR_GPIO, CAPTURE_DIR);

    int last_state = gpioRead(PIR_GPIO);
    if (last_state < 0) {
        syslog(LOG_ERR, "gpioRead(%d) failed: %s", PIR_GPIO, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event(LOG_INFO, "System started");

    while (g_running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead(%d) failed: %s", PIR_GPIO, strerror(errno));
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        /* Detect rising edge (motion detected) */
        if (current_state == 1 && last_state == 0) {
            syslog(LOG_INFO, "Motion detected on GPIO%d", PIR_GPIO);

            /* Debounce delay */
            gpioDelay(DEBOUNCE_MS * 1000);

            int confirmed_state = gpioRead(PIR_GPIO);
            if (confirmed_state < 0) {
                syslog(LOG_ERR, "gpioRead(%d) failed during debounce: %s",
                       PIR_GPIO, strerror(errno));
                continue;
            }

            if (confirmed_state == 1) {
                if (capture_image() == 0) {
                    log_event(LOG_INFO, "Motion detected and image captured");
                } else {
                    log_event(LOG_ERR, "Motion detected but image capture failed");
                }
            }
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    /* Graceful shutdown */
    syslog(LOG_INFO, "Shutting down");
    log_event(LOG_INFO, "System stopped");
    gpioTerminate();
    return EXIT_SUCCESS;
}

