#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEFAULT_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 4
#define CAPTURE_INTERVAL_SEC 1
#define TIMEOUT_SEC 2

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fh, int request, void *arg) {
    int r;
    do {
        r = ioctl(fh, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(const char *device, struct v4l2_capability *cap, struct v4l2_format *fmt, struct v4l2_requestbuffers *req) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device, strerror(errno));
        return -1;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (!(cap->capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", device);
        close(fd);
        return -1;
    }

    if (!(cap->capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", device);
        close(fd);
        return -1;
    }

    if (cap->device_caps & V4L2_CAP_VIDEO_CAPTURE_MPLANE) {
        fmt->type = V4L2_BUF_TYPE_VIDEO_CAPTURE_MPLANE;
    } else {
        fmt->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    }
    fmt->fmt.pix.width = IMAGE_WIDTH;
    fmt->fmt.pix.height = IMAGE_HEIGHT;
    fmt->fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt->fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (fmt->fmt.pix.pixelformat != V4L2_PIX_FMT_GREY) {
        fprintf(stderr, "Warning: requested format %c, got %c\n", V4L2_PIX_FMT_GREY, fmt->fmt.pix.pixelformat);
    }

    req->count = NUM_BUFFERS;
    req->type = fmt->type;
    req->memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (req->count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        return -1;
    }

    return fd;
}

static int init_buffers(int fd, struct v4l2_buffer *buffers, size_t n_buffers) {
    for (size_t i = 0; i < n_buffers; i++) {
        buffers[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buffers[i].memory = V4L2_MEMORY_MMAP;
        buffers[i].index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buffers[i]) < 0) {
            fprintf(stderr, "Error querying buffer %zu: %s\n", i, strerror(errno));
            return -1;
        }

        void *map = mmap(NULL, buffers[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buffers[i].m.offset);
        if (map == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %zu: %s\n", i, strerror(errno));
            return -1;
        }

        buffers[i].m.userptr = map;
    }

    for (size_t i = 0; i < n_buffers; i++) {
        if (xioctl(fd, VIDIOC_QBUF, &buffers[i]) < 0) {
            fprintf(stderr, "Error queuing buffer %zu: %s\n", i, strerror(errno));
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting streaming: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int capture_frame(int fd, struct v4l2_buffer *buf) {
    fd_set fds;
    struct timeval tv;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = TIMEOUT_SEC;
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "Error in select(): %s\n", strerror(errno));
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "select() timed out\n");
        return -1;
    }

    if (xioctl(fd, VIDIOC_DQBUF, buf) < 0) {
        if (errno == EAGAIN) return 0;
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int save_image(const char *filename, const unsigned char *data, int width, int height) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", width, height);
    size_t total = (size_t)width * height;
    if (fwrite(data, 1, total, fp) != total) {
        fprintf(stderr, "Error writing image data: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(int fd, struct v4l2_buffer *buffers, size_t n_buffers) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Warning: error stopping streaming: %s\n", strerror(errno));
    }

    for (size_t i = 0; i < n_buffers; i++) {
        if (buffers[i].m.userptr) {
            munmap(buffers[i].m.userptr, buffers[i].length);
        }
    }

    if (fd >= 0) {
        close(fd);
    }
}

int main(int argc, char *argv[]) {
    const char *device = DEFAULT_DEVICE;
    if (argc > 1) {
        device = argv[1];
    }

    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *image_data = NULL;
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = init_camera(device, &cap, &fmt, &req);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    image_data = malloc(IMAGE_WIDTH * IMAGE_HEIGHT);
    if (!image_data) {
        fprintf(stderr, "Error allocating memory for image data\n");
        cleanup(fd, NULL, 0);
        return EXIT_FAILURE;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "Error allocating memory for buffer structures\n");
        free(image_data);
        cleanup(fd, NULL, 0);
        return EXIT_FAILURE;
    }

    if (init_buffers(fd, buffers, req.count) < 0) {
        free(buffers);
        free(image_data);
        cleanup(fd, NULL, 0);
        return EXIT_FAILURE;
    }

    printf("Capturing grayscale images from %s. Press Ctrl+C to stop.\n", device);

    while (running) {
        if (capture_frame(fd, &buf) < 0) {
            if (!running) break;
            continue;
        }

        memcpy(image_data, buffers[buf.index].m.userptr, IMAGE_WIDTH * IMAGE_HEIGHT);

        char filename[64];
        snprintf(filename, sizeof(filename), "image_%04d.pgm", buf.index + 1);

        if (save_image(filename, image_data, IMAGE_WIDTH, IMAGE_HEIGHT) < 0) {
            fprintf(stderr, "Error saving image %s\n", filename);
        } else {
            printf("Saved image %s\n", filename);
        }

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error re-queuing buffer: %s\n", strerror(errno));
            break;
        }

        if (running) {
            sleep(CAPTURE_INTERVAL_SEC);
        }
    }

    ret = EXIT_SUCCESS;

    free(buffers);
    free(image_data);
    cleanup(fd, NULL, 0);

    printf("Exiting.\n");
    return ret;
}

