static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_video(int *fd, struct v4l2_capability *cap, struct v4l2_format *fmt, struct v4l2_requestbuffers *req) {
    *fd = open(VIDEO_DEVICE, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", VIDEO_DEVICE, strerror(errno));
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }

    if (!(cap->capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", VIDEO_DEVICE);
        close(*fd);
        *fd = -1;
        return -1;
    }

    if (!(cap->capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", VIDEO_DEVICE);
        close(*fd);
        *fd = -1;
        return -1;
    }

    memset(fmt, 0, sizeof(*fmt));
    fmt->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt->fmt.pix.width = MAX_WIDTH;
    fmt->fmt.pix.height = MAX_HEIGHT;
    fmt->fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt->fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }

    if (fmt->fmt.pix.width != MAX_WIDTH || fmt->fmt.pix.height != MAX_HEIGHT) {
        fprintf(stderr, "Warning: driver did not set resolution to %dx%d\n", fmt->fmt.pix.width, fmt->fmt.pix.height);
    }

    memset(req, 0, sizeof(*req));
    req->count = MAX_BUFFERS;
    req->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req->memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }

    if (req->count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(*fd);
        *fd = -1;
        return -1;
    }

    for (int i = 0; i < req->count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error querying buffer %d: %s\n", i, strerror(errno));
            close(*fd);
            *fd = -1;
            return -1;
        }

        size_t size = buf.length;
        buf.m.offset = 0;

        if (xioctl(*fd, VIDIOC_MMAP, &buf) < 0) {
            fprintf(stderr, "Error mapping buffer %d: %s\n", i, strerror(errno));
            close(*fd);
            *fd = -1;
            return -1;
        }

        buffers[i].fd = *fd;
        buffers[i].index = i;
        buffers[i].buffer = buf;
        buffers[i].start = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, buf.m.fd, buf.m.offset);
        if (buffers[i].start == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %d: %s\n", i, strerror(errno));
            munmap(buffers[i].start, size);
            buffers[i].start = NULL;
            close(*fd);
            *fd = -1;
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(*fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting streaming: %s\n", strerror(errno));
        for (int i = 0; i < req->count; i++) {
            munmap(buffers[i].start, buffers[i].buffer.length);
            buffers[i].start = NULL;
        }
        close(*fd);
        *fd = -1;
        return -1;
    }

    return 0;
}

static int capture_frame(int fd, struct v4l2_buffer *buf) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_QBUF, buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting streaming: %s\n", strerror(errno));
        return -1;
    }

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r < 0) {
        fprintf(stderr, "Error selecting frame: %s\n", strerror(errno));
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    if (xioctl(fd, VIDIOC_DQBUF, buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping streaming: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int send_udp_packet(int sockfd, const char *data, size_t len) {
    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(8000);

    if (inet_pton(AF_INET, "192.168.1.100", &servaddr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported: %s\n", strerror(errno));
        return -1;
    }

    if (sendto(sockfd, data, len, 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        fprintf(stderr, "Error sending UDP packet: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);

    if (server_port <= 0 || server_port > 65535) {
        fprintf(stderr, "Invalid port number: %s\n", argv[2]);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct buffer {
        int fd;
        int index;
        struct v4l2_buffer buffer;
        void *start;
    } buffers[MAX_BUFFERS];

    if (init_video(&fd, &cap, &fmt, &req) < 0) {
        return 1;
    }

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        for (int i = 0; i < req.count; i++) {
            munmap(buffers[i].start, buffers[i].buffer.length);
            buffers[i].start = NULL;
        }
        close(fd);
        return 1;
    }

    printf("Video streaming started. Capturing at %dx%d. Sending to %s:%d\n", MAX_WIDTH, MAX_HEIGHT, server_ip, server_port);

    while (running) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (capture_frame(fd, &buf) < 0) {
            break;
        }

        size_t frame_size = buf.bytesused;
        size_t fragments = (frame_size + MAX_UDP_PACKET_SIZE - 1) / MAX_UDP_PACKET_SIZE;
        size_t payload_size = frame_size % MAX_UDP_PACKET_SIZE;

        for (size_t i = 0; i < fragments; i++) {
            size_t packet_size = (i == fragments - 1) ? payload_size : MAX_UDP_PACKET_SIZE;
            char *packet = malloc(UDP_HEADER_SIZE + packet_size);
            if (!packet) {
                fprintf(stderr, "Error allocating packet memory\n");
                break;
            }

            size_t offset = i * MAX_UDP_PACKET_SIZE;
            size_t copy_size = (offset + packet_size > frame_size) ? (frame_size - offset) : packet_size;

            memcpy(packet + UDP_HEADER_SIZE, buf.start + offset, copy_size);

            struct {
                uint32_t frame_index;
                uint32_t fragment_index;
                uint32_t total_fragments;
                uint32_t payload_size;
            } header;
            header.frame_index = 0;
            header.fragment_index = i;
            header.total_fragments = fragments;
            header.payload_size = copy_size;

            memcpy(packet, &header, UDP_HEADER_SIZE);

            if (send_udp_packet(sockfd, packet, UDP_HEADER_SIZE + packet_size) < 0) {
                free(packet);
                break;
            }

            free(packet);
        }
    }

    printf("\nShutting down...\n");

    for (int i = 0; i < req.count; i++) {
        if (buffers[i].start) {
            munmap(buffers[i].start, buffers[i].buffer.length);
            buffers[i].start = NULL;
        }
    }

    if (fd >= 0) {
        close(fd);
    }

    if (sockfd >= 0) {
        close(sockfd);
    }

    return 0;
}

