#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 1920
#define IMAGE_HEIGHT 1080
#define IMAGE_FILE "image.jpg"
#define NUM_BUFFERS 4

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_device(int *fd) {
    *fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (*fd == -1) {
        perror("Error opening device");
        return -1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        close(*fd);
        *fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(*fd);
        *fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(*fd);
        *fd = -1;
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        close(*fd);
        *fd = -1;
        return -1;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "Device does not support MJPEG format\n");
        close(*fd);
        *fd = -1;
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        close(*fd);
        *fd = -1;
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(*fd);
        *fd = -1;
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("Error querying buffer");
        close(*fd);
        *fd = -1;
        return -1;
    }

    void *map = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset);
    if (map == MAP_FAILED) {
        perror("Error mapping buffer");
        close(*fd);
        *fd = -1;
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error queueing initial buffer");
        munmap(map, buf.length);
        close(*fd);
        *fd = -1;
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(*fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting streaming");
        munmap(map, buf.length);
        close(*fd);
        *fd = -1;
        return -1;
    }

    return 0;
}

static int capture_image(int fd, void **buffer, size_t *buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0;
        }
        perror("Error dequeuing buffer");
        return -1;
    }

    if (buf.bytesused == 0) {
        fprintf(stderr, "Error: empty frame received\n");
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (*buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    *buffer_size = buf.bytesused;

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error queueing buffer");
        munmap(*buffer, buf.length);
        return -1;
    }

    return 0;
}

static int save_image(const char *filename, const void *buffer, size_t buffer_size) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t written = fwrite(buffer, 1, buffer_size, fp);
    if (written != buffer_size) {
        fprintf(stderr, "Error writing to file: wrote %zu of %zu bytes\n", written, buffer_size);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing file");
        return -1;
    }

    printf("Image saved to %s (%zu bytes)\n", filename, buffer_size);
    return 0;
}

static void cleanup(int fd, void **buffers, size_t *buffer_sizes) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping streaming");
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (buffers[i] && buffers[i] != MAP_FAILED) {
            munmap(buffers[i], buffer_sizes[i]);
        }
    }

    if (fd != -1) {
        close(fd);
    }
}

int main(void) {
    int fd = -1;
    void *buffers[NUM_BUFFERS] = {NULL};
    size_t buffer_sizes[NUM_BUFFERS] = {0};

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error installing SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Error installing SIGTERM handler");
        return 1;
    }

    if (init_device(&fd) == -1) {
        return 1;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Error querying buffer");
            cleanup(fd, buffers, buffer_sizes);
            return 1;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("Error mapping buffer");
            cleanup(fd, buffers, buffer_sizes);
            return 1;
        }

        buffer_sizes[i] = buf.length;
    }

    printf("Capturing image...\n");

    while (!stop_flag) {
        if (capture_image(fd, buffers, buffer_sizes) == 0) {
            break;
        }
        usleep(10000);
    }

    if (stop_flag) {
        printf("\nInterrupted by signal, exiting gracefully...\n");
    }

    if (save_image(IMAGE_FILE, buffers[0], buffer_sizes[0]) == -1) {
        fprintf(stderr, "Failed to save image\n");
    }

    cleanup(fd, buffers, buffer_sizes);
    return 0;
}

