#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define BUTTON_UP 6
#define BUTTON_DOWN 7
#define BUTTON_LEFT 8
#define BUTTON_RIGHT 9

#define SERVO_MIN_PULSE_WIDTH 1000  // 1 ms
#define SERVO_MAX_PULSE_WIDTH 2000  // 2 ms
#define SERVO_CENTER_PULSE_WIDTH 1500 // 1.5 ms
#define SERVO_MIN_POSITION 25
#define SERVO_MAX_POSITION 125
#define SERVO_STEP 5
#define PWM_PERIOD_NS 20000000  // 20 ms
#define POLL_INTERVAL_NS 50000000  // 50 ms

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse_width(struct gpiod_line *line, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) pulse_width = SERVO_MIN_PULSE_WIDTH;
    if (pulse_width > SERVO_MAX_PULSE_WIDTH) pulse_width = SERVO_MAX_PULSE_WIDTH;
    int duty_cycle = (pulse_width * 1000) / PWM_PERIOD_NS;
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 1000) duty_cycle = 1000;
    int on_time_ns = (duty_cycle * PWM_PERIOD_NS) / 1000;
    int off_time_ns = PWM_PERIOD_NS - on_time_ns;
    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(on_time_ns / 1000);
    if (gpiod_line_set_value(line, 0) < 0) return -1;
    usleep(off_time_ns / 1000);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pan_line = NULL;
    struct gpiod_line *tilt_line = NULL;
    struct gpiod_line *button_lines[4] = {NULL, NULL, NULL, NULL};
    int positions[4] = {SERVO_CENTER_PULSE_WIDTH, SERVO_CENTER_PULSE_WIDTH, SERVO_CENTER_PULSE_WIDTH, SERVO_CENTER_PULSE_WIDTH};
    int ret = EXIT_FAILURE;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    pan_line = gpiod_chip_get_line(chip, PAN_SERVO_PIN);
    tilt_line = gpiod_chip_get_line(chip, TILT_SERVO_PIN);
    button_lines[0] = gpiod_chip_get_line(chip, BUTTON_UP);
    button_lines[1] = gpiod_chip_get_line(chip, BUTTON_DOWN);
    button_lines[2] = gpiod_chip_get_line(chip, BUTTON_LEFT);
    button_lines[3] = gpiod_chip_get_line(chip, BUTTON_RIGHT);

    if (!pan_line || !tilt_line || !button_lines[0] || !button_lines[1] || !button_lines[2] || !button_lines[3]) {
        perror("Failed to get GPIO lines");
        goto cleanup;
    }

    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_input_flags(button_lines[i], "camera-control", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
            perror("Failed to request button line as input");
            goto cleanup;
        }
    }

    if (gpiod_line_request_output(pan_line, "camera-control", 0) < 0 ||
        gpiod_line_request_output(tilt_line, "camera-control", 0) < 0) {
        perror("Failed to request servo lines as output");
        goto cleanup;
    }

    printf("Camera control started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < 4; i++) {
            int val = gpiod_line_get_value(button_lines[i]);
            if (val < 0) {
                perror("Failed to read button");
                goto cleanup;
            }
            if (val == 0) {  // active-low
                positions[i] += SERVO_STEP;
                if (positions[i] > SERVO_MAX_POSITION) positions[i] = SERVO_MAX_POSITION;
                if (positions[i] < SERVO_MIN_POSITION) positions[i] = SERVO_MIN_POSITION;
                if (set_servo_pulse_width(button_lines[i] == BUTTON_UP ? tilt_line : pan_line, positions[i]) < 0) {
                    perror("Failed to set servo pulse width");
                    goto cleanup;
                }
            }
        }
        usleep(POLL_INTERVAL_NS / 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (pan_line) gpiod_line_release(pan_line);
    if (tilt_line) gpiod_line_release(tilt_line);
    for (int i = 0; i < 4; i++) {
        if (button_lines[i]) gpiod_line_release(button_lines[i]);
    }
    if (chip) gpiod_chip_close(chip);
    printf("Camera control stopped.\n");
    return ret;
}

