    printf("Type: %u\n", fmt->type);
    printf("Pixel format: %c%c%c%c\n",
           (fmt->pixelformat >> 0) & 0xFF,
           (fmt->pixelformat >> 8) & 0xFF,
           (fmt->pixelformat >> 16) & 0xFF,
           (fmt->pixelformat >> 24) & 0xFF);
    printf("Field: %u\n", fmt->field);
    printf("Size: %ux%u\n", fmt->fmt.pix.width, fmt->fmt.pix.height);
}

static void print_frame_size(const struct v4l2_frmsizeenum *fs)
{
    printf("Type: %u\n", fs->type);
    printf("Index: %u\n", fs->index);
    printf("Pixel format: %c%c%c%c\n",
           (fs->pixel_format >> 0) & 0xFF,
           (fs->pixel_format >> 8) & 0xFF,
           (fs->pixel_format >> 16) & 0xFF,
           (fs->pixel_format >> 24) & 0xFF);
    printf("Width: %u\n", fs->discrete.width);
    printf("Height: %u\n", fs->discrete.height);
    printf("Step: %u\n", fs->step.width);
    printf("Step: %u\n", fs->step.height);
}

static void print_frame_interval(const struct v4l2_frmivalenum *fi)
{
    printf("Type: %u\n", fi->type);
    printf("Index: %u\n", fi->index);
    printf("Pixel format: %c%c%c%c\n",
           (fi->pixel_format >> 0) & 0xFF,
           (fi->pixel_format >> 8) & 0xFF,
           (fi->pixel_format >> 16) & 0xFF,
           (fi->pixel_format >> 24) & 0xFF);
    printf("Min: %u/%u\n", fi->discrete.numerator, fi->discrete.denominator);
    printf("Max: %u/%u\n", fi->discrete.numerator, fi->discrete.denominator);
    printf("Step: %u/%u\n", fi->step.numerator, fi->step.denominator);
}

static void print_control(const struct v4l2_control *ctrl)
{
    printf("ID: 0x%08x\n", ctrl->id);
    printf("Value: %d\n", ctrl->value);
    printf("Minimum: %d\n", ctrl->minimum);
    printf("Maximum: %d\n", ctrl->maximum);
    printf("Step: %d\n", ctrl->step);
}

int main(void)
{
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    print_capability(&cap);

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB24;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    print_format(&fmt);

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    void *map = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (map == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        munmap(map, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting streaming: %s\n", strerror(errno));
        munmap(map, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap_query;
    memset(&cap_query, 0, sizeof(cap_query));
    cap_query.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    cap_query.index = 0;

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap_query) < 0) {
        fprintf(stderr, "Error querying capabilities after stream: %s\n", strerror(errno));
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(map, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap_query.capabilities & V4L2_CAP_FRAME_INTERVALS)) {
        fprintf(stderr, "Camera does not support frame intervals\n");
    }

    struct v4l2_frmsizeenum frmsize;
    memset(&frmsize, 0, sizeof(frmsize));
    frmsize.index = 0;
    frmsize.pixel_format = V4L2_PIX_FMT_RGB24;
    frmsize.type = V4L2_FRMSIZE_TYPE_DISCRETE;

    if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) < 0) {
        fprintf(stderr, "Error enumerating frame sizes: %s\n", strerror(errno));
    } else {
        printf("Supported frame sizes:\n");
        while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
            print_frame_size(&frmsize);
            frmsize.index++;
        }
        if (errno != EINVAL) {
            fprintf(stderr, "Error enumerating frame sizes: %s\n", strerror(errno));
        }
    }

    struct v4l2_frmivalenum frmival;
    memset(&frmival, 0, sizeof(frmival));
    frmival.index = 0;
    frmival.pixel_format = V4L2_PIX_FMT_RGB24;
    frmival.type = V4L2_FRMVAL_TYPE_DISCRETE;

    if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) < 0) {
        fprintf(stderr, "Error enumerating frame intervals: %s\n", strerror(errno));
    } else {
        printf("Supported frame intervals:\n");
        while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
            print_frame_interval(&frmival);
            frmival.index++;
        }
        if (errno != EINVAL) {
            fprintf(stderr, "Error enumerating frame intervals: %s\n", strerror(errno));
        }
    }

    struct v4l2_control ctrl;
    memset(&ctrl, 0, sizeof(ctrl));
    ctrl.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &ctrl) < 0) {
        fprintf(stderr, "Error querying focus control: %s\n", strerror(errno));
    } else {
        print_control(&ctrl);
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping streaming: %s\n", strerror(errno));
    }

    munmap(map, buf.length);
    close(fd);

    return EXIT_SUCCESS;
}

