#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5

#define UP_BUTTON_PIN    6
#define DOWN_BUTTON_PIN  7
#define LEFT_BUTTON_PIN  8
#define RIGHT_BUTTON_PIN 9

#define SERVO_MIN_US     1000
#define SERVO_MAX_US     2000
#define SERVO_CENTER_US  1500

#define LOOP_DELAY_US    50000   /* 50 ms */
#define STEP_SIZE_US     10      /* 10 us per step */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_position(int pin, int pulse_us)
{
    if (pulse_us < SERVO_MIN_US || pulse_us > SERVO_MAX_US) {
        fprintf(stderr, "Error: pulse %d us out of range [%d, %d]\n",
                pulse_us, SERVO_MIN_US, SERVO_MAX_US);
        return -1;
    }
    if (gpioServo(pin, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return -1;
    }

    /* Configure button pins as inputs with internal pull-ups */
    if (gpioSetMode(UP_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for UP_BUTTON_PIN\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for DOWN_BUTTON_PIN\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for LEFT_BUTTON_PIN\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for RIGHT_BUTTON_PIN\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for UP_BUTTON_PIN\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for DOWN_BUTTON_PIN\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for LEFT_BUTTON_PIN\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for RIGHT_BUTTON_PIN\n");
        gpioTerminate();
        return -1;
    }

    /* Initialize servos to center position */
    if (set_servo_position(PAN_SERVO_PIN, SERVO_CENTER_US) < 0) {
        gpioTerminate();
        return -1;
    }
    if (set_servo_position(TILT_SERVO_PIN, SERVO_CENTER_US) < 0) {
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Stop PWM on both servos */
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);

    /* Release pigpio resources */
    gpioTerminate();
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Pan-tilt system started.\n");
    printf("  Pan servo : GPIO%d\n", PAN_SERVO_PIN);
    printf("  Tilt servo: GPIO%d\n", TILT_SERVO_PIN);
    printf("  UP    : GPIO%d\n", UP_BUTTON_PIN);
    printf("  DOWN  : GPIO%d\n", DOWN_BUTTON_PIN);
    printf("  LEFT  : GPIO%d\n", LEFT_BUTTON_PIN);
    printf("  RIGHT : GPIO%d\n", RIGHT_BUTTON_PIN);
    printf("Press a button to move the servos. Press Ctrl+C to exit.\n");

    int pan_pos = SERVO_CENTER_US;
    int tilt_pos = SERVO_CENTER_US;

    while (g_running) {
        int up_pressed  = (gpioRead(UP_BUTTON_PIN)  == 0);
        int down_pressed = (gpioRead(DOWN_BUTTON_PIN) == 0);
        int left_pressed = (gpioRead(LEFT_BUTTON_PIN) == 0);
        int right_pressed = (gpioRead(RIGHT_BUTTON_PIN) == 0);

        if (up_pressed) {
            pan_pos += STEP_SIZE_US;
            if (pan_pos > SERVO_MAX_US) pan_pos = SERVO_MAX_US;
        } else if (down_pressed) {
            pan_pos -= STEP_SIZE_US;
            if (pan_pos < SERVO_MIN_US) pan_pos = SERVO_MIN_US;
        }

        if (left_pressed) {
            tilt_pos += STEP_SIZE_US;
            if (tilt_pos > SERVO_MAX_US) tilt_pos = SERVO_MAX_US;
        } else if (right_pressed) {
            tilt_pos -= STEP_SIZE_US;
            if (tilt_pos < SERVO_MIN_US) tilt_pos = SERVO_MIN_US;
        }

        if (set_servo_position(PAN_SERVO_PIN, pan_pos) < 0) {
            fprintf(stderr, "Warning: failed to set pan servo position\n");
        }
        if (set_servo_position(TILT_SERVO_PIN, tilt_pos) < 0) {
            fprintf(stderr, "Warning: failed to set tilt servo position\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

