#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>
#include <curl/curl.h>

#define PIR_GPIO 17
#define DEBOUNCE_MS 2000
#define POLL_INTERVAL_MS 100
#define CAPTURE_DIR "motion_captures"
#define MAX_FILENAME_LEN 256
#define MAX_JSON_LEN 512
#define MAX_SERVER_LEN 64
#define MAX_PORT_LEN 8

static volatile sig_atomic_t running = 1;
static int server_port = 80;
static char server_ip[MAX_SERVER_LEN];

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int create_capture_dir(void) {
    struct stat st;
    if (stat(CAPTURE_DIR, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: %s exists but is not a directory\n", CAPTURE_DIR);
        return -1;
    }
    if (errno != ENOENT) {
        fprintf(stderr, "Error: stat(%s) failed: %s\n", CAPTURE_DIR, strerror(errno));
        return -1;
    }
    if (mkdir(CAPTURE_DIR, 0755) != 0) {
        fprintf(stderr, "Error: mkdir(%s) failed: %s\n", CAPTURE_DIR, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
        "libcamera-still -o %s --width 640 --height 480 --quality 85", filename);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: command buffer too small\n");
        return -1;
    }

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error: system() failed: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: libcamera-still exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

static int send_motion_data(const char *filename, const char *timestamp, int motion_detected, int gpio_pin) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error: curl_easy_init() failed\n");
        return -1;
    }

    char json_data[MAX_JSON_LEN];
    int ret = snprintf(json_data, sizeof(json_data),
        "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_detected\": %d, \"gpio_pin\": %d}",
        filename, timestamp, motion_detected, gpio_pin);
    if (ret < 0 || (size_t)ret >= sizeof(json_data)) {
        fprintf(stderr, "Error: JSON buffer too small\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "Error: curl_slist_append() failed\n");
        curl_easy_cleanup(curl);
