#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_MS 50
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }
    fclose(fp);
}

static int capture_image(const char *filename) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
                      "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview",
                      filename);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Command buffer too small\n");
        return -1;
    }
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "system() failed: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still failed (status=%d)\n", status);
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", PIR_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(line, "pir_motion") < 0) {
        fprintf(stderr, "Failed to request falling edge events on GPIO %d: %s\n",
                PIR_PIN, strerror(errno));
        goto cleanup;
    }

    log_event("Motion detection system started");

    while (running) {
        struct timespec ts = {0, POLL_TIMEOUT_MS * 1000000L};
        int ev = gpiod_line_event_wait(line, &ts);
        if (ev < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n", strerror(errno));
            break;
        }
        if (ev == 0) continue;

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "gpiod_line_event_read failed: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) continue;

        struct timespec debounce_ts = {0, DEBOUNCE_MS * 1000000L};
        while (running) {
            int debounced = gpiod_line_event_wait(line, &debounce_ts);
            if (debounced < 0) {
                if (errno == EINTR) continue;
                fprintf(stderr, "gpiod_line_event_wait (debounce) failed: %s\n", strerror(errno));
                break;
            }
            if (debounced == 0) break;
            struct gpiod_line_event debounced_event;
            if (gpiod_line_event_read(line, &debounced_event) < 0) {
                fprintf(stderr, "gpiod_line_event_read (debounce) failed: %s\n", strerror(errno));
                break;
            }
            if (debounced_event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) break;
        }
        if (!running) break;

        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[32];
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        if (!timeinfo) {
            fprintf(stderr, "localtime() failed\n");
            continue;
        }
        strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);

        char filename[128];
        int filename_len = snprintf(filename, sizeof(filename), "%s/%s_mmm.jpg",
                                   IMAGE_DIR, timestamp);
        if (filename_len < 0 || (size_t)filename_len >= sizeof(filename)) {
            fprintf(stderr, "Filename buffer too small\n");
            continue;
        }

        if (capture_image(filename) == 0) {
            log_event(timestamp);
        } else {
            log_event("Failed to capture image");
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    log_event("Motion detection system stopped");
    return ret;
}

