#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_GPIO 17
#define TILT_GPIO 18

#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define NEUTRAL_PULSE_WIDTH 1500
#define PWM_FREQUENCY 50
#define DELAY_MS 100

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int set_servo_angle(int gpio, int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Invalid angle %d for GPIO %d (must be 0-180)\n", angle, gpio);
        return -1;
    }
    int pulse_width = MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH)) / 180;
    if (gpioServo(gpio, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set servo on GPIO %d to pulse width %d\n", gpio, pulse_width);
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    if (gpioSetMode(PAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", PAN_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(TILT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", TILT_GPIO);
        gpioTerminate();
        return 1;
    }

    if (set_servo_angle(PAN_GPIO, 90) != 0 || set_servo_angle(TILT_GPIO, 90) != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Pan-Tilt camera mount ready. Press arrow keys to adjust angles (Ctrl+C to exit).\n");

    while (program_running) {
        int angle = 90;
        int key = getchar();

        if (key == 'w') {
            angle += 5;
            if (angle > 180) angle = 180;
        } else if (key == 's') {
            angle -= 5;
            if (angle < 0) angle = 0;
        } else if (key == 'a') {
            angle -= 5;
            if (angle < 0) angle = 0;
        } else if (key == 'd') {
            angle += 5;
            if (angle > 180) angle = 180;
        } else if (key == 'q') {
            break;
        }

        if (set_servo_angle(PAN_GPIO, angle) != 0 || set_servo_angle(TILT_GPIO, angle) != 0) {
            fprintf(stderr, "Error: Failed to set servo angle\n");
        }

        usleep(DELAY_MS * 1000);
    }

    set_servo_angle(PAN_GPIO, 90);
    set_servo_angle(TILT_GPIO, 90);
    gpioTerminate();
    return 0;
}

