    if (oled_write_command(handle, 0xAE) < 0) return -1; // Display off
    if (oled_write_command(handle, 0xD5) < 0) return -1; // Set display clock divide ratio/oscillator frequency
    if (oled_write_command(handle, 0x80) < 0) return -1; // Set display clock divide ratio/oscillator frequency
    if (oled_write_command(handle, 0xA8) < 0) return -1; // Set multiplex ratio (64 lines)
    if (oled_write_command(handle, 0x3F) < 0) return -1; // Set multiplex ratio (64 lines)
    if (oled_write_command(handle, 0xD3) < 0) return -1; // Set display offset
    if (oled_write_command(handle, 0x00) < 0) return -1; // Set display offset
    if (oled_write_command(handle, 0x40) < 0) return -1; // Set display start line
    if (oled_write_command(handle, 0x8D) < 0) return -1; // Enable charge pump
    if (oled_write_command(handle, 0x14) < 0) return -1; // Enable charge pump
    if (oled_write_command(handle, 0x20) < 0) return -1; // Set memory addressing mode
    if (oled_write_command(handle, 0x00) < 0) return -1; // Set memory addressing mode
    if (oled_write_command(handle, 0xA1) < 0) return -1; // Set segment re-map (column 127 mapped to SEG0)
    if (oled_write_command(handle, 0xC8) < 0) return -1; // Set COM output scan direction (remapped)
    if (oled_write_command(handle, 0xDA) < 0) return -1; // Set COM pins hardware configuration
    if (oled_write_command(handle, 0x12) < 0) return -1; // Set COM pins hardware configuration
    if (oled_write_command(handle, 0x81) < 0) return -1; // Set contrast control
    if (oled_write_command(handle, 0xCF) < 0) return -1; // Set contrast control
    if (oled_write_command(handle, 0xD9) < 0) return -1; // Set pre-charge period
    if (oled_write_command(handle, 0xF1) < 0) return -1; // Set pre-charge period
    if (oled_write_command(handle, 0xDB) < 0) return -1; // Set VCOMH deselect level
    if (oled_write_command(handle, 0x40) < 0) return -1; // Set VCOMH deselect level
    if (oled_write_command(handle, 0xA4) < 0) return -1; // Resume to RAM content display
    if (oled_write_command(handle, 0xA6) < 0) return -1; // Set normal display (not inverted)
    if (oled_write_command(handle, 0xAF) < 0) return -1; // Display on

