// Clear the display
int oled_clear(int handle) {
    for (int i = 0; i < OLED_HEIGHT; i++) {
        if (oled_set_cursor(handle, 0, i) < 0) return -1;
        for (int j = 0; j < OLED_WIDTH; j++) {
            if (oled_write_data(handle, 0x00) < 0) return -1;
        }
    }
    return 0;
}

// Set the cursor position
int oled_set_cursor(int handle, int x, int y) {
    if (x < 0 || x > OLED_WIDTH - 1 || y < 0 || y > OLED_HEIGHT - 1) {
        fprintf(stderr, "Error: Invalid cursor position (x=%d, y=%d)\n", x, y);
        return -1;
    }
    unsigned char cmd = 0xB0 + (y / 8); // Page address (0-7)
    if (oled_write_command(handle, cmd) < 0) return -1;
    unsigned char col = x % 16; // Column address (0-15)
    if (oled_write_command(handle, col) < 0) return -1;
    unsigned char col_high = (x / 16) + 0x10; // Column address (16-23)
    if (oled_write_command(handle, col_high) < 0) return -1;
    return 0;
}

// Write a byte to the OLED display
int oled_write_byte(int handle, unsigned char data) {
    if (i2cWriteByte(handle, data) < 0) {
        fprintf(stderr, "Error: Failed to write byte to I2C device\n");
        return -1;
    }
    return 0;
}

// Write a command to the OLED display
int oled_write_command(int handle, unsigned char command) {
    if (oled_write_byte(handle, 0x00) < 0) return -1; // Co=0, D/C#=0 (command)
    if (oled_write_byte(handle, command) < 0) return -1;
    return 0;
}

// Write data to the OLED display
int oled_write_data(int handle, unsigned char data) {
    if (oled_write_byte(handle, 0x40) < 0) return -1; // Co=0, D/C#=1 (data)
    if (oled_write_byte(handle, data) < 0) return -1;
    return 0;
}

// Display the contents of the OLED display
int oled_display(int handle) {
    for (int i = 0; i < OLED_HEIGHT; i++) {
        if (oled_set_cursor(handle, 0, i) < 0) return -1;
        for (int j = 0; j < OLED_WIDTH; j++) {
            unsigned char data;
            if (oled_read_byte(handle, &data) < 0) return -1;
            if (oled_write_data(handle, data) < 0) return -1;
        }
    }
    return 0;
}

// Draw a bitmap to the OLED display
int oled_draw_bitmap(int handle, int x, int y, const unsigned char *bitmap, int width, int height) {
    if (x < 0 || x > OLED_WIDTH - width || y < 0 || y > OLED_HEIGHT - height) {
        fprintf(stderr, "Error: Invalid bitmap position (x=%d, y=%d, width=%d, height=%d)\n", x, y, width, height);
        return -1;
    }
    for (int i = 0; i < height; i++) {
        if (oled_set_cursor(handle, x, y + i) < 0) return -1;
        for (int j = 0; j < width; j++) {
            unsigned char data = bitmap[i * width + j];
            if (oled_write_data(handle, data) < 0) return -1;
        }
    }
    return 0;
}

// Draw a character to the OLED display
int oled_draw_char(int handle, int x, int y, char c) {
    if (x < 0 || x > OLED_WIDTH - 6 || y < 0 || y > OLED_HEIGHT - 8) {
        fprintf(stderr, "Error: Invalid character position (x=%d, y=%d)\n", x, y);
        return -1;
    }
    const unsigned char *font = (unsigned char *)font5x7;
    int index = c - 32;
    if (index < 0 || index > 95) {
        fprintf(stderr, "Error: Invalid character '%c' (index=%d)\n", c, index);
        return -1;
    }
    for (int i = 0; i < 5; i++) {
        if (oled_set_cursor(handle, x + i, y) < 0) return -1;
        for (int j = 0; j < 8; j++) {
            unsigned char data = font[index * 5 + i];
            if (oled_write_data(handle, data) < 0) return -1;
        }
    }
    return 0;
}

// Draw a string to the OLED display
int oled_draw_string(int handle, int x, int y, const char *str) {
    if (x < 0 || x > OLED_WIDTH - 6 || y < 0 || y > OLED_HEIGHT - 8) {
        fprintf(stderr, "Error: Invalid string position (x=%d, y=%d)\n", x, y);
        return -1;
    }
    while (*str) {
        if (oled_draw_char(handle, x, y, *str) < 0) return -1;
        x += 6;
        str++;
    }
    return 0;
}

// Draw a number to the OLED display
int oled_draw_number(int handle, int x, int y, int num) {
    char str[16];
    snprintf(str, sizeof(str), "%d", num);
    return oled_draw_string(handle, x, y, str);
}

