    snprintf(str, sizeof(str), "Error: %s", error_msg);
    return oled_draw_string(handle, x, y, str);
}

// Read the CPU temperature from the sysfs file
int read_cpu_temp(float *temp) {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open temperature file\n");
        return -1;
    }
    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error: Failed to read temperature from file\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    *temp = temp_milli / 1000.0;
    return 0;
}

// Read the CPU usage from the proc file
int read_cpu_usage(float *usage) {
    FILE *fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open CPU usage file\n");
        return -1;
    }
    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error: Failed to read CPU usage from file\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    int user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    if (sscanf(line, "cpu  %d %d %d %d %d %d %d %d %d %d", &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error: Failed to parse CPU usage data\n");
        return -1;
    }
    long long total_time = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    if (total_time == 0) {
        fprintf(stderr, "Error: Total CPU time is zero\n");
        return -1;
    }
    *usage = (float)(user + nice + system + irq + softirq + steal + guest + guest_nice) / total_time * 100.0;
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, OLED_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C connection (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize OLED display
    if (oled_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: OLED initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Clear the display
    if (oled_clear(i2c_handle) < 0) {
        fprintf(stderr, "Error: Failed to clear OLED display\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float temp, usage;

        // Read CPU temperature
        if (read_cpu_temp(&temp) < 0) {
            fprintf(stderr, "Error: Failed to read CPU temperature, using -1000.0 C\n");
            temp = -1000.0;
        }

        // Read CPU usage
        if (read_cpu_usage(&usage) < 0) {
            fprintf(stderr, "Error: Failed to read CPU usage, using 0.0%%\n");
            usage = 0.0;
        }

        // Draw temperature and usage
        if (oled_draw_temperature(i2c_handle, 0, 0, temp) < 0) {
            fprintf(stderr, "Error: Failed to draw temperature\n");
        }
        if (oled_draw_cpu_usage(i2c_handle, 0, 16, usage) < 0) {
            fprintf(stderr, "Error: Failed to draw CPU usage\n");
        }

        // Display the contents of the OLED display
        if (oled_display(i2c_handle) < 0) {
            fprintf(stderr, "Error: Failed to display OLED contents\n");
        }

        // Wait for the specified interval
        sleep(UPDATE_INTERVAL_SEC);
    }

    // Cleanup
    oled_clear(i2c_handle);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

