#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define CALIBRATION_FACTOR 450.0
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define ENABLE 0x04
#define LCD_BACKLIGHT 0x08
#define ENABLE_PULSE_HIGH 0x04
#define ENABLE_PULSE_LOW 0x00

// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_handle = -1;

// Function prototypes
int initialize_gpio();
int initialize_i2c();
void cleanup();
void signal_handler(int signal);
void flow_sensor_callback(int gpio, int level, uint32_t tick);
void display_flow_rate(float flow_rate);
void display_volume(float volume);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP);

    return 0;
}

// Initialize I2C for LCD display
int initialize_i2c() {
    i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Initialize LCD in 4-bit mode
    // Send 4-bit initialization sequence
    i2cWriteByte(i2c_handle, 0x33);
    gpioDelay(5000); // Wait 5ms
    i2cWriteByte(i2c_handle, 0x32);
    gpioDelay(5000); // Wait 5ms
    i2cWriteByte(i2c_handle, 0x28); // Set 2 lines, 5x8 font
    gpioDelay(5000); // Wait 5ms
    i2cWriteByte(i2c_handle, 0x0C); // Display on, cursor off, blink off
    gpioDelay(5000); // Wait 5ms
    i2cWriteByte(i2c_handle, 0x06); // Entry mode: increment, no shift
    gpioDelay(5000); // Wait 5ms

    return 0;
}

// Cleanup GPIO and I2C resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

// Callback function for flow sensor
void flow_sensor_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    static int pulses = 0;

    if (level == 1) { // Rising edge
        uint32_t pulse_duration = tick - last_tick;
        pulses += (int)(pulse_duration / 1000000.0 * CALIBRATION_FACTOR); // Convert microseconds to seconds
        last_tick = tick;
    }
}

// Display flow rate on LCD
void display_flow_rate(float flow_rate) {
    char buffer[LCD_WIDTH + 1];
    snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f L/min", flow_rate);
    i2cWriteI2CBlockData(i2c_handle, LCD_CMD, buffer, strlen(buffer));
}

// Display volume on LCD
void display_volume(float volume) {
    char buffer[LCD_WIDTH + 1];
    snprintf(buffer, sizeof(buffer), "Volume: %.2f L", volume);
    i2cWriteI2CBlockData(i2c_handle, LCD_CMD, buffer, strlen(buffer));
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up flow sensor callback
    gpioSetAlertFunc(FLOW_SENSOR_GPIO, flow_sensor_callback);

    float flow_rate = 0.0;
    float volume = 0.0;
    uint32_t last_display_time = 0;

    printf("Flow sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Calculate flow rate
        flow_rate = (float)pulses / 60.0; // Convert pulses to liters per minute
        volume += flow_rate / 60.0; // Convert liters per minute to liters

        // Display flow rate and volume
        if (gpioTick() - last_display_time >= 1000000) { // Check if 1 second has elapsed
            display_flow_rate(flow_rate);
            display_volume(volume);
            last_display_time = gpioTick();
        }

        gpioDelay(100000); // Delay for 100ms
    }

    // Cleanup
    cleanup();
    printf("Flow sensor monitoring stopped.\n");

    return 0;
}

