#define LCD_CMD             0   /* Command display (bit 0) */
#define LCD_BACKLIGHT        0x08 /* Enable backlight */
#define ENABLE_PIN          0x04 /* Enable bit (4) */
#define ENABLE_PULSE_US     1

#define ANEMOMETER_GPIO     17
#define ANEMOMETER_PULSES_PER_REV 10
#define ANEMOMETER_SAMPLE_MS 500

#define SPI_CHANNEL         0
#define SPI_SPEED_HZ        1000000
#define SPI_FLAGS          0

#define ADC_CHANNEL         0
#define ADC_MAX_VALUE       1023
#define ADC_VREF            3.3
#define WIND_SPEED_PER_PULSE 0.5f   /* m/s per pulse */

#define SAMPLE_WINDOW_MS    ANEMOMETER_SAMPLE_MS
#define SAMPLE_WINDOW_PULSES (SAMPLE_WINDOW_MS * ANEMOMETER_PULSES_PER_REV)

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_pulse_count = 0;

static int g_i2c_handle = -1;
static int g_spi_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static void anemometer_callback(int gpio, int level, uint32_t tick, void *userdata);
static int  lcd_init(void);
static int  lcd_send_byte(uint8_t byte, uint8_t mode);
static void lcd_clear(void);
static void lcd_set_cursor(int row, int col);
static void lcd_print(const char *text);
static int  read_adc(int channel);
static int  calculate_wind_direction(int adc_value);
static void display_data(float wind_speed, int wind_direction);

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Anemometer callback ------------------------ */
static void anemometer_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {
        g_pulse_count++;
    }
}

/* ----------------------------- LCD helpers -------------------------------- */
static int lcd_init(void)
{
    /*
     * MCP8574 control sequence for 4-bit mode:
     *   1. Send 0x30 (0011 0000) -> initialization sequence
     *   2. Send 0x30 (0011 0000) -> repeat
     *   3. Send 0x20 (0010 0000) -> 4-bit mode
     *   4. Send 0x28 (0010 1000) -> 4-bit, 2 lines, 5x8 font
     *   5. Send 0x0C (0000 1100) -> display on, cursor off, blink off
     *   6. Send 0x06 (0000 0110) -> entry mode: increment, no shift
     */
    uint8_t init_seq[5] = { 0x30, 0x30, 0x20, 0x28, 0x0C };

    g_i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %s\n",
                LCD_I2C_ADDR, pigpio_error(g_i2c_handle));
        return -1;
    }

    for (int i = 0; i < 5; i++) {
        if (i2cWriteByte(g_i2c_handle, init_seq[i]) < 0) {
            fprintf(stderr, "Error writing to I2C device at address 0x%02X: %s\n",
                    LCD_I2C_ADDR, pigpio_error(g_i2c_handle));
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            return -1;
        }
        gpioDelay(5000); /* 5 ms settle */
    }

    return 0;
}

static int lcd_send_byte(uint8_t byte, uint8_t mode)
{
    uint8_t data = (byte & 0xF0) | (mode | LCD_BACKLIGHT);
    uint8_t enable_data = (data | ENABLE_PIN) & 0xF0;
    uint8_t enable_command = (data | ENABLE_PIN) & 0xF0;

    if (i2cWriteByte(g_i2c_handle, enable_data) < 0) {
        fprintf(stderr, "Error writing to I2C device at address 0x%02X: %s\n",
                LCD_I2C_ADDR, pigpio_error(g_i2c_handle));
        return -1;
    }
    gpioDelay(ENABLE_PULSE_US);
    if (i2cWriteByte(g_i2c_handle, data) < 0) {
        fprintf(stderr, "Error writing to I2C device at address 0x%02X: %s\n",
                LCD_I2C_ADDR, pigpio_error(g_i2c_handle));
        return -1;
    }
    gpioDelay(ENABLE_PULSE_US);
    if (i2cWriteByte(g_i2c_handle, enable_command) < 0) {
        fprintf(stderr, "Error writing to I2C device at address 0x%02X: %s\n",
                LCD_I2C_ADDR, pigpio_error(g_i2c_handle));
        return -1;
    }
    gpioDelay(ENABLE_PULSE_US);

    return 0;
}

static void lcd_clear(void)
{
    lcd_send_byte(0x01, LCD_CMD);
    gpioDelay(2000); /* 2 ms clear delay */
}

static void lcd_set_cursor(int row, int col)
{
    uint8_t addr;
    if (row == 0) {
        addr = 0x80 + col;
    } else {
        addr = 0xC0 + col;
    }
    lcd_send_byte(addr, LCD_CMD);
}

static void lcd_print(const char *text)
{
    for (int i = 0; text[i] != '\0'; i++) {
        lcd_send_byte((uint8_t)text[i], LCD_CHR);
    }
}

/* ----------------------------- ADC helpers -------------------------------- */
static int read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read sequence (3 bytes):
     *   Byte 0: 0x01 (start bit)
     *   Byte 1: (0x08 | channel) << 4 (single-ended + channel)
     *   Byte 2: 0x00 (don't care)
     * Result: 10-bit value in bits 9..0 of rx[1] (lower 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed: returned %d\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ----------------------------- Wind direction ----------------------------- */
static int calculate_wind_direction(int adc_value)
{
    if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }

    /*
     * MCP3008 is 10-bit ADC.
     * 0..1023 maps to 0..359 degrees.
     * Channel 0 maps to 0 degrees, channel 7 to 359 degrees.
     */
    float angle = ((float)adc_value / (float)ADC_MAX_VALUE) * 360.0f;
    return (int)(angle + 0.5f);
}

/* ----------------------------- Data display ----------------------------- */
static void display_data(float wind_speed, int wind_direction)
{
    char buffer[32];

    lcd_clear();

    snprintf(buffer, sizeof(buffer), "Wind Speed: %.1f m/s", wind_speed);
    lcd_set_cursor(0, 0);
    lcd_print(buffer);

    snprintf(buffer, sizeof(buffer), "Wind Dir: %d deg", wind_direction);
    lcd_set_cursor(1, 0);
    lcd_print(buffer);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize SPI for MCP3008 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED_HZ, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", pigpio_error(g_spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize LCD */
    if (lcd_init() != 0) {
        fprintf(stderr, "LCD initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set up anemometer interrupt */
    if (gpioSetMode(ANEMOMETER_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", ANEMOMETER_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ANEMOMETER_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", ANEMOMETER_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFuncEx(ANEMOMETER_GPIO, anemometer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d\n", ANEMOMETER_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Wind speed and direction monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int adc_value = read_adc(ADC_CHANNEL);

        if (adc_value < 0) {
            fprintf(stderr, "ADC read error — skipping sample\n");
            gpioDelay(SAMPLE_WINDOW_MS * 1000);
            continue;
        }

        /* Sensor-absent / fault detection */
        if (adc_value == 0 || adc_value == ADC_MAX_VALUE) {
            fprintf(stderr, "Warning: ADC reading at extreme (%d). Sensor may be disconnected.\n",
                    adc_value);
        }

        int wind_direction = calculate_wind_direction(adc_value);
        if (wind_direction < 0) {
            fprintf(stderr, "Wind direction calculation error — skipping sample\n");
            gpioDelay(SAMPLE_WINDOW_MS * 1000);
            continue;
        }

        float wind_speed = (float)g_pulse_count * WIND_SPEED_PER_PULSE;
        g_pulse_count = 0;

        display_data(wind_speed, wind_direction);

        gpioDelay(SAMPLE_WINDOW_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

