#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

// Configuration
#define FLOW_SENSOR_GPIO 17
#define CALIBRATION_FACTOR 7.5
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0

// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_handle = -1;

// Function prototypes
int initialize_gpio();
int initialize_i2c();
void lcd_init();
void lcd_send_byte(int bits, int mode);
void lcd_string(const char *string);
void lcd_clear();
void lcd_set_cursor(int row, int col);
void flow_sensor_callback(int gpio, int level, uint32_t tick);
float calculate_flow_rate(int pulses, float calibration_factor);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP);

    return 0;
}

// Initialize I2C for LCD
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Initialize LCD display
void lcd_init() {
    // Wait for LCD to be ready (max 40ms)
    gpioDelay(50000);

    // Send initialization commands
    lcd_send_byte(0x33, LCD_CMD);
    gpioDelay(5000);
    lcd_send_byte(0x32, LCD_CMD);
    gpioDelay(150);
    lcd_send_byte(0x28, LCD_CMD); // 2 lines, 5x8 font
    gpioDelay(150);
    lcd_send_byte(0x0C, LCD_CMD); // Display on, cursor off, blink off
    gpioDelay(150);
    lcd_send_byte(0x06, LCD_CMD); // Entry mode: increment, no shift
    gpioDelay(150);
    lcd_clear();
}

// Send byte to LCD (high nibble first)
void lcd_send_byte(int bits, int mode) {
    int high_nibble = (bits & 0xF0) | mode;
    int low_nibble = (bits << 4) | mode;

    gpioWrite(LCD_RS, mode);
    gpioWrite(LCD_D4, (high_nibble >> 4) & 1);
    gpioWrite(LCD_D5, (high_nibble >> 5) & 1);
    gpioWrite(LCD_D6, (high_nibble >> 6) & 1);
    gpioWrite(LCD_D7, (high_nibble >> 7) & 1);
    gpioDelay(1);
    gpioWrite(LCD_EN, 1);
    gpioDelay(1);
    gpioWrite(LCD_EN, 0);
    gpioDelay(1);

    gpioWrite(LCD_D4, (low_nibble >> 4) & 1);
    gpioWrite(LCD_D5, (low_nibble >> 5) & 1);
    gpioWrite(LCD_D6, (low_nibble >> 6) & 1);
    gpioWrite(LCD_D7, (low_nibble >> 7) & 1);
    gpioDelay(1);
    gpioWrite(LCD_EN, 1);
    gpioDelay(1);
    gpioWrite(LCD_EN, 0);
    gpioDelay(1);
}

// Send string to LCD
void lcd_string(const char *string) {
    while (*string) {
        lcd_send_byte((int)*string, LCD_CHR);
        string++;
    }
}

// Clear LCD display
void lcd_clear() {
    lcd_send_byte(0x01, LCD_CMD);
    gpioDelay(2000);
}

// Set LCD cursor position
void lcd_set_cursor(int row, int col) {
    int addr;
    if (row == 0) {
        addr = col;
    } else {
        addr = col + 0x40;
    }
    lcd_send_byte(addr | 0x80, LCD_CMD);
}

// Flow sensor callback function
void flow_sensor_callback(int gpio, int level, uint32_t tick) {
    static int pulse_count = 0;
    static uint32_t last_tick = 0;

    if (level == 1) {
        pulse_count++;
    }

    if (tick - last_tick > 1000000) { // 1 second
        float flow_rate = calculate_flow_rate(pulse_count, CALIBRATION_FACTOR);
        char flow_rate_string[16];
        snprintf(flow_rate_string, sizeof(flow_rate_string), "Flow Rate: %.2f L/min", flow_rate);

        lcd_clear();
        lcd_set_cursor(0, 0);
        lcd_string(flow_rate_string);

        pulse_count = 0;
        last_tick = tick;
    }
}

// Calculate flow rate from pulse count
float calculate_flow_rate(int pulses, float calibration_factor) {
    return (float)pulses / calibration_factor;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    lcd_init();

    // Set up flow sensor callback
    if (gpioSetAlertFunc(FLOW_SENSOR_GPIO, flow_sensor_callback) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", FLOW_SENSOR_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        sleep(1);
    }

    // Cleanup
    gpioSetAlertFunc(FLOW_SENSOR_GPIO, NULL);
    lcd_clear();
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

