#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define MLX75031_ADDR 0x4C
#define DISTANCE_REG 0x0D
#define LOG_FILE "depth_log.csv"
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d, addr 0x%02X: %s\n",
                I2C_BUS, MLX75031_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(uint16_t *distance) {
    char reg = (char)DISTANCE_REG;
    char buf[2];

    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n",
                DISTANCE_REG, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
        return -1;
    }

    *distance = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int log_data(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%u\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX75031 distance logger started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t distance;

        if (read_distance(&distance) == 0) {
            if (log_data(distance) != 0) {
                fprintf(stderr, "Logging failed, attempting to re-initialize I2C.\n");
                i2cClose(i2c_handle);
                i2c_handle = -1;
                if (init_i2c() != 0) {
                    fprintf(stderr, "Re-initialization failed, exiting.\n");
                    break;
                }
            }
        } else {
            fprintf(stderr, "Failed to read distance, attempting to re-initialize I2C.\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            if (init_i2c() != 0) {
                fprintf(stderr, "Re-initialization failed, exiting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

