        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX75031 distance logger started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t distance;

        if (read_distance(&distance) == 0) {
            if (log_data(distance) != 0) {
                fprintf(stderr, "Logging failed, attempting to re-initialize I2C.\n");
                i2cClose(i2c_handle);
                i2c_handle = -1;
                if (init_i2c() != 0) {
                    fprintf(stderr, "Re-initialization failed, exiting.\n");
                    break;
                }
            }
        } else {
            fprintf(stderr, "Failed to read distance, attempting to re-initialize I2C.\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            if (init_i2c() != 0) {
                fprintf(stderr, "Re-initialization failed, exiting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

