#define SI1145_HW_KEY 0x17

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(g_i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X\n", value, reg);
        return -1;
    }
    return 0;
}

static int i2c_read_byte(uint8_t reg, uint8_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(g_i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error setting register 0x%02X\n", reg);
        return -1;
    }
    char data[1];
    if (i2cReadDevice(g_i2c_handle, data, 1) != 1) {
        fprintf(stderr, "Error reading from reg 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)data[0];
    return 0;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(g_i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error setting register 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(g_i2c_handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "Error reading %u bytes from reg 0x%02X\n", len, reg);
        return -1;
    }
    return 0;
}

static int init_si1145(void) {
    uint8_t part_id = 0;
    if (i2c_read_byte(SI1145_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }

    if (i2c_write_byte(SI1145_REG_HW_KEY, SI1145_HW_KEY) != 0) {
        fprintf(stderr, "Failed to write HW_KEY\n");
        return -1;
    }

    if (i2c_write_byte(SI1145_REG_MEAS_RATE0, 0x00) != 0) return -1;
    if (i2c_write_byte(SI1145_REG_MEAS_RATE1, 0x00) != 0) return -1;

    if (i2c_write_byte(SI1145_REG_IRQ_ENABLE, 0x00) != 0) return -1;
    if (i2c_write_byte(SI1145_REG_IRQ_MODE1, 0x00) != 0) return -1;
    if (i2c_write_byte(SI1145_REG_IRQ_MODE2, 0x00) != 0) return -1;

    if (i2c_write_byte(SI1145_REG_COMMAND, 0x00) != 0) return -1;

    return 0;
}

static int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light) {
    uint8_t data[6];
    if (i2c_read_block(SI1145_REG_ALS_VIS_DATA0, data, 6) != 0) {
        return -1;
    }
    *proximity = (uint16_t)((data[1] << 8) | data[0]);
    *ambient_light = (uint16_t)((data[3] << 8) | data[2]);
    return 0;
}

static void log_data(uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(g_log_file, "%s,Proximity: %u, Ambient Light: %u\n", timestamp, proximity, ambient_light);
    fflush(g_log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    g_i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", g_i2c_handle);
        return 1;
    }

    if (init_si1145() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(g_i2c_handle);
        return 1;
    }

    g_log_file = fopen("biometric_log.txt", "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        i2cClose(g_i2c_handle);
        return 1;
    }

    printf("Biometric data logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t proximity = 0, ambient_light = 0;
        if (read_sensor_data(&proximity, &ambient_light) == 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(500000);
    }

    printf("\nShutting down...\n");
    if (g_log_file) {
        fclose(g_log_file);
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

