#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_PIN 4
#define LED_PIN 17
#define CHIP_NAME "gpiochip4"
#define LOG_FILE "proximity.log"
#define POLL_INTERVAL_MS 100
#define BLINK_DURATION_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        fprintf(stderr, "Error converting time to UTC\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            fprintf(stderr, "Error opening GPIO chip '%s': %s\n", CHIP_NAME, strerror(errno));
            return EXIT_FAILURE;
        }
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Error getting sensor line %d: %s\n", SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line %d: %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor_line, "proximity-sensor") < 0) {
        fprintf(stderr, "Error requesting sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "proximity-led", 0) < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    int last_state = 1;  /* assume no object initially (HIGH) */

    while (program_running) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
            break;
        }

        /* Detect falling edge: HIGH -> LOW (object entering range) */
        if (sensor_value == 0 && last_state == 1) {
            if (gpiod_line_set_value(led_line, 1) < 0) {
                fprintf(stderr, "Error turning on LED: %s\n", strerror(errno));
                break;
            }

            if (log_event("Object detected") < 0) {
                fprintf(stderr, "Warning: failed to log event\n");
            }

            usleep(BLINK_DURATION_MS * 1000);

            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Error turning off LED: %s\n", strerror(errno));
                break;
            }
        }

        last_state = sensor_value;
        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Proximity sensor monitoring stopped.\n");
    return ret;
}

