#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SI1145_ADDR 0x60
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_CH_LIST 0x4F
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_PS1_DATA0 0x18
#define SI1145_REG_PS1_DATA1 0x19
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_COMMAND 0x30
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PS_FORCE 0x07
#define SI1145_PART_ID 0x45
#define I2C_BUS 1

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X: %s\n", value, reg, strerror(errno));
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_reg16(uint8_t reg_low, uint16_t *value) {
    uint8_t low, high;
    if (read_reg(reg_low, &low) < 0) return -1;
    if (read_reg(reg_low + 1, &high) < 0) return -1;
    *value = (uint16_t)((high << 8) | low);
    return 0;
}

static int init_si1145(void) {
    uint8_t part_id;
    if (read_reg(SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor may be absent or bus error\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }
    if (write_reg(SI1145_REG_HW_KEY, 0x17) < 0) return -1;
    if (write_reg(SI1145_REG_CH_LIST, 0x17) < 0) return -1;
    if (write_reg(SI1145_REG_MEAS_RATE0, 0x0A) < 0) return -1;
    if (write_reg(SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;
    return 0;
