        strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", tstruct);
        fprintf(log_fp, "%s, Time to water the plant!\n", buf);
        fflush(log_fp);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    printf("Plant watering reminder started. Press Ctrl+C to exit.\n");

    while (running) {
        if (trigger_sensor() < 0) {
            log_data(0.0f, 1);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        long long pulse_us = measure_echo_pulse();
        if (pulse_us < 0) {
            log_data(0.0f, 1);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        float distance = calculate_distance(pulse_us);

        if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
            log_data(0.0f, 1);
        } else {
            log_data(distance, 0);
            check_watering_threshold(distance);
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

