static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Initialize the VL53L0X sensor */
static int init_vl53l0x(int handle) {
    /* Verify sensor presence by reading the model ID register */
    int model_id = i2cReadByteData(handle, 0x010F);
    if (model_id < 0) {
        fprintf(stderr, "Error: Failed to read model ID from VL53L0X (pigpio error %d).\n", model_id);
        return -1;
    }
    printf("VL53L0X detected (model ID: 0x%02X).\n", model_id);

    /* Set measurement timing budget to 20 ms (0x000A) */
    if (i2cWriteByteData(handle, 0x0089, 0x0A) < 0) {
        fprintf(stderr, "Error: Failed to set timing budget.\n");
        return -1;
    }

    /* Set inter-measurement period to 100 ms (0x000B) */
    if (i2cWriteByteData(handle, 0x008A, 0x0B) < 0) {
        fprintf(stderr, "Error: Failed to set inter-measurement period.\n");
        return -1;
    }

