#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define CH101_ADDR     0x45
#define TRIGGER_CMD    0x01
#define MEASURE_DELAY_US 50000   /* 50 ms */
#define SAMPLE_DELAY_US 200000  /* 200 ms */
#define LOG_FILE       "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single command byte to the CH101                          */
/* ------------------------------------------------------------------ */
static int ch101_write_cmd(int handle, uint8_t cmd)
{
    int rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x%02X) failed: %d\n",
                cmd, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 2 bytes from the CH101 — distance MSB first                     */
/* ------------------------------------------------------------------ */
static int ch101_read_distance(int handle, uint16_t *distance_mm)
{
    char buf[2];
    int rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 2)\n", rc);
        return -1;
    }
    *distance_mm = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Format current local time as YYYY-MM-DD HH:MM:SS                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo);
}

/* ------------------------------------------------------------------ */
/* Append one CSV line to the log file                                 */
/* ------------------------------------------------------------------ */
static int log_distance(FILE *fp, const char *timestamp, uint16_t distance_mm)
{
    if (fprintf(fp, "%s, %u\n", timestamp, distance_mm) < 0) {
        perror("[ERROR] fprintf to log file");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("[ERROR] fflush log file");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources                                               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    char timestamp[32];

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus to CH101 --- */
    g_i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, CH101_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("CH101 distance logger started. Logging to '%s'.\n", LOG_FILE);
    printf("Press Ctrl-C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        /* Trigger a measurement */
        if (ch101_write_cmd(g_i2c_handle, TRIGGER_CMD) != 0) {
            fprintf(stderr, "[WARN] Trigger command failed; skipping sample.\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        /* Wait for measurement to complete */
        gpioDelay(MEASURE_DELAY_US);

        /* Read distance */
        uint16_t distance_mm = 0;
        if (ch101_read_distance(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "[WARN] Distance read failed; skipping sample.\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        /* Get timestamp */
        get_timestamp(timestamp, sizeof(timestamp));

        /* Log to file */
        if (log_distance(g_log_file, timestamp, distance_mm) != 0) {
            fprintf(stderr, "[WARN] Logging failed; continuing.\n");
        }

        /* Print to console */
        printf("%s, %u mm\n", timestamp, distance_mm);

        /* Wait before next sample */
        gpioDelay(SAMPLE_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

