#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define ICU20201_ADDR 0x6A
#define LED_GPIO 17
#define DISTANCE_THRESHOLD 20.0f
#define LOG_FILE "distance_log.txt"
#define POLL_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d, addr 0x%02X: %d\n",
                I2C_BUS, ICU20201_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_GPIO);
        return -1;
    }
    gpioWrite(LED_GPIO, 0);
    return 0;
}

static int read_distance(float *distance) {
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading distance data: expected 2 bytes, got %d\n", bytes_read);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *distance = (float)raw / 100.0f;
    return 0;
}

static void log_distance(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }
    fprintf(fp, "%s, Distance: %.2f cm\n", timestamp, distance);
    fclose(fp);
}

static void control_led(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICU-20201 distance monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float distance;
        if (read_distance(&distance) == 0) {
            log_distance(distance);
            control_led(distance);
        } else {
            fprintf(stderr, "Failed to read distance, retrying...\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

