#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ICU-20201 I2C address (SA0 tied to GND) */
#define ICU20201_ADDR 0x6A

/* ICU-20201 register addresses */
#define REG_WHO_AM_I 0x00
#define REG_DISTANCE_MSB 0x02
#define REG_DISTANCE_LSB 0x03
#define REG_THRESHOLD 0x04
#define REG_CONFIG 0x05

/* Expected WHO_AM_I value for ICU-20201 */
#define ICU20201_WHO_AM_I 0x20

/* GPIO pin for LED */
#define LED_GPIO 17

/* Default threshold in mm */
#define DEFAULT_THRESHOLD 100

/* Global variables for cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Function to initialize the ICU-20201 sensor */
static int initialize_sensor(int handle) {
    int who_am_i = i2cReadByteData(handle, REG_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }

    if (who_am_i != ICU20201_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n",
                ICU20201_WHO_AM_I, who_am_i);
        return -1;
    }

    /* Set threshold to default value */
    if (i2cWriteByteData(handle, REG_THRESHOLD, DEFAULT_THRESHOLD) < 0) {
        fprintf(stderr, "Error writing threshold register\n");
        return -1;
    }

    /* Configure sensor: enable distance measurement */
    if (i2cWriteByteData(handle, REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error writing CONFIG register\n");
        return -1;
    }

    return 0;
}

/* Function to read distance from the ICU-20201 sensor */
static int read_distance(int handle, uint16_t *distance) {
    int msb = i2cReadByteData(handle, REG_DISTANCE_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading distance MSB: %d\n", msb);
        return -1;
    }

    int lsb = i2cReadByteData(handle, REG_DISTANCE_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error reading distance LSB: %d\n", lsb);
        return -1;
    }

    *distance = ((uint16_t)msb << 8) | (uint16_t)lsb;
    return 0;
}

/* Function to log distance data to a file */
static int log_distance(uint16_t distance) {
    FILE *fp = fopen("tof_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Distance: %u mm\n", timestamp, distance);
    fclose(fp);
    return 0;
}

/* Function to control the LED based on distance */
static void control_led(uint16_t distance, int threshold) {
    if (distance < threshold) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;

    /* Parse command-line argument for threshold */
    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold value. Using default: %d mm\n", DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        }
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO 17 as output and ensure LED is off initially */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus 1 at the ICU-20201 address */
    i2c_handle = i2cOpen(1, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize the ICU-20201 sensor */
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("ICU-20201 distance monitoring started. Threshold: %d mm. Press Ctrl+C to exit.\n", threshold);

    /* Main loop */
    while (!terminate) {
        uint16_t distance;

        if (read_distance(i2c_handle, &distance) == 0) {
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Error logging distance\n");
            }
            control_led(distance, threshold);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(50000); /* 50 ms delay */
    }

    /* Cleanup */
