#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define B5L_LD50_ADDR 0x50
#define DISTANCE_THRESHOLD 1000
#define NUM_SAMPLES 10
#define SAMPLE_DELAY_MS 100
#define MEASUREMENT_DELAY_MS 10
#define RESPONSE_SIZE 15
#define HEADER_BYTE 0x50

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int i2c_write_cmd(uint8_t cmd1, uint8_t cmd2, uint8_t cmd3, uint8_t cmd4) {
    uint8_t buf[4] = {cmd1, cmd2, cmd3, cmd4};
    if (write(i2c_fd, buf, 4) != 4) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_response(uint8_t *buf, size_t len) {
    ssize_t n = read(i2c_fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(int *distance_mm) {
    uint8_t cmd[4] = {0x50, 0x0A, 0x00, 0x01};
    uint8_t resp[RESPONSE_SIZE];

    if (i2c_write_cmd(cmd[0], cmd[1], cmd[2], cmd[3]) < 0) {
        return -1;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000);

    if (i2c_read_response(resp, RESPONSE_SIZE) < 0) {
        return -1;
    }

    if (resp[0] != HEADER_BYTE) {
        fprintf(stderr, "Invalid header byte: 0x%02X (expected 0x%02X)\n", resp[0], HEADER_BYTE);
        return -1;
    }

    uint16_t raw = ((uint16_t)resp[11] << 8) | resp[12];
    *distance_mm = (int)raw;
    return 0;
}

static void log_intrusion(int distance_mm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Intrusion detected! Distance: %d mm\n", timestamp, distance_mm);
    fflush(log_file);
    printf("%s - Intrusion detected! Distance: %d mm\n", timestamp, distance_mm);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, B5L_LD50_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", B5L_LD50_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("intrusion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sum = 0;
        int valid_samples = 0;

        for (int i = 0; i < NUM_SAMPLES; i++) {
            int distance;
            if (read_distance(&distance) == 0) {
                sum += distance;
                valid_samples++;
            } else {
                fprintf(stderr, "Failed to read distance sample %d\n", i + 1);
            }
            usleep(SAMPLE_DELAY_MS * 1000);
        }

        if (valid_samples > 0) {
            int avg_distance = sum / valid_samples;
            if (avg_distance < DISTANCE_THRESHOLD) {
                log_intrusion(avg_distance);
            }
        } else {
            fprintf(stderr, "No valid distance samples obtained in this cycle.\n");
        }

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

