#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L0X_ADDR        0x29
#define I2C_BUS             1
#define POLL_TIMEOUT_MS     100
#define SAMPLE_INTERVAL_US  500000

/* VL53L0X register addresses */
#define REG_IDENTIFICATION_MODEL_ID  0xC0
#define REG_SYSRANGE_START          0x00
#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS    0x14
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0B

#define EXPECTED_MODEL_ID 0xEE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to a VL53L0X register */
static int vl53l0x_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

/* Read a single byte from a VL53L0X register */
static int vl53l0x_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* Read a 16-bit little-endian value from two consecutive registers */
static int vl53l0x_read_reg16(int handle, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, expected 2): got %d (%s)\n",
                reg, rc, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* Initialize the VL53L0X sensor */
static int vl53l0x_init(int handle)
{
    uint8_t model_id = 0;

    /* Verify sensor presence by reading the model ID */
    if (vl53l0x_read_reg(handle, REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "VL53L0X not detected (model ID 0x%02X, expected 0x%02X)\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    /* Clear any pending interrupt so the next measurement is ready */
    if (vl53l0x_write_reg(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        return -1;
    }

    return 0;
}

/* Perform a single-shot ranging measurement */
static int vl53l0x_read_distance(int handle, uint16_t *distance)
{
    /* Start a single-shot measurement */
    if (vl53l0x_write_reg(handle, REG_SYSRANGE_START, 0x01) < 0) {
        return -1;
    }

    /* Poll RESULT_INTERRUPT_STATUS until bit 0 is set (data ready) */
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        uint8_t status = 0;
        if (vl53l0x_read_reg(handle, REG_RESULT_INTERRUPT_STATUS, &status) < 0) {
            return -1;
        }
        if (status & 0x01) {
            break;
        }
        gpioDelay(1000); /* 1 ms */
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "Timeout waiting for VL53L0X data ready\n");
        return -1;
    }

    /* Read the 16-bit distance from RESULT_RANGE_STATUS */
    if (vl53l0x_read_reg16(handle, REG_RESULT_RANGE_STATUS, distance) < 0) {
        return -1;
    }

    /* Clear the interrupt so the next measurement is ready */
    if (vl53l0x_write_reg(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        return -1;
    }

    return 0;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C device */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %s\n",
                I2C_BUS, VL53L0X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (vl53l0x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L0X distance reader started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t distance = 0;

        if (vl53l0x_read_distance(g_i2c_handle, &distance) == 0) {
            time_t rawtime;
            struct tm timeinfo;
            char timestamp[20];

            time(&rawtime);
            localtime_r(&rawtime, &timeinfo);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

            printf("%s Distance: %u mm\n", timestamp, distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: failed to read distance, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

