 * Board:  Raspberry Pi 4 Model B
 * Bus:    /dev/i2c-1  (I2C bus 1)
 * Address: 0x4C
 *
 * Reads the 16-bit distance register (0x00) and prints the
 * distance in millimetres every 500 ms.  Handles I2C errors
 * gracefully and exits cleanly on SIGINT/SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x4C
#define DISTANCE_REG   0x00
#define DISTANCE_SCALE 0.125f   /* mm per count */
#define POLL_MS        500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Write a single byte to an 8-bit register.
 * Returns 0 on success, -1 on error.
 */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit little-endian register.
 * Returns 0 on success and stores the value in *out; -1 on error.
 */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Read 2 bytes (low byte first) */
    uint8_t buf[2];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the I2C slave address */
    if (ioctl(fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MLX75030_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Verify the device is present by reading the device ID register */
    uint16_t dev_id = 0;
    if (i2c_read_reg16(fd, 0x0F, &dev_id) != 0) {
        fprintf(stderr, "MLX75030 not responding at address 0x%02X\n",
                MLX75030_ADDR);
        close(fd);
        return EXIT_FAILURE;
    }
    printf("MLX75030 detected (device ID 0x%04X)\n", dev_id);

    /* Main polling loop */
    while (g_running) {
        uint16_t distance = 0;
        if (i2c_read_reg16(fd, DISTANCE_REG, &distance) == 0) {
            float mm = (float)distance * DISTANCE_SCALE;
            printf("Distance: %.2f mm\n", mm);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read distance data; retrying next cycle\n");
        }

        /* Sleep 500 ms using nanosleep so signals are caught promptly */
        struct timespec ts = { 0, POLL_MS * 1000000L };
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && g_running) {
            /* Retry if interrupted by a signal */
        }
    }

    /* Clean shutdown */
    printf("\nExiting cleanly...\n");
    close(fd);
    return EXIT_SUCCESS;
}

