/*
 * HC-SR04 Ultrasonic Distance Sensor Reader for Raspberry Pi 3 Model B+
 * Library: pigpio (modern, actively maintained, actively developed)
 *
 * Wiring:
 *   HC-SR04 VCC -> 5V (Pin 2 or 4)
 *   HC-SR04 GND -> GND (Pin 6)
 *   HC-SR04 TRIG -> GPIO 17 (BCM, Pin 11)
 *   HC-SR04 ECHO -> GPIO 18 (BCM, Pin 12) via 1 kOhm resistor
 *
 * Note: HC-SR04 operates at 5V while the Pi GPIO is only 3.3V tolerant.
 *       A 1 kOhm resistor is recommended on the echo line for protection.
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 microseconds trigger pulse */
#define ECHO_TIMEOUT_US  200000     /* 200 ms echo timeout (microseconds) */
#define MAX_RANGE_CM     400.0      /* HC-SR04 maximum range in cm */
#define SAMPLE_PERIOD_US 1000000    /* 1 second between readings */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only, do not call pigpio functions here. */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Measure echo pulse width in microseconds.                            */
/* Returns pulse width on success, or -1 on timeout / error.           */
/* ------------------------------------------------------------------ */
static long measure_echo_pulse(void)
{
    uint32_t start_tick = 0;
    uint32_t end_tick   = 0;
    uint32_t timeout_start;

    /* Wait for echo rising edge (start of pulse) */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_start) >= ECHO_TIMEOUT_US) {
            return -1;  /* Timeout waiting for rising edge */
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (end of pulse) */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_start) >= ECHO_TIMEOUT_US) {
            return -1;  /* Timeout waiting for falling edge */
        }
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

/* ------------------------------------------------------------------ */
/* Convert pulse width (us) to distance (cm).                         */
/* Returns distance on success, or -1.0 on invalid pulse width.        */
/* ------------------------------------------------------------------ */
static double calculate_distance(long pulse_us)
{
    if (pulse_us <= 0) {
        return -1.0;
    }

    /* Speed of sound: 343 m/s = 0.0343 cm/us */
    double distance = (double)pulse_us * 0.0343 / 2.0;

    /* HC-SR04 range: 2 cm to 400 cm */
    if (distance < 2.0 || distance > MAX_RANGE_CM) {
        return -1.0;
    }

    return distance;
}

/* ------------------------------------------------------------------ */
/* Log distance with timestamp to console.                             */
/* ------------------------------------------------------------------ */
static void log_distance(double distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return;
    }

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call even if pigpio is not initialized.    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure trigger is low before terminating pigpio */
    if (gpioInitialise() >= 0) {
        gpioWrite(TRIGGER_PIN, 0);
        gpioTerminate();
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n",
                gpioInitialise());
        fprintf(stderr, "       Ensure pigpiod is not running and you have "
                        "permission to run the program.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set TRIGGER_PIN %d as output.\n",
                TRIGGER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set ECHO_PIN %d as input.\n",
                ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize TRIGGER_PIN %d low.\n",
                TRIGGER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance sensor reader started.\n");
    printf("  Trigger: GPIO %d (BCM)\n", TRIGGER_PIN);
    printf("  Echo:    GPIO %d (BCM)\n", ECHO_PIN);
    printf("  Range:   2 cm to %.0f cm\n", MAX_RANGE_CM);
    printf("  Press Ctrl+C to exit.\n\n");

    /* Main sampling loop */
    while (g_running) {
        /* Send 10 microsecond trigger pulse */
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Warning: Failed to set TRIGGER_PIN high.\n");
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Warning: Failed to set TRIGGER_PIN low.\n");
        }

        long pulse_us = measure_echo_pulse();

        if (pulse_us < 0) {
            fprintf(stderr, "Error: Echo pulse measurement failed.\n");
        } else {
            double distance = calculate_distance(pulse_us);

            if (distance < 0.0) {
                fprintf(stderr, "Error: Invalid distance reading (%ld us).\n",
                        pulse_us);
            } else {
                log_distance(distance);
            }
        }

        /* Sleep for 1 second, checking g_running periodically */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    printf("Program terminated.\n");

    return EXIT_SUCCESS;
}

