        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return;
    }

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call even if pigpio is not initialized.    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure trigger is low before terminating pigpio */
    if (gpioInitialise() >= 0) {
        gpioWrite(TRIGGER_PIN, 0);
        gpioTerminate();
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n",
                gpioInitialise());
        fprintf(stderr, "       Ensure pigpiod is not running and you have "
                        "permission to run the program.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set TRIGGER_PIN %d as output.\n",
                TRIGGER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set ECHO_PIN %d as input.\n",
                ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize TRIGGER_PIN %d low.\n",
                TRIGGER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance sensor reader started.\n");
    printf("  Trigger: GPIO %d (BCM)\n", TRIGGER_PIN);
    printf("  Echo:    GPIO %d (BCM)\n", ECHO_PIN);
    printf("  Range:   2 cm to %.0f cm\n", MAX_RANGE_CM);
    printf("  Press Ctrl+C to exit.\n\n");

    /* Main sampling loop */
    while (g_running) {
        /* Send 10 microsecond trigger pulse */
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Warning: Failed to set TRIGGER_PIN high.\n");
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Warning: Failed to set TRIGGER_PIN low.\n");
        }

        long pulse_us = measure_echo_pulse();

        if (pulse_us < 0) {
            fprintf(stderr, "Error: Echo pulse measurement failed.\n");
        } else {
            double distance = calculate_distance(pulse_us);

            if (distance < 0.0) {
                fprintf(stderr, "Error: Invalid distance reading (%ld us).\n",
                        pulse_us);
            } else {
                log_distance(distance);
            }
        }

        /* Sleep for 1 second, checking g_running periodically */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    printf("Program terminated.\n");

    return EXIT_SUCCESS;
}

