    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    uint8_t magic_word[MAGIC_WORD_SIZE] = {MAGIC_WORD_0, MAGIC_WORD_1, MAGIC_WORD_2, MAGIC_WORD_3, MAGIC_WORD_4, MAGIC_WORD_5, MAGIC_WORD_6, MAGIC_WORD_7};
    uint8_t frame_buffer[FRAME_HEADER_SIZE + FRAME_DATA_SIZE];
    uint16_t range_profile[NUM_RANGE_BINS];

    while (running) {
        ssize_t bytes_read = read(uart_fd, frame_buffer, sizeof(frame_buffer));
        if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            break;
        } else if (bytes_read == 0) {
            continue;
        }

        if (bytes_read < FRAME_HEADER_SIZE) {
            continue;
        }

        if (memcmp(frame_buffer, magic_word, MAGIC_WORD_SIZE) != 0) {
            memmove(frame_buffer, frame_buffer + 1, bytes_read - 1);
            continue;
        }

        memcpy(range_profile, frame_buffer + FRAME_HEADER_SIZE, FRAME_DATA_SIZE);

        if (detect_intrusion(range_profile)) {
            log_intrusion(RANGE_RESOLUTION * NUM_RANGE_BINS);
            gpioWrite(GPIO_LED, 1);
            gpioDelay(2000000);
            gpioWrite(GPIO_LED, 0);
        }
    }

    if (uart_fd >= 0) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Intrusion detection system stopped.\n");
    return 0;
}

