#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* Configuration */
#define I2C_BUS        1
#define I2C_ADDR       0x69
#define DISTANCE_REG_H 0x31
#define DISTANCE_REG_L 0x32
#define ALERT_GPIO     17
#define DISTANCE_THRESHOLD 10.0f   /* cm */
#define SAMPLE_PERIOD_US 100000   /* 100 ms */
#define LOG_FILE       "distance_log.txt"

/* Globals for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read 16-bit distance from the ICU-20201                            */
/* Returns 0 on success, -1 on error.                                */
/* ------------------------------------------------------------------ */
static int read_distance(int handle, float *distance_cm)
{
    int high, low;

    high = i2cReadByteData(handle, DISTANCE_REG_H);
    if (high < 0) {
        fprintf(stderr, "Error reading distance high byte: %s\n",
                pigpio_error(high));
        return -1;
    }

    low = i2cReadByteData(handle, DISTANCE_REG_L);
    if (low < 0) {
        fprintf(stderr, "Error reading distance low byte: %s\n",
                pigpio_error(low));
        return -1;
    }

    uint16_t raw = ((uint16_t)high << 8) | (uint16_t)low;
    *distance_cm = (float)raw / 10.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log distance with ISO 8601 timestamp                               */
/* Returns 0 on success, -1 on error.                                */
/* ------------------------------------------------------------------ */
static int log_distance(FILE *fp, float distance_cm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(fp, "%s, Distance: %.2f cm\n", timestamp, distance_cm) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger GPIO alert if distance below threshold                       */
/* ------------------------------------------------------------------ */
static void check_threshold(float distance_cm)
{
    if (distance_cm < DISTANCE_THRESHOLD) {
        if (gpioWrite(ALERT_GPIO, 1) != 0) {
            fprintf(stderr, "Warning: failed to set alert GPIO high\n");
        }
    } else {
        if (gpioWrite(ALERT_GPIO, 0) != 0) {
            fprintf(stderr, "Warning: failed to set alert GPIO low\n");
        }
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — releases all resources                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure alert GPIO */
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", ALERT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_GPIO, 0);

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICU-20201 distance monitoring started.\n");
    printf("I2C bus %d, address 0x%02X, alert GPIO %d, threshold %.1f cm\n",
           I2C_BUS, I2C_ADDR, ALERT_GPIO, DISTANCE_THRESHOLD);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (!terminate) {
        float distance_cm;

        if (read_distance(i2c_handle, &distance_cm) == 0) {
            if (log_distance(log_file, distance_cm) != 0) {
                fprintf(stderr, "Warning: failed to log distance\n");
            }
            check_threshold(distance_cm);
        } else {
            fprintf(stderr, "Warning: failed to read distance, skipping sample\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

