#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* VL53L1X I2C address (default) */
#define VL53L1X_ADDR 0x29

/* VL53L1X register addresses */
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START       0x007
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x013
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x078
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR  0x014
#define VL53L1X_REG_SYSTEM_RESET            0x0000

/* Expected model ID */
#define VL53L1X_MODEL_ID 0xEA

/* Expected interrupt status bit */
#define VL53L1X_INT_STATUS_DATA_READY 0x01

/* Polling timeout for data-ready (100 ms) */
#define VL53L1X_DATA_READY_TIMEOUT_MS 100

/* Distance thresholds (mm) */
#define DISTANCE_THRESHOLD_STOP     300
#define DISTANCE_THRESHOLD_APPROACH 300
#define DISTANCE_THRESHOLD_SLOW     600
#define DISTANCE_THRESHOLD_CLEAR    1200

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a VL53L1X register (big-endian on wire)       */
/* ------------------------------------------------------------------ */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a VL53L1X register (big-endian on wire)      */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    char reg_buf[2];
    char data_buf[2];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 0)
        return -1;

    if (i2cReadDevice(handle, data_buf, 2) != 2)
        return -1;

    *value = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 8-bit value from a VL53L1X register                            */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_reg8(int handle, uint16_t reg, uint8_t *value)
{
    char reg_buf[2];
    char data_buf[1];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 0)
        return -1;

    if (i2cReadDevice(handle, data_buf, 1) != 1)
        return -1;

    *value = (uint8_t)data_buf[0];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Software reset                                                     */
/* ------------------------------------------------------------------ */
static int vl53l1x_reset(int handle)
{
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_RESET, 0x00) != 0)
        return -1;
    gpioDelay(2000); /* 2 ms */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Start continuous back-to-back ranging                              */
/* ------------------------------------------------------------------ */
static int vl53l1x_start_ranging(int handle)
{
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Check for data-ready and read distance                              */
/* Returns 0 on success, -1 on error, 1 if timeout                       */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    int timeout = 0;

    /* Poll interrupt status bit 0 */
    while (timeout < VL53L1X_DATA_READY_TIMEOUT_MS) {
        if (vl53l1x_read_reg8(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status) != 0)
            return -1;
        if (status & VL53L1X_INT_STATUS_DATA_READY)
            break;
        gpioDelay(1000); /* 1 ms */
        timeout++;
    }

    if (timeout >= VL53L1X_DATA_READY_TIMEOUT_MS)
        return 1; /* timeout */

    /* Read 16-bit distance (big-endian) from RESULT__RANGE_STATUS + 10 */
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS + 10, distance_mm) != 0)
        return -1;

    /* Clear interrupt by writing 0x01 to SYSTEM__INTERRUPT_CLEAR */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped distance reading to the CSV log                 */
/* ------------------------------------------------------------------ */
static int log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL)
        return -1;

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0)
        return -1;

    if (fprintf(fp, "%s,%u\n", timestamp, distance_mm) < 0)
        return -1;

    if (fflush(fp) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Determine parking guidance based on distance threshold              */
/* ------------------------------------------------------------------ */
static const char *determine_parking_guidance(uint16_t distance_mm)
{
    if (distance_mm < DISTANCE_THRESHOLD_STOP)
        return "STOP";
    if (distance_mm < DISTANCE_THRESHOLD_APPROACH)
        return "APPROACH";
    if (distance_mm < DISTANCE_THRESHOLD_SLOW)
        return "SLOW";
    return "CLEAR";
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at VL53L1X address */
    g_i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    uint16_t model_id = 0;
    if (vl53l1x_read_reg16(g_i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error: failed to read model ID register.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%04X (expected 0x%04X).\n",
                model_id, VL53L1X_MODEL_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Software reset */
    if (vl53l1x_reset(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X software reset failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start continuous back-to-back ranging */
    if (vl53l1x_start_ranging(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X start ranging failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("distance_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open distance_log.csv for appending.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,distance_mm\n");
        fflush(g_log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Parking assistance system started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        uint16_t distance_mm = 0;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance_mm);

        if (rc == 0) {
            if (log_distance(g_log_file, distance_mm) != 0) {
                fprintf(stderr, "Warning: failed to log distance.\n");
            }

            const char *guidance = determine_parking_guidance(distance_mm);
            printf("Distance: %u mm, Parking Guidance: %s\n",
                   distance_mm, guidance);
        } else if (rc == 1) {
            /* Timeout — sensor may be busy or not responding */
            fprintf(stderr, "Warning: data-ready timeout (sensor may be busy).\n");
        } else {
            fprintf(stderr, "Error: I2C read failure.\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

