/*
 * CH201 Ultrasonic ToF Sensor - Distance-Based LED Blink
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (I2C + GPIO)
 *
 * Wiring:
 *   CH201 SDA  -> GPIO 2 (I2C bus 1 SDA)
 *   CH201 SCL  -> GPIO 3 (I2C bus 1 SCL)
 *   CH201 VDD  -> 3.3 V
 *   CH201 GND  -> GND
 *   LED anode  -> GPIO 18 (via 330 Ohm resistor to 3.3 V)
 *   LED cathode -> GND
 *
 * Build:  gcc -O2 -Wall -o ch201_blink ch201_blink.c -lpigpio -lrt
 * Run:    sudo ./ch201_blink
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- CH201 I2C defaults ---- */
#define I2C_BUS          1
#define CH201_ADDR       0x45

/* ---- CH201 register addresses ---- */
#define REG_DISTANCE_MM  0x00
#define REG_LED_FREQ     0x01
#define REG_MODE         0x02

/* ---- LED GPIO ---- */
#define LED_GPIO         18

/* ---- Timing ---- */
#define SAMPLE_PERIOD_US 100000   /* 100 ms */
#define BLINK_HALF_US    50000    /* 50 ms  -> 2 Hz */
#define MAX_RETRIES      3
#define RETRY_DELAY_US   10000    /* 10 ms  */

/* ---- Distance mapping ---- */
#define MIN_DISTANCE_MM  50
#define MAX_DISTANCE_MM  500
#define MIN_FREQ_HZ      1
#define MAX_FREQ_HZ      10

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a CH201 register                              */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int ch201_write_reg(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    int rc = i2cWriteDevice(handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a CH201 register                              */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int ch201_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cWriteDevice(handle, (char *)&reg, 1);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg select=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }

    char buf[1];
    rc = i2cReadDevice(handle, buf, 1);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    *value = (uint8_t)buf[0];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in mm from the CH201                                   */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int ch201_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t value;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (ch201_read_reg(handle, REG_DISTANCE_MM, &value) == 0) {
            *distance_mm = (uint16_t)((value << 8) | value);
            return 0;
        }
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Map distance to blink frequency (Hz)                                */
/* ------------------------------------------------------------------ */
static int distance_to_frequency(uint16_t distance_mm)
{
    if (distance_mm <= MIN_DISTANCE_MM) {
        return MIN_FREQ_HZ;
    }
    if (distance_mm >= MAX_DISTANCE_MM) {
        return MAX_FREQ_HZ;
    }
    return MIN_FREQ_HZ +
           (int)(((float)(distance_mm - MIN_DISTANCE_MM) /
                  (float)(MAX_DISTANCE_MM - MIN_DISTANCE_MM)) *
                  (float)(MAX_FREQ_HZ - MIN_FREQ_HZ));
}

/* ------------------------------------------------------------------ */
/* Set LED frequency via CH201 register                               */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int set_led_frequency(int handle, int frequency_hz)
{
    if (frequency_hz < MIN_FREQ_HZ || frequency_hz > MAX_FREQ_HZ) {
        fprintf(stderr, "[ERROR] Invalid frequency %d Hz (must be %d-%d Hz)\n",
                frequency_hz, MIN_FREQ_HZ, MAX_FREQ_HZ);
        return -1;
    }
    uint8_t value = (uint8_t)(frequency_hz - MIN_FREQ_HZ);
    return ch201_write_reg(handle, REG_LED_FREQ, value);
}

/* ------------------------------------------------------------------ */
/* Blink the LED for the given duration (microseconds)                 */
/* ------------------------------------------------------------------ */
static void blink_led(int gpio, int duration_us)
{
    gpioWrite(gpio, 1);
    gpioDelay(duration_us);
    gpioWrite(gpio, 0);
    gpioDelay(duration_us);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, CH201_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("CH201 distance-based LED blink started.\n");
    printf("  I2C bus %d, address 0x%02X, LED on GPIO %d\n",
           I2C_BUS, CH201_ADDR, LED_GPIO);
    printf("  Min distance: %d mm, Max distance: %d mm\n",
           MIN_DISTANCE_MM, MAX_DISTANCE_MM);
    printf("  Min frequency: %d Hz, Max frequency: %d Hz\n",
           MIN_FREQ_HZ, MAX_FREQ_HZ);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t distance_mm;

        if (ch201_read_distance(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "[WARN] Failed to read distance after %d retries; "
                            "sensor may be absent or bus error.\n", MAX_RETRIES);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int frequency_hz = distance_to_frequency(distance_mm);

        if (set_led_frequency(g_i2c_handle, frequency_hz) != 0) {
            fprintf(stderr, "[WARN] Failed to set LED frequency to %d Hz.\n",
                    frequency_hz);
        }

        /* Half-cycle blink */
        blink_led(LED_GPIO, BLINK_HALF_US);

        /* Timestamp */
        time_t rawtime;
        struct tm timeinfo;
        char timestamp[32];
        time(&rawtime);
        localtime_r(&rawtime, &timeinfo);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

        printf("[%s] Distance: %u mm, Blink freq: %d Hz\n",
               timestamp, distance_mm, frequency_hz);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

