    uint8_t value;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (ch201_read_reg(handle, REG_DISTANCE_MM, &value) == 0) {
            *distance_mm = (uint16_t)((value << 8) | value);
            return 0;
        }
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Map distance to blink frequency (Hz)                                */
/* ------------------------------------------------------------------ */
static int distance_to_frequency(uint16_t distance_mm)
{
    if (distance_mm <= MIN_DISTANCE_MM) {
        return MIN_FREQ_HZ;
    }
    if (distance_mm >= MAX_DISTANCE_MM) {
        return MAX_FREQ_HZ;
    }
    return MIN_FREQ_HZ +
           (int)(((float)(distance_mm - MIN_DISTANCE_MM) /
                  (float)(MAX_DISTANCE_MM - MIN_DISTANCE_MM)) *
                  (float)(MAX_FREQ_HZ - MIN_FREQ_HZ));
}

/* ------------------------------------------------------------------ */
/* Set LED frequency via CH201 register                               */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int set_led_frequency(int handle, int frequency_hz)
{
    if (frequency_hz < MIN_FREQ_HZ || frequency_hz > MAX_FREQ_HZ) {
        fprintf(stderr, "[ERROR] Invalid frequency %d Hz (must be %d-%d Hz)\n",
                frequency_hz, MIN_FREQ_HZ, MAX_FREQ_HZ);
        return -1;
    }
    uint8_t value = (uint8_t)(frequency_hz - MIN_FREQ_HZ);
    return ch201_write_reg(handle, REG_LED_FREQ, value);
}

/* ------------------------------------------------------------------ */
/* Blink the LED for the given duration (microseconds)                 */
/* ------------------------------------------------------------------ */
static void blink_led(int gpio, int duration_us)
{
    gpioWrite(gpio, 1);
    gpioDelay(duration_us);
    gpioWrite(gpio, 0);
    gpioDelay(duration_us);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, CH201_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("CH201 distance-based LED blink started.\n");
    printf("  I2C bus %d, address 0x%02X, LED on GPIO %d\n",
           I2C_BUS, CH201_ADDR, LED_GPIO);
    printf("  Min distance: %d mm, Max distance: %d mm\n",
           MIN_DISTANCE_MM, MAX_DISTANCE_MM);
    printf("  Min frequency: %d Hz, Max frequency: %d Hz\n",
           MIN_FREQ_HZ, MAX_FREQ_HZ);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t distance_mm;

        if (ch201_read_distance(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "[WARN] Failed to read distance after %d retries; "
                            "sensor may be absent or bus error.\n", MAX_RETRIES);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int frequency_hz = distance_to_frequency(distance_mm);

        if (set_led_frequency(g_i2c_handle, frequency_hz) != 0) {
            fprintf(stderr, "[WARN] Failed to set LED frequency to %d Hz.\n",
                    frequency_hz);
        }

        /* Half-cycle blink */
        blink_led(LED_GPIO, BLINK_HALF_US);

        /* Timestamp */
        time_t rawtime;
        struct tm timeinfo;
        char timestamp[32];
        time(&rawtime);
        localtime_r(&rawtime, &timeinfo);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

        printf("[%s] Distance: %u mm, Blink freq: %d Hz\n",
               timestamp, distance_mm, frequency_hz);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

