#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_US 10000
#define LOG_FILE "proximity_log.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read GPIO %d\n", gpio_pin);
        return -1;
    }
    return value;
}

static int log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: gmtime failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Sensor %d: %s\n", timestamp, sensor_id, event_type) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
    }

    return 0;
}

int main(void) {
    int sensor1_state = 1;  /* assume no obstacle initially (HIGH) */
    int sensor2_state = 1;
    int last_sensor1_state = 1;
    int last_sensor2_state = 1;
    int debounce_count1 = 0;
    int debounce_count2 = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value < 0 || sensor2_value < 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        /* Debounce: ignore reads that differ from the previous state for DEBOUNCE_MS */
        if (sensor1_value != last_sensor1_state) {
            debounce_count1++;
            if (debounce_count1 >= (DEBOUNCE_MS * 1000) / POLL_INTERVAL_US) {
                sensor1_state = sensor1_value;
                debounce_count1 = 0;
            }
        } else {
            debounce_count1 = 0;
        }

        if (sensor2_value != last_sensor2_state) {
            debounce_count2++;
            if (debounce_count2 >= (DEBOUNCE_MS * 1000) / POLL_INTERVAL_US) {
                sensor2_state = sensor2_value;
                debounce_count2 = 0;
            }
        } else {
            debounce_count2 = 0;
        }

        last_sensor1_state = sensor1_state;
        last_sensor2_state = sensor2_state;

        /* Log only on state change */
        if (sensor1_state != last_sensor1_state) {
            if (log_event(1, sensor1_state == 0 ? "DETECTED" : "CLEARED") != 0) {
                fprintf(stderr, "Warning: failed to log sensor 1 event\n");
            }
        }

        if (sensor2_state != last_sensor2_state) {
            if (log_event(2, sensor2_state == 0 ? "DETECTED" : "CLEARED") != 0) {
                fprintf(stderr, "Warning: failed to log sensor 2 event\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Warning: failed to close log file: %s\n", strerror(errno));
        }
        log_file = NULL;
    }

    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

