#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x49

#define REG_DIST_HIGH  0x08
#define REG_DIST_LOW   0x09
#define REG_MEAS_STATUS 0x06
#define REG_MEAS_TRIGGER 0x04

#define MEAS_TRIGGER_CMD 0x01
#define MEAS_STATUS_BIT  0x01
#define MEAS_TIMEOUT_MS 50

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_high, uint16_t *value)
{
    uint8_t high, low;
    if (i2c_read_reg(fd, reg_high, &high) < 0)
        return -1;
    if (i2c_read_reg(fd, reg_high + 1, &low) < 0)
        return -1;
    *value = ((uint16_t)high << 8) | low;
    return 0;
}

static int trigger_measurement(int fd)
{
    if (i2c_write_reg(fd, REG_MEAS_TRIGGER, MEAS_TRIGGER_CMD) < 0)
        return -1;
    return 0;
}

static int wait_for_data_ready(int fd)
{
    uint8_t status;
    for (int i = 0; i < MEAS_TIMEOUT_MS; i++) {
        if (i2c_read_reg(fd, REG_MEAS_STATUS, &status) < 0)
            return -1;
        if (status & MEAS_STATUS_BIT)
            return 0;
        usleep(1000);
    }
    fprintf(stderr, "Timeout waiting for CH-101 data-ready\n");
    return -1;
}

static int read_distance(int fd, uint16_t *distance_mm)
{
    if (trigger_measurement(fd) < 0)
        return -1;
    if (wait_for_data_ready(fd) < 0)
        return -1;
    return i2c_read_reg16(fd, REG_DIST_HIGH, distance_mm);
}

static int log_data(FILE *fp, uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", timestamp, distance_mm) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush CSV failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                CH101_ADDR, strerror(errno));
        goto cleanup;
    }

    fp = fopen("distance_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open distance_log.csv: %s\n", strerror(errno));
        goto cleanup;
    }

    fprintf(fp, "timestamp,distance_mm\n");
    fflush(fp);

    while (g_running) {
        uint16_t distance_mm = 0;
        if (read_distance(fd, &distance_mm) < 0) {
            fprintf(stderr, "Read failed; skipping sample\n");
        } else {
            if (log_data(fp, distance_mm) < 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        }
        usleep(500000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
    }
    if (fd >= 0)
        close(fd);
    return rc;
}

