// Write a 16-bit value to a VL53L5CX register (little-endian)
int i2c_write_reg16(int fd, uint16_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "Error writing to I2C register 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

