    if (i2c_write_reg16(fd, REG_RESULT_RANGE_STATUS_SD0, 0x0001) < 0) {
        fprintf(stderr, "Failed to clear data ready bit\n");
        return -1;
    }

    return 0;
}

int main() {
    // Open I2C bus
    i2c_fd = open(I2C_BUS_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
