#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define MLX75030_ADDR 0x4C
#define I2C_BUS 1
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_distance_mm(int handle, uint16_t *distance_mm) {
    char cmd = 0x00;
    char buf[2];
    int result;

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        result = i2cWriteDevice(handle, &cmd, 1);
        if (result == 0) {
            gpioDelay(1000);
            result = i2cReadDevice(handle, buf, 2);
            if (result == 2) {
                *distance_mm = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
                return 0;
            }
        }
        fprintf(stderr, "I2C read error (attempt %d/%d): %d\n", attempt + 1, RETRY_COUNT, result);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static void log_distance(uint16_t distance_mm) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("[%s.%03ld] Distance: %u mm\n", timestamp, ts.tv_nsec / 1000000, distance_mm);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X on bus %d: %d\n",
                MLX75030_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX75030 ToF sensor reader started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t distance_mm;
        if (read_distance_mm(i2c_handle, &distance_mm) == 0) {
            log_distance(distance_mm);
        } else {
            fprintf(stderr, "Failed to read distance after %d retries.\n", RETRY_COUNT);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

