#include <pigpio.h>

#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100
#define I2C_BUS 1
#define POLL_DELAY_US 500000

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET 0x0001
#define REG_I2C_SLAVE__DEVICE_ADDRESS 0x0001
#define REG_SYSTEM__MODE_START 0x0007
#define REG_RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM 0x0096

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a 16-bit register address and a 16-bit value (big-endian on the bus) */
static int vl53l1x_write_reg16(uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(i2c_handle, buf, 4);
}

/* Read a 16-bit register address and return its 16-bit value (big-endian on the bus) */
static int vl53l1x_read_reg16(uint16_t reg, uint16_t *value) {
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(i2c_handle, addr, 2) != 0) {
        return -1;
    }
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* Initialize the VL53L1X sensor */
static int vl53l1x_init(void) {
    uint16_t soft_reset_val = 0x00;
    uint16_t mode_start_val = 0x00;
    uint16_t i2c_addr_val = VL53L1X_ADDR;

    /* Soft reset */
    if (vl53l1x_write_reg16(REG_SOFT_RESET, soft_reset_val) != 0) {
        fprintf(stderr, "Error: Failed to write soft reset register\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay for reset to complete */

    /* Set I2C slave address */
    if (vl53l1x_write_reg16(REG_I2C_SLAVE__DEVICE_ADDRESS, i2c_addr_val) != 0) {
        fprintf(stderr, "Error: Failed to write I2C slave address register\n");
        return -1;
    }

    /* Start continuous ranging mode */
    if (vl53l1x_write_reg16(REG_SYSTEM__MODE_START, mode_start_val) != 0) {
        fprintf(stderr, "Error: Failed to start continuous ranging mode\n");
        return -1;
    }

    gpioDelay(10000); /* 10 ms delay for mode to take effect */

    return 0;
}

/* Read distance from the VL53L1X sensor */
static int vl53l1x_read_distance(uint16_t *distance) {
    uint16_t raw_distance = 0;

    if (vl53l1x_read_reg16(REG_RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM, &raw_distance) != 0) {
        fprintf(stderr, "Error: Failed to read distance register\n");
        return -1;
    }

    *distance = raw_distance;
    return 0;
}

