static void buzzer_control(int state) {
    gpioWrite(BUZZER_GPIO, state);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO 22 as output and ensure it is off */
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    buzzer_control(0);

    /* Open I2C bus 1 at VL53L1X address 0x29 */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (error %d)\n",
                I2C_BUS, VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the VL53L1X sensor */
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance monitoring started. Press Ctrl+C to exit.\n");

    int buzzer_on = 0;

    while (running) {
        uint16_t distance = 0;

        if (vl53l1x_read_distance(&distance) == 0) {
            printf("Distance: %u mm\n", distance);

            if (distance < DISTANCE_THRESHOLD && !buzzer_on) {
                buzzer_control(1);
                buzzer_on = 1;
                printf("Buzzer ON\n");
            } else if (distance >= DISTANCE_THRESHOLD && buzzer_on) {
                buzzer_control(0);
                buzzer_on = 0;
                printf("Buzzer OFF\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance, re-initializing sensor...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(1000000); /* 1 second delay before retry */

            if (vl53l1x_init() != 0) {
                fprintf(stderr, "Error: Re-initialization failed, exiting...\n");
                break;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    buzzer_control(0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

