#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   17

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM          2.0
#define MAX_DISTANCE_CM          400.0
#define MIN_PULSE_US             500
#define MAX_PULSE_US             2500
#define TRIGGER_PULSE_US         10
#define ECHO_TIMEOUT_US          50000
#define LOOP_DELAY_US            200000
#define SERVO_MIN_PULSE_US       500
#define SERVO_MAX_PULSE_US       2500

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set servo pin %d as output.\n", SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize trigger pin %d low.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin high.\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin low.\n");
        return -1;
    }
    return 0;
}

static long measure_echo_pulse_us(void) {
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            return -1;
        }
    }
    start_tick = gpioTick();

    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            return -1;
        }
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

static float calculate_distance(long pulse_us) {
    if (pulse_us < 0) {
        return -1.0f;
    }
    return (float)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;
}

static int map_distance_to_angle(float distance_cm) {
    if (distance_cm < MIN_DISTANCE_CM) {
        distance_cm = MIN_DISTANCE_CM;
    }
    if (distance_cm > MAX_DISTANCE_CM) {
        distance_cm = MAX_DISTANCE_CM;
    }
    float angle = (distance_cm - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM) *
                 (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US) + SERVO_MIN_PULSE_US;
    return (int)angle;
}

static int set_servo_angle(int angle) {
    if (angle < SERVO_MIN_PULSE_US) {
        angle = SERVO_MIN_PULSE_US;
    }
    if (angle > SERVO_MAX_PULSE_US) {
        angle = SERVO_MAX_PULSE_US;
    }
    if (gpioServo(SERVO_PIN, angle) != 0) {
        fprintf(stderr, "Error: failed to set servo pulse width %d us.\n", angle);
        return -1;
    }
    return 0;
}

static void log_data(float distance_cm, int angle) {
    FILE *fp = fopen("sensor_data.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: failed to open sensor_data.log for appending.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Distance: %.2f cm, Angle: %d degrees\n", timestamp, distance_cm, angle);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (running) {
        if (trigger_sensor() != 0) {
            fprintf(stderr, "Warning: trigger failed, skipping this reading.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        long pulse_us = measure_echo_pulse_us();
        if (pulse_us < 0) {
            fprintf(stderr, "Warning: echo timeout, skipping this reading.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        float distance_cm = calculate_distance(pulse_us);
        if (distance_cm < 0) {
            fprintf(stderr, "Warning: invalid distance, skipping this reading.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int angle = map_distance_to_angle(distance_cm);
        if (set_servo_angle(angle) != 0) {
            fprintf(stderr, "Warning: servo set failed, skipping this reading.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        log_data(distance_cm, angle);
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Parking Assist System stopped.\n");
    return EXIT_SUCCESS;
}

