#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define THRESHOLD_DISTANCE_CM 30.0
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000
#define LOOP_DELAY_US 100000

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int running = 1;

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        start_tick = tick;
        echo_received = 0;
    } else if (level == 0) {
        end_tick = tick;
        echo_received = 1;
    }
}

static float calculate_distance(void) {
    if (!echo_received) {
        return -1.0f;
    }

    uint32_t diff = end_tick - start_tick;
    if (diff == 0) {
        return -1.0f;
    }

    float distance = (float)diff * SPEED_OF_SOUND_CM_PER_S / 2000000.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1.0f;
    }

    return distance;
}

static void control_buzzer(float distance) {
    if (distance < 0.0f) {
        gpioWrite(BUZZER_PIN, 0);
        return;
    }

    if (distance < THRESHOLD_DISTANCE_CM) {
        gpioWrite(BUZZER_PIN, 1);
    } else {
        gpioWrite(BUZZER_PIN, 0);
    }
}

static void cleanup(void) {
    gpioWrite(BUZZER_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize TRIGGER_PIN %d low.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize BUZZER_PIN %d low.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to set alert function for ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler.\n");
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_sensor();

        uint32_t start_wait = gpioTick();
        while (!echo_received && running) {
            if ((gpioTick() - start_wait) > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Error: echo timeout (no echo received).\n");
                break;
            }
            gpioDelay(100);
        }

        if (!running) {
            break;
        }

        float distance = calculate_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Error: invalid distance reading (%.2f cm).\n", distance);
        } else {
            printf("Distance: %.2f cm\n", distance);
        }

        control_buzzer(distance);

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    printf("Parking sensor stopped.\n");
    return EXIT_SUCCESS;
}

