#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 20
#define LOG_FILE "gate_log.txt"
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "gate_controller"

#define VL53L1X_SOFT_RESET 0x0000
#define VL53L1X_SYSTEM_START 0x0001
#define VL53L1X_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_RESULT_DISTANCE 0x0096

static int i2c_handle = -1;
static FILE *log_file = NULL;
static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) return -1;
    if (i2cReadDevice(handle, (char *)value, 1) != 1) return -1;
    return 0;
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg16(handle, VL53L1X_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_SYSTEM_START, 0x01) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int read_distance(int handle) {
    uint8_t status;
    int retries = 10;
    while (retries > 0) {
        if (i2c_read_reg16(handle, VL53L1X_RESULT_RANGE_STATUS, &status) != 0) {
            gpioDelay(10000);
            retries--;
            continue;
        }
        if ((status & 0x01) == 0) break;
        gpioDelay(10000);
        retries--;
    }
    if (retries == 0) return -1;
    uint8_t distance;
    if (i2c_read_reg16(handle, VL53L1X_RESULT_DISTANCE, &distance) != 0) return -1;
    return (distance << 8) | distance;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

static void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse_width = 500 + (angle * 2000) / 180;
    gpioServo(SERVO_PIN, pulse_width);
}

static void open_gate(void) {
    set_servo_angle(90);
    log_event("Gate opened");
}

static void close_gate(void) {
    set_servo_angle(0);
    log_event("Gate closed");
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)m; (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        mosquitto_subscribe(m, NULL, "gate_control", 0);
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m; (void)userdata;
    if (message->payloadlen > 0) {
        char *payload = malloc(message->payloadlen + 1);
        if (payload) {
            memcpy(payload, message->payload, message->payloadlen);
            payload[message->payloadlen] = '\0';
            if (strcmp(payload, "force_open") == 0) {
                open_gate();
            } else if (strcmp(payload, "force_close") == 0) {
                close_gate();
            } else if (strcmp(payload, "status_request") == 0) {
                char response[128];
                snprintf(response, sizeof(response), "Gate status: %s", (gpioRead(SERVO_PIN) == 0) ? "CLOSED" : "OPEN");
                mosquitto_publish(m, NULL, "gate_status", strlen(response), response, 0, false);
            }
            free(payload);
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

