        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    mosquitto_loop_start(mosq);

    int gate_open = 0;
    while (running) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
