/*
 * HC-SR04 ultrasonic distance measurement with pigpio.
 *
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO 23 (physical pin 16, BCM, output)
 *   HC-SR04 ECHO -> GPIO 24 (physical pin 18, BCM, input, pull-down)
 *               (5V logic level -> 3.3V Pi GPIO)
 *
 * Build:  gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24

#define SPEED_OF_SOUND_CM_PER_US 0.0343f   /* 343 m/s in cm/us */
#define TRIGGER_PULSE_US        10
#define ECHO_TIMEOUT_US         30000     /* 30 ms max echo wait */
#define MEASURE_INTERVAL_US     200000    /* 200 ms between measurements */
#define LOOP_TIMEOUT_US         60000000  /* 60 s max wait for echo */

#define LOG_FILE_NAME "distance_log.txt"

/* ------------------------------------------------------------------ */
/* Shared state between callback and main thread                       */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_rising_tick = 0;
static volatile uint32_t     g_falling_tick = 0;
static volatile bool         g_echo_seen = false;
static volatile bool         g_echo_ready = false;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Echo alert callback (runs in pigpio thread)                          */
/* ------------------------------------------------------------------ */

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_rising_tick = tick;
        g_echo_seen = false;
        g_echo_ready = false;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_falling_tick = tick;
        g_echo_seen = true;
        g_echo_ready = true;
    }
}

/* ------------------------------------------------------------------ */
/* Trigger a 10 us pulse on the TRIG pin                                */
/* ------------------------------------------------------------------ */

static void trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Compute distance in cm from pulse width in microseconds              */
/* ------------------------------------------------------------------ */

static float calculate_distance(uint32_t pulse_width_us)
{
    if (pulse_width_us == 0) {
        return -1.0f;
    }
    return (float)pulse_width_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;
}

/* ------------------------------------------------------------------ */
/* Log a reading with an ISO 8601 timestamp to stdout and the log file  */
/* ------------------------------------------------------------------ */

static void log_reading(float distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);

    FILE *fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE_NAME);
        return;
    }

    fprintf(fp, "%s, Distance: %.2f cm\n", timestamp, distance);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    /* Ensure trigger is low before releasing */
    gpioWrite(TRIGGER_PIN, 0);

    /* Disable alert callback */
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);

    /* Release pigpio resources */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register alert callback for ECHO pin */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  TRIGGER: GPIO %d (BCM)\n", TRIGGER_PIN);
    printf("  ECHO:    GPIO %d (BCM)\n", ECHO_PIN);
    printf("  Log:     %s\n", LOG_FILE_NAME);
    printf("Press Ctrl+C to exit.\n");

    uint32_t last_trigger_tick = 0;
    uint32_t loop_start_tick = 0;

    while (g_running) {
        /* Reset state for this measurement cycle */
        g_rising_tick = 0;
        g_falling_tick = 0;
        g_echo_seen = false;
        g_echo_ready = false;

        /* Trigger a measurement */
        trigger_sensor();

        /* Wait for echo to arrive or timeout */
        loop_start_tick = gpioTick();
        while (!g_echo_ready && g_running) {
            uint32_t elapsed = gpioTick() - loop_start_tick;
            if (elapsed >= LOOP_TIMEOUT_US) {
                fprintf(stderr,
                        "Warning: no echo received within %u us (timeout)\n",
                        LOOP_TIMEOUT_US);
                break;
            }
            gpioDelay(1000); /* 1 ms poll interval */
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_seen) {
            fprintf(stderr,
                    "Warning: echo not received within %u us (no object)\n",
                    ECHO_TIMEOUT_US);
            continue;
        }

        /* Compute pulse width in microseconds */
        uint32_t pulse_width_us = g_falling_tick - g_rising_tick;

        /* Validate pulse width (HC-SR04: 100 us min, 30000 us max) */
        if (pulse_width_us < 100 || pulse_width_us > 30000) {
            fprintf(stderr,
                    "Warning: pulse width %u us out of range (valid 100-30000)\n",
                    pulse_width_us);
            continue;
        }

        /* Calculate distance */
        float distance = calculate_distance(pulse_width_us);

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: invalid distance (pulse %u us)\n",
                    pulse_width_us);
            continue;
        }

        /* Log the reading */
        log_reading(distance);

        /* Wait for the next measurement cycle */
        uint32_t elapsed_since_trigger = gpioTick() - last_trigger_tick;
        if (elapsed_since_trigger < MEASURE_INTERVAL_US) {
            gpioDelay(MEASURE_INTERVAL_US - elapsed_since_trigger);
        }
        last_trigger_tick = gpioTick();
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

