#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24
#define DISTANCE_THRESHOLD_OPEN 50.0f
#define DISTANCE_THRESHOLD_CLOSE 60.0f
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_OPEN_ANGLE 150
#define SERVO_CLOSE_ANGLE 90
#define SERVO_HYSTERESIS 5
#define LOG_FILE "parking_log.txt"
#define POLL_DELAY_US 100000

// Global variables
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;
static int gate_state = 0; // 0 = closed, 1 = open

// Function prototypes
int init_gpio(void);
int init_i2c(void);
int init_vl53l1x(void);
int read_distance(float *distance);
void control_servo(int angle);
void log_event(const char *event, float distance);
void signal_handler(int signal);
void cleanup(void);

// Initialize GPIO pins
int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT);
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);

    // Set servo PWM range to 20ms (50Hz)
    gpioSetPWMrange(SERVO_PIN, 20000);

    // Ensure shutdown pin is low initially
    gpioWrite(SHUTDOWN_PIN, 0);

    return 0;
}

// Initialize I2C communication
int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Initialize VL53L1X sensor
int init_vl53l1x(void) {
    // Check sensor presence by reading model ID
    int model_id = i2cReadByteData(i2c_handle, 0x010F);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0xEA)\n", model_id);
        return -1;
    }

    // Set ranging mode to continuous
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x00) < 0) {
        fprintf(stderr, "Error setting ranging mode\n");
        return -1;
    }

    // Set measurement timing budget to 20ms (0x000A)
    if (i2cWriteByteData(i2c_handle, 0x0089, 0x0A) < 0) {
        fprintf(stderr, "Error setting measurement timing budget\n");
        return -1;
    }

    // Set inter-measurement period to 100ms (0x008B)
    if (i2cWriteByteData(i2c_handle, 0x008B, 0x64) < 0) {
        fprintf(stderr, "Error setting inter-measurement period\n");
        return -1;
    }

    // Set distance threshold to 50mm (0x008C)
    if (i2cWriteByteData(i2c_handle, 0x008C, 0x00) < 0) {
        fprintf(stderr, "Error setting distance threshold\n");
        return -1;
    }

    // Set interrupt polarity to active high (0x008D)
    if (i2cWriteByteData(i2c_handle, 0x008D, 0x01) < 0) {
        fprintf(stderr, "Error setting interrupt polarity\n");
        return -1;
    }

    // Set interrupt type to new sample (0x008E)
    if (i2cWriteByteData(i2c_handle, 0x008E, 0x01) < 0) {
        fprintf(stderr, "Error setting interrupt type\n");
        return -1;
    }

    // Set interrupt enable (0x008F)
    if (i2cWriteByteData(i2c_handle, 0x008F, 0x01) < 0) {
        fprintf(stderr, "Error setting interrupt enable\n");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(float *distance) {
    // Trigger a single measurement
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x01) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    // Wait for measurement to complete (max 100ms)
    gpioDelay(100000);

    // Read distance from result register (0x0096)
    int distance_raw = i2cReadByteData(i2c_handle, 0x0096);
    if (distance_raw < 0) {
        fprintf(stderr, "Error reading distance: %d\n", distance_raw);
        return -1;
    }

    // Convert raw distance to mm
    *distance = (float)distance_raw * 0.2f;

    return 0;
}

// Control servo motor using PWM
void control_servo(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)((float)angle / 180.0f * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    gpioServo(SERVO_PIN, pulse_width);
}

// Log events to file
void log_event(const char *event, float distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s - %s - Distance: %.2f cm\n", timestamp, event, distance);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources
void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioServo(SERVO_PIN, 0); // Stop servo PWM
    gpioTerminate();
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Smart Parking Gate System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float distance;

        if (read_distance(&distance) == 0) {
            printf("Distance: %.2f cm\n", distance);

            if (distance < DISTANCE_THRESHOLD_OPEN && gate_state == 0) {
                control_servo(SERVO_OPEN_ANGLE);
                gate_state = 1;
                log_event("Gate Opened", distance);
            } else if (distance > DISTANCE_THRESHOLD_CLOSE && gate_state == 1) {
                control_servo(SERVO_CLOSE_ANGLE);
                gate_state = 0;
                log_event("Gate Closed", distance);
            }
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    // Cleanup
    cleanup();
    printf("Smart Parking Gate System stopped.\n");

    return 0;
}

