#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_OPEN_PIN 18
#define GATE_CLOSE_PIN 19
#define DISTANCE_THRESHOLD_MM 200
#define POLL_DELAY_US 500000
#define LOG_FILE "gate_events.log"

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_SYSTEM_START 0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a 16-bit register address (big-endian) and a 16-bit value */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteI2CBlockData(handle, buf[0], &buf[2], 2);
}

/* Read a 16-bit register address (big-endian) and return its value */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    char data_buf[2];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteI2CBlockData(handle, reg_buf[0], &reg_buf[1], 1) != 0) {
        return -1;
    }

    if (i2cReadI2CBlockData(handle, reg_buf[0], data_buf, 2) != 2) {
        return -1;
    }

    *value = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* Initialize the VL53L1X sensor */
static int vl53l1x_init(int handle) {
    uint16_t model_id = 0;

    /* Soft reset */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x0001) != 0) {
        fprintf(stderr, "Error: Failed to write soft reset register\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay for reset */

    /* Read model ID to verify sensor presence */
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read model ID register\n");
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Error: Invalid model ID: 0x%04X (expected 0xEACC)\n", model_id);
        return -1;
    }

    /* Set timing budget to 20 ms (0x000A) */
    if (vl53l1x_write_reg16(handle, 0x000A, 0x000A) != 0) {
        fprintf(stderr, "Error: Failed to set timing budget\n");
        return -1;
    }

    /* Start ranging */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x0001) != 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }

    return 0;
}

/* Read distance from the VL53L1X sensor */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm) {
    uint16_t status = 0;

    /* Poll for data ready (bit 0 of RESULT_RANGE_STATUS) */
    for (int i = 0; i < 100; i++) {
        if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) != 0) {
            return -1;
        }
        if (status & 0x0001) {
            break;
        }
        gpioDelay(1000); /* 1 ms */
    }

    if (!(status & 0x0001)) {
        return -1; /* Timeout waiting for data ready */
    }

    /* Read distance */
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, distance_mm) != 0) {
        return -1;
    }

    /* Clear interrupt by writing 0x01 to SYSTEM_START */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x0001) != 0) {
        return -1;
    }

    return 0;
}

/* Log an event with an ISO 8601 UTC timestamp */
static void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", timestamp, event);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main(void) {
    int distance_mm = 0;
    int gate_open = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO pins as outputs */
    gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT);
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 1);

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d\n", VL53L1X_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize VL53L1X sensor */
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
