#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29

#define MOTOR_FORWARD  17
#define MOTOR_BACKWARD 18
#define GPIO_TRIGGER   24

#define DISTANCE_THRESHOLD_LOW  100   /* mm */
#define DISTANCE_THRESHOLD_HIGH 300   /* mm */
#define POLL_TIMEOUT_MS        1000
#define POLL_INTERVAL_US       10000  /* 10 ms */
#define MAX_RETRIES            3
#define RETRY_DELAY_US         100000 /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a VL53L1X register                          */
/* ------------------------------------------------------------------ */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    int rc = i2cWriteDevice(handle, buf, 3);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%04X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a VL53L1X register                          */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *value)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    int rc = i2cWriteDevice(handle, reg_buf, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%04X) failed: %d\n", reg, rc);
        return -1;
    }

    rc = i2cReadDevice(handle, (char *)value, 1);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%04X) failed: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance from VL53L1X                                         */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle, uint16_t *distance)
{
    uint8_t status = 0;
    int retries = 0;

    /* Soft reset */
    if (vl53l1x_write_reg16(handle, 0x0000, 0x00) < 0)
        return -1;
    gpioDelay(1000); /* 1 ms */

    /* Start measurement */
    if (vl53l1x_write_reg16(handle, 0x0000, 0x01) < 0)
        return -1;

    /* Poll data-ready bit (bit 0 of register 0x0089) */
    while (retries < MAX_RETRIES) {
        if (vl53l1x_read_reg16(handle, 0x0089, &status) < 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(POLL_INTERVAL_US);
        retries++;
    }

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "[ERROR] VL53L1X data-ready timeout\n");
        return -1;
    }

    /* Read 16-bit distance (registers 0x0096-0x0097) */
    uint8_t low = 0, high = 0;
    if (vl53l1x_read_reg16(handle, 0x0096, &low) < 0)
        return -1;
    if (vl53l1x_read_reg16(handle, 0x0097, &high) < 0)
        return -1;

    *distance = ((uint16_t)high << 8) | low;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Motor control                                                      */
/* ------------------------------------------------------------------ */
static void motor_forward(void)
{
    gpioWrite(MOTOR_FORWARD, 1);
    gpioWrite(MOTOR_BACKWARD, 0);
}

static void motor_backward(void)
{
    gpioWrite(MOTOR_FORWARD, 0);
    gpioWrite(MOTOR_BACKWARD, 1);
}

static void motor_stop(void)
{
    gpioWrite(MOTOR_FORWARD, 0);
    gpioWrite(MOTOR_BACKWARD, 0);
}

/* ------------------------------------------------------------------ */
/* ISR callback for GPIO24 (rising edge)                                */
/* ------------------------------------------------------------------ */
static void trigger_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;

    uint16_t distance = 0;
    int rc = vl53l1x_read_distance(g_i2c_handle, &distance);

    if (rc == 0) {
        printf("Distance: %u mm\n", distance);

        if (distance < DISTANCE_THRESHOLD_LOW) {
            motor_forward();
        } else if (distance > DISTANCE_THRESHOLD_HIGH) {
            motor_backward();
        } else {
            motor_stop();
        }
    } else {
        fprintf(stderr, "[ERROR] Failed to read distance\n");
        motor_stop();
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    motor_stop();
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure motor pins */
    if (gpioSetMode(MOTOR_FORWARD, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_BACKWARD, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode failed for motor pins\n");
        cleanup();
        return EXIT_FAILURE;
    }
    motor_stop();

    /* Configure trigger pin */
    if (gpioSetMode(GPIO_TRIGGER, PI_INPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode failed for trigger pin\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_UP);

    /* Register ISR for rising edge on GPIO24 */
    if (gpioSetISRFuncEx(GPIO_TRIGGER, RISING_EDGE, 0, trigger_isr, NULL) < 0) {
        fprintf(stderr, "[FATAL] gpioSetISRFuncEx failed for trigger pin\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance sensor running. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

