#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define MPR121_ADDR 0x5A
#define I2C_BUS "/dev/i2c-1"
#define GPIO_CHIP "gpiochip0"
#define LED_PINS {17, 18, 27, 22}
#define NUM_LEDS 4
#define POLL_INTERVAL_MS 50

#define MHD_R 0x2B
#define NHDR_R 0x2C
#define NCLR_R 0x2D
#define FDLR_R 0x2E
#define ELECONFIG0_R 0x5E
#define ELECONFIG1_R 0x5F
#define TOUCHSTATUS_L_R 0x00
#define TOUCHSTATUS_H_R 0x01
#define ECR_R 0x5E
#defineSOFTRESET_R 0x80
#define ECR_ELEPROX_EN 0x01
#define ECR_ELE_EN 0x0C

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_lines[NUM_LEDS];
static int led_pins[NUM_LEDS] = LED_PINS;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    uint8_t whoami;
    if (i2c_read_reg(0x5E, &whoami) < 0) {
        fprintf(stderr, "MPR121 not responding at 0x%02X\n", MPR121_ADDR);
        return -1;
    }
    if (whoami != 0x41) {
        fprintf(stderr, "Unexpected WHO_AM_I: 0x%02X (expected 0x41)\n", whoami);
        return -1;
    }

    if (i2c_write_reg(SOFTRESET_R, 0x63) < 0) return -1;
    usleep(10000);

    if (i2c_write_reg(ECR_R, ECR_ELEPROX_EN) < 0) return -1;
    if (i2c_write_reg(ECR_R, ECR_ELE_EN) < 0) return -1;

    if (i2c_write_reg(MHD_R, 0x01) < 0) return -1;
    if (i2c_write_reg(NHDR_R, 0x01) < 0) return -1;
    if (i2c_write_reg(NCLR_R, 0x0E) < 0) return -1;
    if (i2c_write_reg(FDLR_R, 0x00) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (i2c_write_reg(0x5A + 2 * i, 0x0B) < 0) return -1;
        if (i2c_write_reg(0x5B + 2 * i, 0xC8) < 0) return -1;
    }

    return 0;
}

static int read_touch_status(uint16_t *status) {
    uint8_t lo, hi;
    if (i2c_read_reg(TOUCHSTATUS_L_R, &lo) < 0) return -1;
    if (i2c_read_reg(TOUCHSTATUS_H_R, &hi) < 0) return -1;
    *status = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void set_led_pattern(int pattern) {
    for (int i = 0; i < NUM_LEDS; i++) {
        if (gpiod_line_set_value(led_lines[i], (pattern >> i) & 1) < 0) {
            fprintf(stderr, "Failed to set LED %d: %s\n", led_pins[i], strerror(errno));
        }
    }
}

static void log_proximity_event(uint16_t touch_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (touch_status == 0) {
        fprintf(log_file, "%s - No electrodes detected\n", timestamp);
    } else {
        fprintf(log_file, "%s - Electrodes: ", timestamp);
        for (int i = 0; i < 12; i++) {
            if (touch_status & (1 << i)) {
                fprintf(log_file, "E%d ", i);
            }
        }
        fprintf(log_file, "\n");
    }
    fflush(log_file);
}

static void cleanup(void) {
    for (int i = 0; i < NUM_LEDS; i++) {
        if (led_lines[i]) {
            gpiod_line_set_value(led_lines[i], 0);
            gpiod_line_release(led_lines[i]);
        }
    }
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file) fclose(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    for (int i = 0; i < NUM_LEDS; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, led_pins[i]);
        if (!led_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(led_lines[i], "mpr121_led", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    log_file = fopen("proximity_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Proximity-based art installation started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status;
        if (read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Failed to read touch status, retrying...\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        int pattern = 0;
        for (int i = 0; i < 12; i++) {
            if (touch_status & (1 << i)) {
                pattern |= (1 << i);
            }
        }

        set_led_pattern(pattern);
        log_proximity_event(touch_status);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

