#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define MPR121_ADDR 0x5A
#define LED_GPIO 27
#define PROXIMITY_THRESHOLD 0
#define DEBOUNCE_US 10000
#define LED_ON_TIME_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
    }
    return rc;
}

static int mpr121_read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
    }
    return rc;
}

static int mpr121_init(int handle) {
    int rc;

    // Soft reset
    rc = mpr121_write_reg(handle, 0x80, 0x63);
    if (rc < 0) return -1;
    gpioDelay(10000);

    // Stop mode
    rc = mpr121_write_reg(handle, 0x2B, 0x00);
    if (rc < 0) return -1;

    // Filter configuration
    rc = mpr121_write_reg(handle, 0x2C, 0x01);
    if (rc < 0) return -1;

    // Debounce
    rc = mpr121_write_reg(handle, 0x5B, 0x01);
    if (rc < 0) return -1;

    // ESI
    rc = mpr121_write_reg(handle, 0x5C, 0x00);
    if (rc < 0) return -1;

    // AFE config
    rc = mpr121_write_reg(handle, 0x5D, 0x01);
    if (rc < 0) return -1;

    // Baseline filtering
    rc = mpr121_write_reg(handle, 0x5E, 0x00);
    if (rc < 0) return -1;

    // Touch and release thresholds for electrode 0
    rc = mpr121_write_reg(handle, 0x41, 0x0A);
    if (rc < 0) return -1;
    rc = mpr121_write_reg(handle, 0x42, 0x05);
    if (rc < 0) return -1;

    // Enable electrode 0
    rc = mpr121_write_reg(handle, 0x5E, 0x01);
    if (rc < 0) return -1;

    // Start mode
    rc = mpr121_write_reg(handle, 0x2B, 0x01);
    if (rc < 0) return -1;

    return 0;
}

static int read_proximity(int handle) {
    int touch_status = mpr121_read_reg(handle, 0x00);
    if (touch_status < 0) return -1;

    // Electrode 0 is bit 0
    return (touch_status & 0x01) ? 1 : 0;
}

static void log_proximity_event(void) {
    FILE *fp = fopen("proximity.log", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Proximity detected on electrode 0\n", timestamp);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int proximity = read_proximity(i2c_handle);
        if (proximity < 0) {
            fprintf(stderr, "Error reading proximity, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        if (proximity == PROXIMITY_THRESHOLD) {
            printf("Proximity detected!\n");
            gpioWrite(LED_GPIO, 1);
            log_proximity_event();
            gpioDelay(LED_ON_TIME_US);
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(DEBOUNCE_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

