code:
/*
 * HC-SR04 ultrasonic distance measurement with pigpio ISR.
 *
 * Board:  Raspberry Pi Zero W
 * Sensor: HC-SR04 on BCM GPIO17 (TRIG) and BCM GPIO18 (ECHO)
 *         5V echo signal -> 1kOhm divider -> 3.3V Pi input
 *
 * Build:  gcc -O2 -Wall -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse per second */
#define ECHO_TIMEOUT_US  300000     /* 300 ms max echo wait */
#define MIN_VALID_US     58         /* HC-SR04 minimum range ~1 cm */
#define MAX_VALID_US     25000      /* HC-SR04 maximum range ~4 m */

#define LOG_FILE         "distance_log.txt"

/* ------------------------------------------------------------------ */
/* Shared state between ISR and main thread                          */
/* ------------------------------------------------------------------ */
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile bool     g_echo_seen   = false;
static volatile bool     g_running     = true;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

/* ------------------------------------------------------------------ */
/* ISR callback: fires on EITHER_EDGE of the echo pin                 */
/* ------------------------------------------------------------------ */
static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_start_tick = tick;
        g_echo_seen   = false;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_end_tick   = tick;
        g_echo_seen   = true;
    }
}

/* ------------------------------------------------------------------ */
/* Compute distance in meters from a valid echo pulse width            */
/* ------------------------------------------------------------------ */
static double calculate_distance(uint32_t pulse_us)
{
    /* speed_of_sound = 343 m/s  ->  34300 cm/s  ->  343000000 Hz */
    return (double)pulse_us * 343.0 / 2.0e6;
}

/* ------------------------------------------------------------------ */
/* Fire a 10 us trigger pulse                                         */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Append a timestamped distance reading to the log file                */
/* ------------------------------------------------------------------ */
static void log_distance(double distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, %.2f m\n", ts, distance);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(TRIGGER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(ECHO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    /* --- Register ISR for echo pin --- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_isr, NULL) != 0) {
        fprintf(stderr, "gpioSetISRFuncEx failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  TRIGGER: BCM GPIO%d  ECHO: BCM GPIO%d\n", TRIGGER_PIN, ECHO_PIN);
    printf("  Log file: %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main measurement loop --- */
    while (g_running) {
        trigger_sensor();

        /* Wait for echo with timeout */
        uint32_t waited = 0;
        while (!g_echo_seen && waited < ECHO_TIMEOUT_US && g_running) {
            gpioDelay(1000);  /* 1 ms */
            waited += 1000;
        }

        if (!g_running)
            break;

        if (!g_echo_seen) {
            fprintf(stderr, "Warning: echo timeout (no pulse received)\n");
            gpioDelay(TRIGGER_PULSE_US);
            continue;
        }

        /* Handle tick wraparound */
        uint32_t pulse_us;
        if (g_end_tick >= g_start_tick) {
            pulse_us = g_end_tick - g_start_tick;
        } else {
            pulse_us = (0xFFFFFFFFu - g_start_tick) + g_end_tick + 1u;
        }

        /* Sanity range check */
        if (pulse_us < MIN_VALID_US || pulse_us > MAX_VALID_US) {
            fprintf(stderr, "Warning: pulse width %u us out of range\n", pulse_us);
            gpioDelay(TRIGGER_PULSE_US);
            continue;
        }

        double distance = calculate_distance(pulse_us);
        log_distance(distance);

        printf("Distance: %.2f m\n", distance);

        gpioDelay(TRIGGER_PULSE_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

