#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L1X_ADDR 0x29
#define TRIGGER_PIN 27
#define I2C_BUS 1
#define LOG_INTERVAL_MS 100

/* VL53L1X register addresses */
#define REG_SOFT_RESET 0x0018
#define REG_SYSTEM_MODE 0x0019
#define REG_RANGE_START 0x0020
#define REG_RESULT_DISTANCE 0x0014
#define REG_RESULT_STATUS 0x0016

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg8(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        syslog(LOG_ERR, "I2C write failed (reg 0x%04X, val 0x%02X)", reg, value);
        return -1;
    }
    return 0;
}

static int read_reg8(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        syslog(LOG_ERR, "I2C write (reg select 0x%04X) failed", reg);
        return -1;
    }
    if (i2cReadDevice(handle, buf, 1) != 1) {
        syslog(LOG_ERR, "I2C read failed (reg 0x%04X)", reg);
        return -1;
    }
    *value = (uint8_t)buf[0];
    return 0;
}

static int read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        syslog(LOG_ERR, "I2C write (reg select 0x%04X) failed", reg);
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C read16 failed (reg 0x%04X)", reg);
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int init_sensor(int handle) {
    /* Soft reset */
    if (write_reg8(handle, REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(1000); /* 1 ms */
    if (write_reg8(handle, REG_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(1000); /* 1 ms */

    /* Set continuous mode */
    if (write_reg8(handle, REG_SYSTEM_MODE, 0x00) != 0) return -1;

    /* No timeout */
    if (write_reg8(handle, REG_SYSTEM_MODE, 0x00) != 0) return -1;

    /* Start ranging */
    if (write_reg8(handle, REG_RANGE_START, 0x01) != 0) return -1;

    return 0;
}

static int read_distance(int handle, uint16_t *distance) {
    uint8_t status;
    if (read_reg8(handle, REG_RESULT_STATUS, &status) != 0) return -1;
    if ((status & 0x01) == 0) {
        syslog(LOG_ERR, "Sensor not ready (status 0x%02X)", status);
        return -1;
    }
    if (read_reg16(handle, REG_RESULT_DISTANCE, distance) != 0) return -1;
    return 0;
}

static void log_data(uint16_t distance, uint8_t status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    syslog(LOG_INFO, "%s Distance: %u mm, Status: 0x%02X", timestamp, distance, status);
}

int main(void) {
    openlog("vl53l1x_logger", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioWrite(TRIGGER_PIN, 1); /* Enable sensor */

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device at 0x%02X on bus %d", VL53L1X_ADDR, I2C_BUS);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (init_sensor(i2c_handle) != 0) {
        syslog(LOG_ERR, "Sensor initialisation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "VL53L1X logger started");

    while (running) {
        uint16_t distance;
        uint8_t status;

        if (read_distance(i2c_handle, &distance) == 0) {
            log_data(distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read distance");
        }

        gpioDelay(LOG_INTERVAL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down");
    gpioWrite(TRIGGER_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

