#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD_CM 20.0f
#define LOG_FILE "gate_log.txt"
#define POLL_DELAY_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        return -1;
    }
    return 0;
}

static int read_reg16(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int read_reg16_u16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 2) != 2) {
        return -1;
    }
    return 0;
}

static int init_vl53l1x(int handle) {
    uint8_t model_id = 0;
    if (read_reg16(handle, 0x010F, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read model ID\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID: 0x%02X (expected 0xEA)\n", model_id);
        return -1;
    }

    if (write_reg16(handle, 0x0021, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set ranging mode\n");
        return -1;
    }

    if (write_reg16(handle, 0x0015, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }

    return 0;
}

static int read_distance_mm(int handle, uint16_t *distance_mm) {
    if (read_reg16_u16(handle, 0x0089, distance_mm) != 0) {
        return -1;
    }
    return 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static void control_gate(int gpio, int open) {
    if (gpioWrite(gpio, open ? 1 : 0) != 0) {
        fprintf(stderr, "Error: Failed to write GPIO %d\n", gpio);
        return;
    }
    char msg[128];
    snprintf(msg, sizeof(msg), "Gate %s", open ? "OPEN" : "CLOSED");
    log_event(msg);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X: %d\n", VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_vl53l1x(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", GATE_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GATE_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Gate control system started");

    int gate_open = 0;

    while (!terminate) {
        uint16_t distance_mm = 0;
        if (read_distance_mm(i2c_handle, &distance_mm) == 0) {
            float distance_cm = distance_mm / 10.0f;
            char msg[128];
            snprintf(msg, sizeof(msg), "Distance: %.2f cm", distance_cm);
            log_event(msg);

            if (distance_cm < DISTANCE_THRESHOLD_CM && !gate_open) {
                control_gate(GATE_GPIO, 1);
                gate_open = 1;
            } else if (distance_cm >= DISTANCE_THRESHOLD_CM && gate_open) {
                control_gate(GATE_GPIO, 0);
                gate_open = 0;
            }
        } else {
            log_event("Error: Failed to read distance");
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_event("Gate control system stopped");

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

