static int write_reg8(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing reg 0x%04X: %s\n", reg, pigpio_error(i2cWriteDevice(handle, buf, 3)));
        return -1;
    }
    return 0;
}

static int read_reg8(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error setting reg 0x%04X: %s\n", reg, pigpio_error(i2cWriteDevice(handle, buf, 2)));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error reading reg 0x%04X: %s\n", reg, pigpio_error(i2cReadDevice(handle, (char *)value, 1)));
        return -1;
    }
    return 0;
}

static int read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error setting reg 0x%04X: %s\n", reg, pigpio_error(i2cWriteDevice(handle, buf, 2)));
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading reg 0x%04X: %s\n", reg, pigpio_error(i2cReadDevice(handle, data, 2)));
        return -1;
    }
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

