#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define SPEAKER_PIN 18
#define TRIGGER_PIN 23
#define ECHO_PIN 24

#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 200.0
#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000
#define PWM_RANGE 1000
#define PWM_DUTY_CYCLE 500
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 200000
#define SAMPLE_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int calculate_frequency(float distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1;
    }
    float freq = MIN_FREQUENCY * expf(distance / 50.0f);
    if (freq < MIN_FREQUENCY) freq = MIN_FREQUENCY;
    if (freq > MAX_FREQUENCY) freq = MAX_FREQUENCY;
    return (int)freq;
}

static int set_speaker_frequency(int frequency) {
    if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) {
        fprintf(stderr, "Error: Invalid frequency %d Hz (must be %d-%d Hz)\n",
                frequency, MIN_FREQUENCY, MAX_FREQUENCY);
        return -1;
    }
    int period_us = 1000000 / frequency;
    if (gpioHardwarePWM(SPEAKER_PIN, period_us, PWM_DUTY_CYCLE) < 0) {
        fprintf(stderr, "Error: gpioHardwarePWM failed for frequency %d Hz\n", frequency);
        return -1;
    }
    return 0;
}

static int trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: Failed to set trigger high\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to set trigger low\n");
        return -1;
    }
    return 0;
}

static int read_echo_pulse(uint32_t *start_tick, uint32_t *end_tick) {
    uint32_t timeout = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout) >= 0) {
            fprintf(stderr, "Error: Echo start timeout\n");
            return -1;
        }
    }
    *start_tick = gpioTick();
    timeout = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout) >= 0) {
            fprintf(stderr, "Error: Echo end timeout\n");
            return -1;
        }
    }
    *end_tick = gpioTick();
    return 0;
}

static float calculate_distance(uint32_t start_tick, uint32_t end_tick) {
    uint32_t pulse_width = end_tick - start_tick;
    return (float)pulse_width * 0.0343f / 2.0f;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPEAKER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set speaker pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to initialise trigger pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(50000);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int previous_frequency = -1;

    while (running) {
        if (trigger_sensor() < 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        uint32_t start_tick, end_tick;
        if (read_echo_pulse(&start_tick, &end_tick) < 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float distance = calculate_distance(start_tick, end_tick);
        int frequency = calculate_frequency(distance);

        if (frequency < 0) {
            if (previous_frequency >= 0) {
                set_speaker_frequency(previous_frequency);
            }
        } else {
            if (frequency != previous_frequency) {
                set_speaker_frequency(frequency);
                previous_frequency = frequency;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioHardwarePWM(SPEAKER_PIN, 0, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

