#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define SPEED_OF_SOUND 29.1
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define TIMEOUT_US 50000
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1;
    }
    return 0;
}

static int measure_echo_pulse(uint32_t *start_tick, uint32_t *end_tick) {
    uint32_t timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > TIMEOUT_US) {
            return -1;
        }
    }

    *start_tick = gpioTick();

    timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - timeout_start) > TIMEOUT_US) {
            return -1;
        }
    }

    *end_tick = gpioTick();
    return 0;
}

static float calculate_distance(uint32_t start_tick, uint32_t end_tick) {
    uint32_t pulse_width = end_tick - start_tick;
    return (float)pulse_width / 2.0 / SPEED_OF_SOUND;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler\n");
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        if (trigger_sensor() < 0) {
            fprintf(stderr, "Error: trigger failed\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        uint32_t start_tick, end_tick;
        if (measure_echo_pulse(&start_tick, &end_tick) < 0) {
            fprintf(stderr, "Error: echo timeout (sensor absent or out of range)\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        float distance = calculate_distance(start_tick, end_tick);

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Invalid reading: Distance: %.2f cm\n", distance);
        } else {
            printf("Distance: %.2f cm", distance);
            if (distance < 10.0) {
                printf(" (Too close!)");
            }
            printf("\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

