    buf[0] = REG_TRIGGER;
    buf[1] = 0x01;
    if (spiWrite(spi_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x00: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement to complete (datasheet: typ 10 ms, max 20 ms)
    gpioDelay(20000); // 20 ms

    return 0;
}

// Read distance from the ICU-20201 sensor
int read_distance(int *distance) {
    char tx_buf[2] = {REG_DIST_L, 0x00};
    char rx_buf[2] = {0};

    // Perform a full-duplex transfer to read distance data
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
        return -1;
    }

    // Combine the low and high bytes to form the distance value
    *distance = ((rx_buf[1] & 0xFF) << 8) | (rx_buf[0] & 0xFF);

    return 0;
}

// Log distance data to a CSV file
void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize the ICU-20201 sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int distance;
    while (!terminate) {
        // Read distance
        if (read_distance(&distance) == 0) {
            // Validate distance range
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                // Log the distance
                log_distance(distance);
            } else {
                fprintf(stderr, "Invalid distance reading: %d mm\n", distance);
            }
        } else {
            fprintf(stderr, "Failed to read distance, retrying...\n");
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

