    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1175_I2C_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_reg8(i2c_fd, 0x00, 0x00) < 0) {
        fprintf(stderr, "Failed to initialize Si1175 (sensor absent or bus error)\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (fprintf(log_fp, "timestamp,als_visible\n") < 0) {
        fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
        fclose(log_fp);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (fflush(log_fp) != 0) {
        fprintf(stderr, "Failed to flush CSV header: %s\n", strerror(errno));
        fclose(log_fp);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Si1175 proximity logger started. Logging to %s every %d seconds. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (running) {
        uint16_t als_visible = 0;

        if (i2c_read_reg16(i2c_fd, SI1175_REG_ALS_VIS_DATA0, &als_visible) < 0) {
            fprintf(stderr, "Failed to read ALS visible data. Retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
        } else {
            if (log_data(log_fp, als_visible) < 0) {
                fprintf(stderr, "Failed to log data. Retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            } else {
                printf("ALS Visible: %u\n", als_visible);
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");

    if (log_fp != NULL) {
        fclose(log_fp);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}

