#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SI1120_ADDR 0x60
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_ALS_DATA0 0x22
#define SI1120_REG_ALS_DATA1 0x23
#define SI1120_REG_PS1_DATA0 0x18
#define SI1120_REG_PS1_DATA1 0x19
#define SI1120_REG_RESET 0x30
#define SI1120_PART_ID 0x41
#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int initialize_si1120(int handle) {
    uint8_t part_id;
    if (read_register(handle, SI1120_REG_PART_ID, &part_id) != 0) {
        return -1;
    }
    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Unexpected part ID: 0x%02X (expected 0x%02X)\n", part_id, SI1120_PART_ID);
        return -1;
    }
    if (write_register(handle, SI1120_REG_RESET, 0x01) != 0) {
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_als_data(int handle, uint16_t *als_data) {
    uint8_t low, high;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (read_register(handle, SI1120_REG_ALS_DATA0, &low) != 0) {
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (read_register(handle, SI1120_REG_ALS_DATA1, &high) != 0) {
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        *als_data = (uint16_t)((high << 8) | low);
        return 0;
    }
    return -1;
}

static int read_proximity_data(int handle, uint16_t *proximity_data) {
    uint8_t low, high;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (read_register(handle, SI1120_REG_PS1_DATA0, &low) != 0) {
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (read_register(handle, SI1120_REG_PS1_DATA1, &high) != 0) {
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        *proximity_data = (uint16_t)((high << 8) | low);
        return 0;
    }
    return -1;
}

static void log_data(FILE *fp, uint16_t als_data, uint16_t proximity_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, ALS: %u, Proximity: %u\n", timestamp, als_data, proximity_data);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n", I2C_BUS, SI1120_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_si1120(i2c_handle) != 0) {
        fprintf(stderr, "Si1120 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1120 sensor logging started. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t als_data, proximity_data;

        if (read_als_data(i2c_handle, &als_data) != 0) {
            fprintf(stderr, "Failed to read ALS data after %d retries\n", MAX_RETRIES);
        } else if (read_proximity_data(i2c_handle, &proximity_data) != 0) {
            fprintf(stderr, "Failed to read proximity data after %d retries\n", MAX_RETRIES);
        } else {
            log_data(log_file, als_data, proximity_data);
            printf("ALS: %u, Proximity: %u\n", als_data, proximity_data);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

