    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1120 sensor logging started. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t als_data, proximity_data;

        if (read_als_data(i2c_handle, &als_data) != 0) {
