#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SI1145_ADDR 0x60
#define I2C_BUS 1
#define LOG_FILE "proximity_log.txt"
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int initialize_sensor(int handle) {
    if (write_register(handle, 0x07, 0x03) < 0) return -1;
    if (write_register(handle, 0x06, 0x02) < 0) return -1;
    if (write_register(handle, 0x1A, 0x00) < 0) return -1;
    if (write_register(handle, 0x21, 0x0B) < 0) return -1;
    if (write_register(handle, 0x24, 0x00) < 0) return -1;
    if (write_register(handle, 0x22, 0x49) < 0) return -1;
    if (write_register(handle, 0x0C, 0x03) < 0) return -1;
    if (write_register(handle, 0x0F, 0x0F) < 0) return -1;
    if (write_register(handle, 0x11, 0x03) < 0) return -1;
    if (write_register(handle, 0x0D, 0x07) < 0) return -1;
    if (write_register(handle, 0x80, 0x03) < 0) return -1;
    return 0;
}

static int read_proximity(int handle, uint16_t *proximity) {
    uint8_t low, high;
    if (read_register(handle, 0x16, &low) < 0) return -1;
    if (read_register(handle, 0x17, &high) < 0) return -1;
    *proximity = ((uint16_t)high << 8) | low;
    return 0;
}

static void log_proximity(FILE *fp, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, %u\n", timestamp, proximity);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n", SI1145_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialisation failed. Check wiring and I2C address.\n");
        cleanup();
        return 1;
    }

    printf("Si1145 proximity sensor logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t proximity = 0;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (read_proximity(i2c_handle, &proximity) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d failed, retrying...\n", attempt + 1);
            gpioDelay(100000);
        }

        if (success) {
            log_proximity(log_file, proximity);
            printf("Proximity: %u\n", proximity);
        } else {
            fprintf(stderr, "Failed to read proximity after %d attempts.\n", MAX_RETRIES);
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s, ERROR: Failed to read proximity after %d attempts.\n", timestamp, MAX_RETRIES);
            fflush(log_file);
        }

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

