        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n", SI1145_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialisation failed. Check wiring and I2C address.\n");
        cleanup();
        return 1;
    }

    printf("Si1145 proximity sensor logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t proximity = 0;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (read_proximity(i2c_handle, &proximity) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d failed, retrying...\n", attempt + 1);
            gpioDelay(100000);
        }

        if (success) {
            log_proximity(log_file, proximity);
            printf("Proximity: %u\n", proximity);
        } else {
            fprintf(stderr, "Failed to read proximity after %d attempts.\n", MAX_RETRIES);
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s, ERROR: Failed to read proximity after %d attempts.\n", timestamp, MAX_RETRIES);
            fflush(log_file);
        }

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

