#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define SPEED_OF_SOUND 34300.0
#define TIMEOUT_US 30000
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_MID_PULSE 1500

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

double measure_distance() {
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;
    int timeout = 0;

    while (gpioRead(ECHO_PIN) == 0) {
        if (++timeout > TIMEOUT_US) {
            return -1.0;
        }
        gpioDelay(1);
    }
    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        if (++timeout > TIMEOUT_US) {
            return -1.0;
        }
        gpioDelay(1);
    }
    end_tick = gpioTick();

    uint32_t pulse_duration = end_tick - start_tick;
    double distance = (pulse_duration * SPEED_OF_SOUND) / 2000000.0;
    return distance;
}

void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    int pulse_width = SERVO_MIN_PULSE + (angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE)) / 180;
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    signal(SIGINT, signal_handler);

    while (program_running) {
        double distance = measure_distance();

        if (distance < 0) {
            fprintf(stderr, "Error: Timeout waiting for echo\n");
            gpioDelay(100000);
            continue;
        }

        printf("Distance: %.2f cm\n", distance);

        if (distance < 20.0) {
            set_servo_angle(180);
        } else if (distance < 110.0) {
            set_servo_angle(90);
        } else {
            set_servo_angle(0);
        }

        gpioDelay(100000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return 0;
}

