#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

#define MIN_DISTANCE_CM 20.0
#define MAX_DISTANCE_CM 200.0
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define TIMEOUT_US 50000
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure distance in cm. Returns -1.0 on timeout or error.
 * Uses gpioTick() for microsecond timing.
 */
static float measure_distance(void) {
    uint32_t start_tick, end_tick;
    uint32_t timeout_start;

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);

    /* 10 us trigger pulse */
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    /* Wait for echo rising edge */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > TIMEOUT_US) {
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - timeout_start) > TIMEOUT_US) {
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_duration = end_tick - start_tick;
    float distance = (float)pulse_duration * 0.0343f / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1.0;
    }
    return distance;
}

/*
 * Map distance (cm) to servo angle (degrees).
 * Returns -1.0 on invalid input.
 */
static float distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    float angle = (distance - MIN_DISTANCE_CM) /
                 (MAX_DISTANCE_CM - MIN_DISTANCE_CM) *
                 (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) +
                 MIN_PULSE_WIDTH;

    if (angle < 0.0f) angle = 0.0f;
    if (angle > MAX_PULSE_WIDTH) angle = MAX_PULSE_WIDTH;

    return angle;
}

/*
 * Set servo angle (degrees) using gpioServo().
 * Returns 0 on success, -1 on error.
 */
static int set_servo_angle(float angle) {
    if (angle < 0.0f) angle = 0.0f;
    if (angle > MAX_PULSE_WIDTH) angle = MAX_PULSE_WIDTH;

    int pulse_width = (int)angle;
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        return -1;
    }
    return 0;
}

int main(void) {
    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Error: Timeout or invalid distance measurement\n");
        } else {
            float angle = distance_to_angle(distance);
            if (set_servo_angle(angle) != 0) {
                fprintf(stderr, "Error: Failed to set servo angle\n");
            }
            printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0); /* Stop servo signal */
    gpioTerminate();
    printf("Parking assist system stopped.\n");

    return EXIT_SUCCESS;
}

