#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI7005_ADDR 0x40
#define TEMP_REG 0x01
#define HUMID_REG 0x02
#define CONFIG_REG 0x03
#define CONFIG_VALUE 0x00
#define CONVERSION_DELAY_US 10000
#define LOOP_DELAY_US 2000000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_temperature(int handle, float *temperature) {
    if (write_register(handle, CONFIG_REG, CONFIG_VALUE) < 0) {
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);

    uint8_t temp_raw;
    if (read_register(handle, TEMP_REG, &temp_raw) < 0) {
        return -1;
    }

    *temperature = (175.72f * temp_raw) / 65536.0f - 46.85f;
    return 0;
}

static int read_humidity(int handle, float *humidity) {
    if (write_register(handle, CONFIG_REG, CONFIG_VALUE) < 0) {
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);

    uint8_t hum_raw;
    if (read_register(handle, HUMID_REG, &hum_raw) < 0) {
        return -1;
    }

    *humidity = (125.0f * hum_raw) / 65536.0f - 6.0f;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", SI7005_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (!terminate) {
        float temperature, humidity;

        if (read_temperature(i2c_handle, &temperature) == 0 &&
            read_humidity(i2c_handle, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Attempting recovery...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(1000000);
            i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C device: %d\n", i2c_handle);
                break;
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

