/*
 * MPU-6050 accelerometer/gyroscope reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   MPU-6050 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   MPU-6050 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   MPU-6050 VCC -> 3.3 V
 *   MPU-6050 GND -> GND
 *
 * Build: gcc -Wall -O2 -o mpu6050_reader mpu6050_reader.c -lpigpio -lrt
 * Run:   sudo ./mpu6050_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- MPU-6050 register addresses ---- */
#define MPU6050_ADDR          0x68
#define MPU6050_WHO_AM_I      0x75
#define MPU6050_PWR_MGMT_1    0x6B
#define MPU6050_ACCEL_CONFIG  0x1C
#define MPU6050_GYRO_CONFIG   0x1B
#define MPU6050_SAMPLE_RATE   0x19
#define MPU6050_ACCEL_XOUT_H  0x3B

/* ---- Expected WHO_AM_I value ---- */
#define MPU6050_WHO_AM_I_VAL  0x68

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only, do not call blocking functions.    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a register.                                */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a register.                                */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a block of bytes starting at a register.                        */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: %d\n",
                reg, len, rc);
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "[ERROR] Short read: got %d of %u bytes (reg=0x%02X)\n",
                rc, len, reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the MPU-6050.                                           */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int init_mpu6050(int handle)
{
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (read_register(handle, MPU6050_WHO_AM_I, &who_am_i) != 0) {
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "[ERROR] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, MPU6050_WHO_AM_I_VAL);
        return -1;
    }
    printf("[INFO] MPU-6050 detected (WHO_AM_I = 0x%02X)\n", who_am_i);

    /* Reset the device */
    if (write_register(handle, MPU6050_PWR_MGMT_1, 0x80) != 0) {
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle after reset */

    /* Clear sleep bit (clears SLEEP bit) */
    if (write_register(handle, MPU6050_PWR_MGMT_1, 0x00) != 0) {
        return -1;
    }
    gpioDelay(100000); /* 100 ms stabilisation */

    /* Set sample rate divider to 7 (1 kHz / (1 + 7) = 125 Hz) */
    if (write_register(handle, MPU6050_SAMPLE_RATE, 0x07) != 0) {
        return -1;
    }

    /* Configure accelerometer range to ±2 g (AFS_SEL = 0) */
    if (write_register(handle, MPU6050_ACCEL_CONFIG, 0x00) != 0) {
        return -1;
    }

    /* Configure gyroscope range to ±250 deg/s (FS_SEL = 0) */
    if (write_register(handle, MPU6050_GYRO_CONFIG, 0x00) != 0) {
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read raw accelerometer and gyroscope data.                          */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int read_raw_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                          int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t buf[14];

    /*
     * MPU-6050 data block layout (from ACCEL_XOUT_H):
     *   [0..1]  accel X (big-endian)
     *   [2..3]  accel Y (big-endian)
     *   [4..5]  accel Z (big-endian)
     *   [6..7]  temperature (big-endian)
     *   [8..9]  gyro X  (big-endian)
     *   [10..11] gyro Y  (big-endian)
     *   [12..13] gyro Z  (big-endian)
     */
    if (read_block(handle, MPU6050_ACCEL_XOUT_H, buf, sizeof(buf)) != 0) {
        return -1;
    }

    *ax = (int16_t)((buf[0]  << 8) | buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | buf[3]);
    *az = (int16_t)((buf[4]  << 8) | buf[5]);
    *gx = (int16_t)((buf[8]  << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Print raw accelerometer and gyroscope data to stdout.              */
/* ------------------------------------------------------------------ */
static void print_data(int16_t ax, int16_t ay, int16_t az,
                       int16_t gx, int16_t gy, int16_t gz)
{
    printf("Accel: X=%6d  Y=%6d  Z=%6d  |  Gyro: X=%6d  Y=%6d  Z=%6d\n",
           ax, ay, az, gx, gy, gz);
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the MPU-6050 default address */
    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise the MPU-6050 */
    if (init_mpu6050(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] MPU-6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("[INFO] MPU-6050 initialised. Logging data every 100 ms...\n");
    printf("Press Ctrl+C to stop.\n");

    /* Main loop */
    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (read_raw_data(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            print_data(ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "[WARN] Failed to read sensor data; continuing...\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    printf("\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

