#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SHT40_ADDR        0x44
#define I2C_BUS           1
#define MEASURE_CMD       0xFD
#define MEASURE_DELAY_US  10000   /* 10 ms high-repeatability measurement */
#define LOOP_DELAY_US     5000000 /* 5 seconds */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (polynomial 0x31, initial value 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_sht40(int handle, float *temperature, float *humidity)
{
    uint8_t cmd = MEASURE_CMD;
    uint8_t buf[6];

    /* Send measurement command */
    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "[ERROR] I2C write failed (command 0xFD)\n");
        return -1;
    }

    /* Wait for measurement to complete */
    gpioDelay(MEASURE_DELAY_US);

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "[ERROR] I2C read failed (6 bytes expected)\n");
        return -1;
    }

    /* Validate CRC for temperature (bytes 0-1, CRC at byte 2) */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }

    /* Validate CRC for humidity (bytes 3-4, CRC at byte 5) */
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = -6.0f  + 125.0f * (float)h_raw / 65535.0f;

    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, SHT40_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
