        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file " LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting MLX90614 temperature monitoring. Press Ctrl+C to stop.\n");

    while (running) {
        float ambient = 0.0f, object = 0.0f;
        int read_ok = 1;

        if (read_temperature(i2c_fd, AMBIENT_TEMP_REG, &ambient) < 0) {
            fprintf(stderr, "Error reading ambient temperature.\n");
            read_ok = 0;
        }
        if (read_temperature(i2c_fd, OBJECT_TEMP_REG, &object) < 0) {
            fprintf(stderr, "Error reading object temperature.\n");
            read_ok = 0;
        }

        if (read_ok) {
            if (log_temperature(ambient, object) < 0) {
                fprintf(stderr, "Error logging temperature.\n");
            } else {
                printf("Ambient: %.2f C, Object: %.2f C\n", ambient, object);
            }
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

