#define RETRY_DELAY_US 100000     /* 100 ms */

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/*
 * Send a 2-byte command to the SDP31.
 * Returns 0 on success, -1 on failure.
 */
static int sdp31_send_command(uint8_t msb, uint8_t lsb) {
    char buf[2] = { (char)msb, (char)lsb };
    int rc = i2cWriteDevice(i2c_handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X%02X): %s\n",
                msb, lsb, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read 6 bytes from the SDP31.
 * Returns 0 on success, -1 on failure.
 */
static int sdp31_read_data(uint8_t *data) {
    int rc = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C read failed: expected 6 bytes, got %d: %s\n",
                rc, rc < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/*
 * Convert raw 16-bit data to physical units.
 * Returns 0 on success, -1 on CRC mismatch.
 */
static int sdp31_convert(const uint8_t *data, float *pressure, float *temperature) {
    uint16_t raw_pressure = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_temperature = ((uint16_t)data[3] << 8) | data[4];

    /* CRC-8 check (Sensirion polynomial 0x31, init 0xFF) */
    uint8_t crc_pressure = 0xFF;
    for (int i = 0; i < 2; i++) {
        crc_pressure ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc_pressure & 0x80)
                crc_pressure = (crc_pressure << 1) ^ 0x31;
            else
                crc_pressure <<= 1;
        }
    }
    if (crc_pressure != data[2]) {
        fprintf(stderr, "Pressure CRC mismatch: computed 0x%02X, received 0x%02X\n",
                crc_pressure, data[2]);
        return -1;
    }

    crc_pressure = 0xFF;
    for (int i = 3; i < 5; i++) {
        crc_pressure ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc_pressure & 0x80)
                crc_pressure = (crc_pressure << 1) ^ 0x31;
            else
                crc_pressure <<= 1;
        }
    }
    if (crc_pressure != data[5]) {
        fprintf(stderr, "Temperature CRC mismatch: computed 0x%02X, received 0x%02X\n",
                crc_pressure, data[5]);
        return -1;
    }

    *pressure = (float)raw_pressure / 60.0f;
    *temperature = (float)raw_temperature / 200.0f;
    return 0;
}

