static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int i2c_write_cmd(uint8_t msb, uint8_t lsb) {
    uint8_t buf[2] = {msb, lsb};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t *buf, size_t len) {
    ssize_t n = read(i2c_fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sdp800(float *pressure, float *temperature) {
    if (i2c_write_cmd(MEASUREMENT_CMD_MSB, MEASUREMENT_CMD_LSB) < 0) {
        return -1;
    }
    usleep(MEASUREMENT_DELAY_MS * 1000);

    uint8_t buf[6];
    if (i2c_read_bytes(buf, 6) < 0) {
