#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD 28.0
#define TEMP_HYSTERESIS 1.0
#define BUFFER_SIZE 60
#define MEASUREMENT_DELAY_US 10000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} SensorData;

static SensorData circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_si7021(int handle, float *temperature, float *humidity) {
    char cmd[2];
    char data[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        cmd[0] = 0xE3;
        if (i2cWriteDevice(handle, cmd, 1) != 0) {
            fprintf(stderr, "Error: Failed to trigger temperature measurement (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }
        gpioDelay(MEASUREMENT_DELAY_US);

        cmd[0] = 0xE5;
        if (i2cWriteDevice(handle, cmd, 1) != 0) {
            fprintf(stderr, "Error: Failed to trigger humidity measurement (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }
        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(handle, data, 6) != 6) {
            fprintf(stderr, "Error: Failed to read sensor data (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }

        uint16_t raw_temperature = (data[0] << 8) | data[1];
        uint16_t raw_humidity = (data[3] << 8) | data[4];

        *temperature = 175.72f * raw_temperature / 65536.0f - 46.85f;
        *humidity = 125.0f * raw_humidity / 65536.0f - 6.0f;

        if (*temperature < -40.0f || *temperature > 125.0f || *humidity < 0.0f || *humidity > 100.0f) {
            fprintf(stderr, "Warning: Sensor data out of range (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }

        return 0;
    }

    fprintf(stderr, "Error: Failed to read sensor data after %d attempts\n", MAX_RETRIES);
    return -1;
}

static void add_to_buffer(float temperature, float humidity) {
    time(&circular_buffer[buffer_index].timestamp);
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void) {
    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index - 1 - i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&circular_buffer[idx].timestamp);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("[%s] Temperature: %.2f C, Humidity: %.2f %%\n", time_str, circular_buffer[idx].temperature, circular_buffer[idx].humidity);
    }
    printf("--- End of Log ---\n\n");
}

static void control_fan(float temperature) {
    static int fan_state = 0;

    if (temperature > TEMP_THRESHOLD + TEMP_HYSTERESIS) {
        if (fan_state == 0) {
            gpioWrite(FAN_GPIO, 1);
            fan_state = 1;
            printf("Fan ON (Temperature: %.2f C)\n", temperature);
        }
    } else if (temperature < TEMP_THRESHOLD - TEMP_HYSTERESIS) {
        if (fan_state == 1) {
            gpioWrite(FAN_GPIO, 0);
            fan_state = 0;
            printf("Fan OFF (Temperature: %.2f C)\n", temperature);
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d\n", SI7021_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7021 Fan Control System started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature, humidity;

        if (read_si7021(i2c_handle, &temperature, &humidity) == 0) {
            add_to_buffer(temperature, humidity);
            print_buffer();
            control_fan(temperature);
        } else {
            fprintf(stderr, "Error: Sensor read failed, degrading fan to OFF\n");
            gpioWrite(FAN_GPIO, 0);
        }

        sleep(2);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

