#include <unistd.h>

#define SCD40_ADDR 0x62
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL_SEC 5
#define START_PERIODIC_MEASUREMENT_CMD 0x21B1
#define STOP_PERIODIC_MEASUREMENT_CMD 0x3F86
#define DATA_READY_FLAG 0xE4B8
#define DATA_READ_CMD 0xEC05
#define MEASUREMENT_DELAY_US 1000000
#define START_PERIODIC_MEASUREMENT_DELAY_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to write command 0x%04X to I2C device.\n", cmd);
        return -1;
    }
    return 0;
}

static int read_measurement(uint16_t *co2, float *temperature, float *humidity) {
    uint8_t buf[9];
    int result = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (result != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from I2C device (got %d).\n", result);
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on CO2 data.\n");
