#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TMP05_GPIO 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds */
#define MAX_CONSECUTIVE_ERRORS 3
#define STUCK_TIMEOUT_US 50000      /* 50 ms timeout for edge wait */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure the high pulse width (TH) and total cycle width (TL) of the
 * TMP05 PWM signal. Returns 0 on success, -1 on timeout / error.
 */
static int measure_tmp05(uint32_t *th_us, uint32_t *tl_us) {
    uint32_t start_tick, end_tick;
    uint32_t timeout_tick;

    /* Wait for rising edge (start of PWM cycle) */
    timeout_tick = gpioTick() + STUCK_TIMEOUT_US;
    while (gpioRead(TMP05_GPIO) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: TMP05 rising edge timeout (sensor absent or stuck low)\n");
            return -1;
        }
    }
    start_tick = gpioTick();

    /* Wait for falling edge (end of PWM cycle) */
    timeout_tick = gpioTick() + STUCK_TIMEOUT_US;
    while (gpioRead(TMP05_GPIO) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: TMP05 falling edge timeout (sensor stuck high)\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    *th_us = end_tick - start_tick;
    *tl_us = gpioTick() - end_tick;
    return 0;
}

/*
 * Convert the TMP05 raw 16-bit value to degrees Celsius.
 * Returns 0 on success, -1 on division by zero.
 */
static int convert_to_celsius(uint16_t raw, float *temperature) {
    uint32_t th_us, tl_us;

    if (measure_tmp05(&th_us, &tl_us) != 0) {
        return -1;
    }

    if (tl_us == 0) {
        fprintf(stderr, "Error: TMP05 total cycle width is zero (sensor absent or stuck high)\n");
        return -1;
    }

    float ratio = (float)th_us / (float)tl_us;
    *temperature = 4215.0f - (2143.0f * ratio);

    if (*temperature < -40.0f || *temperature > 150.0f) {
        fprintf(stderr, "Warning: Temperature reading %.2f C outside valid range (-40, 150)\n", *temperature);
        return -1;
    }

    return 0;
}

static void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return;
    }

    if (fprintf(log_file, "%s, %.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
    } else {
        fflush(log_file);
    }
}

static void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return;
    }

    if (fprintf(log_file, "%s, ERROR: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
    } else {
        fflush(log_file);
    }
}

int main(void) {
    int consecutive_errors = 0;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO4 as input with pull-up resistor (TMP05 output is open-collector) */
    gpioSetMode(TMP05_GPIO, PI_INPUT);
    gpioSetPullUpDown(TMP05_GPIO, PI_PUD_UP);

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMP05 temperature logger started. Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    while (running) {
        float temperature;

        if (convert_to_celsius(0, &temperature) == 0) {
            consecutive_errors = 0;
            log_temperature(temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error: Failed to read temperature (consecutive errors: %d)\n", consecutive_errors);

            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_error("SENSOR MALFUNCTION: Too many consecutive read failures");
                fprintf(stderr, "Sensor malfunction detected. Check wiring and sensor presence.\n");
                consecutive_errors = 0;
            }
        }

        /* Sleep in small increments to allow signal handler to interrupt promptly */
        for (int i = 0; i < 50 && running; i++) {
            gpioDelay(10000); /* 10 ms */
        }
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

