#define SINUSOIDAL_OFFSET_HUM 5.0
#define SINUSOIDAL_PERIOD_SEC 3600

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sht35(float *temperature, float *humidity) {
    uint8_t cmd[2] = {MEASURE_CMD_HIGH_REP, MEASURE_CMD_CLOCK_STRETCHING_DISABLED};
    uint8_t data[6];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "Error: I2C write failed (attempt %d/%d)\n", RETRY_COUNT - retries + 1, RETRY_COUNT);
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6) {
