            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(data, 2) != data[2]) {
            fprintf(stderr, "Error: Temperature CRC mismatch (attempt %d/%d)\n", RETRY_COUNT - retries + 1, RETRY_COUNT);
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(data + 3, 2) != data[5]) {
            fprintf(stderr, "Error: Humidity CRC mismatch (attempt %d/%d)\n", RETRY_COUNT - retries + 1, RETRY_COUNT);
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t temp_raw = (data[0] << 8) | data[1];
        uint16_t hum_raw = (data[3] << 8) | data[4];

        *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
        *humidity = 100.0f * (float)hum_raw / 65535.0f;

        return 0;
    }

    fprintf(stderr, "Error: Failed to read SHT35 after %d retries\n", RETRY_COUNT);
    return -1;
