    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    float t = (float)utc->tm_hour + (float)utc->tm_min / 60.0f + (float)utc->tm_sec / 3600.0f;
    float offset_temp = SINUSOIDAL_OFFSET_TEMP * sin(2.0f * M_PI * t / SINUSOIDAL_PERIOD_SEC);
    float offset_hum = SINUSOIDAL_OFFSET_HUM * sin(2.0f * M_PI * t / SINUSOIDAL_PERIOD_SEC);
    *temperature += offset_temp;
    *humidity += offset_hum;
}

static void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X (error %d)\n", SHT35_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;

    while (!terminate) {
        if (read_sht35(&temperature, &humidity) == 0) {
            add_sinusoidal_offset(&temperature, &humidity);
            log_data(temperature, humidity);
        } else {
