#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP810_ADDR 0x25
#define MEASURE_CMD_MSB 0x36
#define MEASURE_CMD_LSB 0x2F
#define CONVERSION_DELAY_MS 45
#define LOG_INTERVAL_S 1
#define CSV_FILE "airflow.csv"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(uint8_t msb, uint8_t lsb) {
    uint8_t buf[2] = {msb, lsb};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int16_t *pressure, int16_t *temperature, int16_t *scale_factor) {
    uint8_t data[9];
    ssize_t bytes_read = read(i2c_fd, data, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "I2C read failed: expected 9 bytes, got %zd: %s\n", bytes_read, strerror(errno));
        return -1;
    }

    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "Scale factor CRC mismatch\n");
        return -1;
    }

    *pressure = (int16_t)((data[0] << 8) | data[1]);
    *temperature = (int16_t)((data[3] << 8) | data[4]);
    *scale_factor = (int16_t)((data[6] << 8) | data[7]);

    return 0;
}

static void convert_data(int16_t pressure, int16_t temperature, int16_t scale_factor, float *pressure_pa, float *temperature_c) {
    if (scale_factor == 0) {
        *pressure_pa = 0.0f;
        *temperature_c = 0.0f;
        return;
    }

    float p_raw = (float)pressure / (float)scale_factor;
    float t_raw = (float)temperature / 100.0f;

    *pressure_pa = p_raw * 100.0f;
    *temperature_c = t_raw;
}

static void log_data(float pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SDP810_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", CSV_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    fflush(log_file);

    while (running) {
        if (i2c_write_cmd(MEASURE_CMD_MSB, MEASURE_CMD_LSB) != 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            sleep(LOG_INTERVAL_S);
            continue;
        }

        usleep(CONVERSION_DELAY_MS * 1000);

        int16_t pressure, temperature, scale_factor;
        if (read_sensor_data(&pressure, &temperature, &scale_factor) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            sleep(LOG_INTERVAL_S);
            continue;
        }

        float pressure_pa, temperature_c;
        convert_data(pressure, temperature, scale_factor, &pressure_pa, &temperature_c);

        log_data(pressure_pa, temperature_c);

        sleep(LOG_INTERVAL_S);
    }

    cleanup();
    return 0;
}

