#define SHT35_ADDR        0x44
#define MEASURE_CMD_MSB   0x24
#define MEASURE_CMD_LSB   0x00
#define MEASURE_DELAY_US  15000   /* 15 ms max conversion time */
#define SAMPLE_INTERVAL_S 5
#define CSV_FILENAME      "environment.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR) ---- */
static uint8_t sht35_crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
