#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR        0x40
#define I2C_BUS            "/dev/i2c-1"
#define LOG_FILE           "environment.log"
#define POLL_TIMEOUT_MS    100
#define SAMPLE_INTERVAL_S  5

/* Si7021 commands */
#define CMD_MEASURE_HUMIDITY  0xF5
#define CMD_MEASURE_TEMP     0xF3
#define CMD_READ_PREV_TEMP  0xE0
#define CMD_RESET            0xFE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Si7021: poly 0x31, init 0x00 */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(uint8_t cmd)
{
    if (write(g_i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t *buf, size_t len)
{
    ssize_t n = read(g_i2c_fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: got %zd of %zu bytes: %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a measurement from the Si7021.
 * Returns 0 on success and stores the raw value in *out;
 * returns -1 on timeout or I2C error.
 */
static int read_measurement(uint16_t *out)
{
    uint8_t cmd;
    uint8_t buf[3];

    /* Trigger measurement */
    switch (cmd = (uint8_t)g_cmd) {
    case CMD_MEASURE_HUMIDITY:
    case CMD_MEASURE_TEMP:
        if (i2c_write_cmd(cmd) != 0)
            return -1;
        break;
    case CMD_READ_PREV_TEMP:
        if (i2c_write_cmd(cmd) != 0)
            return -1;
        /* Si7021 needs a short delay after reading temperature */
        usleep(10000);
        break;
    default:
        fprintf(stderr, "Invalid measurement command 0x%02X\n", cmd);
        return -1;
    }

    /* Poll for data-ready (max ~100 ms) */
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (i2c_read_bytes(buf, 3) == 0)
            break;
        usleep(1000);
    }
    if (i == POLL_TIMEOUT_MS) {
        fprintf(stderr, "Measurement timeout for command 0x%02X\n", cmd);
        return -1;
    }

    /* Verify CRC */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on measurement 0x%02X\n", cmd);
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int log_data(float temp, float hum)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose log failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int reset_sensor(void)
{
    if (i2c_write_cmd(CMD_RESET) != 0)
        return -1;
    usleep(15000); /* reset takes ~15 ms */
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Reset sensor to ensure known state */
    if (reset_sensor() != 0) {
        fprintf(stderr, "Sensor reset failed; continuing anyway.\n");
    }

    printf("Greenhouse monitoring started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t raw_h = 0, raw_t = 0;
        float temp = -999.0f, hum = -999.0f;

        /* Read humidity */
        if (read_measurement(&raw_h) != 0) {
            fprintf(stderr, "Humidity read failed; resetting sensor.\n");
            if (reset_sensor() != 0)
                fprintf(stderr, "Sensor reset failed; continuing.\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        /* Read temperature (paired with previous humidity) */
        if (i2c_write_cmd(CMD_READ_PREV_TEMP) != 0) {
            fprintf(stderr, "Temperature read failed; resetting sensor.\n");
            if (reset_sensor() != 0)
                fprintf(stderr, "Sensor reset failed; continuing.\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }
        usleep(10000); /* 10 ms settle */

        if (read_measurement(&raw_t) != 0) {
            fprintf(stderr, "Temperature read failed; resetting sensor.\n");
            if (reset_sensor() != 0)
                fprintf(stderr, "Sensor reset failed; continuing.\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        /* Convert raw values */
        temp = 175.72f * (float)raw_t / 65536.0f - 46.85f;
        hum  = 125.0f * (float)raw_h / 65536.0f - 6.0f;

        /* Log data */
        if (log_data(temp, hum) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        printf("T=%.2f C  H=%.2f %%\n", temp, hum);

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return EXIT_SUCCESS;
}

