        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose log failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int reset_sensor(void)
{
    if (i2c_write_cmd(CMD_RESET) != 0)
        return -1;
    usleep(15000); /* reset takes ~15 ms */
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Reset sensor to ensure known state */
    if (reset_sensor() != 0) {
        fprintf(stderr, "Sensor reset failed; continuing anyway.\n");
    }

    printf("Greenhouse monitoring started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t raw_h = 0, raw_t = 0;
        float temp = -999.0f, hum = -999.0f;

        /* Read humidity */
        if (read_measurement(&raw_h) != 0) {
            fprintf(stderr, "Humidity read failed; resetting sensor.\n");
            if (reset_sensor() != 0)
                fprintf(stderr, "Sensor reset failed; continuing.\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        /* Read temperature (paired with previous humidity) */
        if (i2c_write_cmd(CMD_READ_PREV_TEMP) != 0) {
            fprintf(stderr, "Temperature read failed; resetting sensor.\n");
            if (reset_sensor() != 0)
                fprintf(stderr, "Sensor reset failed; continuing.\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }
        usleep(10000); /* 10 ms settle */

        if (read_measurement(&raw_t) != 0) {
            fprintf(stderr, "Temperature read failed; resetting sensor.\n");
            if (reset_sensor() != 0)
                fprintf(stderr, "Sensor reset failed; continuing.\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        /* Convert raw values */
        temp = 175.72f * (float)raw_t / 65536.0f - 46.85f;
        hum  = 125.0f * (float)raw_h / 65536.0f - 6.0f;

        /* Log data */
        if (log_data(temp, hum) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        printf("T=%.2f C  H=%.2f %%\n", temp, hum);

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return EXIT_SUCCESS;
}

