static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sensor(int handle, int16_t *flow_rate) {
    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device: expected 2 bytes, got %d\n", bytes_read);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *flow_rate = (int16_t)(raw >> 2);
    return 0;
}

static float calculate_flow_rate(int16_t raw_flow) {
    if (raw_flow < 0) raw_flow = 0;
    if (raw_flow > 14745) raw_flow = 14745;
    return (float)raw_flow / 14745.0f * 10.0f;
}

static int set_fan_speed(int gpio, float flow_rate) {
    if (flow_rate < 0.0f) flow_rate = 0.0f;
    if (flow_rate > 10.0f) flow_rate = 10.0f;
    int duty_cycle = (int)(flow_rate / 10.0f * PWM_RANGE);
    if (gpioPWM(gpio, duty_cycle) != 0) {
