        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
