#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* LPS33HW I2C address (SDO tied to GND) */
#define LPS33HW_ADDR 0x5D

/* LPS33HW register addresses */
#define WHO_AM_I_REG   0x0F
#define CTRL_REG1      0x10
#define PRESS_OUT_XL   0x28
#define PRESS_OUT_L    0x29
#define PRESS_OUT_H    0x2A
#define TEMP_OUT_L     0x2B
#define TEMP_OUT_H     0x2C

/* Expected WHO_AM_I value */
#define WHO_AM_I_VAL   0xB1

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int initialize_i2c(void);
static int read_lps33hw(int32_t *pressure, int16_t *temperature);
static void log_data(int32_t pressure, int16_t temperature);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* Initialize I2C communication */
static int initialize_i2c(void) {
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n",
                LPS33HW_ADDR, strerror(errno));
        return -1;
    }

    /* Verify WHO_AM_I */
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    /* Configure CTRL_REG1: BDU=1 (block data update), ODR=10Hz (0x80), ACT=1 (active) */
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0xB0) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* Read pressure and temperature from LPS33HW */
static int read_lps33hw(int32_t *pressure, int16_t *temperature) {
    char buffer[5];

    /* Read 5 bytes starting from PRESS_OUT_XL (0x28) */
    int bytes_read = i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buffer, 5);
    if (bytes_read != 5) {
        fprintf(stderr, "Error reading pressure and temperature data: expected 5 bytes, got %d\n",
                bytes_read);
        return -1;
    }

    /* Combine bytes into 24-bit two's-complement pressure (big-endian) */
    int32_t raw_pressure = ((int32_t)(uint8_t)buffer[2] << 16) |
                          ((int32_t)(uint8_t)buffer[1] << 8)  |
                          ((int32_t)(uint8_t)buffer[0]);
    if (raw_pressure & 0x00800000) {
        raw_pressure |= 0xFF000000; /* Sign extend */
    }

    /* Combine bytes into 16-bit two's-complement temperature (big-endian) */
    int16_t raw_temperature = ((int16_t)(uint8_t)buffer[4] << 8) |
                             ((int16_t)(uint8_t)buffer[3]);

    *pressure = raw_pressure;
    *temperature = raw_temperature;

    return 0;
}

/* Log data to file and stderr */
static void log_data(int32_t pressure, int16_t temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n",
            timestamp, (float)pressure / 4096.0f, (float)temperature / 480.0f);
    fflush(log_file);

    fprintf(stderr, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n",
            timestamp, (float)pressure / 4096.0f, (float)temperature / 480.0f);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering signal handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    int32_t pressure;
    int16_t temperature;

    /* Main loop */
    while (!terminate) {
        if (read_lps33hw(&pressure, &temperature) == 0) {
            log_data(pressure, temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        gpioDelay(1000000); /* 1 second delay */
    }

    /* Cleanup */
    cleanup();

    return EXIT_SUCCESS;
}

