#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define STLM75_ADDR    0x48
#define TEMP_REG       0x00
#define LED_GPIO       17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define POLL_DELAY_US  1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature from STLM75.                                     */
/* Returns 0 on success (temp stored in *out_temp), -1 on error.       */
/* ------------------------------------------------------------------ */
static int read_temperature(int handle, float *out_temp)
{
