#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SDP32_ADDR 0x21
#define I2C_BUS 1
#define DEFAULT_INTERVAL_MS 1000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int interval_ms = DEFAULT_INTERVAL_MS;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sdp32(int handle, float *pressure_pa) {
    uint8_t cmd[2] = {0x36, 0x2F};
    uint8_t buf[9];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(10000);

        int bytes_read = i2cReadDevice(handle, (char *)buf, 9);
        if (bytes_read != 9) {
            fprintf(stderr, "I2C read failed (attempt %d/%d, got %d bytes)\n", retries + 1, MAX_RETRIES, bytes_read);
            retries++;
            gpioDelay(10000);
            continue;
        }

        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "Pressure CRC mismatch (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        if (crc8(&buf[6], 2) != buf[8]) {
            fprintf(stderr, "Scale-factor CRC mismatch (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

        if (scale_factor == 0) {
            fprintf(stderr, "Invalid scale factor (0) (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        *pressure_pa = (float)raw_pressure / (float)scale_factor;
        return 0;
    }

    return -1;
}

static void log_data(float pressure_pa) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Pressure: %.2f Pa\n", timestamp, pressure_pa);
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    if (argc > 1) {
        interval_ms = atoi(argv[1]);
        if (interval_ms <= 0) {
            fprintf(stderr, "Invalid interval. Using default: %d ms\n", DEFAULT_INTERVAL_MS);
            interval_ms = DEFAULT_INTERVAL_MS;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X on bus %d\n", SDP32_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SDP32 Differential Pressure Sensor Reader\n");
    printf("I2C Bus: %d, Address: 0x%02X, Interval: %d ms\n", I2C_BUS, SDP32_ADDR, interval_ms);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        float pressure_pa;

        if (read_sdp32(i2c_handle, &pressure_pa) == 0) {
            log_data(pressure_pa);
        } else {
            fprintf(stderr, "Failed to read SDP32 sensor after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(interval_ms * 1000);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

