#define I2C_BUS        1
#define SDP810_ADDR    0x25
#define CMD_CONT_MEAS  0x3615
#define MEAS_DELAY_US  45000   /* 45 ms conversion time */
#define LOOP_DELAY_US  1000000 /* 1 s between readings */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only, do not call blocking functions.    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)                */
/* ------------------------------------------------------------------ */
static bool crc8_ok(const uint8_t *data, int len, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc == expected;
}

/* ------------------------------------------------------------------ */
/* Send a 16-bit command to the SDP810                                 */
/* ------------------------------------------------------------------ */
static bool sdp810_write_cmd(uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(g_i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed for command 0x%04X\n", cmd);
        return false;
    }
    return true;
}

/* ------------------------------------------------------------------ */
/* Read 9 bytes from the SDP810: pressure(2)+crc, temp(2)+crc, scale(2)+crc */
/* Returns true on success, false on any I/O error.                    */
/* ------------------------------------------------------------------ */
static bool sdp810_read_data(int16_t *raw_pressure, int16_t *raw_temperature,
                            int16_t *scale_pressure, int16_t *scale_temperature)
{
    uint8_t buf[9];

    if (i2cReadDevice(g_i2c_handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (sensor absent or bus error)\n");
        return false;
    }

    /* Validate CRC for each 3-byte word */
    if (!crc8_ok(&buf[0], 2, buf[2])) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return false;
    }
    if (!crc8_ok(&buf[3], 2, buf[5])) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return false;
    }
    if (!crc8_ok(&buf[6], 2, buf[8])) {
        fprintf(stderr, "[ERROR] Scale CRC mismatch\n");
        return false;
    }

    *raw_pressure     = (int16_t)((buf[0] << 8) | buf[1]);
    *raw_temperature  = (int16_t)((buf[3] << 8) | buf[4]);
    *scale_pressure   = (int16_t)((buf[6] << 8) | buf[7]);
    *scale_temperature = (int16_t)((buf[8] << 8) | buf[9]);

    return true;
}

/* ------------------------------------------------------------------ */
