    }

    /* Wait for first conversion to complete */
    gpioDelay(MEAS_DELAY_US);

    while (g_running) {
        int16_t raw_pressure, raw_temperature, scale_pressure, scale_temperature;

        if (!sdp810_read_data(&raw_pressure, &raw_temperature,
                             &scale_pressure, &scale_temperature)) {
            fprintf(stderr, "[WARN] Read failed; retrying next cycle\n");
        } else {
            float pressure_pa, temperature_c;
