#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HDC1000_ADDR        0x40
#define TEMP_REG            0x00
#define CONFIG_REG          0x02
#define CONFIG_MEASURE_14BIT 0x1000  /* bit 12 = 1, bits 11-9 = 001 (14-bit) */
#define I2C_BUS             "/dev/i2c-1"
#define SAMPLE_INTERVAL_SEC 5
#define CONVERSION_DELAY_MS 20

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value to a 16-bit register pointer (big-endian on the bus). */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read N bytes starting at a 16-bit register pointer (big-endian on the bus). */
static int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu bytes: %s\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read temperature and humidity from the HDC1000. Returns 0 on success, -1 on error. */
static int read_hdc1000(int fd, float *temperature, float *humidity)
{
    /* Trigger a 14-bit measurement by writing the temperature register pointer. */
    if (i2c_write_reg16(fd, TEMP_REG, 0x0000) < 0)
        return -1;

    /* Wait for the conversion to complete (DRDYn pin is not connected). */
    usleep(CONVERSION_DELAY_MS * 1000);

    /* Read 4 bytes: 2 bytes temperature, 2 bytes humidity. */
    uint8_t data[4];
    if (i2c_read_regs(fd, TEMP_REG, data, sizeof(data)) < 0)
        return -1;

    uint16_t raw_temp = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_hum  = ((uint16_t)data[2] << 8) | data[3];

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_hum  / 65536.0f) * 100.0f;

    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus. */
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the I2C slave address. */
    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                HDC1000_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Configure the sensor: enable 14-bit measurement, continuous mode. */
    if (i2c_write_reg16(fd, CONFIG_REG, CONFIG_MEASURE_14BIT) < 0) {
        fprintf(stderr, "Failed to configure HDC1000.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("HDC1000 initialized on %s at address 0x%02X. Logging every %d seconds.\n",
           I2C_BUS, HDC1000_ADDR, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature, humidity;

        if (read_hdc1000(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read HDC1000 data.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++)
            sleep(1);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

