#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ICP10101_ADDR  0x63
#define CMD_READ_OTP   0x50
#define CMD_MEASURE    0x40
#define MEASURE_DELAY_US 7000
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_otp(int handle, uint16_t *scale_factor_lut, uint16_t *scale_factor_h, uint16_t *scale_factor_p) {
    uint8_t cmd = CMD_READ_OTP;
    uint8_t buf[8];

    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to write OTP read command\n");
        return -1;
    }

    gpioDelay(1000);

    int bytes_read = i2cReadDevice(handle, (char *)buf, 8);
    if (bytes_read != 8) {
        fprintf(stderr, "Error: Failed to read OTP data (got %d bytes, expected 8)\n", bytes_read);
        return -1;
    }

    *scale_factor_lut = (uint16_t)((buf[0] << 8) | buf[1]);
    *scale_factor_h  = (uint16_t)((buf[2] << 8) | buf[3]);
    *scale_factor_p  = (uint16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

static int read_sensor(int handle, float *temperature, float *pressure) {
    uint8_t cmd = CMD_MEASURE;
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to write measurement command\n");
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    int bytes_read = i2cReadDevice(handle, (char *)buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error: Failed to read measurement data (got %d bytes, expected 6)\n", bytes_read);
        return -1;
    }

    if (buf[0] == 0xFF && buf[1] == 0xFF && buf[2] == 0xFF && buf[3] == 0xFF && buf[4] == 0xFF && buf[5] == 0xFF) {
        fprintf(stderr, "Error: Sensor returned all 0xFF bytes (sensor absent or bus error)\n");
        return -1;
    }

    int32_t raw_temperature = (int32_t)((buf[0] << 8) | buf[1]);
    int32_t raw_pressure    = (int32_t)((buf[2] << 8) | buf[3]);

    uint16_t scale_factor_lut, scale_factor_h, scale_factor_p;
    if (read_otp(handle, &scale_factor_lut, &scale_factor_h, &scale_factor_p) != 0) {
        return -1;
    }

    float t_comp = (float)raw_temperature / (float)scale_factor_lut;
    float p_comp = (float)raw_pressure / (float)scale_factor_p;

    *temperature = t_comp * 0.02f - 273.15f;
    *pressure    = p_comp * 0.01f;

    return 0;
}

static void log_data(float temperature, float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ICP10101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d (handle=%d)\n",
                ICP10101_ADDR, I2C_BUS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t scale_factor_lut, scale_factor_h, scale_factor_p;
    if (read_otp(g_i2c_handle, &scale_factor_lut, &scale_factor_h, &scale_factor_p) != 0) {
        fprintf(stderr, "Error: Failed to read OTP data. Sensor may be absent or bus error.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ICP-10101 initialized. Logging every %d seconds. Press Ctrl+C to stop.\n", SAMPLE_INTERVAL_S);

    while (g_running) {
        float temperature, pressure;

        if (read_sensor(g_i2c_handle, &temperature, &pressure) == 0) {
            log_data(temperature, pressure);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, will retry next cycle\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

