    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_pressure(int fd, float *pressure)
{
    if (i2c_write_byte(fd, PRESSURE_REG, MEASURE_CMD) < 0)
        return -1;

    usleep(10000); /* 10 ms measurement delay */

    uint16_t raw;
    if (i2c_read_word(fd, PRESSURE_REG, &raw) < 0)
        return -1;

    *pressure = (float)raw * SCALE_FACTOR;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MLX90819_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MLX90819 pressure sensor reader started on %s (addr 0x%02X).\n",
           I2C_BUS, MLX90819_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float pressure;
        if (read_pressure(fd, &pressure) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            if (localtime_r(&now, &tm_info) != NULL &&
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
                printf("[%s] Pressure: %.2f kPa\n", ts, pressure);
            } else {
                printf("[unknown time] Pressure: %.2f kPa\n", pressure);
            }
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read pressure data.\n");
        }
        sleep(POLL_INTERVAL);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

