#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MLX90821_ADDR  0x40
#define PRESSURE_REG   0x00
#define PRESSURE_SCALE 0.01f
#define PRESSURE_WARN_MIN 200.0f
#define PRESSURE_WARN_MAX 250.0f
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_US      1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, MLX90821_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure_out)
{
    char buf[2];
    int rc = i2cReadI2CBlockData(g_i2c_handle, PRESSURE_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading pressure register (rc=%d)\n", rc);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *pressure_out = (float)raw * PRESSURE_SCALE;
    return 0;
}

static void log_pressure(float pressure)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    if (fprintf(g_log_file, "%s,%.2f\n", ts, pressure) < 0) {
        perror("Error writing to log file");
        return;
    }
    fflush(g_log_file);
}

static void check_pressure_warning(float pressure)
{
    if (pressure < PRESSURE_WARN_MIN || pressure > PRESSURE_WARN_MAX) {
        fprintf(stderr, "Warning: Pressure %.2f kPa out of range [%.0f, %.0f]\n",
                pressure, PRESSURE_WARN_MIN, PRESSURE_WARN_MAX);
    }
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
