#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define HIH6130_ADDR 0x27
#define I2C_BUS 1
#define LOG_FILE "environmental_data.log"
#define SAMPLE_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_US 40000
#define LOG_FILE_SIZE_MB 1

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hih6130(int handle, float *temperature, float *humidity) {
    char cmd = 0x00;
    char buf[4];
    int result;

    result = i2cWriteDevice(handle, &cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    result = i2cReadDevice(handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw_t = ((uint16_t)(buf[0] & 0x03) << 8) | (uint8_t)buf[1];
    uint16_t raw_h = ((uint16_t)(buf[2] & 0x03) << 8) | (uint8_t)buf[3];

    if ((buf[0] & 0x0C) != 0x00) {
        fprintf(stderr, "Sensor status error: 0x%02X\n", buf[0]);
        return -1;
    }

    *temperature = (float)raw_t * 165.0f / 16383.0f - 40.0f;
    *humidity = (float)raw_h * 100.0f / 16383.0f;

    return 0;
}

static int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fclose(fp);

    return 0;
}

static int check_log_size(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        return 0;
    }

    fseek(fp, 0, SEEK_END);
    long size = ftell(fp);
    fclose(fp);

    return (size / 1024 / 1024) > LOG_FILE_SIZE_MB;
}

int main(void) {
    float temperature, humidity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HIH6130 environmental monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_hih6130(i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

            if (log_data(LOG_FILE, temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            if (check_log_size(LOG_FILE)) {
                printf("Log file exceeds size, truncating...\n");
                FILE *fp = fopen(LOG_FILE, "w");
                if (fp != NULL) {
                    fprintf(fp, "Log file truncated due to size.\n");
                    fclose(fp);
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

