#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENT_GPIO 4
#define TICK_US 3
#define SYNC_TICKS 56
#define STATUS_NIBBLES 1
#define DATA_NIBBLES 3
#define CHECKSUM_NIBBLES 1
#define PULSE_MIN_TICKS 12
#define PULSE_MAX_TICKS 813
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    gpioSetMode(SENT_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENT_GPIO, PI_PUD_UP);
    return 0;
}

static int read_sent_nibbles(int *nibbles) {
    int ticks = 0;
    int nibble = 0;
    int nibble_idx = 0;
    int timeout = 0;

    while (nibble_idx < STATUS_NIBBLES + DATA_NIBBLES + CHECKSUM_NIBBLES) {
        ticks = gpioTick();
        if (ticks < 0) {
            fprintf(stderr, "Error: gpioTick failed.\n");
            return -1;
        }

        if (ticks > PULSE_MAX_TICKS) {
            fprintf(stderr, "Error: Timeout waiting for nibble %d.\n", nibble_idx);
            return -1;
        }

        if (ticks > PULSE_MIN_TICKS) {
            if (timeout) {
                timeout = 0;
                nibble_idx++;
                if (nibble_idx >= STATUS_NIBBLES + DATA_NIBBLES + CHECKSUM_NIBBLES) {
                    break;
                }
                nibble = 0;
            } else {
                nibble = (nibble << 1) | 1;
            }
        } else {
            timeout = 1;
        }
    }

    if (nibble_idx < STATUS_NIBBLES + DATA_NIBBLES + CHECKSUM_NIBBLES) {
        fprintf(stderr, "Error: Incomplete SENT frame.\n");
        return -1;
    }

    for (int i = 0; i < STATUS_NIBBLES + DATA_NIBBLES + CHECKSUM_NIBBLES; i++) {
        nibbles[i] = nibble;
    }
    return 0;
}

static int validate_checksum(const int *nibbles) {
    int checksum = 0;
    for (int i = 0; i < STATUS_NIBBLES + DATA_NIBBLES; i++) {
        checksum += nibbles[i];
    }
    return (checksum % 16) == nibbles[STATUS_NIBBLES + DATA_NIBBLES];
}

static float convert_to_pressure(const int *nibbles) {
    int raw = (nibbles[0] << 8) | (nibbles[1] << 4) | nibbles[2];
    return (float)raw * 0.001f;
}

static void log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file %s.\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    printf("Brake pressure monitoring started on GPIO %d. Press Ctrl+C to exit.\n", SENT_GPIO);

    while (running) {
        int nibbles[STATUS_NIBBLES + DATA_NIBBLES + CHECKSUM_NIBBLES];
        if (read_sent_nibbles(nibbles) != 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (!validate_checksum(nibbles)) {
            fprintf(stderr, "Error: Checksum mismatch.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float pressure = convert_to_pressure(nibbles);
        log_pressure(pressure);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioTerminate();
    printf("Brake pressure monitoring stopped.\n");
    return 0;
}

