#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_SEC 5
#define LOG_FILE "temperature_log.dat"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureReading;

static TemperatureReading temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temperature) {
    char reg = TEMP_REG;
    char buf[2];

    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: Failed to write temperature register address: %s\n", strerror(errno));
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read temperature data: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw_temp = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (float)raw_temp * 0.0078125f;
    return 0;
}

static void add_reading(float temperature) {
    time(&temperature_buffer[buffer_index].timestamp);
    temperature_buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void flush_buffer_to_file(void) {
    FILE *fp = fopen(LOG_FILE, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    size_t written = fwrite(temperature_buffer, sizeof(TemperatureReading), buffer_count, fp);
    if (written != (size_t)buffer_count) {
        fprintf(stderr, "Warning: Only wrote %zu of %d temperature readings to log file\n", written, buffer_count);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: Failed to close log file: %s\n", strerror(errno));
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d: %s\n",
                TMP117_ADDR, I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler: %s\n", strerror(errno));
    }

    printf("TMP117 temperature logger started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            add_reading(temperature);
            printf("Temperature: %.4f °C\n", temperature);
        } else {
            fprintf(stderr, "Error: Failed to read temperature, skipping sample\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    printf("\nShutting down...\n");
    flush_buffer_to_file();
    cleanup();
    printf("Program terminated successfully.\n");
    return EXIT_SUCCESS;
}

