#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SI7202_ADDR 0x40
#define I2C_BUS 1
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X on bus %d: %s\n",
                SI7202_ADDR, I2C_BUS, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int16_t *raw_field, int16_t *raw_temp) {
    char buf[4];
    int result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: expected 4 bytes, got %d: %s\n",
                result, strerror(errno));
        return -1;
    }
    *raw_field = (int16_t)((buf[0] << 8) | buf[1]);
    *raw_temp = (int16_t)((buf[2] << 8) | buf[3]);
    return 0;
}

static float convert_to_gauss(int16_t raw_value) {
    return (float)raw_value * 0.1f;
}

static float convert_to_celsius(int16_t raw_value) {
    return (float)raw_value * 0.01f - 25.0f;
}

static int log_data(float magnetic_field, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.4f,%.4f\n", timestamp, magnetic_field, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int log_error_data(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,NaN,NaN\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int16_t raw_field, raw_temp;
    float magnetic_field, temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (initialize_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        if (fprintf(log_file, "Timestamp,Magnetic Field (Gauss),Temperature (Celsius)\n") < 0) {
            fprintf(stderr, "Error writing header to log file: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Error flushing header to log file: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting rotational speed measurement. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_sensor_data(&raw_field, &raw_temp) == 0) {
            magnetic_field = convert_to_gauss(raw_field);
            temperature = convert_to_celsius(raw_temp);

            if (log_data(magnetic_field, temperature) != 0) {
                fprintf(stderr, "Error logging data, continuing...\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, logging error...\n");
            if (log_error_data() != 0) {
                fprintf(stderr, "Error logging error data, continuing...\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

