#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define LOG_FILE "dht11_readings.txt"
#define SAMPLE_INTERVAL_US 2000000  /* 2 seconds */
#define MAX_RETRIES 3
#define TIMEOUT_US 100000          /* 100 ms timeout for a bit-level phase */

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single bit to the DHT11 line                                */
/* ------------------------------------------------------------------ */
static int dht11_write_bit(int bit)
{
    if (gpioWrite(DHT11_GPIO, bit) < 0) {
        fprintf(stderr, "[ERROR] gpioWrite(bit %d) failed\n", bit);
        return -1;
    }
    gpioDelay(bit ? 50 : 26);  /* 26 us low, 50 us high for '1' */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single bit from the DHT11 line                                */
/* Returns 0 or 1 on success, -1 on timeout/error                      */
/* ------------------------------------------------------------------ */
static int dht11_read_bit(void)
{
    uint32_t start_tick, end_tick;

    /* Wait for line to go low (sensor response start) */
    start_tick = gpioTick();
    while (gpioRead(DHT11_GPIO) == 1) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "[ERROR] DHT11 response timeout (low)\n");
            return -1;
        }
    }

    /* Measure high-pulse duration to determine bit value */
    start_tick = gpioTick();
    while (gpioRead(DHT11_GPIO) == 0) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "[ERROR] DHT11 response timeout (high start)\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    return (pulse_us > 50) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Read 40 data bits from the DHT11                                    */
/* Returns 0 on success, -1 on timeout/error                          */
/* ------------------------------------------------------------------ */
static int dht11_read_data(uint8_t data[5])
{
    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < 8; j++) {
            if (dht11_read_bit() < 0)
                return -1;
            data[i] <<= 1;
            if (dht11_read_bit() == 1)
                data[i] |= 1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Validate DHT11 checksum                                             */
/* ------------------------------------------------------------------ */
static int dht11_validate(const uint8_t data[5])
{
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    return (checksum == data[4]) ? 0 : -1;
}

/* ------------------------------------------------------------------ */
/* Convert raw DHT11 data to temperature (Celsius) and humidity (%RH)   */
/* ------------------------------------------------------------------ */
static void dht11_convert(const uint8_t data[5], float *temperature, float *humidity)
{
    uint16_t raw_humidity = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t raw_temperature = (uint16_t)((data[2] << 8) | data[3]);

    *humidity = (float)raw_humidity / 10.0f;
    *temperature = (float)raw_temperature / 10.0f;
}

/* ------------------------------------------------------------------ */
/* Log a reading with timestamp to the log file                         */
/* ------------------------------------------------------------------ */
static void log_reading(float temperature, float humidity)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return;
    }

    if (log_fp == NULL) {
        fprintf(stderr, "[ERROR] Log file not open\n");
        return;
    }

    if (fprintf(log_fp, "%s, Temperature: %.2f C, Humidity: %.2f %%RH\n",
                timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
    }
    if (fflush(log_fp) != 0) {
        fprintf(stderr, "[ERROR] fflush log failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Read DHT11 sensor with retries                                       */
/* Returns 0 on success, -1 on failure                                  */
/* ------------------------------------------------------------------ */
static int read_dht11(float *temperature, float *humidity)
{
    uint8_t data[5] = {0};
    int success = 0;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (dht11_write_bit(0) < 0)
            continue;
        if (dht11_write_bit(1) < 0)
            continue;
        if (dht11_write_bit(0) < 0)
            continue;

        /* Switch to input mode (pull-up on DHT11) */
        gpioSetMode(DHT11_GPIO, PI_INPUT);
        gpioSetPullUpDown(DHT11_GPIO, PI_PUD_UP);

        /* Wait for sensor response (response low ~80 us) */
        uint32_t start_tick = gpioTick();
        while (gpioRead(DHT11_GPIO) == 1) {
            if ((gpioTick() - start_tick) > TIMEOUT_US) {
                fprintf(stderr, "[ERROR] DHT11 response timeout (response high)\n");
                continue;
            }
        }

        if (dht11_read_data(data) == 0) {
            if (dht11_validate(data) == 0) {
                dht11_convert(data, temperature, humidity);
                success = 1;
                break;
            } else {
                fprintf(stderr, "[ERROR] DHT11 checksum mismatch\n");
            }
        } else {
            fprintf(stderr, "[ERROR] DHT11 read failed\n");
        }
    }

    return success ? 0 : -1;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — release GPIO resources and close log file          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO 4 as output, initially low */
    if (gpioSetMode(DHT11_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode failed for GPIO %d\n", DHT11_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(DHT11_GPIO, 0) < 0) {
        fprintf(stderr, "[FATAL] gpioWrite failed for GPIO %d\n", DHT11_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    float temperature, humidity;

    printf("DHT11 sensor reader started on GPIO %d. Press Ctrl+C to exit.\n",
           DHT11_GPIO);

    /* Main sampling loop */
    while (running) {
        if (read_dht11(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%RH\n",
                   temperature, humidity);
            log_reading(temperature, humidity);
        } else {
            fprintf(stderr, "[WARN] DHT11 read failed after %d retries\n",
                    MAX_RETRIES);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && running; i++) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

