#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

#define SHT31D_ADDR 0x44
#define MEASURE_CMD_HIGH 0x2C
#define MEASURE_CMD_LOW 0x06
#define MEASUREMENT_DELAY_US 20000
#define RETRY_COUNT 3
#define LOG_FILE "sht31d_data.log"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sht31d(float *temperature, float *humidity) {
    uint8_t cmd[2] = {MEASURE_CMD_HIGH, MEASURE_CMD_LOW};
    uint8_t data[6];
    int result;

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        if (result == 0) {
            gpioDelay(MEASUREMENT_DELAY_US);
            result = i2cReadDevice(i2c_handle, (char *)data, 6);
            if (result == 6) {
                if (crc8(data, 2) == data[2]) {
                    if (crc8(data + 3, 2) == data[5]) {
                        uint16_t temp_raw = (data[0] << 8) | data[1];
                        uint16_t hum_raw = (data[3] << 8) | data[4];
                        *temperature = -45.0f + (175.0f * temp_raw) / 65535.0f;
                        *humidity = 100.0f * hum_raw / 65535.0f;
                        return 0;
                    } else {
                        fprintf(stderr, "CRC mismatch on humidity data (attempt %d)\n", attempt + 1);
                    }
                } else {
                    fprintf(stderr, "CRC mismatch on temperature data (attempt %d)\n", attempt + 1);
                }
            } else {
                fprintf(stderr, "I2C read failed (attempt %d): %d\n", attempt + 1, result);
            }
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", attempt + 1, result);
        }
        gpioDelay(100000);
    }
    return -1;
}

static void log_data(float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float temperature, humidity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SHT31D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", SHT31D_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        if (read_sht31d(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read SHT31D after %d retries\n", RETRY_COUNT);
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s,ERROR,Failed to read SHT31D after %d retries\n", timestamp, RETRY_COUNT);
            fflush(log_file);
        }

        gpioDelay(5000000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

