static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_cct(int handle, uint16_t *cct) {
    char buf[CCT_REG_LEN];
    int result = i2cReadI2CBlockData(handle, CCT_REG, buf, CCT_REG_LEN);
    if (result != CCT_REG_LEN) {
        fprintf(stderr, "Error reading CCT from handle %d: expected %d bytes, got %d\n",
                handle, CCT_REG_LEN, result);
        return -1;
    }
    *cct = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int read_device_id(int handle, uint8_t *id) {
    int result = i2cReadByteData(handle, DEVICE_ID_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading device ID from handle %d\n", handle);
        return -1;
    }
    *id = (uint8_t)result;
    return 0;
}

static int verify_sensor(int handle) {
    uint8_t id;
    if (read_device_id(handle, &id) != 0) {
        return -1;
    }
    if (id != DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID 0x%02X (expected 0x%02X) on handle %d\n",
                id, DEVICE_ID, handle);
        return -1;
    }
    return 0;
}

static int log_cct(FILE *fp, float cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f\n", timestamp, cct) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n",
                SENSOR1_ADDR, i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n",
                SENSOR2_ADDR, i2c_handle2);
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
        gpioTerminate();
        return 1;
    }

    if (verify_sensor(i2c_handle1) != 0) {
        fprintf(stderr, "Sensor 1 at 0x%02X not detected\n", SENSOR1_ADDR);
        cleanup();
        return 1;
    }
    if (verify_sensor(i2c_handle2) != 0) {
        fprintf(stderr, "Sensor 2 at 0x%02X not detected\n", SENSOR2_ADDR);
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
        fflush(log_file);
    }

    printf("Starting CCT logging. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t cct1 = 0, cct2 = 0;
        int ok1 = (read_cct(i2c_handle1, &cct1) == 0);
        int ok2 = (read_cct(i2c_handle2, &cct2) == 0);

        if (ok1 && ok2) {
            float avg_cct = (float)(cct1 + cct2) / 2.0f;
            if (log_cct(log_file, avg_cct) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read error, skipping log entry\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

