#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>

#define I2C_BUS        1
#define LM75B_ADDR     0x48
#define TEMP_REG       0x00
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD_HIGH 28.0f
#define TEMP_THRESHOLD_LOW  26.0f
#define POLL_INTERVAL_US 1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* Circular buffer of temperature readings (60 samples) */
static float g_temperature_buffer[BUFFER_SIZE];
static int   g_buffer_index = 0;
static int   g_buffer_count = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature from LM75B via I2C                                 */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int read_temperature(int handle, float *temperature)
{
    char reg = (char)TEMP_REG;
    char buf[2];

    /* Write the register pointer */
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed (reg select)\n");
        return -1;
    }

    /* Read 2 bytes of temperature data */
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadDevice failed (temperature data)\n");
        return -1;
    }

    /* LM75B: 9-bit two's complement, D9-D1 = bits 1-8, D0 = bit 0 */
    int16_t raw = (int16_t)(((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    raw >>= 1;  /* right-justify 9-bit value */

    /* Sign-extend from 9 bits to 16 bits */
    if (raw & 0x0001) {
        raw |= 0xFF00;
    }

    *temperature = (float)raw * 0.5f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Add a temperature reading to the circular buffer                    */
/* ------------------------------------------------------------------ */
static void add_to_buffer(float temperature)
{
    g_temperature_buffer[g_buffer_index] = temperature;
    g_buffer_index = (g_buffer_index + 1) % BUFFER_SIZE;
    if (g_buffer_count < BUFFER_SIZE) {
        g_buffer_count++;
    }
}

/* ------------------------------------------------------------------ */
/* Compute the running average of the temperature readings            */
/* ------------------------------------------------------------------ */
static float calculate_average(void)
{
    if (g_buffer_count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < g_buffer_count; i++) {
        sum += g_temperature_buffer[i];
    }
    return sum / (float)g_buffer_count;
}

/* ------------------------------------------------------------------ */
/* Control the cooling fan based on the running average                 */
/* ------------------------------------------------------------------ */
static void control_fan(float average_temperature)
{
    int fan_state = (average_temperature > TEMP_THRESHOLD_HIGH) ? 1 : 0;

    if (gpioWrite(FAN_GPIO, fan_state) != 0) {
        fprintf(stderr, "Warning: gpioWrite failed for fan GPIO %d\n", FAN_GPIO);
    } else {
        printf("Fan %s (avg=%.2f C)\n", fan_state ? "ON" : "OFF", average_temperature);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call even if pigpio is not initialized     */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at LM75B address 0x48 */
    g_i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure fan GPIO as output, initially off */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for fan GPIO %d\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LM75B temperature monitor started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        float temperature;

        if (read_temperature(g_i2c_handle, &temperature) == 0) {
            add_to_buffer(temperature);
            float average = calculate_average();
            control_fan(average);
            printf("Temperature: %.2f C, Average: %.2f C\n", temperature, average);
        } else {
            fprintf(stderr, "Error: Failed to read temperature, retrying next cycle...\n");
        }

        /* Sleep 1 second, checking g_running every 100 ms to allow prompt exit */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

