            add_to_buffer(temperature);
            float average = calculate_average();
            control_fan(average);
            printf("Temperature: %.2f C, Average: %.2f C\n", temperature, average);
        } else {
            fprintf(stderr, "Error: Failed to read temperature, retrying next cycle...\n");
        }

        /* Sleep 1 second, checking g_running every 100 ms to allow prompt exit */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

