#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI7021_ADDR        0x40
#define I2C_BUS            1
#define LOG_FILE           "environment.log"
#define SAMPLE_INTERVAL_S  60
#define MAX_RETRIES        3
#define MEASURE_DELAY_US   20000   /* 20 ms for no-hold commands */

/* Si7021 commands (single-byte, no register address) */
#define CMD_MEASURE_RH_NH   0xF5
#define CMD_MEASURE_TEMP_NH 0xF3
#define CMD_READ_PREV_RH    0xE0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte command to the Si7021 */
static int si7021_write_cmd(int handle, uint8_t cmd)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, (char *)&cmd, 1);
        if (rc == 0)
            return 0;
        fprintf(stderr, "[WARN] i2cWriteDevice(0x%02X) failed (attempt %d/%d): rc=%d\n",
                cmd, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(10000); /* 10 ms backoff */
    }
    return -1;
}

/* Read 2 bytes from the Si7021 (big-endian) */
static int si7021_read_bytes(int handle, uint8_t *buf, uint32_t len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == (int)len)
            return 0;
        fprintf(stderr, "[WARN] i2cReadDevice(%u bytes) failed (attempt %d/%d): rc=%d\n",
                len, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(10000);
    }
    return -1;
}

/*
 * Read temperature from the Si7021.
 * Returns 0 on success and stores temperature in *temp_c.
 * Returns -1 on persistent failure.
 */
static int si7021_read_temperature(int handle, float *temp_c)
{
    if (si7021_write_cmd(handle, CMD_MEASURE_TEMP_NH) != 0)
        return -1;

    gpioDelay(MEASURE_DELAY_US);

    uint8_t buf[2];
    if (si7021_read_bytes(handle, buf, sizeof(buf)) != 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp_c = 175.72f * (float)raw / 65536.0f - 46.85f;
    return 0;
}

/*
 * Read humidity from the Si7021.
 * Returns 0 on success and stores humidity in *humidity_pct.
 * Returns -1 on persistent failure.
 */
static int si7021_read_humidity(int handle, float *humidity_pct)
{
    if (si7021_write_cmd(handle, CMD_MEASURE_RH_NH) != 0)
        return -1;

    gpioDelay(MEASURE_DELAY_US);

    uint8_t buf[2];
    if (si7021_read_bytes(handle, buf, sizeof(buf)) != 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *humidity_pct = 125.0f * (float)raw / 65536.0f - 6.0f;
    if (*humidity_pct < 0.0f)   *humidity_pct = 0.0f;
    if (*humidity_pct > 100.0f) *humidity_pct = 100.0f;
    return 0;
}

/*
 * Read humidity from the Si7021 using the previous RH measurement.
 * Returns 0 on success and stores humidity in *humidity_pct.
 * Returns -1 on persistent failure.
 */
static int si7021_read_prev_humidity(int handle, float *humidity_pct)
{
    if (si7021_write_cmd(handle, CMD_READ_PREV_RH) != 0)
        return -1;

    gpioDelay(MEASURE_DELAY_US);

    uint8_t buf[2];
    if (si7021_read_bytes(handle, buf, sizeof(buf)) != 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *humidity_pct = 125.0f * (float)raw / 65536.0f - 6.0f;
    if (*humidity_pct < 0.0f)   *humidity_pct = 0.0f;
    if (*humidity_pct > 100.0f) *humidity_pct = 100.0f;
    return 0;
}

/*
 * Log a reading to the CSV file and stdout.
 */
static void log_reading(float temperature, float humidity)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "[ERROR] Cannot open %s for appending\n", LOG_FILE);
        return;
    }
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fclose(fp);

    printf("%s,%.2f,%.2f\n", ts, temperature, humidity);
    fflush(stdout);
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI7021_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed: %s\n", strerror(errno));
    }

    /* --- Verify sensor presence --- */
    uint8_t id = 0;
    if (si7021_read_bytes(g_i2c_handle, &id, 1) != 0) {
        fprintf(stderr, "[FATAL] Si7021 not responding at 0x%02X\n", SI7021_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Si7021 detected (ID=0x%02X)\n", id);

    /* --- Main sampling loop --- */
    while (g_running) {
        float temperature = 0.0f, humidity = 0.0f;
        int ok = 0;

        if (si7021_read_temperature(g_i2c_handle, &temperature) == 0) {
            if (si7021_read_humidity(g_i2c_handle, &humidity) == 0) {
                ok = 1;
            } else {
                fprintf(stderr, "[WARN] Failed to read humidity after temperature\n");
            }
        } else {
            fprintf(stderr, "[WARN] Failed to read temperature\n");
        }

        if (ok) {
            log_reading(temperature, humidity);
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed after %d retries\n", MAX_RETRIES);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

