#define HDC1080_ADDR 0x40
#define CONFIG_REG 0x02
#define TEMP_REG 0x00
#define HUMID_REG 0x01
#define LOG_FILE "enviro_log.txt"
#define I2C_BUS 1
#define CONVERSION_DELAY_US 25000
#define SAMPLE_INTERVAL_US 5000000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_hdc1080(int handle) {
    /*
     * Config register (0x02):
     *   Bit 15: Heater enable (0 = disabled)
     *   Bits 14:12: Temperature resolution (110 = 14-bit)
     *   Bits 11:9: Humidity resolution (110 = 14-bit)
     *   Bit 8:    Heater power (0 = off)
     *   Bits 7:5:   Heater frequency (000 = off)
     *   Bit 4:    Heater mode (0 = off)
     *   Bits 3:1:   Heater current (000 = off)
     *   Bit 0:    Heater enable (0 = disabled)
     *
     * Value: 0x4000 = 1100 0000 0000 0000
     */
    if (i2cWriteWordData(handle, CONFIG_REG, 0x4000) < 0) {
        fprintf(stderr, "Error: Failed to write configuration register.\n");
        return -1;
    }
    return 0;
}

static int read_hdc1080(int handle, float *temperature, float *humidity) {
    char buf[4];

    /* Point to temperature register (0x00) */
    if (i2cWriteByte(handle, TEMP_REG) < 0) {
        fprintf(stderr, "Error: Failed to set temperature register pointer.\n");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(CONVERSION_DELAY_US);

    /* Read 4 bytes: 2 bytes temperature, 2 bytes humidity */
    if (i2cReadDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "Error: Failed to read 4 bytes from HDC1080.\n");
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t raw_humidity = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_humidity / 65536.0f) * 100.0f;

    return 0;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d.\n", HDC1080_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_hdc1080(i2c_handle) < 0) {
        fprintf(stderr, "Error: HDC1080 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error: Failed to set signal handler");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HDC1080 sensor logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        float temperature, humidity;

        if (read_hdc1080(i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            if (log_data(temperature, humidity) < 0) {
                fprintf(stderr, "Warning: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Warning: Failed to read sensor data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

