#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define STS40_ADDR        0x44
#define I2C_BUS           "/dev/i2c-1"
#define LOG_FILE          "temperature_log.txt"
#define SAMPLE_INTERVAL_S 5
#define CONV_DELAY_MS     10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* Sensirion CRC8: polynomial 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len) {
    ssize_t n = write(fd, cmd, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s (wrote %zd of %zu bytes)\n",
                strerror(errno), n, len);
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: %s (read %zd of %zu bytes)\n",
                strerror(errno), n, len);
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temperature) {
    uint8_t cmd[2] = {0x2C, 0xE0}; /* single-shot, high repeatability */
    uint8_t data[3];

    if (i2c_write_cmd(fd, cmd, sizeof(cmd)) < 0)
        return -1;

    usleep(CONV_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, data, sizeof(data)) < 0)
        return -1;

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *temperature = -45.0f + (175.0f * (float)raw / 65535.0f);
    return 0;
}

static void log_temperature(FILE *fp, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    if (fprintf(fp, "%s, %.2f\n", ts, temperature) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, STS40_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                STS40_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature;

        if (read_temperature(g_i2c_fd, &temperature) == 0) {
            log_temperature(g_log_fp, temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

