#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define START_PERIODIC_MEASUREMENT 0x21B1
#define STOP_PERIODIC_MEASUREMENT 0x3F86
#define READ_MEASUREMENT 0xE000
#define BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data/"
#define ERROR_LOG_DIR "/var/log/scd40_error.log"
#define SAMPLE_INTERVAL_SEC 5
#define LOGGING_INTERVAL_SEC 60

typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_DIR, "a");
    if (!fp) {
        perror("Failed to open error log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }
    return 0;
}

static int start_periodic_measurement(void) {
    uint8_t cmd[2] = {
        (START_PERIODIC_MEASUREMENT >> 8) & 0xFF,
        START_PERIODIC_MEASUREMENT & 0xFF
    };
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        log_error("Failed to send start periodic measurement command");
        return -1;
    }
    return 0;
}

static int stop_periodic_measurement(void) {
    uint8_t cmd[2] = {
        (STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF,
        STOP_PERIODIC_MEASUREMENT & 0xFF
    };
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        log_error("Failed to send stop periodic measurement command");
        return -1;
    }
    return 0;
}

static int read_measurement(uint16_t *co2, float *temperature, float *humidity) {
    uint8_t cmd[2] = {
        (READ_MEASUREMENT >> 8) & 0xFF,
        READ_MEASUREMENT & 0xFF
    };
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        log_error("Failed to send read measurement command");
        return -1;
    }
    gpioDelay(10000);
    uint8_t buf[9];
    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        log_error("Failed to read measurement data");
        return -1;
    }
    if (crc8(&buf[0], 2) != buf[2]) {
        log_error("CRC check failed for CO2 data");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        log_error("CRC check failed for temperature data");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        log_error("CRC check failed for humidity data");
        return -1;
    }
    *co2 = (buf[0] << 8) | buf[1];
    *temperature = -45.0f + 175.0f * (float)buf[3] / 65535.0f;
    *humidity = 100.0f * (float)buf[6] / 65535.0f;
    return 0;
}

static void add_to_buffer(circular_buffer_t *buf, float co2, float temperature, float humidity) {
    pthread_mutex_lock(&buf->mutex);
    buf->data[buf->head].timestamp = time(NULL);
    buf->data[buf->head].co2 = co2;
    buf->data[buf->head].temperature = temperature;
    buf->data[buf->head].humidity = humidity;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) {
        buf->count++;
    }
    pthread_mutex_unlock(&buf->mutex);
}

static void *log_data_to_file(void *arg) {
    (void)arg;
    while (running) {
        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char filename[128];
        strftime(filename, sizeof(filename), LOG_DIR "%Y-%m-%d.csv", tm);
        FILE *fp = fopen(filename, "w");
        if (!fp) {
            log_error("Failed to open log file for writing");
            sleep(LOGGING_INTERVAL_SEC);
            continue;
        }
        fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%)\n");
        pthread_mutex_lock(&buffer.mutex);
        int start = (buffer.count == BUFFER_SIZE) ? buffer.head : 0;
        for (int i = 0; i < buffer.count; i++) {
            int idx = (start + i) % BUFFER_SIZE;
            fprintf(fp, "%ld,%.2f,%.2f,%.2f\n",
                    buffer.data[idx].timestamp,
                    buffer.data[idx].co2,
                    buffer.data[idx].temperature,
                    buffer.data[idx].humidity);
        }
        pthread_mutex_unlock(&buffer.mutex);
        fclose(fp);
        sleep(LOGGING_INTERVAL_SEC);
    }
    return NULL;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }
    if (start_periodic_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    buffer.head = 0;
    buffer.count = 0;
    if (pthread_mutex_init(&buffer.mutex, NULL) != 0) {
        log_error("Failed to initialize mutex");
        stop_periodic_measurement();
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    pthread_t log_thread;
    if (pthread_create(&log_thread, NULL, log_data_to_file, NULL) != 0) {
        log_error("Failed to create logging thread");
        pthread_mutex_destroy(&buffer.mutex);
        stop_periodic_measurement();
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    while (running) {
        uint16_t co2;
        float temperature, humidity;
        if (read_measurement(&co2, &temperature, &humidity) == 0) {
            add_to_buffer(&buffer, co2, temperature, humidity);
        } else {
            log_error("Failed to read sensor data, skipping this sample");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }
    pthread_join(log_thread, NULL);
    pthread_mutex_destroy(&buffer.mutex);
    stop_periodic_measurement();
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

