#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x63
#define LED_PIN        17
#define WARNING_THRESHOLD_PA 95000.0f
#define POLL_INTERVAL_S 1
#define MEASURE_DELAY_MS 20
#define LED_ON_MS 500
#define LED_OFF_MS 500
#define WARNING_LED_ON_MS 100
#define WARNING_LED_OFF_MS 100

#define REG_PRESSURE_MSB 0x00
#define REG_TEMP_MSB 0x02
#define REG_CRC 0x04
#define REG_OTP 0x66
#define CMD_MEASURE_HIGH_ACCURACY 0x4011

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t *buf, int len) {
    if (read(i2c_fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_calibration(uint16_t *c0, uint16_t *c1, uint16_t *c2, uint16_t *c3) {
    uint8_t buf[8];
    if (i2c_read_bytes(buf, 8) < 0)
        return -1;
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on calibration coefficients\n");
        return -1;
    }
    *c0 = (uint16_t)((buf[0] << 8) | buf[1]);
    *c1 = (uint16_t)((buf[3] << 8) | buf[4]);
    *c2 = (uint16_t)((buf[6] << 8) | buf[7]);
    return 0;
}

static int read_sensor_data(uint16_t *pressure, uint16_t *temperature) {
    uint8_t buf[6];
    if (i2c_read_bytes(buf, 6) < 0)
        return -1;
    if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on sensor data\n");
        return -1;
    }
    *pressure = (uint16_t)((buf[0] << 8) | buf[1]);
    *temperature = (uint16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

static float calculate_pressure(uint16_t raw_pressure, uint16_t raw_temperature,
                                uint16_t c0, uint16_t c1, uint16_t c2, uint16_t c3) {
    float t = (float)raw_temperature / 65536.0f;
    float p = (float)raw_pressure / 65536.0f;
    float p_comp = c0 + (c1 * t) + (c2 * t * t) + (c3 * t * t * t);
    return p_comp * 45000.0f;
}

static float calculate_temperature(uint16_t raw_temperature) {
    float t = (float)raw_temperature / 65536.0f;
    return t * 200.0f - 50.0f;
}

static void control_led(int on) {
    if (led_line)
        gpiod_line_set_value(led_line, on ? 1 : 0);
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ICP10125_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    uint16_t c0, c1, c2, c3;
    if (read_calibration(&c0, &c1, &c2, &c3) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
