#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define TEMP_HIGH 30.0
#define TEMP_LOW 28.0
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000
#define LOG_INTERVAL_US 2000000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_temperature(int handle, uint8_t reg, float *temp) {
    int raw;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        raw = i2cReadWordData(handle, reg);
        if (raw >= 0) {
            *temp = (float)raw * 0.02f - 273.15f;
            return 0;
        }
        fprintf(stderr, "I2C read error (reg 0x%02X): %d, retry %d/%d\n",
                reg, raw, retries + 1, MAX_RETRIES);
        retries++;
        if (retries < MAX_RETRIES) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

static void control_fan(int gpio, float temp) {
    if (temp > TEMP_HIGH) {
        gpioWrite(gpio, 1);
    } else if (temp < TEMP_LOW) {
        gpioWrite(gpio, 0);
    }
}

static void log_temperature(float ambient, float object) {
    FILE *fp = fopen("temperature_log.txt", "a");
    if (!fp) {
        perror("Error opening temperature_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Ambient: %.2f C, Object: %.2f C\n", timestamp, ambient, object);
    fclose(fp);
}

int main(void) {
    float ambient, object;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %d\n",
                I2C_BUS, MLX90614_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90614 temperature monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_temperature(i2c_handle, AMBIENT_TEMP_REG, &ambient) == 0 &&
            read_temperature(i2c_handle, OBJECT_TEMP_REG, &object) == 0) {
            printf("Ambient: %.2f C, Object: %.2f C\n", ambient, object);
            control_fan(FAN_GPIO, object);
            log_temperature(ambient, object);
        } else {
            fprintf(stderr, "Failed to read temperature after %d retries\n", MAX_RETRIES);
        }
        gpioDelay(LOG_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

