        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read sensor after %d retries.\n", MAX_RETRIES);
    return -1;
}

int create_server_socket(int port) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket creation failed");
        return -1;
    }

    int opt = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(fd);
        return -1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(port);

    if (bind(fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(fd);
        return -1;
    }

    if (listen(fd, 3) < 0) {
        perror("listen failed");
        close(fd);
        return -1;
    }

    return fd;
}

int handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
    if (bytes_received < 0) {
        perror("recv failed");
        return -1;
    }
    buffer[bytes_received] = '\0';

    float temperature, humidity;
    if (read_sht40(&temperature, &humidity) == 0) {
        char response[BUFFER_SIZE];
        snprintf(response, sizeof(response),
                 "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n"
                 "<!DOCTYPE html><html><head><title>SHT40 Sensor Data</title></head>"
                 "<body><h1>SHT40 Sensor Data</h1>"
                 "<p>Temperature: %.2f C</p>"
                 "<p>Humidity: %.2f %%</p></body></html>",
                 temperature, humidity);
        send(client_socket, response, strlen(response), 0);
    } else {
        char response[BUFFER_SIZE];
        snprintf(response, sizeof(response),
                 "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/html\r\n\r\n"
                 "<!DOCTYPE html><html><head><title>SHT40 Sensor Error</title></head>"
                 "<body><h1>SHT40 Sensor Error</h1>"
                 "<p>Failed to read sensor data.</p></body></html>");
        send(client_socket, response, strlen(response), 0);
    }

    close(client_socket);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    server_fd = create_server_socket(PORT);
    if (server_fd < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d...\n", PORT);

    while (running) {
        struct sockaddr_in client_address;
        socklen_t client_len = sizeof(client_address);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_address, &client_len);
        if (client_socket < 0) {
            if (running) {
                perror("accept failed");
            }
            continue;
        }

        handle_client(client_socket);
    }

    printf("\nShutting down...\n");
    if (server_fd >= 0) close(server_fd);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

