#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define TMP102_ADDR 0x48
#define TMP102_REG_TEMP 0x00
#define I2C_BUS 1
#define LOG_FILE "temperature_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_temperature(float *temperature) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TMP102_REG_TEMP, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature from I2C: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    raw >>= 4;
    *temperature = (float)raw * 0.0625f;
    return 0;
}

static int log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Greenhouse Climate Monitoring System\n");
    printf("Logging to %s every %d seconds. Press Ctrl+C to exit.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (!terminate) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            } else {
                printf("Temperature: %.2f C\n", temperature);
            }
        } else {
            fprintf(stderr, "Failed to read temperature, skipping log entry\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && !terminate; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    printf("\nExiting gracefully...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

