static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X: %d\n", value, reg, rc);
    }
    return rc;
}

static int read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_reg16(int handle, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading 16-bit reg 0x%02X: expected 2 bytes, got %d\n", reg, rc);
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int trigger_measurement(int handle) {
    if (write_reg(handle, MEAS_CONFIG_REG, 0x01) < 0) {
        return -1;
    }
    return 0;
}

static int wait_for_measurement(int handle) {
    uint8_t config;
    for (int i = 0; i < 50; i++) {
        if (read_reg(handle, CONFIG_REG, &config) < 0) {
            return -1;
        }
        if ((config & 0x01) == 0) {
            return 0;
        }
        gpioDelay(1000);
    }
    fprintf(stderr, "Measurement timeout\n");
    return -1;
}

