#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD_MSB 0x36
#define MEASURE_CMD_LSB 0x2F
#define MEASUREMENT_DELAY_US 50000  /* 50 ms */
#define READ_DELAY_US 45000       /* 45 ms after measurement */
#define POLL_DELAY_US 100000      /* 100 ms between polls */

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* CRC-8 calculation for Sensirion sensors (polynomial 0x31, init 0xFF) */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Trigger a continuous measurement and read the 6-byte result */
static int read_sdp800(int handle, int16_t *pressure, int16_t *temperature) {
    uint8_t cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    uint8_t buf[6];

    /* Send measurement command */
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to write measurement command to I2C device.\n");
        return -1;
    }

    /* Wait for measurement to complete */
    gpioDelay(MEASUREMENT_DELAY_US);

    /* Read 6 bytes: pressure MSB, pressure LSB, pressure CRC, temp MSB, temp LSB, temp CRC */
    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read 6 bytes from I2C device.\n");
        return -1;
    }

    /* Verify CRC for pressure data */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch.\n");
        return -1;
    }

    /* Verify CRC for temperature data */
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }

    /* Convert raw data to signed integers */
    *pressure = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);

    return 0;
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C device on bus 1 at address 0x25 */
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d.\n",
                SDP800_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to set SIGINT handler.\n");
    }

    printf("SDP800-500Pa sensor reader started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        int16_t pressure, temperature;

        if (read_sdp800(i2c_handle, &pressure, &temperature) == 0) {
            printf("Pressure: %d Pa, Temperature: %d °C\n", pressure, temperature);
