#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8
#define RELAY_GPIO 17
#define TARGET_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_TEMP_ERROR 100.0

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int read_max6675(int spi_fd, float *temperature) {
    uint8_t tx_buf[3] = {0x00, 0x00, 0x00};
    uint8_t rx_buf[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    uint16_t raw = ((rx_buf[0] & 0x03) << 8) | rx_buf[1];
    if (raw & 0x0400) {
        fprintf(stderr, "MAX6675 open circuit detected\n");
        return -2;
    }

    *temperature = (float)((raw >> 1) & 0x0FFF) / 16.0f;
    return 0;
}

float calculate_pid(float setpoint, float current_temp, float *integral, float *previous_error) {
    float error = setpoint - current_temp;
    *integral += error;
    float derivative = error - *previous_error;
    float output = 0.1 * error + 0.1 * (*integral) + 0.1 * derivative;
    *previous_error = error;
    return output;
}

int set_relay_state(struct gpiod_line *relay_line, float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;
    int value = (duty_cycle > 0.5) ? 1 : 0;
    if (gpiod_line_set_value(relay_line, value) < 0) {
        perror("Failed to set relay GPIO value");
        return -1;
    }
    return 0;
}

int log_data(float temperature, float setpoint, float integral, float derivative) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, setpoint, integral, derivative);
    fclose(fp);
    return 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *relay_line = NULL;
    int spi_fd = -1;
    float integral = 0.0, previous_error = 0.0;
    float setpoint = 0.0, current_temp = 0.0;
    float duty_cycle = 0.0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Failed to get GPIO line 17");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "reflow_relay", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        goto cleanup;
    }

    FILE *fp = fopen(TARGET_FILE, "r");
    if (fp == NULL) {
        perror("Failed to open target file");
        goto cleanup;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (sscanf(line, "%f", &setpoint) == 1) {
            break;
        }
    }
    fclose(fp);

    printf("Reflow oven control started. Target temperature: %.2f C\n", setpoint);

    while (program_running) {
        int ret = read_max6675(spi_fd, &current_temp);
        if (ret == 0) {
            duty_cycle = calculate_pid(setpoint, current_temp, &integral, &previous_error);
            if (set_relay_state(relay_line, duty_cycle) < 0) {
                fprintf(stderr, "Relay control failed\n");
            }
            log_data(current_temp, setpoint, integral, previous_error);
            printf("Temperature: %.2f C, Duty Cycle: %.2f, Integral: %.2f, Derivative: %.2f\n",
                   current_temp, duty_cycle, integral, previous_error);
        } else if (ret == -2) {
            fprintf(stderr, "Sensor absent or open circuit\n");
        } else {
            fprintf(stderr, "SPI communication error\n");
        }
        usleep(SAMPLE_INTERVAL_US);
    }

cleanup:
    printf("\nCleaning up...\n");
    if (relay_line) gpiod_line_set_value(relay_line, 0);
    if (relay_line) gpiod_line_release(relay_line);
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
    return 0;
}

