#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define RELAY_PIN 17
#define PWM_PIN 18
#define TEMP_SENSOR_PIN 4
#define LOG_FILE "greenhouse.log"
#define W1_DEVICES_DIR "/sys/bus/w1/devices"
#define W1_SLAVE_PREFIX "28-"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *pwm_line = NULL;
static struct gpiod_line *temp_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (pwm_line) {
        gpiod_line_set_value(pwm_line, 0);
        gpiod_line_release(pwm_line);
        pwm_line = NULL;
    }
    if (temp_line) {
        gpiod_line_release(temp_line);
        temp_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line %d: %s\n", RELAY_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(relay_line, "greenhouse-relay", 0) < 0) {
        fprintf(stderr, "Failed to request relay line as output: %s\n", strerror(errno));
        return -1;
    }

    pwm_line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!pwm_line) {
        fprintf(stderr, "Failed to get PWM line %d: %s\n", PWM_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(pwm_line, "greenhouse-pwm", 0) < 0) {
        fprintf(stderr, "Failed to request PWM line as output: %s\n", strerror(errno));
        return -1;
    }

    temp_line = gpiod_chip_get_line(chip, TEMP_SENSOR_PIN);
    if (!temp_line) {
        fprintf(stderr, "Failed to get temp sensor line %d: %s\n", TEMP_SENSOR_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_input(temp_line, "greenhouse-temp") < 0) {
        fprintf(stderr, "Failed to request temp sensor line as input: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_temperature(float *temperature) {
    char path[256];
    char buf[256];
    int fd;
    int ret;

    snprintf(path, sizeof(path), "%s/%s/w1_slave", W1_DEVICES_DIR, W1_SLAVE_PREFIX);

    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }

    ret = read(fd, buf, sizeof(buf) - 1);
    close(fd);

    if (ret < 0) {
        fprintf(stderr, "Failed to read from %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (ret == 0) {
        fprintf(stderr, "No data from %s\n", path);
        return -1;
    }
    buf[ret] = '\0';

    if (strstr(buf, "YES") == NULL) {
        fprintf(stderr, "CRC check failed in %s\n", path);
        return -1;
    }

    char *temp_str = strstr(buf, "t=");
    if (!temp_str) {
        fprintf(stderr, "Temperature data not found in %s\n", path);
        return -1;
    }

    long raw = strtol(temp_str + 2, NULL, 10);
    *temperature = (float)raw / 1000.0f;
    return 0;
}

static float calculate_pid(float setpoint, float current_temp, float *integral, float *prev_error, float *prev_time) {
    float error = setpoint - current_temp;
    float dt = time(NULL) - *prev_time;
    *integral += error * dt;
    float derivative = (error - *prev_error) / dt;
    float output = (*integral * 0.1f) + (error * 0.5f) + (derivative * 0.1f);
    *prev_error = error;
    *prev_time = time(NULL);
    return output;
}

static int control_heater(float pid_output) {
    int duty_cycle = (int)(pid_output * 100.0f);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    if (gpiod_line_set_value(pwm_line, 1) < 0) {
        fprintf(stderr, "Failed to set PWM high: %s\n", strerror(errno));
        return -1;
    }
    usleep(duty_cycle * 1000);
    if (gpiod_line_set_value(pwm_line, 0) < 0) {
        fprintf(stderr, "Failed to set PWM low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void log_data(float average_temp, float setpoint, float pid_output, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Average Temp: %.2f, Setpoint: %.2f, PID Output: %.2f, PWM Duty Cycle: %d%%\n",
            timestamp, average_temp, setpoint, pid_output, duty_cycle);
    fflush(log_file);
}

int main(int argc, char *argv[]) {
    float setpoint = 25.0f;
    float Kp = 0.1f, Ki = 0.01f, Kd = 0.001f;
    float integral = 0.0f, prev_error = 0.0f, prev_time = 0.0f;
    float average_temp = 0.0f;
