    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    printf("Greenhouse heater control started. Setpoint: %.2f, Kp: %.2f, Ki: %.2f, Kd: %.2f\n",
           setpoint, Kp, Ki, Kd);

    while (running) {
        float current_temp;
        if (read_temperature(&current_temp) < 0) {
            fprintf(stderr, "Failed to read temperature. Retrying in %d seconds...\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        average_temp = (average_temp * 5.0f + current_temp) / 6.0f;

        pid_output = calculate_pid(setpoint, current_temp, &integral, &prev_error, &prev_time);
        if (control_heater(pid_output) < 0) {
