#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define AHT20_ADDR 0x38
#define DEHUMIDIFIER_GPIO 17
#define HUMIDITY_HIGH 60.0f
#define HUMIDITY_LOW 55.0f
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define MEASUREMENT_DELAY_MS 80
#define POLL_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_line *dehumidifier_line = NULL;
static struct gpiod_chip *chip = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(uint8_t cmd1, uint8_t cmd2, uint8_t cmd3) {
    uint8_t buf[3] = {cmd1, cmd2, cmd3};
    if (write(i2c_fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t *buf, int len) {
    if (read(i2c_fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int aht20_init(void) {
    if (i2c_write_cmd(0xBE, 0x08, 0x00) < 0) return -1;
    usleep(10000);
    return 0;
}

static int aht20_read_humidity(float *humidity) {
    uint8_t data[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_cmd(0xAC, 0x33, 0x00) < 0) {
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        usleep(MEASUREMENT_DELAY_MS * 1000);

        if (i2c_read_bytes(data, 6) < 0) {
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (data[0] != 0x00) {
            fprintf(stderr, "AHT20 status error: 0x%02X\n", data[0]);
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        uint32_t raw_humidity = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
        uint32_t raw_temp = ((uint32_t)data[3] << 16) | ((uint32_t)data[4] << 8) | data[5];

        *humidity = -6.0f + 125.0f * (float)raw_humidity / 65536.0f;
        return 0;
    }

    fprintf(stderr, "Failed to read humidity after %d retries\n", MAX_RETRIES);
    return -1;
}

static void control_dehumidifier(float humidity) {
    int val = (humidity > HUMIDITY_HIGH) ? 1 : 0;
    if (gpiod_line_set_value(dehumidifier_line, val) < 0) {
        fprintf(stderr, "Failed to set dehumidifier GPIO: %s\n", strerror(errno));
    }
}

static void log_data(float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Humidity: %.2f%%\n", timestamp, humidity);
    fflush(stdout);
}

static void cleanup(void) {
    if (dehumidifier_line) {
        gpiod_line_set_value(dehumidifier_line, 0);
        gpiod_line_release(dehumidifier_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }

    dehumidifier_line = gpiod_chip_get_line(chip, DEHUMIDIFIER_GPIO);
    if (!dehumidifier_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", DEHUMIDIFIER_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(dehumidifier_line, "dehumidifier", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", AHT20_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (aht20_init() < 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        cleanup();
        return 1;
    }

    printf("Dehumidifier control started. Press Ctrl+C to exit.\n");

    while (running) {
        float humidity;
        if (aht20_read_humidity(&humidity) == 0) {
            log_data(humidity);
            control_dehumidifier(humidity);
        } else {
            fprintf(stderr, "Failed to read humidity, skipping control\n");
        }
        sleep(POLL_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

