static int http_sock = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        syslog(LOG_ERR, "I2C read reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C read reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int read_humidity(float *humidity) {
    uint8_t data[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read_reg8(i2c_fd, 0xE3, &data[0]) < 0) {
            retries++;
            sleep(1);
            continue;
        }
        if (i2c_read_reg8(i2c_fd, 0xE5, &data[1]) < 0) {
            retries++;
            sleep(1);
            continue;
        }
        if (i2c_read_reg8(i2c_fd, 0xE7, &data[2]) < 0) {
            retries++;
            sleep(1);
            continue;
        }

        uint16_t raw_humidity = ((uint16_t)data[0] << 8) | data[1];
        uint16_t raw_temp = ((uint16_t)data[2] << 8) | data[1];

        if (crc8(data, 2) != data[2]) {
            syslog(LOG_ERR, "Humidity CRC mismatch (calc=0x%02X, got=0x%02X)", crc8(data, 2), data[2]);
            retries++;
            sleep(1);
            continue;
        }

        float temperature = -46.85f + 175.72f * (float)raw_temp / 65535.0f;
        float humidity = 100.0f * (float)raw_humidity / 65535.0f;

        if (humidity < 0.0f || humidity > 100.0f) {
            syslog(LOG_ERR, "Humidity out of range: %.2f%%", humidity);
            retries++;
            sleep(1);
            continue;
        }

        *humidity = humidity;
        return 0;
    }

    syslog(LOG_ERR, "Failed to read humidity after %d retries", MAX_RETRIES);
    return -1;
}

static int send_http_request(float humidity) {
    char json_body[64];
    int body_len = snprintf(json_body, sizeof(json_body), "{\"humidity\": %.2f}", humidity);
    if (body_len < 0 || body_len >= (int)sizeof(json_body)) {
        syslog(LOG_ERR, "JSON body formatting failed");
        return -1;
    }

    char request[512];
    int req_len = snprintf(request, sizeof(request),
        "POST %s HTTP/1.1\r\n"
        "Host: %s\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: %d\r\n"
        "Connection: close\r\n"
        "\r\n"
        "%s",
        API_ENDPOINT, API_ENDPOINT, body_len, json_body);
    if (req_len < 0 || req_len >= (int)sizeof(request)) {
        syslog(LOG_ERR, "HTTP request formatting failed");
        return -1;
    }

    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80);

    if (inet_pton(AF_INET, API_ENDPOINT, &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address: %s", API_ENDPOINT);
        return -1;
    }

    http_sock = socket(AF_INET, SOCK_STREAM, 0);
    if (http_sock < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    if (connect(http_sock, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection to %s failed: %s", API_ENDPOINT, strerror(errno));
        close(http_sock);
        http_sock = -1;
        return -1;
    }

    ssize_t sent = send(http_sock, request, req_len, 0);
    if (sent < 0 || (size_t)sent != req_len) {
        syslog(LOG_ERR, "HTTP request send failed: %s", strerror(errno));
        close(http_sock);
        http_sock = -1;
        return -1;
    }

    char response[4096];
    ssize_t total = 0;
    while (total < sizeof(response) - 1) {
        ssize_t n = recv(http_sock, response + total, sizeof(response) - 1 - total, 0);
        if (n < 0) {
            if (errno == EINTR) continue;
            syslog(LOG_ERR, "HTTP response receive failed: %s", strerror(errno));
            close(http_sock);
            http_sock = -1;
            return -1;
        }
        if (n == 0) {
            syslog(LOG_ERR, "HTTP response received with 0 bytes");
            close(http_sock);
            http_sock = -1;
            return -1;
        }
        total += n;
    }
    response[total] = '\0';

    syslog(LOG_INFO, "HTTP response: %s", response);

    close(http_sock);
    http_sock = -1;
    return 0;
}

int main(void) {
    openlog("htu21d_sensor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        closelog();
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device %s: %s", I2C_DEVICE, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "HTU21D sensor initialized on %s at address 0x%02X", I2C_DEVICE, HTU21D_ADDR);

    while (running) {
        float humidity;
        if (read_humidity(&humidity) == 0) {
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            if (send_http_request(humidity) < 0) {
                syslog(LOG_ERR, "HTTP request failed");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    if (http_sock >= 0) {
        close(http_sock);
        http_sock = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    closelog();
    return 0;
}

