#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_REG 0xE0
#define BMP280_RESET_CMD 0xB6
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CONFIG_REG 0xF5
#define BMP280_PRESS_MSB_REG 0xF7
#define BMP280_CALIB_START_REG 0x88
#define BMP280_CALIB_LEN 24
#define PRESSURE_THRESHOLD_HIGH 1020.0f
#define PRESSURE_THRESHOLD_LOW 980.0f
#define SAMPLE_INTERVAL_SEC 2
#define MAX_RETRIES 3
#define CONVERSION_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

static bmp280_calib_data calib;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C read block failed (reg=0x%02X, rc=%d, expected=%u)\n", reg, rc, len);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write byte failed (reg=0x%02X, value=0x%02X, rc=%d)\n", reg, value, rc);
        return -1;
    }
    return 0;
}

static int bmp280_read_calibration(int handle) {
    uint8_t buf[BMP280_CALIB_LEN];
    if (i2c_read_block(handle, BMP280_CALIB_START_REG, buf, BMP280_CALIB_LEN) != 0) {
        return -1;
    }
    calib.dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    calib.dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    calib.dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    calib.dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    calib.dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    calib.dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    calib.dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    calib.dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    calib.dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    calib.dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    calib.dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    calib.dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int bmp280_init(int handle) {
    uint8_t chip_id;
    if (i2c_read_block(handle, BMP280_CHIP_ID_REG, &chip_id, 1) != 0) {
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch: got 0x%02X, expected 0x%02X\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_byte(handle, BMP280_RESET_REG, BMP280_RESET_CMD) != 0) {
        return -1;
    }
    gpioDelay(2000);
    if (bmp280_read_calibration(handle) != 0) {
        return -1;
    }
    if (i2c_write_byte(handle, BMP280_CONFIG_REG, 0x00) != 0) {
        return -1;
    }
    if (i2c_write_byte(handle, BMP280_CTRL_MEAS_REG, 0x27) != 0) {
        return -1;
    }
    return 0;
}

static int bmp280_read_raw(int handle, int32_t *raw_temp, int32_t *raw_press) {
    uint8_t buf[6];
    if (i2c_write_byte(handle, BMP280_CTRL_MEAS_REG, 0x27) != 0) {
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);
    if (i2c_read_block(handle, BMP280_PRESS_MSB_REG, buf, 6) != 0) {
        return -1;
    }
    *raw_press = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | ((int32_t)buf[2] >> 4);
    *raw_temp = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | ((int32_t)buf[5] >> 4);
    return 0;
}

static float compensate_temperature(int32_t raw_temp) {
    double var1 = ((double)raw_temp / 16384.0 - (double)calib.dig_T1 / 1024.0) * (double)calib.dig_T2;
    double var2 = ((double)raw_temp / 131072.0 - (double)calib.dig_T1 / 8192.0) * ((double)raw_temp / 131072.0 - (double)calib.dig_T1 / 8192.0) * (double)calib.dig_T3;
    t_fine = (int32_t)(var1 + var2);
    return (float)((var1 + var2) / 5120.0);
}

static float compensate_pressure(int32_t raw_press) {
    double var1 = ((double)t_fine / 2.0) - 64000.0;
    double var2 = var1 * var1 * (double)calib.dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)calib.dig_P5 * 2.0;
    var2 = (var2 / 4.0) + ((double)calib.dig_P4 * 65536.0);
    var1 = ((double)calib.dig_P3 * var1 * var1 / 524288.0 + (double)calib.dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)calib.dig_P1;
    if (var1 == 0.0) {
        return 0.0f;
    }
    double p = 1048576.0 - (double)raw_press;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = (double)calib.dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)calib.dig_P8 / 32768.0;
    p = p + (var1 + var2 + (double)calib.dig_P7) / 16.0;
    return (float)p;
}

static void log_pressure_breach(float pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) {
        perror("fopen pressure_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - Pressure breach: %.2f hPa\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X: %d\n", BMP280_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (bmp280_init(i2c_handle) != 0) {
        fprintf(stderr, "BMP280 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("BMP280 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int32_t raw_temp, raw_press;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success) {
            if (bmp280_read_raw(i2c_handle, &raw_temp, &raw_press) == 0) {
                success = 1;
            } else {
                retries++;
