#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO_LINE 17
#define GPIO_CHIP "gpiochip4"
#define LOG_DIR "logs"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd_tmp117 = -1;
static int i2c_fd_aht20 = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t *cmd, int len) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (write(fd, cmd, len) == len) return 0;
        fprintf(stderr, "I2C write failed (attempt %d/%d): %s\n", i + 1, MAX_RETRIES, strerror(errno));
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_data(int fd, uint8_t *buf, int len) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (read(fd, buf, len) == len) return 0;
        fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n", i + 1, MAX_RETRIES, strerror(errno));
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int init_i2c(void) {
    i2c_fd_tmp117 = open(I2C_BUS, O_RDWR);
    if (i2c_fd_tmp117 < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd_tmp117, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TMP117_ADDR, strerror(errno));
        close(i2c_fd_tmp117);
        i2c_fd_tmp117 = -1;
        return -1;
    }
    i2c_fd_aht20 = open(I2C_BUS, O_RDWR);
    if (i2c_fd_aht20 < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        close(i2c_fd_tmp117);
        i2c_fd_tmp117 = -1;
        return -1;
    }
    if (ioctl(i2c_fd_aht20, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", AHT20_ADDR, strerror(errno));
        close(i2c_fd_aht20);
        i2c_fd_aht20 = -1;
        close(i2c_fd_tmp117);
        i2c_fd_tmp117 = -1;
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }
    pir_line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!pir_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", PIR_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", PIR_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        pir_line = NULL;
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp) {
    uint8_t cmd[2] = {0x00, 0x00};
    uint8_t buf[2];
    if (i2c_write_cmd(i2c_fd_tmp117, cmd, 2) < 0) return -1;
    usleep(10000);
    if (i2c_read_data(i2c_fd_tmp117, buf, 2) < 0) return -1;
    int16_t raw = (buf[0] << 8) | buf[1];
    *temp = (float)raw * 0.0078125f;
    return 0;
}

static int read_humidity(float *hum) {
    uint8_t init_cmd[3] = {0xBE, 0x08, 0x00};
    uint8_t measure_cmd[3] = {0xAC, 0x33, 0x00};
    uint8_t buf[7];
    if (i2c_write_cmd(i2c_fd_aht20, init_cmd, 3) < 0) return -1;
    usleep(10000);
    if (i2c_write_cmd(i2c_fd_aht20, measure_cmd, 3) < 0) return -1;
    usleep(100000);
    if (i2c_read_data(i2c_fd_aht20, buf, 7) < 0) return -1;
    if (buf[0] & 0x80) {
        fprintf(stderr, "AHT20 busy bit set\n");
        return -1;
    }
    uint32_t raw_h = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | (buf[3] >> 4);
    uint32_t raw_t = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | buf[5];
    *hum = (float)raw_h / 1048576.0f * 100.0f;
    return 0;
}

static int read_pir(int *motion) {
    *motion = gpiod_line_get_value(pir_line);
    if (*motion < 0) {
        fprintf(stderr, "Failed to read PIR sensor: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int log_data(float temp, float hum, int motion) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char filename[64];
    strftime(filename, sizeof(filename), "%Y-%m-%d.csv", tm_info);
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", filename, strerror(errno));
        return -1;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%d\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
            temp, hum, motion);
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd_tmp117 >= 0) {
        close(i2c_fd_tmp117);
        i2c_fd_tmp117 = -1;
    }
    if (i2c_fd_aht20 >= 0) {
        close(i2c_fd_aht20);
        i2c_fd_aht20 = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Continuing without sensors.\n");
    } else {
        printf("I2C initialized successfully.\n");
    }
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Continuing without PIR sensor.\n");
    } else {
        printf("GPIO initialized successfully.\n");
    }

    while (running) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char filename[64];
        strftime(filename, sizeof(filename), "%Y-%m-%d.csv", tm_info);
        FILE *fp = fopen(filename, "r");
        if (fp) {
            fclose(fp);
        } else {
            if (log_data(0.0f, 0.0f, 0) < 0) {
                fprintf(stderr, "Failed to create log file for day %s\n", filename);
            }
        }

        float temp, hum;
        int motion;
        if (read_temperature(&temp) < 0 || read_humidity(&hum) < 0 || read_pir(&motion) < 0) {
            fprintf(stderr, "Sensor read error. Skipping this sample.\n");
        } else {
            printf("Temperature: %.2f C, Humidity: %.2f %%, Motion: %d\n", temp, hum, motion);
            if (log_data(temp, hum, motion) < 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    cleanup();
    printf("Exiting gracefully.\n");
    return 0;
}

