/*
 * Map CPU load (0-100) to RGB color.
 * Returns 0 on success, -1 on error.
 */
static int map_cpu_load_to_color(float load, int *red, int *green, int *blue) {
    if (load < 0.0f || load > 100.0f) {
        fprintf(stderr, "Error: CPU load %.2f out of range [0, 100]\n", load);
        return -1;
    }

    if (load <= 50.0f) {
        *red   = 0;
        *green = (int)(load / 50.0f * PWM_RANGE);
        *blue  = 0;
    } else if (load <= 100.0f) {
        *red   = (int)((100.0f - load) / 50.0f * PWM_RANGE);
        *green = PWM_RANGE;
        *blue  = 0;
    } else {
        fprintf(stderr, "Error: Invalid CPU load %.2f\n", load);
        return -1;
    }

    return 0;
}

/*
 * Set PWM duty cycle for a given GPIO pin.
 * Clamps value to 0-PWM_RANGE.
 */
static int set_pwm_duty(int pin, int value) {
    if (value < 0) value = 0;
    if (value > PWM_RANGE) value = PWM_RANGE;

    if (gpioPWM(pin, value) != 0) {
        fprintf(stderr, "Error: gpioPWM failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

/*
 * Turn off all LED channels (common-anode: drive all pins to full off).
 */
static void led_off(void) {
    set_pwm_duty(RED_PIN,   PWM_RANGE);
    set_pwm_duty(GREEN_PIN, PWM_RANGE);
    set_pwm_duty(BLUE_PIN,  PWM_RANGE);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    /* Configure LED pins as outputs */
    if (gpioSetMode(RED_PIN,   PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    /* Set PWM range for all three channels */
    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    /* Ensure LED starts off */
    led_off();

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        led_off();
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        led_off();
        gpioTerminate();
        return 1;
    }

    float previous_load = 0.0f;
    int   red, green, blue;

    while (running) {
        float current_load;
        if (read_cpu_load(&current_load) != 0) {
            fprintf(stderr, "Warning: Failed to read CPU load, using previous value\n");
            current_load = previous_load;
        } else {
            previous_load = current_load;
        }

        if (map_cpu_load_to_color(current_load, &red, &green, &blue) != 0) {
            fprintf(stderr, "Warning: Failed to map CPU load to color, using previous color\n");
            red   = previous_red;
            green = previous_green;
            blue  = previous_blue;
        }

        if (set_pwm_duty(RED_PIN,   red) != 0 ||
            set_pwm_duty(GREEN_PIN, green) != 0 ||
            set_pwm_duty(BLUE_PIN,  blue) != 0) {
            fprintf(stderr, "Warning: Failed to set PWM duty cycle\n");
        }

        gpioDelay(SAMPLE_MS * 1000); /* gpioDelay takes microseconds */
    }

    /* Clean shutdown: turn LED off and terminate pigpio */
    led_off();
    gpioTerminate();

    return 0;
}

