                fprintf(stderr, "Failed to send UDP data\n");
            }
        } else {
            fprintf(stderr, "Failed to read BMP280 data\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (udp_socket >= 0) {
        close(udp_socket);
    }
    gpioTerminate();
    return 0;
}

