#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL_US 1000000

#define TEMP_MIN 25.0f
#define TEMP_MAX 60.0f
#define TEMP_STEP 0.25f

#define FAULT_NONE 0
#define FAULT_OPEN_CIRCUIT 1
#define FAULT_SHORT_TO_GND 2
#define FAULT_SHORT_TO_VCC 3
#define FAULT_OPEN_VCC 4
#define FAULT_OPEN_GND 5
#define FAULT_SCG 6
#define FAULT_SCV 7

typedef struct {
    time_t timestamp;
    float temperature;
    int pwm_duty;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_max31855(int handle, float *temperature, int *fault_code) {
    char tx_buf[4] = {0, 0, 0, 0};
    char rx_buf[4] = {0, 0, 0, 0};

    int result = spiXfer(handle, tx_buf, rx_buf, 4);
    if (result != 4) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", result);
        *temperature = 0.0f;
        *fault_code = FAULT_NONE;
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx_buf[0] << 24) |
                   ((uint32_t)(uint8_t)rx_buf[1] << 16) |
                   ((uint32_t)(uint8_t)rx_buf[2] << 8)  |
                   ((uint32_t)(uint8_t)rx_buf[3]);

    if (raw & 0x00010000) {
        *fault_code = (raw >> 16) & 0x07;
        if (*fault_code == FAULT_SCG || *fault_code == FAULT_SCV) {
            *temperature = 0.0f;
            return -1;
        }
        fprintf(stderr, "MAX31855 fault: %d\n", *fault_code);
        return -1;
    }

    int16_t thermocouple_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (thermocouple_raw & 0x2000) {
        thermocouple_raw |= 0xC000;
    }
    *temperature = thermocouple_raw * TEMP_STEP;
    return 0;
}

static int calculate_pwm_duty(float temperature) {
    if (temperature < TEMP_MIN) {
        return 0;
    } else if (temperature < TEMP_MAX) {
        if (temperature < TEMP_MIN + 25.0f) {
            return (int)((temperature - TEMP_MIN) / 25.0f * PWM_RANGE);
        } else if (temperature < TEMP_MIN + 40.0f) {
            return (int)(((temperature - TEMP_MIN) - 25.0f) / 15.0f * PWM_RANGE);
        } else {
            return (int)(((temperature - TEMP_MIN) - 40.0f) / 20.0f * PWM_RANGE);
        }
    } else {
        return PWM_RANGE;
    }
}

static void log_data(float temperature, int pwm_duty) {
    time(&log_buffer[buffer_index].timestamp);
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].pwm_duty = pwm_duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void print_buffer(void) {
    printf("\n--- Log Buffer Contents ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&log_buffer[idx].timestamp);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("[%s] Temp: %.2f C, PWM: %d\n", time_str, log_buffer[idx].temperature, log_buffer[idx].pwm_duty);
    }
    printf("--- End of Log Buffer ---\n\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature = 0.0f;
        int fault_code = FAULT_NONE;

        if (read_max31855(spi_handle, &temperature, &fault_code) == 0) {
            int pwm_duty = calculate_pwm_duty(temperature);
            if (gpioPWM(FAN_GPIO, pwm_duty) != 0) {
                fprintf(stderr, "Failed to set PWM duty on GPIO%d\n", FAN_GPIO);
            }
            log_data(temperature, pwm_duty);
            printf("Temp: %.2f C, PWM: %d\n", temperature, pwm_duty);
        } else {
            fprintf(stderr, "Failed to read temperature or fault\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    print_buffer();
    return EXIT_SUCCESS;
}

