#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0-3)
#define OSS 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t running = 1;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int32_t *ut);
int read_raw_pressure(int32_t *up);
double calculate_temperature(int32_t ut);
double calculate_pressure(int32_t up, int32_t ut);
double calculate_altitude(double pressure);
int log_data(double temperature, double pressure, double altitude);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Signal handler for graceful exit
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Interrupt handler for falling edge
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio;
    (void)level;
    (void)tick;
    (void)user_data;

    // Read raw temperature and pressure
    int32_t ut, up;
    if (read_raw_temperature(&ut) != 0 || read_raw_pressure(&up) != 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return;
    }

    // Calculate temperature and pressure
    double temperature = calculate_temperature(ut);
    double pressure = calculate_pressure(up, ut);

    // Calculate altitude
    double altitude = calculate_altitude(pressure);

    // Log data
    if (log_data(temperature, pressure, altitude) != 0) {
        fprintf(stderr, "Error logging data\n");
    }
}

// Function to read calibration data from BMP180
int read_calibration_data() {
    char buf[22];

    // Read calibration data from registers 0xAA-0xBE
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    // Convert calibration data to integers
    ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1 = (int16_t)((buf[12] << 8) | buf[13]);
    b2 = (int16_t)((buf[14] << 8) | buf[15]);
    mb = (int16_t)((buf[16] << 8) | buf[17]);
    mc = (int16_t)((buf[18] << 8) | buf[19]);
    md = (int16_t)((buf[20] << 8) | buf[21]);

    return 0;
}

// Function to read raw temperature from BMP180
int read_raw_temperature(int32_t *ut) {
    char buf[2];

    // Write control register to request temperature measurement
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // 0x2E = 0010 1110 = temp measurement, OSS=3
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for measurement to complete (at OSS=3, ~4.5ms)
    gpioDelay(5000); // 5ms

    // Read MSB and LSB from registers 0xF6 and 0xF7
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    *ut = (int32_t)((buf[0] << 8) | buf[1]);

    return 0;
}

// Function to read raw pressure from BMP180
int read_raw_pressure(int32_t *up) {
    char buf[3];

    // Write control register to request pressure measurement
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x34 + (OSS << 6); // 0x34 = 0011 0100 = pressure measurement, OSS=3
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for measurement to complete (at OSS=3, ~4.5ms)
    gpioDelay(5000); // 5ms

    // Read MSB, LSB, and XLSB from registers 0xF6, 0xF7, and 0xF8
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading pressure data\n");
        return -1;
    }

    *up = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | (int32_t)buf[2];

    return 0;
}

// Function to calculate temperature in Celsius
double calculate_temperature(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    return ((b5 + 8) >> 4) / 10.0;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int32_t up, int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << OSS) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (double)p;
}

// Function to calculate altitude in meters
double calculate_altitude(double pressure) {
    return 44330.0 * (1.0 - pow(pressure / 101325.0, 0.1903));
}

// Function to log data to a file
int log_data(double temperature, double pressure, double altitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO2 as input with pull-up
    gpioSetMode(2, PI_INPUT);
    gpioSetPullUpDown(2, PI_PUD_UP);

    // Set up interrupt handler for falling edge
    if (gpioSetAlertFuncEx(2, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("BMP180 data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup
    printf("\nCleaning up...\n");
    gpioSetAlertFuncEx(2, NULL, NULL); // Disable interrupt handler
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exited cleanly.\n");
    return 0;
}

