#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define CS_LINE_OFFSET 8
#define LOG_FILE "rtd_log.csv"
#define READ_INTERVAL_SEC 5

#define MAX31865_REG_CONFIG 0x00
#define MAX31865_REG_RTD_MSB 0x01
#define MAX31865_REG_RTD_LSB 0x02
#define MAX31865_REG_RTD_CRC 0x03
#define MAX31865_REG_FAULT 0x04

#define CONFIG_3WIRE 0x0000
#define CONFIG_BIAS_ON 0x0001
#define CONFIG_FAULT_ENABLE 0x0002
#define CONFIG_FAULT_THRESHOLD 0x0004
#define CONFIG_FAULT_CLEAR 0x0008

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Failed to assert CS line: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS line: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int max31865_write_reg(uint8_t reg, uint16_t value) {
    uint8_t tx[4] = {reg, (uint8_t)(value >> 8), (uint8_t)(value & 0xFF), 0x00};
    uint8_t rx[4] = {0};
    return spi_transfer(tx, rx, 4);
}

static int max31865_read_reg(uint8_t reg, uint16_t *value) {
    uint8_t tx[4] = {reg, 0x00, 0x00, 0x00};
    uint8_t rx[4] = {0};
    if (spi_transfer(tx, rx, 4) < 0) return -1;
    *value = ((uint16_t)rx[1] << 8) | rx[2];
    return 0;
}

static int max31865_init(void) {
    if (max31865_write_reg(MAX31865_REG_CONFIG, CONFIG_3WIRE | CONFIG_BIAS_ON | CONFIG_FAULT_ENABLE) < 0) {
        fprintf(stderr, "Failed to initialize MAX31865: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_rtd_raw(uint16_t *rtd_raw) {
    if (max31865_read_reg(MAX31865_REG_RTD_MSB, rtd_raw) < 0) return -1;
    return 0;
}

static int check_fault(uint16_t *fault_status) {
    if (max31865_read_reg(MAX31865_REG_FAULT, fault_status) < 0) return -1;
    return 0;
}

static float calculate_temperature(uint16_t rtd_raw) {
    float rtd_resistance = (float)rtd_raw * 3300.0f / 65536.0f;
    if (rtd_resistance <= 0.0f) return -1000.0f;

    float rtd_temp = 100.0f * log10f(rtd_resistance / 1000.0f);
    float temp_celsius = rtd_temp - 25.0f;
    return temp_celsius;
}

static void log_data(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "Failed to get CS line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "max31865-cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        cleanup();
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (max31865_init() < 0) {
        fprintf(stderr, "MAX31865 initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(log_file, "Timestamp,Temperature (C)\n");
    fflush(log_file);

    while (running) {
        uint16_t rtd_raw = 0;
        uint16_t fault_status = 0;

        if (read_rtd_raw(&rtd_raw) < 0) {
            fprintf(stderr, "Failed to read RTD raw data\n");
            log_data(-1000.0f);
        } else if (check_fault(&fault_status) < 0) {
            fprintf(stderr, "Failed to check fault status\n");
            log_data(-1000.0f);
        } else if (fault_status & 0x0001) {
            fprintf(stderr, "MAX31865 fault detected: 0x%04X\n", fault_status);
            log_data(-1000.0f);
        } else {
            float temperature = calculate_temperature(rtd_raw);
            log_data(temperature);
        }

        sleep(READ_INTERVAL_SEC);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

