#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_CAL_AC1 0xAA

// Alert GPIO pin
#define ALERT_GPIO 24

// Circular buffer size (seconds)
#define BUFFER_SIZE 60

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t running = 1;

// Calibration coefficients
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float pressure;
} BufferEntry;

BufferEntry buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_calibration_data();
int read_raw_temperature();
int read_raw_pressure();
float calculate_pressure(int ut);
float calculate_average_pressure(int num_entries);
void check_pressure_alert(float current_pressure, float average_pressure);
void signal_handler(int signal);
void timer_callback(void *user_data);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Timer callback function
void timer_callback(void *user_data) {
    (void)user_data;

    // Read raw temperature
    int ut = read_raw_temperature();
    if (ut < 0) {
        fprintf(stderr, "Error reading raw temperature\n");
        return;
    }

    // Read raw pressure
    int up = read_raw_pressure();
    if (up < 0) {
        fprintf(stderr, "Error reading raw pressure\n");
        return;
    }

    // Calculate pressure
    float pressure = calculate_pressure(ut);

    // Add to circular buffer
    buffer[buffer_index].timestamp = time(NULL);
    buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    // Calculate average pressure
    float average_pressure = calculate_average_pressure(BUFFER_SIZE);

    // Check pressure alert
    check_pressure_alert(pressure, average_pressure);

    // Log data to console
    printf("Timestamp: %ld, Pressure: %.2f hPa, Average Pressure: %.2f hPa\n",
           buffer[buffer_index].timestamp, pressure, average_pressure);
}

// Function to read calibration data from BMP180
int read_calibration_data() {
    // Read 22 bytes of calibration data starting from register 0xAA
    char data[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, data, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    // Parse calibration coefficients
    ac1 = (int16_t)((data[0] << 8) | data[1]);
    ac2 = (int16_t)((data[2] << 8) | data[3]);
    ac3 = (int16_t)((data[4] << 8) | data[5]);
    ac4 = (uint16_t)((data[6] << 8) | data[7]);
    ac5 = (uint16_t)((data[8] << 8) | data[9]);
    ac6 = (uint16_t)((data[10] << 8) | data[11]);
    b1 = (int16_t)((data[12] << 8) | data[13]);
    b2 = (int16_t)((data[14] << 8) | data[15]);
    mb = (int16_t)((data[16] << 8) | data[17]);
    mc = (int16_t)((data[18] << 8) | data[19]);
    md = (int16_t)((data[20] << 8) | data[21]);

    return 0;
}

// Function to read raw temperature from BMP180
int read_raw_temperature() {
    // Write 0x2E to control register for temperature measurement
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) {
        fprintf(stderr, "Error writing to control register\n");
        return -1;
    }

    // Wait for measurement (at OSS=0, 4.5 ms max)
    gpioDelay(5000);

    // Read MSB and LSB from register 0xF6
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading MSB from temperature register\n");
        return -1;
    }

    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 1);
    if (lsb < 0) {
        fprintf(stderr, "Error reading LSB from temperature register\n");
        return -1;
    }

    // Combine MSB and LSB to form temperature value
    int ut = (msb << 8) | lsb;

    return ut;
}

// Function to read raw pressure from BMP180
int read_raw_pressure() {
    // Write 0x34 to control register for pressure measurement (OSS=0)
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34) < 0) {
        fprintf(stderr, "Error writing to control register\n");
        return -1;
    }

    // Wait for measurement (at OSS=0, 4.5 ms max)
    gpioDelay(5000);

    // Read MSB, LSB, and XLSB from registers 0xF6, 0xF7, and 0xF8
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading MSB from pressure register\n");
        return -1;
    }

    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 1);
    if (lsb < 0) {
        fprintf(stderr, "Error reading LSB from pressure register\n");
        return -1;
    }

    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 2);
    if (xlsb < 0) {
        fprintf(stderr, "Error reading XLSB from pressure register\n");
        return -1;
    }

    // Combine MSB, LSB, and XLSB to form pressure value
    int up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - 0);

    return up;
}

// Function to calculate pressure from raw temperature and pressure
float calculate_pressure(int ut) {
    // Calculate temperature compensation
    int x1 = ((ut - (int)ac6) * (int)ac5) >> 15;
    int x2 = ((int)mc << 11) / (x1 + (int)md);
    int b5 = x1 + x2;
    float temperature = ((b5 + 8) >> 4) / 10.0f;

    // Calculate pressure compensation
    int b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6 >> 12)) >> 11;
    x2 = (ac2 * b6) >> 11;
    int x3 = x1 + x2;
    int b3 = (((((int)ac1) * 4 + x3) << 0) + 2) >> 2;

    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = (ac4 * (uint32_t)(x3 + 32768)) >> 15;

    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);

    int p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    return (float)p / 100.0f;
}

// Function to calculate the average pressure over a specified number of entries
float calculate_average_pressure(int num_entries) {
    if (num_entries <= 0) {
        return 0.0f;
    }

    float sum = 0.0f;
    int count = 0;

    for (int i = 0; i < num_entries; i++) {
        int index = (buffer_index - num_entries + i + BUFFER_SIZE) % BUFFER_SIZE;
        if (buffer[index].pressure > 0.0f) {
            sum += buffer[index].pressure;
            count++;
        }
    }

    if (count == 0) {
        return 0.0f;
    }

    return sum / count;
}

// Function to check if the current pressure deviates from the average pressure by more than 5 hPa
void check_pressure_alert(float current_pressure, float average_pressure) {
    if (average_pressure <= 0.0f) {
        return;
    }

    float deviation = fabsf(current_pressure - average_pressure);
    if (deviation > 5.0f) {
        printf("ALERT: Pressure deviation exceeds 5 hPa! Current Pressure: %.2f hPa, Average Pressure: %.2f hPa\n",
               current_pressure, average_pressure);

        // Set GPIO high to activate alert
        gpioWrite(ALERT_GPIO, 1);
        gpioDelay(1000000); // 1 second delay
        gpioWrite(ALERT_GPIO, 0);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data. Sensor may be absent.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set alert GPIO as output and ensure it is low initially
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0);

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Set up timer for pressure sampling
    if (gpioSetTimerFuncEx(0, 50, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up timer\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("BMP180 pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100000); // 100 ms delay to prevent busy-waiting
    }

    // Cleanup
    printf("\nCleaning up...\n");
    gpioSetTimerFuncEx(0, 50, NULL, NULL); // Disable timer
    gpioWrite(ALERT_GPIO, 0); // Ensure alert GPIO is off
    i2cClose(i2c_handle); // Close I2C connection
    gpioTerminate(); // Terminate pigpio

    return 0;
}

