#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0 = ultra low power)
#define OSS 0

// Global variables
int i2c_handle;
volatile sig_atomic_t running = 1;

// Calibration data structure
typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_data;

// Function prototypes
int read_calibration_data(int handle, bmp180_cal_data *cal);
int read_raw_temperature(int handle, int32_t *ut);
int read_raw_pressure(int handle, int32_t *up);
double calculate_temperature(int32_t ut, bmp180_cal_data cal);
double calculate_pressure(int32_t up, int32_t ut, bmp180_cal_data cal);
void log_data(double temperature, double pressure);
void signal_handler(int signal);
void timer_callback(void *user_data);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Timer callback function
void timer_callback(void *user_data) {
    (void)user_data;
    static int consecutive_errors = 0;
    int32_t ut, up;
    double temperature, pressure;

    if (read_raw_temperature(i2c_handle, &ut) != 0) {
        consecutive_errors++;
        fprintf(stderr, "Error reading temperature (consecutive: %d)\n", consecutive_errors);
        if (consecutive_errors >= 10) {
            fprintf(stderr, "Too many consecutive errors, aborting.\n");
            running = 0;
        }
        return;
    }
    consecutive_errors = 0;

    if (read_raw_pressure(i2c_handle, &up) != 0) {
        consecutive_errors++;
        fprintf(stderr, "Error reading pressure (consecutive: %d)\n", consecutive_errors);
        if (consecutive_errors >= 10) {
            fprintf(stderr, "Too many consecutive errors, aborting.\n");
            running = 0;
        }
        return;
    }
    consecutive_errors = 0;

    temperature = calculate_temperature(ut, cal);
    pressure = calculate_pressure(up, ut, cal);

    log_data(temperature, pressure);
}

// Function to read calibration data from the BMP180
int read_calibration_data(int handle, bmp180_cal_data *cal) {
    char buf[22];

    // Read 22 bytes of calibration data starting from 0xAA
    if (i2cReadI2CBlockData(handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    cal->ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    cal->ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    cal->ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    cal->ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    cal->ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    cal->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    cal->b1 = (int16_t)((buf[12] << 8) | buf[13]);
    cal->b2 = (int16_t)((buf[14] << 8) | buf[15]);
    cal->mb = (int16_t)((buf[16] << 8) | buf[17]);
    cal->mc = (int16_t)((buf[18] << 8) | buf[19]);
    cal->md = (int16_t)((buf[20] << 8) | buf[21]);

    return 0;
}

// Function to read raw temperature from the BMP180
int read_raw_temperature(int handle, int32_t *ut) {
    char buf[2];

    // Write the control byte to request temperature measurement
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // 0x2E = 0010 1110 = temp measurement, OSS = 0

    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device for temperature\n");
        return -1;
    }

    // Wait for measurement to complete (at OSS=0, ~5.5ms)
    gpioDelay(5500);

    // Read 2 bytes of temperature data starting from 0xF6
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    *ut = (int32_t)((buf[0] << 8) | buf[1]);

    return 0;
}

// Function to read raw pressure from the BMP180
int read_raw_pressure(int handle, int32_t *up) {
    char buf[3];

    // Write the control byte to request pressure measurement
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x34 + (OSS << 6); // 0x34 = 0011 0100, OSS = 0

    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device for pressure\n");
        return -1;
    }

