    gpioDelay(4500);

    // Read 3 bytes of pressure data starting from 0xF6
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading pressure data\n");
        return -1;
