double calculate_temperature(int32_t ut, bmp180_cal_data cal) {
    int32_t x1 = ((ut - (int32_t)cal.ac6) * (int32_t)cal.ac5) >> 15;
    int32_t x2 = ((int32_t)cal.mc << 11) / (x1 + (int32_t)cal.md);
    int32_t b5 = x1 + x2;
    return ((b5 + 8) >> 4) / 10.0;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int32_t up, int32_t ut, bmp180_cal_data cal) {
    int32_t x1 = ((ut - (int32_t)cal.ac6) * (int32_t)cal.ac5) >> 15;
    int32_t x2 = ((int32_t)cal.mc << 11) / (x1 + (int32_t)cal.md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)cal.b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)cal.ac2 * b6) >> 11;
