    }

    // Cleanup
    gpioSetTimerFuncEx(0, 500, NULL, NULL); // Disable timer interrupt
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("BMP180 sensor logging stopped.\n");

    return 0;
}

