#define BMP280_CALIB_REG 0x88
#define BMP280_CALIB_LEN 24
#define BMP280_MEAS_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
