}

static int bmp280_read_raw(int fd, int32_t *raw_t, int32_t *raw_p) {
    uint8_t status;
    for (int i = 0; i < BMP280_MEAS_TIMEOUT_MS; i++) {
        if (i2c_read_regs(fd, BMP280_PRESS_MSB_REG, &status, 1) < 0) return -1;
        if (!(status & 0x08)) break;
