        close(i2c_fd);
        return 1;
    }

    while (running) {
        int32_t raw_t, raw_p;
        if (bmp280_read_raw(i2c_fd, &raw_t, &raw_p) < 0) {
            fprintf(stderr, "Failed to read raw data, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        int32_t t_fine;
        double temperature = compensate_temperature(raw_t, (const int16_t *)dig_T, &t_fine) / 100.0;
        double pressure = compensate_pressure(raw_p, t_fine, (const int16_t *)dig_P, &pressure);

