#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_FLAGS 0
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define MAX_TEMP 80.0
#define LOOP_DELAY_US 100000
#define CONFIG_FILE "config.json"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static double target_temp = 25.0;
static double Kp = 1.0;
static double Ki = 0.1;
static double Kd = 0.01;
static double integral = 0.0;
static double previous_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open config file %s, using defaults\n", filename);
        return -1;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, ":");
        char *value = strtok(NULL, "\n");
        if (!key || !value) continue;
        key = strtok(key, " ");
        if (!key) continue;
        if (strcmp(key, "target") == 0) target_temp = atof(value);
        else if (strcmp(key, "Kp") == 0) Kp = atof(value);
        else if (strcmp(key, "Ki") == 0) Ki = atof(value);
        else if (strcmp(key, "Kd") == 0) Kd = atof(value);
    }
    fclose(fp);
    return 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle=%d)\n", spi_handle);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d\n", HEATER_GPIO);
        return -1;
    }
    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for GPIO%d\n", HEATER_GPIO);
        return -1;
    }
    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for GPIO%d\n", HEATER_GPIO);
        return -1;
    }
    return 0;
}

static int read_max31865(double *temperature) {
    unsigned char tx[4] = {0x00, 0x00, 0x00, 0x00};
    unsigned char rx[4] = {0};
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 4);
    if (ret != 4) {
        fprintf(stderr, "Error: spiXfer failed (ret=%d)\n", ret);
        return -1;
    }
    int16_t rtd_code = (rx[0] << 8) | rx[1];
    if (rtd_code & 0x0001) {
        fprintf(stderr, "Error: MAX31865 fault detected (D0=1)\n");
        return -1;
    }
    *temperature = ((double)rtd_code / 32768.0) * 100.0;
    return 0;
}

static double calculate_pid(double current_temp) {
    double error = target_temp - current_temp;
    integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    if (output < 0.0) output = 0.0;
    if (output > 100.0) output = 100.0;
    return output;
}

static void set_heater_pwm(double duty_percent) {
    int pwm_value = (int)(duty_percent * PWM_RANGE / 100.0);
    if (gpioPWM(HEATER_GPIO, pwm_value) != 0) {
        fprintf(stderr, "Error: gpioPWM failed\n");
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioPWM(HEATER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (init_gpio() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (read_config(CONFIG_FILE) != 0) {
        fprintf(stderr, "Error: failed to read config, using defaults\n");
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("Heater control started. Target: %.1f°C, Kp: %.3f, Ki: %.3f, Kd: %.3f\n",
           target_temp, Kp, Ki, Kd);
    while (running) {
        double current_temp;
        if (read_max31865(&current_temp) != 0) {
            fprintf(stderr, "Error: temperature read failed, shutting down\n");
            set_heater_pwm(0.0);
            cleanup();
            return EXIT_FAILURE;
        }
        double duty = calculate_pid(current_temp);
        set_heater_pwm(duty);
        printf("Temp: %.2f°C, Duty: %.1f%%\n", current_temp, duty);
        gpioDelay(LOOP_DELAY_US);
    }
    printf("\nShutting down...\n");
    set_heater_pwm(0.0);
    cleanup();
    return EXIT_SUCCESS;
}

