#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP180_ADDR 0x77
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "breach_log.txt"
#define TEMP_THRESHOLD 30.0f
#define PRESSURE_THRESHOLD 950.0f
#define MAX_RETRIES 3

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        usleep(10000);
    }
    return -1;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) == 1) {
            if (read(fd, value, 1) == 1) return 0;
        }
        usleep(10000);
    }
    return -1;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) == 1) {
            if (read(fd, buf, len) == len) return 0;
        }
        usleep(10000);
    }
    return -1;
}

static int read_calibration_data(int fd, int16_t *ac1, int16_t *ac2, int16_t *ac3, uint16_t *ac4, uint16_t *ac5, uint16_t *ac6, int16_t *b1, int16_t *b2, int16_t *mb, int16_t *mc, int16_t *md) {
    uint8_t buf[22];
    if (i2c_read_burst(fd, BMP180_REG_CAL_AC1, buf, 22) != 0) return -1;
    *ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    *ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    *ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    *ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    *ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    *ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    *b1 = (int16_t)((buf[12] << 8) | buf[13]);
    *b2 = (int16_t)((buf[14] << 8) | buf[15]);
    *mb = (int16_t)((buf[16] << 8) | buf[17]);
    *mc = (int16_t)((buf[18] << 8) | buf[19]);
    *md = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int fd, int32_t *ut) {
    if (i2c_write_reg(fd, BMP180_REG_CONTROL, 0x2E) != 0) return -1;
    usleep(5000);
    uint8_t buf[2];
    if (i2c_read_burst(fd, BMP180_REG_MSB, buf, 2) != 0) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int fd, int32_t *up) {
    if (i2c_write_reg(fd, BMP180_REG_CONTROL, 0x34) != 0) return -1;
    usleep(5000);
    uint8_t buf[3];
    if (i2c_read_burst(fd, BMP180_REG_MSB, buf, 3) != 0) return -1;
    *up = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | buf[2];
    return 0;
}

static int calculate_b5(int32_t ut, int16_t ac6, int16_t ac5, int16_t mc, int16_t md) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static float calculate_temperature(int32_t ut, int16_t ac6, int16_t ac5, int16_t mc, int16_t md) {
    int32_t b5 = calculate_b5(ut, ac6, ac5, mc, md);
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t up, int32_t ut, int16_t ac6, int16_t ac5, int16_t mc, int16_t md, int16_t b1, int16_t b2, int16_t mb, int16_t mc, int16_t md) {
    int32_t b5 = calculate_b5(ut, ac6, ac5, mc, md);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * (b6 * b6 >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 0) + 2) >> 2;
    uint32_t x1_u = ((uint32_t)ac3 * b6) >> 13;
    uint32_t x2_u = ((uint32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    uint32_t x3_u = ((x1_u + x2_u) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3_u + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p;
}

static void log_breach(float temperature, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_fp, "%s - Temperature: %.2f C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

