#include <math.h>

#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define LOG_FILE "heater_log.csv"
#define TARGET_TEMPERATURE 25.0
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define MAX_DUTY_CYCLE 80.0
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(int handle, float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)(rx[0] & 0x03) << 18) |
                   ((uint32_t)(rx[1] & 0xFF) << 10) |
                   ((uint32_t)(rx[2] & 0xFF) << 2)  |
                   ((uint32_t)(rx[3] & 0xC0) >> 6);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault detected\n");
        return -2;
    }

    if (raw & 0x00000004) {
        fprintf(stderr, "MAX31855 short to GND\n");
        return -3;
    }

