#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27
#define TEMP_FILE  "/sys/class/thermal/thermal_zone0/temp"
#define PWM_RANGE  255
#define LOOP_US    500000   /* 0.5 s */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read CPU temperature in m°C from the thermal zone sysfs file.
 * Returns 0 on success and stores the temperature in *out_temp;
 * returns -1 on any error.
 */
static int read_cpu_temp(int *out_temp)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen(" TEMP_FILE ")");
        return -1;
    }

    char buf[16];
    if (!fgets(buf, sizeof(buf), fp)) {
        if (ferror(fp)) {
            perror("fgets");
            fclose(fp);
            return -1;
        }
        /* Empty file or read error: treat as no temperature */
        fclose(fp);
        return 0;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    char *endptr = NULL;
    long millideg = strtol(buf, &endptr, 10);
    if (endptr == buf || *endptr != '\n' && *endptr != '\0') {
        fprintf(stderr, "Warning: invalid temperature data: '%s'\n", buf);
        return -1;
    }

    if (millideg < 0 || millideg > 100000) {
        fprintf(stderr, "Warning: temperature out of range: %ld m°C\n", millideg);
        return -1;
    }

    *out_temp = (int)millideg;
    return 0;
}

/*
 * Set the RGB LED brightness using hardware PWM.
 * Common-anode: duty 255 = fully on, duty 0 = fully off.
 */
static void set_led_color(int r, int g, int b)
{
    int duty_r = PWM_RANGE - r;
    int duty_g = PWM_RANGE - g;
    int duty_b = PWM_RANGE - b;

    if (gpioPWM(RED_PIN, duty_r) < 0)
        fprintf(stderr, "gpioPWM(RED_PIN) failed\n");
    if (gpioPWM(GREEN_PIN, duty_g) < 0)
        fprintf(stderr, "gpioPWM(GREEN_PIN) failed\n");
    if (gpioPWM(BLUE_PIN, duty_b) < 0)
        fprintf(stderr, "gpioPWM(BLUE_PIN) failed\n");
}

/*
 * Map temperature (m°C) to RGB color values.
 * Returns 0 on success and stores RGB values in *r, *g, *b;
 * returns -1 on any error.
 */
static int map_temperature_to_rgb(int temp, int *r, int *g, int *b)
{
    if (temp < 40000) {
        *r = 0;
        *g = 0;
        *b = 255;
    } else if (temp < 60000) {
        *r = 0;
        *g = 255;
        *b = 0;
    } else {
        *r = 255;
        *g = 0;
        *b = 0;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as outputs */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(RED_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(GREEN_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(BLUE_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range for each pin */
    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange(RED_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange(GREEN_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange(BLUE_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at startup (common-anode: duty 255 = off) */
    if (gpioPWM(RED_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioPWM(RED_PIN, PWM_RANGE) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(GREEN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioPWM(GREEN_PIN, PWM_RANGE) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(BLUE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioPWM(BLUE_PIN, PWM_RANGE) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Mood light control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int temp;
        if (read_cpu_temp(&temp) != 0) {
            fprintf(stderr, "Failed to read CPU temperature; skipping cycle.\n");
        } else {
            int r, g, b;
            if (map_temperature_to_rgb(temp, &r, &g, &b) != 0) {
                fprintf(stderr, "Failed to map temperature to RGB; skipping cycle.\n");
            } else {
                set_led_color(r, g, b);
                printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n",
                       temp, r, g, b);
            }
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++) {
            usleep(10000); /* 10 ms */
        }
    }

    /* Clean shutdown: turn off LED and terminate pigpio */
    printf("\nShutting down...\n");
    set_led_color(0, 0, 0);
    gpioTerminate();
    printf("Mood light control stopped.\n");
    return EXIT_SUCCESS;
}

