#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 2
#define READ_INTERVAL_SEC 10
#define DHT22_START_LOW_US 20000
#define DHT22_START_HIGH_US 30
#define DHT22_RESPONSE_TIMEOUT_US 100000
#define DHT22_BIT_TIMEOUT_US 100

static volatile sig_atomic_t running = 1;
static char *server_url = "http://your-server.com/api/humidity";

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int last_level = 1;
    uint32_t start_tick, end_tick;
    int timeout;

    /* --- Start signal: pull low for >= 1 ms, then high for 20-40 µs --- */
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(DHT22_START_LOW_US);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(DHT22_START_HIGH_US);
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    /* --- Wait for sensor response: low ~80 µs, then high ~80 µs --- */
    timeout = DHT22_RESPONSE_TIMEOUT_US;
    while (gpioRead(DHT22_GPIO) == 1) {
        if (--timeout <= 0) return -1;
        gpioDelay(1);
    }
    timeout = DHT22_RESPONSE_TIMEOUT_US;
    while (gpioRead(DHT22_GPIO) == 0) {
        if (--timeout <= 0) return -1;
        gpioDelay(1);
    }
    timeout = DHT22_RESPONSE_TIMEOUT_US;
    while (gpioRead(DHT22_GPIO) == 1) {
        if (--timeout <= 0) return -1;
        gpioDelay(1);
    }

    /* --- Read 40 data bits --- */
    for (bit_idx = 0; bit_idx < 40; bit_idx++) {
        /* Wait for low-to-high transition (end of bit) */
        timeout = DHT22_BIT_TIMEOUT_US;
        while (gpioRead(DHT22_GPIO) == 0) {
            if (--timeout <= 0) return -1;
            gpioDelay(1);
        }
        start_tick = gpioTick();

        /* Wait for high-to-low transition (end of bit) */
        timeout = DHT22_BIT_TIMEOUT_US;
        while (gpioRead(DHT22_GPIO) == 1) {
            if (--timeout <= 0) return -1;
            gpioDelay(1);
        }
        end_tick = gpioTick();

        uint32_t duration = end_tick - start_tick;
        if (duration > 50) {
            data[bit_idx / 8] |= (1 << (7 - (bit_idx % 8)));
        }
    }

    /* --- Checksum --- */
    int checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (checksum != data[4]) {
        syslog(LOG_ERR, "DHT22 checksum mismatch: computed 0x%02X, received 0x%02X", checksum, data[4]);
        return -1;
    }

    *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
    return 0;
}

static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    char **response = (char **)userp;
    char *ptr = realloc(*response, strlen(*response) + realsize + 1);
    if (!ptr) {
        syslog(LOG_ERR, "Memory allocation failed");
        return 0;
    }
    *response = ptr;
    memcpy(*response + strlen(*response), contents, realsize);
    (*response)[strlen(*response) + realsize] = '\0';
    return realsize;
}

static int post_humidity(float humidity) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "curl_easy_init() failed");
        return -1;
    }

    char json_data[64];
    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        syslog(LOG_ERR, "Failed to set HTTP headers");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, server_url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&server_response);

    CURLcode res = curl_easy_perform(curl);
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    if (res != CURLE_OK) {
        syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        return -1;
    }

    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    if (http_code < 200 || http_code >= 300) {
        syslog(LOG_ERR, "HTTP request failed with status code: %ld", http_code);
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("dht22_sensor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "DHT22 sensor monitoring started on GPIO %d, server: %s", DHT22_GPIO, server_url);

    while (running) {
        float humidity = 0.0f;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (!running) break;

            if (read_dht22(&humidity) == 0) {
                success = 1;
                break;
            }

            syslog(LOG_WARNING, "DHT22 read failed (attempt %d/%d), retrying in %d seconds...",
                   attempt + 1, MAX_RETRIES, RETRY_DELAY_SEC);
            sleep(RETRY_DELAY_SEC);
        }

        if (success) {
            if (post_humidity(humidity) == 0) {
                syslog(LOG_INFO, "Humidity: %.2f%% posted successfully", humidity);
            } else {
                syslog(LOG_ERR, "Failed to post humidity data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity after %d attempts", MAX_RETRIES);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down gracefully...");
    gpioTerminate();
    curl_global_cleanup();
    closelog();
    return EXIT_SUCCESS;
}

