#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define MAX_FAN_SPEED 3
#define TEMP_THRESHOLD_1 45000
#define TEMP_THRESHOLD_2 55000
#define TEMP_THRESHOLD_3 65000
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

static int read_cpu_temp(int *temp_millideg) {
    FILE *fp = fopen(CPU_TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening CPU temperature file: %s\n", strerror(errno));
        return -1;
    }
    if (fscanf(fp, "%d", temp_millideg) != 1) {
        fprintf(stderr, "Error reading CPU temperature\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int set_fan_state(int state) {
    FILE *fp = fopen(FAN_STATE_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening fan state file: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing fan state: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int validate_fan_state(int state) {
    FILE *fp = fopen(FAN_STATE_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening fan state file for validation: %s\n", strerror(errno));
        return -1;
    }
    int max_state;
    if (fscanf(fp, "%d", &max_state) != 1) {
        fprintf(stderr, "Error reading fan state max\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    if (state < 0 || state > max_state) {
        fprintf(stderr, "Invalid fan state %d (must be 0-%d)\n", state, max_state);
        return -1;
    }
    return 0;
}

static int determine_fan_speed(int temp_millideg) {
    if (temp_millideg < TEMP_THRESHOLD_1) {
        return 0;
    } else if (temp_millideg < TEMP_THRESHOLD_2) {
        return 1;
