#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_FLAGS 0
#define LOG_FILE "heater_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_TEMP 100.0
#define MIN_TEMP 0.0
#define FAILSAFE_TEMP 100.0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static double Kp = 1.0;
static double Ki = 0.1;
static double Kd = 0.01;
static double target_temp = 50.0;
static double integral = 0.0;
static double previous_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(double *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)(rx[0] & 0x03) << 16) |
                   ((uint32_t)(rx[1] & 0xFF) << 8)  |
                   ((uint32_t)(rx[2] & 0xFF));

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault: open circuit\n");
        return -2;
    }
    if (raw & 0x00020000) {
        fprintf(stderr, "MAX31855 fault: short to GND\n");
        return -3;
    }
    if (raw & 0x00040000) {
        fprintf(stderr, "MAX31855 fault: short to VCC\n");
        return -4;
    }

    int16_t thermocouple_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (thermocouple_raw & 0x2000) {
        thermocouple_raw |= 0xC000;
    }

    *temperature = thermocouple_raw * 0.25;
    return 0;
}

static double calculate_pid(double current_temp) {
    double error = target_temp - current_temp;
    integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    return output;
}

static void control_heater(double pid_output) {
    int duty_cycle = (int)(pid_output + 0.5);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    gpioPWM(HEATER_GPIO, duty_cycle);
}

static void log_data(double temperature, int duty_cycle, double pid_output) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temp: %.2f C, Duty: %d%%, PID: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, duty_cycle, pid_output);
    fclose(fp);
}

static void failsafe_action(void) {
    fprintf(stderr, "Failsafe triggered! Disabling heater.\n");
    gpioPWM(HEATER_GPIO, 0);
    integral = 0.0;
    previous_error = 0.0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, 1000);
    gpioSetPWMrange(HEATER_GPIO, 100);
    gpioPWM(HEATER_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("PID controller started. Target: %.1f C\n", target_temp);

    while (running) {
        double temperature;
        int ret = read_max31855(&temperature);

        if (ret == 0) {
            double pid_output = calculate_pid(temperature);
            control_heater(pid_output);
            int duty_cycle = (int)(pid_output + 0.5);
            log_data(temperature, duty_cycle, pid_output);

            if (temperature > FAILSAFE_TEMP || temperature < MIN_TEMP) {
                failsafe_action();
            }
        } else {
            fprintf(stderr, "Error reading temperature: %d\n", ret);
            log_data(-999.0, -1, -1.0);
            failsafe_action();
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioPWM(HEATER_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

