#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define POLL_INTERVAL_SEC 5
#define MIN_TEMP_C 40.0
#define MAX_TEMP_C 70.0
#define MIN_DUTY 0
#define MAX_DUTY 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("Error opening temperature file");
        return -1;
    }
    int temp_millideg;
    if (fscanf(fp, "%d", &temp_millideg) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp_millideg / 1000;
}

static int calculate_duty_cycle(int temp_c) {
    if (temp_c < MIN_TEMP_C) {
        return MIN_DUTY;
    } else if (temp_c > MAX_TEMP_C) {
        return MAX_DUTY;
    }
    double frac = (temp_c - MIN_TEMP_C) / (MAX_TEMP_C - MIN_TEMP_C);
    return (int)(frac * (MAX_DUTY - MIN_DUTY) + MIN_DUTY);
}

static int set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        return -1;
    }
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

static int log_data(int temp_c, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (!tm) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%d,%d\n", timestamp, temp_c, duty_cycle);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, 25000) != 25000) {
        fprintf(stderr, "Failed to set PWM frequency to 25 kHz\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, 100) != 100) {
        fprintf(stderr, "Failed to set PWM range to 100\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handler");
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Cooling system started. Press Ctrl+C to exit.\n");

    while (running) {
        int temp_c = read_cpu_temp();
        if (temp_c < 0) {
            fprintf(stderr, "Failed to read CPU temperature, skipping cycle\n");
        } else {
            int duty_cycle = calculate_duty_cycle(temp_c);
            if (set_fan_speed(duty_cycle) != 0) {
                fprintf(stderr, "Failed to set fan speed\n");
            }
            if (log_data(temp_c, duty_cycle) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
            printf("Temperature: %d°C, Duty Cycle: %d%%\n", temp_c, duty_cycle);
        }
        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    printf("Cooling system stopped.\n");
    return EXIT_SUCCESS;
}

