        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%d,%d\n", timestamp, temp_c, duty_cycle);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, 25000) != 25000) {
        fprintf(stderr, "Failed to set PWM frequency to 25 kHz\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, 100) != 100) {
        fprintf(stderr, "Failed to set PWM range to 100\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handler");
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Cooling system started. Press Ctrl+C to exit.\n");

    while (running) {
        int temp_c = read_cpu_temp();
        if (temp_c < 0) {
            fprintf(stderr, "Failed to read CPU temperature, skipping cycle\n");
        } else {
            int duty_cycle = calculate_duty_cycle(temp_c);
            if (set_fan_speed(duty_cycle) != 0) {
                fprintf(stderr, "Failed to set fan speed\n");
            }
            if (log_data(temp_c, duty_cycle) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
            printf("Temperature: %d°C, Duty Cycle: %d%%\n", temp_c, duty_cycle);
        }
        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    printf("Cooling system stopped.\n");
    return EXIT_SUCCESS;
}

