#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define MEASUREMENT_CMD 0x3608
#define LOG_FILE "flow_log.txt"
#define RETRY_COUNT 3
#define POLL_INTERVAL_US 1000000

static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t cmd[2] = { (MEASUREMENT_CMD >> 8) & 0xFF, MEASUREMENT_CMD & 0xFF };
    uint8_t buf[3];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write error (handle %d): %d\n", handle, retries + 1);
            retries++;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(10000);

        int bytes_read = i2cReadDevice(handle, (char *)buf, 3);
        if (bytes_read != 3) {
            fprintf(stderr, "I2C read error (handle %d): expected 3 bytes, got %d\n", handle, bytes_read);
            retries++;
            gpioDelay(10000);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "CRC mismatch on handle %d\n", handle);
            retries++;
            gpioDelay(10000);
            continue;
        }

        int16_t raw = (buf[0] << 8) | buf[1];
        *flow_rate = (float)raw * 0.01f;
        return 0;
    }

    fprintf(stderr, "Failed to read flow rate after %d retries\n", RETRY_COUNT);
    return -1;
}

static void log_flow_rates(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1 (addr 0x%02X): %d\n", SENSOR1_ADDR, i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2 (addr 0x%02X): %d\n", SENSOR2_ADDR, i2c_handle2);
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float flow1 = 0.0f, flow2 = 0.0f;

        if (read_flow_rate(i2c_handle1, &flow1) == 0) {
            if (read_flow_rate(i2c_handle2, &flow2) == 0) {
                log_flow_rates(flow1, flow2);
                printf("Flow1: %.2f ml/min, Flow2: %.2f ml/min\n", flow1, flow2);
            } else {
                fprintf(stderr, "Failed to read flow rate from sensor 2\n");
            }
        } else {
            fprintf(stderr, "Failed to read flow rate from sensor 1\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Flow monitoring stopped.\n");
    return EXIT_SUCCESS;
}

