#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18
#define PULSES_PER_REVOLUTION 360
#define LOG_FILE "encoder_log.txt"

static volatile int running = 1;
static volatile int encoder_count = 0;
static volatile int last_state = 0;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int read_encoder_state(int pin) {
    int state = gpioRead(pin);
    if (state < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return state;
}

int calculate_angle(int count) {
    return (count * 360) / PULSES_PER_REVOLUTION;
}

int log_data(int angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Angle: %.2f degrees\n", timestamp, angle);
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_A_PIN, PI_INPUT);
    gpioSetMode(SENSOR_B_PIN, PI_INPUT);

    gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int state_a = read_encoder_state(SENSOR_A_PIN);
        int state_b = read_encoder_state(SENSOR_B_PIN);

        if (state_a < 0 || state_b < 0) {
            gpioDelay(100000);
            continue;
        }

        int new_state = (state_a << 1) | state_b;

        if (new_state != last_state) {
            encoder_count += (new_state - last_state) & 3;
            last_state = new_state;

            int angle = calculate_angle(encoder_count);
            if (log_data(angle) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        }

        gpioDelay(10000);
    }

    gpioTerminate();
    printf("Encoder monitoring stopped.\n");
    return 0;
}

