#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define ADPD144RI_I2C_ADDR 0x39
#define ADPD144RI_FIFO_DATA_REG 0x60
#define LED_GPIO_LINE 17
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "adpd144ri_log.txt"
#define THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int read_adpd144ri_data(int fd, uint16_t *red, uint16_t *ir) {
    uint16_t raw;
    if (i2c_read_reg16(fd, ADPD144RI_FIFO_DATA_REG, &raw) < 0) {
        return -1;
    }
    *red = (raw >> 8) & 0xFF;
    *ir = raw & 0xFF;
    return 0;
}

static void log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp);
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADPD144RI_I2C_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (i2c_write_reg8(i2c_fd, 0x00, 0x00) < 0) {
        fprintf(stderr, "Failed to configure ADPD144RI (sensor absent or bus error)\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "adpd144ri_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("ADPD144RI red/IR sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t red, ir;
        if (read_adpd144ri_data(i2c_fd, &red, &ir) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        log_data(log_file, red, ir);

        if (ir > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

