#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>

#define SENSOR_GPIO 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

/*
 * ISR callback: increment pulse counter on rising edge.
 * pigpio dispatches ISRs on a dedicated thread, so we use a mutex
 * to protect the counter.
 */
static void sensor_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;

    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

/*
 * Calculate RPM over the given interval.
 * Returns -1.0 on error (mutex not initialized).
 */
static double calculate_rpm(uint32_t pulses, uint32_t interval_us) {
    if (interval_us == 0) {
        return -1.0;
    }
    double rpm = (double)pulses * 60000000.0 / (double)interval_us;
    return rpm;
}

/*
 * Log RPM with a timestamp to the log file.
 * Returns 0 on success, -1 on error.
 */
static int log_rpm(double rpm) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[80];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %.2f RPM\n", timestamp, rpm) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file\n");
        return -1;
    }

    return 0;
}

/*
 * Signal handler for graceful shutdown.
 */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor GPIO as input with pull-down */
    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register ISR for rising edge detection */
    if (gpioSetISRFuncEx(SENSOR_GPIO, RISING_EDGE, 0, sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed for GPIO %d\n", SENSOR_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        running = 0;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed\n");
        running = 0;
    }

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_GPIO);

    /* Main loop: sample RPM every 1 second */
    while (running) {
        uint32_t start_tick = gpioTick();

        /* Wait for the next sample interval (interruptible by signals) */
        while (running && (gpioTick() - start_tick) < SAMPLE_INTERVAL_US) {
            gpioDelay(1000);  /* 1 ms sleep to reduce CPU usage */
        }

        if (!running) {
            break;
        }

        /* Read and reset pulse counter atomically */
        uint32_t pulses;
        pthread_mutex_lock(&pulse_mutex);
        pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double rpm = calculate_rpm(pulses, SAMPLE_INTERVAL_US);

        if (rpm < 0.0) {
            fprintf(stderr, "Error: invalid RPM calculation\n");
        } else {
            if (log_rpm(rpm) != 0) {
                fprintf(stderr, "Error: failed to log RPM\n");
            } else {
                printf("RPM: %.2f\n", rpm);
            }
        }
    }

    /* Cleanup */
    printf("\nShutting down...\n");

    gpioSetISRFuncEx(SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL);  /* unregister ISR */
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    pthread_mutex_destroy(&pulse_mutex);

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

