#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define MIC_GPIO_LINE 17
#define GAIN_GPIO_LINE 18
#define LOG_FILE "audio_log.txt"
#define SAMPLE_INTERVAL_MS 10

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(const char *filename, int level) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "Error converting time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s LEVEL\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *mic_line = NULL;
    struct gpiod_line *gain_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    mic_line = gpiod_chip_get_line(chip, MIC_GPIO_LINE);
    if (!mic_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", MIC_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    gain_line = gpiod_chip_get_line(chip, GAIN_GPIO_LINE);
    if (!gain_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GAIN_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(mic_line, "max9814-mic") < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", MIC_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(gain_line, "max9814-gain", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GAIN_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    printf("MAX9814 audio logger started. Press Ctrl+C to exit.\n");

    int prev_state = gpiod_line_get_value(mic_line);
    if (prev_state < 0) {
        fprintf(stderr, "Error reading initial GPIO value: %s\n", strerror(errno));
        goto cleanup;
    }

    while (program_running) {
        int current_state = gpiod_line_get_value(mic_line);
        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
            break;
        }

        if (current_state == 1 && prev_state == 0) {
            if (log_event(LOG_FILE, 1) == 0) {
                printf("Peak detected!\n");
            } else {
                fprintf(stderr, "Failed to log event.\n");
            }
        }

        prev_state = current_state;
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (gain_line) {
        gpiod_line_set_value(gain_line, 0);
        gpiod_line_release(gain_line);
    }
    if (mic_line) {
        gpiod_line_release(mic_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Program terminated.\n");
    return ret;
}

