#include <unistd.h>

#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define START_MEASUREMENT_CMD 0x3608
#define FLOW_RATE_SCALE 1000.0f
#define LOG_FILE "flow_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t sensirion_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int initialize_sensor(void) {
    uint8_t cmd[2] = {
        (START_MEASUREMENT_CMD >> 8) & 0xFF,
        START_MEASUREMENT_CMD & 0xFF
    };

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to write start measurement command to I2C device.\n");
        return -1;
    }

    gpioDelay(10000); /* 10 ms settle time after start command */
    return 0;
}

static int read_flow_rate(float *flow_rate) {
    uint8_t buffer[3];

    if (i2cReadDevice(i2c_handle, (char *)buffer, 3) != 3) {
        fprintf(stderr, "Error: Failed to read 3 bytes from I2C device.\n");
        return -1;
    }

    if (sensirion_crc8(buffer, 2) != buffer[2]) {
        fprintf(stderr, "Error: CRC check failed for flow rate data.\n");
        return -1;
    }

    int16_t raw_flow = (int16_t)((buffer[0] << 8) | buffer[1]);
    *flow_rate = (float)raw_flow / FLOW_RATE_SCALE;
    return 0;
}

static void log_flow_rate(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d.\n", SLF3S_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring flow rate from SLF3S-4000B on I2C bus %d, address 0x%02X. Press Ctrl+C to exit.\n", I2C_BUS, SLF3S_ADDR);

    while (!terminate) {
        float flow_rate;

        if (read_flow_rate(&flow_rate) == 0) {
            log_flow_rate(flow_rate);
            printf("Flow Rate: %.2f uL/min\n", flow_rate);
        } else {
            fprintf(stderr, "Warning: Failed to read flow rate, will retry next cycle.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nCleaning up and exiting...\n");

    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

