#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x70
#define LOG_FILE "air_quality_log.csv"
#define READ_INTERVAL_SEC 5

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sensor_data(int handle, uint16_t *tvoc, uint16_t *eco2) {
    char buf[7];
    int result = i2cReadI2CBlockData(handle, 0x00, buf, 7);
    if (result != 7) {
        fprintf(stderr, "Error reading sensor data: expected 7 bytes, got %d\n", result);
        return -1;
    }

    *tvoc = ((uint16_t)(uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    *eco2 = ((uint16_t)(uint8_t)buf[5] << 8) | (uint8_t)buf[4];
    return 0;
}

static float calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    float tvoc_ppb = (float)tvoc;
    float eco2_ppm = (float)eco2;
    float iaq = 100.0f - (tvoc_ppb / 10.0f) - ((eco2_ppm - 400.0f) / 50.0f);
    if (iaq < 0.0f) iaq = 0.0f;
    if (iaq > 100.0f) iaq = 100.0f;
    return iaq;
}

static void log_data(FILE *fp, float iaq, uint16_t tvoc, uint16_t eco2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%u,%u\n", timestamp, iaq, tvoc, eco2);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d, addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,IAQ,TVOC_ppb,eCO2_ppm\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler: %s\n", strerror(errno));
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t tvoc, eco2;

        if (read_sensor_data(i2c_handle, &tvoc, &eco2) == 0) {
            float iaq = calculate_iaq(tvoc, eco2);
            log_data(log_file, iaq, tvoc, eco2);
            printf("TVOC: %u ppb, eCO2: %u ppm, IAQ: %.2f\n", tvoc, eco2, iaq);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying in %d seconds...\n", READ_INTERVAL_SEC);
        }

        for (int i = 0; i < READ_INTERVAL_SEC && !terminate; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

