#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <gpiod.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 2
#define NUM_SAMPLES 1024
#define FILE_NAME "audio_capture.pcm"

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    int fd = -1;
    FILE *fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int16_t *pcm_buffer = NULL;
    int ret = EXIT_FAILURE;

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    // Open I2S device
    fd = open(I2S_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2S device %s: %s\n", I2S_DEVICE, strerror(errno));
        goto cleanup;
    }

    // Configure I2S device
    int format = AFMT_S16_LE;
    int channels = NUM_CHANNELS;
    int rate = SAMPLE_RATE;
    int bits_per_sample = 16;

    if (ioctl(fd, SNDCTL_DSP_SETFMT, &format) < 0) {
        fprintf(stderr, "Error setting I2S format: %s\n", strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, SNDCTL_DSP_CHANNELS, &channels) < 0) {
        fprintf(stderr, "Error setting I2S channels: %s\n", strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, SNDCTL_DSP_SPEED, &rate) < 0) {
        fprintf(stderr, "Error setting I2S rate: %s\n", strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, SNDCTL_DSP_BITS_PER_SAMPLE, &bits_per_sample) < 0) {
        fprintf(stderr, "Error setting I2S bits per sample: %s\n", strerror(errno));
        goto cleanup;
    }

    // Open GPIO chip and line for microphone L/R select
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "inmp441_mic", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    // Allocate memory for PCM buffer
    pcm_buffer = (int16_t *)malloc(NUM_SAMPLES * sizeof(int16_t));
    if (!pcm_buffer) {
        fprintf(stderr, "Error allocating memory for PCM buffer\n");
        goto cleanup;
    }

    // Open file for writing
    fp = fopen(FILE_NAME, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", FILE_NAME, strerror(errno));
        goto cleanup;
    }

    printf("Starting audio capture. Press Ctrl+C to stop.\n");

    // Main loop
    while (running) {
        // Select left channel (set GPIO low)
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Error setting GPIO low: %s\n", strerror(errno));
            goto cleanup;
        }

        // Read 32-bit frame (24-bit left-justified in 32-bit word)
        uint32_t frame;
        ssize_t bytes_read = read(fd, &frame, sizeof(frame));
        if (bytes_read != sizeof(frame)) {
            if (bytes_read < 0) {
                fprintf(stderr, "Error reading from I2S device: %s\n", strerror(errno));
            } else {
                fprintf(stderr, "Error reading from I2S device: unexpected bytes read\n");
            }
            goto cleanup;
        }

        // Extract 24-bit left-justified data (bits 23:8)
        int32_t left_data = (frame >> 8) & 0x00FFFFFF;

        // Right channel (set GPIO high)
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Error setting GPIO high: %s\n", strerror(errno));
            goto cleanup;
        }

        // Read 32-bit frame (24-bit left-justified in 32-bit word)
        bytes_read = read(fd, &frame, sizeof(frame));
        if (bytes_read != sizeof(frame)) {
            if (bytes_read < 0) {
                fprintf(stderr, "Error reading from I2S device: %s\n", strerror(errno));
            } else {
                fprintf(stderr, "Error reading from I2S device: unexpected bytes read\n");
            }
            goto cleanup;
        }

        // Extract 24-bit left-justified data (bits 23:8)
        int32_t right_data = (frame >> 8) & 0x00FFFFFF;

        // Right channel is unused, so we use left channel for PCM
        int16_t pcm_sample = (int16_t)left_data;

        // Write PCM sample to file
        if (fwrite(&pcm_sample, sizeof(pcm_sample), 1, fp) != 1) {
            fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    printf("\nAudio capture stopped.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp) {
        fclose(fp);
    }
    if (pcm_buffer) {
        free(pcm_buffer);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

