#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FLAME_SENSOR_GPIO 4
#define FAN_GPIO 18
#define PWM_FREQUENCY 100
#define PWM_RANGE 255
#define DEBOUNCE_DELAY_US 50000
#define POLL_DELAY_US 50000
#define FLAME_TIMEOUT_US 1000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input.\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d.\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO %d.\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize PWM on GPIO %d.\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_GPIO);
    if (value < 0) {
        fprintf(stderr, "Error: Failed to read GPIO %d.\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    return value;
}

static void control_fan(int flame_detected) {
    if (flame_detected) {
        int duty_cycle = (int)(80.0 * (1.0 - exp(-0.001 * (double)FLAME_TIMEOUT_US)));
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
        if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
            fprintf(stderr, "Error: Failed to set PWM duty cycle on GPIO %d.\n", FAN_GPIO);
        }
    } else {
        if (gpioPWM(FAN_GPIO, 0) != 0) {
            fprintf(stderr, "Error: Failed to turn off PWM on GPIO %d.\n", FAN_GPIO);
        }
    }
}

static void cleanup(void) {
    gpioPWM(FAN_GPIO, 0);
    gpioSetMode(FAN_GPIO, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioTerminate();
    if (log_file) {
        log_event("System shutdown");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    log_event("System started");

    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed");
        cleanup();
        return 1;
    }

    log_event("GPIO initialized successfully");

    int flame_detected = 0;
    uint32_t flame_start_tick = 0;
    uint32_t last_poll_tick = gpioTick();

    while (running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        uint32_t current_tick = gpioTick();
        uint32_t elapsed_us = current_tick - last_poll_tick;
        last_poll_tick = current_tick;

        if (sensor_value == 0 && !flame_detected) {
            flame_detected = 1;
            flame_start_tick = current_tick;
            log_event("Flame detected");
        } else if (sensor_value == 1 && flame_detected) {
            uint32_t flame_duration = current_tick - flame_start_tick;
            if (flame_duration > FLAME_TIMEOUT_US) {
                flame_detected = 0;
                log_event("Flame ended");
            }
        }

        control_fan(flame_detected);

        gpioDelay(DEBOUNCE_DELAY_US);
    }

    log_event("Shutting down");
    cleanup();
    return 0;
}

