#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define TRIGGER_PIN 23
#define DATA_READY_PIN 24
#define FRAME_SIZE 32768
#define LOG_FILE "radar_data.bin"

#pragma pack(push, 1)
typedef struct {
    uint32_t magic;
    uint64_t timestamp;
    uint32_t start_freq;
    uint32_t end_freq;
    uint32_t chirps;
    uint32_t samples;
    uint32_t frame_period_ms;
} RadarConfig;
#pragma pack(pop)

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", DATA_READY_PIN);
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO %d low\n", TRIGGER_PIN);
        return -1;
    }
    return 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle=%d)\n", spi_handle);
        return -1;
    }
    return 0;
}

static int trigger_radar(void) {
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d high\n", TRIGGER_PIN);
        return -1;
    }
    gpioDelay(1000);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d low\n", TRIGGER_PIN);
        return -1;
    }
    return 0;
}

static int read_data_ready(void) {
    int ready = gpioRead(DATA_READY_PIN);
    if (ready < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d\n", DATA_READY_PIN);
        return -1;
    }
    return ready;
}

static int read_radar_data(uint8_t *data, int len) {
    int bytes_read = spiXfer(spi_handle, (char *)data, (char *)data, len);
    if (bytes_read != len) {
        fprintf(stderr, "Error: spiXfer returned %d (expected %d)\n", bytes_read, len);
        return -1;
    }
    return 0;
}

static int log_radar_data(const uint8_t *data, int len, int frame_number) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    uint64_t timestamp = (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)ts.tv_nsec / 1000ULL;

    RadarConfig config = {
        .magic = 0x52444144,
        .timestamp = timestamp,
        .start_freq = 77000000ULL,
        .end_freq = 79000000ULL,
        .chirps = 64,
        .samples = 256,
        .frame_period_ms = 100
    };

    if (fwrite(&config, sizeof(config), 1, log_file) != 1) {
        perror("fwrite config");
        return -1;
    }
    if (fwrite(data, 1, len, log_file) != (size_t)len) {
        perror("fwrite data");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (init_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "wb");
    if (log_file == NULL) {
        perror("fopen log file");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Radar data acquisition started. Press Ctrl+C to stop.\n");

    while (running) {
        if (trigger_radar() != 0) {
            break;
        }

        int ready = 0;
        int timeout = 0;
        while (!ready && running) {
            ready = read_data_ready();
            if (ready < 0) {
                break;
            }
            if (!ready) {
                gpioDelay(1000);
                timeout++;
                if (timeout > 100) {
                    fprintf(stderr, "Error: Data-ready timeout\n");
                    break;
                }
            }
        }

        if (!running) {
            break;
        }

        if (ready == 0) {
            continue;
        }

        uint8_t *data = malloc(FRAME_SIZE);
        if (data == NULL) {
            fprintf(stderr, "Error: malloc failed for frame data\n");
            break;
        }

        if (read_radar_data(data, FRAME_SIZE) != 0) {
            free(data);
            break;
        }

        int frame_number = 0;
        if (log_radar_data(data, FRAME_SIZE, frame_number) != 0) {
            free(data);
            break;
        }
        frame_number++;

        free(data);
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("Radar data acquisition stopped.\n");
    return 0;
}

