#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 20
#define LOG_FILE "flame_log.txt"
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(const char *event_type) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        fprintf(stderr, "Error converting time to UTC\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - %s\n", timestamp, event_type) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_request_input(line, "flame_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    int last_value = -1;
    int current_value;

    while (program_running) {
        current_value = gpiod_line_get_value(line);
        if (current_value < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
            break;
        }

        if (current_value != last_value) {
            if (current_value == 1) {
                if (log_event("Flame Detected") != 0) {
                    fprintf(stderr, "Error logging flame detection event\n");
                }
            } else {
                if (log_event("Flame Cleared") != 0) {
                    fprintf(stderr, "Error logging flame clear event\n");
                }
            }
            last_value = current_value;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup_line:
    gpiod_line_release(line);
cleanup_chip:
    gpiod_chip_close(chip);

    return ret;
}

