#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define OPT3001_ADDR 0x44
#define REG_RESULT 0x00
#define REG_CONFIG 0x01

#define CONFIG_CONTINUOUS 0x0000
#define CONFIG_100MS_CONV 0x0001
#define CONFIG_AUTO_RANGE 0x0002
#define CONFIG_100MS_CONV_AUTO_RANGE 0x0003

#define I2C_BUS 1
#define LOG_FILE "light_data.txt"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_config(uint16_t config) {
    char buf[3];
    buf[0] = (char)(REG_CONFIG >> 8);
    buf[1] = (char)(REG_CONFIG & 0xFF);
    buf[2] = (char)(config >> 8);
    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_result(uint16_t *result) {
    char reg = (char)(REG_RESULT >> 8);
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error selecting result register: %s\n", strerror(errno));
        return -1;
    }
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading result register: %s\n", strerror(errno));
        return -1;
    }
    *result = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static float convert_to_lux(uint16_t result) {
    int exponent = (result >> 12) & 0x0F;
    int mantissa = result & 0x0FFF;
    return 0.01f * (float)(1 << exponent) * (float)mantissa;
}

static int log_data(float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
