#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        perror("time");
        return -1;
    }

    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return -1;
    }

    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *line_settings = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_line_request *line_req = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Configure line settings: input with pull-up bias */
    line_settings = gpiod_line_settings_new();
    if (line_settings == NULL) {
        perror("gpiod_line_settings_new");
        goto cleanup;
    }

    if (gpiod_line_settings_set_direction(line_settings, GPIOD_LINE_DIRECTION_INPUT) < 0) {
        perror("gpiod_line_settings_set_direction");
        goto cleanup;
    }

    if (gpiod_line_settings_set_bias(line_settings, GPIOD_LINE_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_settings_set_bias");
        goto cleanup;
    }

    /* Configure line config: request line 17 */
    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        perror("gpiod_line_config_new");
        goto cleanup;
    }

    unsigned int offsets[1] = { GPIO_LINE_OFFSET };
    if (gpiod_line_config_add_line_settings(line_cfg, offsets, 1, line_settings) < 0) {
        perror("gpiod_line_config_add_line_settings");
        goto cleanup;
    }

    /* Configure request config: consumer name "flame_detect" */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        perror("gpiod_request_config_new");
        goto cleanup;
    }

    gpiod_request_config_set_consumer(req_cfg, "flame_detect");

    /* Request the line */
    line_req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (line_req == NULL) {
        perror("gpiod_chip_request_lines");
        goto cleanup;
    }

    printf("Flame detection started on GPIO line %d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    /* Main polling loop */
    while (program_running) {
        int value = gpiod_line_request_get_value(line_req, GPIO_LINE_OFFSET);
        if (value < 0) {
            perror("gpiod_line_request_get_value");
            break;
        }

        char timestamp[32];
        if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
            printf("[%s] Flame Detected: %s\n", timestamp,
                   (value == 0) ? "YES" : "NO");
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to get timestamp\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line_req != NULL) {
        gpiod_line_request_release(line_req);
    }
    if (req_cfg != NULL) {
        gpiod_request_config_free(req_cfg);
    }
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }
    if (line_settings != NULL) {
        gpiod_line_settings_free(line_settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

