#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define CHIP_NAME "gpiochip0"
#define POLL_INTERVAL_MS 100

static const unsigned int touch_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_CHANNELS];
static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: ", touch_pins[i]);
            perror("");
            cleanup();
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_input(lines[i], "ttp226-touch") < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: ", touch_pins[i]);
            perror("");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("TTP226 touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO line %u: ", touch_pins[i]);
                perror("");
                cleanup();
                return EXIT_FAILURE;
            }
