    printf("Monitoring Hall-Effect sensors on GPIO %d and %d...\n",
           SENSOR_1_PIN, SENSOR_2_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (running) {
        int sensor1_value = gpioRead(SENSOR_1_PIN);
        int sensor2_value = gpioRead(SENSOR_2_PIN);

