#include <pigpio.h>

#define TILT_SENSOR_GPIO 4
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_tilt_state(int tilt_state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return;
    }

    printf("[%s] Tilt State: %s\n", timestamp,
           tilt_state == 0 ? "Tilted" : "Not Tilted");
    fflush(stdout);
}

int main(void)
{
    int last_tilt_state = -1;
    int ret;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure tilt sensor GPIO as input with pull-up resistor */
    ret = gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed (code %d)\n",
                TILT_SENSOR_GPIO, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed (code %d)\n",
                TILT_SENSOR_GPIO, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n",
           TILT_SENSOR_GPIO);
    fflush(stdout);

    /* Main polling loop */
    while (program_running) {
        int tilt_state = gpioRead(TILT_SENSOR_GPIO);

        if (tilt_state < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed (code %d)\n",
                    TILT_SENSOR_GPIO, tilt_state);
