#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_CHLIST 0x01
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_UVINDEX0 0x2C
#define SI1145_REG_UVINDEX1 0x2D

// Si1145 commands
#define SI1145_CMD_ALS_FORCE 0x06

// Expected PART ID for Si1145
#define SI1145_PART_ID 0x45

// Global variables for cleanup
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1145(int handle);
int read_uv_index(int handle, uint16_t *uv_index);
int read_als_visible(int handle, uint16_t *als_visible);
void log_data(uint16_t uv_index, uint16_t als_visible);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

// Function to initialize the Si1145 sensor
int init_si1145(int handle) {
    // Verify sensor presence by reading PART_ID
    int part_id = i2cReadByteData(handle, SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID: %s\n", strerror(errno));
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }

    // Write HW_KEY to enable the sensor
    if (i2cWriteByteData(handle, SI1145_REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error writing HW_KEY: %s\n", strerror(errno));
        return -1;
    }

    // Configure CHLIST: enable UV and ALS_VIS
    if (i2cWriteByteData(handle, SI1145_REG_CHLIST, 0x03) < 0) {
        fprintf(stderr, "Error writing CHLIST: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read the UV index from the Si1145 sensor
int read_uv_index(int handle, uint16_t *uv_index) {
    int low = i2cReadByteData(handle, SI1145_REG_UVINDEX0);
    if (low < 0) {
        fprintf(stderr, "Error reading UV index low byte: %s\n", strerror(errno));
        return -1;
    }

    int high = i2cReadByteData(handle, SI1145_REG_UVINDEX1);
    if (high < 0) {
        fprintf(stderr, "Error reading UV index high byte: %s\n", strerror(errno));
        return -1;
    }

    *uv_index = (uint16_t)((high << 8) | low);
    return 0;
}

// Function to read the ALS_VIS data from the Si1145 sensor
int read_als_visible(int handle, uint16_t *als_visible) {
    int low = i2cReadByteData(handle, SI1145_REG_ALS_VIS_DATA0);
    if (low < 0) {
        fprintf(stderr, "Error reading ALS_VIS low byte: %s\n", strerror(errno));
        return -1;
    }

    int high = i2cReadByteData(handle, SI1145_REG_ALS_VIS_DATA1);
    if (high < 0) {
        fprintf(stderr, "Error reading ALS_VIS high byte: %s\n", strerror(errno));
        return -1;
    }

    *als_visible = (uint16_t)((high << 8) | low);
    return 0;
}

// Function to log the data to a CSV file
void log_data(uint16_t uv_index, uint16_t als_visible) {
    FILE *fp = fopen("uv_als_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%u,%u\n", timestamp, uv_index, als_visible);
    fclose(fp);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection on bus 1
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1145 sensor
    if (init_si1145(i2c_handle) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handling for Ctrl+C and termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Trigger ALS_FORCE measurement
        if (i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) {
            fprintf(stderr, "Error triggering ALS_FORCE measurement: %s\n", strerror(errno));
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Wait for measurement to complete (max 100ms)
        gpioDelay(100000);

        // Read UV index and ALS_VIS data
        uint16_t uv_index, als_visible;
        if (read_uv_index(i2c_handle, &uv_index) < 0 || read_als_visible(i2c_handle, &als_visible) < 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Log the data
        log_data(uv_index, als_visible);

        // Print the data to the console
        printf("UV Index: %u, ALS Visible: %u\n", uv_index, als_visible);

        // Wait 1 second before next reading
        gpioDelay(1000000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

