#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000  /* 50 ms */

/* Structure to hold sensor data with timestamp */
typedef struct {
    time_t timestamp;
    int reading;
} SensorData;

/* Circular buffer of sensor data */
static SensorData sensor_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    printf("\nCaught signal, exiting gracefully...\n");
    printf("--- Sensor Data Buffer ---\n");
    for (int i = 0; i < buffer_count; i++) {
        struct tm *timeinfo = localtime(&sensor_buffer[i].timestamp);
        char timestamp_str[64];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Reading: %d\n", timestamp_str, sensor_buffer[i].reading);
    }
    printf("--- End of Buffer ---\n");
    gpioTerminate();
    exit(0);
}

/* Function to initialize the circular buffer */
static void initialize_buffer(void) {
    buffer_index = 0;
    buffer_count = 0;
}

/* Function to add data to the circular buffer */
static void add_to_buffer(int reading) {
    sensor_buffer[buffer_index].timestamp = time(NULL);
    sensor_buffer[buffer_index].reading = reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO pin as input with pull-up resistor */
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);

    /* Register signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    printf("Obstacle Avoidance Sensor Monitoring System\n");
    printf("Sensor: KY-033 on GPIO %d (BCM), polling every 50 ms\n", SENSOR_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main polling loop */
    while (1) {
        int reading = gpioRead(SENSOR_PIN);

        if (reading == 0) {
            printf("Obstacle detected! Reading: %d\n", reading);
            add_to_buffer(reading);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Unreachable, but kept for completeness */
    gpioTerminate();
    return 0;
}

