/*
 * fan_health.c — Omron D7S vibration sensor monitor for Raspberry Pi 5
 *
 * Uses the Linux I2C character-device API (no wiringPi).
 *
 * Wiring:
 *   D7S SDA  -> GPIO 2  (pin 3, I2C bus 1 SDA)
 *   D7S SCL  -> GPIO 3  (pin 5, I2C bus 1 SCL)
 *   D7S VDD  -> 3.3 V
 *   D7S GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o fan_health fan_health.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- D7S constants (7-bit I2C address 0x55) ---- */
#define D7S_I2C_ADDR        0x55
#define D7S_REG_MODE_CONTROL 0x1D
#define D7S_REG_OPERATING_STATUS 0x1B
#define D7S_REG_X_LSB       0x2A
#define D7S_REG_X_MSB       0x2B
#define D7S_REG_Y_LSB       0x2C
#define D7S_REG_Y_MSB       0x2D
#define D7S_REG_Z_LSB       0x2E
#define D7S_REG_Z_MSB       0x2F

#define D7S_MODE_CONTROL_ACTIVE  0x10
#define D7S_OPERATING_STATUS_BIT 0x01

#define I2C_BUS        "/dev/i2c-1"
#define CSV_FILENAME   "fan_health.csv"
#define SAMPLE_PERIOD_US 500000   /* 500 ms */
#define ACTIVE_TIMEOUT_S 1       /* sensor must be active within 1 s */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Write one byte to an 8-bit register. Returns 0 on success, -1 on error. */
static int d7s_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read one byte from an 8-bit register. Returns 0 on success, -1 on error. */
static int d7s_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    ssize_t n = read(fd, &val, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* Read a 16-bit little-endian signed value from two consecutive registers. */
static int d7s_read_reg16(int fd, uint8_t lsb_reg, int16_t *out)
{
    uint8_t lsb, msb;
    if (d7s_read_reg8(fd, lsb_reg, &lsb) < 0)
        return -1;
    if (d7s_read_reg8(fd, lsb_reg + 1, &msb) < 0)
        return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

/* Initialize the D7S sensor: switch to active mode, wait for it to be ready. */
static int d7s_init(int fd)
{
    /* Write MODE_CONTROL = 0x10 to switch to active mode. */
    if (d7s_write_reg8(fd, D7S_REG_MODE_CONTROL, D7S_MODE_CONTROL_ACTIVE) < 0)
        return -1;

    /* Poll OPERATING_STATUS bit 0 until it reads 1 (active). */
    for (int i = 0; i < ACTIVE_TIMEOUT_S * 10; i++) {
        uint8_t status;
        if (d7s_read_reg8(fd, D7S_REG_OPERATING_STATUS, &status) < 0)
            return -1;
        if (status & D7S_OPERATING_STATUS_BIT)
            return 0;
        usleep(100000); /* 100 ms */
    }

    fprintf(stderr, "D7S sensor did not become active within %d s.\n",
            ACTIVE_TIMEOUT_S);
    return -1;
}

/* Read acceleration data in g. Returns 0 on success, -1 on error. */
static int d7s_read_acceleration(int fd, float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    if (d7s_read_reg16(fd, D7S_REG_X_LSB, &raw_x) < 0)
        return -1;
    if (d7s_read_reg16(fd, D7S_REG_Y_LSB, &raw_y) < 0)
        return -1;
    if (d7s_read_reg16(fd, D7S_REG_Z_LSB, &raw_z) < 0)
        return -1;

    /* D7S outputs g-force: 0.0009765625 g/LSB */
    *x = (float)raw_x * 0.0009765625f;
    *y = (float)raw_y * 0.0009765625f;
    *z = (float)raw_z * 0.0009765625f;
    return 0;
}

/* Append a CSV row with an ISO-8601 timestamp. Returns 0 on success, -1 on error. */
static int log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf() to CSV failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the D7S slave address */
    if (ioctl(i2c_fd, I2C_SLAVE, D7S_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                D7S_I2C_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (d7s_init(i2c_fd) < 0) {
        fprintf(stderr, "D7S initialization failed.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open CSV file in append mode; write header if file is empty */
    FILE *fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "timestamp,x_g,y_g,z_g\n");
        fflush(fp);
    }

    printf("Monitoring D7S vibration sensor. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (d7s_read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            if (log_data(fp, x, y, z) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            } else {
                printf("X: %.6f g, Y: %.6f g, Z: %.6f g\n", x, y, z);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    fclose(fp);
    close(i2c_fd);
    printf("Done.\n");
    return EXIT_SUCCESS;
}

