#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define STALL_DURATION_SEC 2
#define LOG_FILE "stall_log.txt"
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

/*
 * Read a sensor GPIO value. Returns 0 or 1 on success, -1 on error.
 */
static int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio, pigpio_error(value));
        return -1;
    }
    return value;
}

/*
 * Log a stall event to the log file. Returns 0 on success, -1 on error.
 */
static int log_stall(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time to local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Stall detected!\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    printf("Stall detected! Logged to %s\n", LOG_FILE);
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO modes */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-down resistors on both sensors */
    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Conveyor belt stall monitor started. Press Ctrl+C to exit.\n");

    int stall_active = 0;
    time_t stall_start_time = 0;

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value < 0 || sensor2_value < 0) {
            /* Error already reported by read_sensor */
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        /* Check for stall condition: both sensors LOW */
        if (sensor1_value == 0 && sensor2_value == 0) {
            if (!stall_active) {
                stall_active = 1;
                stall_start_time = time(NULL);
                printf("Stall detected on GPIO %d and GPIO %d\n", SENSOR_1_GPIO, SENSOR_2_GPIO);
            } else {
                time_t current_time = time(NULL);
                if (current_time - stall_start_time >= STALL_DURATION_SEC) {
                    if (log_stall() != 0) {
                        fprintf(stderr, "Failed to log stall event\n");
                    }
                    stall_active = 0;
                }
            }
        } else {
            stall_active = 0;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean up */
    gpioTerminate();
    printf("Conveyor belt stall monitor stopped.\n");
    return EXIT_SUCCESS;
}

