 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   TMAG5170 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   TMAG5170 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   TMAG5170 VDD -> 3.3 V
 *   TMAG5170 GND -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o mag_logger mag_logger.c -lpigpio -lrt
 * Run:   sudo ./mag_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- TMAG5170-Q1 I2C Address ---- */
#define TMAG5170_ADDR 0x0E

/* ---- TMAG5170 Register Addresses ---- */
#define TMAG5170_REG_DEVICE_ID      0x00
#define TMAG5170_REG_X_MSB          0x01
#define TMAG5170_REG_X_LSB          0x02
#define TMAG5170_REG_Y_MSB          0x03
#define TMAG5170_REG_Y_LSB          0x04
#define TMAG5170_REG_Z_MSB          0x05
#define TMAG5170_REG_Z_LSB          0x06
#define TMAG5170_REG_CONFIG         0x07
#define TMAG5170_REG_STATUS         0x08

/* ---- Expected Device ID ---- */
#define TMAG5170_DEVICE_ID          0x8D

/* ---- Configuration: Continuous conversion, all axes enabled, 50 mT range ---- */
#define TMAG5170_CONFIG_VALUE       0x00

/* ---- Sensitivity scale factor for 50 mT range (LSB = 0.0000001 mT) ---- */
#define TMAG5170_SCALE_FACTOR       0.0000001f

/* ---- I2C bus on Raspberry Pi 4 ---- */
#define I2C_BUS 1

/* ---- Sampling interval in microseconds ---- */
#define SAMPLE_INTERVAL_US 100000

/* ---- Global state for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only, do not block in a signal handler  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a TMAG5170 register                          */
/* ------------------------------------------------------------------ */
static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a TMAG5170 register                          */
/* ------------------------------------------------------------------ */
static int read_register(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit two's-complement value from two consecutive registers  */
/* ------------------------------------------------------------------ */
static int read_16bit_le(int handle, uint8_t msb_reg, int16_t *out)
{
    int msb = read_register(handle, msb_reg);
    if (msb < 0)
        return -1;

    int lsb = read_register(handle, msb_reg + 1);
    if (lsb < 0)
        return -1;

    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the TMAG5170 sensor                                     */
/* ------------------------------------------------------------------ */
static int initialize_sensor(int handle)
{
    /* Verify device ID */
    int device_id = read_register(handle, TMAG5170_REG_DEVICE_ID);
    if (device_id < 0) {
        fprintf(stderr, "[ERROR] Cannot read device ID — sensor may be absent.\n");
        return -1;
    }
    if (device_id != TMAG5170_DEVICE_ID) {
        fprintf(stderr, "[ERROR] Unexpected device ID: 0x%02X (expected 0x%02X).\n",
                device_id, TMAG5170_DEVICE_ID);
        return -1;
    }
    printf("[INFO] TMAG5170 detected (Device ID: 0x%02X).\n", device_id);

    /* Configure: continuous conversion, all axes enabled, 50 mT range */
    if (write_register(handle, TMAG5170_REG_CONFIG, TMAG5170_CONFIG_VALUE) < 0)
        return -1;

    /* Allow first conversion to complete */
    gpioDelay(10000); /* 10 ms */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a timestamped reading to the CSV file                          */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x_mt, float y_mt, float z_mt)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x_mt, y_mt, z_mt);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources                                               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, TMAG5170_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, TMAG5170_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (initialize_sensor(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("magnetic_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open magnetic_log.csv for writing.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,x_mt,y_mt,z_mt\n");
        fflush(g_log_file);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("[INFO] Logging magnetic data to magnetic_log.csv. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t x_raw, y_raw, z_raw;

        if (read_16bit_le(g_i2c_handle, TMAG5170_REG_X_MSB, &x_raw) < 0 ||
            read_16bit_le(g_i2c_handle, TMAG5170_REG_Y_MSB, &y_raw) < 0 ||
            read_16bit_le(g_i2c_handle, TMAG5170_REG_Z_MSB, &z_raw) < 0) {
            fprintf(stderr, "[WARN] I2C read error — continuing.\n");
        } else {
            float x_mt = (float)x_raw * TMAG5170_SCALE_FACTOR;
            float y_mt = (float)y_raw * TMAG5170_SCALE_FACTOR;
            float z_mt = (float)z_raw * TMAG5170_SCALE_FACTOR;

            log_data(g_log_file, x_mt, y_mt, z_mt);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

