#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_GPIO 23
#define LOG_FILE "flood_log.txt"
#define POLL_INTERVAL_SEC 2
#define REINIT_DELAY_SEC 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input.\n", SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: Failed to set pull-down on GPIO %d.\n", SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor(void) {
    int value = gpioRead(SENSOR_GPIO);
    if (value < 0) {
        fprintf(stderr, "Error: Failed to read GPIO %d.\n", SENSOR_GPIO);
        return -1;
    }
    return value;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp.\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s %s\n", timestamp, message);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error registering SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_GPIO);

    int reinit_count = 0;

    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, re-initializing GPIO...\n");
            gpioTerminate();
            sleep(REINIT_DELAY_SEC);
            reinit_count++;
            if (init_gpio() != 0) {
                fprintf(stderr, "Failed to re-initialize GPIO after %d attempts.\n", reinit_count);
                break;
            }
            continue;
        }

        reinit_count = 0;

        if (sensor_value == 1) {
            printf("ALERT: Water detected!\n");
            log_event("ALERT: Water detected");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    gpioTerminate();
    printf("Water level monitoring stopped.\n");
    return EXIT_SUCCESS;
}

