#define PULSES_PER_REV       60         /* one pulse per revolution */

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t      g_pulse_count = 0;
static FILE                 *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback (runs in pigpio thread)                         */
/* ------------------------------------------------------------------ */
static void pulse_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    (void)tick;

    if (level == 1) {
        /* Rising edge: one pulse per revolution */
        g_pulse_count++;
    }
}

/* ------------------------------------------------------------------ */
/* Compute RPM from pulse count and sample interval                       */
/* ------------------------------------------------------------------ */
static double calculate_rpm(uint32_t pulses, uint32_t interval_us)
{
    if (interval_us == 0) {
        return 0.0;
    }
    return (double)pulses * PULSES_PER_REV * 60.0 / (double)interval_us;
}

