{
    /* Disable the alert callback before tearing down pigpio */
    gpioSetAlertFuncEx(SENSOR_GPIO, NULL, NULL);

    /* Stop the 1-second timer */
    gpioSetTimerFuncEx(0, 0, NULL);

    if (g_log_file != NULL) {
