    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Register alert callback for rising edges --- */
    if (gpioSetAlertFuncEx(SENSOR_GPIO, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d\n", SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Start 1-second timer --- */
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, NULL) != 0) {
        fprintf(stderr, "Failed to start 1-second timer\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90217 RPM logger started. Logging to '%s'. Press Ctrl+C to stop.\n",
           LOG_FILE);
    fflush(stdout);

    /* --- Main loop --- */
    while (g_running) {
        gpioDelay(SAMPLE_INTERVAL_US);  /* 1 second */

        uint32_t pulses = g_pulse_count;
        g_pulse_count = 0;

        double rpm = calculate_rpm(pulses, SAMPLE_INTERVAL_US);
        log_rpm(rpm);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

