#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27
#define LOG_FILE "rotation_log.txt"

#define Q_STATE_A 0
#define Q_STATE_B 1
#define Q_STATE_C 2
#define Q_STATE_D 3

static volatile int running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

static volatile int sensor_a_state = Q_STATE_A;
static volatile int sensor_b_state = Q_STATE_A;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_rotation(const char *direction) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", timestamp, direction);
        fflush(log_file);
    }
    pthread_mutex_unlock(&log_mutex);
}

static void sensor_a_alert_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    if (level == 1) {
        switch (sensor_a_state) {
            case Q_STATE_A: sensor_a_state = Q_STATE_B; break;
            case Q_STATE_B: sensor_a_state = Q_STATE_C; break;
            case Q_STATE_C: sensor_a_state = Q_STATE_D; break;
            case Q_STATE_D: sensor_a_state = Q_STATE_A; break;
            default: break;
        }
    } else if (level == 0) {
        switch (sensor_a_state) {
            case Q_STATE_A: sensor_a_state = Q_STATE_D; break;
            case Q_STATE_B: sensor_a_state = Q_STATE_A; break;
            case Q_STATE_C: sensor_a_state = Q_STATE_B; break;
            case Q_STATE_D: sensor_a_state = Q_STATE_C; break;
            default: break;
        }
    }
}

static void sensor_b_alert_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    if (level == 1) {
        switch (sensor_b_state) {
            case Q_STATE_A: sensor_b_state = Q_STATE_B; break;
            case Q_STATE_B: sensor_b_state = Q_STATE_C; break;
            case Q_STATE_C: sensor_b_state = Q_STATE_D; break;
            case Q_STATE_D: sensor_b_state = Q_STATE_A; break;
            default: break;
        }
    } else if (level == 0) {
        switch (sensor_b_state) {
            case Q_STATE_A: sensor_b_state = Q_STATE_D; break;
            case Q_STATE_B: sensor_b_state = Q_STATE_A; break;
            case Q_STATE_C: sensor_b_state = Q_STATE_B; break;
            case Q_STATE_D: sensor_b_state = Q_STATE_C; break;
            default: break;
        }
    }
}

int main(void) {
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", SENSOR_A_GPIO, pigpio_error(ret));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(SENSOR_B_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", SENSOR_B_GPIO, pigpio_error(ret));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);
    if (ret != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d: %s\n", SENSOR_A_GPIO, pigpio_error(ret));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);
    if (ret != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d: %s\n", SENSOR_B_GPIO, pigpio_error(ret));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetAlertFunc(SENSOR_A_GPIO, sensor_a_alert_callback);
    if (ret != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d: %s\n", SENSOR_A_GPIO, pigpio_error(ret));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetAlertFunc(SENSOR_B_GPIO, sensor_b_alert_callback);
    if (ret != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d: %s\n", SENSOR_B_GPIO, pigpio_error(ret));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    while (running) {
        if (sensor_a_state != sensor_b_state) {
            if (sensor_a_state == sensor_b_state + 1 || sensor_a_state == sensor_b_state - 3) {
                log_rotation("CW");
            } else {
                log_rotation("CCW");
            }
            sensor_a_state = sensor_b_state;
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");

    gpioSetAlertFunc(SENSOR_A_GPIO, NULL);
    gpioSetAlertFunc(SENSOR_B_GPIO, NULL);

    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_unlock(&log_mutex);

    gpioTerminate();

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

