    if (ret != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d: %s\n", SENSOR_B_GPIO, pigpio_error(ret));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    while (running) {
        if (sensor_a_state != sensor_b_state) {
            if (sensor_a_state == sensor_b_state + 1 || sensor_a_state == sensor_b_state - 3) {
                log_rotation("CW");
            } else {
                log_rotation("CCW");
            }
            sensor_a_state = sensor_b_state;
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");

    gpioSetAlertFunc(SENSOR_A_GPIO, NULL);
    gpioSetAlertFunc(SENSOR_B_GPIO, NULL);

    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_unlock(&log_mutex);

    gpioTerminate();

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

