#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define TOUCH_PIN 17
#define LED_PIN 18
#define DEBOUNCE_MS 50
#define POLL_TIMEOUT_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int debounce_ms(struct gpiod_line *line, int target_value) {
    struct timespec ts_start, ts_now;
    int val;

    clock_gettime(CLOCK_MONOTONIC, &ts_start);

    do {
        val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
            return -1;
        }
        if (val != target_value) {
            clock_gettime(CLOCK_MONOTONIC, &ts_now);
            long elapsed_ms = (ts_now.tv_sec - ts_start.tv_sec) * 1000L +
                              (ts_now.tv_nsec - ts_start.tv_nsec) / 1000000L;
            if (elapsed_ms >= DEBOUNCE_MS) {
                return 0;
            }
        }
        usleep(1000);
    } while (1);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", TOUCH_PIN, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(touch_line, "ttp223b-touch") < 0) {
        fprintf(stderr, "Failed to request touch line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "ttp223b-led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int val = gpiod_line_get_value(touch_line);
        if (val < 0) {
            fprintf(stderr, "Error reading touch sensor: %s\n", strerror(errno));
            break;
        }

        if (val == 1) {
            if (debounce_ms(touch_line, 1) == 0) {
                int led_val = gpiod_line_get_value(led_line);
                if (led_val < 0) {
                    fprintf(stderr, "Error reading LED state: %s\n", strerror(errno));
                    break;
                }
                if (gpiod_line_set_value(led_line, led_val ? 0 : 1) < 0) {
                    fprintf(stderr, "Error writing LED state: %s\n", strerror(errno));
                    break;
                }
                printf("Touch detected! LED toggled.\n");
            }
        }

        usleep(POLL_TIMEOUT_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return ret;
}

