#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN   27
#define LED_2_PIN   22

#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000  /* 50 ms */

/* ------------------------------------------------------------------ */
/* Circular buffer entry                                              */
/* ------------------------------------------------------------------ */
typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} LogEntry;

/* ------------------------------------------------------------------ */
/* Globals                                                             */
/* ------------------------------------------------------------------ */
static LogEntry log_buffer[BUFFER_SIZE];
static int buffer_head = 0;
static int buffer_count = 0;
static int overflow_count = 0;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a log entry to the circular buffer                           */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_pin, int state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    log_buffer[buffer_head].sensor_pin = sensor_pin;
    log_buffer[buffer_head].timestamp = now;
    log_buffer[buffer_head].state = state;

    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    } else {
        overflow_count++;
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Turn off LEDs */
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);

    /* Release pigpio resources */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pins as outputs, initially low */
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO %d low\n", LED_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO %d low\n", LED_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");
    printf("Sensor 1: GPIO %d | LED 1: GPIO %d | Sensor 2: GPIO %d | LED 2: GPIO %d\n",
           SENSOR_1_PIN, LED_1_PIN, SENSOR_2_PIN, LED_2_PIN);

    /* Main polling loop */
    while (program_running) {
        int sensor1_state = gpioRead(SENSOR_1_PIN);
        int sensor2_state = gpioRead(SENSOR_2_PIN);

        if (sensor1_state < 0) {
            fprintf(stderr, "gpioRead failed on GPIO %d\n", SENSOR_1_PIN);
        } else if (sensor1_state == 1) {
            if (gpioWrite(LED_1_PIN, 1) != 0) {
                fprintf(stderr, "gpioWrite failed on GPIO %d\n", LED_1_PIN);
            }
            log_event(SENSOR_1_PIN, 1);
        } else {
            if (gpioWrite(LED_1_PIN, 0) != 0) {
                fprintf(stderr, "gpioWrite failed on GPIO %d\n", LED_1_PIN);
            }
        }

        if (sensor2_state < 0) {
            fprintf(stderr, "gpioRead failed on GPIO %d\n", SENSOR_2_PIN);
        } else if (sensor2_state == 1) {
            if (gpioWrite(LED_2_PIN, 1) != 0) {
                fprintf(stderr, "gpioWrite failed on GPIO %d\n", LED_2_PIN);
            }
            log_event(SENSOR_2_PIN, 1);
        } else {
            if (gpioWrite(LED_2_PIN, 0) != 0) {
                fprintf(stderr, "gpioWrite failed on GPIO %d\n", LED_2_PIN);
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    printf("Log buffer contents:\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_head - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("  Sensor %d: %ld, State: %d\n",
