#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18

// Debounce time in microseconds (5 ms)
#define DEBOUNCE_TIME_US 5000

// Global variables for program state
volatile int running = 1;
volatile int last_sensor1_state = 0;
volatile int last_sensor2_state = 0;
volatile int pulse_count = 0;

// Function prototypes
int initialize_gpio(void);
int read_sensor(int pin);
void log_data(int sensor1_state, int sensor2_state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Initialize GPIO pins using pigpio library
int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);

    // Enable pull-up resistors on both sensors (DRV5032FJDBZR outputs are open-collector)
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP);

    return 0;
}

// Read sensor value with debounce
int read_sensor(int pin) {
    int current_state = gpioRead(pin);
    if (current_state == PI_BAD_GPIO) {
        fprintf(stderr, "Error reading GPIO pin %d\n", pin);
        return -1;
    }

    // Debounce: wait for stable state before reading
    gpioDelay(DEBOUNCE_TIME_US);
    int stable_state = gpioRead(pin);
    if (stable_state == PI_BAD_GPIO) {
        fprintf(stderr, "Error reading GPIO pin %d after debounce\n", pin);
        return -1;
    }

    // Check for state change
    if (stable_state != current_state) {
        return -1; // Debounce failed
    }

    return stable_state;
}

// Log data to CSV file
void log_data(int sensor1_state, int sensor2_state) {
    FILE *fp = fopen("shaft_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
    fclose(fp);
}

int main(void) {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor1_state = read_sensor(SENSOR1_PIN);
        int sensor2_state = read_sensor(SENSOR2_PIN);

        if (sensor1_state == -1 || sensor2_state == -1) {
            fprintf(stderr, "Error reading sensor data, skipping cycle\n");
            gpioDelay(100000); // Wait 100 ms before retrying
            continue;
        }

        // Detect rising edge (pulse from sensor)
        if (sensor1_state == 1 && last_sensor1_state == 0) {
            pulse_count++;
        }
        if (sensor2_state == 1 && last_sensor2_state == 0) {
            pulse_count++;
        }

        last_sensor1_state = sensor1_state;
        last_sensor2_state = sensor2_state;

        // Calculate RPM (approximate: 2 pulses per revolution)
        double rpm = (double)pulse_count * 60.0 / 2.0;

        // Log data
        log_data(sensor1_state, sensor2_state);

        printf("RPM: %.2f\n", rpm);

        gpioDelay(100000); // Wait 100 ms
    }

    // Cleanup
    gpioTerminate();
    printf("RPM monitoring stopped.\n");

    return EXIT_SUCCESS;
}

