#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SI1182_ADDR 0x28
#define SI1182_REG_PART_ID 0x00
#define SI1182_REG_HR_DATA 0x02
#define SI1182_REG_SPO2_DATA 0x04
#define SI1182_REG_CONFIG 0x30
#define SI1182_PART_ID 0x82
#define LOG_FILE "biometric_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int initialize_sensor(int handle) {
    uint8_t part_id;
    if (read_register(handle, SI1182_REG_PART_ID, &part_id) != 0) {
        return -1;
    }
    if (part_id != SI1182_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1182_PART_ID);
        return -1;
    }

    if (write_register(handle, SI1182_REG_CONFIG, 0x01) != 0) {
