#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN    27
#define LOG_FILE     "bridge_integrity.log"
#define POLL_DELAY_US 100000  /* 100 ms */
#define ALARM_TIMEOUT_US 2000000 /* 2 seconds */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event_type, int sensor_pin) {
    if (!log_file) return;

    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    fprintf(log_file, "%s - %s - Sensor %d\n", timestamp, event_type, sensor_pin);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure alarm is off before terminating pigpio */
    gpioWrite(ALARM_PIN, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs with pull-down */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure alarm pin as output, initially LOW */
    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALARM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO %d to LOW\n", ALARM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Bridge integrity monitor started", 0);

    int alarm_active = 0;
    uint32_t alarm_start_tick = 0;

    while (running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "gpioRead error on sensor pins (s1=%d, s2=%d)\n", s1, s2);
            log_event("Error reading sensor pins", 0);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Check for tilt threshold exceeded (HIGH for more than 2 seconds) */
        if (s1 == 1 && s2 == 1) {
            if (!alarm_active) {
                alarm_active = 1;
                alarm_start_tick = gpioTick();
                log_event("Tilt threshold exceeded", 0);
            } else {
                uint32_t elapsed = gpioTick() - alarm_start_tick;
                if (elapsed >= ALARM_TIMEOUT_US) {
                    gpioWrite(ALARM_PIN, 1);
                    log_event("Alarm activated", 0);
                    alarm_active = 1;
                }
            }
        } else {
            /* Tilt event cleared or no tilt */
            if (alarm_active) {
                gpioWrite(ALARM_PIN, 0);
                log_event("Alarm deactivated", 0);
                alarm_active = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_event("Bridge integrity monitor stopped", 0);
    cleanup();
    return EXIT_SUCCESS;
}

