#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x1D          /* D7S-A0011 default 7-bit address */
#define LED_GPIO             17
#define THRESHOLD            500.0f        /* Vibration magnitude threshold */
#define POLL_INTERVAL_US     100000        /* 100 ms between readings */
#define LED_ON_DURATION_US   1000000       /* 1 second LED on duration */
#define MAX_RETRIES          3
#define LOG_FILE             "seismic_events.log"

/* D7S-A0011 register addresses */
#define REG_CTRL1            0x1F
#define REG_ACCEL_X_L        0x28
#define REG_ACCEL_X_H        0x29
#define REG_ACCEL_Y_L        0x2A
#define REG_ACCEL_Y_H        0x2B
#define REG_ACCEL_Z_L        0x2C
#define REG_ACCEL_Z_H        0x2D

/* CTRL1: bit 0 = power-down (0 = active) */
#define CTRL1_POWER_DOWN     0x00

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  initialize_i2c(void);
static int  initialize_sensor(void);
static int  read_acceleration(float *x, float *y, float *z);
static float calculate_vibration_magnitude(float x, float y, float z);
static void control_led(int state);
static void log_event(float magnitude);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C helpers ------------------------------- */

/*
 * Write a single byte to an 8-bit register.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_write_reg8(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice(reg=0x%02X, val=0x%02X) failed\n",
                reg, value);
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from an 8-bit register.
 * Returns 0 on success and stores the value in *out; -1 on failure.
 */
static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *out)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice(reg select 0x%02X) failed\n", reg);
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error: i2cReadDevice(reg=0x%02X) failed\n", reg);
        return -1;
    }
    *out = (uint8_t)data_buf[0];
    return 0;
}

/*
 * Read a 6-byte block of acceleration data (little-endian, X, Y, Z).
 * Returns 0 on success and stores the values in *x, *y, *z; -1 on failure.
 */
static int read_acceleration(float *x, float *y, float *z)
{
    uint8_t buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read_block_data(g_i2c_handle, REG_ACCEL_X_L, (char *)buf, 6) == 6) {
            int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
            int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
            int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
            *x = (float)raw_x;
            *y = (float)raw_y;
            *z = (float)raw_z;
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            fprintf(stderr, "Warning: I2C read failed (attempt %d/%d), retrying...\n",
                    retries, MAX_RETRIES);
            gpioDelay(10000); /* 10 ms backoff */
        }
    }

    fprintf(stderr, "Error: Failed to read acceleration after %d retries\n",
            MAX_RETRIES);
    return -1;
}

/* ----------------------------- Sensor init ------------------------------- */

static int initialize_sensor(void)
{
    /* Verify sensor presence by reading CTRL1 (should be 0x00 after power-up) */
    uint8_t ctrl1 = 0;
    if (i2c_read_reg8(g_i2c_handle, REG_CTRL1, &ctrl1) != 0) {
        fprintf(stderr, "Error: Cannot read CTRL1 register (sensor absent or bus error)\n");
        return -1;
    }
    if (ctrl1 != CTRL1_POWER_DOWN) {
        fprintf(stderr, "Error: CTRL1 = 0x%02X (expected 0x%02X) - sensor not active\n",
                ctrl1, CTRL1_POWER_DOWN);
        return -1;
    }

    /* Clear power-down bit so the sensor is active */
    if (i2c_write_reg8(g_i2c_handle, REG_CTRL1, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to clear power-down bit in CTRL1\n");
        return -1;
    }

    gpioDelay(10000); /* 10 ms settle time after power-up */
    return 0;
}

/* ----------------------------- Vibration magnitude ------------------------ */

static float calculate_vibration_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ----------------------------- LED control -------------------------------- */

static void control_led(int state)
{
    gpioWrite(LED_GPIO, state);
}

/* ----------------------------- Logging ----------------------------------- */

static void log_event(float magnitude)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s - Vibration magnitude: %.2f V\n", timestamp, magnitude);
    fflush(g_log_file);
}

/* ----------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: Cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float x, y, z;

        if (read_acceleration(&x, &y, &z) == 0) {
            float magnitude = calculate_vibration_magnitude(x, y, z);

            if (magnitude > THRESHOLD) {
                printf("Threshold exceeded! Vibration magnitude: %.2f V\n", magnitude);
                control_led(1);
                log_event(magnitude);
                gpioDelay(LED_ON_DURATION_US);
                control_led(0);
            }
        } else {
            fprintf(stderr, "Error: Failed to read acceleration data, continuing...\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

