#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip4"
#define LED_PIN 18
#define SENSOR_PINS {4, 17, 27, 22}
#define NUM_SENSORS 4
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *sensor_lines[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_SENSORS; i++) {
        sensor_lines[i] = NULL;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line(LED)");
        goto cleanup;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, SENSOR_PINS[i]);
        if (!sensor_lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(sensor %d): %s\n",
                    i, strerror(errno));
            goto cleanup;
        }
    }

    if (gpiod_line_request_output(led_line, "obstacle_led", 0) < 0) {
        perror("gpiod_line_request_output(LED)");
        goto cleanup;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpiod_line_request_input(sensor_lines[i], "obstacle_sensor") < 0) {
            fprintf(stderr, "gpiod_line_request_input(sensor %d): %s\n",
                    i, strerror(errno));
            goto cleanup;
        }
    }

    printf("Obstacle detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int any_detected = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(sensor_lines[i]);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_get_value(sensor %d): %s\n",
                        i, strerror(errno));
                goto cleanup;
            }
            if (val == 0) {
                any_detected = 1;
                break;
            }
        }

        if (gpiod_line_set_value(led_line, any_detected ? 1 : 0) < 0) {
            perror("gpiod_line_set_value(LED)");
            goto cleanup;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

