/*
 * flame_monitor.c — KY-026 flame sensor monitor using libgpiod (v1.6+)
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor
 *
 * Wiring:
 *   KY-026 VCC  -> 3.3 V (pin 1)
 *   KY-026 GND  -> GND  (pin 6)
 *   KY-026 OUT  -> BCM GPIO 2, 3, 4, 17, 27 (pin 3, 5, 7, 11, 13)
 *
 * Sensor output is LOW when a flame is detected, HIGH otherwise.
 *
 * Build with libgpiod v1.6+ (libgpiod-dev >= 1.6.0).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define LOG_FILE         "/var/log/flame_events.log"
#define POLL_INTERVAL_S  1
#define DEBOUNCE_MS      50

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_id, int pin)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "fopen(%s): %s", LOG_FILE, strerror(errno));
        return;
    }

    flock(fileno(fp), LOCK_EX);

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        syslog(LOG_ERR, "time(): %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r(): %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime(): buffer too small");
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n",
                ts, sensor_id, pin) < 0) {
        syslog(LOG_ERR, "fprintf: %s", strerror(errno));
    }

    if (fflush(fp) != 0) {
        syslog(LOG_ERR, "fflush: %s", strerror(errno));
    }

    flock(fileno(fp), LOCK_UN);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting flame sensor monitoring (libgpiod v1.6+)");

    if (install_signal_handlers() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_SENSORS];
    int line_count = 0;

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        line_count++;
    }

    syslog(LOG_INFO, "Monitoring %d KY-026 sensors on BCM GPIO %u-%u",
           line_count, sensor_pins[0], sensor_pins[NUM_SENSORS - 1]);

    int prev_state[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        prev_state[i] = gpiod_line_get_value(lines[i]);
        if (prev_state[i] < 0) {
            syslog(LOG_ERR, "gpiod_line_get_value(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                syslog(LOG_ERR, "gpiod_line_get_value(%u): %s",
                       sensor_pins[i], strerror(errno));
                continue;
            }

            /* Rising edge: no-flame -> flame (LOW) */
            if (val == 0 && prev_state[i] == 1) {
                usleep(DEBOUNCE_MS * 1000);

                int reval = gpiod_line_get_value(lines[i]);
                if (reval < 0) {
                    syslog(LOG_ERR, "gpiod_line_get_value(%u): %s",
                           sensor_pins[i], strerror(errno));
                    continue;
                }

                if (reval == 0) {
                    log_event(i, sensor_pins[i]);
                    syslog(LOG_INFO, "Flame detected on sensor %d (GPIO %d)",
                           i, sensor_pins[i]);
                }
            }

            prev_state[i] = val;
        }

        sleep(POLL_INTERVAL_S);
    }

cleanup:
    syslog(LOG_INFO, "Shutting down flame sensor monitoring");

    for (int i = 0; i < line_count; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

