#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int touch_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("[%s] ", timestamp);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk lines;
    int prev_states[NUM_CHANNELS];
    int ret;

    /* Initialize prev_states to -1 to indicate initial state */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        prev_states[i] = -1;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 3 Model B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Request all eight touch sensor lines as inputs */
    ret = gpiod_chip_request_lines_bulk(chip, &lines, touch_pins, NUM_CHANNELS);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO lines %u-%u as inputs: %s\n",
                touch_pins[0], touch_pins[NUM_CHANNELS - 1], strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("TTP226 touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        ret = gpiod_line_get_value_bulk(&lines, prev_states);
        if (ret < 0) {
            fprintf(stderr, "Failed to read GPIO values: %s\n", strerror(errno));
            break;
        }

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int current_state = prev_states[i];
            int new_state = ret[i];

            if (new_state != current_state) {
                print_timestamp();
                printf("Sensor %d (BCM GPIO %u): ", i, touch_pins[i]);

                if (new_state == 1) {
                    printf("Touch detected\n");
                } else {
                    printf("Touch released\n");
                }

                fflush(stdout);
                prev_states[i] = new_state;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* Clean up resources */
    gpiod_chip_release_lines_bulk(&lines);
    gpiod_chip_close(chip);

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

