#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* VEML7700 I2C address (ADDR pin tied to GND) */
#define VEML7700_ADDR 0x10

/* VEML7700 register addresses */
#define VEML7700_ALS_CONF 0x00
#define VEML7700_ALS_DATA 0x04

/* LED GPIO pin */
#define LED_PIN 18

/* PWM parameters */
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100

/* Lux thresholds for adaptive brightness */
#define LUX_THRESHOLD_LOW 100.0f
#define LUX_THRESHOLD_MED 500.0f
#define LUX_THRESHOLD_HIGH 1000.0f

/* Global state for signal handler */
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

/* Function prototypes */
static int veml7700_init(int handle);
static float veml7700_read_lux(int handle);
static int set_led_brightness(int gpio, int brightness);
static void log_data(FILE *fp, float lux, int brightness, int error_code);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Initialize VEML7700 sensor: ALS gain 1/8 (0x00), ALS integration time 100 ms (0x00) */
static int veml7700_init(int handle) {
    /* Write 16-bit little-endian config value to ALS_CONF register */
    uint8_t config[2] = {0x00, 0x00};
    if (i2cWriteDevice(handle, (char *)config, 2) != 0) {
        fprintf(stderr, "Error: Failed to write VEML7700 config register\n");
        return -1;
    }
    return 0;
}

/* Read ambient light from VEML7700 ALS register (16-bit little-endian) */
static float veml7700_read_lux(int handle) {
    uint8_t data[2];
    int result = i2cReadDevice(handle, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error: Failed to read VEML7700 ALS data (returned %d)\n", result);
        return -1.0f;
    }
    uint16_t raw = (uint16_t)((data[1] << 8) | data[0]);
    return (float)raw * 0.0576f;
}

/* Set LED brightness using hardware PWM */
static int set_led_brightness(int gpio, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    if (gpioPWM(gpio, brightness) != 0) {
        fprintf(stderr, "Error: Failed to set PWM on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

/* Log data to file with ISO timestamp */
static void log_data(FILE *fp, float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Lux: %.2f, Brightness: %d, Error: %d\n", timestamp, lux, brightness, error_code);
    fflush(fp);
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at VEML7700 address */
    i2c_handle = i2cOpen(1, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X (error %d)\n", VEML7700_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize VEML7700 sensor */
    if (veml7700_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VEML7700 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);

    /* Open log file in append mode */
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open grow_log.txt for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Grow light system started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        float lux = veml7700_read_lux(i2c_handle);
        int error_code = 0;

        if (lux < 0.0f) {
            error_code = 1;
            lux = 0.0f;
        }

        int brightness;
        if (lux < LUX_THRESHOLD_LOW) {
            brightness = PWM_RANGE;
        } else if (lux < LUX_THRESHOLD_MED) {
            brightness = (int)((lux / LUX_THRESHOLD_MED) * PWM_RANGE);
        } else if (lux < LUX_THRESHOLD_HIGH) {
            brightness = (int)((lux / LUX_THRESHOLD_HIGH) * PWM_RANGE);
        } else {
            brightness = 0;
        }

        if (set_led_brightness(LED_PIN, brightness) != 0) {
            error_code = 2;
        }

        log_data(log_file, lux, brightness, error_code);

        sleep(1);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

