int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at VEML7700 address */
    i2c_handle = i2cOpen(1, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X (error %d)\n", VEML7700_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize VEML7700 sensor */
    if (veml7700_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VEML7700 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);

    /* Open log file in append mode */
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open grow_log.txt for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Grow light system started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        float lux = veml7700_read_lux(i2c_handle);
        int error_code = 0;

        if (lux < 0.0f) {
            error_code = 1;
            lux = 0.0f;
        }

        int brightness;
        if (lux < LUX_THRESHOLD_LOW) {
            brightness = PWM_RANGE;
        } else if (lux < LUX_THRESHOLD_MED) {
            brightness = (int)((lux / LUX_THRESHOLD_MED) * PWM_RANGE);
        } else if (lux < LUX_THRESHOLD_HIGH) {
            brightness = (int)((lux / LUX_THRESHOLD_HIGH) * PWM_RANGE);
        } else {
            brightness = 0;
        }

        if (set_led_brightness(LED_PIN, brightness) != 0) {
            error_code = 2;
        }

        log_data(log_file, lux, brightness, error_code);

        sleep(1);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

