#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define NUM_CHANNELS 8
#define LED_GPIO 17
#define POLL_DELAY_US 50000  /* 50 ms */

/* TTP226 digital output pins (BCM numbering) */
static const int touch_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t program_running = 1;

/* Debounce state for each channel (1 = touched, 0 = released) */
static int debounce_state[NUM_CHANNELS];

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only, do not block in a signal handler */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure touch pins as inputs with pull-down */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return -1;
    }

    /* Configure touch pins as inputs with pull-down resistors */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(touch_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as input.\n",
                    touch_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(touch_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: failed to set pull-down on GPIO %d.\n",
                    touch_pins[i]);
            gpioTerminate();
            return -1;
        }
        debounce_state[i] = 0;  /* start with no touch */
    }

    /* Configure LED pin as output */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }
    gpioWrite(LED_GPIO, 0);  /* ensure LED is off initially */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all touch sensor channels; returns 1 if any channel is touched, */
/* 0 if all channels are released, or -1 on read error.              */
/* ------------------------------------------------------------------ */
static int read_touch_sensors(void)
{
    int any_touched = 0;

    for (int i = 0; i < NUM_CHANNELS; i++) {
        int level = gpioRead(touch_pins[i]);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO %d (code %d).\n",
                    touch_pins[i], level);
            return -1;
        }

        /* Detect rising edge: touched -> released */
        if (level == 1 && debounce_state[i] == 0) {
            any_touched = 1;
            debounce_state[i] = 1;
        }
        /* Detect falling edge: released -> touched */
        else if (level == 0 && debounce_state[i] == 1) {
            debounce_state[i] = 0;
        }
    }

    return any_touched;
}

