#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define OPT3001_ADDR        0x44
#define CONFIG_REG          0x01
#define RESULT_REG          0x00
#define CONFIG_WORD         0xC810  /* continuous, auto-range, 100 ms */
#define I2C_BUS             1
#define LOG_FILE            "light_data.txt"
#define SAMPLE_INTERVAL_US  1000000  /* 1 second */
#define CONV_WAIT_US       100000   /* 100 ms conversion wait */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value (big-endian on OPT3001) to a 16-bit register address. */
static int opt3001_write_reg(int handle, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);   /* OPT3001 expects MSB first */
    buf[2] = (uint8_t)(value & 0xFF);
    if (i2cWriteDevice(handle, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit value (big-endian on OPT3001) from a 16-bit register address. */
static int opt3001_read_reg(int handle, uint8_t reg, uint16_t *value)
{
    int raw = i2cReadWordData(handle, reg);
    if (raw < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* pigpio returns data as (low byte << 8) | high byte; OPT3001 expects MSB first */
    *value = (uint16_t)((raw & 0xFF) << 8) | ((raw >> 8) & 0xFF);
    return 0;
}

/* Read ambient light lux from the OPT3001. Returns 0 on success, -1 on error. */
static int read_light_lux(int handle, float *lux_out)
{
    uint16_t config = CONFIG_WORD;
    uint16_t result = 0;

    if (opt3001_write_reg(handle, CONFIG_REG, config) != 0)
        return -1;

    gpioDelay(CONV_WAIT_US);

    if (opt3001_read_reg(handle, RESULT_REG, &result) != 0)
        return -1;

    /* Extract exponent and mantissa from 16-bit result */
    uint16_t exponent = (result >> 12) & 0x0F;
    uint16_t mantissa = result & 0x0FFF;

    *lux_out = (float)mantissa * 0.01f * (float)(1 << exponent);
    return 0;
}

static void log_data(float lux)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at OPT3001 address 0x44 */
    g_i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, OPT3001_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Greenhouse Light Monitoring System\n");
    printf("OPT3001 at I2C bus %d, address 0x%02X, logging to '%s'\n",
           I2C_BUS, OPT3001_ADDR, LOG_FILE);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        float lux = 0.0f;

        if (read_light_lux(g_i2c_handle, &lux) == 0) {
            printf("Lux: %.2f\n", lux);
            log_data(lux);
        } else {
            fprintf(stderr, "Failed to read light data. Skipping this sample.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");

    return EXIT_SUCCESS;
}

