    /* Open I2C bus 1 at OPT3001 address 0x44 */
    g_i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, OPT3001_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Greenhouse Light Monitoring System\n");
    printf("OPT3001 at I2C bus %d, address 0x%02X, logging to '%s'\n",
           I2C_BUS, OPT3001_ADDR, LOG_FILE);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        float lux = 0.0f;

        if (read_light_lux(g_i2c_handle, &lux) == 0) {
            printf("Lux: %.2f\n", lux);
            log_data(lux);
        } else {
            fprintf(stderr, "Failed to read light data. Skipping this sample.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");

    return EXIT_SUCCESS;
}

