#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 4
#define ALERT_GPIO 17
#define POLL_INTERVAL_US 500000  /* 500 ms */
#define ALERT_DURATION_US 1000000 /* 1 second */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown (SIGINT / SIGTERM) */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Initialize pigpio and configure GPIO pins */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input.\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", ALERT_GPIO);
        gpioTerminate();
        return -1;
    }

    /* Ensure alert starts LOW */
    if (gpioWrite(ALERT_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO %d to LOW.\n", ALERT_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Read flame sensor value (0 = flame detected, 1 = no flame) */
static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_GPIO);
    if (value < 0) {
        fprintf(stderr, "Error: Failed to read GPIO %d.\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    return value;
}

/* Log a flame event with timestamp to file */
static void log_flame_event(int flame_detected) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed.\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed.\n");
        return;
    }

    if (log_file != NULL) {
        if (flame_detected) {
            fprintf(log_file, "%s - Flame detected!\n", timestamp);
        } else {
            fprintf(log_file, "%s - No flame detected.\n", timestamp);
        }
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

/* Trigger alert by setting GPIO HIGH for 1 second */
static void trigger_alert(void) {
    if (gpioWrite(ALERT_GPIO, 1) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d HIGH.\n", ALERT_GPIO);
        return;
    }
    gpioDelay(ALERT_DURATION_US);
    if (gpioWrite(ALERT_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d LOW.\n", ALERT_GPIO);
    }
}

