    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("fire_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file 'fire_events.log': %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected < 0) {
            /* Sensor read error; log and continue */
            log_flame_event(-1);
        } else {
            log_flame_event(flame_detected);

            if (flame_detected) {
                trigger_alert();
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

