#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SLF3S_ADDR     0x08
#define MEASURE_CMD_MSB 0x36
#define MEASURE_CMD_LSB 0x08
#define SAMPLE_PERIOD_US 1000000
#define LOG_FILE       "cooling_log.csv"
#define FLOW_MIN       0.0f
#define FLOW_MAX       100.0f
#define RAW_SCALE      90.0f
#define CRC8_POLY      0x31
#define CRC8_INIT      0xFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int init_i2c(void) {
    g_i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, SLF3S_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int start_measurement(void) {
    uint8_t cmd[2] = { MEASURE_CMD_MSB, MEASURE_CMD_LSB };
    int rc = i2cWriteDevice(g_i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error sending measurement command: %d\n", rc);
        return -1;
    }
    gpioDelay(2000); /* 2 ms conversion time */
    return 0;
}

static int read_flow_data(int16_t *raw_flow, uint8_t *status) {
    uint8_t buf[3];
    int rc = i2cReadDevice(g_i2c_handle, (char *)buf, 3);
    if (rc != 3) {
        fprintf(stderr, "Error reading flow data: expected 3 bytes, got %d\n", rc);
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }
    *raw_flow = (int16_t)((buf[0] << 8) | buf[1]);
    *status = buf[2];
    return 0;
}

static float convert_to_ml_min(int16_t raw_flow) {
    return (float)raw_flow / RAW_SCALE;
}

static int log_data(float flow_rate, uint8_t status) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    const char *status_str = "OK";
    if (status & 0x01) status_str = "ERROR";
    if (status & 0x02) status_str = "INVALID";

    if (fprintf(g_log_file, "%s,%.2f,%s\n", timestamp, flow_rate, status_str) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(g_log_file);
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler\n");
        gpioTerminate();
