#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_LEFT   17
#define GPIO_MIDDLE 27
#define GPIO_RIGHT  22
#define LOG_FILE    "path_log.csv"
#define POLL_MS     50

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_data(FILE *fp, int left, int middle, int right)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, left, middle, right) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    lines[0] = gpiod_chip_get_line(chip, GPIO_LEFT);
    lines[1] = gpiod_chip_get_line(chip, GPIO_MIDDLE);
    lines[2] = gpiod_chip_get_line(chip, GPIO_RIGHT);
    if (lines[0] == NULL || lines[1] == NULL || lines[2] == NULL) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < 3; i++) {
        if (gpiod_line_request_input(lines[i], "obstacle_avoidance") < 0) {
            fprintf(stderr, "Failed to request GPIO %d as input: %s\n",
                    i == 0 ? GPIO_LEFT : (i == 1 ? GPIO_MIDDLE : GPIO_RIGHT),
                    strerror(errno));
            goto cleanup;
        }
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Obstacle avoidance logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int left   = gpiod_line_get_value(lines[0]);
        int middle = gpiod_line_get_value(lines[1]);
        int right  = gpiod_line_get_value(lines[2]);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Failed to read GPIO values: %s\n", strerror(errno));
            break;
        }

        if (log_data(fp, left, middle, right) != 0) {
            break;
        }

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        }
    }
    for (int i = 0; i < 3; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    printf("Obstacle avoidance logging stopped.\n");
    return ret;
}

