/*
 * TMAG5110A1 Hall-effect latch magnet sensor monitor for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   Sensor OUT  -> GPIO4  (BCM)
 *   Sensor OUT  -> GPIO17 (BCM)
 *   Sensor OUT  -> GPIO27 (BCM)
 *   Sensor VCC  -> 3.3 V
 *   Sensor GND  -> GND
 *   Sensor INT  -> internal pull-up enabled (open-drain OUT drives GPIO input)
 *
 * The TMAG5110A1 latch is active-low: a low reading means magnet present,
 * a high reading means magnet removed.  The internal pull-up keeps the
 * GPIO input high when no magnet is present, so a logic low means
 * magnet-present.
 *
 * Build:  gcc -O2 -Wall -Wextra -o magnet_monitor magnet_monitor.c -lpigpio -lrt
 * Run:    sudo ./magnet_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27
#define POLL_DELAY_US 100000   /* 100 ms */
#define LOG_FILE_NAME "magnet_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_pin, int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (g_log_file != NULL) {
        fprintf(g_log_file, "%s - Sensor %d: %s\n",
                timestamp, sensor_pin,
                state ? "Magnet Present" : "Magnet Removed");
        fflush(g_log_file);
    } else {
        fprintf(stderr, "Log file not open\n");
    }
}

/* ------------------------------------------------------------------ */
/* GPIO initialization                                                 */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    int pins[] = { SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN };
    const int num_pins = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "gpioSetMode failed for pin %d\n", pins[i]);
            return -1;
        }

        /* Enable internal pull-up so the input is HIGH when no magnet
         * is present (latch is active-low). */
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", pins[i]);
            return -1;
        }
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
/* Returns 0 on success, -1 on read error.  On success, *out_state is
 * set to 0 (magnet present) or 1 (magnet removed). */
static int read_sensor(int pin, int *out_state)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "gpioRead failed for pin %d\n", pin);
        return -1;
    }

    *out_state = (level == 0) ? 0 : 1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int sensor_pins[] = { SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN };
    const int num_sensors = sizeof(sensor_pins) / sizeof(sensor_pins[0]);
    int initial_states[num_sensors];
    int current_states[num_sensors];
    int first_read = 1;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE_NAME ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Read initial states without logging transitions. */
    for (int i = 0; i < num_sensors; i++) {
        if (read_sensor(sensor_pins[i], &initial_states[i]) != 0) {
            fprintf(stderr, "Initial read failed for sensor %d\n", i + 1);
            cleanup();
            return EXIT_FAILURE;
        }
        current_states[i] = initial_states[i];
    }

    printf("Monitoring TMAG5110A1 sensors on GPIO%d, GPIO%d, GPIO%d...\n",
           SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        for (int i = 0; i < num_sensors; i++) {
            if (read_sensor(sensor_pins[i], &current_states[i]) != 0) {
                fprintf(stderr, "Read error on sensor %d\n", i + 1);
                continue;
            }

            if (first_read || current_states[i] != initial_states[i]) {
                log_event(sensor_pins[i], current_states[i]);
                first_read = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

