#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1182_ADDR 0x4A
#define I2C_BUS 1

#define SI1182_REG_PART_ID 0x00
#define SI1182_REG_HW_REV 0x01
#define SI1182_REG_LED_CURRENT 0x3F
#define SI1182_REG_AVG_COUNT 0x04
#define SI1182_REG_ENABLE 0x01
#define SI1182_REG_HR_DATA 0x2A

#define SI1182_PART_ID_EXPECTED 0x02
#define SI1182_HW_REV_EXPECTED 0x01

#define HEART_RATE_MIN 30.0
#define HEART_RATE_MAX 220.0
#define MOVING_AVG_SIZE 5
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int initialize_sensor(int handle) {
    uint8_t part_id, hw_rev;

    if (read_register(handle, SI1182_REG_PART_ID, &part_id) != 0) {
        return -1;
    }
    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }

    if (read_register(handle, SI1182_REG_HW_REV, &hw_rev) != 0) {
        return -1;
    }
    if (hw_rev != SI1182_HW_REV_EXPECTED) {
        fprintf(stderr, "Unexpected HW_REV: 0x%02X (expected 0x%02X)\n", hw_rev, SI1182_HW_REV_EXPECTED);
        return -1;
    }

    if (write_register(handle, SI1182_REG_LED_CURRENT, 0x0F) != 0) {
        return -1;
    }
    if (write_register(handle, SI1182_REG_AVG_COUNT, 0x04) != 0) {
        return -1;
    }
    if (write_register(handle, SI1182_REG_ENABLE, 0x01) != 0) {
        return -1;
    }

    return 0;
}

static int read_heart_rate(int handle, float *heart_rate) {
    int raw = i2cReadWordData(handle, SI1182_REG_HR_DATA);
    if (raw < 0) {
        fprintf(stderr, "Error reading heart-rate data: %d\n", raw);
        return -1;
    }

    *heart_rate = (float)raw * 0.5f;
    return 0;
}

static float calculate_moving_average(float *buffer, int size, int index) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += buffer[i];
    }
    return sum / size;
}

static void log_heart_rate(FILE *fp, float heart_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f\n", timestamp, heart_rate);
    fflush(fp);
}

static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float heart_rate_buffer[MOVING_AVG_SIZE];
    int buffer_index = 0;
    int consecutive_errors = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening heart_rate.csv for writing\n");
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,BPM\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Heart-rate monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float heart_rate;
        if (read_heart_rate(i2c_handle, &heart_rate) == 0) {
            consecutive_errors = 0;

            heart_rate_buffer[buffer_index] = heart_rate;
            buffer_index = (buffer_index + 1) % MOVING_AVG_SIZE;

            float filtered_heart_rate = calculate_moving_average(heart_rate_buffer, MOVING_AVG_SIZE, buffer_index);

            if (filtered_heart_rate >= HEART_RATE_MIN && filtered_heart_rate <= HEART_RATE_MAX) {
                log_heart_rate(log_file, filtered_heart_rate);
                printf("BPM: %.2f\n", filtered_heart_rate);
            } else {
