/*
 * touch_counter.c — TTP226 8-channel capacitive touch sensor → 8-bit binary counter
 * Board:  Raspberry Pi Zero W
 * API:    libgpiod v2+ (bulk/config)
 *
 * Wiring:
 *   TTP226 OUT1..OUT8 -> GPIO 5, 6, 7, 8, 9, 10, 11, 12 (BCM)
 *   TTP226 VCC/GND   -> 3.3 V, GND
 *   Counter display: 8-bit binary on GPIO17 (bit 0, LSB) through GPIO24 (bit 7, MSB)
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 10
#define STABILIZATION_MS 200
#define LOG_FILE "touch_log.txt"

/* BCM GPIO numbers for sensor input lines */
static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};

/* BCM GPIO numbers for counter output lines (bit 0 = LSB) */
static const unsigned int counter_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_touch_event(int channel, int counter)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Warning: localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_info) == 0) {
        fprintf(stderr, "Warning: strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, Channel: %d, Counter: %d\n", ts, channel, counter);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: gpiod_chip_open_by_name(\"gpiochip0\"): %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure sensor lines as inputs --- */
    struct gpiod_line_settings *sensor_settings = gpiod_line_settings_new();
    if (!sensor_settings) {
        fprintf(stderr, "Error: gpiod_line_settings_new(): %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_settings_set_direction(sensor_settings, GPIOD_LINE_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "Error: gpiod_line_settings_set_direction(INPUT): %s\n",
                strerror(errno));
        gpiod_line_settings_free(sensor_settings);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line_config *sensor_line_cfg = gpiod_line_config_new();
    if (!sensor_line_cfg) {
        fprintf(stderr, "Error: gpiod_line_config_new(): %s\n", strerror(errno));
        gpiod_line_settings_free(sensor_settings);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_config_add_line_settings(sensor_line_cfg, sensor_pins, NUM_CHANNELS,
                                            sensor_settings) < 0) {
        fprintf(stderr, "Error: gpiod_line_config_add_line_settings(sensor): %s\n",
                strerror(errno));
        gpiod_line_config_free(sensor_line_cfg);
        gpiod_line_settings_free(sensor_settings);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* --- Configure counter lines as outputs, initial value 0 --- */
    struct gpiod_line_settings *counter_settings = gpiod_line_settings_new();
    if (!counter_settings) {
        fprintf(stderr, "Error: gpiod_line_settings_new(): %s\n", strerror(errno));
        gpiod_line_config_free(sensor_line_cfg);
        gpiod_line_settings_free(sensor_settings);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_settings_set_direction(counter_settings, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpiod_line_settings_set_direction(OUTPUT): %s\n",
                strerror(errno));
        gpiod_line_settings_free(counter_settings);
        gpiod_line_config_free(sensor_line_cfg);
        gpiod_line_settings_free(sensor_settings);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_settings_set_output_value(counter_settings, 0) < 0) {
