        gpiod_line_config_free(counter_line_cfg);
        gpiod_line_settings_free(counter_settings);
        gpiod_line_config_free(sensor_line_cfg);
        gpiod_line_settings_free(sensor_settings);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line_request *counter_req =
        gpiod_chip_request_lines(chip, NULL, counter_line_cfg);
    if (!counter_req) {
        fprintf(stderr, "Error: gpiod_chip_request_lines(counter): %s\n",
                strerror(errno));
        gpiod_line_request_release(sensor_req);
        gpiod_line_config_free(counter_line_cfg);
        gpiod_line_settings_free(counter_settings);
        gpiod_line_config_free(sensor_line_cfg);
        gpiod_line_settings_free(sensor_settings);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

