#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_SENSORS 4
#define POLL_INTERVAL_MS 100
#define CSV_FILENAME "tracking_log.csv"

static const unsigned int sensor_pins[NUM_SENSORS] = {17, 18, 27, 22};
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_data(FILE *fp, int sensor1, int sensor2, int sensor3, int sensor4) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3, sensor4) < 0) {
        fprintf(stderr, "Error: fprintf() to CSV failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        fprintf(stderr, "Error: gpiod_chip_open_by_name(\"gpiochip4\") failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: gpiod_chip_get_line(%u) failed: %s\n", sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "ky033-tracking") < 0) {
            fprintf(stderr, "Error: gpiod_line_request_input(%u) failed: %s\n", sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: fopen(%s) failed: %s\n", CSV_FILENAME, strerror(errno));
        goto cleanup;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n") < 0) {
            fprintf(stderr, "Error: fprintf() to CSV header failed: %s\n", strerror(errno));
            goto cleanup;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "Warning: fflush() after header failed: %s\n", strerror(errno));
        }
    }

    printf("Tracking module data logging started. Press Ctrl+C to stop.\n");

    while (program_running) {
        int sensor1 = gpiod_line_get_value(lines[0]);
        int sensor2 = gpiod_line_get_value(lines[1]);
        int sensor3 = gpiod_line_get_value(lines[2]);
        int sensor4 = gpiod_line_get_value(lines[3]);

        if (sensor1 < 0 || sensor2 < 0 || sensor3 < 0 || sensor4 < 0) {
            fprintf(stderr, "Error: gpiod_line_get_value() failed: %s\n", strerror(errno));
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (log_data(fp, sensor1, sensor2, sensor3, sensor4) != 0) {
            fprintf(stderr, "Error: Failed to log data.\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (fp != NULL) {
        fclose(fp);
    }

    return ret;
}

