        line18 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int log_tilt_event(int sensor_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    int ret;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

