        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input_flags(line18, "tilt_sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", GPIO_LINE_18, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    int prev_val17 = 1;
    int prev_val18 = 1;
    struct timespec last_event_time17 = {0, 0};
    struct timespec last_event_time18 = {0, 0};

    while (program_running) {
        int val17 = gpiod_line_get_value(line17);
        if (val17 < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_LINE_17, strerror(errno));
            break;
        }

        int val18 = gpiod_line_get_value(line18);
        if (val18 < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_LINE_18, strerror(errno));
            break;
        }

        if (val17 == 0 && prev_val17 == 1) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);

            if (now.tv_sec - last_event_time17.tv_sec >= DEBOUNCE_MS / 1000.0 ||
                (now.tv_sec - last_event_time17.tv_sec < DEBOUNCE_MS / 1000.0 &&
                 now.tv_nsec - last_event_time17.tv_nsec >= (DEBOUNCE_MS % 1000) * 1000000L)) {
                if (log_tilt_event(17) == 0) {
                    printf("Sensor 17 tilted\n");
                }
                last_event_time17 = now;
            }
        }

        if (val18 == 0 && prev_val18 == 1) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);

            if (now.tv_sec - last_event_time18.tv_sec >= DEBOUNCE_MS / 1000.0 ||
                (now.tv_sec - last_event_time18.tv_sec < DEBOUNCE_MS / 1000.0 &&
                 now.tv_nsec - last_event_time18.tv_nsec >= (DEBOUNCE_MS % 1000) * 1000000L)) {
                if (log_tilt_event(18) == 0) {
                    printf("Sensor 18 tilted\n");
                }
                last_event_time18 = now;
            }
        }

        prev_val17 = val17;
        prev_val18 = val18;

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

