#include <errno.h>
#include <gpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN 22
#define LOG_FILE "obstacle_log.csv"
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_data(FILE *fp, int s1, int s2, int led) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, s1, s2, led) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *s1 = NULL, *s2 = NULL, *led = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    s1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    s2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!s1 || !s2 || !led) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(s1, "tcrt5000-s1") < 0) {
        fprintf(stderr, "Failed to request SENSOR1 as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(s2, "tcrt5000-s2") < 0) {
        fprintf(stderr, "Failed to request SENSOR2 as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "tcrt5000-led", 0) < 0) {
        fprintf(stderr, "Failed to request LED as output: %s\n", strerror(errno));
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int s1_val = gpiod_line_get_value(s1);
        int s2_val = gpiod_line_get_value(s2);
        if (s1_val < 0 || s2_val < 0) {
            fprintf(stderr, "Failed to read sensor values: %s\n", strerror(errno));
            break;
        }

        int led_state = (s1_val == 0 && s2_val == 0) ? 1 : 0;
        if (gpiod_line_set_value(led, led_state) < 0) {
            fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
            break;
        }

        if (log_data(fp, s1_val, s2_val, led_state) < 0) {
            break;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led) {
        gpiod_line_set_value(led, 0);
        gpiod_line_release(led);
    }
    if (s1) gpiod_line_release(s1);
    if (s2) gpiod_line_release(s2);
    if (chip) gpiod_chip_close(chip);
    if (fp) fclose(fp);

    printf("Obstacle avoidance system stopped.\n");
    return ret;
}

