#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define SI1175_ADDR 0x49
#define SI1175_ALS_VIS_DATA0 0x24
#define SI1175_ALS_VIS_DATA1 0x25
#define I2C_BUS "/dev/i2c-1"
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    (void)sig;
    running = 0;
}

int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_reg16(int fd, uint8_t reg_lsb, uint16_t *val) {
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, reg_lsb, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, reg_lsb + 1, &msb) < 0) return -1;
    *val = ((uint16_t)msb << 8) | lsb;
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1175_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("Si1175 heart-rate sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t als_vis;
        if (i2c_read_reg16(fd, SI1175_ALS_VIS_DATA0, &als_vis) < 0) {
            fprintf(stderr, "Failed to read ALS visible data. Retrying in %d ms...\n", POLL_INTERVAL_MS);
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        printf("ALS Visible: %u\n", als_vis);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    close(fd);
    return 0;
}

