        goto cleanup;
    }

    ret = gpiod_line_request_input(right_line, "keywish-sensor");
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to request GPIO line %d as input: %s\n", RIGHT_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Keywish 3-Way Tracking Sensor (IR Reflectance, Digital GPIO)\n");
    printf("Left: GPIO %d, Middle: GPIO %d, Right: GPIO %d\n", LEFT_PIN, MIDDLE_PIN, RIGHT_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main polling loop */
    while (program_running) {
        int left_val = gpiod_line_get_value(left_line);
        int middle_val = gpiod_line_get_value(middle_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || middle_val < 0 || right_val < 0) {
            fprintf(stderr, "Error: Failed to read GPIO values: %s\n", strerror(errno));
            break;
        }

        printf("L:%d M:%d R:%d\n", left_val, middle_val, right_val);
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    /* Release lines and close chip */
    if (left_line) gpiod_line_release(left_line);
    if (middle_line) gpiod_line_release(middle_line);
    if (right_line) gpiod_line_release(right_line);
    if (chip) gpiod_chip_close(chip);

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

