#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27
#define PWM_FREQ   1000
#define PWM_RANGE  255
#define FADE_STEPS 50
#define FADE_SEC   5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Convert HSV color to RGB using standard formulas. */
static void hsv_to_rgb(float h, float s, float v, uint8_t *r, uint8_t *g, uint8_t *b) {
    if (s <= 0.0f) {
        *r = *g = *b = (uint8_t)v;
        return;
    }
    float hh = h * 6.0f;
    int i = (int)(hh);
    float f = hh - i;
    float p = v * (1.0f - s);
    float q = v * (1.0f - s * f);
    float t = v * (1.0f - s * (1.0f - f));
    switch (i) {
        case 0: *r = (uint8_t)(v * 255.0f); *g = (uint8_t)(t * 255.0f); *b = (uint8_t)(p * 255.0f); break;
        case 1: *r = (uint8_t)(q * 255.0f); *g = (uint8_t)(v * 255.0f); *b = (uint8_t)(p * 255.0f); break;
        case 2: *r = (uint8_t)(p * 255.0f); *g = (uint8_t)(v * 255.0f); *b = (uint8_t)(t * 255.0f); break;
        case 3: *r = (uint8_t)(p * 255.0f); *g = (uint8_t)(q * 255.0f); *b = (uint8_t)(v * 255.0f); break;
        case 4: *r = (uint8_t)(t * 255.0f); *g = (uint8_t)(p * 255.0f); *b = (uint8_t)(v * 255.0f); break;
        default: *r = (uint8_t)(v * 255.0f); *g = (uint8_t)(p * 255.0f); *b = (uint8_t)(q * 255.0f); break;
    }
}

/* Smoothly fade from one color to another over FADE_STEPS steps. */
static void fade_color(uint8_t r1, uint8_t g1, uint8_t b1,
                      uint8_t r2, uint8_t g2, uint8_t b2) {
    for (int i = 0; i <= FADE_STEPS && g_running; i++) {
        float frac = (float)i / FADE_STEPS;
        uint8_t r = (uint8_t)(r1 * (1.0f - frac) + r2 * frac);
        uint8_t g = (uint8_t)(g1 * (1.0f - frac) + g2 * frac);
        uint8_t b = (uint8_t)(b1 * (1.0f - frac) + b2 * frac);
        gpioPWM(RED_PIN,   PWM_RANGE - r);
        gpioPWM(GREEN_PIN, PWM_RANGE - g);
        gpioPWM(BLUE_PIN,  PWM_RANGE - b);
        gpioDelay(FADE_SEC * 1000000 / FADE_STEPS);
    }
}

int main(void) {
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO modes");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) != 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        syslog(LOG_ERR, "Failed to set PWM range");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    while (g_running) {
        uint8_t r1, g1, b1, r2, g2, b2;
        float hue1 = (float)rand() / RAND_MAX;
        float hue2 = (float)rand() / RAND_MAX;

        hsv_to_rgb(hue1, 1.0f, 1.0f, &r1, &g1, &b1);
        hsv_to_rgb(hue2, 1.0f, 1.0f, &r2, &g2, &b2);

        fade_color(r1, g1, b1, r2, g2, b2);
    }

    /* Turn off LED on exit. */
    gpioPWM(RED_PIN,   PWM_RANGE);
    gpioPWM(GREEN_PIN, PWM_RANGE);
    gpioPWM(BLUE_PIN,  PWM_RANGE);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

