#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 18
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define BH1750_CONV_TIME_MS 180
#define NUM_LEDS 10
#define MAX_LUX 1000.0f
#define MIN_LUX 0.0f
#define MIN_BRIGHTNESS 0
#define MAX_BRIGHTNESS 255

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioPWM(LED_PIN, 0);
    gpioTerminate();
}

static int read_light_level(void) {
    char cmd = BH1750_CONT_HIGH_RES;
    char buf[2];
    int retries = 3;

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
            fprintf(stderr, "I2C write error (attempt %d)\n", 4 - retries);
            retries--;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(BH1750_CONV_TIME_MS * 1000);

        if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
            fprintf(stderr, "I2C read error (attempt %d)\n", 4 - retries);
            retries--;
            gpioDelay(10000);
            continue;
        }

        int raw = (buf[0] << 8) | buf[1];
        return raw;
    }

    fprintf(stderr, "Failed to read light level after multiple retries\n");
    return -1;
}

static int map_lux_to_brightness(float lux) {
    if (lux < MIN_LUX) lux = MIN_LUX;
    if (lux > MAX_LUX) lux = MAX_LUX;
    float normalized = (lux - MIN_LUX) / (MAX_LUX - MIN_LUX);
    float log_norm = log10f(normalized + 1.0f);
    float brightness = MIN_BRIGHTNESS + (log_norm * (MAX_BRIGHTNESS - MIN_BRIGHTNESS));
    if (brightness < MIN_BRIGHTNESS) brightness = MIN_BRIGHTNESS;
    if (brightness > MAX_BRIGHTNESS) brightness = MAX_BRIGHTNESS;
    return (int)brightness;
}

static void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;
    gpioPWM(LED_PIN, brightness);
}

static void generate_ws2812b_data(uint8_t *data, int brightness) {
    for (int i = 0; i < NUM_LEDS; i++) {
        uint8_t g = (brightness * 3) / 4;
        uint8_t r = (brightness * 3) / 4;
        uint8_t b = brightness;
        data[i * 3] = g;
        data[i * 3 + 1] = r;
        data[i * 3 + 2] = b;
    }
}

static void send_ws2812b_data(const uint8_t *data) {
    gpioWaveClear();
    gpioWaveAddGeneric(NUM_LEDS * 3 * 8, (unsigned int *)data);
    gpioWaveTxSend(0, PI_WAVE_MODE_ONE_SHOT);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X\n", BH1750_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(LED_PIN, 8000000);
    gpioSetPWMrange(LED_PIN, 255);
    gpioPWM(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting light-controlled WS2812B strip control...\n");

    while (running) {
        int light_level = read_light_level();
        if (light_level < 0) {
            fprintf(stderr, "Skipping frame due to sensor error\n");
            gpioDelay(100000);
            continue;
        }

        int brightness = map_lux_to_brightness((float)light_level);
        set_led_brightness(brightness);

        uint8_t data[NUM_LEDS * 3];
        generate_ws2812b_data(data, brightness);
        send_ws2812b_data(data);

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

