#define NUM_LEDS 10
#define MIN_LUX 10.0
#define MAX_LUX 300.0
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_DELAY_US 0

static int i2c_fd = -1;
static int spi_fd = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t bytes = read(fd, buf, len);
    if (bytes < 0 || (size_t)bytes != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_ONE_TIME_HIGH_RES) < 0) {
        return -1;
    }
    usleep(120000);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux) {
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) {
        return -1;
    }
    uint16_t raw = (buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int apa102_init(int fd) {
    uint8_t zero_frame[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    for (int i = 0; i < NUM_LEDS; i++) {
        if (write(fd, zero_frame, 4) != 4) {
            fprintf(stderr, "APA102 init write error: %s\n", strerror(errno));
            return -1;
        }
    }
    if (write(fd, end_frame, 4) != 4) {
        fprintf(stderr, "APA102 init end write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int apa102_set_brightness(int fd, uint8_t brightness) {
    uint8_t frame[4];
    frame[0] = 0xE0 | brightness;
    frame[1] = 0x00;
    frame[2] = 0x00;
    frame[3] = 0x00;
    for (int i = 0; i < NUM_LEDS; i++) {
        if (write(fd, frame, 4) != 4) {
            fprintf(stderr, "APA102 brightness write error: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int apa102_off(int fd) {
    uint8_t frame[4] = {0xE0, 0x00, 0x00, 0x00};
    for (int i = 0; i < NUM_LEDS; i++) {
        if (write(fd, frame, 4) != 4) {
            fprintf(stderr, "APA102 off write error: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    if (apa102_init(spi_fd) < 0) {
        fprintf(stderr, "APA102 initialization failed\n");
        apa102_off(spi_fd);
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    printf("Starting light-to-LED brightness control. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Failed to read lux. Retrying...\n");
            usleep(100000);
            continue;
        }

        if (lux < MIN_LUX) lux = MIN_LUX;
        if (lux > MAX_LUX) lux = MAX_LUX;

        uint8_t brightness = (uint8_t)((lux - MIN_LUX) / (MAX_LUX - MIN_LUX) * 31.0f);
        if (apa102_set_brightness(spi_fd, brightness) < 0) {
            fprintf(stderr, "Failed to set LED brightness\n");
        }

        usleep(100000);
    }

    printf("\nShutting down...\n");
    apa102_off(spi_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    if (spi_fd >= 0) close(spi_fd);
    printf("Cleanup complete.\n");
    return 0;
}

