#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_SENSORS 3
#define I2C_BUS 1
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define FADE_DURATION_MS 500
#define LOOP_DELAY_MS 100
#define CONVERSION_DELAY_MS 180

static int i2c_handles[NUM_SENSORS];
static int spi_handle;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c_sensor(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", addr, handle);
        return -1;
    }
    if (i2cWriteByte(handle, 0x00) < 0) {
        fprintf(stderr, "Error writing to I2C device at 0x%02X\n", addr);
        i2cClose(handle);
        return -1;
    }
    if (i2cWriteByte(handle, 0x21) < 0) {
        fprintf(stderr, "Error setting One-Time High-Resolution Mode 2 at 0x%02X\n", addr);
        i2cClose(handle);
        return -1;
    }
    return handle;
}

static int read_bh1750(int handle, float *lux) {
    if (i2cWriteByte(handle, 0x00) < 0) {
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_MS * 1000);
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int calculate_average_lux(float *lux_values, int num_sensors) {
    float sum = 0.0f;
    int valid_count = 0;
    for (int i = 0; i < num_sensors; i++) {
        if (lux_values[i] >= 0.0f) {
            sum += lux_values[i];
            valid_count++;
        }
    }
    if (valid_count == 0) {
        return -1;
    }
    return (int)(sum / valid_count);
}

static int init_apa102(int spi_handle) {
    char buffer[4];
    buffer[0] = 0x00;
    buffer[1] = 0x00;
    buffer[2] = 0x00;
    buffer[3] = 0x00;
    if (spiWrite(spi_handle, buffer, 4) < 0) {
        fprintf(stderr, "Error initializing APA102\n");
        return -1;
    }
    return 0;
}

static void set_apa102_brightness(int spi_handle, int brightness) {
    char buffer[4];
    buffer[0] = 0x00;
    buffer[1] = (brightness & 0x1F) << 2;
    buffer[2] = 0x00;
    buffer[3] = 0x00;
    if (spiWrite(spi_handle, buffer, 4) < 0) {
        fprintf(stderr, "Error setting APA102 brightness\n");
    }
}

static void fade_to_brightness(int spi_handle, int target_brightness, int duration_ms) {
    int steps = duration_ms / 10;
    int increment = (target_brightness - 1) / steps;
    int current_brightness = 1;
    for (int i = 0; i < steps && running; i++) {
        set_apa102_brightness(spi_handle, current_brightness);
        current_brightness += increment;
        gpioDelay(10000);
    }
    set_apa102_brightness(spi_handle, target_brightness);
}

static void cleanup(void) {
    set_apa102_brightness(spi_handle, 0);
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
        }
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (init_apa102(spi_handle) < 0) {
        cleanup();
        return 1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = -1;
    }

    i2c_handles[0] = init_i2c_sensor(I2C_BUS, 0x23);
    if (i2c_handles[0] < 0) {
        fprintf(stderr, "Sensor 1 (0x23) not found\n");
    } else {
        i2c_handles[1] = init_i2c_sensor(I2C_BUS, 0x5C);
        if (i2c_handles[1] < 0) {
            fprintf(stderr, "Sensor 2 (0x5C) not found\n");
        } else {
            i2c_handles[2] = init_i2c_sensor(I2C_BUS, 0x77);
            if (i2c_handles[2] < 0) {
                fprintf(stderr, "Sensor 3 (0x77) not found\n");
            }
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float lux_values[NUM_SENSORS];
    int current_brightness = 0;

    while (running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] >= 0) {
                if (read_bh1750(i2c_handles[i], &lux_values[i]) < 0) {
                    fprintf(stderr, "Error reading sensor %d\n", i + 1);
                    lux_values[i] = -1.0f;
                }
            } else {
                lux_values[i] = -1.0f;
            }
        }

        int average_lux = calculate_average_lux(lux_values, NUM_SENSORS);
        if (average_lux < 0) {
            fprintf(stderr, "Error calculating average lux, skipping fade\n");
        } else {
            int target_brightness = (int)((1.0f - (average_lux / 1000.0f)) * 31.0f);
            if (target_brightness < 0) target_brightness = 0;
            if (target_brightness > 31) target_brightness = 31;

            if (target_brightness != current_brightness) {
                fade_to_brightness(spi_handle, target_brightness, FADE_DURATION_MS);
                current_brightness = target_brightness;
            }
        }

        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

