// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_ALS_REG 0x04
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 18
#define NUM_LEDS 10
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c(void);
int init_veml7700(void);
int read_veml7700(uint16_t *als_value);
float calculate_lux(uint16_t als_value);
int map_lux_to_brightness(float lux);
void set_led_brightness(int brightness);
void ws2812_send(const uint8_t *data, int len);
void cleanup(void);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Cleanup function to release resources
void cleanup(void) {
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

// Initialize I2C interface
int init_i2c(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize VEML7700 sensor
int init_veml7700(void) {
    uint8_t config_data[2];
    config_data[0] = VEML7700_CONFIG_REG;
    config_data[1] = 0x00; // Integration time 100 ms, gain 1/8

    if (write(i2c_fd, config_data, 2) != 2) {
        fprintf(stderr, "Failed to write config register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read ALS data from VEML7700
int read_veml7700(uint16_t *als_value) {
    uint8_t reg = VEML7700_ALS_REG;
    uint8_t data[2];

    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to write register address: %s\n", strerror(errno));
        return -1;
    }

    if (read(i2c_fd, data, 2) != 2) {
        fprintf(stderr, "Failed to read ALS data: %s\n", strerror(errno));
        return -1;
    }

    *als_value = (data[0] << 8) | data[1];
    return 0;
}

// Calculate lux value from ALS data
float calculate_lux(uint16_t als_value) {
    // Default integration time 100 ms, gain 1/8, lux = raw * 0.0036 * (1/gain) * (100ms/integration_time)
    // For default settings, lux = raw * 0.0288
    return (float)als_value * 0.0288f;
}

// Map lux value to LED brightness (0-255) using gamma correction
int map_lux_to_brightness(float lux) {
    if (lux < 0.0f) lux = 0.0f;
    if (lux > 120000.0f) lux = 120000.0f;

    float brightness = 255.0f * powf(lux / 120000.0f, 1.0f / 2.2f);
    if (brightness < 0.0f) brightness = 0.0f;
    if (brightness > 255.0f) brightness = 255.0f;

    return (int)brightness;
}

// Set LED brightness using bit-banging (800 kHz high frequency)
void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    // WS2812B protocol: 800 kHz, 50% duty cycle
    const int bit_delay_us = 50; // 50 us per bit
    const int total_delay_us = 1000000; // 1 ms total
    const int num_bits = 24; // 24 bits per LED
    const int num_bytes = (num_bits + 7) / 8; // Round up to multiple of 8

    uint8_t data[num_bytes];
    for (int i = 0; i < num_bytes; i++) {
        data[i] = 0;
    }

    // Set bits from high byte to low byte
    for (int i = 0; i < num_bits; i++) {
        int bit = (brightness >> (num_bits - 1 - i)) & 1;
        if (bit) {
            data[num_bytes - 1 - (i / 8)] |= (1 << (7 - (i % 8)));
        }
    }

    ws2812_send(data, num_bytes);
}

// Send data to WS2812B strip via libgpiod
void ws2812_send(const uint8_t *data, int len) {
    // WS2812B protocol: 800 kHz, 50% duty cycle
    const int bit_delay_us = 50; // 50 us per bit
    const int total_delay_us = 1000000; // 1 ms total
    const int num_bits = 24; // 24 bits per LED
    const int num_bytes = (num_bits + 7) / 8; // Round up to multiple of 8

    // Convert data to bit stream (MSB first)
    uint32_t bit_stream = 0;
    for (int i = 0; i < num_bytes; i++) {
        for (int j = 7; j >= 0; j--) {
            bit_stream <<= 1;
            if (data[i] & (1 << j)) {
                bit_stream |= 1;
            }
        }
    }

    // Send data using libgpiod
    // WS2812B requires 24 bits per LED, so we send 24 bits per byte
    // For each byte, we send 8 bits (24 bits)
    // For each bit, we send 2 pulses: one high, one low
    // High pulse: ~800 us, ~50% duty cycle
    // Low pulse: ~800 us, ~50% duty cycle
    // We use a single GPIO line for both high and low pulses
    // We toggle the line at a high frequency (800 kHz)
    // We use a busy-wait delay to achieve the desired high frequency
    // We use a small delay between bits to achieve the desired timing

    for (int i = 0; i < num_bytes; i++) {
        for (int j = 7; j >= 0; j--) {
            // High pulse
            gpiod_line_set_value(line, 1);
            usleep(bit_delay_us);

            // Low pulse
            gpiod_line_set_value(line, 0);
            usleep(bit_delay_us);
        }
    }
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize VEML7700
    if (init_veml7700() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO using libgpiod
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    // Request line as output, initially low
    if (gpiod_line_request_output(line, "veml7700_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("VEML7700 LED strip control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        uint16_t als_value = 0;
        int retries = 0;
        int success = 0;

        // Retry loop for I2C read
        while (retries < MAX_RETRIES && !success) {
            if (read_veml7700(&als_value) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "I2C read failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);
                    usleep(RETRY_DELAY_MS * 1000);
                }
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read ALS data after %d retries. Continuing...\n", MAX_RETRIES);
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }

        float lux = calculate_lux(als_value);
        int brightness = map_lux_to_brightness(lux);

        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        // Set LED brightness using bit-banging
        set_led_brightness(brightness);

        usleep(LOOP_DELAY_MS * 1000);
    }

    // Cleanup
    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

