#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

#define CONSUMER "flame_sensor"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static int blink_led(struct gpiod_line *led_line, int duration_ms) {
    int ret;

    ret = gpiod_line_set_value(led_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED high: %s\n", strerror(errno));
        return -1;
    }
    usleep(duration_ms * 1000);

    ret = gpiod_line_set_value(led_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED low: %s\n", strerror(errno));
        return -1;
    }
    usleep(duration_ms * 1000);

    return 0;
}

static int blink_led_rapidly(struct gpiod_line *led_line) {
    for (int i = 0; i < 5 && program_running; i++) {
        if (blink_led(led_line, 500) < 0) {
            return -1;
        }
    }
    return 0;
}

static int play_buzzer_pattern(struct gpiod_line *buzzer_line) {
    int ret;

    ret = gpiod_line_set_value(buzzer_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer high: %s\n", strerror(errno));
        return -1;
    }
    usleep(200 * 1000);

    ret = gpiod_line_set_value(buzzer_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer low: %s\n", strerror(errno));
        return -1;
    }
    usleep(200 * 1000);

    ret = gpiod_line_set_value(buzzer_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer high: %s\n", strerror(errno));
        return -1;
    }
    usleep(200 * 1000);

    ret = gpiod_line_set_value(buzzer_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer low: %s\n", strerror(errno));
        return -1;
    }
    usleep(600 * 1000);

    ret = gpiod_line_set_value(buzzer_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer high: %s\n", strerror(errno));
        return -1;
    }
    usleep(200 * 1000);

    ret = gpiod_line_set_value(buzzer_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer low: %s\n", strerror(errno));
        return -1;
    }
    usleep(200 * 1000);

    return 0;
}

static int play_buzzer_pattern_repeated(struct gpiod_line *buzzer_line) {
    for (int i = 0; i < 3 && program_running; i++) {
        if (play_buzzer_pattern(buzzer_line) < 0) {
            return -1;
        }
    }
