#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define I2C_DEVICE "/dev/i2c-1"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_CONT_HIGH_RES) < 0) {
        return -1;
    }
    usleep(180000);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux) {
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) {
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static void circular_buffer_add(float lux, float *buffer, int *index, int *count) {
    buffer[*index] = lux;
    *index = (*index + 1) % BUFFER_SIZE;
    if (*count < BUFFER_SIZE) {
        *count++;
    }
}

static float circular_buffer_average(float *buffer, int count) {
    if (count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < count; i++) {
        sum += buffer[i];
    }
    return sum / count;
}

static void set_led_rate(float avg_lux) {
    float rate = 0.5f + (avg_lux / 1000.0f) * 4.5f;
    if (rate < 0.5f) rate = 0.5f;
    if (rate > 5.0f) rate = 5.0f;
    int half_period_us = (int)(1000000.0f / rate);
    int on_time_us = half_period_us / 2;
    int off_time_us = half_period_us - on_time_us;
    if (led_line) {
        gpiod_line_set_value(led_line, 1);
        usleep(on_time_us);
        gpiod_line_set_value(led_line, 0);
        usleep(off_time_us);
    }
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "bh1750_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    float lux_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_count = 0;

    while (running) {
        float lux = 0.0f;
        if (bh1750_read_lux(i2c_fd, &lux) == 0) {
            circular_buffer_add(lux, lux_buffer, &buffer_index, &buffer_count);
            float avg_lux = circular_buffer_average(lux_buffer, buffer_count);
            set_led_rate(avg_lux);
            printf("Lux: %.2f, Avg: %.2f\n", lux, avg_lux);
        } else {
            fprintf(stderr, "Failed to read lux, skipping sample\n");
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

