        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "bh1750_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    float lux_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_count = 0;

    while (running) {
        float lux = 0.0f;
        if (bh1750_read_lux(i2c_fd, &lux) == 0) {
            circular_buffer_add(lux, lux_buffer, &buffer_index, &buffer_count);
            float avg_lux = circular_buffer_average(lux_buffer, buffer_count);
            set_led_rate(avg_lux);
            printf("Lux: %.2f, Avg: %.2f\n", lux, avg_lux);
        } else {
            fprintf(stderr, "Failed to read lux, skipping sample\n");
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

