#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// 7-segment display pattern for digit '5' (common cathode)
// Order: a, b, c, d, e, f, g, dp
static const unsigned char digit5[8] = {0b00111111, 0b00000110, 0b01011011, 0b01001111, 0b01100110, 0b01101101, 0b01111101, 0b00000111};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *data_line = NULL;
static struct gpiod_line *clock_line = NULL;
static struct gpiod_line *latch_line = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (data_line) gpiod_line_release(data_line);
    if (clock_line) gpiod_line_release(clock_line);
    if (latch_line) gpiod_line_release(latch_line);
    if (chip) gpiod_chip_close(chip);
    exit(0);
}

// Shift out one byte MSB-first, with clock and latch timing
void shift_out(unsigned char data) {
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(data_line, (data >> i) & 1);
        gpiod_line_set_value(clock_line, 1);
        usleep(1); // 1 us clock high
        gpiod_line_set_value(clock_line, 0);
        usleep(1); // 1 us clock low
    }
    gpiod_line_set_value(latch_line, 1);
    usleep(1); // 1 us latch high
    gpiod_line_set_value(latch_line, 0);
    usleep(1); // 1 us latch low
}

int main() {
    // Set up signal handler for clean exit
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    // Open GPIO chip 0 (Raspberry Pi GPIOs)
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get GPIO lines
    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);
    if (!data_line || !clock_line || !latch_line) {
        perror("Failed to get GPIO lines");
        cleanup_and_exit(1);
    }

    // Request lines as outputs, initially low
    if (gpiod_line_request_output(data_line, "seven-seg", 0) < 0 ||
        gpiod_line_request_output(clock_line, "seven-seg", 0) < 0 ||
        gpiod_line_request_output(latch_line, "seven-seg", 0) < 0) {
        perror("Failed to request GPIO lines as output");
        cleanup_and_exit(1);
    }

    printf("7-segment display blinking on GPIO17, GPIO18, GPIO27. Press Ctrl+C to exit.\n");

    while (1) {
        shift_out(digit5[5]); // Display digit '5'
        usleep(500000); // 500 ms on
        shift_out(0x00); // Turn off display
        usleep(500000); // 500 ms off
    }

    // Unreachable, but for completeness
    cleanup_and_exit(0);
    return 0;
}

