#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18
#define CONSUMER "blink_button"

static volatile sig_atomic_t keep_running = 1;

static void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    struct gpiod_line_event event;
    int ret;

    /* Register signal handler for graceful termination */
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip 0 */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip 0");
        return EXIT_FAILURE;
    }

    /* Get LED line (BCM GPIO17) */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        goto cleanup;
    }

    /* Request LED line as output, initial value low */
    ret = gpiod_line_request_output(led_line, CONSUMER, 0);
    if (ret < 0) {
        perror("Failed to request LED line as output");
        goto cleanup;
    }

    /* Get button line (BCM GPIO18) */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Failed to get button line");
        goto cleanup;
    }

    /* Request button line as input with internal pull-up and falling-edge events */
    ret = gpiod_line_request_falling_edge_events(button_line, CONSUMER);
    if (ret < 0) {
        perror("Failed to request button line as falling-edge events");
        goto cleanup;
    }

    printf("Blinking LED on BCM GPIO%d with button on BCM GPIO%d. Press Ctrl+C to exit.\n",
           LED_PIN, BUTTON_PIN);

    /* Main blink loop */
    while (keep_running) {
        ret = gpiod_line_event_wait(button_line, &(struct timespec){1, 0});
        if (ret < 0) {
            if (errno == EINTR) {
                continue; /* Interrupted by signal, check keep_running */
            }
            perror("Error waiting for button event");
            goto cleanup;
        }
        if (ret == 0) {
            /* Timeout, no event, loop back and check keep_running */
            continue;
        }

        /* Event detected, read it */
        ret = gpiod_line_event_read(button_line, &event);
        if (ret < 0) {
            perror("Error reading button event");
            goto cleanup;
        }

        /* Falling edge: button pressed */
        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            printf("Button pressed! Stopping blinking.\n");
            break;
        }
    }

    /* Turn off LED */
    ret = gpiod_line_set_value(led_line, 0);
    if (ret < 0) {
        perror("Failed to turn off LED");
        goto cleanup;
    }

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;

cleanup:
    /* Ensure LED is off on error */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return EXIT_FAILURE;
}

