#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_GPIO 5
#define BLINK_DELAY_US 750000  /* 750 ms in microseconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Register signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO5 as output */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is initially off */
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO%d low\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("LED blinking started on GPIO%d. Press Ctrl+C to exit.\n", LED_GPIO);

    while (running) {
        /* Turn LED on */
        if (gpioWrite(LED_GPIO, 1) != 0) {
            fprintf(stderr, "Failed to turn LED on on GPIO%d\n", LED_GPIO);
            break;
        }
        printf("LED ON\n");
        fflush(stdout);

        /* Wait for 750 ms */
        time_sleep(0.75);

        /* Turn LED off */
        if (gpioWrite(LED_GPIO, 0) != 0) {
            fprintf(stderr, "Failed to turn LED off on GPIO%d\n", LED_GPIO);
            break;
        }
        printf("LED OFF\n");
        fflush(stdout);

        /* Wait for 750 ms */
        time_sleep(0.75);
    }

    /* Clean up: turn LED off and terminate pigpio */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("\nLED blinking stopped.\n");

    return EXIT_SUCCESS;
}

