#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define LED_PIN 24
#define BUTTON_PIN 22
#define CONSUMER "led_button"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the gpiochip0 device */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    /* Get the LED line (GPIO24) */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line(LED_PIN)");
        goto cleanup;
    }

    /* Get the button line (GPIO22) */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line(BUTTON_PIN)");
        goto cleanup;
    }

    /* Request the LED line as output, initial value LOW */
    if (gpiod_line_request_output(led_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(LED_line)");
        goto cleanup;
    }

    /* Request the button line as input with internal pull-down */
    if (gpiod_line_request_input_flags(button_line, CONSUMER,
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        perror("gpiod_line_request_input_flags(button_line)");
        goto cleanup;
    }

    printf("LED button control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int button_val = gpiod_line_get_value(button_line);
        if (button_val < 0) {
            perror("gpiod_line_get_value(button_line)");
            break;
        }

        if (button_val == 0) {
            /* Button pressed: blink LED */
            if (gpiod_line_set_value(led_line, 1) < 0) {
                perror("gpiod_line_set_value(led_line, 1)");
                break;
            }
            usleep(500000); /* 500 ms */
            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("gpiod_line_set_value(led_line, 0)");
                break;
            }
            usleep(500000); /* 500 ms */
        } else {
            /* Button released: turn LED off */
            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("gpiod_line_set_value(led_line, 0)");
                break;
            }
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure LED is off before releasing resources */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Program terminated.\n");
    return ret;
}

