#include <signal.h>
#include <gpiod.h>

#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18
#define PWM_PERIOD_NS 10000000  // 10 ms
#define PWM_DUTY_NS 10000       // 10% duty cycle
#define PWM_STEPS 100

static volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;
    int ret;

    // Open GPIO chip 0 (Raspberry Pi 5 uses gpiochip0)
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    // Get GPIO lines
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        perror("Failed to get GPIO lines");
        goto cleanup;
    }

    // Request lines as outputs, initially low
    ret = gpiod_line_request_output(red_line, "rgb-led", 0);
    if (ret < 0) {
        perror("Failed to request red line as output");
        goto cleanup;
    }
    ret = gpiod_line_request_output(green_line, "rgb-led", 0);
    if (ret < 0) {
        perror("Failed to request green line as output");
        goto cleanup;
    }
    ret = gpiod_line_request_output(blue_line, "rgb-led", 0);
    if (ret < 0) {
        perror("Failed to request blue line as output");
        goto cleanup;
    }

    // Set up signal handler for clean exit
    signal(SIGINT, handle_sigint);

    // Main PWM loop
    while (running) {
        int red = rand() % 101;
        int green = rand() % 101;
        int blue = rand() % 101;

        // Software PWM: set duty cycle for each channel
        // For simplicity, we use busy-wait with clock_nanosleep
        // This is not a production-ready PWM implementation; use hardware PWM
        // or a dedicated PWM library for production
        for (int i = 0; i < PWM_STEPS && running; i++) {
            long duty_ns = (long)i * PWM_DUTY_NS / PWM_STEPS;
            long on_ns = PWM_PERIOD_NS - duty_ns;
            long off_ns = duty_ns;

            // Turn on red
