            if (ret < 0) {
                perror("Failed to set red high");
                goto cleanup;
            }
            // Wait for on time
            struct timespec ts_on = {0, on_ns};
            nanosleep(&ts_on, NULL);

            // Turn off red
            ret = gpiod_line_set_value(red_line, 0);
            if (ret < 0) {
                perror("Failed to set red low");
                goto cleanup;
            }
            // Wait for off time
            struct timespec ts_off = {0, off_ns};
            nanosleep(&ts_off, NULL);
        }

        // Turn on green
        ret = gpiod_line_set_value(green_line, 1);
        if (ret < 0) {
            perror("Failed to set green high");
            goto cleanup;
        }
        // Wait for on time
        struct timespec ts_on = {0, on_ns};
        nanosleep(&ts_on, NULL);

        // Turn off green
        ret = gpiod_line_set_value(green_line, 0);
        if (ret < 0) {
            perror("Failed to set green low");
            goto cleanup;
        }
        // Wait for off time
        struct timespec ts_off = {0, off_ns};
        nanosleep(&ts_off, NULL);

        // Turn on blue
        ret = gpiod_line_set_value(blue_line, 1);
        if (ret < 0) {
            perror("Failed to set blue high");
            goto cleanup;
        }
        // Wait for on time
        struct timespec ts_on = {0, on_ns};
        nanosleep(&ts_on, NULL);

        // Turn off blue
        ret = gpiod_line_set_value(blue_line, 0);
        if (ret < 0) {
            perror("Failed to set blue low");
            goto cleanup;
        }
        // Wait for off time
        struct timespec ts_off = {0, off_ns};
        nanosleep(&ts_off, NULL);
    }

cleanup:
    // Ensure LED is off before releasing lines
    if (red_line) gpiod_line_set_value(red_line, 0);
    if (green_line) gpiod_line_set_value(green_line, 0);
    if (blue_line) gpiod_line_set_value(blue_line, 0);

    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

