#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* LSM303DLHC I2C address (SA0 tied to GND) */
#define LSM303_ADDR 0x19

/* LSM303DLHC register addresses */
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A   0x28

/* GPIO pin for impact pulse */
#define IMPACT_PIN 17

/* Default threshold in G-force */
#define DEFAULT_THRESHOLD 2.0f

/* Global variables for cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Initialize the LSM303DLHC accelerometer */
static int init_lsm303(int handle) {
    /* CTRL_REG1_A: enable XYZ axes, 100 Hz ODR, normal mode */
    if (i2cWriteByteData(handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG1_A\n");
        return -1;
    }

    /* CTRL_REG4_A: 2G full-scale, high-resolution mode */
    if (i2cWriteByteData(handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG4_A\n");
        return -1;
    }

    return 0;
}

/* Read accelerometer data in G-force units (16384 LSB/G) */
static int read_accelerometer(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    /* Read 6 bytes starting from OUT_X_L_A (auto-increment) */
    if (i2cReadI2CBlockData(handle, OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error: Failed to read accelerometer data\n");
        return -1;
    }

    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    /* Convert to G-force units (16384 LSB/G = 16384 mg/G) */
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;

    return 0;
}

/* Calculate the total G-force magnitude */
static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

/* Log impact data to file */
static void log_impact(float x, float y, float z) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open impact_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, X: %.3f, Y: %.3f, Z: %.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);

    fclose(fp);
}

/* Pulse the impact GPIO pin */
static void pulse_impact_pin(int pin, int duration_ms) {
    gpioWrite(pin, 1);
    gpioDelay(duration_ms * 1000); /* gpioDelay takes microseconds */
    gpioWrite(pin, 0);
}

int main(int argc, char *argv[]) {
    float threshold = DEFAULT_THRESHOLD;
    int opt;

    /* Parse command-line arguments */
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Error: Threshold must be positive\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_g]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection to LSM303DLHC */
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus 1\n", LSM303_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the LSM303DLHC */
    if (init_lsm303(i2c_handle) < 0) {
        fprintf(stderr, "Error: LSM303DLHC initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO17 as output */
    gpioSetMode(IMPACT_PIN, PI_OUTPUT);
    gpioWrite(IMPACT_PIN, 0);

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Impact detection started. Threshold: %.2f G\n", threshold);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        float x, y, z;

        if (read_accelerometer(i2c_handle, &x, &y, &z) == 0) {
            float magnitude = calculate_magnitude(x, y, z);

            if (magnitude > threshold) {
                printf("Impact detected! Magnitude: %.3f G\n", magnitude);
                log_impact(x, y, z);
                pulse_impact_pin(IMPACT_PIN, 50);
            }
        } else {
            fprintf(stderr, "Warning: Failed to read accelerometer data, retrying...\n");
        }

        gpioDelay(100000); /* 100 ms delay (10 Hz polling rate) */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(IMPACT_PIN, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

