#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>

/* FXOS8700CQ I2C address (SA0 tied to GND) */
#define FXOS8700_ADDR 0x1F

/* FXOS8700CQ register addresses */
#define FXOS8700_WHO_AM_I 0x0D
#define FXOS8700_WHO_AM_I_VAL 0xC7
#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_XYZ_DATA_CFG 0x0E
#define FXOS8700_OUT_X_MSB 0x01

/* Sensitivity for ±2g range: 4096 counts/g */
#define SENSITIVITY 4096.0f

/* Impact threshold: 2g in m/s^2 */
#define IMPACT_THRESHOLD 19.62f

/* Global variables for cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Initialize the FXOS8700CQ sensor */
static int init_fxos8700(int handle) {
    int who_am_i = i2cReadByteData(handle, FXOS8700_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode: clear CTRL_REG1 bit 0 */
    if (i2cWriteByteData(handle, FXOS8700_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1 (standby)\n");
        return -1;
    }

    /* Configure XYZ_DATA_CFG: 0x00 = ±2g range, no high-resolution */
    if (i2cWriteByteData(handle, FXOS8700_XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing XYZ_DATA_CFG\n");
        return -1;
    }

    /* Active mode: set CTRL_REG1 bit 0 (active mode, 200 Hz ODR) */
    if (i2cWriteByteData(handle, FXOS8700_CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1 (active mode)\n");
        return -1;
    }

    return 0;
}

/* Read 6 bytes of acceleration data (left-justified, 14-bit) */
static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(handle, FXOS8700_OUT_X_MSB, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading acceleration data: expected 6 bytes, got %d\n", result);
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    /* Left-justified: shift right by 2 */
    raw_x >>= 2;
    raw_y >>= 2;
    raw_z >>= 2;

    /* Convert to g (sensitivity 4096 counts/g) */
    *x = (float)raw_x / SENSITIVITY;
    *y = (float)raw_y / SENSITIVITY;
    *z = (float)raw_z / SENSITIVITY;

    return 0;
}

/* Compute the magnitude of the acceleration vector */
static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

/* Log an impact event to a file */
static int log_impact(float x, float y, float z, float magnitude) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening impact_log.txt");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at FXOS8700_ADDR */
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n",
                FXOS8700_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (init_fxos8700(i2c_handle) < 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error setting SIGINT handler");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float x, y, z, magnitude;

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > IMPACT_THRESHOLD) {
                printf("Impact detected! Magnitude: %.3f m/s^2\n", magnitude);
                if (log_impact(x, y, z, magnitude) < 0) {
                    fprintf(stderr, "Error logging impact event\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        gpioDelay(50000); /* 50 ms delay */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

