            if (magnitude > IMPACT_THRESHOLD) {
                printf("Impact detected! Magnitude: %.3f m/s^2\n", magnitude);
                if (log_impact(x, y, z, magnitude) < 0) {
                    fprintf(stderr, "Error logging impact event\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        gpioDelay(50000); /* 50 ms delay */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

