/*
 * GY-50 L3G4200D gyroscope reader for Raspberry Pi Zero W
 * Uses Linux i2c-dev ioctl (/dev/i2c-1) — no wiringPi dependency.
 *
 * Wiring:
 *   GY-50 SDA -> GPIO2 (pin 3, I2C1 SDA)
 *   GY-50 SCL -> GPIO3 (pin 5, I2C1 SCL)
 *   GY-50 VDD -> 3.3 V
 *   GY-50 GND -> GND
 *   GY-50 SA0 -> VDD (I2C address 0x69)
 *
 * Build:  gcc -O2 -Wall -o gyro_log gyro_log.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- GY-50 constants ---- */
#define GYRO_ADDR          0x69
#define WHO_AM_I_REG       0x0F
#define WHO_AM_I_VAL       0xD3
#define CTRL_REG1_REG      0x20
#define CTRL_REG4_REG      0x23
#define OUT_X_L_REG        0x28
#define OUT_X_H_REG        0x29
#define OUT_Y_L_REG        0x2A
#define OUT_Y_H_REG        0x2B
#define OUT_Z_L_REG        0x2C
#define OUT_Z_H_REG        0x2D

#define GYRO_SENSITIVITY   0.00875f   /* dps/LSB at 250 dps full-scale */
#define STATIONARY_SAMPLES 100
#define SAMPLE_PERIOD_US  50000      /* 50 ms -> 20 Hz */
#define ALERT_THRESHOLD   50.0f      /* dps */
#define LOG_FILE          "gyro_log.txt"

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ---- Sensor init ---- */
static int gyro_init(int fd)
{
    uint8_t who;
    if (i2c_read_block(fd, WHO_AM_I_REG, &who, 1) < 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: ODR=100 Hz (bits[3:0]=0100), all axes enabled (bit[6]=1) */
    if (i2c_write_reg8(fd, CTRL_REG1_REG, 0x0F) < 0)
        return -1;

    /* CTRL_REG4: full-scale = 250 dps (bits[3:0]=0000), continuous update (bit[7]=0) */
    if (i2c_write_reg8(fd, CTRL_REG4_REG, 0x00) < 0)
        return -1;

    return 0;
}

/* ---- Calibration ---- */
static int gyro_calibrate(int fd, float *x_off, float *y_off, float *z_off)
{
    int16_t x_raw, y_raw, z_raw;
    float x_sum = 0.0f, y_sum = 0.0f, z_sum = 0.0f;
    int ok = 0;

    printf("Calibrating gyroscope (stationary for %d samples)...\n",
           STATIONARY_SAMPLES);
    fflush(stdout);

    for (int i = 0; i < STATIONARY_SAMPLES; i++) {
        if (i2c_read_block(fd, OUT_X_L_REG, (uint8_t *)&x_raw, 2) < 0)
            return -1;
        if (i2c_read_block(fd, OUT_Y_L_REG, (uint8_t *)&y_raw, 2) < 0)
            return -1;
        if (i2c_read_block(fd, OUT_Z_L_REG, (uint8_t *)&z_raw, 2) < 0)
            return -1;

        x_sum += x_raw;
        y_sum += y_raw;
        z_sum += z_raw;
        usleep(SAMPLE_PERIOD_US);
    }

    *x_off = x_sum / STATIONARY_SAMPLES;
    *y_off = y_sum / STATIONARY_SAMPLES;
    *z_off = z_sum / STATIONARY_SAMPLES;

    printf("Calibration complete: X=%.2f Y=%.2f Z=%.2f\n",
           *x_off, *y_off, *z_off);
    return 0;
}

/* ---- Read one sample ---- */
static int gyro_read(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_L_REG, buf, 6) < 0)
        return -1;

    int16_t x_raw = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t y_raw = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t z_raw = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)x_raw * GYRO_SENSITIVITY;
    *y = (float)y_raw * GYRO_SENSITIVITY;
    *z = (float)z_raw * GYRO_SENSITIVITY;
    return 0;
}

/* ---- Logging ---- */
static void log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, x, y, z);
    fflush(fp);
}

static void log_alert(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    fprintf(fp, "%s,ALERT,%.2f,%.2f,%.2f\n", ts, x, y, z);
    fflush(fp);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(/dev/i2c-1) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                GYRO_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gyro_init(g_i2c_fd) < 0) {
        fprintf(stderr, "GYRO initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    float x_off = 0.0f, y_off = 0.0f, z_off = 0.0f;
    if (gyro_calibrate(g_i2c_fd, &x_off, &y_off, &z_off) < 0) {
        fprintf(stderr, "Calibration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging gyro data to %s at 20 Hz. Press Ctrl+C to stop.\n",
           LOG_FILE);
    fflush(stdout);

    while (g_running) {
        float x, y, z;
        if (gyro_read(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error — continuing\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        x -= x_off;
        y -= y_off;
        z -= z_off;

        log_data(g_log_fp, x, y, z);

        if (fabsf(x) > ALERT_THRESHOLD ||
            fabsf(y) > ALERT_THRESHOLD ||
            fabsf(z) > ALERT_THRESHOLD) {
            log_alert(g_log_fp, x, y, z);
            fprintf(stderr, "ALERT: X=%.2f Y=%.2f Z=%.2f\n", x, y, z);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

