#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM303DLHC I2C addresses */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

/* LSM303DLHC register addresses */
#define CTRL_REG1_A      0x20
#define CTRL_REG4_A      0x23
#define OUT_X_L_A        0x28
#define MR_REG_M         0x02
#define OUT_X_H_M        0x03

/* Sensitivity scale factors for +/- 2 gauss range */
#define ACCEL_SENSITIVITY 0.000061f
#define MAG_SENSITIVITY   0.14f

/* Global variables for I2C handles and program termination */
static int accel_handle = -1;
static int mag_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Initialize the LSM303DLHC accelerometer */
static int init_accelerometer(void) {
    accel_handle = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (accel_handle < 0) {
        fprintf(stderr, "Error opening accelerometer I2C device (handle=%d)\n", accel_handle);
        return -1;
    }

    /* CTRL_REG1_A: 50 Hz, all axes enabled, normal mode */
    if (i2cWriteByteData(accel_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        i2cClose(accel_handle);
        accel_handle = -1;
        return -1;
    }

    /* CTRL_REG4_A: 8 g full scale, high-resolution mode */
    if (i2cWriteByteData(accel_handle, CTRL_REG4_A, 0x08) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        i2cClose(accel_handle);
        accel_handle = -1;
        return -1;
    }

    return 0;
}

/* Initialize the LSM303DLHC magnetometer */
static int init_magnetometer(void) {
    mag_handle = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (mag_handle < 0) {
        fprintf(stderr, "Error opening magnetometer I2C device (handle=%d)\n", mag_handle);
        return -1;
    }

    /* MR_REG_M: continuous-conversion mode */
    if (i2cWriteByteData(mag_handle, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to MR_REG_M\n");
        i2cClose(mag_handle);
        mag_handle = -1;
        return -1;
    }

    return 0;
}

/* Read accelerometer data (6 bytes starting at OUT_X_L_A) */
static int read_accelerometer(float *x, float *y, float *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(accel_handle, OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    *x = (float)raw_x * ACCEL_SENSITIVITY;
    *y = (float)raw_y * ACCEL_SENSITIVITY;
    *z = (float)raw_z * ACCEL_SENSITIVITY;

    return 0;
}

/* Read magnetometer data (6 bytes starting at OUT_X_H_M) */
static int read_magnetometer(float *x, float *y, float *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(mag_handle, OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_z = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t raw_y = (int16_t)((buffer[4] << 8) | buffer[5]);

    /* Convert to gauss: 1 LSB = 110 mg/digit, 1 gauss = 1100 mg/digit */
    *x = (float)raw_x * MAG_SENSITIVITY / 1000.0f;
    *y = (float)raw_y * MAG_SENSITIVITY / 1000.0f;
    *z = (float)raw_z * MAG_SENSITIVITY / 1000.0f;

    return 0;
}

/* Calculate tilt-compensated heading (degrees) */
static float calculate_heading(float ax, float ay, float az, float mx, float my, float mz) {
    float roll = atan2f(ay, az) * 180.0f / M_PI;
    float pitch = atan2f(-ax, sqrtf(ay * ay + az * az)) * 180.0f / M_PI;

    float hx = mx * cosf(pitch * M_PI / 180.0f) + mz * sinf(pitch * M_PI / 180.0f);
    float hy = mx * sinf(roll * M_PI / 180.0f) * sinf(pitch * M_PI / 180.0f) + my * cosf(roll * M_PI / 180.0f) - mz * sinf(roll * M_PI / 180.0f) * cosf(pitch * M_PI / 180.0f);

    return atan2f(hy, hx) * 180.0f / M_PI;
}

/* Log data to file */
static int log_data(float heading, float ax, float ay, float az, float mx, float my, float mz) {
    FILE *fp = fopen("compass_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", timestamp, heading, ax, ay, az, mx, my, mz);
    fclose(fp);
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Initialize sensors */
    if (init_accelerometer() != 0 || init_magnetometer() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        gpioTerminate();
        return 1;
    }

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers\n");
        i2cClose(accel_handle);
        i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }

    printf("Compass data logging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        float ax, ay, az, mx, my, mz;

        if (read_accelerometer(&ax, &ay, &az) == 0 &&
            read_magnetometer(&mx, &my, &mz) == 0) {

            float heading = calculate_heading(ax, ay, az, mx, my, mz);

            if (log_data(heading, ax, ay, az, mx, my, mz) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging\n");
        }

        gpioDelay(100000); /* 100 ms delay */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (accel_handle >= 0) {
        i2cClose(accel_handle);
    }
    if (mag_handle >= 0) {
        i2cClose(mag_handle);
    }
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

