#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define DATA_REG 0x01
#define CTRL_REG 0x00
#define ENABLE_CONTINUOUS 0x80
#define SAMPLE_INTERVAL_US 10000
#define LOG_FILE "audio_log.dat"

static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_sensor(int handle, int addr) {
    if (i2cWriteByteData(handle, CTRL_REG, ENABLE_CONTINUOUS) < 0) {
        fprintf(stderr, "Error: Failed to enable continuous measurement on sensor 0x%02X\n", addr);
        return -1;
    }
    return 0;
}

static int read_audio_sample(int handle, int addr, int16_t *sample) {
    int raw = i2cReadWordData(handle, DATA_REG);
    if (raw < 0) {
        fprintf(stderr, "Error: Failed to read audio sample from sensor 0x%02X (pigpio error %d)\n", addr, raw);
        return -1;
    }
    *sample = (int16_t)raw;
    return 0;
}

static void get_timestamp(struct timespec *ts) {
    clock_gettime(CLOCK_REALTIME, ts);
}

static void log_data(FILE *fp, struct timespec ts, int16_t s1, int16_t s2, long long tdoa_ns) {
    fprintf(fp, "%ld.%09ld,%d,%d,%lld\n", ts.tv_sec, ts.tv_nsec, s1, s2, tdoa_ns);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error: Failed to open I2C device for sensor 1 (addr 0x%02X): pigpio error %d\n", SENSOR1_ADDR, i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error: Failed to open I2C device for sensor 2 (addr 0x%02X): pigpio error %d\n", SENSOR2_ADDR, i2c_handle2);
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(i2c_handle1, SENSOR1_ADDR) != 0 || init_sensor(i2c_handle2, SENSOR2_ADDR) != 0) {
        fprintf(stderr, "Error: Sensor initialization failed. Check wiring and I2C address.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Bat Echolocation Analysis System started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (!terminate) {
        struct timespec ts1, ts2;
        int16_t s1, s2;
        long long tdoa_ns;

        if (read_audio_sample(i2c_handle1, SENSOR1_ADDR, &s1) != 0) {
            fprintf(stderr, "Warning: Sensor 1 read failed, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (read_audio_sample(i2c_handle2, SENSOR2_ADDR, &s2) != 0) {
            fprintf(stderr, "Warning: Sensor 2 read failed, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        get_timestamp(&ts1);
        get_timestamp(&ts2);

        tdoa_ns = (long long)(ts2.tv_sec - ts1.tv_sec) * 1000000000LL + (long long)(ts2.tv_nsec - ts1.tv_nsec);

        log_data(log_file, ts1, s1, s2, tdoa_ns);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

