#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16488A register addresses (MSB = 0) */
#define REG_X_GYRO   0x04
#define REG_Y_GYRO   0x06
#define REG_Z_GYRO   0x08
#define REG_X_ACCEL  0x0A
#define REG_Y_ACCEL  0x0C
#define REG_Z_ACCEL  0x0E

/* Sensitivities (from datasheet) */
#define GYRO_SENSITIVITY  0.005f   /* deg/sec/LSB */
#define ACCEL_SENSITIVITY 0.00025f /* g/LSB */

/* SPI configuration */
#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0b11000000000 /* bit 9 = CPHA, bit 10 = CPOL, bit 8 = aux SPI off */

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 100000

/* Dummy read delay (microseconds) */
#define READ_DELAY_US 40

/* Global state for cleanup */
static int spi_handle = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address (MSB = 0) and read a 16-bit word   */
/* ------------------------------------------------------------------ */
static int adis16488_read_register(int handle, uint8_t reg, uint16_t *value)
{
    char tx[2];
    char rx[2];

    /* Build request: MSB=0, D2=0, D1=0, D0=reg, then 0x00 */
    tx[0] = (char)(reg & 0x7F);
    tx[1] = 0x00;

    /* Perform dummy read to clock out the register address */
    if (spiXfer(handle, tx, rx, 2) != 2) {
        fprintf(stderr, "Error: spiXfer (dummy read) failed for reg 0x%02X\n", reg);
        return -1;
    }

    /* Small delay to allow the ADIS16488 to prepare the data */
    gpioDelay(READ_DELAY_US);

    /* Read the 16-bit data word */
    if (spiXfer(handle, tx, rx, 2) != 2) {
        fprintf(stderr, "Error: spiXfer (read) failed for reg 0x%02X\n", reg);
        return -1;
    }

    *value = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw 16-bit data to physical units                          */
/* ------------------------------------------------------------------ */
static void convert_data(uint16_t raw_gyro_x, uint16_t raw_gyro_y,
                         uint16_t raw_gyro_z, uint16_t raw_accel_x,
                         uint16_t raw_accel_y, uint16_t raw_accel_z,
                         float *gyro_x, float *gyro_y, float *gyro_z,
                         float *accel_x, float *accel_y, float *accel_z)
{
    *gyro_x = (float)raw_gyro_x * GYRO_SENSITIVITY;
    *gyro_y = (float)raw_gyro_y * GYRO_SENSITIVITY;
    *gyro_z = (float)raw_gyro_z * GYRO_SENSITIVITY;
    *accel_x = (float)raw_accel_x * ACCEL_SENSITIVITY;
    *accel_y = (float)raw_accel_y * ACCEL_SENSITIVITY;
    *accel_z = (float)raw_accel_z * ACCEL_SENSITIVITY;
}

/* ------------------------------------------------------------------ */
/* Log one sample to CSV file with millisecond timestamp                */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z,
                     float accel_x, float accel_y, float accel_z)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Warning: clock_gettime failed\n");
        snprintf(timestamp, sizeof(timestamp), "0.000");
    } else {
        localtime_r(&ts.tv_sec, &tm_info);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
        snprintf(timestamp + strlen(timestamp),
                 sizeof(timestamp) - strlen(timestamp),
                 ".%03ld", ts.tv_nsec / 1000000);
    }

    fprintf(fp, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register cleanup on every exit path */
    if (atexit(cleanup) != 0) {
        fprintf(stderr, "Warning: could not register cleanup handler\n");
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open CSV file for appending */
    csv_file = fopen("imu_data.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error: cannot open imu_data.csv for appending\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(csv_file, 0, SEEK_END);
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
        fflush(csv_file);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("ADIS16488A IMU data logger started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        uint16_t raw_gyro_x = 0, raw_gyro_y = 0, raw_gyro_z = 0;
        uint16_t raw_accel_x = 0, raw_accel_y = 0, raw_accel_z = 0;

        if (adis16488_read_register(spi_handle, REG_X_GYRO, &raw_gyro_x) != 0) {
            fprintf(stderr, "Warning: failed to read gyro X\n");
        }
        if (adis16488_read_register(spi_handle, REG_Y_GYRO, &raw_gyro_y) != 0) {
            fprintf(stderr, "Warning: failed to read gyro Y\n");
        }
        if (adis16488_read_register(spi_handle, REG_Z_GYRO, &raw_gyro_z) != 0) {
            fprintf(stderr, "Warning: failed to read gyro Z\n");
        }
        if (adis16488_read_register(spi_handle, REG_X_ACCEL, &raw_accel_x) != 0) {
            fprintf(stderr, "Warning: failed to read accel X\n");
        }
        if (adis16488_read_register(spi_handle, REG_Y_ACCEL, &raw_accel_y) != 0) {
            fprintf(stderr, "Warning: failed to read accel Y\n");
        }
        if (adis16488_read_register(spi_handle, REG_Z_ACCEL, &raw_accel_z) != 0) {
            fprintf(stderr, "Warning: failed to read accel Z\n");
        }

        float gyro_x_dps, gyro_y_dps, gyro_z_dps;
        float accel_x_g, accel_y_g, accel_z_g;

        convert_data(raw_gyro_x, raw_gyro_y, raw_gyro_z,
                     raw_accel_x, raw_accel_y, raw_accel_z,
                     &gyro_x_dps, &gyro_y_dps, &gyro_z_dps,
                     &accel_x_g, &accel_y_g, &accel_z_g);

        log_data(csv_file, gyro_x_dps, gyro_y_dps, gyro_z_dps,
                 accel_x_g, accel_y_g, accel_z_g);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

