#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define SPI_BITS_PER_WORD 8
#define CS_LINE_OFFSET 8
#define CS_CHIP_NAME "gpiochip4"
#define CS_LINE_OFFSET 8
#define SAMPLE_INTERVAL_US 100000

#define ADIS16448_REG_XGYRO_OUT 0x04
#define ADIS16448_REG_YGYRO_OUT 0x06
#define ADIS16448_REG_ZGYRO_OUT 0x08
#define ADIS16448_REG_XACCL_OUT 0x0A
#define ADIS16448_REG_YACCL_OUT 0x0C
#define ADIS16448_REG_ZACCL_OUT 0x0E

#define GYRO_SCALE 0.02f
#define ACCEL_SCALE 0.00025f

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Failed to assert CS line: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS line: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int adis16448_read_register(uint8_t reg, int16_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    if (spi_transfer(tx, rx, 2) < 0) {
        return -1;
    }

    *value = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

static int adis16448_read_gyro(int16_t *x, int16_t *y, int16_t *z) {
    return adis16448_read_register(ADIS16448_REG_XGYRO_OUT, x) ||
           adis16448_read_register(ADIS16448_REG_YGYRO_OUT, y) ||
           adis16448_read_register(ADIS16448_REG_ZGYRO_OUT, z);
}

static int adis16448_read_accel(int16_t *x, int16_t *y, int16_t *z) {
    return adis16448_read_register(ADIS16448_REG_XACCL_OUT, x) ||
           adis16448_read_register(ADIS16448_REG_YACCL_OUT, y) ||
           adis16448_read_register(ADIS16448_REG_ZACCL_OUT, z);
}

static void cleanup(void) {
    if (cs_line) {
        gpiod_line_set_value(cs_line, 1);
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name(CS_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", CS_CHIP_NAME, strerror(errno));
        cleanup();
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "adis16448-cs", 1) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", CS_LINE_OFFSET, strerror(errno));
        cleanup();
        return 1;
    }

    printf("ADIS16448 IMU Reader started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t gyro_x, gyro_y, gyro_z;
        int16_t accel_x, accel_y, accel_z;

        if (adis16448_read_gyro(&gyro_x, &gyro_y, &gyro_z) < 0) {
            fprintf(stderr, "Error reading gyroscope data.\n");
        } else if (adis16448_read_accel(&accel_x, &accel_y, &accel_z) < 0) {
            fprintf(stderr, "Error reading accelerometer data.\n");
        } else {
            float gyro_x_dps = (float)gyro_x * GYRO_SCALE;
            float gyro_y_dps = (float)gyro_y * GYRO_SCALE;
            float gyro_z_dps = (float)gyro_z * GYRO_SCALE;
            float accel_x_g = (float)accel_x * ACCEL_SCALE;
            float accel_y_g = (float)accel_y * ACCEL_SCALE;
            float accel_z_g = (float)accel_z * ACCEL_SCALE;

            struct timespec ts;
            clock_gettime(CLOCK_MONOTONIC, &ts);
            double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;

            printf("Timestamp: %.3f, Gyro X: %.3f dps, Gyro Y: %.3f dps, Gyro Z: %.3f dps, "
                   "Accel X: %.6f g, Accel Y: %.6f g, Accel Z: %.6f g\n",
                   timestamp, gyro_x_dps, gyro_y_dps, gyro_z_dps,
                   accel_x_g, accel_y_g, accel_z_g);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

