#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>

// ADIS16448 Register Addresses
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Scaling factors
#define GYRO_SCALE 0.05f // deg/sec/LSB
#define ACCL_SCALE 0.00025f // g/LSB

// Global variables for cleanup
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Function to read a 16-bit register from the ADIS16448
int read_register(int handle, uint8_t reg_addr, int16_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    // Build the SPI message for a two-cycle read
    tx_buf[0] = (reg_addr | 0x80) >> 8; // Set MSB for read
    tx_buf[1] = reg_addr & 0xFF;

    // Send the first read command
