#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define MPU6886_ADDR 0x68
#define WHO_AM_I 0x75
#define WHO_AM_I_VAL 0x86
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43
#define I2C_BUS "/dev/i2c-1"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (read(fd, value, 1) == 1) return 0;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int i2c_read_reg16(int fd, uint8_t reg, int16_t *value) {
    uint8_t buf[2];
    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (read(fd, buf, 2) == 2) {
            *value = (int16_t)((buf[0] << 8) | buf[1]);
            return 0;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6886_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    uint8_t who_am_i = 0;
    if (i2c_read_reg8(i2c_fd, WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n", WHO_AM_I_VAL, who_am_i);
        close(i2c_fd);
        return 1;
    }

    if (i2c_write_reg8(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU-6886: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    usleep(100000);

    if (i2c_write_reg8(i2c_fd, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set accelerometer range: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_reg8(i2c_fd, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set gyroscope range: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("MPU-6886 initialized successfully. Reading data every 50 ms...\n");

    while (running) {
        int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

        if (i2c_read_reg16(i2c_fd, ACCEL_XOUT_H, &accel_x) < 0) {
            fprintf(stderr, "Failed to read accelerometer data: %s\n", strerror(errno));
        } else if (i2c_read_reg16(i2c_fd, ACCEL_YOUT_H, &accel_y) < 0) {
            fprintf(stderr, "Failed to read accelerometer data: %s\n", strerror(errno));
        } else if (i2c_read_reg16(i2c_fd, ACCEL_ZOUT_H, &accel_z) < 0) {
            fprintf(stderr, "Failed to read accelerometer data: %s\n", strerror(errno));
        } else if (i2c_read_reg16(i2c_fd, GYRO_XOUT_H, &gyro_x) < 0) {
            fprintf(stderr, "Failed to read gyroscope data: %s\n", strerror(errno));
        } else if (i2c_read_reg16(i2c_fd, GYRO_YOUT_H, &gyro_y) < 0) {
            fprintf(stderr, "Failed to read gyroscope data: %s\n", strerror(errno));
        } else if (i2c_read_reg16(i2c_fd, GYRO_ZOUT_H, &gyro_z) < 0) {
            fprintf(stderr, "Failed to read gyroscope data: %s\n", strerror(errno));
        } else {
            printf("Accel X: %6d, Y: %6d, Z: %6d, Gyro X: %6d, Y: %6d, Z: %6d\n",
                   accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        }

        usleep(50000);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

