#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXL345 I2C address (SDO tied to GND) */
#define ADXL345_ADDR 0x53

/* ADXL345 registers */
#define ADXL345_REG_DEVID_AD 0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0 0x32

/* Expected device ID */
#define ADXL345_DEVID_AD 0xE5

/* Full-resolution mode, +/-2g range, 100 Hz ODR */
#define ADXL345_DATA_FORMAT_FULL_RES_2G 0x0B

/* GPIO pin for LED */
#define LED_PIN 17

/* Impact threshold in g */
#define IMPACT_THRESHOLD 2.5f

/* Sensitivity scale factor for +/-2g range (256 LSB/g) */
#define SCALE_FACTOR 256.0f

/* Polling interval in microseconds */
#define POLL_INTERVAL_US 10000

/* LED on-time in microseconds */
#define LED_ON_TIME_US 500000

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Initialize the ADXL345 accelerometer */
static int adxl345_init(int handle) {
    int devid = i2cReadByteData(handle, ADXL345_REG_DEVID_AD);
    if (devid < 0) {
        fprintf(stderr, "Error reading DEVID_AD register: %d\n", devid);
        return -1;
    }
    if (devid != ADXL345_DEVID_AD) {
        fprintf(stderr, "ADXL345 not detected (DEVID_AD=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_AD);
        return -1;
    }

    /* Standby mode */
    if (i2cWriteByteData(handle, ADXL345_REG_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    /* Set data format: full resolution, +/-2g range, 100 Hz ODR */
    if (i2cWriteByteData(handle, ADXL345_REG_DATA_FORMAT, ADXL345_DATA_FORMAT_FULL_RES_2G) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    /* Enter measurement mode */
    if (i2cWriteByteData(handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

/* Read acceleration data from the ADXL345 */
static int adxl345_read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    /* Read 6 bytes starting from DATAX0 (0x32) */
