#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ICM-20602 I2C address (AD0 tied to GND) */
#define ICM20602_ADDR 0x68

/* ICM-20602 register addresses */
#define WHO_AM_I       0x75
#define PWR_MGMT_1     0x6B
#define ACCEL_CONFIG   0x1C
#define GYRO_CONFIG    0x1B
#define ACCEL_XOUT_H   0x3B
#define GYRO_XOUT_H    0x43

/* Expected WHO_AM_I value for ICM-20602 */
#define ICM20602_WHO_AM_I 0x12

/* Sensitivity scales for +/-2g and +/-250 dps */
#define ACCEL_SCALE 16384.0f
#define GYRO_SCALE  131.0f

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Initialize the ICM-20602 sensor */
static int init_imu(void) {
    /* Verify sensor identity */
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != ICM20602_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n",
                ICM20602_WHO_AM_I, who_am_i);
        return -1;
    }

    /* Wake up the device (clear sleep bit) */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100000); /* 100 ms delay for oscillator to stabilize */

    /* Configure accelerometer: +/-2g, 8 kHz data rate */
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to ACCEL_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    /* Configure gyroscope: +/-250 dps, 8 kHz data rate */
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* Read accelerometer and gyroscope data from the ICM-20602 */
static int read_imu_data(float *accel_x, float *accel_y, float *accel_z,
                        float *gyro_x, float *gyro_y, float *gyro_z) {
    char buf[14];

    /* Burst read 6 bytes starting from ACCEL_XOUT_H (0x3B) */
    int result = i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading accelerometer data: expected 6 bytes, got %d\n", result);
        return -1;
    }

    /* Combine high and low bytes (little-endian) */
    int16_t raw_accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_accel_z = (int16_t)((buf[4] << 8) | buf[5]);

    /* Burst read 6 bytes starting from GYRO_XOUT_H (0x43) */
    result = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading gyroscope data: expected 6 bytes, got %d\n", result);
        return -1;
    }

    /* Combine high and low bytes (little-endian) */
    int16_t raw_gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    /* Convert raw values to physical units */
    *accel_x = (float)raw_accel_x / ACCEL_SCALE;
    *accel_y = (float)raw_accel_y / ACCEL_SCALE;
    *accel_z = (float)raw_accel_z / ACCEL_SCALE;
    *gyro_x  = (float)raw_gyro_x  / GYRO_SCALE;
    *gyro_y  = (float)raw_gyro_y  / GYRO_SCALE;
    *gyro_z  = (float)raw_gyro_z  / GYRO_SCALE;

    return 0;
}

/* Log data to a CSV file */
static int log_data(float accel_x, float accel_y, float accel_z,
                    float gyro_x, float gyro_y, float gyro_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                timestamp, accel_x, accel_y, accel_z,
                gyro_x, gyro_y, gyro_z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the ICM-20602 address */
    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the ICM-20602 sensor */
    if (init_imu() != 0) {
        fprintf(stderr, "IMU initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if the file is newly created */
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");
        fflush(log_file);
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    /* Main loop */
    while (!terminate) {
        if (read_imu_data(&accel_x, &accel_y, &accel_z,
                          &gyro_x, &gyro_y, &gyro_z) == 0) {
            if (log_data(accel_x, accel_y, accel_z,
                         gyro_x, gyro_y, gyro_z) != 0) {
                fprintf(stderr, "Logging failed, exiting\n");
                break;
            }
        } else {
            fprintf(stderr, "Failed to read IMU data, exiting\n");
            break;
        }

        gpioDelay(100000); /* 100 ms delay (10 Hz sampling rate) */
    }

    /* Cleanup */
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

