#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8451Q_ADDR  0x1D
#define WHO_AM_I       0x0D
#define WHO_AM_I_VAL   0x1A
#define CTRL_REG1      0x2A
#define OUT_X_MSB      0x01
#define LED_PIN        17
#define THRESHOLD_G    2.0f
#define POLL_MS        100
#define LED_ON_MS      500
#define LOG_FILE       "impact_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mma8451q(void) {
    uint8_t who;
    if (i2c_read_reg(WHO_AM_I, &who) < 0) return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg(CTRL_REG1, 0x00) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg(CTRL_REG1, 0x01) < 0) return -1;
    usleep(10000);
    return 0;
}

static int read_accel(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (write(i2c_fd, OUT_X_MSB, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", OUT_X_MSB, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, 6) != 6) {
        fprintf(stderr, "I2C read 6 bytes failed: %s\n", strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static float calc_g(int16_t raw) {
    return (float)raw / 1024.0f;
}

static void log_impact(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Impact detected!\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec);
    }
    fclose(fp);
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", MMA8451Q_ADDR, strerror(errno));
        cleanup();
        return 1;
    }
    if (init_mma8451q() < 0) {
        fprintf(stderr, "MMA8451Q initialization failed\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(led_line, "mma8451q-led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    printf("MMA8451Q monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t x, y, z;
        if (read_accel(&x, &y, &z) < 0) {
            usleep(POLL_MS * 1000);
            continue;
        }
        float gx = calc_g(x);
        float gy = calc_g(y);
        float gz = calc_g(z);
        float mag = sqrtf(gx * gx + gy * gy + gz * gz);
        if (mag > THRESHOLD_G) {
            printf("Impact detected! Magnitude: %.2fg\n", mag);
            gpiod_line_set_value(led_line, 1);
            usleep(LED_ON_MS * 1000);
            gpiod_line_set_value(led_line, 0);
            log_impact();
        }
        usleep(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

