    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TMAG5273_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "Timestamp,X,Y,Z\n");
        fflush(log_fp);
    }

    printf("TMAG5273 logging started. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t x, y, z;

        if (i2c_read_reg16(i2c_fd, X_REG, &x) < 0) {
            fprintf(stderr, "Error reading X register\n");
        } else if (i2c_read_reg16(i2c_fd, Y_REG, &y) < 0) {
            fprintf(stderr, "Error reading Y register\n");
        } else if (i2c_read_reg16(i2c_fd, Z_REG, &z) < 0) {
            fprintf(stderr, "Error reading Z register\n");
        } else {
            if (log_data(log_fp, x, y, z) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        sleep(1);
    }

    printf("\nShutting down...\n");

    if (log_fp != NULL) {
        fclose(log_fp);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

