/*
 * ADXL345 Freefall Interrupt Logger for Raspberry Pi 4 Model B
 * Uses libgpiod for falling-edge interrupt on GPIO17 (physical pin 11)
 * and Linux i2c-dev for I2C communication.
 *
 * Build: gcc -O2 -Wall -o freefall_logger freefall_logger.c -lgpiod
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <poll.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- ADXL345 I2C Configuration ---- */
#define ADXL345_I2C_BUS        "/dev/i2c-1"
#define ADXL345_I2C_ADDR       0x53

/* ADXL345 Registers */
#define ADXL345_REG_DEVID       0x00
#define ADXL345_REG_POWER_CTL   0x2D
#define ADXL345_REG_INT_ENABLE  0x2E
#define ADXL345_REG_INT_MAP     0x2F
#define ADXL345_REG_INT_SOURCE  0x30
#define ADXL345_REG_DATAX0      0x32
#define ADXL345_REG_THRESH_FF   0x0A
#define ADXL345_REG_TIME_FF     0x20

/* Expected Device ID */
#define ADXL345_DEVID_EXPECTED  0xE5

/* ---- Freefall Configuration ---- */
#define FREEFALL_THRESHOLD_MG   300
#define FREEFALL_TIME_MS       100

/* ---- GPIO Configuration ---- */
#define GPIO_CHIP_NAME         "gpiochip4"
#define GPIO_LINE_OFFSET       17

/* ---- Log File ---- */
#define LOG_FILE_NAME          "freefall_log.csv"

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_line = NULL;
static FILE *g_log_fp = NULL;

/* ---- Signal Handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C Helpers ---- */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- ADXL345 Initialization ---- */
static int adxl345_init(int fd)
{
    uint8_t devid = 0;

    /* Verify device identity */
    if (i2c_read_regs(fd, ADXL345_REG_DEVID, &devid, 1) < 0) {
        fprintf(stderr, "Failed to read DEVID register\n");
        return -1;
    }
    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "Unexpected DEVID: 0x%02X (expected 0x%02X). Sensor not present?\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    /* Standby mode */
    if (i2c_write_reg(fd, ADXL345_REG_POWER_CTL, 0x00) < 0)
        return -1;

    /* Clear any pending interrupts */
    if (i2c_write_reg(fd, ADXL345_REG_INT_SOURCE, 0x07) < 0)
        return -1;

    /* Set freefall threshold (300 mg) */
    if (i2c_write_reg(fd, ADXL345_REG_THRESH_FF, FREEFALL_THRESHOLD_MG / 256) < 0)
        return -1;

    /* Set freefall time (100 ms) */
    if (i2c_write_reg(fd, ADXL345_REG_TIME_FF, FREEFALL_TIME_MS / 2) < 0)
        return -1;

    /* Map freefall interrupt to INT1 */
    if (i2c_write_reg(fd, ADXL345_REG_INT_MAP, 0x00) < 0)
        return -1;

    /* Enable freefall interrupt (bit 2 = FF) */
    if (i2c_write_reg(fd, ADXL345_REG_INT_ENABLE, 0x04) < 0)
        return -1;

    /* Enter measurement mode */
    if (i2c_write_reg(fd, ADXL345_REG_POWER_CTL, 0x08) < 0)
        return -1;

    return 0;
}

/* ---- Freefall Event Detection ---- */
static int detect_freefall(int fd)
{
    uint8_t int_source = 0;

    /* Read INT_SOURCE to verify freefall bit (bit 2) */
    if (i2c_read_regs(fd, ADXL345_REG_INT_SOURCE, &int_source, 1) < 0)
        return -1;

    if (!(int_source & 0x04))
        return 0; /* No freefall event */

    /* Clear interrupt by reading INT_SOURCE again */
    if (i2c_read_regs(fd, ADXL345_REG_INT_SOURCE, &int_source, 1) < 0)
        return -1;

    return 1; /* Freefall detected */
}

/* ---- Read Acceleration Data ---- */
static int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];

    if (i2c_read_regs(fd, ADXL345_REG_DATAX0, buf, 6) < 0)
        return -1;

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

/* ---- Log Data ---- */
static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_line) {
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    int ret = EXIT_FAILURE;

    /* Setup signal handlers */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(ADXL345_I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", ADXL345_I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                ADXL345_I2C_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialize ADXL345 */
    if (adxl345_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        goto cleanup;
    }

    /* Open GPIO chip and request falling-edge interrupt line */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    g_line = gpiod_chip_get_line(g_chip, GPIO_LINE_OFFSET);
    if (!g_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(g_line, "adxl345_freefall") < 0) {
        fprintf(stderr, "Failed to request falling-edge events on GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        goto cleanup;
    }

    /* Write header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,X,Y,Z\n");
        fflush(g_log_fp);
    }

    printf("ADXL345 freefall logger started. Logging to %s. Press Ctrl+C to exit.\n",
           LOG_FILE_NAME);

    /* Main event loop */
    while (g_running) {
        struct pollfd pfd;
        int poll_ret;

        pfd.fd = g_line->line_event_fd;
        pfd.events = POLLIN;
        pfd.revents = 0;

        poll_ret = poll(&pfd, 1, 1000); /* 1 second timeout */

        if (poll_ret < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "poll() failed: %s\n", strerror(errno));
            break;
        }

        if (poll_ret == 0)
            continue; /* Timeout, no event */

        if (pfd.revents & POLLIN) {
            int16_t x, y, z;

            if (read_acceleration(g_i2c_fd, &x, &y, &z) < 0) {
                fprintf(stderr, "Failed to read acceleration data\n");
                continue;
            }

            if (detect_freefall(g_i2c_fd) == 1) {
                if (log_data(g_log_fp, x, y, z) < 0) {
                    fprintf(stderr, "Failed to log data\n");
                } else {
                    printf("Freefall detected! X=%d Y=%d Z=%d\n", x, y, z);
                }
            }
        }
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    cleanup();
    return ret;
}

