#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C address (SA0 tied to GND) */
#define LSM6DSR_ADDR 0x6A

/* LSM6DSR register addresses */
#define LSM6DSR_WHO_AM_I 0x0F
#define LSM6DSR_CTRL1_XL 0x10
#define LSM6DSR_CTRL2_G 0x11
#define LSM6DSR_OUTX_L_G 0x22
#define LSM6DSR_OUTX_L_XL 0x28

/* Expected WHO_AM_I value for LSM6DSR */
#define LSM6DSR_WHO_AM_I_VAL 0x6A

/* Freefall threshold (g) */
#define FREEFALL_THRESHOLD 0.2f

/* Impact threshold (g) */
#define IMPACT_THRESHOLD 2.5f

/* Impact window (seconds) */
#define IMPACT_WINDOW 1.0f

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Global variables */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Structure to hold sensor data */
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Function to initialize the LSM6DSR sensor */
static int init_lsm6dsr(void) {
    int who_am_i;

    /* Verify sensor identity */
    who_am_i = i2cReadByteData(i2c_handle, LSM6DSR_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != LSM6DSR_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n",
                LSM6DSR_WHO_AM_I_VAL, who_am_i);
        return -1;
    }

    /* Configure accelerometer: 104 Hz ODR, +/- 2g range */
    if (i2cWriteByteData(i2c_handle, LSM6DSR_CTRL1_XL, 0x60) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    /* Configure gyroscope: 104 Hz ODR, +/- 250 dps range */
    if (i2cWriteByteData(i2c_handle, LSM6DSR_CTRL2_G, 0x60) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

/* Function to read raw accelerometer data from the LSM6DSR */
static int read_raw_accel(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LSM6DSR_OUTX_L_XL, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

/* Function to read raw gyroscope data from the LSM6DSR */
static int read_raw_gyro(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LSM6DSR_OUTX_L_G, buffer, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

/* Function to convert raw accelerometer data to g-force units */
static void convert_accel(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                          float *accel_x, float *accel_y, float *accel_z) {
    /* Sensitivity for +/- 2g range: 16384 LSB/g */
    *accel_x = (float)raw_x / 16384.0f;
    *accel_y = (float)raw_y / 16384.0f;
    *accel_z = (float)raw_z / 16384.0f;
}

/* Function to convert raw gyroscope data to degrees per second units */
static void convert_gyro(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                         float *gyro_x, float *gyro_y, float *gyro_z) {
    /* Sensitivity for +/- 250 dps range: 131 LSB/dps */
    *gyro_x = (float)raw_x / 131.0f;
    *gyro_y = (float)raw_y / 131.0f;
    *gyro_z = (float)raw_z / 131.0f;
}

/* Function to log sensor data to a file */
static void log_data(float accel_x, float accel_y, float accel_z,
                     float gyro_x, float gyro_y, float gyro_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            timestamp, accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
    fflush(log_file);
}

/* Function to detect freefall */
static int detect_freefall(float accel_magnitude) {
    static time_t freefall_start_time = 0;
    static int freefall_detected = 0;

    if (accel_magnitude < FREEFALL_THRESHOLD) {
        if (!freefall_detected) {
            freefall_start_time = time(NULL);
            freefall_detected = 1;
        } else {
            if (difftime(time(NULL), freefall_start_time) >= IMPACT_WINDOW) {
                freefall_detected = 0;
            }
        }
    } else {
        freefall_detected = 0;
    }

    return freefall_detected;
}

/* Function to detect impact */
static int detect_impact(float accel_magnitude) {
    static time_t impact_start_time = 0;
    static int impact_detected = 0;

    if (accel_magnitude > IMPACT_THRESHOLD) {
        if (!impact_detected) {
            impact_start_time = time(NULL);
            impact_detected = 1;
        } else {
            if (difftime(time(NULL), impact_start_time) >= IMPACT_WINDOW) {
                impact_detected = 0;
            }
        }
    } else {
        impact_detected = 0;
    }

    return impact_detected;
}

/* Function to cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int16_t raw_accel_x, raw_accel_y, raw_accel_z;
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
    float accel_magnitude;
    int freefall_detected, impact_detected;

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize LSM6DSR sensor */
    if (init_lsm6dsr() != 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        cleanup();
        return 1;
    }

    /* Open log file in append mode */
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    /* Register signal handlers for graceful shutdown */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("LSM6DSR motion detection started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        /* Read raw accelerometer data */
        if (read_raw_accel(&raw_accel_x, &raw_accel_y, &raw_accel_z) == 0) {
            /* Read raw gyroscope data */
            if (read_raw_gyro(&raw_gyro_x, &raw_gyro_y, &raw_gyro_z) == 0) {
                /* Convert raw data to g-force units */
                convert_accel(raw_accel_x, raw_accel_y, raw_accel_z,
                              &accel_x, &accel_y, &accel_z);
                convert_gyro(raw_gyro_x, raw_gyro_y, raw_gyro_z,
                             &gyro_x, &gyro_y, &gyro_z);

                /* Calculate accelerometer magnitude */
                accel_magnitude = sqrtf(accel_x * accel_x +
                                         accel_y * accel_y +
                                         accel_z * accel_z);

                /* Detect freefall and impact */
                freefall_detected = detect_freefall(accel_magnitude);
                impact_detected = detect_impact(accel_magnitude);

                /* Log data to file */
                log_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

                /* Print detection status */
                printf("Accel: X=%.2f Y=%.2f Z=%.2f | Gyro: X=%.2f Y=%.2f Z=%.2f | "
                       "Mag=%.2f | Freefall=%s | Impact=%s\n",
                       accel_x, accel_y, accel_z,
                       gyro_x, gyro_y, gyro_z,
                       accel_magnitude,
                       freefall_detected ? "YES" : "NO",
                       impact_detected ? "YES" : "NO");
            } else {
                fprintf(stderr, "Error reading gyroscope data, retrying...\n");
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
        }

        /* Delay for 100 milliseconds (104 Hz ODR) */
        gpioDelay(100000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

