#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16266 Register Addresses (16-bit, MSB first) */
#define WHO_AM_I_REG        0x00
#define WHO_AM_I_VAL        0x3F5A
#define X_GYRO_OUT_REG      0x14
#define X_GYRO_OUT_LSB_REG  0x15
#define X_GYRO_OUT_MSB_REG  0x16

/* SPI Configuration */
#define SPI_CHANNEL         0
#define SPI_SPEED           1000000  /* 1 MHz */
#define SPI_FLAGS           0x0003  /* Mode 3: CPOL=1, CPHA=1 */

/* Global variables */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int spi_read_register(uint8_t reg, uint16_t *value);
static int spi_write_register(uint8_t reg, uint16_t value);
static int read_gyro_data(float *gyro_x);
static int log_data(float gyro_x);
static void signal_handler(int signal);
static void cleanup(void);

/*
 * Read a 16-bit register from the ADIS16266.
 * The ADIS16266 expects the register address with bit 7 set (0x80).
 * The response is returned in the next transaction.
 */
static int spi_read_register(uint8_t reg, uint16_t *value) {
    char tx_buf[2];
