#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* L3G4200D I2C address (SA0 tied to GND) */
#define L3G4200D_ADDR 0x69

/* L3G4200D register addresses */
#define WHO_AM_I      0x0F
#define CTRL_REG1     0x20
#define CTRL_REG4     0x23
#define OUT_X_L       0x28

/* Expected WHO_AM_I value for L3G4200D */
#define WHO_AM_I_VAL  0xD3

/* Sensitivity for +/- 250 dps range: 8.75 mdps/LSB */
#define SENSITIVITY   8.75f

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Retry parameters */
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

/* Global variables for signal handler */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int init_gyro(void);
static int read_gyro_data(float *x, float *y, float *z);
static int log_data(float x, float y, float z);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful termination */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* Initialize the L3G4200D gyroscope */
static int init_gyro(void) {
    int retries = 0;
    int result;

    /* Verify sensor identity */
    result = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (result < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (result != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n",
                WHO_AM_I_VAL, result);
        return -1;
    }

    /* Configure CTRL_REG1: normal mode, all axes enabled, 100 Hz ODR */
    result = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
    if (result < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    /* Configure CTRL_REG4: +/- 250 dps full-scale range, high-resolution off */
    result = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* Read raw X, Y, and Z angular velocities from the gyroscope */
static int read_gyro_data(float *x, float *y, float *z) {
    char buffer[6];
    int result;

    /* Read 6 bytes starting from OUT_X_L (0x28) */
    result = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading gyroscope data: expected 6 bytes, got %d: %s\n",
                result, strerror(errno));
        return -1;
    }

    /* Combine high and low bytes (little-endian) */
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    /* Convert to degrees per second */
    *x = (float)raw_x / SENSITIVITY;
    *y = (float)raw_y / SENSITIVITY;
    *z = (float)raw_z / SENSITIVITY;

    return 0;
}

/* Log data to a CSV file with nanosecond timestamps */
static int log_data(float x, float y, float z) {
    struct timespec ts;
    char timestamp[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp),
             ".%09ld", ts.tv_nsec);

    if (fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    float x, y, z;

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection to the L3G4200D */
    i2c_handle = i2cOpen(I2C_BUS, L3G4200D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the gyroscope */
    if (init_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write the header row if the file is newly created */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            if (log_data(x, y, z) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyro data, retrying...\n");
        }

        gpioDelay(10000); /* 10 ms delay */
    }

    /* Graceful cleanup */
    printf("\nExiting gracefully...\n");
    cleanup();

    return EXIT_SUCCESS;
}

