#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x53
#define X_LSB_REG      0x28
#define X_MSB_REG      0x29
#define Y_LSB_REG      0x2A
#define Y_MSB_REG      0x2B
#define Z_LSB_REG      0x2C
#define Z_MSB_REG      0x2D
#define SAMPLE_MS      100
#define LOG_FILE       "vibration_log.csv"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read a single byte from an 8-bit register; returns 0 on success, -1 on error. */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a signed 16-bit axis from two consecutive registers (LSB, MSB). */
static int i2c_read_axis(int fd, uint8_t lsb_reg, uint8_t msb_reg, int16_t *out)
{
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, lsb_reg, &lsb) < 0)
        return -1;
    if (i2c_read_reg8(fd, msb_reg, &msb) < 0)
        return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus. */
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the D7S-0001 slave address. */
    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                D7S_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Verify sensor presence by reading the X_LSB register. */
    uint8_t probe;
    if (i2c_read_reg8(fd, X_LSB_REG, &probe) < 0) {
        fprintf(stderr, "D7S-0001 not responding at 0x%02X on %s\n",
                D7S_ADDR, I2C_BUS);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode. */
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty. */
    long pos = ftell(fp);
    if (pos == 0) {
        if (fprintf(fp, "Timestamp,X,Y,Z\n") < 0) {
            fprintf(stderr, "fprintf(header) failed: %s\n", strerror(errno));
            fclose(fp);
            close(fd);
            return EXIT_FAILURE;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "fflush(header) failed: %s\n", strerror(errno));
            fclose(fp);
            close(fd);
            return EXIT_FAILURE;
        }
    }

    printf("Vibration monitoring started. Logging to %s every %d ms.\n",
           LOG_FILE, SAMPLE_MS);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop. */
    while (g_running) {
        int16_t x, y, z;

        if (i2c_read_axis(fd, X_LSB_REG, X_MSB_REG, &x) < 0) {
            fprintf(stderr, "X axis read failed; skipping sample.\n");
        } else if (i2c_read_axis(fd, Y_LSB_REG, Y_MSB_REG, &y) < 0) {
            fprintf(stderr, "Y axis read failed; skipping sample.\n");
        } else if (i2c_read_axis(fd, Z_LSB_REG, Z_MSB_REG, &z) < 0) {
            fprintf(stderr, "Z axis read failed; skipping sample.\n");
        } else {
            if (log_data(fp, x, y, z) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        }

        /* Sleep SAMPLE_MS milliseconds, checking g_running every 100 ms. */
        for (int i = 0; i < 10 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down...\n");

    /* Clean resource release on all exit paths. */
    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(log) failed: %s\n", strerror(errno));
    }
    if (close(fd) != 0) {
        fprintf(stderr, "close(fd) failed: %s\n", strerror(errno));
    }

    printf("Resources released. Goodbye.\n");
    return EXIT_SUCCESS;
}

