#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LOG_FILE "conveyor_log.txt"
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_data(FILE *fp, int sensor1_state, int sensor2_state) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    if (fprintf(fp, "%s - Sensor1: %d, Sensor2: %d\n", timestamp, sensor1_state, sensor2_state) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor1_line = NULL;
    struct gpiod_line *sensor2_line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SENSOR1_PIN, strerror(errno));
        goto cleanup;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SENSOR2_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(sensor1_line, "conveyor_monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input with pull-up: %s\n", SENSOR1_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(sensor2_line, "conveyor_monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input with pull-up: %s\n", SENSOR2_PIN, strerror(errno));
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Conveyor belt monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_state = gpiod_line_get_value(sensor1_line);
        int sensor2_state = gpiod_line_get_value(sensor2_line);

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "Error reading sensor values: %s\n", strerror(errno));
            break;
        }

        if (log_data(log_file, sensor1_state, sensor2_state) != 0) {
            break;
        }

        if (sensor1_state == 1 && sensor2_state == 1) {
            printf("Conveyor halted due to both sensors triggered!\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Conveyor belt monitoring stopped.\n");
    return ret;
}

