#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MMA8452Q_ADDR        0x1D
#define WHO_AM_I_REG        0x0D
#define WHO_AM_I_VAL        0x2A
#define CTRL_REG1_REG       0x2A
#define OUT_X_MSB_REG       0x01
#define SAMPLE_PERIOD_US    10000   /* 10 ms -> 100 Hz */
#define TILT_THRESHOLD_DEG  45.0f
#define LOG_FILE_NAME       "fall_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mma8452q(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, WHO_AM_I_REG, &who_am_i) < 0)
        return -1;
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode first so we can configure */
    if (i2c_write_reg8(fd, CTRL_REG1_REG, 0x00) < 0)
        return -1;

    /* Data rate = 100 Hz (bits 3-5 = 0b010) */
    if (i2c_write_reg8(fd, CTRL_REG1_REG, 0x02) < 0)
        return -1;

    /* Active mode */
    if (i2c_write_reg8(fd, CTRL_REG1_REG, 0x01) < 0)
        return -1;

    return 0;
}

static int read_accel_data(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_MSB_REG, buf, sizeof(buf)) < 0)
        return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]) >> 4;
    *y = (int16_t)((buf[2] << 8) | buf[3]) >> 4;
    *z = (int16_t)((buf[4] << 8) | buf[5]) >> 4;
    return 0;
}

static float calculate_tilt_angle(int16_t x, int16_t y, int16_t z)
{
    float x_norm = (float)x / 16384.0f;
    float y_norm = (float)y / 16384.0f;
    float z_norm = (float)z / 16384.0f;

    float tilt_angle = atan2f(x_norm, sqrtf(y_norm * y_norm + z_norm * z_norm)) * 180.0f / M_PI;
    if (tilt_angle < 0.0f)
        tilt_angle += 360.0f;
    return tilt_angle;
}

static void log_fall_event(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MMA8452Q_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_mma8452q(g_i2c_fd) < 0) {
        fprintf(stderr, "MMA8452Q initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("MMA8452Q initialized. Logging fall events to %s. Press Ctrl+C to exit.\n",
           LOG_FILE_NAME);

    while (g_running) {
        int16_t x, y, z;
        if (read_accel_data(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read accelerometer data; skipping sample.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float tilt_angle = calculate_tilt_angle(x, y, z);

        if (tilt_angle > TILT_THRESHOLD_DEG) {
            log_fall_event(g_log_fp, x, y, z);
            printf("Fall detected! Tilt angle: %.2f degrees\n", tilt_angle);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0)
            fprintf(stderr, "Warning: fclose log file failed: %s\n", strerror(errno));
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        if (close(g_i2c_fd) != 0)
            fprintf(stderr, "Warning: close I2C fd failed: %s\n", strerror(errno));
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

