        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MMA8452Q_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_mma8452q(g_i2c_fd) < 0) {
        fprintf(stderr, "MMA8452Q initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("MMA8452Q initialized. Logging fall events to %s. Press Ctrl+C to exit.\n",
           LOG_FILE_NAME);

    while (g_running) {
        int16_t x, y, z;
        if (read_accel_data(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read accelerometer data; skipping sample.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float tilt_angle = calculate_tilt_angle(x, y, z);

        if (tilt_angle > TILT_THRESHOLD_DEG) {
            log_fall_event(g_log_fp, x, y, z);
            printf("Fall detected! Tilt angle: %.2f degrees\n", tilt_angle);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0)
            fprintf(stderr, "Warning: fclose log file failed: %s\n", strerror(errno));
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        if (close(g_i2c_fd) != 0)
            fprintf(stderr, "Warning: close I2C fd failed: %s\n", strerror(errno));
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

