#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LIS3MDL_ADDR   0x1E
#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0x3D
#define CTRL_REG1      0x20
#define CTRL_REG4      0x23
#define CTRL_REG3      0x22
#define OUT_X_L        0x28
#define OUT_X_H        0x29
#define OUT_Y_L        0x2A
#define OUT_Y_H        0x2B
#define OUT_Z_L        0x2C
#define OUT_Z_H        0x2D

#define MAG_SENSITIVITY 0.146f   /* mG/LSB for +/-4 gauss */
#define THRESHOLD_MG   800.0f
#define SAMPLE_HZ      10
#define RETRY_COUNT    3
#define LOG_FILE       "magnetic_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (burst reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_lis3mdl(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: ODR=80Hz (0x70), continuous-conversion mode (0x00) */
    if (i2c_write_reg8(fd, CTRL_REG1, 0x70) < 0) return -1;

    /* CTRL_REG4: FS=+/-4 gauss (0x0C), high-performance mode (0x0C) */
    if (i2c_write_reg8(fd, CTRL_REG4, 0x0C) < 0) return -1;

    /* CTRL_REG3: all axes enabled (0x00) */
    if (i2c_write_reg8(fd, CTRL_REG3, 0x00) < 0) return -1;

    return 0;
}

static int read_magnetometer(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, OUT_X_L, buf, 6) < 0) {
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * MAG_SENSITIVITY;
    *y = (float)raw_y * MAG_SENSITIVITY;
    *z = (float)raw_z * MAG_SENSITIVITY;

    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    fprintf(fp, "%.3f,%.3f,%.3f\n", x, y, z);
    fflush(fp);
}

static void check_threshold(float x, float y, float z) {
    float mag = sqrtf(x * x + y * y + z * z);
    if (mag > THRESHOLD_MG) {
        fprintf(stderr, "Metal detected! Total field: %.2f mG\n", mag);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_lis3mdl(g_i2c_fd) < 0) {
        fprintf(stderr, "LIS3MDL initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen " LOG_FILE);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("LIS3MDL initialized. Logging to %s at %d Hz. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_HZ);

    while (g_running) {
        float x, y, z;
        int ok = 0;

        for (int attempt = 0; attempt < RETRY_COUNT && g_running; attempt++) {
            if (read_magnetometer(g_i2c_fd, &x, &y, &z) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed\n", attempt + 1, RETRY_COUNT);
            usleep(100000);
        }

        if (!ok) {
            fprintf(stderr, "Failed to read magnetometer after %d attempts; continuing\n", RETRY_COUNT);
            usleep(1000000 / SAMPLE_HZ);
            continue;
        }

        log_data(g_log_fp, x, y, z);
        check_threshold(x, y, z);

        usleep(1000000 / SAMPLE_HZ);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    return EXIT_SUCCESS;
}

