#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL354B Register Addresses
#define ADXL354B_REG_DEVID_AD 0x00
#define ADXL354B_REG_PARTID    0x01
#define ADXL354B_REG_RESET     0x1F
#define ADXL354B_REG_POWER_CTL 0x2D
#define ADXL354B_REG_DATAX0    0x08
#define ADXL354B_REG_STATUS    0x04

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_FLAGS 0       // Mode 0, active low CS

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_register(int handle, uint8_t reg, uint8_t *value);
int spi_write_register(int handle, uint8_t reg, uint8_t value);
int adxl354b_init(int handle);
int read_acceleration(int handle, float *x, float *y, float *z);
void log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read a single register from the ADXL354B
int spi_read_register(int handle, uint8_t reg, uint8_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    // Construct SPI message for read (bit 7 = 1, bit 6 = 0)
    tx_buf[0] = reg | 0x80; // Read bit set
    tx_buf[1] = 0x00;       // Dummy byte for clocking data out

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI read error on register 0x%02X\n", reg);
        return -1;
    }

    *value = (uint8_t)rx_buf[1];
    return 0;
}

// Function to write a single register to the ADXL354B
int spi_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx_buf[2];
    char rx_buf[2];

    // Construct SPI message for write (bit 7 = 0, bit 6 = 0)
    tx_buf[0] = reg & 0x7F; // Write bit cleared
    tx_buf[1] = value;

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI write error on register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

// Function to initialize the ADXL354B accelerometer
int adxl354b_init(int handle) {
    uint8_t partid;

    // Check device ID to verify sensor presence
    if (spi_read_register(handle, ADXL354B_REG_DEVID_AD, &partid) != 0) {
        fprintf(stderr, "Failed to read PARTID register\n");
        return -1;
    }

    if (partid != 0x1D) {
        fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x1D)\n", partid);
        return -1;
    }

    // Reset the device
    if (spi_write_register(handle, ADXL354B_REG_RESET, 0x52) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms for reset to complete

    // Set measurement mode: clear RUN bit in POWER_CTL
    if (spi_write_register(handle, ADXL354B_REG_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Failed to set measurement mode\n");
        return -1;
    }
    gpioDelay(1000); // Wait for measurement mode to stabilize

    // Set measurement mode: set RUN bit in POWER_CTL
    if (spi_write_register(handle, ADXL354B_REG_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Failed to set measurement mode\n");
        return -1;
    }
    gpioDelay(1000); // Wait for measurement mode to stabilize

    return 0;
}

// Function to read acceleration data from the ADXL354B
int read_acceleration(int handle, float *x, float *y, float *z) {
    uint8_t data[6];
    int16_t x_raw, y_raw, z_raw;
    float x_g, y_g, z_g;

    // Read 6 bytes of acceleration data (XDATA, YDATA, ZDATA)
    if (spi_read_register(handle, ADXL354B_REG_DATAX0, &data[0]) != 0) {
        fprintf(stderr, "Failed to read XDATA\n");
        return -1;
    }
    if (spi_read_register(handle, ADXL354B_REG_DATAX0 + 1, &data[1]) != 0) {
        fprintf(stderr, "Failed to read YDATA\n");
        return -1;
    }
    if (spi_read_register(handle, ADXL354B_REG_DATAX0 + 2, &data[2]) != 0) {
        fprintf(stderr, "Failed to read ZDATA\n");
        return -1;
    }

    // Combine bytes into 16-bit signed integers (20-bit left-justified)
    x_raw = (int16_t)((data[1] << 12) | (data[0] << 4) | (data[2] >> 4));
    y_raw = (int16_t)((data[3] << 12) | (data[2] << 4) | (data[4] >> 4));
    z_raw = (int16_t)((data[5] << 12) | (data[4] << 4) | (data[6] >> 4));

    // Convert to g-force units (3.9 microg/LSB = 0.0000039 g/LSB)
    x_g = (float)x_raw * 0.0000039f;
    y_g = (float)y_raw * 0.0000039f;
    z_g = (float)z_raw * 0.0000039f;

    *x = x_g;
    *y = y_g;
    *z = z_g;

    return 0;
}

// Function to log data to a file
void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, X: %.3f g, Y: %.3f g, Z: %.3f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

int main() {
    float x, y, z;

