#define ADIS16362_REG_XACCL  0x0A
#define ADIS16362_REG_YACCL  0x0C
#define ADIS16362_REG_ZACCL  0x0E

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_FLAGS 3  /* Mode 3: active-high CE, MSB first */

/* Scaling factors */
#define GYRO_SCALE 0.05f  /* deg/sec/LSB */
#define ACCEL_SCALE 0.0025f /* g/LSB */

/* Global variables for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Read a 16-bit register from the ADIS16362 via SPI */
static int read_register(uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    /* Build SPI message: send register address (MSB set) + dummy byte */
    tx_buf[0] = (char)(reg_addr | 0x80);
    tx_buf[1] = 0x00;

    /* Perform SPI transfer */
    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: spiXfer failed for register 0x%02X (returned %d)\n", reg_addr, result);
        return -1;
    }

    /* Data is returned in the second byte of the response */
    *data = (int16_t)((uint8_t)rx_buf[1] << 8);
    return 0;
}

/* Log data to CSV file */
static int log_data(FILE *fp, float x_gyro, float y_gyro, float z_gyro,
                    float x_accel, float y_accel, float z_accel) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%ld.%09ld,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
                (long)ts.tv_sec, ts.tv_nsec,
                x_gyro, y_gyro, z_gyro,
                x_accel, y_accel, z_accel) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open imu_log.csv: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
        fflush(log_file);
    }

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler: %s\n", strerror(errno));
    }

    /* Main loop */
    while (!terminate) {
        int16_t x_gyro, y_gyro, z_gyro;
        int16_t x_accel, y_accel, z_accel;
        float gyro_x, gyro_y, gyro_z;
        float accel_x, accel_y, accel_z;

        /* Read gyroscope data */
        if (read_register(ADIS16362_REG_XGYRO, &x_gyro) != 0) {
            fprintf(stderr, "Error: Failed to read gyroscope data\n");
        } else {
            gyro_x = (float)x_gyro * GYRO_SCALE;
        }

        if (read_register(ADIS16362_REG_YGYRO, &y_gyro) != 0) {
            fprintf(stderr, "Error: Failed to read gyroscope data\n");
        } else {
            gyro_y = (float)y_gyro * GYRO_SCALE;
        }

        if (read_register(ADIS16362_REG_ZGYRO, &z_gyro) != 0) {
            fprintf(stderr, "Error: Failed to read gyroscope data\n");
        } else {
            gyro_z = (float)z_gyro * GYRO_SCALE;
        }

        /* Read accelerometer data */
        if (read_register(ADIS16362_REG_XACCL, &x_accel) != 0) {
            fprintf(stderr, "Error: Failed to read accelerometer data\n");
        } else {
            accel_x = (float)x_accel * ACCEL_SCALE;
        }

        if (read_register(ADIS16362_REG_YACCL, &y_accel) != 0) {
            fprintf(stderr, "Error: Failed to read accelerometer data\n");
        } else {
            accel_y = (float)y_accel * ACCEL_SCALE;
        }

        if (read_register(ADIS16362_REG_ZACCL, &z_accel) != 0) {
            fprintf(stderr, "Error: Failed to read accelerometer data\n");
        } else {
            accel_z = (float)z_accel * ACCEL_SCALE;
        }

        /* Log data */
        if (log_data(log_file, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        /* Delay for approximately 10 ms (100 Hz sampling) */
        gpioDelay(10000);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

