#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo);
    } else {
        snprintf(buf, len, "UNKNOWN");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *req = NULL;
    struct gpiod_line_bulk bulk;
    struct gpiod_line_values values;
    int ret;
    char timestamp[32];

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the two lines for both sensors */
    ret = gpiod_chip_get_lines(chip, &bulk);
    if (ret < 0) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_bulk_add(&bulk, SENSOR1_PIN) < 0) {
        fprintf(stderr, "Failed to add line %d: %s\n", SENSOR1_PIN, strerror(errno));
        goto cleanup_chip;
    }
    if (gpiod_line_bulk_add(&bulk, SENSOR2_PIN) < 0) {
        fprintf(stderr, "Failed to add line %d: %s\n", SENSOR2_PIN, strerror(errno));
        goto cleanup_chip;
    }

    /* Request both lines as inputs */
    req = gpiod_chip_request_lines(&bulk, "ky032-collision", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (req == NULL) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(errno));
        goto cleanup_chip;
    }

    printf("Collision avoidance system started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (program_running) {
        ret = gpiod_line_request_get_values(req, &values);
        if (ret < 0) {
            fprintf(stderr, "Failed to read GPIO values: %s\n", strerror(errno));
            break;
        }

        get_timestamp(timestamp, sizeof(timestamp));

        printf("[%s] Sensor1: %d, Sensor2: %d\n",
               timestamp,
               gpiod_line_value_get_value(&values, SENSOR1_PIN),
               gpiod_line_value_get_value(&values, SENSOR2_PIN));

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");

cleanup_req:
    if (req != NULL) {
        gpiod_line_request_release(req);
    }
cleanup_chip:
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

