        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error setting CS low: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error setting CS high: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Initialize ADIS16266 sensor
int adis16266_init(void) {
    // Enable data ready mode (bit 0 of MSC_CTRL)
    uint8_t msc_ctrl_buf[3] = {0x24, 0x01, 0x00}; // MSC_CTRL register address, then data
    if (spi_transfer(msc_ctrl_buf, NULL, 3) < 0) {
        fprintf(stderr, "Error writing to MSC_CTRL register\n");
        return -1;
    }

    // Wait for data ready (bit 0 of MSC_CTRL should be 1)
    uint8_t msc_ctrl_read[3] = {0x24, 0x00, 0x00};
    uint8_t msc_ctrl_read_buf[3];
    for (int i = 0; i < 10; i++) {
        if (spi_transfer(msc_ctrl_read, msc_ctrl_read_buf, 3) < 0) {
            fprintf(stderr, "Error reading MSC_CTRL register\n");
            return -1;
        }
        if (msc_ctrl_read_buf[2] & 0x01) {
            break;
        }
        usleep(10000); // 10 ms delay
    }

    if (!(msc_ctrl_read_buf[2] & 0x01)) {
        fprintf(stderr, "ADIS16266 data ready timeout\n");
        return -1;
    }

    return 0;
}

// Read gyroscope data from ADIS16266
int adis16266_read_gyro(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Read X gyroscope output (0x04)
    tx_buf[0] = ADIS16266_REG_XGYRO_OUT | 0x80; // Set MSB for read
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;

    if (spi_transfer(tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error reading X gyroscope data\n");
        return -1;
    }

    *x = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);

    // Read Y gyroscope output (0x06)
    tx_buf[0] = ADIS16266_REG_YGYRO_OUT | 0x80;
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;

    if (spi_transfer(tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error reading Y gyroscope data\n");
        return -1;
    }

    *y = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);

    // Read Z gyroscope output (0x08)
    tx_buf[0] = ADIS16266_REG_ZGYRO_OUT | 0x80;
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;

    if (spi_transfer(tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error reading Z gyroscope data\n");
        return -1;
    }

    *z = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);

    return 0;
}

// Cleanup resources
void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    // Register signal handler for Ctrl+C
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    // Initialize SPI
    if (spi_init() < 0) {
        return 1;
    }

    // Initialize libgpiod for CS line
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE);
    if (!cs_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", CS_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "adis16266_cs", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize ADIS16266 sensor
    if (adis16266_init() < 0) {
        fprintf(stderr, "ADIS16266 initialization failed\n");
        cleanup();
        return 1;
    }

    printf("ADIS16266 initialized. Reading gyroscope data...\n");

    // Main loop
    while (keep_running) {
        int16_t x, y, z;

        if (adis16266_read_gyro(&x, &y, &z) == 0) {
            // Convert raw data to angular rates (deg/sec/LSB)
            float x_rate = (float)x * 0.02f;
            float y_rate = (float)y * 0.02f;
            float z_rate = (float)z * 0.02f;

            // Print the data to the console
            printf("X: %.2f deg/sec, Y: %.2f deg/sec, Z: %.2f deg/sec\n", x_rate, y_rate, z_rate);
        } else {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
        }

        usleep(100000); // 100 ms delay
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

