/*
 * LSM6DSR accel/gyro reader for Raspberry Pi 3 Model B+
 * Uses pigpio C API (no wiringPi).
 *
 * Wiring:
 *   LSM6DSR SDA -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   LSM6DSR SCL -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   LSM6DSR VDD -> 3.3 V
 *   LSM6DSR GND -> GND
 *
 * Build:  gcc -O2 -Wall -o lsm6dsr_reader lsm6dsr_reader.c -lpigpio -lrt
 * Run:    sudo ./lsm6dsr_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- LSM6DSR constants ---- */
#define LSM6DSR_ADDR          0x6B
#define WHO_AM_I_REG         0x0F
#define WHO_AM_I_VAL         0x6B

#define CTRL1_XL             0x10
#define CTRL2_G              0x11
#define OUTX_L_G             0x22
#define OUTX_L_XL            0x28

#define ACCEL_SENSITIVITY    0.000061f   /* g/LSB  -> 0.061 mg/LSB */
#define GYRO_SENSITIVITY     0.00875f    /* dps/LSB -> 0.00875 mdps/LSB */

/* ---- Globals for cleanup ---- */
static int  i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register; returns 0 on success, -1 on error.    */
static int reg_write(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read N bytes starting at `reg` and store them in `buf`.          */
/* Returns 0 on success, -1 on error.                                */
static int reg_read_burst(uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: got %d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Verify sensor identity.                                            */
static int verify_sensor(void)
{
    int who = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who < 0) {
        fprintf(stderr, "[ERROR] Cannot read WHO_AM_I register: %d\n", who);
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "[ERROR] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }
    printf("LSM6DSR detected (WHO_AM_I = 0x%02X)\n", who);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure accelerometer: 104 Hz, +/-2g.                            */
static int configure_accelerometer(void)
{
    /* CTRL1_XL: ODR=104 Hz (0x42), FS=+/-2g (0x00) -> 0x42 */
    if (reg_write(CTRL1_XL, 0x42) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure gyroscope: 104 Hz, +/-250 dps.                            */
static int configure_gyroscope(void)
{
    /* CTRL2_G: ODR=104 Hz (0x42), FS=+/-250 dps (0x00) -> 0x42 */
    if (reg_write(CTRL2_G, 0x42) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one burst of 12 bytes: GX_L, GX_H, GY_L, GY_H, GZ_L, GZ_H, XL_L,   */
/* XL_H, YL_L, YL_H, ZL_L, ZL_H.  Returns 0 on success, -1 on error.    */
static int read_sensor_data(float *gx, float *gy, float *gz,
                            float *ax, float *ay, float *az)
{
    uint8_t buf[12];

    if (reg_read_burst(OUTX_L_G, buf, sizeof(buf)) < 0)
        return -1;

    int16_t gx_raw = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t gy_raw = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t gz_raw = (int16_t)((buf[5] << 8) | buf[4]);
    int16_t ax_raw = (int16_t)((buf[7] << 8) | buf[6]);
    int16_t ay_raw = (int16_t)((buf[9] << 8) | buf[8]);
    int16_t az_raw = (int16_t)((buf[11] << 8) | buf[10]);

    *gx = (float)gx_raw * GYRO_SENSITIVITY;
    *gy = (float)gy_raw * GYRO_SENSITIVITY;
    *gz = (float)gz_raw * GYRO_SENSITIVITY;
    *ax = (float)ax_raw * ACCEL_SENSITIVITY;
    *ay = (float)ay_raw * ACCEL_SENSITIVITY;
    *az = (float)az_raw * ACCEL_SENSITIVITY;

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at LSM6DSR address --- */
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                LSM6DSR_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Verify sensor identity --- */
    if (verify_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure sensor --- */
    if (configure_accelerometer() < 0 || configure_gyroscope() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("LSM6DSR data acquisition started. Press Ctrl+C to stop.\n");

    /* --- Main acquisition loop --- */
    while (!terminate) {
        float gx, gy, gz, ax, ay, az;

        if (read_sensor_data(&gx, &gy, &gz, &ax, &ay, &az) == 0) {
            printf("G: X=%.3f Y=%.3f Z=%.3f  |  A: X=%.3f Y=%.3f Z=%.3f\n",
                   gx, gy, gz, ax, ay, az);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; continuing.\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

