#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* FXOS8700 I2C address (SA0 tied to GND) */
#define FXOS8700_ADDR 0x1D

/* FXOS8700 register addresses */
#define FXOS8700_WHO_AM_I 0x0D
#define FXOS8700_WHO_AM_I_VAL 0xC7
#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_CTRL_REG2 0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB 0x01

/* Expected accelerometer and magnetometer data length */
#define FXOS8700_DATA_LEN 12

/* Global I2C handle for cleanup */
static int i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

/* Initialize the FXOS8700 sensor */
static int init_fxos8700(int handle) {
    int status;

    /* Verify sensor identity */
    status = i2cReadByteData(handle, FXOS8700_WHO_AM_I);
    if (status < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", status);
        return -1;
    }
    if (status != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                status, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Configure accelerometer: hybrid mode, 400 Hz ODR, normal power */
    status = i2cWriteByteData(handle, FXOS8700_CTRL_REG1, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing CTRL_REG1: %d\n", status);
        return -1;
    }

    /* Configure magnetometer: hybrid mode, 80 Hz ODR, normal power */
    status = i2cWriteByteData(handle, FXOS8700_M_CTRL_REG1, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing M_CTRL_REG1: %d\n", status);
        return -1;
    }

    /* Enable accelerometer and magnetometer */
    status = i2cWriteByteData(handle, FXOS8700_CTRL_REG2, 0x0C);
    if (status < 0) {
        fprintf(stderr, "Error writing CTRL_REG2: %d\n", status);
        return -1;
    }

    return 0;
}

/* Read 12 bytes of accelerometer and magnetometer data */
static int read_fxos8700_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                             int16_t *mx, int16_t *my, int16_t *mz) {
    char buffer[FXOS8700_DATA_LEN];
    int status;

    /* Read 12 bytes starting from OUT_X_MSB (0x01) */
    status = i2cReadI2CBlockData(handle, FXOS8700_OUT_X_MSB, buffer, FXOS8700_DATA_LEN);
    if (status != FXOS8700_DATA_LEN) {
