#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37
#define ADXL345_REG_THRESH_TILT 0x28
#define ADXL345_REG_TIME_INACT 0x27
#define ADXL345_REG_ACT_INACT_CTL 0x2A
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_MAP 0x2F
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_FILTER 0x2C
#define ADXL345_REG_FIFO_CTL 0x38
#define ADXL345_REG_FIFO_STATUS 0x39
#define ADXL345_REG_FIFO_DATA 0x3A
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_POWER_CTL_VAL 0x08
#define ADXL345_REG_INT_ENABLE_VAL 0x02
#define ADXL345_REG_INT_MAP_VAL 0x00
#define ADXL345_REG_INT_SOURCE_VAL 0x00
#define ADXL345_REG_FILTER_VAL 0x00
#define ADXL345_REG_FIFO_CTL_VAL 0x00
#define ADXL345_REG_FIFO_STATUS_VAL 0x00
#define ADXL345_REG_FIFO_DATA_VAL 0x00
#define ADXL345_REG_BW_RATE_VAL 0x0A
#define ADXL345_REG_THRESH_TILT_VAL 0x00
#define ADXL345_REG_TIME_INACT_VAL 0x00
#define ADXL345_REG_ACT_INACT_CTL_VAL 0x00
#define ADXL345_DEVID_EXPECTED 0xE5
#define I2C_DEVICE "/dev/i2c-1"
#define LOG_FILE "/var/log/tilt_events.log"
#define TILT_THRESHOLD 30.0
#define SAMPLE_INTERVAL_MS 100

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int i2c_write_byte(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "Error reading %zu bytes from I2C register 0x%02X: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int adxl345_init(void) {
    uint8_t devid;
    if (i2c_read_bytes(ADXL345_REG_DEVID, &devid, 1) != 0) {
        fprintf(stderr, "Failed to read DEVID register\n");
        return -1;
    }
    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "Unexpected DEVID: 0x%02X (expected 0x%02X). Sensor not present?\n", devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    if (i2c_write_byte(ADXL345_REG_POWER_CTL, ADXL345_REG_POWER_CTL_VAL) != 0) return -1;
    if (i2c_write_byte(ADXL345_REG_INT_ENABLE, ADXL345_REG_INT_ENABLE_VAL) != 0) return -1;
    if (i2c_write_byte(ADXL345_REG_INT_MAP, ADXL345_REG_INT_MAP_VAL) != 0) return -1;
    if (i2c_write_byte(ADXL345_REG_INT_SOURCE, ADXL345_REG_INT_SOURCE_VAL) != 0) return -1;
    if (i2c_write_byte(ADXL345_REG_FILTER, ADXL345_REG_FILTER_VAL) != 0) return -1;
    if (i2c_write_byte(ADXL345_REG_FIFO_CTL, ADXL345_REG_FIFO_CTL_VAL) != 0) return -1;
    if (i2c_write_byte(ADXL345_REG_FIFO_STATUS, ADXL345_REG_FIFO_STATUS_VAL) != 0) return -1;
    if (i2c_write_byte(ADXL345_REG_FIFO_DATA, ADXL345_REG_FIFO_DATA_VAL) != 0) return -1;
    if (i2c_write_byte(ADXL345_REG_BW_RATE, ADXL345_REG_BW_RATE_VAL) != 0) return -1;
    if (i2c_write_byte(ADXL345_REG_THRESH_TILT, ADXL345_REG_THRESH_TILT_VAL) != 0) return -1;
    if (i2c_write_byte(ADXL345_REG_TIME_INACT, ADXL345_REG_TIME_INACT_VAL) != 0) return -1;
    if (i2c_write_byte(ADXL345_REG_ACT_INACT_CTL, ADXL345_REG_ACT_INACT_CTL_VAL) != 0) return -1;

    return 0;
}

static int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_bytes(ADXL345_REG_DATAX0, buf, 6) != 0) {
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static double calculate_tilt_angle(int16_t x, int16_t y) {
    double angle = atan2((double)y, (double)x) * 180.0 / M_PI;
    if (angle < 0) {
        angle += 360.0;
    }
    return angle;
}

static void log_tilt_event(double tilt_angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Tilt angle: %.2f degrees\n", timestamp, tilt_angle);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (adxl345_init() != 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("ADXL345 tilt monitor started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int16_t x, y, z;
        if (read_accelerometer_data(&x, &y, &z) == 0) {
            double tilt_angle = calculate_tilt_angle(x, y);
            if (tilt_angle > TILT_THRESHOLD) {
                log_tilt_event(tilt_angle);
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data. Retrying...\n");
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

