#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_GPIO 17
#define SAMPLE_INTERVAL_US 1000   /* 1 ms */
#define WINDOW_DURATION_S 5       /* 5 seconds */
#define POLL_DELAY_US 1000000     /* 1 second between windows */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-up so the pin reads HIGH when no sound is present */
    if (gpioSetPullUpDown(SOUND_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO%d.\n", SOUND_SENSOR_GPIO);
    }

    return 0;
}

static int read_sound_sensor(void)
{
    return gpioRead(SOUND_SENSOR_GPIO);
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return;
    }

    printf("[%s] ", timestamp);
}

int main(int argc, char *argv[])
{
    int threshold;
    int high_count;
    int exit_code = EXIT_SUCCESS;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        fprintf(stderr, "  threshold: minimum number of high readings per 5-second window\n");
        fprintf(stderr, "            required to trigger an alert (must be a positive integer)\n");
        return EXIT_FAILURE;
    }

    threshold = atoi(argv[1]);
    if (threshold <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer.\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT)");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-038 sound sensor on GPIO%d. Threshold: %d high readings per 5 s.\n",
           SOUND_SENSOR_GPIO, threshold);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        high_count = 0;

        for (int i = 0; i < WINDOW_DURATION_S * 10 && g_running; i++) {
            int value = read_sound_sensor();
            if (value < 0) {
                fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", SOUND_SENSOR_GPIO);
                exit_code = EXIT_FAILURE;
                goto cleanup;
            }
            if (value == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        print_timestamp();

        if (high_count > threshold) {
            printf("ALERT: %d high readings in %d s (threshold: %d)\n",
                   high_count, WINDOW_DURATION_S, threshold);
        } else {
            printf("Status: %d high readings in %d s\n",
                   high_count, WINDOW_DURATION_S);
        }
        fflush(stdout);

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < POLL_DELAY_US / SAMPLE_INTERVAL_US && g_running; i++) {
            gpioDelay(SAMPLE_INTERVAL_US);
        }
    }

cleanup:
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return exit_code;
}

