#define BH1750_ADDR 0x23
#define BH1750_ONE_TIME_HIGH_RES_MODE_2 0x21
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "light_log.txt"
#define CONVERSION_TIME_MS 180
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int read_bh1750(int fd, float *lux) {
    uint8_t cmd = BH1750_ONE_TIME_HIGH_RES_MODE_2;
    if (i2c_write_byte(fd, cmd) < 0) {
        return -1;
    }

    usleep(CONVERSION_TIME_MS * 1000);

    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) {
        return -1;
    }

    uint16_t raw = (buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

int log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
