static int read_touch_data(int handle, int *touch_data) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, 0x00, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    touch_data[0] = (buf[1] << 8) | buf[0];
    return 0;
}

static float map_touch_data_to_frequency(int touch_data) {
    float normalized = (float)touch_data / 1023.0f;
    float frequency = MIN_FREQUENCY + normalized * (MAX_FREQUENCY - MIN_FREQUENCY);
    return frequency;
}

static void play_tone(float frequency) {
    if (frequency <= 0.0f) return;
    int period_us = 1000000 / (int)frequency;
    gpioPWM(PWM_GPIO, 128);
    gpioDelay(period_us);
    gpioPWM(PWM_GPIO, 0);
    gpioDelay(period_us);
}

static void log_frequency(float frequency) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f\n", s, frequency);
    fclose(fp);
}

static void handle_client(int client_fd) {
    char buffer[1024];
    ssize_t bytes_read = read(client_fd, buffer, sizeof(buffer) - 1);
    if (bytes_read > 0) {
        buffer[bytes_read] = '\0';
        printf("Received: %s\n", buffer);
        if (strncmp(buffer, "MOTION_DETECTED:", 16) == 0) {
            char *secret = strstr(buffer, "MySecretKey");
            if (secret) {
                int touch_data[2];
                if (read_touch_data(i2c_handle, touch_data) == 0) {
                    float frequency = map_touch_data_to_frequency(touch_data[0]);
                    printf("Touch detected: %d, Frequency: %.2f Hz\n", touch_data[0], frequency);
                    play_tone(frequency);
                    log_frequency(frequency);
                } else {
                    fprintf(stderr, "Failed to read touch data\n");
                }
            } else {
                fprintf(stderr, "Missing shared secret\n");
            }
        }
    } else if (bytes_read == 0) {
        printf("Client disconnected\n");
    } else {
        fprintf(stderr, "Error reading from client: %s\n", strerror(errno));
    }
    close(client_fd);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_handle) != 0) {
        fprintf(stderr, "Failed to initialize MPR121\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, 1000);
    gpioPWM(PWM_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        fprintf(stderr, "Socket creation failed: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt)) < 0) {
        fprintf(stderr, "setsockopt failed: %s\n", strerror(errno));
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        fprintf(stderr, "Bind failed: %s\n", strerror(errno));
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        fprintf(stderr, "Listen failed: %s\n", strerror(errno));
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

