// LSM303DLHC I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC register addresses
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08

// GPIO pin for LED (BCM numbering)
#define LED_PIN 17

// I2C bus device path
#define I2C_DEVICE "/dev/i2c-1"

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// PWM range (0-255)
#define PWM_RANGE 255

// Global variables for cleanup
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(void);
int init_magnetometer(void);
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
