void set_led_brightness(float magnitude);
void cleanup(void);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup function to release resources
void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0); // Turn off LED
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

// Initialize I2C interface
int init_i2c(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", LSM303_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize magnetometer
int init_magnetometer(void) {
    // Configure magnetometer: 10 Hz continuous conversion, high performance mode
    uint8_t config = 0x18; // 0x18 = 10 Hz, high performance mode
    if (write(i2c_fd, &config, 1) != 1) {
        fprintf(stderr, "Error writing to CTRL_REG1_M: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read magnetometer data from I2C block
