#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 500000
#define WINDOW_SIZE 100

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_magnetometer(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_msb, x_lsb, z_msb, z_lsb, y_msb, y_lsb;
    if (read_register(handle, HMC5883L_DATA_X_MSB, &x_msb) < 0) return -1;
    if (read_register(handle, HMC5883L_DATA_X_LSB, &x_lsb) < 0) return -1;
    if (read_register(handle, HMC5883L_DATA_Z_MSB, &z_msb) < 0) return -1;
    if (read_register(handle, HMC5883L_DATA_Z_LSB, &z_lsb) < 0) return -1;
    if (read_register(handle, HMC5883L_DATA_Y_MSB, &y_msb) < 0) return -1;
    if (read_register(handle, HMC5883L_DATA_Y_LSB, &y_lsb) < 0) return -1;
    *x = (int16_t)((x_msb << 8) | x_lsb);
    *z = (int16_t)((z_msb << 8) | z_lsb);
    *y = (int16_t)((y_msb << 8) | y_lsb);
    return 0;
}

static void calculate_offsets(int16_t *x_data, int16_t *y_data, int16_t *z_data,
                              int num_samples, float *x_offset, float *y_offset, float *z_offset) {
    float x_sum = 0.0f, y_sum = 0.0f, z_sum = 0.0f;
    for (int i = 0; i < num_samples; i++) {
        x_sum += x_data[i];
        y_sum += y_data[i];
        z_sum += z_data[i];
    }
    *x_offset = x_sum / num_samples;
    *y_offset = y_sum / num_samples;
    *z_offset = z_sum / num_samples;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", HMC5883L_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_register(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (write_register(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (write_register(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int16_t x_data[WINDOW_SIZE], y_data[WINDOW_SIZE], z_data[WINDOW_SIZE];
    int data_index = 0;
    float x_offset = 0.0f, y_offset = 0.0f, z_offset = 0.0f;

    while (running) {
        int16_t x, y, z;
        if (read_magnetometer(i2c_handle, &x, &y, &z) == 0) {
            x_data[data_index] = x;
            y_data[data_index] = y;
            z_data[data_index] = z;
            data_index = (data_index + 1) % WINDOW_SIZE;
            if (data_index == 0) {
                calculate_offsets(x_data, y_data, z_data, WINDOW_SIZE, &x_offset, &y_offset, &z_offset);
            }
            float x_corrected = (float)x - x_offset;
            float y_corrected = (float)y - y_offset;
            float z_corrected = (float)z - z_offset;
            printf("X: %.2f, Y: %.2f, Z: %.2f\n", x_corrected, y_corrected, z_corrected);
        } else {
            fprintf(stderr, "Error reading magnetometer data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

