/*
 * LSM303D accelerometer monitor with libgpiod interrupt and circular buffer.
 *
 * Wiring:
 *   LSM303D SDA -> GPIO2 (pin 3, physical pin 5)
 *   LSM303D SCL -> GPIO3 (pin 5, physical pin 3)
 *   LSM303D VDD -> 3.3 V
 *   LSM303D GND -> GND
 *   LSM303D SA0 -> GND (I2C address 0x1D)
 *   INT1 -> GPIO23 (pin 16, physical pin 12)
 *
 * Build: gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- LSM303D constants ---- */
#define LSM303D_ADDR          0x1D
#define WHO_AM_I_REG          0x0F
#define WHO_AM_I_VAL          0x49
#define CTRL_REG1_A          0x20
#define CTRL_REG4_A          0x23
#define INT1_CFG             0x30
#define OUT_X_L_A            0x28
#define OUT_X_H_A            0x29
#define OUT_Y_L_A            0x2A
#define OUT_Y_H_A            0x2B
#define OUT_Z_L_A            0x2C
#define OUT_Z_H_A            0x2D

/* ---- GPIO / interrupt constants ---- */
#define GPIO_CHIP_NAME        "gpiochip0"
#define INT1_LINE_OFFSET      23          /* BCM pin 23 */
#define INT1_LINE_CONSUMER    "lsm303d-int1"

/* ---- Circular buffer ---- */
#define BUFFER_SIZE           64
#define SAMPLE_INTERVAL_US   10000       /* 10 ms */

typedef struct {
    int16_t x, y, z;
} accel_sample_t;

typedef struct {
    accel_sample_t buf[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals ---- */
