static int  init_lsm303d(void);
static int  read_accel(int16_t *x, int16_t *y, int16_t *z);
static void add_to_buffer(circular_buffer_t *cb, int16_t x, int16_t y, int16_t z);
static void dump_buffer(const circular_buffer_t *cb);
static void int1_handler(void *ctx);
static void cleanup(void);
static void signal_handler(int sig);

