    return 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    if (i2c_smbus_write_byte_data(fd, reg, val) < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (i2c_smbus_read_i2c_block_data(fd, reg, (char *)buf, len) < 0) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, len %zu): %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_lsm303d(void)
{
    uint8_t whoami = 0;

    if (i2c_read_byte(g_i2c_fd, WHO_AM_I_REG, &whoami) < 0)
        return -1;
    if (whoami != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, WHO_AM_I_VAL);
        return -1;
    }

