               i, cb->buf[idx].x, cb->buf[idx].y, cb->buf[idx].z);
    }
    printf("--------------------------\n\n");
}

static void int1_handler(void *ctx)
{
    (void)ctx;
    printf("INT1 interrupt received — dumping last %d samples\n", g_buf.count);
    dump_buffer(&g_buf);
