        (void)i2c_write_byte(g_i2c_fd, CTRL_REG1_A, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

