        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(g_int1_line, INT1_LINE_CONSUMER) < 0) {
        fprintf(stderr, "Cannot request rising edge events on GPIO %d: %s\n",
