#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define CONSUMER_NAME "solenoid-control"
#define DELAY_MS 500

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig)
{
    (void)sig;
    keep_running = 0;
}

static int set_line(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting line value to %d: %s\n",
                value, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sol1 = NULL;
    struct gpiod_line *sol2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the lines for both solenoids */
    sol1 = gpiod_chip_get_line(chip, SOLENOID_1_PIN);
    if (!sol1) {
        fprintf(stderr, "Failed to get line %d: %s\n",
                SOLENOID_1_PIN, strerror(errno));
        goto cleanup;
    }

    sol2 = gpiod_chip_get_line(chip, SOLENOID_2_PIN);
    if (!sol2) {
        fprintf(stderr, "Failed to get line %d: %s\n",
                SOLENOID_2_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW (no solenoid energized) */
    if (gpiod_line_request_output(sol1, CONSUMER_NAME, 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                SOLENOID_1_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(sol2, CONSUMER_NAME, 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                SOLENOID_2_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Solenoid control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        /* Energize solenoid 1 for 500 ms */
        if (set_line(sol1, 1) < 0) {
            goto cleanup;
        }
        printf("Solenoid 1 energized\n");

        struct timespec ts = {
            .tv_sec = DELAY_MS / 1000,
            .tv_nsec = (long)(DELAY_MS % 1000) * 1000000L
        };
        while (nanosleep(&ts, &ts) < 0 && errno == EINTR && keep_running) {
            /* Retry if interrupted by signal */
        }
        if (!keep_running) {
            break;
        }

        /* De-energize solenoid 1 */
        if (set_line(sol1, 0) < 0) {
            goto cleanup;
        }
        printf("Solenoid 1 de-energized\n");

        /* Energize solenoid 2 for 500 ms */
        if (set_line(sol2, 1) < 0) {
            goto cleanup;
        }
        printf("Solenoid 2 energized\n");

        while (nanosleep(&ts, &ts) < 0 && errno == EINTR && keep_running) {
            /* Retry if interrupted by signal */
        }
        if (!keep_running) {
            break;
        }

        /* De-energize solenoid 2 */
        if (set_line(sol2, 0) < 0) {
            goto cleanup;
        }
        printf("Solenoid 2 de-energized\n");
    }

    printf("\nShutting down cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure both lines are LOW before releasing */
    if (sol1) {
        gpiod_line_set_value(sol1, 0);
        gpiod_line_release(sol1);
    }
    if (sol2) {
        gpiod_line_set_value(sol2, 0);
        gpiod_line_release(sol2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

