#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define CODE_LENGTH 6
#define EXPECTED_CODE "123456"
#define TIMEOUT_SEC 5
#define UNLOCK_DURATION_SEC 2
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int uart_fd1 = -1;
static int uart_fd2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    if (gpioSetMode(LOCK1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LOCK1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LOCK2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LOCK2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LOCK1_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d LOW.\n", LOCK1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d LOW.\n", LOCK2_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_uart(const char *device, int baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error: tcgetattr failed on %s: %s\n", device, strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = TIMEOUT_SEC;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error: tcsetattr failed on %s: %s\n", device, strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_code(int fd, char *code, size_t len) {
    size_t total = 0;
    time_t start = time(NULL);

    while (total < len && running) {
        char buf[256];
        ssize_t n = read(fd, buf, sizeof(buf) - 1);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                if (time(NULL) - start >= TIMEOUT_SEC) {
                    fprintf(stderr, "Error: timeout waiting for code on %d.\n", fd);
                    return -1;
                }
                usleep(POLL_DELAY_US);
                continue;
            }
            fprintf(stderr, "Error: read failed on %d: %s\n", fd, strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "Error: serial port closed on %d.\n", fd);
            return -1;
        }

        for (ssize_t i = 0; i < n; i++) {
            char c = buf[i];
            if (c >= '0' && c <= '9') {
                code[total++] = c;
            } else if (c == '\r' || c == '\n') {
                code[total] = '\0';
                return 0;
            } else {
                code[total++] = '\0';
                tcflush(fd, TCIOFLUSH);
                start = time(NULL);
            }
        }
    }

    return -1;
}

static int compare_codes(const char *code1, const char *code2) {
    if (strlen(code1) != CODE_LENGTH || strlen(code2) != CODE_LENGTH) {
        return -1;
    }
    for (int i = 0; i < CODE_LENGTH; i++) {
        if (code1[i] != code2[i]) {
            return -1;
        }
    }
    return 0;
}

static int unlock_doors(void) {
    if (gpioWrite(LOCK1_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to unlock GPIO%d.\n", LOCK1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to unlock GPIO%d.\n", LOCK2_GPIO);
        gpioWrite(LOCK1_GPIO, 0);
        return -1;
    }
    printf("Doors unlocked.\n");
    return 0;
}

static int lock_doors(void) {
    if (gpioWrite(LOCK1_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to lock GPIO%d.\n", LOCK1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to lock GPIO%d.\n", LOCK2_GPIO);
        gpioWrite(LOCK1_GPIO, 1);
        return -1;
    }
    printf("Doors locked.\n");
    return 0;
}

static void cleanup(void) {
    lock_doors();
    if (uart_fd1 >= 0) {
        close(uart_fd1);
        uart_fd1 = -1;
    }
    if (uart_fd2 >= 0) {
        close(uart_fd2);
        uart_fd2 = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    uart_fd1 = init_uart("/dev/serial0", B9600);
    if (uart_fd1 < 0) {
        gpioTerminate();
        return 1;
    }

    uart_fd2 = init_uart("/dev/serial1", B9600);
    if (uart_fd2 < 0) {
        close(uart_fd1);
        gpioTerminate();
        return 1;
    }

    printf("Dual-factor authentication system started. Press Ctrl+C to exit.\n");

    while (running) {
        char code1[CODE_LENGTH + 1];
        char code2[CODE_LENGTH + 1];

        printf("Enter code for Lock 1 (6 digits): ");
        fflush(stdout);
        if (read_code(uart_fd1, code1, sizeof(code1)) != 0) {
            fprintf(stderr, "Error: code read failed for Lock 1.\n");
            continue;
        }

        printf("Enter code for Lock 2 (6 digits): ");
        fflush(stdout);
        if (read_code(uart_fd2, code2, sizeof(code2)) != 0) {
            fprintf(stderr, "Error: code read failed for Lock 2.\n");
            continue;
        }

        if (compare_codes(code1, code2) == 0) {
            printf("Codes match. Unlocking doors...\n");
            if (unlock_doors() != 0) {
                fprintf(stderr, "Error: failed to unlock doors.\n");
            } else {
                sleep(UNLOCK_DURATION_SEC);
                if (lock_doors() != 0) {
                    fprintf(stderr, "Error: failed to lock doors.\n");
                }
            }
        } else {
            printf("Codes do not match. Doors locked.\n");
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

