#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <syslog.h>
#include <time.h>
#include <gpiod.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define CHIP_NAME "gpiochip0"
#define STRIKE_DURATION_MS 1000
#define POLL_INTERVAL_MS 50
#define MOTION_TIMEOUT_SEC 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register SIGINT handler: %s", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %s", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip %s: %s", CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR line %d: %s", PIR_PIN, strerror(errno));
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get relay line %d: %s", RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(pir_line, "door_strike") < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, "door_strike", 0) < 0) {
        syslog(LOG_ERR, "Failed to request relay line as output: %s", strerror(errno));
        goto cleanup;
    }

    log_message(LOG_INFO, "Door strike system started. Monitoring PIR on GPIO4, relay on GPIO17.");

    int relay_state = 0;
    time_t last_motion_time = 0;
    int pir_high_count = 0;

    while (running) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            syslog(LOG_ERR, "Failed to read PIR value: %s", strerror(errno));
            break;
        }

        if (pir_value == 1) {
            time_t current_time = time(NULL);
            if (current_time - last_motion_time >= MOTION_TIMEOUT_SEC) {
                log_message(LOG_WARNING, "PIR sensor remains HIGH for more than 10 seconds. Failsafe triggered.");
                if (relay_state == 1) {
                    if (gpiod_line_set_value(relay_line, 0) < 0) {
                        syslog(LOG_ERR, "Failed to de-energize relay: %s", strerror(errno));
                    } else {
                        relay_state = 0;
                        log_message(LOG_INFO, "Relay de-energized due to failsafe.");
                    }
                }
                pir_high_count = 0;
            } else {
                pir_high_count++;
                if (pir_high_count >= 100) {
                    log_message(LOG_WARNING, "PIR sensor remains HIGH for 100 consecutive readings. Failsafe triggered.");
                    if (relay_state == 1) {
                        if (gpiod_line_set_value(relay_line, 0) < 0) {
                            syslog(LOG_ERR, "Failed to de-energize relay: %s", strerror(errno));
                        } else {
                            relay_state = 0;
                            log_message(LOG_INFO, "Relay de-energized due to failsafe.");
                        }
                    }
                    pir_high_count = 0;
                }
            }
            last_motion_time = current_time;
        } else {
            pir_high_count = 0;
        }

        if (relay_state == 1) {
            if (gpiod_line_set_value(relay_line, 0) < 0) {
                syslog(LOG_ERR, "Failed to de-energize relay: %s", strerror(errno));
            } else {
                relay_state = 0;
                log_message(LOG_INFO, "Relay de-energized.");
            }
        }

