#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_1_PIN 4
#define RELAY_2_PIN 17
#define RELAY_3_PIN 27
#define RELAY_4_PIN 22

#define RELAY_COUNT 4
#define RELAY_ACTIVATION_DURATION 300  /* seconds */
#define PAUSE_DURATION 60            /* seconds */
#define TIMER_INTERVAL 60            /* seconds */

static const int relay_pins[RELAY_COUNT] = {RELAY_1_PIN, RELAY_2_PIN, RELAY_3_PIN, RELAY_4_PIN};

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t timer_triggered = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

static void deactivate_all_relays(void) {
    for (int i = 0; i < RELAY_COUNT; i++) {
        if (gpioWrite(relay_pins[i], 1) != 0) {
            syslog(LOG_ERR, "Failed to deactivate relay on GPIO %d", relay_pins[i]);
        }
    }
}

static void timer_callback(void *user_data) {
    (void)user_data;
    timer_triggered = 1;
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register signal handler");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    deactivate_all_relays();

    for (int i = 0; i < RELAY_COUNT; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            syslog(LOG_ERR, "Failed to set GPIO %d as output", relay_pins[i]);
            deactivate_all_relays();
            gpioTerminate();
            closelog();
            return EXIT_FAILURE;
        }
        if (gpioWrite(relay_pins[i], 1) != 0) {
            syslog(LOG_ERR, "Failed to initialise GPIO %d to HIGH", relay_pins[i]);
            deactivate_all_relays();
            gpioTerminate();
            closelog();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set timer function");
        deactivate_all_relays();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    log_event("Irrigation system started");

    while (running) {
        if (timer_triggered) {
            timer_triggered = 0;

            static int relay_index = 0;
            static int action_type = 0;  /* 0 = activation, 1 = deactivation, 2 = pause */

            if (action_type == 0) {
                if (gpioWrite(relay_pins[relay_index], 0) == 0) {
                    log_event("Relay activated");
                    action_type = 1;
                } else {
                    syslog(LOG_ERR, "Failed to activate relay on GPIO %d", relay_pins[relay_index]);
                }
            } else if (action_type == 1) {
                if (gpioWrite(relay_pins[relay_index], 1) == 0) {
                    log_event("Relay deactivated");
                    action_type = 2;
                } else {
                    syslog(LOG_ERR, "Failed to deactivate relay on GPIO %d", relay_pins[relay_index]);
                }
            } else if (action_type == 2) {
                if (relay_index < RELAY_COUNT - 1) {
                    relay_index++;
                } else {
                    relay_index = 0;
                }
                action_type = 0;
            }

            /* Pause for the remainder of the current activation duration */
            for (int i = 0; i < RELAY_ACTIVATION_DURATION && running; i++) {
                sleep(1);
            }
        }
        sleep(1);
    }

    deactivate_all_relays();
    gpioTerminate();
    log_event("Irrigation system stopped");
    closelog();
    return EXIT_SUCCESS;
}

