#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define ACCEL_SCALE 16384.0f
#define BUFFER_SIZE 100
#define SAMPLE_PERIOD_NS 100000000L

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *sysfs_file = NULL;
static char sysfs_path[256];
static struct timespec timer_ts;
static float accel_buffer[BUFFER_SIZE][3];
static int buffer_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg(fd, ACCEL_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_accel(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_regs(fd, ACCEL_XOUT_H, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    *x = (float)raw_x / ACCEL_SCALE;
    *y = (float)raw_y / ACCEL_SCALE;
    *z = (float)raw_z / ACCEL_SCALE;
    return 0;
}

static void timer_handler(int sig, siginfo_t *si, void *uc) {
    (void)sig;
    (void)si;
    (void)uc;
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    long elapsed_ns = (now.tv_sec - timer_ts.tv_sec) * 1000000000L + (now.tv_nsec - timer_ts.tv_nsec);
    if (elapsed_ns >= SAMPLE_PERIOD_NS) {
        timer_ts = now;
        float x, y, z;
        if (read_accel(i2c_fd, &x, &y, &z) == 0) {
            accel_buffer[buffer_index][0] = x;
            accel_buffer[buffer_index][1] = y;
            accel_buffer[buffer_index][2] = z;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        }
    }
}

static int init_sysfs(void) {
    snprintf(sysfs_path, sizeof(sysfs_path), "/sys/kernel/mpu6050_accel/latest");
    sysfs_file = fopen(sysfs_path, "r");
    if (!sysfs_file) {
        fprintf(stderr, "Failed to open sysfs file %s: %s\n", sysfs_path, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sysfs(float *x, float *y, float *z) {
    char buf[128];
    if (!sysfs_file) return -1;
    if (!fgets(buf, sizeof(buf), sysfs_file)) {
        fprintf(stderr, "Failed to read sysfs data: %s\n", strerror(errno));
        return -1;
    }
    if (sscanf(buf, "%f %f %f", x, y, z) != 3) {
        fprintf(stderr, "Failed to parse sysfs data\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (sysfs_file) {
        fclose(sysfs_file);
        sysfs_file = NULL;
    }
    if (sysfs_path[0] != '\0') {
        unlink(sysfs_path);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050\n");
        cleanup();
        return 1;
    }

    if (init_sysfs() < 0) {
        cleanup();
        return 1;
    }

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    sev.sigev_value.sival_ptr = &timer_ts;

    if (timer_create(CLOCK_MONOTONIC, &sev, &timer_ts) < 0) {
        fprintf(stderr, "Failed to create timer: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("MPU6050 initialized. Reading at 100 Hz. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;
        if (read_sysfs(&x, &y, &z) == 0) {
            printf("Sysfs: X=%.2f g, Y=%.2f g, Z=%.2f g\n", x, y, z);
        } else {
            printf("Sysfs read failed\n");
        }
        usleep(10000);
    }

    printf("\nShutting down...\n");
    timer_delete(timer_ts.sigev_signo);
    cleanup();
    return 0;
}

