#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_LIGHTS 4
#define CHIP_NAME "gpiochip0"
#define CONSUMER "smart-lighting"

static const unsigned int light_pins[NUM_LIGHTS] = {18, 23, 24, 25};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_LIGHTS];
static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    for (int i = 0; i < NUM_LIGHTS; i++) {
        lines[i] = gpiod_chip_get_line(chip, light_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", light_pins[i]);
            return -1;
        }

        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", light_pins[i]);
            return -1;
        }
    }

    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_LIGHTS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int toggle_light(int index) {
    int val = gpiod_line_get_value(lines[index]);
    if (val < 0) {
        perror("Failed to read GPIO value");
        return -1;
    }

    if (gpiod_line_set_value(lines[index], val ? 0 : 1) < 0) {
        perror("Failed to write GPIO value");
        return -1;
    }

    return 0;
}

static int calculate_interval_seconds(int index) {
    switch (index) {
        case 0: return 2;
        case 1: return 3;
        case 2: return 5;
        case 3: return 7;
        default: return -1;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        for (int i = 0; i < NUM_LIGHTS && keep_running; i++) {
            int interval = calculate_interval_seconds(i);
            if (interval < 0) {
                fprintf(stderr, "Invalid interval for light %d\n", i);
                continue;
            }

            struct timespec ts;
            ts.tv_sec = interval;
            ts.tv_nsec = 0;

            while (nanosleep(&ts, &ts) < 0 && errno == EINTR && keep_running) {
                // Interrupted by signal, check keep_running
            }

            if (!keep_running) {
                break;
            }

            if (toggle_light(i) < 0) {
                fprintf(stderr, "Failed to toggle light %d\n", i);
                break;
            }
        }
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

