#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define WHO_AM_I     0x75
#define GYRO_XOUT_H  0x43

// Gyroscope sensitivity for default +-250 dps range
#define GYRO_SENSITIVITY 131.0f

// Threshold for angular velocity (degrees/second)
#define ANGULAR_VELOCITY_THRESHOLD 50.0f

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Structure to hold circular buffer data
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_fd = -1;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg, uint8_t *value);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int read_gyro_data(int fd, gyro_data_t *data);
void add_to_circular_buffer(circular_buffer_t *buffer, gyro_data_t data);
float calculate_angular_velocity(gyro_data_t data);
void check_threshold(float angular_velocity);
void signal_handler(int signal);

// Function to read a single register from the MPU-6050
int i2c_read_register(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Error reading register value");
        return -1;
    }
    return 0;
}

// Function to write a single register to the MPU-6050
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to register");
        return -1;
    }
    return 0;
}

// Function to read gyroscope data from the MPU-6050
int read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t buffer[6];
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading gyroscope data");
        return -1;
    }

    // Combine high and low bytes for each axis (little-endian)
    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert raw data to degrees/second (sensitivity for default +-250 dps range)
    data->x = (float)raw_x / GYRO_SENSITIVITY;
    data->y = (float)raw_y / GYRO_SENSITIVITY;
