#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        9600
#define READ_INTERVAL_S  5
#define READ_TIMEOUT_US  100000   /* 100 ms */
#define CO2_LOG_FILE     "co2_log.json"
#define ERROR_LOG_FILE   "co2_error.log"
#define CO2_READ_LEN     9
#define CO2_CMD_LEN      9

static volatile sig_atomic_t g_running = 1;
static int  g_uart_handle = -1;
static FILE *g_log_file   = NULL;
static FILE *g_err_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly.            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped message to the error log file.                 */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    if (!g_err_file)
        return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(g_err_file, "[timestamp-error] %s\n", msg);
        fflush(g_err_file);
        return;
    }

    fprintf(g_err_file,
            "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(g_err_file);
}

/* ------------------------------------------------------------------ */
/* Initialise pigpio and open the UART.                               */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    g_uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (g_uart_handle < 0) {
        log_error("Failed to open UART device");
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Send the 9-byte read command to the MH-Z19B.                         */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int send_read_command(void)
{
    unsigned char cmd[CO2_CMD_LEN] = {
        0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79
    };

    if (serWrite(g_uart_handle, (char *)cmd, CO2_CMD_LEN) != CO2_CMD_LEN) {
        log_error("Failed to write read command to UART");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read exactly `len` bytes from the UART with a timeout.             */
/* Returns 0 on success, -1 on timeout, -2 on read error.            */
/* ------------------------------------------------------------------ */
static int read_uart_data(unsigned char *buf, int len)
{
    int total = 0;
    uint32_t start_tick = gpioTick();

    while (total < len) {
        int avail = serDataAvailable(g_uart_handle);
        if (avail < 0) {
            log_error("serDataAvailable failed");
            return -2;
        }
        if (avail == 0) {
            /* Timeout — sensor may be absent or not responding */
            uint32_t now = gpioTick();
            if ((now - start_tick) > READ_TIMEOUT_US) {
                log_error("UART read timeout");
                return -1;
            }
            gpioDelay(1000); /* 1 ms */
            continue;
        }

        int to_read = (avail < (len - total)) ? avail : (len - total);
        int n = serRead(g_uart_handle, (char *)(buf + total), to_read);
        if (n < 0) {
            log_error("serRead failed");
            return -2;
        }
        if (n == 0) {
            gpioDelay(1000);
            continue;
        }
        total += n;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Validate the CO2 response checksum.                                 */
/* Returns 0 on success, -1 on checksum mismatch.                    */
/* ------------------------------------------------------------------ */
static int validate_co2_checksum(const unsigned char *resp)
{
    unsigned char checksum = 0xFF;
    for (int i = 1; i < 8; i++)
        checksum += resp[i];
    checksum += 1;

    if (checksum != resp[8]) {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Checksum mismatch: calc=0x%02X recv=0x%02X",
                 checksum, resp[8]);
        log_error(msg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Extract CO2 concentration from the response.                        */
/* ------------------------------------------------------------------ */
static int extract_co2_ppm(const unsigned char *resp, int *co2_ppm)
{
    if (validate_co2_checksum(resp) != 0)
        return -1;

    *co2_ppm = (resp[2] << 8) | resp[3];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one JSON object to the CO2 log file.                         */
/* ------------------------------------------------------------------ */
static int log_co2_data(int co2_ppm, int error)
{
    if (!g_log_file)
        return -1;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        log_error("localtime_r failed");
        return -1;
    }

    fprintf(g_log_file,
            "{\"timestamp\":%ld,\"co2_ppm\":%d,\"error\":%d}\n",
            (long)t, co2_ppm, error);
    fflush(g_log_file);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_uart_handle >= 0) {
        serClose(g_uart_handle);
        g_uart_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_err_file) {
        fclose(g_err_file);
        g_err_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Open error log file first so all messages are available */
    g_err_file = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_file) {
        perror("fopen(error_log)");
        return EXIT_FAILURE;
    }

    /* Open CO2 log file in append mode */
    g_log_file = fopen(CO2_LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(co2_log)");
        fclose(g_err_file);
        g_err_file = NULL;
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialise pigpio and UART */
    if (init_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CO2 monitoring started. Logging to %s every %d s.\n",
           CO2_LOG_FILE, READ_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        unsigned char resp[CO2_READ_LEN];
        int co2_ppm = 0;
        int error = 0;

        if (send_read_command() != 0) {
            error = 1;
        } else {
            if (read_uart_data(resp, CO2_READ_LEN) != 0) {
                error = 1;
            } else {
                if (extract_co2_ppm(resp, &co2_ppm) != 0) {
                    error = 1;
                }
            }
        }

        if (log_co2_data(co2_ppm, error) != 0) {
            log_error("Failed to log CO2 data");
        }

        /* Print the same JSON to stdout for remote monitoring */
        if (error) {
            printf("{\"timestamp\":0,\"co2_ppm\":0,\"error\":1}\n");
        } else {
            printf("{\"timestamp\":0,\"co2_ppm\":%d,\"error\":0}\n", co2_ppm);
        }
        fflush(stdout);

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

