#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define CONFIG_A 0x00
#define CONFIG_B 0x01
#define MODE 0x02
#define DATA 0x03

#define GPIO_PIN 17
#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

typedef struct {
    float heading;
    bool valid;
} HeadingData;

static HeadingData heading_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_hmc5883l(void) {
    if (i2cWriteByteData(i2c_handle, CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing CONFIG_A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing CONFIG_B\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing MODE\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, DATA, buf, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static float calculate_heading(int16_t x, int16_t y, int16_t z) {
    float heading = atan2f((float)y, (float)x) * 180.0 / M_PI;
    if (heading < 0) heading += 360.0;
    return heading;
}

static void update_buffer(float heading) {
    heading_buffer[buffer_index].heading = heading;
    heading_buffer[buffer_index].valid = true;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void control_gpio(float heading) {
    if (fabsf(heading - TARGET_HEADING) > DEVIATION_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1);
    } else {
        gpioWrite(GPIO_PIN, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int16_t x, y, z;
    while (running) {
        if (read_magnetometer(&x, &y, &z) == 0) {
            float heading = calculate_heading(x, y, z);
            update_buffer(heading);
            control_gpio(heading);
            printf("Heading: %.2f degrees, Target: %.2f degrees\n", heading, TARGET_HEADING);
        } else {
            fprintf(stderr, "Failed to read magnetometer data, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(GPIO_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

