            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int red = (lux < LUX_THRESHOLD_LOW) ? 1 : 0;
        int green = (lux >= LUX_THRESHOLD_LOW && lux < LUX_THRESHOLD_MED) ? 1 : 0;
        int blue = (lux >= LUX_THRESHOLD_MED && lux < LUX_THRESHOLD_HIGH) ? 1 : 0;

        gpio_set(red_line, red);
        gpio_set(green_line, green);
        gpio_set(blue_line, blue);

        log_data(lux, red, green, blue);

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

