#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43
#define SERVO_PIN 18
#define PWM_CHIP "/sys/class/pwm/pwmchip2"
#define PWM_PERIOD_NS 1000000000L
#define PWM_RANGE 1000
#define LOG_FILE "solar_tracker.log"
#define I2C_BUS "/dev/i2c-1"
#define RETRY_DELAY_MS 100
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    struct i2c_msg msgs[1] = {
        { .addr = MPU6050_ADDR, .flags = 0, .len = 2, .buf = buf }
    };
    struct i2c_rdwr_ioctl_data data = { .msgs = msgs, .nmsgs = 1 };
    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    struct i2c_msg msgs[2] = {
        { .addr = MPU6050_ADDR, .flags = 0, .len = 1, .buf = &reg },
        { .addr = MPU6050_ADDR, .flags = I2C_M_RD, .len = len, .buf = buf }
    };
    struct i2c_rdwr_ioctl_data data = { .msgs = msgs, .nmsgs = 2 };
    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "I2C read burst from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    return 0;
}

static int read_mpu6050(int fd, float *pitch, float *roll) {
    uint8_t buf[14];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, sizeof(buf)) < 0) return -1;
    int16_t ax = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t ay = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t az = (int16_t)((buf[4] << 8) | buf[5]);
    int16_t gx = (int16_t)((buf[8] << 8) | buf[9]);
    int16_t gy = (int16_t)((buf[10] << 8) | buf[11]);
    int16_t gz = (int16_t)((buf[12] << 8) | buf[13]);
    *pitch = atan2f((float)ay, (float)az) * 180.0f / M_PI;
    *roll = atan2f(-(float)ax, sqrtf((float)ay * ay + (float)az * az)) * 180.0f / M_PI;
    return 0;
}

static int set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int duty_ns = (int)(((float)angle / 180.0f) * PWM_RANGE * PWM_PERIOD_NS / 100.0f);
    char path[64];
    snprintf(path, sizeof(path), "%s/pwm0/duty_cycle", PWM_CHIP);
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    fprintf(fp, "%d", duty_ns);
    fclose(fp);
    return 0;
}

static void log_data(float pitch, float roll, int servo_angle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_fp, "%s,%.2f,%.2f,%d\n", ts, pitch, roll, servo_angle);
    fflush(log_fp);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    set_servo_angle(0);
    usleep(100000);
    char path[64];
    snprintf(path, sizeof(path), "%s/pwm0/duty_cycle", PWM_CHIP);
    unlink(path);
    snprintf(path, sizeof(path), "%s/pwm0/enable", PWM_CHIP);
    unlink(path);
    snprintf(path, sizeof(path), "%s/pwm0/period", PWM_CHIP);
    unlink(path);
    snprintf(path, sizeof(path), "%s/pwm0/duty_cycle", PWM_CHIP);
    unlink(path);
    snprintf(path, sizeof(path), "%s/pwm0/enable", PWM_CHIP);
    unlink(path);
    snprintf(path, sizeof(path), "%s/pwm0/period", PWM_CHIP);
    unlink(path);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
