#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define FADE_DURATION_SEC 1800
#define FADE_STEP_SEC 1
#define SCHEDULE_FILE "lighting_schedule.txt"

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_schedule(const char *filename, char schedule[NUM_RELAYS][2][6]) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening schedule file");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (fscanf(fp, "%5s %5s", schedule[i][0], schedule[i][1]) != 2) {
            fprintf(stderr, "Error reading schedule entry for relay %d\n", i + 1);
            fclose(fp);
            return -1;
        }
    }

    fclose(fp);
    return 0;
}

static int parse_time(const char *time_str, int *hour, int *min, int *sec) {
    if (sscanf(time_str, "%d:%d:%d", hour, min, sec) != 3) {
        return -1;
    }
    if (*hour < 0 || *hour > 23 || *min < 0 || *min > 59 || *sec < 0 || *sec > 59) {
        return -1;
    }
    return 0;
}

static int is_time_in_range(int hour, int min, int sec, const char *start_time, const char *end_time) {
    int start_hour, start_min, start_sec;
    int end_hour, end_min, end_sec;

    if (parse_time(start_time, &start_hour, &start_min, &start_sec) != 0) {
        fprintf(stderr, "Invalid start time format: %s\n", start_time);
        return 0;
    }
    if (parse_time(end_time, &end_hour, &end_min, &end_sec) != 0) {
        fprintf(stderr, "Invalid end time format: %s\n", end_time);
        return 0;
    }

    if (start_hour > end_hour) {
        return (hour >= start_hour || hour < end_hour) || (hour == start_hour && min >= start_min) || (hour == end_hour && min <= end_min);
    } else {
        return (hour == start_hour && min >= start_min) || (hour == end_hour && min <= end_min);
    }
}

static int set_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static int set_all_relays(int states[NUM_RELAYS]) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (set_relay(relay_pins[i], states[i]) != 0) {
            return -1;
        }
    }
    return 0;
}

static int fade_relay(int pin, int target_state, int duration_sec) {
    int current_state = gpioRead(pin);
    if (current_state < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", pin);
        return -1;
    }

    int steps = duration_sec / FADE_STEP_SEC;
    int step_size = (target_state - current_state) / steps;

    for (int i = 0; i < steps && running; i++) {
        int new_state = current_state + step_size;
        if (new_state > target_state) new_state = target_state;
        if (new_state < current_state) new_state = current_state;

        if (set_relay(pin, new_state) != 0) {
            return -1;
        }
        current_state = new_state;
        gpioDelay(FADE_STEP_SEC * 1000000);
    }

    if (set_relay(pin, target_state) != 0) {
        return -1;
    }
    return 0;
}

static int apply_schedule(const char schedule[NUM_RELAYS][2][6], int current_hour, int current_min, int current_sec) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (is_time_in_range(current_hour, current_min, current_sec, schedule[i][0], schedule[i][1])) {
            printf("Time %02d:%02d:%02d matches relay %d: %s\n", current_hour, current_min, current_sec, i + 1, schedule[i][1]);
            if (strcmp(schedule[i][1], "on") == 0) {
                if (set_relay(relay_pins[i], 1) != 0) {
                    return -1;
                }
            } else if (strcmp(schedule[i][1], "off") == 0) {
                if (set_relay(relay_pins[i], 0) != 0) {
                    return -1;
                }
            } else {
                fprintf(stderr, "Invalid state for relay %d: %s\n", i + 1, schedule[i][1]);
                return -1;
            }
            if (fade_relay(relay_pins[i], strcmp(schedule[i][1], "on") == 0 ? 1 : 0, FADE_DURATION_SEC) != 0) {
                return -1;
            }
        }
    }
    return 0;
}

int main(void) {
    char schedule[NUM_RELAYS][2][6];
    int current_hour, current_min, current_sec;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (set_relay(relay_pins[i], 0) != 0) {
            gpioTerminate();
            return 1;
        }
    }

    if (read_schedule(SCHEDULE_FILE, schedule) != 0) {
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        set_all_relays(0);
        gpioTerminate();
        return 1;
    }

    while (running) {
        time_t rawtime;
        struct tm *timeinfo;

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        if (!timeinfo) {
            perror("localtime failed");
            break;
        }

        current_hour = timeinfo->tm_hour;
        current_min = timeinfo->tm_min;
        current_sec = timeinfo->tm_sec;

        if (apply_schedule(schedule, current_hour, current_min, current_sec) != 0) {
            break;
        }

        gpioDelay(1000000);
    }

    set_all_relays(0);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

