#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 30.0
#define MIN_FREQUENCY   200
#define MAX_FREQUENCY   2000

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  300000  /* 300 ms max echo wait */
#define LOOP_DELAY_US    60000   /* 60 ms between measurements */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure distance in cm using HC-SR04.
 * Returns -1.0 on timeout / error.
 */
static float measure_distance(void) {
    uint32_t start_tick, end_tick;

    /* Ensure trigger is low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0;
    }
    gpioDelay(2);  /* 2 us settle */

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1.0;
    }
