#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  22
#define BLUE_PIN   27
#define PWM_FREQ   1000
#define PWM_RANGE  255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_led_color(int red, int green, int blue) {
    if (gpioPWM(RED_PIN,   red) < 0) fprintf(stderr, "Warning: gpioPWM(RED_PIN) failed\n");
    if (gpioPWM(GREEN_PIN, green) < 0) fprintf(stderr, "Warning: gpioPWM(GREEN_PIN) failed\n");
    if (gpioPWM(BLUE_PIN,  blue) < 0) fprintf(stderr, "Warning: gpioPWM(BLUE_PIN) failed\n");
}

static void off_led(void) {
    set_led_color(0, 0, 0);
}

static void sine_wave_led(double time) {
    double val = sin(time * 2.0 * M_PI);
    if (val < 0.0) val = 0.0;
    if (val > 1.0) val = 1.0;
    int r = (int)(val * 255.0);
    int g = (int)((1.0 - val) * 255.0);
    int b = 0;
    set_led_color(r, g, b);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0) { fprintf(stderr, "Error: gpioSetMode(RED_PIN) failed\n"); off_led(); gpioTerminate(); return EXIT_FAILURE; }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) { fprintf(stderr, "Error: gpioSetMode(GREEN_PIN) failed\n"); off_led(); gpioTerminate(); return EXIT_FAILURE; }
    if (gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) { fprintf(stderr, "Error: gpioSetMode(BLUE_PIN) failed\n"); off_led(); gpioTerminate(); return EXIT_FAILURE; }

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) < 0) { fprintf(stderr, "Error: gpioSetPWMfrequency(RED_PIN) failed\n"); off_led(); gpioTerminate(); return EXIT_FAILURE; }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0) { fprintf(stderr, "Error: gpioSetPWMfrequency(GREEN_PIN) failed\n"); off_led(); gpioTerminate(); return EXIT_FAILURE; }
    if (gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) < 0) { fprintf(stderr, "Error: gpioSetPWMfrequency(BLUE_PIN) failed\n"); off_led(); gpioTerminate(); return EXIT_FAILURE; }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0) { fprintf(stderr, "Error: gpioSetPWMrange(RED_PIN) failed\n"); off_led(); gpioTerminate(); return EXIT_FAILURE; }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) { fprintf(stderr, "Error: gpioSetPWMrange(GREEN_PIN) failed\n"); off_led(); gpioTerminate(); return EXIT_FAILURE; }
    if (gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) { fprintf(stderr, "Error: gpioSetPWMrange(BLUE_PIN) failed\n"); off_led(); gpioTerminate(); return EXIT_FAILURE; }

    off_led();

    while (running) {
        sine_wave_led(time_time());
        time_sleep(0.01);
    }

    off_led();
    gpioTerminate();
    return EXIT_SUCCESS;
}

