#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define PWM_FREQUENCY 1000  /* Hz */
#define PWM_DUTY_CYCLE 128   /* 50% of 255 */
#define DEBOUNCE_US 50000    /* 50 ms */

/* Melody: frequency (Hz) and duration (ms) */
typedef struct {
    int frequency;
    int duration_ms;
} MelodyNote;

/* Lookup table: 12 notes, 12 rests */
static const MelodyNote melody[] = {
    {262, 500}, {294, 500}, {330, 500}, {349, 500}, {392, 500},
    {440, 500}, {494, 500}, {523, 500}, {0, 500}, {0, 500},
    {0, 500}, {0, 500}, {262, 500}, {294, 500}, {330, 500}, {349, 500},
    {392, 500}, {440, 500}, {494, 500}, {523, 500}, {0, 500}, {0, 500},
    {0, 500}, {0, 500}, {262, 500}, {294, 500}, {330, 500}, {349, 500},
    {392, 500}, {440, 500}, {494, 500}, {523, 500}, {0, 500}, {0, 500},
    {0, 500}, {0, 500}
};

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t melody_playing = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only, do not block in a pigpio thread.   */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Play a single note (frequency > 0) using hardware PWM.            */
/* Returns 0 on success, -1 on gpioHardwarePWM failure.              */
/* ------------------------------------------------------------------ */
static int play_note(int frequency, int duration_ms)
{
    if (frequency <= 0) {
        fprintf(stderr, "Error: invalid frequency %d\n", frequency);
        return -1;
    }

    if (gpioHardwarePWM(BUZZER_PIN, frequency, PWM_DUTY_CYCLE) < 0) {
        fprintf(stderr, "Error: gpioHardwarePWM failed for frequency %d Hz\n",
                frequency);
        return -1;
    }

    gpioDelay(duration_ms * 1000);  /* microseconds */

    /* Stop PWM (duty cycle 0) */
    if (gpioHardwarePWM(BUZZER_PIN, 0, 0) < 0) {
        fprintf(stderr, "Warning: gpioHardwarePWM stop failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Play the melody stored in the lookup table.                        */
/* Returns 0 on success, -1 on any error.                             */
/* ------------------------------------------------------------------ */
static int play_melody(void)
{
    melody_playing = 1;

    for (int i = 0; i < sizeof(melody) / sizeof(melody[0]); i++) {
        if (!running) {
            break;
        }

        if (melody[i].frequency > 0) {
            if (play_note(melody[i].frequency, melody[i].duration_ms) < 0) {
                melody_playing = 0;
                return -1;
            }
        } else {
            /* Rest: wait for duration_ms, but check running flag */
            gpioDelay(melody[i].duration_ms * 1000);
        }
    }

    melody_playing = 0;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Button interrupt callback — runs in pigpio thread.                   */
/* ------------------------------------------------------------------ */
static void button_interrupt_handler(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level != 0) {  /* active-low: 0 = pressed */
        return;
    }

    /* Debounce: wait and re-check */
    gpioDelay(DEBOUNCE_US);
    if (gpioRead(BUTTON_PIN) != 0) {
        return;  /* debounce still active */
    }

    if (melody_playing) {
        /* Graceful stop: set PWM duty cycle to 0 */
        gpioHardwarePWM(BUZZER_PIN, 0, 0);
        melody_playing = 0;
        printf("Melody stopped.\n");
    } else {
        if (play_melody() < 0) {
            fprintf(stderr, "Error: melody playback failed\n");
        }
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                     */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop PWM first */
    gpioHardwarePWM(BUZZER_PIN, 0, 0);

    /* Release pigpio resources */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure button pin */
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button pin %d\n", BUTTON_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-up so the button is defined when idle */
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for button pin %d\n", BUTTON_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure buzzer pin for hardware PWM */
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for buzzer pin %d\n", BUZZER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency and duty cycle */
    if (gpioHardwarePWM(BUZZER_PIN, PWM_FREQUENCY, PWM_DUTY_CYCLE) < 0) {
        fprintf(stderr, "Error: gpioHardwarePWM failed for buzzer pin %d\n", BUZZER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register interrupt handler for button press */
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed for button pin %d\n", BUTTON_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Musical doorbell ready. Press the button (GPIO%d) to play.\n", BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop — wait for signal or until melody finishes */
    while (running) {
        gpioDelay(100000);  /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

