#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* LSM303DLHC magnetometer I2C address (SA0 tied to GND) */
#define LSM303_ADDR 0x1E

/* LSM303DLHC register addresses */
#define MR_REG_M     0x02
#define CRA_REG_M    0x00
#define OUT_X_L_M    0x03

/* Hard-iron calibration offsets (example values; calibrate for your sensor) */
#define X_OFFSET 10.0f
#define Y_OFFSET -5.0f
#define Z_OFFSET 20.0f

/* Global resources for signal-handler cleanup */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an 8-bit register using SMBus block write   */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an 8-bit register using SMBus block read  */
/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of magnetometer data (X_L, X_H, Z_L, Z_H, Y_L, Y_H)     */
/* ------------------------------------------------------------------ */
static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "I2C read of magnetometer data failed: %s\n",
                strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Apply hard-iron calibration offsets to raw sensor data            */
/* ------------------------------------------------------------------ */
static void calibrate_magnetometer(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                                   float *cal_x, float *cal_y, float *cal_z)
{
    *cal_x = (float)raw_x - X_OFFSET;
    *cal_y = (float)raw_y - Y_OFFSET;
    *cal_z = (float)raw_z - Z_OFFSET;
}

/* ------------------------------------------------------------------ */
/* Compute compass heading from calibrated X and Y values              */
/* ------------------------------------------------------------------ */
static float calculate_heading(float cal_x, float cal_y)
{
    float heading = atan2f(cal_y, cal_x) * 180.0f / M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

/* ------------------------------------------------------------------ */
/* Map heading to compass direction string                            */
/* ------------------------------------------------------------------ */
static const char *map_heading_to_direction(float heading)
{
    if (heading >= 337.5f || heading < 22.5f)
        return "N";
    if (heading >= 22.5f && heading < 67.5f)
        return "NE";
    if (heading >= 67.5f && heading < 112.5f)
        return "E";
    if (heading >= 112.5f && heading < 157.5f)
        return "SE";
    if (heading >= 157.5f && heading < 202.5f)
        return "S";
    if (heading >= 202.5f && heading < 247.5f)
        return "SW";
    if (heading >= 247.5f && heading < 292.5f)
        return "W";
    return "NW";
}

/* ------------------------------------------------------------------ */
/* Append a CSV row with timestamp, calibrated X, Y, Z, and heading    */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float cal_x, float cal_y, float cal_z, float heading)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, cal_x, cal_y, cal_z, heading) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush CSV failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources — called on every exit path                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv_fp != NULL) {
        fclose(g_csv_fp);
        g_csv_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 (/dev/i2c-1) */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the LSM303DLHC slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access for 0x%02X: %s\n",
                LSM303_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure magnetometer: continuous-conversion mode, 15 Hz ODR */
    if (i2c_write_reg8(g_i2c_fd, MR_REG_M, 0x00) != 0) {
        fprintf(stderr, "Failed to configure magnetometer (MR_REG_M)\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2c_write_reg8(g_i2c_fd, CRA_REG_M, 0x14) != 0) {
        fprintf(stderr, "Failed to configure magnetometer (CRA_REG_M)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV file in append mode; write header if file is empty */
    g_csv_fp = fopen("mag_log.csv", "a");
    if (g_csv_fp == NULL) {
        fprintf(stderr, "Failed to open mag_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_csv_fp, 0, SEEK_END);
    long file_size = ftell(g_csv_fp);
    if (file_size == 0) {
        fprintf(g_csv_fp, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
        fflush(g_csv_fp);
    }

    printf("LSM303DLHC magnetometer logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        float cal_x, cal_y, cal_z;
        float heading;

        if (read_magnetometer(g_i2c_fd, &raw_x, &raw_y, &raw_z) != 0) {
            /* I2C read failure — skip this sample and continue */
            sleep(1);
            continue;
        }

        calibrate_magnetometer(raw_x, raw_y, raw_z, &cal_x, &cal_y, &cal_z);
        heading = calculate_heading(cal_x, cal_y);

        printf("X: %.2f  Y: %.2f  Z: %.2f  Heading: %.2f°  %s\n",
               cal_x, cal_y, cal_z, heading, map_heading_to_direction(heading));

        if (log_data(g_csv_fp, cal_x, cal_y, cal_z, heading) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

