#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define TOUCH_SENSOR_GPIO 4
#define DEBOUNCE_MS 200
#define LOG_FILE "relay_log.json"

static volatile sig_atomic_t running = 1;
static volatile uint32_t last_touch_tick = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", ts, state ? "ON" : "OFF");
    } else {
        fprintf(fp, "{\"timestamp\":\"unknown\",\"relay_state\":\"%s\"}\n", state ? "ON" : "OFF");
    }

    fclose(fp);
}

static void touch_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;

    if (level != 0) {
        return;
    }

    uint32_t elapsed = tick - last_touch_tick;
