#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define MOISTURE_THRESHOLD 30
#define RELAY_ON_DURATION_SEC 5
#define RELAY_OFF_DURATION_SEC 1
#define LOG_FILE "irrigation_log.txt"
#define POLL_INTERVAL_SEC 10

static const unsigned int relay_pins[NUM_RELAYS] = {17, 23, 24, 25};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS] = {NULL};
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 1);  /* OFF */
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int setup_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    relay_pins[i], strerror(errno));
            return -1;
        }

        if (gpiod_line_request_output(relay_lines[i], "irrigation", 1) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output: %s\n",
                    relay_pins[i], strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int activate_relay(int relay_number) {
    if (relay_number < 0 || relay_number >= NUM_RELAYS) {
        fprintf(stderr, "Invalid relay number: %d\n", relay_number);
        return -1;
    }

    if (gpiod_line_set_value(relay_lines[relay_number], 0) < 0) {
        fprintf(stderr, "Failed to activate relay %d: %s\n",
                relay_number, strerror(errno));
        return -1;
    }

    printf("Relay %d activated\n", relay_number);

    time_t start = time(NULL);
    while (program_running && (time(NULL) - start) < RELAY_ON_DURATION_SEC) {
        sleep(1);
    }

    if (gpiod_line_set_value(relay_lines[relay_number], 1) < 0) {
        fprintf(stderr, "Failed to deactivate relay %d: %s\n",
                relay_number, strerror(errno));
        return -1;
    }

    printf("Relay %d deactivated\n", relay_number);

    return 0;
}

static int log_event(int relay_number, int moisture_level) {
    if (!log_file) {
        fprintf(stderr, "Log file not open\n");
        return -1;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    if (!tm_info) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info) == 0) {
        fprintf(stderr, "Failed to format timestamp\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Relay %d - Moisture Level: %d\n",
                timestamp, relay_number, moisture_level) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (setup_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int moisture_level = rand() % 101;
        printf("Moisture Level: %d\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            for (int i = 0; i < NUM_RELAYS && program_running; i++) {
                if (activate_relay(i) < 0) {
                    fprintf(stderr, "Relay activation failed, exiting\n");
                    break;
                }
                if (log_event(i, moisture_level) < 0) {
                    fprintf(stderr, "Logging failed, exiting\n");
                    break;
                }
            }
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

