/*
 * Automated Plant Watering System — Raspberry Pi Zero W
 *
 * Hardware:
 *   - SG90 servo on GPIO17 (physical pin 11) — valve control
 *   - SG90 servo on GPIO18 (physical pin 12) — nozzle direction control
 *
 * Behavior:
 *   - Simulated soil-moisture readings every second.
 *   - Water valve when soil is below 50%.
 *   - Sweep nozzle through 0, 45, 90, 135, 180 degrees at 2 s/step.
 *   - Hold for 5 s after each cycle.
 *   - Stop servos on SIGINT/SIGTERM.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 * Run:
 *   sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define VALVE_SERVO_PIN      17          /* GPIO17 — physical pin 11 */
#define NOZZLE_SERVO_PIN     18          /* GPIO18 — physical pin 12 */

#define MOISTURE_THRESHOLD   50          /* %  */
#define SERVO_MIN_PULSE_US   500         /* 0 degrees */
#define SERVO_MAX_PULSE_US   2500        /* 180 degrees */
#define SERVO_STOP_PULSE_US  0           /* stop signal */

#define WATERING_DURATION_S  5           /* seconds between cycles */
#define SWEEP_DURATION_S     2           /* seconds per sweep step */
#define SWEEP_STEP_DELAY_S   0.1         /* seconds between sweep steps */
#define SERVO_RETRY_COUNT     3
#define SERVO_RETRY_DELAY_US 100000      /* 100 ms backoff */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;

/* --------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Servo helpers ------------------------------- */

/*
 * Set a servo to a given pulse width (0-2500 us).
 * Returns 0 on success, -1 on failure.
 */
static int set_servo_pulse(int pin, int pulse_us)
{
    if (pulse_us < SERVO_MIN_PULSE_US || pulse_us > SERVO_MAX_PULSE_US) {
        fprintf(stderr, "Error: pulse %d us out of range [%d, %d] on GPIO%d\n",
                pulse_us, SERVO_MIN_PULSE_US, SERVO_MAX_PULSE_US, pin);
        return -1;
    }

    for (int attempt = 0; attempt < SERVO_RETRY_COUNT; attempt++) {
        if (gpioServo(pin, pulse_us) == 0)
            return 0;
        fprintf(stderr, "Warning: gpioServo failed on GPIO%d (pulse %d us), attempt %d/%d\n",
                pin, pulse_us, attempt + 1, SERVO_RETRY_COUNT);
        if (attempt < SERVO_RETRY_COUNT - 1)
            gpioDelay(SERVO_RETRY_DELAY_US);
    }

    fprintf(stderr, "Error: gpioServo failed on GPIO%d after %d attempts\n",
            pin, SERVO_RETRY_COUNT);
    return -1;
}

/*
 * Stop the servo by sending a stop signal (0 us).
 * Returns 0 on success, -1 on failure.
 */
static int stop_servo(int pin)
{
    return set_servo_pulse(pin, SERVO_STOP_PULSE_US);
}

/* --------------------------- Watering cycle ----------------------------- */

static void watering_cycle(void)
{
    /* Open valve: close (0 degrees) */
    if (set_servo_pulse(VALVE_SERVO_PIN, SERVO_STOP_PULSE_US) != 0) {
        fprintf(stderr, "Critical: failed to open valve during watering cycle\n");
        return;
    }
    printf("Valve opened (0 degrees)\n");
    fflush(stdout);

    /* Sweep nozzle through all five angles */
    for (int angle = 0; angle <= 180 && g_running; angle += 45) {
        if (set_servo_pulse(NOZZLE_SERVO_PIN, angle * 1000) != 0) {
            fprintf(stderr, "Warning: failed to set nozzle to angle %d degrees\n", angle);
            continue;
        }
        printf("Nozzle at %d degrees\n", angle);
        fflush(stdout);

        /* Hold for the watering duration */
        for (int s = 0; s < WATERING_DURATION_S && g_running; s++)
            sleep(1);
    }

    /* Close valve: open (90 degrees) */
    if (set_servo_pulse(VALVE_SERVO_PIN, SERVO_MAX_PULSE_US) != 0) {
        fprintf(stderr, "Critical: failed to close valve during watering cycle\n");
    } else {
        printf("Valve closed (90 degrees)\n");
        fflush(stdout);
    }

    /* Hold for the post-watering gap */
    for (int s = 0; s < WATERING_DURATION_S && g_running; s++)
        sleep(1);
}

/* ------------------------------- Main ----------------------------------- */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handlers\n");
    }

    printf("Automated Plant Watering System started.\n");
    printf("  Valve servo : GPIO%d (physical pin 11)\n", VALVE_SERVO_PIN);
    printf("  Nozzle servo: GPIO%d (physical pin 12)\n", NOZZLE_SERVO_PIN);
    printf("  Threshold : %d%%\n", MOISTURE_THRESHOLD);
    printf("  Cycle     : every %d s\n", SWEEP_DURATION_S);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main loop --- */
    while (g_running) {
        /* Simulated soil-moisture reading every second */
        int moisture = (rand() % 101);  /* 0–100 */

        printf("Moisture: %d%%\n", moisture);
        fflush(stdout);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Watering cycle started (moisture below threshold)\n");
            fflush(stdout);
            watering_cycle();
        } else {
