                safe_write(step_pins[1], step_sequence[idx][1]) < 0 ||
                safe_write(step_pins[2], step_sequence[idx][2]) < 0 ||
                safe_write(step_pins[3], step_sequence[idx][3]) < 0) {
                return -1;
            }
            gpioDelay(STEP_DELAY_US);
        }
    }
    return 0;
