        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    if (safe_set_mode(LOCK_BUTTON, PI_INPUT) < 0 ||
        safe_set_mode(UNLOCK_BUTTON, PI_INPUT) < 0 ||
        safe_set_mode(STEP_PIN1, PI_OUTPUT) < 0 ||
        safe_set_mode(STEP_PIN2, PI_OUTPUT) < 0 ||
        safe_set_mode(STEP_PIN3, PI_OUTPUT) < 0 ||
        safe_set_mode(STEP_PIN4, PI_OUTPUT) < 0) {
        deenergize_coils();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_pull_up(LOCK_BUTTON) < 0 ||
        safe_set_pull_up(UNLOCK_BUTTON) < 0) {
        deenergize_coils();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    deenergize_coils();

    printf("Automatic door lock system started. Press Ctrl+C to exit.\n");
    printf("Press LOCK button to rotate motor clockwise.\n");
    printf("Press UNLOCK button to rotate motor counter-clockwise.\n");

    while (running) {
        int lock_pressed = (gpioRead(LOCK_BUTTON) == 0);
        int unlock_pressed = (gpioRead(UNLOCK_BUTTON) == 0);

        if (lock_pressed) {
            printf("Lock button pressed. Rotating motor clockwise...\n");
            if (rotate_stepper(NUM_STEPS, 1) < 0) {
                fprintf(stderr, "Error: motor rotation failed\n");
                break;
            }
            deenergize_coils();
            gpioDelay(DEBOUNCE_US);
        } else if (unlock_pressed) {
            printf("Unlock button pressed. Rotating motor counter-clockwise...\n");
            if (rotate_stepper(NUM_STEPS, -1) < 0) {
                fprintf(stderr, "Error: motor rotation failed\n");
                break;
            }
            deenergize_coils();
            gpioDelay(DEBOUNCE_US);
        }

        gpioDelay(10000);
    }

    deenergize_coils();
    gpioTerminate();
    printf("Door lock system stopped.\n");
    return EXIT_SUCCESS;
}

