#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define TIMEOUT_US  50000   /* 50 ms max echo wait */
#define MIN_GUARD_US 60000  /* 60 ms min between measurements */
#define POLL_INTERVAL_US 1000000  /* 1 second */

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Measure distance in centimeters.
 * Returns 0 on success, -1 on timeout/error.
 */
static int measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo)
{
    struct timespec start, end;
    long elapsed_us;

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    usleep(2);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for echo rising edge (timeout) */
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_us = (end.tv_sec - start.tv_sec) * 1000000L +
                     (end.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            fprintf(stderr, "Error: echo rising edge timeout\n");
            return -1;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &start);

    /* Wait for echo falling edge (timeout) */
    while (gpiod_line_get_value(echo) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_us = (end.tv_sec - start.tv_sec) * 1000000L +
                     (end.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            fprintf(stderr, "Error: echo falling edge timeout\n");
            return -1;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &end);

    elapsed_us = (end.tv_sec - start.tv_sec) * 1000000L +
                 (end.tv_nsec - start.tv_nsec) / 1000L;

    /* distance = duration_us * 0.01715 (speed of sound 343 m/s) */
    return (int)(elapsed_us * 0.01715);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Open log file once in append mode */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open GPIO chip 0 (gpiochip0 on Pi 4) */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Error: cannot open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Get trigger line */
    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        fprintf(stderr, "Error: cannot get trigger line %d: %s\n",
                TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    /* Get echo line */
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Error: cannot get echo line %d: %s\n",
                ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request trigger as output, initial value low */
    if (gpiod_line_request_output(trigger, "hcsr04-trigger", 0) < 0) {
        fprintf(stderr, "Error: cannot request trigger line as output: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Request echo as input */
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Error: cannot request echo line as input: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    /* Main measurement loop */
    while (running) {
        int distance = measure_distance(trigger, echo);

        if (distance < 0) {
            fprintf(log_fp, "-1\n");
            fflush(log_fp);
            fprintf(stderr, "Measurement failed, logging -1\n");
        } else {
            fprintf(log_fp, "%d\n", distance);
            fflush(log_fp);
            printf("Distance: %d cm\n", distance);
        }

        /* Enforce minimum guard between measurements */
        usleep(MIN_GUARD_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (trigger) {
        gpiod_line_release(trigger);
    }
    if (echo) {
        gpiod_line_release(echo);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (log_fp) {
        fclose(log_fp);
    }

    return ret;
}

