#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L1X_ADDR 0x29
#define I2C_BUS 1
#define RELAY_GPIO 18
#define DISTANCE_THRESHOLD 50
#define POLL_DELAY_US 100000

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET 0x0000
#define REG_SYSTEM_MODE 0x0080
#define REG_INTERRUPT_STATUS 0x0044
#define REG_RESULT_DISTANCE_MSB 0x0096
#define REG_RESULT_DISTANCE_LSB 0x0097

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a 16-bit register address and a 16-bit value (big-endian on the bus) */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit register address and return its value (big-endian on the bus) */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) != 0) {
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* Software reset: write 0x00 to register 0x0000 */
static int vl53l1x_reset(int handle) {
    return vl53l1x_write_reg16(handle, REG_SOFT_RESET, 0x00);
}

/* Initialise VL53L1X: set ranging mode to continuous, start ranging */
static int vl53l1x_init(int handle) {
    if (vl53l1x_reset(handle) != 0) {
        fprintf(stderr, "Error: Failed to reset VL53L1X\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    if (vl53l1x_write_reg16(handle, REG_SYSTEM_MODE, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to set ranging mode\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    return 0;
}

/* Read distance in mm; returns -1 on error */
static int vl53l1x_read_distance(int handle) {
    uint16_t status = 0;
    uint16_t dist_msb = 0, dist_lsb = 0;

    /* Poll interrupt status register for data ready (bit 0) */
    for (int i = 0; i < 10; i++) {
        if (vl53l1x_read_reg16(handle, REG_INTERRUPT_STATUS, &status) != 0) {
            fprintf(stderr, "Error: Failed to read interrupt status\n");
            return -1;
        }
        if (status & 0x01) {
            break;
        }
        gpioDelay(10000); /* 10 ms */
    }
    if (!(status & 0x01)) {
        fprintf(stderr, "Error: Timeout waiting for data ready\n");
        return -1;
    }

    /* Read 16-bit distance (MSB first) */
    if (vl53l1x_read_reg16(handle, REG_RESULT_DISTANCE_MSB, &dist_msb) != 0) {
        fprintf(stderr, "Error: Failed to read distance MSB\n");
        return -1;
    }
    if (vl53l1x_read_reg16(handle, REG_RESULT_DISTANCE_LSB, &dist_lsb) != 0) {
        fprintf(stderr, "Error: Failed to read distance LSB\n");
        return -1;
    }

    /* Clear interrupt by writing 0x01 to register 0x0044 */
    if (vl53l1x_write_reg16(handle, REG_INTERRUPT_STATUS, 0x01) != 0) {
        fprintf(stderr, "Warning: Failed to clear interrupt\n");
    }

    return (int)(dist_msb << 8) | dist_lsb;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection to VL53L1X */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d\n",
                VL53L1X_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize VL53L1X */
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO as output and ensure it starts LOW */
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    /* Set up signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity-based door system started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        int distance = vl53l1x_read_distance(i2c_handle);

        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);

            if (distance <= DISTANCE_THRESHOLD) {
                gpioWrite(RELAY_GPIO, 1);
                printf("Door opened!\n");
            } else {
                gpioWrite(RELAY_GPIO, 0);
                printf("Door closed.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

