        fprintf(stderr, "Error: Timeout waiting for data ready\n");
        return -1;
    }

    /* Read 16-bit distance (MSB first) */
    if (vl53l1x_read_reg16(handle, REG_RESULT_DISTANCE_MSB, &dist_msb) != 0) {
        fprintf(stderr, "Error: Failed to read distance MSB\n");
        return -1;
    }
    if (vl53l1x_read_reg16(handle, REG_RESULT_DISTANCE_LSB, &dist_lsb) != 0) {
        fprintf(stderr, "Error: Failed to read distance LSB\n");
        return -1;
    }

    /* Clear interrupt by writing 0x01 to register 0x0044 */
    if (vl53l1x_write_reg16(handle, REG_INTERRUPT_STATUS, 0x01) != 0) {
        fprintf(stderr, "Warning: Failed to clear interrupt\n");
    }

    return (int)(dist_msb << 8) | dist_lsb;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection to VL53L1X */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d\n",
                VL53L1X_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize VL53L1X */
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO as output and ensure it starts LOW */
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    /* Set up signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity-based door system started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        int distance = vl53l1x_read_distance(i2c_handle);

        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);

            if (distance <= DISTANCE_THRESHOLD) {
                gpioWrite(RELAY_GPIO, 1);
                printf("Door opened!\n");
            } else {
                gpioWrite(RELAY_GPIO, 0);
                printf("Door closed.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

