#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the four relays (BCM numbering)
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Define sunrise duration in seconds (30 minutes)
#define SUNRISE_DURATION 1800

// Define log file name
#define LOG_FILE "smart_lighting.log"

// Global flag for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio(void);
int set_relay_state(int pin, int state);
int log_event(const char *message);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins using pigpio
int initialize_gpio(void) {
    // Set GPIO modes for relay pins
    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", RELAY1_PIN);
        return -1;
    }
    if (gpioSetMode(RELAY2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", RELAY2_PIN);
        return -1;
    }
    if (gpioSetMode(RELAY3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", RELAY3_PIN);
        return -1;
    }
    if (gpioSetMode(RELAY4_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", RELAY4_PIN);
        return -1;
    }

    // Initialize PWM on all relay pins
    if (gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO%d\n", RELAY1_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO%d\n", RELAY2_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO%d\n", RELAY3_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO%d\n", RELAY4_PIN);
        return -1;
