#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define WHO_AM_I     0x75

/* Expected WHO_AM_I value for MPU-6050 */
#define MPU6050_WHO_AM_I 0x68

/* GPIO pin for LED */
#define LED_PIN 17

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Gyroscope sensitivity: 131 LSB/deg/s for ±250 deg/s range */
#define GYRO_SENSITIVITY 131.0f

/* Angular velocity threshold in degrees/second */
#define THRESHOLD 250.0f

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Circular buffer structure */
typedef struct {
    time_t timestamp;
    float gyro_x;
    float gyro_y;
    float gyro_z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;

/* Function prototypes */
static int initialize_mpu6050(void);
static int read_gyro_data(float *gyro_x, float *gyro_y, float *gyro_z);
static void add_to_circular_buffer(float gyro_x, float gyro_y, float gyro_z);
static void check_threshold(float gyro_x, float gyro_y, float gyro_z);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* Initialize the MPU-6050 sensor */
static int initialize_mpu6050(void) {
    /* Verify sensor identity */
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n",
                MPU6050_WHO_AM_I, who_am_i);
        return -1;
    }

    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        return -1;
    }

    /* Set sample rate divider to 1 kHz (19 = 1 kHz / (1 + 19)) */
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 19) < 0) {
        fprintf(stderr, "Error writing to SMPLRT_DIV register\n");
        return -1;
    }

    /* Set gyroscope full-scale range to ±250 deg/s (0x00) */
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG register\n");
        return -1;
    }

    return 0;
}

/* Read gyroscope data from the MPU-6050 */
static int read_gyro_data(float *gyro_x, float *gyro_y, float *gyro_z) {
    char buffer[6];

    /* Read 6 bytes starting from GYRO_XOUT_H (register 0x43) */
    int bytes_read = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading gyroscope data: expected 6 bytes, got %d\n", bytes_read);
        return -1;
    }

    /* Combine high and low bytes (big-endian) */
    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    /* Convert to degrees/second */
    *gyro_x = (float)raw_x / GYRO_SENSITIVITY;
    *gyro_y = (float)raw_y / GYRO_SENSITIVITY;
    *gyro_z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

/* Add data to the circular buffer */
static void add_to_circular_buffer(float gyro_x, float gyro_y, float gyro_z) {
    time(&gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].gyro_x = gyro_x;
    gyro_buffer[buffer_index].gyro_y = gyro_y;
    gyro_buffer[buffer_index].gyro_z = gyro_z;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

/* Check if any axis exceeds the threshold */
static void check_threshold(float gyro_x, float gyro_y, float gyro_z) {
    if (fabsf(gyro_x) > THRESHOLD ||
        fabsf(gyro_y) > THRESHOLD ||
        fabsf(gyro_z) > THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection to MPU-6050 */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 sensor */
    if (initialize_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float gyro_x, gyro_y, gyro_z;

    /* Main loop */
    while (!terminate) {
        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) == 0) {
            add_to_circular_buffer(gyro_x, gyro_y, gyro_z);
            check_threshold(gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data, attempting re-initialization...\n");
            cleanup();
            if (initialize_mpu6050() != 0) {
                fprintf(stderr, "Re-initialization failed, exiting...\n");
                break;
            }
        }

        gpioDelay(50000); /* 50 ms delay (pigpio uses microseconds) */
    }

    /* Cleanup and exit */
    cleanup();
    return EXIT_SUCCESS;
}

