#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0
#define CS_LINE         8
#define CS_CHIP         "/dev/gpiochip0"
#define GYRO_SCALE      131.0f
#define LOG_FILE        "gyro_log.txt"
#define SAMPLE_PERIOD_US 10000
#define MAX_RETRIES     3

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *cs_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    return 0;
}

static int cs_init(void) {
    cs_chip = gpiod_chip_open(CS_CHIP);
    if (!cs_chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", CS_CHIP, strerror(errno));
        return -1;
    }

    cs_line = gpiod_chip_get_line(cs_chip, CS_LINE);
    if (!cs_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", CS_LINE, strerror(errno));
        gpiod_chip_close(cs_chip); cs_chip = NULL; return -1;
    }

    if (gpiod_line_request_output(cs_line, "mpu9250-cs", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", CS_LINE, strerror(errno));
        gpiod_chip_close(cs_chip); cs_chip = NULL; cs_line = NULL; return -1;
    }

    return 0;
}

static int read_gyro_burst(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx[7] = {0x43, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    uint8_t rx[7] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 7,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error asserting CS: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error deasserting CS: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((rx[1] << 8) | rx[0]);
    *y = (int16_t)((rx[3] << 8) | rx[2]);
    *z = (int16_t)((rx[5] << 8) | rx[4]);

    return 0;
}

static void log_data(float x, float y, float z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(log_fp, "%s.%09ld,%.2f,%.2f,%.2f\n", timestamp, ts.tv_nsec, x, y, z);
    fflush(log_fp);
}

static void cleanup(void) {
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (cs_line) {
        gpiod_line_set_value(cs_line, 1);
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (cs_chip) {
        gpiod_chip_close(cs_chip);
        cs_chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (cs_init() < 0) {
        close(spi_fd); spi_fd = -1;
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("MPU-9250 Gyroscope Logger started. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t raw_x, raw_y, raw_z;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (read_gyro_burst(&raw_x, &raw_y, &raw_z) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "SPI read attempt %d failed, retrying...\n", attempt + 1);
            usleep(10000);
        }

        if (!success) {
            fprintf(stderr, "Failed to read gyroscope data after %d attempts.\n", MAX_RETRIES);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float x_rate = (float)raw_x / GYRO_SCALE;
        float y_rate = (float)raw_y / GYRO_SCALE;
        float z_rate = (float)raw_z / GYRO_SCALE;

        log_data(x_rate, y_rate, z_rate);
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

