#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>

// MPU-6050 I2C address (AD0 tied to GND)
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

// GPIO pin for LED
#define LED_PIN 21

// Threshold degrees
#define ROLL_THRESHOLD 45.0
#define PITCH_THRESHOLD 45.0

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050(int handle);
int read_mpu6050_data(int handle, float *roll, float *pitch);
void control_led(float roll, float pitch);
void log_data(float roll, float pitch);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Initialize MPU-6050
int init_mpu6050(int handle) {
    // Wake up the MPU-6050 (clear sleep bit)
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to wake up MPU-6050\n");
        return -1;
    }
    gpioDelay(100000); // 100 ms delay for stabilization

    // Set accelerometer full-scale range to +/- 2g (0x00)
    if (i2cWriteByteData(handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set accelerometer full-scale range\n");
        return -1;
    }

    return 0;
}

// Read raw accelerometer data from MPU-6050
int read_mpu6050_data(int handle, float *roll, float *pitch) {
    char buffer[6];
    int16_t accel_x, accel_y, accel_z;

    // Read 6 bytes of accelerometer data starting from ACCEL_XOUT_H
    if (i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buffer, 6) != 6) {
        fprintf(stderr, "Error: Failed to read accelerometer data\n");
        return -1;
    }

    // Combine high and low bytes (little-endian)
    accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to g's (assuming +/- 2g range)
    float accel_x_g = (float)accel_x / 16384.0f;
    float accel_y_g = (float)accel_y / 16384.0f;
    float accel_z_g = (float)accel_z / 16384.0f;

    // Calculate roll and pitch angles (in degrees)
    *roll = atan2(accel_y_g, accel_z_g) * 180.0f / M_PI;
    *pitch = atan2(-accel_x_g, sqrt(accel_y_g * accel_y_g + accel_z_g * accel_z_g)) * 180.0f / M_PI;

    return 0;
}

// Control the LED based on tilt thresholds
void control_led(float roll, float pitch) {
    int led_state = 0;

    if (fabs(roll) > ROLL_THRESHOLD || fabs(pitch) > PITCH_THRESHOLD) {
        led_state = 1;
    }

    gpioWrite(LED_PIN, led_state);
}

// Log data to a file with timestamp
void log_data(float roll, float pitch) {
    FILE *fp = fopen("tilt_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open tilt_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection on bus 1
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X\n", MPU6050_ADDR);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_handle) != 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float roll, pitch;

    // Main loop
    while (!terminate) {
        // Read tilt data
        if (read_mpu6050_data(i2c_handle, &roll, &pitch) == 0) {
            // Control LED
            control_led(roll, pitch);

            // Log data
            log_data(roll, pitch);

            // Print roll and pitch to console
            printf("Roll: %.2f degrees, Pitch: %.2f degrees\n", roll, pitch);
        } else {
            fprintf(stderr, "Warning: Failed to read sensor data, skipping logging\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

