#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADXRS290 register addresses (ORed with 0x80 for read) */
#define ADXRS290_X_RATE_REG 0x02
#define ADXRS290_Y_RATE_REG 0x04

/* SPI configuration */
#define SPI_CHANNEL 0          /* CE0 (GPIO8) */
#define SPI_BAUD    1000000    /* 1 MHz */
#define SPI_FLAGS   0          /* Mode 0, active-low CE */

/* Sensitivity: 200 LSB/deg/s */
#define SENSITIVITY 200.0f

/* Sample interval in microseconds (10 ms) */
#define SAMPLE_INTERVAL_US 10000

/* Max SPI re-initialisation attempts */
#define MAX_SPI_RETRIES 3

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only, do not call pigpio functions here */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single register from the ADXRS290.                           */
/* Returns 0 on success (data stored in *out), -1 on error.           */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx[2];
    char rx[2];

    /*
     * SPI protocol (Mode 0, MSB first):
     *   tx[0] = reg | 0x80  (read bit + register address)
     *   tx[1] = 0x00      (dummy byte for clocking out data)
     *   rx[1] = data high byte
     *   rx[2] = data low byte
     */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;

    int ret = spiXfer(g_spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X (ret=%d): %s\n",
                reg, ret, strerror(errno));
        return -1;
    }

    /* rx[1] is the high byte, rx[2] is the low byte */
    *out = (int16_t)(((uint8_t)rx[1] << 8) | (uint8_t)rx[2]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise SPI and open the log file.                              */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int initialize(void)
{
    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    /* Open SPI channel 0, 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, baud %d): %s\n",
                SPI_CHANNEL, SPI_BAUD, strerror(errno));
        gpioTerminate();
        return -1;
    }

    /* Open log file in append mode */
    g_log_file = fopen("gyro_data.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open gyro_data.csv: %s\n", strerror(errno));
        spiClose(g_spi_handle);
        g_spi_handle = -1;
        gpioTerminate();
        return -1;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
