static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only, do not call pigpio functions here */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single register from the ADXRS290.                           */
/* Returns 0 on success (data stored in *out), -1 on error.           */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx[2];
    char rx[2];

    /*
     * SPI protocol (Mode 0, MSB first):
     *   tx[0] = reg | 0x80  (read bit + register address)
     *   tx[1] = 0x00      (dummy byte for clocking out data)
     *   rx[1] = data high byte
     *   rx[2] = data low byte
