#define SENSOR2_GPIO 24
#define ALERT_GPIO 17
#define SEISMIC_DURATION_MS 500
#define ALERT_DURATION_MS 2000
#define LOG_FILE "seismic_events.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(log_file, "%s - %s\n", timestamp, message);
        fflush(log_file);
    }
}

static void alert_seismic_event(void) {
    if (gpioWrite(ALERT_GPIO, 1) != 0) {
        fprintf(stderr, "Error: Failed to set alert GPIO HIGH\n");
        return;
    }
    gpioDelay(ALERT_DURATION_MS * 1000);
    if (gpioWrite(ALERT_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to set alert GPIO LOW\n");
    }
}

static void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    if (level != 1) return;

    static uint32_t last_trigger_tick = 0;
    uint32_t elapsed = tick - last_trigger_tick;
    if (elapsed < SEISMIC_DURATION_MS * 1000) return;

    last_trigger_tick = tick;
    alert_seismic_event();
    log_event("Seismic event detected!");
}

