    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input\n", SENSOR1_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input\n", SENSOR2_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", ALERT_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: Failed to set pull-down on GPIO%d\n", SENSOR1_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: Failed to set pull-down on GPIO%d\n", SENSOR2_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALERT_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialise alert GPIO LOW\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR1_GPIO, sensor_callback) != 0) {
        fprintf(stderr, "Error: Failed to set callback for GPIO%d\n", SENSOR1_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFunc(SENSOR2_GPIO, sensor_callback) != 0) {
        fprintf(stderr, "Error: Failed to set callback for GPIO%d\n", SENSOR2_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Seismic event detection started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioWrite(ALERT_GPIO, 0);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

