#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

/* ADXRS290 Register Addresses */
#define RATE_XL 0x02
#define RATE_XH 0x03

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 /* 1 MHz */
#define SPI_FLAGS 0       /* Mode 0, active-low CE */

/* LED Configuration */
#define LED_GPIO 17

/* Threshold for angular velocity (deg/s) */
#define THRESHOLD 20.0

/* Circular Buffer Size */
#define BUFFER_SIZE 100

/* ADXRS290 Sensitivity: 200 LSB/deg/s */
#define SENSITIVITY 200.0

/* Global Variables */
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;
static double buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

/* Function Prototypes */
static int spi_read_register(uint8_t reg, uint8_t *value);
static int read_gyro_rate(double *rate);
static void add_to_circular_buffer(double value);
static void check_threshold(double rate);
static void signal_handler(int signal);
static void cleanup(void);

/*
 * Reads a single byte from an ADXRS290 register.
 * The MSB (bit 7) of the register address indicates a read.
 */
static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = (char)(reg | 0x80); /* Set MSB for read */
    tx_buf[1] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error: SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    *value = (uint8_t)rx_buf[1];
    return 0;
}

/*
 * Reads the X-axis angular rate from the ADXRS290.
 * The ADXRS290 returns the rate in two's-complement format.
 */
static int read_gyro_rate(double *rate) {
    uint8_t rate_xl, rate_xh;

    if (spi_read_register(RATE_XL, &rate_xl) != 0) {
        return -1;
    }

    if (spi_read_register(RATE_XH, &rate_xh) != 0) {
        return -1;
    }

    /* Combine the two bytes into a 16-bit signed integer */
    int16_t raw_rate = (int16_t)((rate_xh << 8) | rate_xl);

    /* Convert to degrees per second */
    *rate = (double)raw_rate / SENSITIVITY;

    return 0;
}

/*
 * Adds a value to the circular buffer.
 * The buffer is thread-safe and wraps around when it reaches capacity.
 */
static void add_to_circular_buffer(double value) {
    pthread_mutex_lock(&buffer_mutex);
    buffer[buffer_index] = value;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
    pthread_mutex_unlock(&buffer_mutex);
}

/*
 * Checks the angular velocity against the threshold and controls the LED.
 */
static void check_threshold(double rate) {
    pthread_mutex_lock(&buffer_mutex);
    int count = buffer_count;
    pthread_mutex_unlock(&buffer_mutex);

    if (count < 2) {
        return; /* Not enough data to calculate a moving average */
    }

    double sum = 0.0;
    pthread_mutex_lock(&buffer_mutex);
    for (int i = 0; i < count; i++) {
        sum += buffer[i];
    }
    pthread_mutex_unlock(&buffer_mutex);

    double average = sum / count;

    if (fabs(rate - average) > THRESHOLD) {
