#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27
#define PWM_RANGE 255
#define PWM_FREQUENCY 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(LAMP1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", LAMP1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LAMP2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", LAMP2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LAMP3_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", LAMP3_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO%d.\n", LAMP1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO%d.\n", LAMP2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO%d.\n", LAMP3_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO%d.\n", LAMP1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO%d.\n", LAMP2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO%d.\n", LAMP3_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void set_lamp_brightness(int gpio, int brightness) {
    if (gpioPWM(gpio, brightness) != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle on GPIO%d.\n", gpio);
    }
}

static void turn_off_lamp(int gpio) {
    set_lamp_brightness(gpio, 0);
}

static void cleanup_gpio(void) {
    turn_off_lamp(LAMP1_GPIO);
    turn_off_lamp(LAMP2_GPIO);
    turn_off_lamp(LAMP3_GPIO);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        fprintf(stderr, "  fade_duration_seconds: integer between 1 and 3600\n");
        return EXIT_FAILURE;
    }

    int fade_duration = atoi(argv[1]);
    if (fade_duration < 1 || fade_duration > 3600) {
        fprintf(stderr, "Error: Fade duration must be between 1 and 3600 seconds.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator started. Fade duration: %d seconds\n", fade_duration);
    printf("Press Ctrl+C to exit.\n");

    for (int i = 0; i <= fade_duration && program_running; i++) {
        set_lamp_brightness(LAMP1_GPIO, (int)(((float)i / fade_duration) * PWM_RANGE));
        set_lamp_brightness(LAMP2_GPIO, (int)(((float)(i + 1) / fade_duration) * PWM_RANGE));
        set_lamp_brightness(LAMP3_GPIO, (int)(((float)(i + 2) / fade_duration) * PWM_RANGE));

        printf("Lamp 1: %d%% | Lamp 2: %d%% | Lamp 3: %d%% | Progress: %d/%d seconds\n",
               (int)(((float)i / fade_duration) * 100.0f),
               (int)(((float)(i + 1) / fade_duration) * 100.0f),
               (int)(((float)(i + 2) / fade_duration) * 100.0f),
               i, fade_duration);

        sleep(1);
    }

    printf("\nCleaning up and exiting...\n");
    cleanup_gpio();
    printf("Smart Sunset Simulator stopped.\n");

    return EXIT_SUCCESS;
}

