#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip4"
#define RED_PIN 17
#define YELLOW_PIN 22
#define GREEN_PIN 23
#define BLUE_PIN 24

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4] = {NULL, NULL, NULL, NULL};
    int pins[4] = {RED_PIN, YELLOW_PIN, GREEN_PIN, BLUE_PIN};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        ret = gpiod_line_request_output(lines[i], "traffic-light", 1);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_request_output(%d): %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    while (running) {
        printf("State: Red\n");
        if (set_relay(lines[0], 0) < 0 || set_relay(lines[1], 1) < 0 ||
            set_relay(lines[2], 1) < 0 || set_relay(lines[3], 1) < 0) {
            goto cleanup;
        }
        sleep(10);

        printf("State: Red+Yellow\n");
        if (set_relay(lines[0], 0) < 0 || set_relay(lines[1], 0) < 0 ||
            set_relay(lines[2], 1) < 0 || set_relay(lines[3], 1) < 0) {
            goto cleanup;
        }
        sleep(2);

        printf("State: Green\n");
        if (set_relay(lines[0], 1) < 0 || set_relay(lines[1], 1) < 0 ||
            set_relay(lines[2], 0) < 0 || set_relay(lines[3], 1) < 0) {
            goto cleanup;
        }
        sleep(10);

        printf("State: Yellow\n");
        if (set_relay(lines[0], 1) < 0 || set_relay(lines[1], 0) < 0 ||
            set_relay(lines[2], 1) < 0 || set_relay(lines[3], 0) < 0) {
            goto cleanup;
        }
        sleep(3);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

