            fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        ret = gpiod_line_request_output(lines[i], "traffic-light", 1);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_request_output(%d): %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    while (running) {
        printf("State: Red\n");
        if (set_relay(lines[0], 0) < 0 || set_relay(lines[1], 1) < 0 ||
            set_relay(lines[2], 1) < 0 || set_relay(lines[3], 1) < 0) {
            goto cleanup;
        }
        sleep(10);

        printf("State: Red+Yellow\n");
        if (set_relay(lines[0], 0) < 0 || set_relay(lines[1], 0) < 0 ||
            set_relay(lines[2], 1) < 0 || set_relay(lines[3], 1) < 0) {
            goto cleanup;
        }
        sleep(2);

        printf("State: Green\n");
        if (set_relay(lines[0], 1) < 0 || set_relay(lines[1], 1) < 0 ||
            set_relay(lines[2], 0) < 0 || set_relay(lines[3], 1) < 0) {
            goto cleanup;
        }
        sleep(10);

        printf("State: Yellow\n");
        if (set_relay(lines[0], 1) < 0 || set_relay(lines[1], 0) < 0 ||
            set_relay(lines[2], 1) < 0 || set_relay(lines[3], 0) < 0) {
            goto cleanup;
        }
        sleep(3);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

