#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY_GPIO 17
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define DEBOUNCE_DELAY_MS 100
#define POLL_DELAY_MS 10

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioSetMode(RELAY_GPIO, PI_INPUT);
    if (log_file) {
        log_message("Program terminated cleanly.");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write error: reg=0x%02X, val=0x%02X, rc=%d", reg, value, rc);
        log_message(msg);
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write_reg(0x80, 0x63) < 0) return -1;
    gpioDelay(10000);
    if (mpr121_write_reg(0x5E, 0x00) < 0) return -1;
    if (mpr121_write_reg(0x5D, 0x01) < 0) return -1;
    if (mpr121_write_reg(0x41, 0x0A) < 0) return -1;
    if (mpr121_write_reg(0x42, 0x08) < 0) return -1;
    if (mpr121_write_reg(0x5B, 0x21) < 0) return -1;
    if (mpr121_write_reg(0x5C, 0x0D) < 0) return -1;
    if (mpr121_write_reg(0x5E, 0x0D) < 0) return -1;
    return 0;
}

static int read_touch_status(uint16_t *touch_status) {
    int lsb = i2cReadByteData(i2c_handle, 0x00);
    if (lsb < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C read error (LSB): rc=%d", lsb);
        log_message(msg);
        return -1;
    }
    int msb = i2cReadByteData(i2c_handle, 0x01);
    if (msb < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C read error (MSB): rc=%d", msb);
        log_message(msg);
        return -1;
    }
    *touch_status = (uint16_t)((msb << 8) | lsb);
    return 0;
}

int main(void) {
    log_file = fopen("touch_relay.log", "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        fclose(log_file);
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to open I2C device at 0x%02X: rc=%d", MPR121_ADDR, i2c_handle);
        log_message(msg);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    if (mpr121_init() < 0) {
        log_message("MPR121 initialisation failed");
        cleanup();
        return 1;
    }

    log_message("Program started.");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t prev_touch = 0;
    int relay_state = 0;

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            gpioDelay(POLL_DELAY_MS * 1000);
            continue;
        }

        uint16_t new_touch = touch_status & 0x01;
        if (new_touch != prev_touch) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            if (read_touch_status(&touch_status) < 0) {
                gpioDelay(POLL_DELAY_MS * 1000);
                continue;
            }
            new_touch = touch_status & 0x01;
        }

        if (new_touch && !relay_state) {
            relay_state = 1;
            gpioWrite(RELAY_GPIO, 1);
            log_message("Relay turned ON");
        } else if (!new_touch && relay_state) {
            relay_state = 0;
            gpioWrite(RELAY_GPIO, 0);
            log_message("Relay turned OFF");
        }

        prev_touch = new_touch;
        gpioDelay(POLL_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

