#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23
#define LOG_FILE "flame_log.txt"
#define DEBOUNCE_READINGS 3
#define DEBOUNCE_DELAY_MS 50
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

static int log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int ret;
    int flame_detected = 0;
    int last_flame_state = 1;
    int debounce_count = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        fprintf(stderr, "Error getting flame sensor line (GPIO%d): %s\n", FLAME_SENSOR_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line (GPIO%d): %s\n", BUZZER_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line (GPIO%d): %s\n", LED_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(flame_line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting flame sensor line as input: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Fire alarm system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int current_flame_state = gpiod_line_get_value(flame_line);
        if (current_flame_state < 0) {
            fprintf(stderr, "Error reading flame sensor: %s\n", strerror(errno));
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (current_flame_state == 0 && last_flame_state == 1) {
            debounce_count++;
            if (debounce_count >= DEBOUNCE_READINGS) {
                flame_detected = 1;
                printf("Flame detected!\n");
            }
        } else if (current_flame_state == 1 && last_flame_state == 0) {
            debounce_count--;
            if (debounce_count < 0) {
                debounce_count = 0;
            }
        }

        last_flame_state = current_flame_state;

        if (flame_detected) {
            ret = gpiod_line_set_value(buzzer_line, 1);
            if (ret < 0) {
                fprintf(stderr, "Error activating buzzer: %s\n", strerror(errno));
            }

            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
                fprintf(stderr, "Error activating LED: %s\n", strerror(errno));
            }

            if (log_event("Flame Detected") != 0) {
                fprintf(stderr, "Warning: failed to log flame event\n");
            }

            while (program_running && flame_detected) {
                usleep(POLL_INTERVAL_MS * 1000);
                current_flame_state = gpiod_line_get_value(flame_line);
                if (current_flame_state < 0) {
                    fprintf(stderr, "Error reading flame sensor during alarm: %s\n", strerror(errno));
                    flame_detected = 0;
                    break;
                }
                if (current_flame_state == 0) {
                    flame_detected = 0;
                }
            }

            ret = gpiod_line_set_value(buzzer_line, 0);
            if (ret < 0) {
                fprintf(stderr, "Error deactivating buzzer: %s\n", strerror(errno));
            }

            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                fprintf(stderr, "Error deactivating LED: %s\n", strerror(errno));
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

