        fprintf(stderr, "Error getting LED line (GPIO%d): %s\n", LED_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(flame_line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting flame sensor line as input: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Fire alarm system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int current_flame_state = gpiod_line_get_value(flame_line);
        if (current_flame_state < 0) {
            fprintf(stderr, "Error reading flame sensor: %s\n", strerror(errno));
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (current_flame_state == 0 && last_flame_state == 1) {
            debounce_count++;
            if (debounce_count >= DEBOUNCE_READINGS) {
                flame_detected = 1;
                printf("Flame detected!\n");
            }
        } else if (current_flame_state == 1 && last_flame_state == 0) {
            debounce_count--;
            if (debounce_count < 0) {
                debounce_count = 0;
            }
        }

        last_flame_state = current_flame_state;

        if (flame_detected) {
            ret = gpiod_line_set_value(buzzer_line, 1);
            if (ret < 0) {
                fprintf(stderr, "Error activating buzzer: %s\n", strerror(errno));
            }

            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
                fprintf(stderr, "Error activating LED: %s\n", strerror(errno));
            }

            if (log_event("Flame Detected") != 0) {
                fprintf(stderr, "Warning: failed to log flame event\n");
            }

            while (program_running && flame_detected) {
                usleep(POLL_INTERVAL_MS * 1000);
                current_flame_state = gpiod_line_get_value(flame_line);
                if (current_flame_state < 0) {
                    fprintf(stderr, "Error reading flame sensor during alarm: %s\n", strerror(errno));
                    flame_detected = 0;
                    break;
                }
                if (current_flame_state == 0) {
                    flame_detected = 0;
                }
            }

            ret = gpiod_line_set_value(buzzer_line, 0);
            if (ret < 0) {
                fprintf(stderr, "Error deactivating buzzer: %s\n", strerror(errno));
            }

            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                fprintf(stderr, "Error deactivating LED: %s\n", strerror(errno));
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

