#include <string.h>
#include <errno.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DISPENSE_DURATION_MS 5000
#define HALF_DISPENSE_DURATION_MS (DISPENSE_DURATION_MS / 2)
#define DISPENSE_INTERVAL_US (DISPENSE_DURATION_MS * 1000)

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int activate_solenoid(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to activate solenoid on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static int deactivate_solenoid(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to deactivate solenoid on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static int dispense(int solenoid_pin, int duration_ms) {
    if (activate_solenoid(solenoid_pin) != 0) {
        return -1;
    }
    gpioDelay(duration_ms * 1000);
    if (deactivate_solenoid(solenoid_pin) != 0) {
        return -1;
    }
    return 0;
}

static int log_dispense(int solenoid_pin, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open dispense_log.txt: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - Solenoid %d dispensed for %d ms\n", timestamp, solenoid_pin, duration_ms);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pneumatic dispensing system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (dispense(SOLENOID_1_PIN, HALF_DISPENSE_DURATION_MS) != 0) {
            break;
        }
        if (!running) break;

        if (dispense(SOLENOID_2_PIN, HALF_DISPENSE_DURATION_MS) != 0) {
            break;
        }

        if (log_dispense(SOLENOID_1_PIN, HALF_DISPENSE_DURATION_MS) != 0) {
            break;
        }
        if (!running) break;

        if (log_dispense(SOLENOID_2_PIN, HALF_DISPENSE_DURATION_MS) != 0) {
            break;
        }

        gpioDelay(DISPENSE_INTERVAL_US);
    }

