#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_A_ENABLE 24
#define MOTOR_B_ENABLE 25

#define KP 1.0
#define KI 0.01
#define KD 0.1

#define MIN_SPEED 0
#define MAX_SPEED 255
#define OBSTACLE_THRESHOLD 20.0
#define DISTANCE_MIN 2.0
#define DISTANCE_MAX 400.0
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(MOTOR_A_ENABLE, 255) != 0 ||
        gpioSetPWMrange(MOTOR_B_ENABLE, 255) != 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(MOTOR_A_ENABLE, 1) != 0 ||
        gpioWrite(MOTOR_B_ENABLE, 1) != 0) {
        fprintf(stderr, "Error: failed to enable motors\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

static void set_motor_speed(int motor, int speed) {
    if (speed < MIN_SPEED) speed = MIN_SPEED;
    if (speed > MAX_SPEED) speed = MAX_SPEED;

    if (motor == 1) {
        gpioWrite(MOTOR_A_FORWARD, (speed > 0) ? 1 : 0);
        gpioWrite(MOTOR_A_BACKWARD, (speed < 0) ? 1 : 0);
        gpioPWM(MOTOR_A_ENABLE, abs(speed));
    } else if (motor == 2) {
        gpioWrite(MOTOR_B_FORWARD, (speed > 0) ? 1 : 0);
        gpioWrite(MOTOR_B_BACKWARD, (speed < 0) ? 1 : 0);
        gpioPWM(MOTOR_B_ENABLE, abs(speed));
    } else {
        fprintf(stderr, "Error: invalid motor number %d\n", motor);
    }
}

static void stop_motors(void) {
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
}

static float get_tilt_error(void) {
    return (float)(rand() % 21) - 10.0;
}

static float get_distance(void) {
    return (float)(rand() % 381) + DISTANCE_MIN;
}

static void control_motors(float tilt_error, float distance) {
    float integral = 0.0;
    static float previous_error = 0.0;
    float derivative;
    float motor_a_speed, motor_b_speed;

    integral += tilt_error;
    derivative = tilt_error - previous_error;
    previous_error = tilt_error;

    motor_a_speed = KP * tilt_error + KI * integral + KD * derivative;
    motor_b_speed = KP * tilt_error + KI * integral + KD * derivative;

    if (distance < OBSTACLE_THRESHOLD) {
        motor_a_speed *= 0.5;
        motor_b_speed *= 0.5;
    }

    set_motor_speed(1, (int)motor_a_speed);
    set_motor_speed(2, (int)motor_b_speed);
}

static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

int main(void) {
    srand((unsigned int)time(NULL));

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Self-balancing robot started. Press Ctrl+C to exit.\n");

    while (running) {
        float tilt_error = get_tilt_error();
        float distance = get_distance();

        control_motors(tilt_error, distance);
        log_data(tilt_error, distance, gpioGetPWMdutycycle(MOTOR_A_ENABLE), gpioGetPWMdutycycle(MOTOR_B_ENABLE));

        gpioDelay(LOOP_DELAY_US);
    }

    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Self-balancing robot stopped.\n");
    return 0;
}

