#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define TOUCH_SENSOR_GPIO 4
#define DEBOUNCE_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", RELAY_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-down on touch sensor (TTP223 has its own pull-down) */
    if (gpioSetPullUpDown(TOUCH_SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: Failed to set pull-down on GPIO%d.\n", TOUCH_SENSOR_GPIO);
    }

    /* Ensure relay starts in the OFF state */
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialise relay state on GPIO%d.\n", RELAY_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    /* Ensure relay is OFF before terminating pigpio */
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Smart Light Switch running. Press Ctrl+C to exit.\n");

    while (running) {
