                fprintf(stderr, "Error: snd_pcm_resume failed: %s\n", strerror(errno));
                return -1;
            }
        } else {
            fprintf(stderr, "Error: snd_pcm_readi failed: %s\n", strerror(errno));
            return -1;
        }
        return 0;
    }

    if (n != (int)SAMPLE_SIZE) {
        fprintf(stderr, "Warning: short read (%d of %d frames)\n", n, SAMPLE_SIZE);
        return 0;
    }

    *amplitude = 0.0;
    for (size_t i = 0; i < SAMPLE_SIZE; i++) {
        int16_t sample = ac->buffer[i * 2];
        *amplitude += (double)sample * sample;
    }
    *amplitude /= SAMPLE_SIZE;
    *amplitude = sqrt(*amplitude);

    return 0;
}

static void cleanup_audio_capture(audio_capture_t *ac)
{
    if (ac->handle) {
        snd_pcm_drain(ac->handle);
        snd_pcm_close(ac->handle);
        ac->handle = NULL;
    }
    if (ac->params) {
        snd_pcm_hw_params_free(ac->params);
        ac->params = NULL;
    }
    if (ac->buffer) {
        free(ac->buffer);
        ac->buffer = NULL;
    }
    if (ac->samples) {
        free(ac->samples);
        ac->samples = NULL;
    }
}

/* ----------------------------- Color mapping ----------------------------- */

static void map_amplitude_to_color(double amplitude, uint8_t *r, uint8_t *g, uint8_t *b)
{
    if (amplitude < 0.0) amplitude = 0.0;
    if (amplitude > 1.0) amplitude = 1.0;

    /* Non-linear transition: cool for low amplitude, warm for high */
    double t = 1.0 - (amplitude * amplitude);
    if (t < 0.0) t = 0.0;
    if (t > 1.0) t = 1.0;

    *r = (uint8_t)(t * 255.0);
    *g = (uint8_t)((1.0 - t) * 255.0);
    *b = 0;
}

/* ----------------------------- pigpio PWM helpers ----------------------------- */

static int set_pwm_range(int pin, int range)
{
    if (gpioSetPWMrange(pin, range) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d, %d) failed\n", pin, range);
        return -1;
    }
    return 0;
}

static int set_pwm_frequency(int pin, int freq)
{
    if (gpioSetPWMfrequency(pin, freq) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d, %d) failed\n", pin, freq);
        return -1;
    }
    return 0;
}

static int set_pwm_value(int pin, int value)
{
    if (gpioPWM(pin, value) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", pin, value);
        return -1;
    }
    return 0;
}

/* ----------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main ----------------------------------- */

int main(int argc, char *argv[])
{
    double sensitivity = DEFAULT_SENSITIVITY;

    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0.0) {
            fprintf(stderr, "Error: sensitivity must be positive, got %.2f\n", sensitivity);
            return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_pwm_range(RED_PIN, PWM_RANGE) < 0 ||
        set_pwm_range(GREEN_PIN, PWM_RANGE) < 0 ||
        set_pwm_range(BLUE_PIN, PWM_RANGE) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_pwm_frequency(RED_PIN, PWM_FREQ) < 0 ||
        set_pwm_frequency(GREEN_PIN, PWM_FREQ) < 0 ||
        set_pwm_frequency(BLUE_PIN, PWM_FREQ) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    audio_capture_t ac;
    if (init_audio_capture(&ac) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Mood light started. Press Ctrl+C to exit.\n");
    printf("Sensitivity: %.2f\n", sensitivity);

    while (g_running) {
        double amplitude = 0.0;
#ifndef ALSA_AVAILABLE
        amplitude = simulate_noise();
#else
        if (read_audio_capture(&ac, &amplitude) < 0) {
            fprintf(stderr, "Error: audio capture read failed, exiting\n");
            break;
        }
#endif

        uint8_t r, g, b;
        map_amplitude_to_color(amplitude * sensitivity, &r, &g, &b);

        if (set_pwm_value(RED_PIN, r) < 0 ||
            set_pwm_value(GREEN_PIN, g) < 0 ||
            set_pwm_value(BLUE_PIN, b) < 0) {
            fprintf(stderr, "Error: PWM write failed, exiting\n");
            break;
        }

        gpioDelay(10000); /* 10 ms */
    }

    cleanup_audio_capture(&ac);
    gpioTerminate();
    printf("\nMood light stopped.\n");
    return EXIT_SUCCESS;
}

