#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TCS34725_ADDR 0x29
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 500000
#define LOG_FILE "color_data.csv"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int tcs34725_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int tcs34725_read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int tcs34725_init(int handle) {
    if (tcs34725_write_reg(handle, TCS34725_ENABLE, 0x00) < 0) return -1;
    gpioDelay(3000);
    if (tcs34725_write_reg(handle, TCS34725_ATIME, 0xD5) < 0) return -1;
    if (tcs34725_write_reg(handle, TCS34725_ENABLE, 0x03) < 0) return -1;
    gpioDelay(3000);
    return 0;
}

static int tcs34725_read_color(int handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t c_low, c_high, r_low, r_high, g_low, g_high, b_low, b_high;
    if (tcs34725_read_reg(handle, TCS34725_CDATA, &c_low) < 0) return -1;
    if (tcs34725_read_reg(handle, TCS34725_CDATA + 1, &c_high) < 0) return -1;
    if (tcs34725_read_reg(handle, TCS34725_RDATA, &r_low) < 0) return -1;
    if (tcs34725_read_reg(handle, TCS34725_RDATA + 1, &r_high) < 0) return -1;
    if (tcs34725_read_reg(handle, TCS34725_GDATA, &g_low) < 0) return -1;
    if (tcs34725_read_reg(handle, TCS34725_GDATA + 1, &g_high) < 0) return -1;
    if (tcs34725_read_reg(handle, TCS34725_BDATA, &b_low) < 0) return -1;
    if (tcs34725_read_reg(handle, TCS34725_BDATA + 1, &b_high) < 0) return -1;
    *clear = (uint16_t)((c_high << 8) | c_low);
    *red = (uint16_t)((r_high << 8) | r_low);
    *green = (uint16_t)((g_high << 8) | g_low);
    *blue = (uint16_t)((b_high << 8) | b_low);
    return 0;
}

static void log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t now = time(NULL);
    fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)now, clear, red, green, blue);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, TCS34725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, TCS34725_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (tcs34725_init(i2c_handle) < 0) {
        fprintf(stderr, "TCS34725 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,clear,red,green,blue\n");
        fflush(log_file);
    }

    uint16_t clear, red, green, blue;
    while (running) {
        if (tcs34725_read_color(i2c_handle, &clear, &red, &green, &blue) == 0) {
            log_data(log_file, clear, red, green, blue);
        } else {
            fprintf(stderr, "Failed to read color data, setting values to 0\n");
            clear = red = green = blue = 0;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

