#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define RELAY1_PIN 11
#define RELAY2_PIN 13
#define RELAY3_PIN 15
#define RELAY4_PIN 17

#define NUM_RELAYS 4
#define PWM_PERIOD_MS 100
#define PWM_DUTY_CYCLE_MS 50

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(struct gpiod_line *line, int pin, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting GPIO %d to %d: %s\n", pin, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int set_all_relays(struct gpiod_line *lines[], int values[]) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (set_relay(lines[i], RELAY1_PIN + i, values[i]) < 0) {
            return -1;
        }
    }
    return 0;
}

static void sleep_ms(int ms) {
    struct timespec ts = {
        .tv_sec = ms / 1000,
        .tv_nsec = (ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int values[NUM_RELAYS];
    int phase = 0;
    int duty_cycle_ms = PWM_DUTY_CYCLE_MS;
    int period_ms = PWM_PERIOD_MS;
    int elapsed_ms = 0;

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "sunrise-simulator", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Sunrise simulator started. Press Ctrl+C to exit.\n");

    while (running) {
        switch (phase) {
            case 0:
                printf("Sunrise phase started.\n");
                for (int i = 0; i < NUM_RELAYS; i++) {
                    values[i] = 1;
                }
                if (set_all_relays(lines, values) < 0) {
                    goto cleanup;
                }
                elapsed_ms = 0;
                break;
            case 1:
                printf("Daytime phase started.\n");
                for (int i = 0; i < NUM_RELAYS; i++) {
                    values[i] = 1;
                }
                if (set_all_relays(lines, values) < 0) {
                    goto cleanup;
                }
                elapsed_ms = 0;
                break;
            case 2:
                printf("Sunset phase started.\n");
                for (int i = 0; i < NUM_RELAYS; i++) {
                    values[i] = 0;
                }
                if (set_all_relays(lines, values) < 0) {
                    goto cleanup;
                }
                elapsed_ms = 0;
                break;
            case 3:
                printf("Nighttime phase started.\n");
                for (int i = 0; i < NUM_RELAYS; i++) {
                    values[i] = 0;
                }
                if (set_all_relays(lines, values) < 0) {
                    goto cleanup;
                }
                elapsed_ms = 0;
                break;
        }

        while (running && elapsed_ms < period_ms) {
            if (set_all_relays(lines, values) < 0) {
                goto cleanup;
            }
            sleep_ms(duty_cycle_ms);
            elapsed_ms += duty_cycle_ms;
        }

        if (running) {
            phase = (phase + 1) % 4;
        }
    }

cleanup:
    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            set_relay(lines[i], pins[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Sunrise simulator stopped.\n");
    return EXIT_SUCCESS;
}

