#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTION_SENSOR_GPIO 17
#define VIDEO_DURATION_SEC 5
#define DEBOUNCE_DELAY_US 200000
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int get_timestamp(char *timestamp_str, size_t max_len) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }

    if (strftime(timestamp_str, max_len, "%Y%m%d_%H%M%S", timeinfo) == 0) {
        return -1;
    }

    return 0;
}

static int record_video(const char *timestamp) {
    char filename[64];
    char command[256];

    snprintf(filename, sizeof(filename), "%s/%s.h264", VIDEO_DIR, timestamp);

    snprintf(command, sizeof(command),
             "raspivid -o %s -t %d000", filename, VIDEO_DURATION_SEC * 1000);

    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error executing raspivid: %s\n", strerror(errno));
        return -1;
    } else if (!WIFEXITED(result) || WEXITSTATUS(result) != 0) {
        fprintf(stderr, "raspivid failed with exit code %d\n", WEXITSTATUS(result));
        return -1;
    }

    return 0;
}

static int log_motion_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Motion detected!\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    char timestamp[32];
    int last_motion_detected = 0;
    uint32_t last_trigger_tick = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(MOTION_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(MOTION_SENSOR_GPIO, PI_PUD_UP);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int motion_detected = gpioRead(MOTION_SENSOR_GPIO);

        if (motion_detected < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", MOTION_SENSOR_GPIO);
            gpioDelay(100000);
            continue;
        }

        if (motion_detected == 0 && last_motion_detected == 1) {
            uint32_t current_tick = gpioTick();

            if (current_tick - last_trigger_tick >= DEBOUNCE_DELAY_US) {
                if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                    if (record_video(timestamp) == 0) {
                        printf("Video recorded: %s\n", timestamp);
                    } else {
                        fprintf(stderr, "Failed to record video.\n");
                    }

                    if (log_motion_event(timestamp) == 0) {
                        printf("Motion event logged: %s\n", timestamp);
                    } else {
                        fprintf(stderr, "Failed to log motion event.\n");
                    }
                } else {
                    fprintf(stderr, "Failed to get timestamp.\n");
                }

                last_trigger_tick = current_tick;
            }
        }

        last_motion_detected = motion_detected;
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

