#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* MPU-6050 I2C address (AD0 low) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43

/* Sensitivity for ±250°/s range: 131 LSB/°/s */
#define GYRO_SENSITIVITY 131.0f

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Initialize the MPU-6050 sensor */
static int init_mpu6050(void) {
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to wake up MPU-6050 (pigpio error %d)\n",
                i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00));
        return -1;
    }

    /* Set sample rate divider to 125 Hz (1 kHz / (1 + 125) = 125 Hz) */
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 125) < 0) {
        fprintf(stderr, "Error: Failed to set sample rate divider (pigpio error %d)\n",
                i2cWriteByteData(i2c_handle, SMPLRT_DIV, 125));
        return -1;
    }

    /* Set gyroscope full-scale range to ±250°/s (FS_SEL = 0) */
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set gyroscope full-scale range (pigpio error %d)\n",
                i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00));
        return -1;
    }

    return 0;
}

/* Read raw gyroscope data from the MPU-6050 */
static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    /* Read 6 bytes starting from GYRO_XOUT_H (0x43) using a combined I2C block read */
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6) != 6) {
        fprintf(stderr, "Error: Failed to read gyroscope data (pigpio error %d)\n",
                i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6));
        return -1;
    }

    /* Combine high and low bytes (big-endian) */
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

/* Convert raw gyroscope data to degrees per second */
static void convert_to_degrees_per_second(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                                          float *x_dps, float *y_dps, float *z_dps) {
    *x_dps = (float)raw_x / GYRO_SENSITIVITY;
    *y_dps = (float)raw_y / GYRO_SENSITIVITY;
    *z_dps = (float)raw_z / GYRO_SENSITIVITY;
}

/* Log data to a CSV file */
static void log_data(float x_dps, float y_dps, float z_dps) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error: Failed to get timestamp: %s\n", strerror(errno));
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_file, "%s.%03ld,%.2f,%.2f,%.2f\n",
            timestamp, ts.tv_nsec / 1000000, x_dps, y_dps, z_dps);
    fflush(log_file);
}

/* Re-initialize the MPU-6050 sensor after a failure */
static int reinit_mpu6050(void) {
    fprintf(stderr, "Re-initializing MPU-6050...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    gpioDelay(100000); /* 100 ms delay before re-opening I2C */

    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to re-open I2C bus (pigpio error %d)\n", i2c_handle);
        return -1;
    }

    if (init_mpu6050() != 0) {
        fprintf(stderr, "Error: MPU-6050 re-initialization failed\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    fprintf(stderr, "MPU-6050 re-initialized successfully\n");
    return 0;
}

int main(void) {
    int16_t raw_x, raw_y, raw_z;
    float x_dps, y_dps, z_dps;
    int consecutive_errors = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus (pigpio error %d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 sensor */
    if (init_mpu6050() != 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if the file is newly created */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
        fflush(log_file);
    }

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to set SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to set SIGTERM handler: %s\n", strerror(errno));
    }

    /* Main loop */
    while (!terminate) {
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            convert_to_degrees_per_second(raw_x, raw_y, raw_z, &x_dps, &y_dps, &z_dps);
            log_data(x_dps, y_dps, z_dps);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error: Failed to read gyroscope data (attempt %d)\n",
                    consecutive_errors);

            if (consecutive_errors >= 3) {
                fprintf(stderr, "Fatal: Max consecutive errors reached. Re-initializing...\n");
                if (reinit_mpu6050() != 0) {
                    fprintf(stderr, "Fatal: Re-initialization failed. Exiting.\n");
                    break;
                }
                consecutive_errors = 0;
            }
        }

        gpioDelay(10000); /* 10 ms delay (100 Hz sampling) */
    }

    /* Cleanup */
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

