    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    gpioDelay(100000); /* 100 ms delay before re-opening I2C */

    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to re-open I2C bus (pigpio error %d)\n", i2c_handle);
        return -1;
    }

    if (init_mpu6050() != 0) {
        fprintf(stderr, "Error: MPU-6050 re-initialization failed\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    fprintf(stderr, "MPU-6050 re-initialized successfully\n");
    return 0;
}

int main(void) {
    int16_t raw_x, raw_y, raw_z;
    float x_dps, y_dps, z_dps;
    int consecutive_errors = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus (pigpio error %d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 sensor */
    if (init_mpu6050() != 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if the file is newly created */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
        fflush(log_file);
    }

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to set SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to set SIGTERM handler: %s\n", strerror(errno));
    }

    /* Main loop */
    while (!terminate) {
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            convert_to_degrees_per_second(raw_x, raw_y, raw_z, &x_dps, &y_dps, &z_dps);
            log_data(x_dps, y_dps, z_dps);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error: Failed to read gyroscope data (attempt %d)\n",
                    consecutive_errors);

            if (consecutive_errors >= 3) {
                fprintf(stderr, "Fatal: Max consecutive errors reached. Re-initializing...\n");
                if (reinit_mpu6050() != 0) {
                    fprintf(stderr, "Fatal: Re-initialization failed. Exiting.\n");
                    break;
                }
                consecutive_errors = 0;
            }
        }

        gpioDelay(10000); /* 10 ms delay (100 Hz sampling) */
    }

    /* Cleanup */
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

