#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RELAY_1 4
#define RELAY_2 17
#define RELAY_3 27
#define RELAY_4 22
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    int pins[] = {RELAY_1, RELAY_2, RELAY_3, RELAY_4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialize GPIO %d HIGH.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_moisture_sensor(void) {
    return rand() % 101;
}

static int control_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d to %d.\n", pin, state);
        return -1;
    }
    return 0;
}

static void log_data(int zone, int moisture, int relay_state, const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: log file not open.\n");
        return;
    }
    if (fprintf(log_file, "%d, %d, %d, %s\n", zone, moisture, relay_state, timestamp) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
    }
    fflush(log_file);
}

static void cleanup(void) {
    int pins[] = {RELAY_1, RELAY_2, RELAY_3, RELAY_4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        gpioWrite(pins[i], 1);
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart Greenhouse Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        if (timeinfo == NULL) {
            fprintf(stderr, "Error: localtime failed.\n");
            break;
        }

        if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
            fprintf(stderr, "Error: strftime failed.\n");
            break;
        }

        int moisture = read_moisture_sensor();
        int relay_state = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;

        if (control_relay(RELAY_1, relay_state) != 0) break;
        if (control_relay(RELAY_2, relay_state) != 0) break;
        if (control_relay(RELAY_3, relay_state) != 0) break;
        if (control_relay(RELAY_4, relay_state) != 0) break;

        log_data(1, moisture, relay_state, timestamp);
        log_data(2, moisture, relay_state, timestamp);
        log_data(3, moisture, relay_state, timestamp);
        log_data(4, moisture, relay_state, timestamp);

        printf("Zone 1: Moisture=%d, Relay=%s\n", moisture, relay_state ? "ON" : "OFF");
        printf("Zone 2: Moisture=%d, Relay=%s\n", moisture, relay_state ? "ON" : "OFF");
        printf("Zone 3: Moisture=%d, Relay=%s\n", moisture, relay_state ? "ON" : "OFF");
        printf("Zone 4: Moisture=%d, Relay=%s\n", moisture, relay_state ? "ON" : "OFF");

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

