#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

/* ADXL345 I2C address */
#define ADXL345_ADDR 0x53

/* ADXL345 registers */
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32

/* Freefall detection parameters */
#define FREEFALL_THRESHOLD 0.2f
#define FREEFALL_DURATION_MS 500
#define FREEFALL_CONFIRM_MS 500
#define SAMPLE_INTERVAL_MS 100

/* GPIO pin for alarm */
#define ALARM_PIN 27

/* Global variables for cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int adxl345_init(int handle);
static int adxl345_read_data(int handle, float *x, float *y, float *z);
static int detect_freefall(float x, float y, float z);
static void trigger_alarm(int pin);
static void log_freefall(float x, float y, float z);
static void signal_handler(int signal);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Initialize the ADXL345 sensor */
static int adxl345_init(int handle) {
    /* Set data format: ±2g, full resolution */
    if (i2cWriteByteData(handle, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    /* Enable measurement mode */
    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

/* Read accelerometer data from the ADXL345 */
static int adxl345_read_data(int handle, float *x, float *y, float *z) {
    char buffer[6];

    /* Read 6 bytes starting from DATAX0 (0x32) */
    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    /* Combine high and low bytes for each axis (little-endian) */
    int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    /* Convert to g-force using full resolution: 256 LSB/g */
    *x = (float)x_raw / 256.0f;
    *y = (float)y_raw / 256.0f;
    *z = (float)z_raw / 256.0f;

    return 0;
}

/* Detect freefall based on three axes */
static int detect_freefall(float x, float y, float z) {
    return (fabsf(x) < FREEFALL_THRESHOLD &&
            fabsf(y) < FREEFALL_THRESHOLD &&
            fabsf(z) < FREEFALL_THRESHOLD);
}

/* Trigger the alarm */
static void trigger_alarm(int pin) {
    gpioWrite(pin, 1);
    gpioDelay(ALARM_DURATION_MS * 1000);
    gpioWrite(pin, 0);
}

/* Log freefall event to file */
static void log_freefall(float x, float y, float z) {
    FILE *fp = fopen("freefall.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening freefall.log for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec,
            x, y, z);

    fclose(fp);
}

int main() {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C connection to ADXL345 */
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize ADXL345 */
    if (adxl345_init(i2c_handle) < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Configure GPIO pin for alarm */
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0);

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Freefall detection started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        float x, y, z;

        if (adxl345_read_data(i2c_handle, &x, &y, &z) == 0) {
            if (detect_freefall(x, y, z)) {
                printf("Freefall detected! X: %.3f g, Y: %.3f g, Z: %.3f g\n", x, y, z);

                /* Trigger alarm */
                trigger_alarm(ALARM_PIN);

                /* Confirm freefall by reading twice with delay */
                gpioDelay(FREEFALL_CONFIRM_MS * 1000);
                if (!terminate) {
                    float x2, y2, z2;
                    if (adxl345_read_data(i2c_handle, &x2, &y2, &z2) == 0) {
                        if (detect_freefall(x2, y2, z2)) {
                            printf("Freefall confirmed!\n");
                            log_freefall(x, y, z);
                        }
                    }
                }
            }
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    gpioWrite(ALARM_PIN, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

