#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 18
#define MAX_DISTANCE_CM 400.0
#define TIMEOUT_US 100000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US 200000
#define ECHO_TIMEOUT_US 23200

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick = 0;
static volatile int g_echo_received = 0;
static volatile int g_echo_timeout = 0;
static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *g_log_file = NULL;
static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_start_tick = tick;
        g_echo_received = 0;
        g_echo_timeout = 0;
    } else if (level == 0) {
        g_end_tick = tick;
        g_echo_received = 1;
    }
}

static void cleanup(void) {
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    pthread_mutex_destroy(&g_mutex);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize TRIGGER_PIN %d low.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to set alert function for ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int initialize_logging(void) {
    g_log_file = fopen("distance_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: failed to open distance_log.txt: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int measure_distance(float *distance_cm) {
    pthread_mutex_lock(&g_mutex);
    g_echo_received = 0;
    g_echo_timeout = 0;
    pthread_mutex_unlock(&g_mutex);

    trigger_sensor();

    uint32_t start_wait = gpioTick();
    while (!g_echo_received && !g_echo_timeout) {
        if ((gpioTick() - start_wait) > TIMEOUT_US) {
            pthread_mutex_lock(&g_mutex);
            g_echo_timeout = 1;
            pthread_mutex_unlock(&g_mutex);
            return -1;
        }
        gpioDelay(100);
    }

    if (g_echo_timeout) {
        pthread_mutex_lock(&g_mutex);
        g_echo_timeout = 0;
        pthread_mutex_unlock(&g_mutex);
        return -1;
    }

    uint32_t pulse_width = g_end_tick - g_start_tick;
    pthread_mutex_lock(&g_mutex);
    g_echo_received = 0;
    g_echo_timeout = 0;
    pthread_mutex_unlock(&g_mutex);

    if (pulse_width == 0) {
        return -1;
    }

    float distance = (float)pulse_width / 58.0f;
    if (distance > MAX_DISTANCE_CM) {
        return -1;
    }

    *distance_cm = distance;
    return 0;
}

static void log_distance(float distance_cm) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log_file, "%s.%09ld,%.2f\n", timestamp, ts.tv_nsec, distance_cm);
    fflush(g_log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    if (initialize_logging() != 0) {
        cleanup();
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance;
        if (measure_distance(&distance) == 0) {
            log_distance(distance);
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Warning: measurement failed or timeout.\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

