#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LIS3DH I2C address
#define LIS3DH_ADDR 0x18

// LIS3DH registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28

// GPIO pin for buzzer
#define BUZZER_PIN 17

// Default thresholds (in g)
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 1.5f

// Sensitivity for +/-2g range (16384 LSB/g)
#define SENSITIVITY 16384.0f

// I2C bus
#define I2C_BUS 1

// Retry count for I2C communication
#define I2C_RETRY_COUNT 3

// Global variables for cleanup
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(void);
int init_lis3dh(void);
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void trigger_buzzer(int duration_ms);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

// Initialize I2C communication
int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", LIS3DH_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize LIS3DH accelerometer
int init_lis3dh(void) {
    // CTRL_REG1: 100 Hz data rate, normal mode, all axes enabled
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // CTRL_REG4: +/-2g full scale, high resolution disabled
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from LIS3DH
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result;

    // Read 6 bytes starting from OUT_X_L (0x28)
    result = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        return -1;
    }

    // Combine high and low bytes (little-endian)
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate acceleration magnitude in g
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrtf((float)(x * x + y * y + z * z)) / SENSITIVITY;
}

// Trigger the buzzer for a specified duration
void trigger_buzzer(int duration_ms) {
    gpioWrite(BUZZER_PIN, 1);
    gpioDelay(duration_ms * 1000); // Convert ms to microseconds
    gpioWrite(BUZZER_PIN, 0);
}

int main(int argc, char *argv[]) {
    int16_t x, y, z;
    float magnitude;
    int freefall_detected = 0;
    int impact_detected = 0;
    int i2c_error_count = 0;

    // Parse command-line arguments
    if (argc > 1) {
        FREEFALL_THRESHOLD = atof(argv[1]);
    }
    if (argc > 2) {
        IMPACT_THRESHOLD = atof(argv[2]);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("LIS3DH Fall Detection System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            i2c_error_count = 0;

            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for freefall
            if (magnitude < FREEFALL_THRESHOLD) {
                if (!freefall_detected) {
                    printf("Freefall detected! Magnitude: %.2f g\n", magnitude);
                    freefall_detected = 1;
                }
            } else {
                freefall_detected = 0;
            }

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                if (!impact_detected) {
                    printf("Impact detected! Magnitude: %.2f g\n", magnitude);
                    impact_detected = 1;
                    trigger_buzzer(1000); // Activate buzzer for 1 second
                }
            } else {
                impact_detected = 0;
            }
        } else {
            i2c_error_count++;
            fprintf(stderr, "I2C read error count: %d\n", i2c_error_count);

            if (i2c_error_count >= I2C_RETRY_COUNT) {
                fprintf(stderr, "I2C communication failed after %d retries. Exiting.\n", I2C_RETRY_COUNT);
                break;
            }
        }

        gpioDelay(10000); // 10ms delay to reduce CPU usage
    }

    // Cleanup
    cleanup();

    printf("Program terminated.\n");
    return 0;
}

