#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LIS3DH_ADDR_DEFAULT 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

#define DEFAULT_THRESHOLD 2.0f
#define LOG_FILE "/var/log/high_acceleration.log"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_lis3dh(int handle) {
    /* CTRL_REG1: 100 Hz ODR, high-resolution mode, normal mode */
    if (i2cWriteByteData(handle, CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG1\n");
        return -1;
    }
    /* CTRL_REG4: 12-bit left-justified, ±2g range */
    if (i2cWriteByteData(handle, CTRL_REG4, 0x88) < 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG4\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(handle, OUT_X_L, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read acceleration data\n");
        return -1;
    }

    raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    /* 12-bit left-justified: shift right 4 */
    *x = (float)raw_x >> 4;
    *y = (float)raw_y >> 4;
    *z = (float)raw_z >> 4;

    /* Convert to g: 2g range -> 2048 LSB/g */
    *x *= 0.0009765625f;
    *y *= 0.0009765625f;
    *z *= 0.0009765625f;

    return 0;
}

static void log_event(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %.4f g, Y: %.4f g, Z: %.4f g\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z);
    } else {
        fprintf(fp, "(unknown time), X: %.4f g, Y: %.4f g, Z: %.4f g\n", x, y, z);
    }

    fclose(fp);
}

static void shutdown_system(void) {
    printf("High acceleration detected! Shutting down...\n");
    fflush(stdout);
    if (system("sudo shutdown -h now") != 0) {
        perror("Error shutting down system");
    }
}

int main(int argc, char *argv[]) {
    int i2c_address = LIS3DH_ADDR_DEFAULT;
    float threshold = DEFAULT_THRESHOLD;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            i2c_address = (int)strtol(argv[++i], NULL, 0);
            if (i2c_address < 0x08 || i2c_address > 0x77) {
                fprintf(stderr, "Error: I2C address must be 0x08-0x77\n");
                return 1;
            }
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = strtof(argv[++i], NULL);
            if (threshold <= 0.0f) {
                fprintf(stderr, "Error: threshold must be greater than 0\n");
                return 1;
            }
        } else {
            fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at address 0x%02X\n", i2c_address);
        gpioTerminate();
        return 1;
    }

    if (init_lis3dh(i2c_handle) != 0) {
        fprintf(stderr, "Error: LIS3DH initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: failed to register SIGINT handler");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Monitoring acceleration (threshold: %.2f g)...\n", threshold);
    fflush(stdout);

    while (running) {
        float x, y, z;

        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
                log_event(x, y, z);
                shutdown_system();
                break;
            }
        } else {
            fprintf(stderr, "Warning: sensor read error, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

