static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    int left;
    int center;
    int right;
} SensorData;

static SensorData sensor_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static void add_sensor_data(int left, int center, int right) {
