#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7210_ADDR    0x30
#define RELAY_GPIO     17
#define FIELD_THRESHOLD_MT 5.0f
#define SAMPLE_PERIOD_US 100000
#define CONVERSION_TIMEOUT_MS 50
#define CONVERSION_POLL_DELAY_US 1000

/* Si7210 register addresses */
#define REG_FIELD_LSB  0xC0
#define REG_FIELD_MSB  0xC1
#define REG_CONFIG    0xC2
#define REG_MEAS_CFG  0xC3
#define REG_MEAS_TRIG 0xC1

/* Config register bits */
#define CFG_AUTO_MEAS 0x01
#define CFG_AUTO_TRIG 0x02
#define CFG_AUTO_EN   0x04

/* Measurement config bits */
#define MEAS_TRIG_ONE_SHOT 0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_i2c(void) {
    g_i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, SI7210_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    /* Enable auto-measurement mode (bit 0) */
    if (i2cWriteByteData(g_i2c_handle, REG_CONFIG, CFG_AUTO_EN) < 0) {
        fprintf(stderr, "Error writing config register\n");
        return -1;
    }
    return 0;
}

static int read_field_raw(int16_t *raw_out) {
    int lsb = i2cReadByteData(g_i2c_handle, REG_FIELD_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error reading field LSB: %d\n", lsb);
        return -1;
    }
    int msb = i2cReadByteData(g_i2c_handle, REG_FIELD_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading field MSB: %d\n", msb);
        return -1;
    }
    *raw_out = (int16_t)((msb << 8) | lsb);
    return 0;
}

static float convert_to_mt(int16_t raw) {
    return (float)raw * 25.0f / 1000.0f;
}

static int trigger_measurement(void) {
    /* Trigger one-shot conversion */
    if (i2cWriteByteData(g_i2c_handle, REG_MEAS_TRIG, MEAS_TRIG_ONE_SHOT) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }
    return 0;
}

static int wait_for_conversion(void) {
    int elapsed = 0;
    while (elapsed < CONVERSION_TIMEOUT_MS * 1000) {
        int status = i2cReadByteData(g_i2c_handle, REG_MEAS_TRIG);
        if (status < 0) {
            fprintf(stderr, "Error reading measurement status: %d\n", status);
            return -1;
        }
        if ((status & MEAS_TRIG_ONE_SHOT) == 0) {
            return 0;
        }
        gpioDelay(CONVERSION_POLL_DELAY_US);
        elapsed += CONVERSION_POLL_DELAY_US / 1000;
    }
    fprintf(stderr, "Timeout waiting for measurement\n");
    return -1;
}

static int log_event(const char *event) {
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (!fp) {
        perror("Error opening magnetic_events.txt");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    } else {
        fprintf(fp, "<unknown-time> %s\n", event);
    }
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    if (init_i2c() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("System started");

    while (g_running) {
        int16_t raw;
        if (read_field_raw(&raw) < 0) {
            log_event("Error reading field data");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float field_mt = convert_to_mt(raw);
        int relay_state = gpioRead(RELAY_GPIO);

        if (trigger_measurement() < 0) {
            log_event("Error triggering measurement");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (wait_for_conversion() < 0) {
            log_event("Error waiting for measurement");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (relay_state == 0 && field_mt > FIELD_THRESHOLD_MT) {
            if (gpioWrite(RELAY_GPIO, 1) < 0) {
                fprintf(stderr, "Error activating relay\n");
            } else {
                log_event("Relay activated");
            }
        } else if (relay_state == 1 && field_mt <= FIELD_THRESHOLD_MT) {
            if (gpioWrite(RELAY_GPIO, 0) < 0) {
                fprintf(stderr, "Error deactivating relay\n");
            } else {
                log_event("Relay deactivated");
            }
        }

        char log_buf[128];
        snprintf(log_buf, sizeof(log_buf),
                 "Field: %.2f mT, Relay: %s",
                 field_mt, relay_state ? "ON" : "OFF");
        log_event(log_buf);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    log_event("System shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

