#define LOG_FILE "relay_log.txt"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0);
    return 0;
}

static int init_server(void) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket creation failed");
        return -1;
    }
    int opt = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(fd);
        return -1;
    }
    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);
    if (bind(fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(fd);
        return -1;
    }
    if (listen(fd, 3) < 0) {
        perror("listen failed");
        close(fd);
        return -1;
    }
    return fd;
}

static int handle_client(int client_fd) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read = read(client_fd, buffer, BUFFER_SIZE - 1);
    if (bytes_read < 0) {
        perror("read failed");
        return -1;
    }
    if (bytes_read == 0) {
        log_event("Client disconnected");
        return 0;
    }
    buffer[bytes_read] = '\0';
    char *command = strtok(buffer, "\r\n");
    if (!command) {
        log_event("Invalid command received");
        return 0;
    }
    command = strtok(NULL, "\r\n");
    if (!command) {
        log_event("Invalid command received");
        return 0;
    }
    command = strtok(command, " \r\n");
    if (!command) {
        log_event("Invalid command received");
        return 0;
    }
    char *command_copy = strdup(command);
    if (!command_copy) {
        log_event("Memory allocation failed");
        return -1;
    }
    char *upper_command = strdup(command_copy);
    if (!upper_command) {
        log_event("Memory allocation failed");
        free(command_copy);
        return -1;
    }
    for (char *c = upper_command; *c; c++) {
        *c = toupper((unsigned char)*c);
    }
    free(command_copy);
    if (strcmp(upper_command, "ON") == 0) {
        if (gpioWrite(GPIO_RELAY, 1) == 0) {
            log_event("Relay turned ON");
        } else {
            log_event("Failed to turn relay ON");
        }
    } else if (strcmp(upper_command, "OFF") == 0) {
        if (gpioWrite(GPIO_RELAY, 0) == 0) {
            log_event("Relay turned OFF");
        } else {
            log_event("Failed to turn relay OFF");
        }
    } else {
        log_event("Invalid command received");
    }
    free(upper_command);
    return 0;
