static void cleanup(void) {
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        log_event("Server shutting down");
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT failed");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM failed");
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }
    log_event("Server starting");
    if (init_gpio() < 0) {
        log_event("GPIO initialization failed");
        cleanup();
        return 1;
    }
    server_fd = init_server();
    if (server_fd < 0) {
        log_event("Server initialization failed");
        cleanup();
        return 1;
    }
    log_event("Server listening on port 5000");
    while (running) {
        struct sockaddr_in client_address;
        socklen_t client_len = sizeof(client_address);
        client_fd = accept(server_fd, (struct sockaddr *)&client_address, &client_len);
        if (client_fd < 0) {
            if (running) {
                perror("accept failed");
            }
            continue;
        }
        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_address.sin_addr, client_ip, sizeof(client_ip));
        char client_port[16];
        snprintf(client_port, sizeof(client_port), "%d", ntohs(client_address.sin_port));
        char log_message[128];
        snprintf(log_message, sizeof(log_message), "Client connected: %s:%s", client_ip, client_port);
        log_event(log_message);
        handle_client(client_fd);
        close(client_fd);
        client_fd = -1;
    }
    log_event("Server shutting down");
    cleanup();
    return 0;
}

