#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SENSOR1_ADDR   0x08
#define SENSOR2_ADDR   0x09
#define GPIO_RELAY     18
#define FLOW_THRESHOLD 5.0f
#define POLL_DELAY_US  100000   /* 100 ms */
#define LOG_FILE       "flow_log.txt"

/* SLF3S-1300F: start-measurement command (0x36, 0x08) */
static const uint8_t SLF3S_CMD_START[2] = {0x36, 0x08};

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle1 = -1;
static int g_i2c_handle2 = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)                */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read flow rate from a SLF3S sensor.                                 */
/* Returns 0 on success (flow_out set), -1 on I2C error, -2 on CRC mismatch. */
/* ------------------------------------------------------------------ */
static int read_flow_rate(int handle, float *flow_out)
{
    uint8_t buf[3];
    int bytes_read;

    /* Send start-measurement command */
    if (i2cWriteDevice(handle, (char *)SLF3S_CMD_START, 2) != 0) {
        fprintf(stderr, "[ERROR] I2C write failed on handle %d\n", handle);
        return -1;
    }

    /* Wait for measurement to complete (~15 ms typ, use 20 ms) */
    gpioDelay(20000);

    /* Read 3 bytes: MSB, LSB, CRC */
    bytes_read = i2cReadDevice(handle, (char *)buf, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "[ERROR] I2C read failed on handle %d (got %d bytes)\n",
                handle, bytes_read);
        return -1;
    }

    /* Validate CRC-8 */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[WARN] CRC mismatch on handle %d (calc=0x%02X, recv=0x%02X)\n",
                handle, crc8(buf, 2), buf[2]);
        return -2;
    }

    /* Convert big-endian signed 16-bit value to ml/min */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw / 1500.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log flow rate with millisecond timestamp to file.                 */
/* ------------------------------------------------------------------ */
static void log_flow_rate(float flow1, float flow2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("[ERROR] clock_gettime");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%03ld", ts.tv_nsec / 1000000L);

    fprintf(fp, "%s, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            timestamp, flow1, flow2);
    fflush(fp);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — de-energize relay, close I2C handles, terminate pigpio */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
    }
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C handles for both sensors */
    g_i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_handle1 < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SENSOR1_ADDR, g_i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_handle2 < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SENSOR2_ADDR, g_i2c_handle2);
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO as output and ensure it starts de-energized */
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", GPIO_RELAY);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(GPIO_RELAY, 0) != 0) {
        fprintf(stderr, "[FATAL] gpioWrite(%d, 0) failed\n", GPIO_RELAY);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int rc1 = read_flow_rate(g_i2c_handle1, &flow1);
        int rc2 = read_flow_rate(g_i2c_handle2, &flow2);

        if (rc1 == 0 && rc2 == 0) {
            printf("Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n", flow1, flow2);

            if (flow1 < FLOW_THRESHOLD || flow2 < FLOW_THRESHOLD) {
                if (gpioWrite(GPIO_RELAY, 1) != 0) {
                    fprintf(stderr, "[WARN] gpioWrite(%d, 1) failed\n", GPIO_RELAY);
                } else {
                    printf("Relay energized (flow below threshold)\n");
                }
            } else {
                if (gpioWrite(GPIO_RELAY, 0) != 0) {
                    fprintf(stderr, "[WARN] gpioWrite(%d, 0) failed\n", GPIO_RELAY);
                } else {
                    printf("Relay de-energized (flow above threshold)\n");
                }
            }

            log_flow_rate(flow1, flow2);
        } else {
            fprintf(stderr, "[WARN] Sensor read error — relay status unchanged\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Flow monitoring stopped.\n");
    return EXIT_SUCCESS;
}

