/*
 * rain_window.c — Raspberry Pi 5 single-process rain-actuated window controller
 *
 * Hardware:
 *   - Seeed Studio Rain Sensor v1.0 (digital DO output)
 *     DO  -> GPIO 17 (BCM),  pull-up enabled
 *     VCC -> 3.3 V, GND -> GND
 *   - L298N DC motor driver
 *     ENA -> GPIO 22 (BCM)
 *     IN1 -> GPIO 23 (BCM)
 *     IN2 -> GPIO 24 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o rain_window rain_window.c -lpigpio -lrt
 * Run:
 *   sudo ./rain_window
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define RAIN_SENSOR_PIN  17
#define MOTOR_ENA_PIN    22
#define MOTOR_IN1_PIN    23
#define MOTOR_IN2_PIN    24

/* ---- Timing constants (microseconds) ---- */
#define POLL_INTERVAL_US  200000   /* 200 ms */
#define MOTOR_RUN_US      5000000  /* 5 s    */
#define SUPPRESS_US       300000   /* 300 ms */

/* ---- Global state ---- */
static volatile sig_atomic_t g_running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Motor control helpers ---- */
static int motor_stop(void)
{
    if (gpioWrite(MOTOR_ENA_PIN, 0) < 0) {
        syslog(LOG_WARNING, "gpioWrite(MOTOR_ENA_PIN, 0) failed");
        return -1;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        syslog(LOG_WARNING, "gpioWrite(MOTOR_IN1_PIN, 0) failed");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_WARNING, "gpioWrite(MOTOR_IN2_PIN, 0) failed");
        return -1;
    }
    return 0;
}

static int motor_start(void)
{
    if (gpioWrite(MOTOR_ENA_PIN, 1) < 0) {
        syslog(LOG_WARNING, "gpioWrite(MOTOR_ENA_PIN, 1) failed");
        return -1;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
        syslog(LOG_WARNING, "gpioWrite(MOTOR_IN1_PIN, 1) failed");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_WARNING, "gpioWrite(MOTOR_IN2_PIN, 0) failed");
        return -1;
    }
    return 0;
}

/* ---- Rain sensor read ---- */
static int read_rain_sensor(void)
{
    int v = gpioRead(RAIN_SENSOR_PIN);
    if (v < 0) {
        syslog(LOG_WARNING, "gpioRead(RAIN_SENSOR_PIN) failed");
        return -1;
    }
    /* Seeed Studio Rain Sensor v1.0: DO is LOW when rain is detected */
    return (v == 0) ? 1 : 0;
}

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    motor_stop();
    gpioTerminate();
    closelog();
}

/* ---- Main ---- */
int main(void)
{
    /* ---- Open syslog ---- */
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Rain window controller started");

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %m");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %m");
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise() failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- Configure pins ---- */
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(RAIN_SENSOR_PIN) failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(RAIN_SENSOR_PIN) failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(MOTOR_ENA_PIN) failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(MOTOR_IN1_PIN) failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(MOTOR_IN2_PIN) failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure motor is stopped at startup */
    if (motor_stop() < 0) {
        syslog(LOG_ERR, "Initial motor stop failed");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Rain window controller ready");

    /* ---- Main loop ---- */
    int dry_count = 0;
    int rain_detected = 0;

    while (g_running) {
        int rain = read_rain_sensor();
        if (rain < 0) {
            /* Sensor read error — back off briefly and retry */
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (rain) {
            if (!rain_detected) {
                syslog(LOG_INFO, "Rain detected — closing window");
                if (motor_start() < 0) {
                    syslog(LOG_ERR, "Motor start failed");
                } else {
                    gpioDelay(MOTOR_RUN_US);
                    if (motor_stop() < 0) {
                        syslog(LOG_ERR, "Motor stop failed");
                    } else {
                        syslog(LOG_INFO, "Window closed");
                        dry_count = 0;
                        rain_detected = 1;
                    }
                }
            } else {
                dry_count++;
                if (dry_count >= SUPPRESS_US) {
                    syslog(LOG_INFO, "Rain persists — suppressing further triggers");
                    dry_count = 0;
                }
            }
        } else {
            if (rain_detected) {
                syslog(LOG_INFO, "Rain stopped — re-opening window");
                if (motor_start() < 0) {
                    syslog(LOG_ERR, "Motor start failed");
                } else {
                    gpioDelay(MOTOR_RUN_US);
                    if (motor_stop() < 0) {
                        syslog(LOG_ERR, "Motor stop failed");
                    } else {
                        syslog(LOG_INFO, "Window re-opened");
                        dry_count = 0;
                        rain_detected = 0;
                    }
                }
            } else {
                dry_count = 0;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

