#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define BUTTON_LOCK    21
#define BUTTON_UNLOCK  22

#define LOCKED_PULSE_US 2000
#define UNLOCKED_PULSE_US 1000
#define DEBOUNCE_US     200000   /* 200 ms */
#define POLL_DELAY_US   10000    /* 10 ms  */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_position(int pin, int pulse_us)
{
    if (gpioServo(pin, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d (pulse %d us)\n",
                pin, pulse_us);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Stop servo pulses before terminating pigpio */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for servo pin %d\n", SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUTTON_LOCK, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button pin %d\n", BUTTON_LOCK);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUTTON_UNLOCK, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button pin %d\n", BUTTON_UNLOCK);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-ups so the buttons read HIGH when idle */
    if (gpioSetPullUpDown(BUTTON_LOCK, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for button pin %d\n", BUTTON_LOCK);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_UNLOCK, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for button pin %d\n", BUTTON_UNLOCK);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure servo starts in a safe position */
    if (set_servo_position(SERVO_PIN, UNLOCKED_PULSE_US) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door lock control started.  Press Ctrl+C to exit.\n");
    printf("  Lock button : GPIO %d (active LOW)\n", BUTTON_LOCK);
    printf("  Unlock button: GPIO %d (active LOW)\n", BUTTON_UNLOCK);
    printf("  Servo      : GPIO %d (pulse width %d us for locked)\n",
           SERVO_PIN, LOCKED_PULSE_US);
    printf("  Debounce   : %d us\n", DEBOUNCE_US);

    /* --- Main loop --- */
    while (g_running) {
        int lock_pressed = (gpioRead(BUTTON_LOCK) == 0);
        int unlock_pressed = (gpioRead(BUTTON_UNLOCK) == 0);

        if (lock_pressed) {
            printf("Lock button pressed -> locking door\n");
            if (set_servo_position(SERVO_PIN, LOCKED_PULSE_US) != 0) {
                break;
            }
            gpioDelay(DEBOUNCE_US);
        } else if (unlock_pressed) {
            printf("Unlock button pressed -> unlocking door\n");
            if (set_servo_position(SERVO_PIN, UNLOCKED_PULSE_US) != 0) {
                break;
            }
            gpioDelay(DEBOUNCE_US);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Door lock control stopped.\n");
    return EXIT_SUCCESS;
}

