#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_PIN      4
#define FLOODLIGHT_PIN 17
#define LOG_FILE     "security_log.txt"
#define POLL_DELAY_US 100000   /* 100 ms */
#define FLOODLIGHT_DURATION_S 60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Append a timestamped event to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_event(const char *event_type, int duration_s)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - %s: %d seconds\n", timestamp, event_type, duration_s) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

/*
 * Activate the floodlight for FLOODLIGHT_DURATION_S seconds.
 * Returns 0 on success, -1 on failure.
 */
static int activate_floodlight(void)
{
    if (gpioWrite(FLOODLIGHT_PIN, 1) != 0) {
        fprintf(stderr, "gpioWrite(FLOODLIGHT_PIN, 1) failed\n");
        return -1;
    }

    printf("Floodlight activated for %d seconds.\n", FLOODLIGHT_DURATION_S);

    for (int i = 0; i < FLOODLIGHT_DURATION_S && g_running; i++) {
        gpioDelay(1000000); /* 1 s */
    }

    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(FLOODLIGHT_PIN, 0) failed\n");
        return -1;
    }

    printf("Floodlight deactivated.\n");
    return 0;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(PIR_PIN, PI_INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure floodlight is off at startup */
    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(FLOODLIGHT_PIN, 0) failed at startup\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Security Light System started.\n");
    printf("PIR sensor on GPIO %d, floodlight on GPIO %d.\n", PIR_PIN, FLOODLIGHT_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int pir_value = gpioRead(PIR_PIN);
        if (pir_value < 0) {
            fprintf(stderr, "gpioRead(PIR_PIN) failed\n");
            break;
        }

        if (pir_value == 1) {
            printf("Motion detected!\n");

            if (activate_floodlight() != 0) {
                fprintf(stderr, "Failed to activate floodlight.\n");
                break;
            }

            /* Log activation event */
            if (log_event("Motion Detected", FLOODLIGHT_DURATION_S) != 0) {
                fprintf(stderr, "Failed to log activation event.\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioWrite(FLOODLIGHT_PIN, 0);
    gpioTerminate();

    printf("Smart Security Light System stopped.\n");
    return EXIT_SUCCESS;
}

