#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHD_R 0x2B
#define MPR121_NHD_R 0x2C
#define MPR121_NCL_R 0x2D
#define MPR121_FDL_R 0x2E
#define MPR121_MHD_F 0x2F
#define MPR121_NHD_F 0x30
#define MPR121_NCL_F 0x31
#define MPR121_FDL_F 0x32
#define MPR121_ECR 0x5E
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_AUTOCONFIG0 0x7B
#define MPR121_AUTOCONFIG1 0x7C
#define MPR121_AUTOCONFIG2 0x7D

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int mpr121_read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int mpr121_init(int handle) {
    /* Soft reset */
    if (mpr121_write_reg(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* Baseline filtering: MHD=10, NHD=10, NCL=0, FDL=0 */
    if (mpr121_write_reg(handle, MPR121_MHD_R, 0x10) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHD_R, 0x10) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCL_R, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDL_R, 0x00) < 0) return -1;

    /* Filter for charge: MHD=10, NHD=10, NCL=0, FDL=0 */
    if (mpr121_write_reg(handle, MPR121_MHD_F, 0x10) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHD_F, 0x10) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCL_F, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDL_F, 0x00) < 0) return -1;

    /* Debounce: 3 samples for touch, 3 samples for release */
    if (mpr121_write_reg(handle, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI=4 samples, CDT=0.5 us */
    if (mpr121_write_reg(handle, MPR121_CONFIG1, 0x10) < 0) return -1;

    /* Auto-config: enable, 12 electrodes, 16 uA charge current */
    if (mpr121_write_reg(handle, MPR121_AUTOCONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_AUTOCONFIG1, 0x0C) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_AUTOCONFIG2, 0x00) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking */
    if (mpr121_write_reg(handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) return -1;

    return 0;
}

static int read_touch_status(int handle, uint16_t *touch_status) {
    uint8_t lo, hi;
    if (mpr121_read_reg(handle, MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (mpr121_read_reg(handle, MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *touch_status = ((uint16_t)hi << 8) | lo;
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    printf("MPR121 relay control started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(i2c_handle, &touch_status) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        if (touch_status & 0x0001) {
            static int relay_state = 0;
            relay_state = !relay_state;
            gpioWrite(RELAY_GPIO, relay_state);
            printf("Electrode 0 touched, relay %s\n", relay_state ? "ON" : "OFF");
            gpioDelay(200000); /* 200 ms debounce */
        }

        gpioDelay(10000); /* 10 ms polling interval */
    }

    /* Clean shutdown */
    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

