            printf("Electrode 0 touched, relay %s\n", relay_state ? "ON" : "OFF");
            gpioDelay(200000); /* 200 ms debounce */
        }

        gpioDelay(10000); /* 10 ms polling interval */
    }

    /* Clean shutdown */
    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
