#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <syslog.h>
#include <stdarg.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>

#define PORT 5000
#define SERVO_PIN 17
#define PIR_PIN 4
#define PWM_PERIOD_NS 20000000  /* 20 ms = 50 Hz */
#define PWM_HALF_PERIOD_NS 10000000 /* 10 ms = 50 Hz */
#define PWM_DUTY_CYCLE_NS 1000000 /* 1 ms = 50 Hz */
#define PWM_RANGE 180
#define PWM_STEPS 100
#define PIR_THRESHOLD 100

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;
static FILE *log_file = NULL;

static void log_event(const char *message, ...) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: ", timestamp);
    va_list args;
    va_start(args, message);
    vfprintf(log_file, message, args);
    va_end(args);
    fputc('\n', log_file);
    fflush(log_file);
}

static void log_error(const char *message, ...) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: ERROR: ", timestamp);
    va_list args;
    va_start(args, message);
    vfprintf(log_file, message, args);
    va_end(args);
    fputc('\n', log_file);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        log_error("Failed to open gpiochip4: %s", strerror(errno));
        return -1;
    }
    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        log_error("Failed to get GPIO line %d: %s", SERVO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(servo_line, "servo_control", 0) < 0) {
        log_error("Failed to request GPIO line %d as output: %s", SERVO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        servo_line = NULL;
        return -1;
    }
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_error("Failed to get GPIO line %d: %s", PIR_PIN, strerror(errno));
        gpiod_line_release(servo_line);
        servo_line = NULL;
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        log_error("Failed to request GPIO line %d as input: %s", PIR_PIN, strerror(errno));
        gpiod_line_release(servo_line);
        servo_line = NULL;
        gpiod_line_release(pir_line);
        pir_line = NULL;
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    if (servo_line) {
        gpiod_line_set_value(servo_line, 0);
        gpiod_line_release(servo_line);
        servo_line = NULL;
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > PWM_RANGE) angle = PWM_RANGE;
    int duty_cycle = (angle * PWM_HALF_PERIOD_NS) / PWM_RANGE;
    if (gpiod_line_set_value(servo_line, 1) < 0) {
        log_error("Failed to set servo high: %s", strerror(errno));
        return;
    }
    struct timespec high_time = {0, duty_cycle};
    nanosleep(&high_time, NULL);
    if (gpiod_line_set_value(servo_line, 0) < 0) {
        log_error("Failed to set servo low: %s", strerror(errno));
    }
    struct timespec low_time = {0, PWM_HALF_PERIOD_NS - duty_cycle};
    nanosleep(&low_time, NULL);
}

static int read_pir_sensor(void) {
    int val = gpiod_line_get_value(pir_line);
    if (val < 0) {
        log_error("Failed to read PIR sensor: %s", strerror(errno));
        return -1;
    }
    return val;
}

static void *servo_pwm_thread(void *arg) {
    (void)arg;
    while (running) {
        set_servo_angle(0);
        struct timespec sleep_time = {0, 100000000}; /* 100 ms */
        nanosleep(&sleep_time, NULL);
        set_servo_angle(90);
        sleep_time = {0, 100000000};
        nanosleep(&sleep_time, NULL);
        set_servo_angle(180);
        sleep_time = {0, 100000000};
        nanosleep(&sleep_time, NULL);
    }
    return NULL;
}

static int parse_command(const char *command, char *command_type, char *argument) {
    if (strncmp(command, "SERVO", 5) == 0) {
        *command_type = 'S';
        if (sscanf(command, "SERVO %d", argument) != 1) {
            return -1;
        }
        if (atoi(argument) < 0 || atoi(argument) > PWM_RANGE) {
            return -2;
        }
        return 0;
    } else if (strncmp(command, "PIR", 3) == 0) {
        *command_type = 'P';
        return 0;
    }
    return -3;
}

static void send_response(int client_fd, const char *response) {
    if (send(client_fd, response, strlen(response), 0) < 0) {
        log_error("Failed to send response: %s", strerror(errno));
    }
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen("security.log", "a");
    if (!log_file) {
        log_error("Failed to open security.log: %s", strerror(errno));
        closelog();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_error("Failed to set signal handlers: %s", strerror(errno));
        fclose(log_file);
        closelog();
        return 1;
    }

    if (init_gpio() < 0) {
        log_error("GPIO initialization failed");
        fclose(log_file);
        closelog();
        return 1;
    }

    pthread_t servo_thread;
    if (pthread_create(&servo_thread, NULL, servo_pwm_thread, NULL) != 0) {
        log_error("Failed to create servo PWM thread: %s", strerror(errno));
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_error("Failed to create socket: %s", strerror(errno));
        running = 0;
        pthread_join(servo_thread, NULL);
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_error("Failed to set SO_REUSEADDR: %s", strerror(errno));
        running = 0;
        pthread_join(servo_thread, NULL);
        cleanup_gpio();
        close(server_fd);
        fclose(log_file);
        closelog();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_error("Failed to bind socket: %s", strerror(errno));
        running = 0;
        pthread_join(servo_thread, NULL);
        cleanup_gpio();
        close(server_fd);
        fclose(log_file);
        closelog();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        log_error("Failed to listen on socket: %s", strerror(errno));
        running = 0;
        pthread_join(servo_thread, NULL);
        cleanup_gpio();
        close(server_fd);
        fclose(log_file);
        closelog();
        return 1;
    }

    log_event("Security system started");

    while (running) {
        struct sockaddr_in client_address;
        socklen_t client_len = sizeof(client_address);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_address, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            log_error("Failed to accept connection: %s", strerror(errno));
            continue;
        }

        char buffer[1024];
        ssize_t bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            log_error("Failed to receive data: %s", strerror(errno));
            close(client_fd);
            continue;
        }
        if (bytes_received == 0) {
            log_event("Client disconnected");
            close(client_fd);
            continue;
        }
        buffer[bytes_received] = '\0';

        char command_type = 0;
        char argument[16] = {0};
        int parse_result = parse_command(buffer, &command_type, argument);
        if (parse_result == 0) {
            switch (command_type) {
                case 'S': {
                    int angle = atoi(argument);
                    char response[64];
                    snprintf(response, sizeof(response), "SERVO:OK %d", angle);
                    log_event(response);
                    send_response(client_fd, response);
                    break;
                }
                case 'P': {
                    int pir_value = read_pir_sensor();
                    char response[64];
                    if (pir_value < 0) {
                        snprintf(response, sizeof(response), "PIR:ERROR");
                    } else {
                        snprintf(response, sizeof(response), "PIR:%d", pir_value);
                    }
                    log_event(response);
                    send_response(client_fd, response);
                    break;
                }
                default: {
                    char response[64];
                    snprintf(response, sizeof(response), "UNKNOWN_COMMAND");
                    log_event(response);
                    send_response(client_fd, response);
                    break;
                }
            }
        } else {
            char response[64];
            switch (parse_result) {
                case -1: {
                    snprintf(response, sizeof(response), "INVALID_COMMAND");
                    break;
                }
                case -2: {
                    snprintf(response, sizeof(response), "ANGLE_OUT_OF_RANGE");
                    break;
                }
                default: {
                    snprintf(response, sizeof(response), "UNKNOWN_ERROR");
                    break;
                }
            }
            log_event(response);
            send_response(client_fd, response);
        }

        close(client_fd);
    }

    log_event("Security system shutting down");
    running = 0;
    pthread_join(servo_thread, NULL);
    cleanup_gpio();
    close(server_fd);
    fclose(log_file);
    closelog();
    return 0;
}

