#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define HX711_DOUT_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 25

#define DEFAULT_THRESHOLD 1000.0f
#define DEFAULT_SCALE 1000.0f
#define DEFAULT_DURATION 200
#define NUM_READINGS 5
#define TARE_SAMPLES 10
#define MAX_RETRIES 3
#define READ_TIMEOUT_MS 1000
#define POLL_INTERVAL_MS 500

static volatile sig_atomic_t running = 1;
static float threshold = DEFAULT_THRESHOLD;
static float scale = DEFAULT_SCALE;
static int duration_ms = DEFAULT_DURATION;

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *dout_line = NULL;
static struct gpiod_line *sck_line = NULL;
static struct gpiod_line *solenoid_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        return -1;
    }

    dout_line = gpiod_chip_get_line(chip, HX711_DOUT_PIN);
    sck_line = gpiod_chip_get_line(chip, HX711_SCK_PIN);
    solenoid_line = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!dout_line || !sck_line || !solenoid_line) {
        syslog(LOG_ERR, "Failed to get GPIO lines: %s", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(dout_line, "hx711_dout") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT as input: %s", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(sck_line, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK as output: %s", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(solenoid_line, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid as output: %s", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    if (solenoid_line) {
        gpiod_line_set_value(solenoid_line, 0);
        gpiod_line_release(solenoid_line);
        solenoid_line = NULL;
    }
    if (sck_line) {
        gpiod_line_release(sck_line);
        sck_line = NULL;
    }
    if (dout_line) {
        gpiod_line_release(dout_line);
        dout_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int read_hx711(int32_t *raw_out) {
    int32_t value = 0;
    int timeout = 0;

    // Wait for DOUT to go LOW (data ready)
    while (gpiod_line_get_value(dout_line) == 1) {
        usleep(1000);
        timeout++;
        if (timeout > READ_TIMEOUT_MS) {
            syslog(LOG_ERR, "HX711 timeout waiting for DOUT LOW");
            return -1;
        }
    }

    // Read 24 bits MSB-first
    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck_line, 1) < 0) {
            syslog(LOG_ERR, "Failed to set SCK high: %s", strerror(errno));
            return -1;
        }
        usleep(1);

        value <<= 1;
        if (gpiod_line_get_value(dout_line) == 1) {
            value |= 1;
        }

        if (gpiod_line_set_value(sck_line, 0) < 0) {
            syslog(LOG_ERR, "Failed to set SCK low: %s", strerror(errno));
            return -1;
        }
        usleep(1);
    }

    // 25th pulse: select Channel A / Gain 128
    if (gpiod_line_set_value(sck_line, 1) < 0) {
        syslog(LOG_ERR, "Failed to set SCK high (25th pulse): %s", strerror(errno));
        return -1;
    }
    usleep(1);
    if (gpiod_line_set_value(sck_line, 0) < 0) {
        syslog(LOG_ERR, "Failed to set SCK low (25th pulse): %s", strerror(errno));
        return -1;
    }
    usleep(1);

    // Convert 24-bit two's-complement to signed 32-bit
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    *raw_out = value;
    return 0;
}

static float calculate_weight(int32_t raw) {
    return (float)(raw - (int32_t)scale) / scale;
}

static void trigger_solenoid(void) {
    syslog(LOG_INFO, "Triggering solenoid for %d ms", duration_ms);
    gpiod_line_set_value(solenoid_line, 1);
    usleep(duration_ms * 1000);
    gpiod_line_set_value(solenoid_line, 0);
    syslog(LOG_INFO, "Solenoid deactivated");
}

static void log_error(const char *msg) {
    syslog(LOG_ERR, "Error: %s", msg);
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration_ms = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration]\n", argv[0]);
                return 1;
        }
    }

    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting weight monitoring (threshold=%.2f, scale=%.2f, duration=%d ms)",
           threshold, scale, duration_ms);

    if (init_gpio() < 0) {
        cleanup_gpio();
        closelog();
        return 1;
    }

    // Tare: average NUM_READINGS readings
    float tare_sum = 0.0f;
    int tare_ok = 0;
    for (int i = 0; i < TARE_SAMPLES; i++) {
        int32_t raw;
        if (read_hx711(&raw) == 0) {
            tare_sum += calculate_weight(raw);
            tare_ok++;
        } else {
            log_error("Tare read failed");
        }
        usleep(10000);
    }

    if (tare_ok == 0) {
        log_error("Tare failed: no valid readings");
        cleanup_gpio();
        closelog();
        return 1;
    }

    float tare_offset = tare_sum / tare_ok;
    syslog(LOG_INFO, "Tare complete: offset=%.2f", tare_offset);

    // Main loop
    while (running) {
        int32_t raw;
        if (read_hx711(&raw) == 0) {
            float weight = calculate_weight(raw);
            syslog(LOG_INFO, "Weight: %.2f grams", weight);

            if (weight > threshold) {
                trigger_solenoid();
            }
        } else {
            log_error("Read failed");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup_gpio();
    closelog();
    return 0;
}

