/*
 * relay_controller.c — MQTT-controlled relay on Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - Relay module on GPIO17 (physical pin 11, BCM)
 *   - 4.7 kΩ series resistor between relay module IN and GPIO17
 *   - 4.7 kΩ series resistor between relay module VCC and 3.3 V
 *   - 4.7 kΩ series resistor between relay module GND and GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c \
 *       -lmosquitto -lpigpio -lrt
 *
 * Run:
 *   sudo ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER_ADDRESS  "localhost"
#define MQTT_BROKER_PORT    1883
#define MQTT_CLIENT_ID     "relay_controller_1"
#define MQTT_TOPIC         "home/lights/control"
#define GPIO_RELAY         17
#define LOOP_DELAY_US      100000   /* 100 ms */
#define RETRY_DELAY_S      5
#define KEEPALIVE_SEC      60

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_message(int priority, const char *message)
{
    syslog(priority, "%s", message);
}

/* ------------------------------------------------------------------ */
/* Relay control                                                      */
/* ------------------------------------------------------------------ */
static int relay_set(int state)
{
    if (gpioWrite(GPIO_RELAY, state) != 0) {
        log_message(LOG_ERR, "gpioWrite failed on GPIO17");
        return -1;
    }
    char msg[128];
    snprintf(msg, sizeof(msg), "Relay set to %s", state ? "ON" : "OFF");
    log_message(LOG_INFO, msg);
    return 0;
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        log_message(LOG_INFO, "MQTT connected");
        if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            log_message(LOG_ERR, "Failed to subscribe to MQTT topic");
        } else {
            log_message(LOG_INFO, "Subscribed to MQTT topic");
        }
    } else {
        char msg[128];
        snprintf(msg, sizeof(msg), "MQTT connect failed: %s",
                 mosquitto_strerror(result));
        log_message(LOG_ERR, msg);
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq;
    (void)userdata;
    char msg[128];
    snprintf(msg, sizeof(msg), "MQTT disconnected (rc=%d)", rc);
    log_message(LOG_INFO, msg);
}

static void on_message(struct mosquitto *mosq, void *userdata,
                       const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (message->payloadlen == 0) {
        log_message(LOG_ERR, "Empty MQTT message received");
        return;
    }

    char payload[256];
    size_t len = (size_t)message->payloadlen;
    if (len >= sizeof(payload)) {
        len = sizeof(payload) - 1;
    }
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    char msg[256];
    snprintf(msg, sizeof(msg), "Received MQTT message: %s", payload);
    log_message(LOG_INFO, msg);

    if (strcmp(payload, "ON") == 0) {
        if (relay_set(1) != 0) {
            log_message(LOG_ERR, "Failed to set relay ON");
        }
    } else if (strcmp(payload, "OFF") == 0) {
        if (relay_set(0) != 0) {
            log_message(LOG_ERR, "Failed to set relay OFF");
        }
    } else {
        log_message(LOG_ERR, "Invalid payload: must be ON or OFF");
    }
}

static void on_error(struct mosquitto *mosq, void *userdata, int err)
{
    (void)mosq;
    (void)userdata;
    char msg[256];
    snprintf(msg, sizeof(msg), "MQTT error: %s", mosquitto_strerror(err));
    log_message(LOG_ERR, msg);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_mosq != NULL) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    gpioWrite(GPIO_RELAY, 0);   /* ensure relay is OFF */
    gpioTerminate();
    mosquitto_lib_cleanup();
    closelog();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set GPIO17 as output");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioWrite(GPIO_RELAY, 0) != 0) {
        log_message(LOG_ERR, "Failed to initialise GPIO17 LOW");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* --- mosquitto init --- */
    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (g_mosq == NULL) {
        log_message(LOG_ERR, "mosquitto_new failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);
    mosquitto_error_callback_set(g_mosq, on_error);

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_message(LOG_ERR, "sigaction(SIGINT) failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        log_message(LOG_ERR, "sigaction(SIGTERM) failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Connect --- */
    int rc = mosquitto_connect(g_mosq, MQTT_BROKER_ADDRESS,
                               MQTT_BROKER_PORT, KEEPALIVE_SEC);
    if (rc != MOSQ_ERR_SUCCESS) {
        char msg[128];
        snprintf(msg, sizeof(msg), "mosquitto_connect failed: %s",
                 mosquitto_strerror(rc));
        log_message(LOG_ERR, msg);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Main loop --- */
    while (g_running) {
        rc = mosquitto_loop(g_mosq, LOOP_DELAY_US, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            char msg[128];
            snprintf(msg, sizeof(msg), "mosquitto_loop error: %s",
                     mosquitto_strerror(rc));
            log_message(LOG_ERR, msg);
            /* Attempt to reconnect on transient errors */
            sleep(RETRY_DELAY_S);
            rc = mosquitto_reconnect(g_mosq);
            if (rc != MOSQ_ERR_SUCCESS) {
                log_message(LOG_ERR, "mosquitto_reconnect failed");
                break;
            }
        }
    }

    /* --- Graceful shutdown --- */
    cleanup();
    return EXIT_SUCCESS;
}

