#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdatomic.h>

#define MOTOR_A_PWM_PIN 17
#define MOTOR_A_DIR_PIN 18
#define MOTOR_B_PWM_PIN 22
#define MOTOR_B_DIR_PIN 23

#define ENCODER_A_A_PIN 4
#define ENCODER_A_B_PIN 5
#define ENCODER_B_A_PIN 6
#define ENCODER_B_B_PIN 12

#define TARGET_SPEED_RPM 50.0
#define PWM_FREQUENCY 10000
#define PWM_RANGE 255
#define LOOP_PERIOD_US 100000
#define ENCODER_TICKS_PER_REV 64
#define ENCODER_COUNTS_PER_REV 1
#define ENCODER_STALL_THRESHOLD_SEC 2.0
#define ENCODER_STALL_COUNTS 0

#define KP 0.5
#define KI 0.05

static volatile sig_atomic_t running = 1;
static atomic_int encoder_a_count = 0;
static atomic_int encoder_b_count = 0;
static atomic_int encoder_a_last_tick = 0;
static atomic_int encoder_b_last_tick = 0;
static atomic_int encoder_a_last_edge = 0;
static atomic_int encoder_b_last_edge = 0;
static atomic_int encoder_a_stall_count = 0;
static atomic_int encoder_b_stall_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void encoder_a_isr(int gpio, int level, uint32_t tick) {
    (void)gpio;
    int current_tick = tick;
    int last_tick = atomic_exchange(&encoder_a_last_tick, current_tick);
    int diff = current_tick - last_tick;
    if (diff > 0) {
        atomic_fetch_add(&encoder_a_count, 1);
    } else if (diff < 0) {
        atomic_fetch_sub(&encoder_a_count, 1);
    }
}

static void encoder_b_isr(int gpio, int level, uint32_t tick) {
    (void)gpio;
    int current_tick = tick;
    int last_tick = atomic_exchange(&encoder_b_last_tick, current_tick);
    int diff = current_tick - last_tick;
    if (diff > 0) {
        atomic_fetch_add(&encoder_b_count, 1);
    } else if (diff < 0) {
        atomic_fetch_sub(&encoder_b_count, 1);
    }
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", MOTOR_A_PWM_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", MOTOR_A_DIR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", MOTOR_B_PWM_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", MOTOR_B_DIR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d.\n", MOTOR_A_PWM_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d.\n", MOTOR_B_PWM_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(MOTOR_A_PWM_PIN, PWM_RANGE) != PWM_RANGE) {
