#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 17
#define LUX_THRESHOLD_LOW 50.0
#define LUX_THRESHOLD_HIGH 200.0
#define POLL_INTERVAL_SEC 5
#define BH1750_CMD_OT_HRES2 0x21
#define BH1750_CONV_TIME_US 180000  // 180 ms for OT_HRES2 mode

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio(void);
int initialize_i2c(void);
float read_lux(void);
int control_relay(float lux);
void log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup(void);

// Initialize GPIO pins
int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);  // Ensure relay is off initially

    return 0;
}

// Initialize I2C communication
int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d\n", BH1750_ADDR, I2C_BUS);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750 sensor
float read_lux(void) {
    char buf[2];
    int result;

    // Send One-Time High-Resolution Mode 2 command
    result = i2cWriteByte(i2c_handle, BH1750_CMD_OT_HRES2);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to write BH1750 command 0x%02X\n", BH1750_CMD_OT_HRES2);
        return -1.0;
    }

    // Wait for conversion to complete
    gpioDelay(BH1750_CONV_TIME_US);

    // Read 2 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: Failed to read BH1750 data (read %d bytes)\n", result);
        return -1.0;
    }

    // Convert raw data to lux (assuming 1.2 lux resolution)
    int raw_lux = (buf[0] << 8) | buf[1];
    return (float)raw_lux / 1.2;
}

// Control the relay based on lux value
int control_relay(float lux) {
    static int relay_state = 0;  // 0 = off, 1 = on
    int new_state;

    if (lux < LUX_THRESHOLD_LOW) {
        new_state = 1;
    } else if (lux > LUX_THRESHOLD_HIGH) {
        new_state = 0;
    } else {
        return relay_state;  // No change
    }

    if (new_state != relay_state) {
        gpioWrite(RELAY_GPIO, new_state);
        relay_state = new_state;
        log_data(-1.0, relay_state);
        return relay_state;
    }

    return relay_state;
}

// Log data to file
void log_data(float lux, int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (lux >= 0.0) {
        fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    } else {
        fprintf(log_file, "%s: Error reading lux, Relay = %s\n", timestamp, relay_state ? "ON" : "OFF");
    }
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources
void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);  // Ensure relay is off
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    float lux;
    int relay_state;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("chicken_coop_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Smart Chicken Coop Lighting System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        lux = read_lux();

        if (lux >= 0.0) {
            relay_state = control_relay(lux);
        } else {
            // Error reading lux, turn off relay
            relay_state = 0;
            gpioWrite(RELAY_GPIO, 0);
        }

        log_data(lux, relay_state);

        sleep(POLL_INTERVAL_SEC);
    }

    // Cleanup
    cleanup();
    printf("Smart Chicken Coop Lighting System stopped.\n");

    return 0;
}

