        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);  // Ensure relay is off
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    float lux;
    int relay_state;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("chicken_coop_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Smart Chicken Coop Lighting System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        lux = read_lux();

        if (lux >= 0.0) {
            relay_state = control_relay(lux);
        } else {
            // Error reading lux, turn off relay
            relay_state = 0;
            gpioWrite(RELAY_GPIO, 0);
        }

        log_data(lux, relay_state);

        sleep(POLL_INTERVAL_SEC);
    }

    // Cleanup
    cleanup();
    printf("Smart Chicken Coop Lighting System stopped.\n");

    return 0;
}

