#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000  /* 50 ms */
#define LOOP_DELAY_US 10000     /* 10 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    /* Start with relay OFF */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize relay state on GPIO %d.\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_touch_sensor(void) {
    int value = gpioRead(TOUCH_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read GPIO %d.\n", TOUCH_SENSOR_PIN);
        return -1;
    }
    return value;
}

static int toggle_relay(void) {
    int current_state = gpioRead(RELAY_PIN);
    if (current_state < 0) {
        fprintf(stderr, "Error: failed to read relay state on GPIO %d.\n", RELAY_PIN);
        return -1;
    }

    int new_state = !current_state;

    if (gpioWrite(RELAY_PIN, new_state) != 0) {
        fprintf(stderr, "Error: failed to write relay state on GPIO %d.\n", RELAY_PIN);
        return -1;
    }

    return new_state;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return;
    }

    printf("[%s] Relay state: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Relay control started. Touch sensor on GPIO %d, relay on GPIO %d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    int last_touch_state = 0;
    int relay_state = 0;

    while (running) {
        int touch_state = read_touch_sensor();
        if (touch_state < 0) {
            /* Sensor read error; wait and retry */
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        /* Detect rising edge: touch detected (HIGH) */
        if (touch_state == 1 && last_touch_state == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            touch_state = read_touch_sensor();
            if (touch_state < 0) {
                continue;
            }

            if (touch_state == 1) {
                /* Still HIGH after debounce; toggle */
                relay_state = toggle_relay();
                if (relay_state < 0) {
                    continue;
                }
                log_relay_state(relay_state);
            }
        }

        /* Detect falling edge: touch released (LOW) */
        if (touch_state == 0 && last_touch_state == 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
            touch_state = read_touch_sensor();
            if (touch_state < 0) {
                continue;
            }

            if (touch_state == 0) {
                /* Still LOW after debounce; allow next toggle */
                last_touch_state = 0;
            }
        }

        last_touch_state = touch_state;
        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Relay control stopped.\n");

    return EXIT_SUCCESS;
}

