#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define PULSES_PER_LITER 450.0
#define SAMPLE_INTERVAL_US 1000000
#define DEBOUNCE_TIMEOUT_US 1000000

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;

    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static double calculate_lpm(uint32_t pulses) {
    return ((double)pulses / PULSES_PER_LITER) * 60.0;
}

static void control_solenoid(double lpm) {
    static int solenoid_state = 1; /* HIGH = open, LOW = closed */

    if (lpm > LPM_THRESHOLD_HIGH && solenoid_state == 0) {
        if (gpioWrite(SOLENOID_GPIO, 1) == 0) {
            solenoid_state = 1;
            if (log_file) {
                time_t now = time(NULL);
                struct tm *t = localtime(&now);
                char timestamp[64];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
                fprintf(log_file, "%s - Solenoid opened (LPM: %.2f)\n", timestamp, lpm);
                fflush(log_file);
            }
        }
    } else if (lpm < LPM_THRESHOLD_LOW && solenoid_state == 1) {
        if (gpioWrite(SOLENOID_GPIO, 0) == 0) {
            solenoid_state = 0;
            if (log_file) {
                time_t now = time(NULL);
                struct tm *t = localtime(&now);
                char timestamp[64];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
                fprintf(log_file, "%s - Solenoid closed (LPM: %.2f)\n", timestamp, lpm);
                fflush(log_file);
            }
        }
    }
}

static void cleanup(void) {
    if (log_file) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
        fprintf(log_file, "%s - Program terminated, closing solenoid to safe state\n", timestamp);
        fflush(log_file);
        gpioWrite(SOLENOID_GPIO, 0);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set flow sensor GPIO %d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set solenoid GPIO %d as output\n", SOLENOID_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_GPIO, 1) != 0) {
        fprintf(stderr, "Error: Failed to initialize solenoid GPIO %d to HIGH\n", SOLENOID_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_TIMEOUT_US, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR function for flow sensor GPIO %d\n", FLOW_SENSOR_GPIO);
        gpioWrite(SOLENOID_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("water_flow.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open water_flow.log for appending\n");
        gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_TIMEOUT_US, NULL, NULL);
        gpioWrite(SOLENOID_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    time_t last_sample_time = time(NULL);

    while (running) {
        time_t current_time = time(NULL);
        if (difftime(current_time, last_sample_time) >= 1.0) {
            uint32_t local_count = 0;
            pthread_mutex_lock(&pulse_mutex);
            local_count = pulse_count;
            pulse_count = 0;
            pthread_mutex_unlock(&pulse_mutex);

            double lpm = calculate_lpm(local_count);
            control_solenoid(lpm);

            if (log_file) {
                time_t now = time(NULL);
                struct tm *t = localtime(&now);
                char timestamp[64];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
                fprintf(log_file, "%s - Flow rate: %.2f LPM, Solenoid state: %s\n",
                        timestamp, lpm, solenoid_state ? "OPEN" : "CLOSED");
                fflush(log_file);
            }

            last_sample_time = current_time;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

