#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18
#define CONFIG_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define SERVER_IP "127.0.0.1"
#define SERVER_PORT 12345
#define HX711_TIMEOUT_US 1000
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_SETTLE_DELAY_US 1000000
#define DISPENSE_DELAY_US 1000000
#define READ_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static double calibration_factor = 1.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename, double *cal_factor, const char **server_ip, int *server_port) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file %s. Using defaults.\n", filename);
        *cal_factor = 1.0;
        *server_ip = SERVER_IP;
        *server_port = SERVER_PORT;
        return 0;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");
        if (!key || !value) continue;
        key[strcspn(key, "\r\n")] = 0;
        value[strcspn(value, "\r\n")] = 0;

        if (strcmp(key, "calibration_factor") == 0) {
            *cal_factor = atof(value);
        } else if (strcmp(key, "server_ip") == 0) {
            *server_ip = strdup(value);
        } else if (strcmp(key, "server_port") == 0) {
            *server_port = atoi(value);
        }
    }

    fclose(fp);
    return 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(10000);

    return 0;
}

static int init_server(const char *ip, int port) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket");
        return -1;
    }

    int opt = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(fd);
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(ip);
    addr.sin_port = htons(port);

    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(fd);
        return -1;
    }

    if (listen(fd, 3) < 0) {
        perror("listen");
        close(fd);
        return -1;
    }

    return fd;
}

static int init_client(const char *ip, int port) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(ip);
    addr.sin_port = htons(port);

    if (connect(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("connect");
        close(fd);
        return -1;
    }

    return fd;
}

static long read_hx711(void) {
    long value = 0;
    int timeout = 0;

    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > HX711_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 data pin stuck HIGH (timeout).\n");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        value <<= 1;
