        fprintf(stderr, "Error: Pulse width %d out of range [%d, %d].\n", pulse_width, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
        return -1;
    }

    gpioServo(SERVO_PIN, pulse_width);
    return 0;
}

static int dispense_ingredient(double target_weight) {
    int pulse_width = (int)(((target_weight / 1000.0) / 100.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH);
    if (set_servo_pulse_width(pulse_width) != 0) {
        return -1;
    }

