    while (running) {
        client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            if (running) {
                perror("accept");
            }
            continue;
        }

        printf("Client connected.\n");

        ssize_t n = read(client_fd, &target_weight, sizeof(target_weight));
        if (n < 0) {
            perror("read");
            close(client_fd);
            client_fd = -1;
            continue;
        } else if (n == 0) {
            fprintf(stderr, "Client disconnected.\n");
            close(client_fd);
            client_fd = -1;
            continue;
        }

        long raw_value = read_hx711();
        if (raw_value < 0) {
            fprintf(stderr, "Error reading HX711.\n");
            log_dispensing_event(target_weight, 0.0, "HX711 read failed");
            close(client_fd);
            client_fd = -1;
            continue;
        }

        double actual_weight = calibrate_hx711(raw_value);
        printf("Target: %.2f g, Actual: %.2f g\n", target_weight, actual_weight);

        if (dispense_ingredient(target_weight) != 0) {
            fprintf(stderr, "Error dispensing ingredient.\n");
            log_dispensing_event(target_weight, actual_weight, "Dispense failed");
        } else {
            log_dispensing_event(target_weight, actual_weight, NULL);
