#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define TOUCH_SENSOR_GPIO 4
#define DEFAULT_DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;
static int debounce_ms = DEFAULT_DEBOUNCE_MS;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_ms = atoi(optarg);
                if (debounce_ms <= 0) {
                    fprintf(stderr, "Error: debounce must be a positive integer\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d debounce_ms]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set relay GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set touch sensor GPIO %d as input\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay GPIO %d to LOW\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    int relay_state = 0;
    int last_touch_state = 0;
    uint32_t last_change_tick = 0;

    printf("Touch-controlled relay started. Press Ctrl+C to exit.\n");
    printf("Touch sensor: GPIO %d, Relay: GPIO %d, Debounce: %d ms\n",
           TOUCH_SENSOR_GPIO, RELAY_GPIO, debounce_ms);

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_GPIO);
        if (touch_state < 0) {
            fprintf(stderr, "Error: failed to read touch sensor GPIO %d\n", TOUCH_SENSOR_GPIO);
            break;
        }

        if (touch_state != last_touch_state) {
            uint32_t now = gpioTick();
            if (now - last_change_tick >= (uint32_t)(debounce_ms * 1000)) {
                last_touch_state = touch_state;
                last_change_tick = now;

                if (touch_state == 1) {
                    relay_state = !relay_state;
                    if (gpioWrite(RELAY_GPIO, relay_state) != 0) {
                        fprintf(stderr, "Error: failed to write relay GPIO %d\n", RELAY_GPIO);
                        break;
                    }
                    log_relay_state(relay_state);
                }
            }
        }

        gpioDelay(1000);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");

    return EXIT_SUCCESS;
}

