#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define MIN_PULSE_US   500
#define MAX_PULSE_US   2500
#define MIN_ANGLE      0
#define MAX_ANGLE      180
#define STEP_ANGLE     10
#define PWM_FREQ_HZ    50
#define PWM_RANGE      1000
#define SERVO_INIT_US  1500

static volatile sig_atomic_t g_running = 1;
static struct termios g_old_term;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int restore_terminal(void)
{
    if (tcsetattr(STDIN_FILENO, TCSANOW, &g_old_term) != 0) {
        perror("tcsetattr(TCSANOW)");
        return -1;
    }
    return 0;
}

static int save_terminal(void)
{
    if (tcgetattr(STDIN_FILENO, &g_old_term) != 0) {
        perror("tcgetattr");
        return -1;
    }
    struct termios new_term;
    if (tcgetattr(STDIN_FILENO, &new_term) != 0) {
        perror("tcgetattr");
        return -1;
    }
    new_term.c_lflag &= ~(ICANON | ECHO);
    new_term.c_cc[VMIN]  = 0;
    new_term.c_cc[VTIME] = 0;
    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_term) != 0) {
        perror("tcsetattr(TCSANOW, non-canonical)");
        return -1;
    }
    return 0;
}

static int set_servo_angle(int angle)
{
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: angle %d out of range [%d, %d]\n",
                angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    int pulse_us = MIN_PULSE_US +
        (int)((long)angle * (MAX_PULSE_US - MIN_PULSE_US) / MAX_ANGLE);
    if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
        fprintf(stderr, "Error: pulse %d us out of range [%d, %d]\n",
                pulse_us, MIN_PULSE_US, MAX_PULSE_US);
        return -1;
    }
    if (gpioServo(SERVO_PIN, pulse_us) != 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d, pulse %d us\n",
                SERVO_PIN, pulse_us);
        return -1;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (save_terminal() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", SERVO_PIN);
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(SERVO_PIN, PWM_FREQ_HZ) != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %d\n", SERVO_PIN);
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(SERVO_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d\n", SERVO_PIN);
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_servo_angle(90) != 0) {
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Servo control started. Press '+' to increase, '-' to decrease, 'q' to quit.\n");
    printf("Current angle: %d\n", 90);

    int angle = 90;

    while (g_running) {
        int ch = getchar();
        if (ch == EOF) {
            break;
        }
        if (ch == 'q') {
            break;
        }
        if (ch == '+') {
            angle += STEP_ANGLE;
            if (angle > MAX_ANGLE) {
                angle = MAX_ANGLE;
            }
        } else if (ch == '-') {
            angle -= STEP_ANGLE;
            if (angle < MIN_ANGLE) {
                angle = MIN_ANGLE;
            }
        }
        if (set_servo_angle(angle) != 0) {
            break;
        }
        printf("Current angle: %d\n", angle);
    }

    if (g_running) {
        printf("\nShutting down...\n");
    }

    gpioServo(SERVO_PIN, 0);
    restore_terminal();
    gpioTerminate();
    return EXIT_SUCCESS;
}

