#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define FAILSAFE_TIMEOUT  10          /* seconds */
#define POLL_DELAY_US    50000       /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    /* Start with relay OFF */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay state on GPIO%d.\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Ensure relay is OFF before terminating pigpio */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch-controlled relay control started.\n");
    printf("  Touch sensor : GPIO%d (3.3V logic HIGH when touched)\n", TOUCH_SENSOR_PIN);
    printf("  Relay       : GPIO%d (active-HIGH)\n", RELAY_PIN);
    printf("  Failsafe    : touch HIGH for >%d s, relay OFF\n", FAILSAFE_TIMEOUT);
    printf("Press Ctrl+C to exit.\n");

    int relay_state = 0;
    int failsafe_active = 0;
    time_t failsafe_start_time = 0;

    while (g_running) {
        int touch_level = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_level == PI_BAD_GPIO) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (touch_level == 1) {
