#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_GPIO 18
#define DIRECTION_GPIO 23
#define FLOW_SENSOR_GPIO 24
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define PULSES_PER_LITER 450.0
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "flow_log.csv"

static volatile sig_atomic_t running = 1;
static volatile int pulse_count = 0;
static volatile double flow_rate = 0.0;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)tick;
    (void)userdata;
    if (level == 1) {
        pulse_count++;
    }
}

static int initialize_gpio(void) {
    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", VALVE_GPIO);
        return -1;
    }
    if (gpioSetMode(DIRECTION_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", DIRECTION_GPIO);
        return -1;
    }
    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", FLOW_SENSOR_GPIO);
        return -1;
    }
    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d\n", VALVE_GPIO);
        return -1;
    }
    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO %d\n", VALVE_GPIO);
        return -1;
    }
    if (gpioWrite(VALVE_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO %d to LOW\n", VALVE_GPIO);
        return -1;
    }
    if (gpioWrite(DIRECTION_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO %d to LOW\n", DIRECTION_GPIO);
        return -1;
    }
    return 0;
}

static int initialize_flow_sensor(void) {
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register ISR on GPIO %d\n", FLOW_SENSOR_GPIO);
        return -1;
    }
    return 0;
}

static int set_valve_position(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    if (gpioPWM(VALVE_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle to %d\n", duty_cycle);
        return -1;
    }
    return 0;
}

static int log_data(double flow_rate, int valve_position) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);
    if (fprintf(log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(VALVE_GPIO, 0);
    gpioWrite(VALVE_GPIO, 0);
    gpioWrite(DIRECTION_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    double target_flow_rate = 0.0;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = atof(optarg);
                if (target_flow_rate <= 0.0) {
                    fprintf(stderr, "Error: Target flow rate must be positive\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t target_flow_rate_lmin]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_flow_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow control system started. Target flow rate: %.2f L/min\n", target_flow_rate);

    while (running) {
        struct timespec start, end;
        if (clock_gettime(CLOCK_MONOTONIC, &start) != 0) {
            perror("clock_gettime");
            break;
        }

        gpioDelay(SAMPLE_INTERVAL_US);

        if (!running) break;

        if (clock_gettime(CLOCK_MONOTONIC, &end) != 0) {
            perror("clock_gettime");
            break;
        }

        long elapsed_us = (end.tv_sec - start.tv_sec) * 1000000L + (end.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed_us <= 0) elapsed_us = 1;

        double pulses_per_second = (double)pulse_count / (elapsed_us / 1000000.0);
        flow_rate = pulses_per_second * PULSES_PER_LITER;
        pulse_count = 0;

        int duty_cycle = (int)(target_flow_rate / flow_rate * PWM_RANGE);
        if (set_valve_position(duty_cycle) != 0) {
            break;
        }

        if (log_data(flow_rate, duty_cycle) != 0) {
            break;
        }

        printf("Flow Rate: %.2f L/min, Valve Position: %d\n", flow_rate, duty_cycle);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

