#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_PIN_1 17
#define LOCK_PIN_2 27
#define BUTTON_PIN 22
#define SPI_CHANNEL 0
#define SPI_SPEED 100000
#define LOCK_DURATION_MS 5000
#define DEBOUNCE_MS 50
#define POLL_DELAY_US 10000

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&now, &tm_info)) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static int read_rfid_tag(unsigned char *tag_data) {
    unsigned char tx[10] = {0};
    unsigned char rx[10] = {0};
    int bytes_read = spiXfer(spi_handle, (char *)tx, (char *)rx, 10);
    if (bytes_read != 10) {
        log_event("Error: SPI read returned unexpected number of bytes");
        return -1;
    }
    if (memcmp(rx, "\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00", 10) == 0) {
        log_event("Error: No tag detected (all-zero response)");
        return -1;
    }
    memcpy(tag_data, rx, 10);
    return 0;
}

static int authenticate_tag(const unsigned char *tag_data) {
    if (memcmp(tag_data, "\x01\x02\x03\x04\x05\x06\x07\x08\x09\x0A", 10) != 0) {
        log_event("Error: Invalid RFID tag data");
        return -1;
    }
    log_event("RFID tag authentication successful");
    return 0;
}

static void control_locks(int engaged) {
    if (gpioWrite(LOCK_PIN_1, engaged ? 0 : 1) != 0) {
        log_event("Error: Failed to write to lock pin 1");
    }
    if (gpioWrite(LOCK_PIN_2, engaged ? 0 : 1) != 0) {
        log_event("Error: Failed to write to lock pin 2");
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    control_locks(1);
    if (log_file) {
        log_event("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d, speed %d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("/var/log/door_access.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(LOCK_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on button pin\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LOCK_PIN_1, 1) != 0 || gpioWrite(LOCK_PIN_2, 1) != 0) {
        fprintf(stderr, "Error: Failed to initialise lock pins to engaged state\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Program started");

    while (running) {
        int button_pressed = (gpioRead(BUTTON_PIN) == 0);
        if (button_pressed) {
            gpioDelay(DEBOUNCE_MS * 1000);
            if (gpioRead(BUTTON_PIN) == 0) {
                log_event("Button press detected");
                unsigned char tag_data[10];
                if (read_rfid_tag(tag_data) == 0) {
                    if (authenticate_tag(tag_data) == 0) {
                        control_locks(0);
                        log_event("Two-factor authentication successful");
                        gpioDelay(LOCK_DURATION_MS * 1000);
                        control_locks(1);
                    } else {
                        log_event("Two-factor authentication failed");
                    }
                } else {
                    log_event("RFID read failed");
                }
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

