#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

#define KP 1.0
#define KI 0.1
#define KD 0.01
#define SAMPLE_TIME_MS 100
#define PWM_FREQUENCY_HZ 100
#define PWM_PERIOD_NS (1000000000L / PWM_FREQUENCY_HZ)
#define ENCODER_PULSES_PER_REV 600
