    fflush(log_file);
}

static void set_motor_speed(struct gpiod_line *ena, struct gpiod_line *in1,
                            struct gpiod_line *in2, float speed) {
    if (speed > 0.0f) {
        gpiod_line_set_value(in1, 1);
        gpiod_line_set_value(in2, 0);
    } else if (speed < 0.0f) {
        gpiod_line_set_value(in1, 0);
        gpiod_line_set_value(in2, 1);
    } else {
        gpiod_line_set_value(in1, 0);
        gpiod_line_set_value(in2, 0);
    }
    gpiod_line_set_value(ena, 1);
}

static void *encoder_thread1(void *arg) {
    (void)arg;
    struct gpiod_line *a = encoder1_a;
    struct gpiod_line *b = encoder1_b;
    int prev_a = 0, prev_b = 0;
    int count = 0;

    while (running) {
        int a_val = gpiod_line_get_value(a);
        int b_val = gpiod_line_get_value(b);

        if (a_val < 0 || b_val < 0) {
            fprintf(stderr, "Error reading encoder1: %s\n", strerror(errno));
            usleep(100000);
            continue;
        }

        if (a_val != prev_a || b_val != prev_b) {
            if (a_val == 1 && b_val == 0) {
                count++;
            } else if (a_val == 0 && b_val == 1) {
                count--;
            }
            prev_a = a_val;
            prev_b = b_val;
        }
        usleep(1000);
    }
    return NULL;
}

static void *encoder_thread2(void *arg) {
    (void)arg;
    struct gpiod_line *a = encoder2_a;
    struct gpiod_line *b = encoder2_b;
    int prev_a = 0, prev_b = 0;
    int count = 0;

    while (running) {
        int a_val = gpiod_line_get_value(a);
