    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    motor1_ena = gpiod_chip_get_line(chip, MOTOR1_ENA);
    motor1_in1 = gpiod_chip_get_line(chip, MOTOR1_IN1);
    motor1_in2 = gpiod_chip_get_line(chip, MOTOR1_IN2);
    motor2_enb = gpiod_chip_get_line(chip, MOTOR2_ENB);
    motor2_in3 = gpiod_chip_get_line(chip, MOTOR2_IN3);
    motor2_in4 = gpiod_chip_get_line(chip, MOTOR2_IN4);
    encoder1_a = gpiod_chip_get_line(chip, ENCODER1_A);
    encoder1_b = gpiod_chip_get_line(chip, ENCODER1_B);
    encoder2_a = gpiod_chip_get_line(chip, ENCODER2_A);
    encoder2_b = gpiod_chip_get_line(chip, ENCODER2_B);

    if (!motor1_ena || !motor1_in1 || !motor1_in2 ||
        !motor2_enb || !motor2_in3 || !motor2_in4 ||
        !encoder1_a || !encoder1_b || !encoder2_a || !encoder2_b) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(motor1_ena, "motor1_ena", 0) < 0 ||
        gpiod_line_request_output(motor1_in1, "motor1_in1", 0) < 0 ||
        gpiod_line_request_output(motor1_in2, "motor1_in2", 0) < 0 ||
        gpiod_line_request_output(motor2_enb, "motor2_enb", 0) < 0 ||
        gpiod_line_request_output(motor2_in3, "motor2_in3", 0) < 0 ||
        gpiod_line_request_output(motor2_in4, "motor2_in4", 0) < 0 ||
        gpiod_line_request_input(encoder1_a, "encoder1_a") < 0 ||
        gpiod_line_request_input(encoder1_b, "encoder1_b") < 0 ||
        gpiod_line_request_input(encoder2_a, "encoder2_a") < 0 ||
        gpiod_line_request_input(encoder2_b, "encoder2_b") < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        cleanup();
        return 1;
    }

    log_file = fopen("motor_log.csv", "a");
    if (!log_file) {
        perror("fopen");
        cleanup();
        return 1;
    }
    fprintf(log_file, "timestamp,motor1_speed,motor2_speed,pid_p,pid_i,pid_d,pid_output\n");
    fflush(log_file);

    pthread_t encoder_thread1_id, encoder_thread2_id;
    if (pthread_create(&encoder_thread1_id, NULL, encoder_thread1, NULL) != 0 ||
        pthread_create(&encoder_thread2_id, NULL, encoder_thread2, NULL) != 0) {
        perror("pthread_create");
        cleanup();
        return 1;
    }

    float target_rpm1 = 60.0f;
    float target_rpm2 = 60.0f;
    float integral = 0.0f;
    float prev_error = 0.0f;
    float pid_output = 0.0f;

    while (running) {
        pthread_mutex_lock(&encoder1_mutex);
        int count1 = encoder1_count;
        pthread_mutex_unlock(&encoder1_mutex);
        pthread_mutex_lock(&encoder2_mutex);
        int count2 = encoder2_count;
        pthread_mutex_unlock(&encoder2_mutex);

        float encoder_rate1 = (float)count1 / ENCODER_PULSES_PER_REV * 60.0f * SAMPLE_TIME_MS / 1000.0f;
        float encoder_rate2 = (float)count2 / ENCODER_PULSES_PER_REV * 60.0f * SAMPLE_TIME_MS / 1000.0f;

        float error1 = target_rpm1 - encoder_rate1;
        float error2 = target_rpm2 - encoder_rate2;

        integral += error1 * SAMPLE_TIME_MS / 1000.0f;
        float derivative = (error1 - prev_error) * SAMPLE_TIME_MS / 1000.0f;

        pid_output = KP * error1 + KI * integral + KD * derivative;
        if (pid_output > 100.0f) pid_output = 100.0f;
        if (pid_output < -100.0f) pid_output = -100.0f;

        prev_error = error1;

        float motor1_speed = pid_output;
        float motor2_speed = pid_output;

        set_motor_speed(motor1_ena, motor1_in1, motor1_in2, motor1_speed);
        set_motor_speed(motor2_enb, motor2_in3, motor2_in4, motor2_speed);

        pthread_mutex_lock(&encoder1_mutex);
        encoder1_count = 0;
        pthread_mutex_unlock(&encoder1_mutex);
        pthread_mutex_lock(&encoder2_mutex);
        encoder2_count = 0;
        pthread_mutex_unlock(&encoder2_mutex);

        log_data(encoder_rate1, encoder_rate2, error1, integral, derivative, pid_output);

        usleep(SAMPLE_TIME_MS * 1000);
    }

    pthread_join(encoder_thread1_id, NULL);
    pthread_join(encoder_thread2_id, NULL);
    cleanup();
    return 0;
}

