#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1
#define POLL_DELAY_US 50000 // 50 ms

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init(int handle);
int mpr121_read_touch_status(int handle, uint16_t *touch_status);
int mpr121_set_electrode_config(int handle, uint8_t config);
int mpr121_set_touch_threshold(int handle, uint8_t electrode, uint8_t touch_threshold);
int mpr121_set_release_threshold(int handle, uint8_t electrode, uint8_t release_threshold);
int relay_control(int gpio_pin, int state);
int log_relay_state(int gpio_pin, int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the MPR121 sensor
int mpr121_init(int handle) {
    // Soft reset
    if (i2cWriteByteData(handle, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset to MPR121\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms for reset to complete

    // Set electrode configuration: baseline tracking, 12 electrodes, baseline tracking enabled
    if (mpr121_set_electrode_config(handle, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to set electrode configuration\n");
        return -1;
    }

    // Set touch and release thresholds for all 12 electrodes
    for (int i = 0; i < 12; i++) {
        if (mpr121_set_touch_threshold(handle, i, 10) < 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (mpr121_set_release_threshold(handle, i, 2) < 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Set filtering parameters
    if (i2cWriteByteData(handle, MPR121_MHDR, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write MHDR\n");
        return -1;
    }
    if (i2cWriteByteData(handle, MPR121_NHDR, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write NHDR\n");
        return -1;
    }
    if (i2cWriteByteData(handle, MPR121_NCLR, 0x0E) < 0) {
        fprintf(stderr, "Error: Failed to write NCLR\n");
        return -1;
    }
    if (i2cWriteByteData(handle, MPR121_FDLR, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write FDLR\n");
        return -1;
    }
    if (i2cWriteByteData(handle, MPR121_MHDF, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write MHDF\n");
        return -1;
    }
    if (i2cWriteByteData(handle, MPR121_NHDF, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write NHDF\n");
        return -1;
    }
    if (i2cWriteByteData(handle, MPR121_NCLF, 0x0E) < 0) {
        fprintf(stderr, "Error: Failed to write NCLF\n");
        return -1;
    }
    if (i2cWriteByteData(handle, MPR121_FDLF, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write FDLF\n");
        return -1;
    }
    if (i2cWriteByteData(handle, MPR121_NHDT, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write NHDT\n");
        return -1;
    }
    if (i2cWriteByteData(handle, MPR121_NCLT, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write NCLT\n");
        return -1;
    }
    if (i2cWriteByteData(handle, MPR121_FDLT, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write FDLT\n");
        return -1;
    }

    // Set debounce and configuration
    if (i2cWriteByteData(handle, MPR121_DEBOUNCE, 0x33) < 0) {
        fprintf(stderr, "Error: Failed to write debounce\n");
        return -1;
    }
    if (i2cWriteByteData(handle, MPR121_CONFIG1, 0x10) < 0) {
        fprintf(stderr, "Error: Failed to write config1\n");
        return -1;
    }
    if (i2cWriteByteData(handle, MPR121_CONFIG2, 0x20) < 0) {
        fprintf(stderr, "Error: Failed to write config2\n");
        return -1;
    }

    // Enable run mode
    if (i2cWriteByteData(handle, MPR121_ECR, 0x8C) < 0) {
        fprintf(stderr, "Error: Failed to enable run mode\n");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status(int handle, uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status from MPR121\n");
        return -1;
    }
    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to set the electrode configuration
int mpr121_set_electrode_config(int handle, uint8_t config) {
    if (i2cWriteByteData(handle, MPR121_ELECTRODE_CONFIG, config) < 0) {
        fprintf(stderr, "Error: Failed to set electrode configuration\n");
        return -1;
    }
    return 0;
}

// Function to set the touch threshold for a specific electrode
int mpr121_set_touch_threshold(int handle, uint8_t electrode, uint8_t touch_threshold) {
    if (i2cWriteByteData(handle, MPR121_E0TTH + (electrode * 2), touch_threshold) < 0) {
        fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", electrode);
        return -1;
    }
    return 0;
}

// Function to set the release threshold for a specific electrode
int mpr121_set_release_threshold(int handle, uint8_t electrode, uint8_t release_threshold) {
    if (i2cWriteByteData(handle, MPR121_E0RTH + (electrode * 2), release_threshold) < 0) {
        fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", electrode);
        return -1;
    }
    return 0;
}

// Function to control the relay
int relay_control(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) < 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to log the relay state to a file
int log_relay_state(int gpio_pin, int state) {
    FILE *fp = fopen("relay_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open relay_log.txt for writing: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - GPIO %d: %s\n", timestamp, gpio_pin, state ? "ON" : "OFF");
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C connection to MPR121 at address 0x%02X: %d\n", MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121 sensor
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Relay control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch_status(i2c_handle, &touch_status) == 0) {
            int relay_state = (touch_status & 0x0FFF) ? 1 : 0; // Check if any electrode is touched
            if (relay_control(RELAY_GPIO, relay_state) == 0) {
                if (log_relay_state(RELAY_GPIO, relay_state) != 0) {
                    fprintf(stderr, "Warning: Failed to log relay state\n");
                }
            }
        } else {
            fprintf(stderr, "Warning: Failed to read touch status, retrying...\n");
        }
        gpioDelay(POLL_DELAY_US); // Delay for 50ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    relay_control(RELAY_GPIO, 0); // Turn off relay
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

