#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define I2C_BUS 1

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_FILTER_CONFIG 0x20
#define MPR121_ELECTRODE_CURRENT 0x01
#define MPR121_TOUCH_TH 0x10
#define MPR121_RELEASE_TH 0x0A
#define MPR121_ELE_EN 0x20
#define MPR121_RUN_MODE 0x00

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

int mpr121_read_reg(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

int mpr121_init(int handle) {
    if (mpr121_write_reg(handle, MPR121_ELECTRODE_CONFIG, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FILTER_CONFIG, 0x20) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_ELECTRODE_CURRENT, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_TOUCH_TH, 0x10) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_RELEASE_TH, 0x0A) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_ELE_EN, 0x20) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_RUN_MODE, 0x00) < 0) return -1;
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 touch sensor relay control started. Press Ctrl+C to exit.\n");

    while (running) {
        uint8_t touch_status_l, touch_status_h;
        if (mpr121_read_reg(i2c_handle, MPR121_TOUCHSTATUS_L, &touch_status_l) < 0 ||
            mpr121_read_reg(i2c_handle, MPR121_TOUCHSTATUS_H, &touch_status_h) < 0) {
            gpioDelay(100000);
            continue;
        }

        uint16_t touch_status = (touch_status_h << 8) | touch_status_l;
        if (touch_status > 0) {
            gpioWrite(RELAY_PIN, !gpioRead(RELAY_PIN));
            printf("Relay toggled to %s\n", gpioRead(RELAY_PIN) ? "ON" : "OFF");
        }

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

