    if (length < MIN_STEPS || length > MAX_PATTERN_LENGTH) {
        fprintf(stderr, "Error: Pattern length must be between %d and %d\n", MIN_STEPS, MAX_PATTERN_LENGTH);
        return -1;
    }

    for (int i = 0; i < length; i++) {
        pattern[i] = rand() % (MAX_DUTY_CYCLE + 1);
    }
    return 0;
