#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// GPIO pin definitions
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Calibration data structure
typedef struct {
    double scale_factor;
    double offset;
} CalibrationData;

// Global variables
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static FILE *calibration_file = NULL;
static CalibrationData calibration_data = {1.0, 0.0};

// Function prototypes
int read_hx711(int data_pin, int clock_pin);
double convert_to_weight(int raw_value, double scale_factor, double offset);
int calibrate_hx711(int data_pin, int clock_pin, double *scale_factor, double *offset);
void control_solenoid(int solenoid_pin, double weight);
void log_weight(double weight);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Function to read raw data from the HX711
int read_hx711(int data_pin, int clock_pin) {
    int value = 0;
    int timeout = 0;

    // Wait for data ready (low)
    while (gpioRead(data_pin) == 1) {
        gpioDelay(100); // 100 microseconds
        timeout++;
        if (timeout > 1000) { // 1 second timeout
            fprintf(stderr, "Error: HX711 data ready timeout\n");
            return -1;
        }
    }

    // Read 24 bits
    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1); // 1 microsecond
        value = value << 1;
        if (gpioRead(data_pin)) {
            value++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1); // 1 microsecond
    }

    // 25th pulse to set gain to 128
    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    // Convert to signed 24-bit value
    if (value & 0x800000) {
        value |= 0xFF000000; // Sign extend
    }

    return value;
}

// Function to convert raw data to weight
double convert_to_weight(int raw_value, double scale_factor, double offset) {
    return (double)raw_value / scale_factor + offset;
}

// Function to calibrate the HX711
int calibrate_hx711(int data_pin, int clock_pin, double *scale_factor, double *offset) {
    int sum = 0;
    int num_readings = 100;
    int raw_value;

    printf("Starting one-time calibration...\n");

    // Read raw values and sum them
    for (int i = 0; i < num_readings; i++) {
        raw_value = read_hx711(data_pin, clock_pin);
        if (raw_value == -1) {
            fprintf(stderr, "Error: Failed to read HX711 during calibration\n");
            return -1;
        }
        sum += raw_value;
        gpioDelay(1000); // 1 ms delay between readings
    }

    // Calculate average and offset
    *offset = (double)sum / num_readings;
    printf("Offset: %.2f\n", *offset);

    // Set scale factor to 1.0 (assuming zero load)
    *scale_factor = 1.0;
    printf("Scale factor: %.2f\n", *scale_factor);

    printf("Calibration complete.\n");
    return 0;
}

// Function to control the solenoid lock
void control_solenoid(int solenoid_pin, double weight) {
    if (weight > 10.0) {
        gpioWrite(solenoid_pin, 1); // Engage solenoid lock
    } else {
        gpioWrite(solenoid_pin, 0); // Release solenoid lock
    }
}

// Function to log weight data to a file
void log_weight(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Weight: %.2f kg\n", timestamp, weight);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("weight_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open weight_log.txt\n");
        gpioTerminate();
        return 1;
    }

    // Open calibration file
    calibration_file = fopen("calibration.txt", "r");
    if (calibration_file != NULL) {
        // Read calibration data from file
        if (fscanf(calibration_file, "%lf %lf", &calibration_data.scale_factor, &calibration_data.offset) != 2) {
            fprintf(stderr, "Warning: Invalid calibration data, using defaults\n");
            calibration_data.scale_factor = 1.0;
            calibration_data.offset = 0.0;
        }
        fclose(calibration_file);
    } else {
        // File not found, use defaults
        fprintf(stderr, "Warning: Calibration file not found, using defaults\n");
    }

    // Set initial solenoid state to released
    gpioWrite(SOLENOID_PIN, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Calibrate HX711
    if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &calibration_data.scale_factor, &calibration_data.offset) != 0) {
        fprintf(stderr, "Error: HX711 calibration failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Save calibration data to file
    calibration_file = fopen("calibration.txt", "w");
    if (calibration_file != NULL) {
        fprintf(calibration_file, "%lf %lf", calibration_data.scale_factor, calibration_data.offset);
        fclose(calibration_file);
    } else {
        fprintf(stderr, "Error: Failed to save calibration data\n");
    }

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int raw_value = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw_value == -1) {
            fprintf(stderr, "Error: Failed to read HX711, skipping iteration\n");
            gpioDelay(500000); // 0.5 seconds delay before retrying
            continue;
        }

        double weight = convert_to_weight(raw_value, calibration_data.scale_factor, calibration_data.offset);
        control_solenoid(SOLENOID_PIN, weight);
        log_weight(weight);

        gpioDelay(500000); // 0.5 seconds delay between readings
    }

    // Cleanup
    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is released
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (calibration_file != NULL) {
        fclose(calibration_file);
    }
    gpioTerminate();

    return 0;
}

