#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define HX711_DT_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 17

// Define weight threshold (grams)
#define WEIGHT_THRESHOLD 100.0

// Define solenoid activation duration (seconds)
#define SOLENOID_DURATION 5

// Define timeout for HX711 read (microseconds)
#define HX711_TIMEOUT_US 100000

// Define polling interval (microseconds)
#define POLL_INTERVAL_US 1000000

// Global flag for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_hx711(int dt_pin, int sck_pin);
double convert_to_weight(int raw_value);
void activate_solenoid(int solenoid_pin, int duration);
void log_event(const char *event_message);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read raw data from HX711
int read_hx711(int dt_pin, int sck_pin) {
    int value = 0;
    int timeout = 0;

    // Wait for DT to go low (data ready)
    while (gpioRead(dt_pin) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
        if (timeout > HX711_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 data-ready timeout (DT stuck high)\n");
            return -1;
        }
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(sck_pin, 1);
        gpioDelay(1); // Small delay for SCK high
        value = value << 1;
        if (gpioRead(dt_pin)) {
            value++;
        }
        gpioWrite(sck_pin, 0);
        gpioDelay(1); // Small delay for SCK low
    }

    // 25th pulse to set gain to 128 (default)
    gpioWrite(sck_pin, 1);
    gpioDelay(1);
    gpioWrite(sck_pin, 0);
    gpioDelay(1);

    // Convert to signed 24-bit value
    if (value & 0x800000) {
        value |= 0xFF000000; // Sign extend
    }

    return value;
}

// Function to convert raw data to weight (grams)
double convert_to_weight(int raw_value) {
    // Example conversion: raw value * 0.000125 (example gain)
    return (double)raw_value * 0.000125;
}

// Function to activate the solenoid lock
void activate_solenoid(int solenoid_pin, int duration) {
    gpioWrite(solenoid_pin, 1); // Activate solenoid
    gpioDelay(duration * 1000000); // Wait for specified duration
    gpioWrite(solenoid_pin, 0); // Deactivate solenoid
}

// Function to log events to a file
void log_event(const char *event_message) {
    FILE *fp = fopen("stock_events.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open stock_events.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event_message);

    fclose(fp);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DT_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Initialize HX711 to known state (SCK low, DT high)
    gpioWrite(HX711_SCK_PIN, 0);
    gpioWrite(HX711_DT_PIN, 1);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Kitchen stock monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int raw_value = read_hx711(HX711_DT_PIN, HX711_SCK_PIN);
        if (raw_value == -1) {
            fprintf(stderr, "Error reading HX711, retrying...\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        double weight = convert_to_weight(raw_value);

        printf("Weight: %.2f g\n", weight);

        if (weight < WEIGHT_THRESHOLD) {
            printf("Weight below threshold! Activating solenoid lock.\n");
            activate_solenoid(SOLENOID_PIN, SOLENOID_DURATION);
            log_event("Solenoid lock activated");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    // Cleanup
    gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
    gpioTerminate();
    printf("Program terminated.\n");

    return 0;
}

