#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define weight threshold in kg
#define WEIGHT_THRESHOLD 5.0

// Define calibration file name
#define CALIBRATION_FILE "calibration.txt"

// Define security log file name
#define SECURITY_LOG_FILE "security.log"

// Define timeout for HX711 communication (in microseconds)
#define HX711_TIMEOUT_US 100000

// Global variables
static volatile int running = 1;
static int calibration_factor = 1;
static FILE *calibration_file = NULL;
static FILE *security_log_file = NULL;

// Function prototypes
int read_hx711(int data_pin, int clock_pin);
double calibrate_load_cell(int data_pin, int clock_pin, double known_weight);
void control_solenoid(int solenoid_pin, int duration_ms);
void log_security_event(double weight);
void signal_handler(int signal);
void cleanup();

// Function to read raw data from HX711
int read_hx711(int data_pin, int clock_pin) {
    int value = 0;
    int timeout = 0;

    // Wait for data line to go low (data ready)
    while (gpioRead(data_pin) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
        if (timeout > HX711_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 data line stuck high (timeout).\n");
            return -1;
        }
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1); // Small delay
        value = value << 1;
        if (gpioRead(data_pin)) {
            value++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1); // Small delay
    }

    // 25th pulse to set gain to 128 (default)
    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    // Convert to signed 24-bit value
    if (value & 0x800000) {
        value |= 0xFF000000; // Sign extend
    }

    return value;
}

// Function to calibrate the load cell
double calibrate_load_cell(int data_pin, int clock_pin, double known_weight) {
    int raw_value;
    double weight;

    printf("Place a known weight on the load cell (in kg): ");
    fflush(stdout);
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Error: Invalid input for known weight.\n");
        return -1.0;
    }

    printf("Reading raw value...\n");
    fflush(stdout);

    raw_value = read_hx711(data_pin, clock_pin);
    if (raw_value == -1) {
        fprintf(stderr, "Error: Failed to read raw value from HX711.\n");
        return -1.0;
    }

    printf("Raw value: %d\n", raw_value);
    fflush(stdout);

    // Calculate calibration factor
    calibration_factor = (int)(raw_value / known_weight);
    printf("Calibration factor: %d\n", calibration_factor);
    fflush(stdout);

    // Save calibration factor to file
    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return -1.0;
    }

    fprintf(calibration_file, "%d", calibration_factor);
    fclose(calibration_file);
    calibration_file = NULL;

    printf("Calibration saved to %s\n", CALIBRATION_FILE);
    fflush(stdout);

    return calibration_factor;
}

// Function to control the solenoid lock
void control_solenoid(int solenoid_pin, int duration_ms) {
    gpioWrite(solenoid_pin, 1); // Activate solenoid
    printf("Solenoid lock activated for %d ms\n", duration_ms);
    fflush(stdout);
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(solenoid_pin, 0); // Deactivate solenoid
    printf("Solenoid lock deactivated\n");
    fflush(stdout);
}

// Function to log security events
void log_security_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    security_log_file = fopen(SECURITY_LOG_FILE, "a");
    if (security_log_file == NULL) {
        fprintf(stderr, "Error: Could not open security log file for writing.\n");
        return;
    }

    fprintf(security_log_file, "%d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fclose(security_log_file);
    security_log_file = NULL;

    printf("Security event logged: Weight: %.2f kg\n", weight);
    fflush(stdout);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    fflush(stdout);

    // Unlock solenoid lock
    gpioWrite(SOLENOID_PIN, 0);

    // Close calibration file
    if (calibration_file != NULL) {
        fclose(calibration_file);
        calibration_file = NULL;
    }

    // Close security log file
    if (security_log_file != NULL) {
        fclose(security_log_file);
        security_log_file = NULL;
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete.\n");
    fflush(stdout);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Initialize solenoid lock to deactivated state
    gpioWrite(SOLENOID_PIN, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open calibration file for reading
    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file != NULL) {
        if (fscanf(calibration_file, "%d", &calibration_factor) != 1) {
            fprintf(stderr, "Error: Invalid calibration data in file.\n");
            fclose(calibration_file);
            calibration_file = NULL;
        } else {
            printf("Calibration factor loaded from file: %d\n", calibration_factor);
            fflush(stdout);
        }
    } else {
        printf("Calibration file not found. Calibrating load cell...\n");
        fflush(stdout);

        // Calibrate load cell
        if (calibration_factor != -1) {
            fprintf(stderr, "Error: Calibration factor already set.\n");
            cleanup();
            return 1;
        }

        calibration_factor = calibrate_load_cell(HX711_DATA_PIN, HX711_CLOCK_PIN, WEIGHT_THRESHOLD);
        if (calibration_factor == -1) {
            fprintf(stderr, "Error: Failed to calibrate load cell.\n");
            cleanup();
            return 1;
        }
    }

    printf("Load cell calibration complete. Starting weight monitoring...\n");
    fflush(stdout);

    // Main loop
    while (running) {
        int raw_value;
        double weight;

        // Read raw value from HX711
        raw_value = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw_value == -1) {
            fprintf(stderr, "Error: Failed to read raw value from HX711.\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Convert raw value to weight
        weight = (double)raw_value / calibration_factor;

        // Check if weight exceeds threshold
        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight exceeded threshold! Weight: %.2f kg\n", weight);
            fflush(stdout);

            // Log security event
            log_security_event(weight);

            // Control solenoid lock
            control_solenoid(SOLENOID_PIN, 5000); // Activate for 5 seconds
        }

        gpioDelay(100000); // Delay 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

