    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int log_motion_event(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Error: localtime failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Motion detected!\n", timestamp) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    int ret;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open gpiochip4: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        fprintf(stderr, "Error: Failed to get PIR line %d: %s\n", PIR_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(pir_line, "pir-sensor");
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to request PIR line as input: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error: Failed to get buzzer line %d: %s\n", BUZZER_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to request buzzer line as output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            fprintf(stderr, "Error: Failed to read PIR sensor: %s\n", strerror(errno));
            break;
        }

        if (pir_value == 1) {
            printf("Motion detected!\n");

            if (log_motion_event() != 0) {
                fprintf(stderr, "Error: Failed to log motion event.\n");
            }

            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                fprintf(stderr, "Error: Failed to activate buzzer: %s\n", strerror(errno));
                break;
            }

            usleep(BUZZER_DURATION_MS * 1000);

            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                fprintf(stderr, "Error: Failed to deactivate buzzer: %s\n", strerror(errno));
                break;
            }
        }

        usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

