#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define VALVE_GPIO_LINE 18
#define CONFIG_FILE "watering.conf"
#define MIN_DURATION 1
#define MAX_DURATION 3600
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int parse_duration(const char *line, int *duration_out)
{
    char *endptr = NULL;
    long val = strtol(line, &endptr, 10);

    if (endptr == line || *endptr != '\0') {
        fprintf(stderr, "Error: duration must be an integer between %d and %d\n",
                MIN_DURATION, MAX_DURATION);
        return -1;
    }

    if (val < MIN_DURATION || val > MAX_DURATION) {
        fprintf(stderr, "Error: duration must be between %d and %d\n",
                MIN_DURATION, MAX_DURATION);
        return -1;
    }

    *duration_out = (int)val;
    return 0;
}

static int read_watering_duration(const char *filename, int *duration_out)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        if (feof(fp)) {
            fprintf(stderr, "Error: %s is empty\n", filename);
        } else {
            fprintf(stderr, "Error: cannot read %s: %s\n", filename, strerror(errno));
        }
        fclose(fp);
        return -1;
    }

    fclose(fp);

    if (parse_duration(line, duration_out) != 0) {
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: cannot install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error: cannot open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for valve control */
    line = gpiod_chip_get_line(chip, VALVE_GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error: cannot get GPIO line %d: %s\n",
                VALVE_GPIO_LINE, strerror(errno));
        goto cleanup_chip;
    }

    /* Request the line as output, initial value 0 (valve off) */
    if (gpiod_line_request_output(line, "watering-valve", 0) < 0) {
        fprintf(stderr, "Error: cannot request GPIO line %d as output: %s\n",
                VALVE_GPIO_LINE, strerror(errno));
        goto cleanup_chip;
    }

    printf("Watering system started. Valve on GPIO%d. Press Ctrl+C to exit.\n",
           VALVE_GPIO_LINE);

    while (program_running) {
        int duration;

        if (read_watering_duration(CONFIG_FILE, &duration) != 0) {
            fprintf(stderr, "Error: failed to read watering duration. Retrying in %d s...\n",
                    POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        printf("Watering for %d seconds...\n", duration);

        /* Activate valve (active-low: 1 = ON, 0 = OFF) */
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Error: failed to set GPIO line %d high: %s\n",
                    VALVE_GPIO_LINE, strerror(errno));
            goto cleanup_valve;
        }

        /* Sleep for the configured duration, checking for signals */
        for (int i = 0; i < duration && program_running; i++) {
            sleep(1);
        }

        /* Deactivate valve */
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Error: failed to set GPIO line %d low: %s\n",
                    VALVE_GPIO_LINE, strerror(errno));
            goto cleanup_valve;
        }

        printf("Valve turned off.\n");
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup_valve:
    /* Ensure valve is off on exit */
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }

cleanup_chip:
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

