#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// GPIO pin definitions
#define SENSOR_LEFT  4
#define SENSOR_MIDDLE 17
#define SENSOR_RIGHT 27
#define MOTOR_LEFT_1 22
#define MOTOR_LEFT_2 23
#define MOTOR_RIGHT_1 24
#define MOTOR_RIGHT_2 25

// Motor speed constants
#define MOTOR_SPEED_BASE 150
#define MOTOR_SPEED_MAX 255

// Log file path
#define LOG_FILE "trace_log.txt"

// Global flag for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
int calculate_motor_speeds(int left_sensor, int right_sensor);
void set_motor_speeds(int left_speed, int right_speed);
void log_data(int left_sensor, int right_sensor, int left_speed, int right_speed);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read a sensor value (active-low: 0 = low, 1 = high)
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return value;
}

// Function to calculate motor speeds based on sensor readings
int calculate_motor_speeds(int left_sensor, int right_sensor) {
    int left_speed = MOTOR_SPEED_BASE;
    int right_speed = MOTOR_SPEED_BASE;

    // If only the left sensor reads low, turn right
    if (left_sensor == 0) {
        right_speed = MOTOR_SPEED_BASE / 2;
    }
    // If only the right sensor reads low, turn left
    else if (right_sensor == 0) {
        left_speed = MOTOR_SPEED_BASE / 2;
    }

    // Clamp motor speeds to valid range
    if (left_speed < 0) left_speed = 0;
    if (left_speed > MOTOR_SPEED_MAX) left_speed = MOTOR_SPEED_MAX;
    if (right_speed < 0) right_speed = 0;
    if (right_speed > MOTOR_SPEED_MAX) right_speed = MOTOR_SPEED_MAX;

    return left_speed, right_speed;
}

// Function to set motor speeds using PWM
void set_motor_speeds(int left_speed, int right_speed) {
    // Left motor: forward
    gpioPWM(MOTOR_LEFT_1, left_speed);
    gpioPWM(MOTOR_LEFT_2, 0);

    // Right motor: forward
    gpioPWM(MOTOR_RIGHT_1, right_speed);
    gpioPWM(MOTOR_RIGHT_2, 0);
}

// Function to log data to a file
void log_data(int left_sensor, int right_sensor, int left_speed, int right_speed) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, Left: %d, Right: %d, Left Speed: %d, Right Speed: %d\n",
            timestamp, left_sensor, right_sensor, left_speed, right_speed);

    fclose(fp);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_LEFT, PI_INPUT);
    gpioSetMode(SENSOR_MIDDLE, PI_INPUT);
    gpioSetMode(SENSOR_RIGHT, PI_INPUT);
    gpioSetMode(MOTOR_LEFT_1, PI_OUTPUT);
    gpioSetMode(MOTOR_LEFT_2, PI_OUTPUT);
    gpioSetMode(MOTOR_RIGHT_1, PI_OUTPUT);
    gpioSetMode(MOTOR_RIGHT_2, PI_OUTPUT);

    // Set PWM frequency to 1 kHz
    gpioSetPWMfrequency(MOTOR_LEFT_1, 1000);
    gpioSetPWMfrequency(MOTOR_LEFT_2, 1000);
    gpioSetPWMfrequency(MOTOR_RIGHT_1, 1000);
    gpioSetPWMfrequency(MOTOR_RIGHT_2, 1000);

    // Set PWM range to 255 (0-255)
    gpioSetPWMrange(MOTOR_LEFT_1, 255);
    gpioSetPWMrange(MOTOR_LEFT_2, 255);
    gpioSetPWMrange(MOTOR_RIGHT_1, 255);
    gpioSetPWMrange(MOTOR_RIGHT_2, 255);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_sensor = read_sensor(SENSOR_LEFT);
        int middle_sensor = read_sensor(SENSOR_MIDDLE);
        int right_sensor = read_sensor(SENSOR_RIGHT);

        // Calculate motor speeds
        int left_speed, right_speed;
        if (left_sensor >= 0 && middle_sensor >= 0 && right_sensor >= 0) {
            left_speed, right_speed = calculate_motor_speeds(left_sensor, right_sensor);
        } else {
            // Error reading sensor, stop motors
            left_speed = 0;
            right_speed = 0;
        }

        // Set motor speeds
        set_motor_speeds(left_speed, right_speed);

        // Log data
        log_data(left_sensor, right_sensor, left_speed, right_speed);

        // Delay for 10 ms
        gpioDelay(10000); // 10,000 microseconds = 10 ms
    }

    // Stop motors before exiting
    set_motor_speeds(0, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Line-following robot stopped.\n");

    return 0;
}

