#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22
#define SERVO_PIN 18

#define LOCKED_POSITION 1000
#define UNLOCKED_POSITION 2000

#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    return 0;
}

int read_button(int button_pin) {
    return gpioRead(button_pin);
}

int set_servo_position(int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (pulse_width > MAX_PULSE_WIDTH) {
        pulse_width = MAX_PULSE_WIDTH;
    }

    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width to %d\n", pulse_width);
        return -1;
    }

    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int lock_button_pressed = read_button(LOCK_BUTTON);
        int unlock_button_pressed = read_button(UNLOCK_BUTTON);

        if (lock_button_pressed == 0) {
            printf("Lock button pressed, moving servo to locked position...\n");
            if (set_servo_position(LOCKED_POSITION) != 0) {
                fprintf(stderr, "Error: Failed to set lock position\n");
            }
            gpioDelay(100000); // 100 ms debounce
        } else if (unlock_button_pressed == 0) {
            printf("Unlock button pressed, moving servo to unlocked position...\n");
            if (set_servo_position(UNLOCKED_POSITION) != 0) {
                fprintf(stderr, "Error: Failed to set unlock position\n");
            }
            gpioDelay(100000); // 100 ms debounce
        }

        gpioDelay(10000); // 10 ms polling interval
    }

    gpioServo(SERVO_PIN, 0); // Stop servo PWM signal
    gpioTerminate();
    printf("Door lock control stopped.\n");

    return 0;
}

