#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define PULSE_DURATION_MS 200
#define INTER_PULSE_DELAY_MS 300
#define CONSUMER "haptic-feedback"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Failed to set GPIO value");
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *motor1_line = NULL;
    struct gpiod_line *motor2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("Failed to open gpiochip4");
        return EXIT_FAILURE;
    }

    motor1_line = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!motor1_line) {
        perror("Failed to get GPIO line 17");
        goto cleanup;
    }

    motor2_line = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!motor2_line) {
        perror("Failed to get GPIO line 27");
        goto cleanup;
    }

    if (gpiod_line_request_output(motor1_line, CONSUMER, 0) < 0) {
        perror("Failed to request GPIO line 17 as output");
        goto cleanup;
    }

    if (gpiod_line_request_output(motor2_line, CONSUMER, 0) < 0) {
        perror("Failed to request GPIO line 27 as output");
        goto cleanup;
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (set_motor_value(motor1_line, 1) < 0) {
            goto cleanup;
        }
        if (set_motor_value(motor2_line, 0) < 0) {
            goto cleanup;
        }
        usleep(PULSE_DURATION_MS * 1000);

        if (!running) {
            break;
        }

        if (set_motor_value(motor1_line, 0) < 0) {
            goto cleanup;
        }
        if (set_motor_value(motor2_line, 1) < 0) {
            goto cleanup;
        }
        usleep(INTER_PULSE_DELAY_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (motor1_line) {
        gpiod_line_set_value(motor1_line, 0);
        gpiod_line_release(motor1_line);
    }
    if (motor2_line) {
        gpiod_line_set_value(motor2_line, 0);
        gpiod_line_release(motor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Haptic feedback system stopped.\n");
    return ret;
}

