#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>
#include <zmq.h>

#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO 27
#define ALARM_DURATION_MS 1000
#define POLL_INTERVAL_MS 10
#define ZMQ_PORT 5555
#define ZMQ_TOPIC "SOUND_ALERTS"
#define GPIO_CHIP_NAME "gpiochip4"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int setup_gpio(struct gpiod_chip **chip, struct gpiod_line **sound_line, struct gpiod_line **alarm_line) {
    *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!*chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    *sound_line = gpiod_chip_get_line(*chip, SOUND_SENSOR_GPIO);
    if (!*sound_line) {
        perror("gpiod_chip_get_line(SOUND_SENSOR)");
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    *alarm_line = gpiod_chip_get_line(*chip, ALARM_LED_GPIO);
    if (!*alarm_line) {
        perror("gpiod_chip_get_line(ALARM_LED)");
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    if (gpiod_line_request_input(*sound_line, "sound_sensor") < 0) {
        perror("gpiod_line_request_input(SOUND_SENSOR)");
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(*alarm_line, "alarm_led", 0) < 0) {
        perror("gpiod_line_request_output(ALARM_LED)");
        gpiod_line_release(*sound_line);
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    return 0;
}

