#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define IR_GPIO 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MQTT_CLIENT_ID "ir_decoder"
#define MAX_PULSES 100
#define NEC_HDR_MARK 9000
#define NEC_HDR_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_RPT_SPACE 2250
#define NEC_TOLERANCE 200

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_times[MAX_PULSES];
static volatile int pulse_count = 0;
static MQTTClient client;
static MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
static MQTTClient_message pubmsg = MQTTClient_message_initializer;
static MQTTClient_deliveryToken token;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void ir_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 0) {
        if (pulse_count < MAX_PULSES) {
            pulse_times[pulse_count++] = tick;
        } else {
            syslog(LOG_ERR, "Pulse buffer overflow, discarding frame");
            pulse_count = 0;
        }
    }
}

static int decode_nec(uint32_t *pulses, int count, uint32_t *address, uint32_t *command) {
    if (count < 34) {
        syslog(LOG_ERR, "Not enough pulses for NEC frame (got %d, need 34)", count);
        return -1;
    }

    if (pulses[0] < NEC_HDR_MARK - NEC_TOLERANCE || pulses[0] > NEC_HDR_MARK + NEC_TOLERANCE) {
        syslog(LOG_ERR, "Invalid NEC header mark: %u", pulses[0]);
        return -1;
    }
    if (pulses[1] < NEC_HDR_SPACE - NEC_TOLERANCE || pulses[1] > NEC_HDR_SPACE + NEC_TOLERANCE) {
        syslog(LOG_ERR, "Invalid NEC header space: %u", pulses[1]);
        return -1;
    }

    uint32_t address_bits = 0;
    uint32_t command_bits = 0;
    int bit_idx = 0;

    for (int i = 2; i < count; i++) {
        if (i % 2 == 0) {
            if (pulses[i] < NEC_BIT_MARK - NEC_TOLERANCE || pulses[i] > NEC_BIT_MARK + NEC_TOLERANCE) {
                syslog(LOG_ERR, "Invalid bit mark: %u", pulses[i]);
                return -1;
            }
            if (pulses[i + 1] < NEC_ONE_SPACE - NEC_TOLERANCE || pulses[i + 1] > NEC_ONE_SPACE + NEC_TOLERANCE) {
                syslog(LOG_ERR, "Invalid one space: %u", pulses[i + 1]);
                return -1;
            }
            command_bits <<= 1;
            command_bits |= 1;
            bit_idx++;
        } else {
            if (pulses[i] < NEC_ZERO_SPACE - NEC_TOLERANCE || pulses[i] > NEC_ZERO_SPACE + NEC_TOLERANCE) {
                syslog(LOG_ERR, "Invalid zero space: %u", pulses[i]);
                return -1;
            }
            command_bits <<= 1;
            bit_idx++;
        }
    }

    if (bit_idx != 32) {
        syslog(LOG_ERR, "Invalid bit count: %d", bit_idx);
        return -1;
    }

    *address = address_bits;
    *command = command_bits;
    return 0;
}

static void publish_mqtt(uint32_t address, uint32_t command) {
    char payload[128];
    int len = snprintf(payload, sizeof(payload), "{\"address\":%u,\"command\":%u}", address, command);
    if (len < 0 || (size_t)len >= sizeof(payload)) {
        syslog(LOG_ERR, "Payload formatting failed");
        return;
    }

    pubmsg.payload = payload;
    pubmsg.payloadlen = (uint32_t)len;
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    int rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", MQTTClient_strerror(rc));
    } else {
        syslog(LOG_INFO, "Published: %s", payload);
    }
}

static void cleanup(void) {
    if (client != NULL) {
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        client = NULL;
    }
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(IR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as input", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(IR_GPIO, PI_PUD_UP) != 0) {
        syslog(LOG_WARNING, "Failed to set pull-up on GPIO %d", IR_GPIO);
    }

    if (gpioSetAlertFunc(IR_GPIO, ir_callback) != 0) {
        syslog(LOG_ERR, "Failed to set alert function on GPIO %d", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    conn_opts.keepAliveInterval = 60;
    conn_opts.cleansession = 1;

    int rc = MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT client creation failed: %s", MQTTClient_strerror(rc));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "IR decoder started on GPIO %d, MQTT %s:%d, topic %s", IR_GPIO, MQTT_BROKER, MQTT_PORT, MQTT_TOPIC);

    while (running) {
        gpioDelay(100000);

        if (pulse_count >= 34) {
            uint32_t address = 0, command = 0;
            if (decode_nec(pulse_times, pulse_count, &address, &command) == 0) {
                publish_mqtt(address, command);
            }
            pulse_count = 0;
        }
    }

    syslog(LOG_INFO, "Shutting down...");
    cleanup();
    return EXIT_SUCCESS;
}

