        syslog(LOG_ERR, "Failed to set alert function on GPIO %d", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    conn_opts.keepAliveInterval = 60;
    conn_opts.cleansession = 1;

