    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "IR decoder started on GPIO %d, MQTT %s:%d, topic %s", IR_GPIO, MQTT_BROKER, MQTT_PORT, MQTT_TOPIC);

    while (running) {
        gpioDelay(100000);

        if (pulse_count >= 34) {
            uint32_t address = 0, command = 0;
            if (decode_nec(pulse_times, pulse_count, &address, &command) == 0) {
