#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR_1  0x23
#define BH1750_ADDR_2  0x24
#define BH1750_ADDR_3  0x25
#define BH1750_ADDR_4  0x26
#define BH1750_CMD_OT_HRES 0x20
#define BH1750_CONV_MS  180
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_open(int addr) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    uint8_t cmd = BH1750_CMD_OT_HRES;
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "BH1750 write(0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    usleep(BH1750_CONV_MS * 1000);

    uint8_t buf[2];
    ssize_t r = read(fd, buf, 2);
    if (r != 2) {
        fprintf(stderr, "BH1750 read: got %zd bytes, expected 2: %s\n",
                r, r < 0 ? strerror(errno) : "short read");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(int sockfd, const char *data) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    ssize_t sent = sendto(sockfd, data, strlen(data), 0,
                         (struct sockaddr *)&addr, sizeof(addr));
    if (sent < 0) {
        fprintf(stderr, "sendto: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)sent != strlen(data)) {
        fprintf(stderr, "sendto: partial send (%zd/%zu)\n", sent, strlen(data));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fds[4] = {-1, -1, -1, -1};
    int open_count = 0;

    for (int i = 0; i < 4; i++) {
        int addr = (i == 0) ? BH1750_ADDR_1 :
                   (i == 1) ? BH1750_ADDR_2 :
                   (i == 2) ? BH1750_ADDR_3 : BH1750_ADDR_4;
        fds[i] = i2c_open(addr);
        if (fds[i] < 0) {
            continue;
        }
        open_count++;
    }

    if (open_count == 0) {
        fprintf(stderr, "No BH1750 sensors found on %s\n", I2C_BUS);
        return EXIT_FAILURE;
    }

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "socket: %s\n", strerror(errno));
        for (int i = 0; i < 4; i++) {
            if (fds[i] >= 0) close(fds[i]);
        }
        return EXIT_FAILURE;
    }

    int ttl = 1;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "setsockopt(IP_MULTICAST_TTL): %s\n", strerror(errno));
        close(sockfd);
        for (int i = 0; i < 4; i++) {
            if (fds[i] >= 0) close(fds[i]);
        }
        return EXIT_FAILURE;
    }

    printf("BH1750 multicast reader started. Ctrl+C to exit.\n");

    while (g_running) {
        float lux[4] = {NAN, NAN, NAN, NAN};
        int ok = 1;

        for (int i = 0; i < 4; i++) {
            if (fds[i] < 0) continue;
            if (bh1750_read_lux(fds[i], &lux[i]) < 0) {
                fprintf(stderr, "Sensor %d read failed\n", i + 1);
                ok = 0;
            }
        }

        if (ok) {
            char msg[256];
            int n = snprintf(msg, sizeof(msg), "%d,%.1f;%d,%.1f;%d,%.1f;%d,%.1f",
                             1, lux[0], 2, lux[1], 3, lux[2], 4, lux[3]);
            if (n < 0 || (size_t)n >= sizeof(msg)) {
                fprintf(stderr, "snprintf failed\n");
                continue;
            }
            if (send_multicast(sockfd, msg) < 0) {
                fprintf(stderr, "Multicast send failed\n");
            }
        }

        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < 4; i++) {
        if (fds[i] >= 0) close(fds[i]);
    }
    if (sockfd >= 0) close(sockfd);
    printf("Done.\n");
    return EXIT_SUCCESS;
}

