#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AWM7300_ADDR   0x28
#define LOG_FILE       "airflow_log.txt"
#define SAMPLE_PERIOD  1
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_airflow_data(int fd, float *flow_rate) {
    uint8_t cmd = 0x00;
    uint8_t data[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_byte(fd, cmd) < 0) {
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        usleep(1000);

        if (i2c_read_bytes(fd, data, sizeof(data)) < 0) {
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
        raw &= 0x3FFF;
        *flow_rate = (float)(raw - 3277) * 0.1f;
        return 0;
    }

    fprintf(stderr, "Failed to read airflow data after %d retries.\n", MAX_RETRIES);
    return -1;
}

static void log_airflow_data(FILE *fp, float flow_rate) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Failed to get local time.\n");
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Failed to format timestamp.\n");
        return;
    }

    if (fprintf(fp, "%s, %.2f SLPM\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Failed to write to log file.\n");
    }
    fflush(fp);
}

static void cleanup(void) {
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AWM7300_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", AWM7300_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float flow_rate;
        if (read_airflow_data(g_i2c_fd, &flow_rate) == 0) {
            log_airflow_data(g_log_fp, flow_rate);
            printf("Flow Rate: %.2f SLPM\n", flow_rate);
        } else {
            fprintf(stderr, "Failed to read airflow data.\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

