}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int as7341_init(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, AS7341_REG_WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != AS7341_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, AS7341_WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg8(fd, AS7341_REG_ENABLE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_REG_CFG6, 0x00) < 0) return -1;

    if (i2c_write_reg8(fd, AS7341_REG_ENABLE, 0x01) < 0) return -1;
    usleep(10000);

    return 0;
}

static int as7341_read_channel(int fd, uint8_t channel, uint16_t *value) {
    uint8_t reg = AS7341_REG_DATA0 + (channel * 2);
