    if (!log_fp) {
        perror("fopen " LOG_FILE);
        close(i2c_fd);
        return 1;
    }

    fprintf(log_fp, "Timestamp,Lux\n");
    fflush(log_fp);

    while (running) {
        uint16_t f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;
        if (as7341_read_channel(i2c_fd, 0, &f1) < 0 ||
            as7341_read_channel(i2c_fd, 1, &f2) < 0 ||
            as7341_read_channel(i2c_fd, 2, &f3) < 0 ||
            as7341_read_channel(i2c_fd, 3, &f4) < 0 ||
            as7341_read_channel(i2c_fd, 4, &f5) < 0 ||
            as7341_read_channel(i2c_fd, 5, &f6) < 0 ||
            as7341_read_channel(i2c_fd, 6, &f7) < 0 ||
            as7341_read_channel(i2c_fd, 7, &f8) < 0 ||
            as7341_read_channel(i2c_fd, 8, &clear) < 0 ||
            as7341_read_channel(i2c_fd, 9, &nir) < 0) {
            fprintf(stderr, "Sensor read error — continuing\n");
        } else {
