#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x37
#define REG_X_L        0x28
#define REG_X_H        0x29
#define REG_Y_L        0x2A
#define REG_Y_H        0x2B
#define REG_Z_L        0x2C
#define REG_Z_H        0x2D
#define SCALE_FACTOR   0.000244f   /* ±8 g range: 1 LSB = 0.000244 g */
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 10
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2)
            return 0;
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            if (attempt < MAX_RETRIES - 1)
                usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        ssize_t n = read(fd, buf, len);
        if (n == (ssize_t)len)
            return 0;
        if (n < 0 && errno == EINTR)
            continue;
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int read_acceleration(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, REG_X_L, buf, sizeof(buf)) < 0)
        return -1;

    int16_t x_raw = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t y_raw = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t z_raw = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)x_raw * SCALE_FACTOR;
    *y = (float)y_raw * SCALE_FACTOR;
    *z = (float)z_raw * SCALE_FACTOR;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,ERROR,%s\n", ts, msg);
    fflush(fp);
    fprintf(stderr, "%s,ERROR,%s\n", ts, msg);
}

int main(int argc, char *argv[])
{
    int i2c_addr = D7S_ADDR;
    int interval = SAMPLE_PERIOD_S;
    const char *filename = "seismic_data.csv";
    int opt;

    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a': i2c_addr = (int)strtol(optarg, NULL, 0); break;
            case 'i': interval = atoi(optarg); break;
            case 'f': filename = optarg; break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_addr] [-i interval_s] [-f filename]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (interval <= 0) {
        fprintf(stderr, "Invalid interval: %d\n", interval);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, i2c_addr) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", i2c_addr, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_csv_fp = fopen(filename, "a");
    if (!g_csv_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_csv_fp, 0, SEEK_END);
    if (ftell(g_csv_fp) == 0)
        fprintf(g_csv_fp, "timestamp,x_g,y_g,z_g\n");

    printf("Seismic sensor logging started. I2C addr 0x%02X, interval %d s, output %s\n",
           i2c_addr, interval, filename);

    while (g_running) {
        float x, y, z;
        if (read_acceleration(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_csv_fp, x, y, z);
        } else {
            log_error(g_csv_fp, "I2C read failed");
        }
        sleep(interval);
    }

    printf("\nShutting down...\n");
    if (g_csv_fp) {
        fflush(g_csv_fp);
        fclose(g_csv_fp);
        g_csv_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

