    *x = (float)x_raw * SCALE_FACTOR;
    *y = (float)y_raw * SCALE_FACTOR;
    *z = (float)z_raw * SCALE_FACTOR;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,ERROR,%s\n", ts, msg);
    fflush(fp);
    fprintf(stderr, "%s,ERROR,%s\n", ts, msg);
}

int main(int argc, char *argv[])
{
    int i2c_addr = D7S_ADDR;
    int interval = SAMPLE_PERIOD_S;
    const char *filename = "seismic_data.csv";
    int opt;

    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a': i2c_addr = (int)strtol(optarg, NULL, 0); break;
            case 'i': interval = atoi(optarg); break;
            case 'f': filename = optarg; break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_addr] [-i interval_s] [-f filename]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (interval <= 0) {
        fprintf(stderr, "Invalid interval: %d\n", interval);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, i2c_addr) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", i2c_addr, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_csv_fp = fopen(filename, "a");
    if (!g_csv_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_csv_fp, 0, SEEK_END);
    if (ftell(g_csv_fp) == 0)
        fprintf(g_csv_fp, "timestamp,x_g,y_g,z_g\n");

    printf("Seismic sensor logging started. I2C addr 0x%02X, interval %d s, output %s\n",
           i2c_addr, interval, filename);

    while (g_running) {
        float x, y, z;
        if (read_acceleration(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_csv_fp, x, y, z);
        } else {
            log_error(g_csv_fp, "I2C read failed");
        }
        sleep(interval);
    }

    printf("\nShutting down...\n");
    if (g_csv_fp) {
        fflush(g_csv_fp);
        fclose(g_csv_fp);
        g_csv_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

