#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define CSV_FILE "radar_data.csv"
#define BUFFER_SIZE 4096
#define MAGIC_WORD_LEN 8
#define FRAME_HEADER_LEN 8
#define TLV_HEADER_LEN 8
#define DETECTED_OBJ_SIZE 12
#define MAX_OBJECTS 100

static volatile sig_atomic_t running = 1;
static int uart_handle = -1;
static FILE *csv_file = NULL;

static uint8_t magic_word[MAGIC_WORD_LEN] = {0x02, 0x04, 0x03, 0x06, 0x08, 0x05, 0x07, 0x09};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(void) {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART %s: %d\n", UART_DEVICE, uart_handle);
        return -1;
    }
    return 0;
}

static int init_csv(void) {
    csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        perror("Error opening CSV file");
        return -1;
    }
    fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    fflush(csv_file);
    return 0;
}

static void cleanup(void) {
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
    if (csv_file) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
    gpioTerminate();
}

static int find_magic_word(const uint8_t *buf, int len) {
    for (int i = 0; i <= len - MAGIC_WORD_LEN; i++) {
        if (memcmp(buf + i, magic_word, MAGIC_WORD_LEN) == 0) {
            return i;
        }
    }
    return -1;
}

static int process_frame(const uint8_t *frame, int len) {
    if (len < FRAME_HEADER_LEN) {
        fprintf(stderr, "Frame too short for header\n");
        return -1;
    }

    uint32_t total_packet_len = (frame[4] << 24) | (frame[5] << 16) | (frame[6] << 8) | frame[7];
    if (total_packet_len > len) {
        fprintf(stderr, "Frame length mismatch: expected %u, got %d\n", total_packet_len, len);
        return -1;
    }

    uint32_t num_detected_obj = (frame[12] << 24) | (frame[13] << 16) | (frame[14] << 8) | frame[15];
    if (num_detected_obj > MAX_OBJECTS) {
        fprintf(stderr, "Warning: num_detected_obj %u exceeds max %d\n", num_detected_obj, MAX_OBJECTS);
    }

    int offset = FRAME_HEADER_LEN;
    for (uint32_t tlv_idx = 0; tlv_idx < num_detected_obj; tlv_idx++) {
        if (offset + TLV_HEADER_LEN > len) {
            fprintf(stderr, "TLV header at offset %d exceeds frame bounds\n", offset);
            return -1;
        }

        uint32_t tlv_type = (frame[offset] << 24) | (frame[offset + 1] << 16) | (frame[offset + 2] << 8) | frame[offset + 3];
        uint32_t tlv_len = (frame[offset + 4] << 24) | (frame[offset + 5] << 16) | (frame[offset + 6] << 8) | frame[offset + 7];

        if (offset + TLV_HEADER_LEN + tlv_len > len) {
            fprintf(stderr, "TLV payload at offset %d exceeds frame bounds\n", offset);
            return -1;
        }

        if (tlv_type == 1 && tlv_len >= DETECTED_OBJ_SIZE) {
            uint16_t range_idx = (frame[offset + 8] << 8) | frame[offset + 9];
            uint16_t velocity_idx = (frame[offset + 10] << 8) | frame[offset + 11];

            float range = (float)range_idx / 100.0f;
            float velocity = (float)velocity_idx / 100.0f;

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(csv_file, "%s,%u,%.2f,%.2f\n", timestamp, tlv_idx, range, velocity);
            fflush(csv_file);
        }

        offset += TLV_HEADER_LEN + tlv_len;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_uart() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_csv() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint8_t buffer[BUFFER_SIZE];
    int buffer_len = 0;

    printf("Radar data acquisition started. Press Ctrl+C to stop.\n");

    while (running) {
        int bytes_read = serRead(uart_handle, (char *)(buffer + buffer_len), BUFFER_SIZE - buffer_len);
        if (bytes_read > 0) {
            buffer_len += bytes_read;

            int magic_idx = find_magic_word(buffer, buffer_len);
            if (magic_idx >= 0) {
                int remaining = buffer_len - magic_idx;
                if (remaining >= FRAME_HEADER_LEN) {
                    uint32_t total_packet_len = (buffer[magic_idx + 4] << 24) | (buffer[magic_idx + 5] << 16) | (buffer[magic_idx + 6] << 8) | buffer[magic_idx + 7];
                    if (total_packet_len > BUFFER_SIZE) {
                        fprintf(stderr, "Frame length exceeds buffer, resetting\n");
                        buffer_len = 0;
                        continue;
                    }

                    if (remaining >= total_packet_len) {
                        process_frame(buffer + magic_idx, total_packet_len);
                        memmove(buffer, buffer + magic_idx + total_packet_len, buffer_len - magic_idx - total_packet_len);
                        buffer_len -= magic_idx + total_packet_len;
                    } else {
                        break;
                    }
                } else {
                    break;
                }
            } else {
                if (buffer_len >= BUFFER_SIZE) {
                    fprintf(stderr, "Buffer overflow, resetting\n");
                    buffer_len = 0;
                }
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "UART read error: %d\n", bytes_read);
            break;
        } else {
            usleep(1000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

