#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <time.h>
#include <signal.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define LINE_BUFFER_SIZE 256
#define READ_TIMEOUT_SEC 2
#define INTER_BYTE_TIMEOUT_SEC 0.5

static volatile sig_atomic_t program_running = 1;
static int uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int configure_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNPAR | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag &= ~OPOST;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_lflag &= ~(ECHOCTL | ECHONL | ICANON | ISIG);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = (int)(INTER_BYTE_TIMEOUT_SEC * 10);

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_line(int fd, char *buffer, size_t buffer_size) {
    size_t total_read = 0;
    char ch;

    while (total_read < buffer_size - 1) {
        fd_set readfds;
        struct timeval timeout;

        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);

        timeout.tv_sec = READ_TIMEOUT_SEC;
        timeout.tv_usec = 0;

        int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);
        if (retval < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error during select: %s\n", strerror(errno));
            return -1;
        }
        if (retval == 0) {
            fprintf(stderr, "Timeout waiting for data on UART\n");
            return -1;
        }

        ssize_t bytes_read = read(fd, &ch, 1);
        if (bytes_read < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        }
        if (bytes_read == 0) {
            fprintf(stderr, "UART closed unexpectedly\n");
            return -1;
        }

        if (ch == '\n') {
            buffer[total_read] = '\0';
            return (int)total_read;
        }

        buffer[total_read++] = ch;
    }

    buffer[total_read] = '\0';
    return (int)total_read;
}

static int parse_line(const char *line, float *range) {
    char *endptr;
    long timestamp = strtol(line, &endptr, 10);
    if (endptr == line || *endptr != ',') {
        fprintf(stderr, "Invalid timestamp format: %s\n", line);
        return -1;
    }

    char *range_str = endptr + 1;
    errno = 0;
    double range_meters = strtod(range_str, &endptr);
    if (errno != 0 || endptr == range_str) {
        fprintf(stderr, "Invalid range value: %s\n", range_str);
        return -1;
    }

    *range = (float)range_meters;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    uart_fd = configure_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        return 1;
    }

    char line_buffer[LINE_BUFFER_SIZE];
    int line_buffer_index = 0;

    printf("Radar data acquisition started on %s at %d baud.\n", UART_DEVICE, BAUD_RATE);
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        int bytes_read = read_line(uart_fd, line_buffer, sizeof(line_buffer));
        if (bytes_read < 0) {
            if (program_running) {
                fprintf(stderr, "Error reading from UART, retrying...\n");
            }
            continue;
        }

        if (bytes_read == 0) {
            continue;
        }

        for (int i = 0; i < bytes_read; i++) {
            char ch = line_buffer[i];
            if (ch == '\n') {
                if (line_buffer_index > 0) {
                    line_buffer[line_buffer_index] = '\0';
                    float range;
                    if (parse_line(line_buffer, &range) == 0) {
                        time_t now = time(NULL);
                        struct tm *tstruct = localtime(&now);
                        char buf[80];
                        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);
                        printf("Timestamp: %s, Range: %.2f meters\n", buf, range);
                        fflush(stdout);
                    }
                    line_buffer_index = 0;
                }
            } else {
                if (line_buffer_index < LINE_BUFFER_SIZE - 1) {
                    line_buffer[line_buffer_index++] = ch;
                } else {
                    fprintf(stderr, "Line buffer overflow, discarding data\n");
                    line_buffer_index = 0;
                }
            }
        }
    }

    printf("\nShutting down...\n");
    if (uart_fd >= 0) {
        close(uart_fd);
    }
    return 0;
}

